export interface MCQItem {
  id: string;
  section: string;
  unit: string;
  chapter: string;
  questionNumber: string;
  question: string;
  options: Record<string, string>;
  correctOption: string;
  correctAnswer: string;
  questionType: string;
  explanation?: any;
}

export const MCQ_BANK_4: MCQItem[] = [{"id":"P1_U4_MCQ_001","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_001","question":"A specialist joinery workshop builds individual curved wooden staircases designed to fit the exact dimensions of each client's home. Which method of production is this workshop using?","options":{"A":"Flow production","B":"Job production","C":"Batch production","D":"Lean production"},"correctOption":"B","correctAnswer":"Job production","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because job production involves making a single, unique product at a time to meet an individual customer's specific requirements.","distractor_reasons":{"A":"Incorrect because flow production continuously manufactures large quantities of identical, standardized products on a production line.","B":"Correct selection.","C":"Incorrect because batch production makes a set quantity of identical items together before switching machinery to produce another batch.","D":"Incorrect because lean production refers to techniques aimed at eliminating waste rather than a specific method of organizing output volume."}}},{"id":"P1_U4_MCQ_002","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_002","question":"A ceramic tile factory produces 4,800 tiles per week and employs 12 production workers. What is the weekly labour productivity of this factory?","options":{"A":"400 tiles per employee","B":"4,800 tiles per week","C":"57,600 tiles per employee","D":"12 tiles per employee"},"correctOption":"A","correctAnswer":"400 tiles per employee","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because labour productivity is calculated by dividing total output per period (4,800 tiles) by the number of employees (12), which equals 400 tiles per employee.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 4,800 tiles is the total level of production (output), not output per worker.","C":"Incorrect because this multiplies output by the number of employees instead of dividing output by employees.","D":"Incorrect because 12 is the number of employees rather than the output produced per worker."}}},{"id":"P1_U4_MCQ_003","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_003","question":"Last year, a toy factory produced 10,000 wooden toys per month with 20 workers, and this year it produces 12,000 wooden toys per month after hiring 10 additional workers. What happened to the factory's level of production and labour productivity this year?","options":{"A":"Both the level of production and labour productivity increased","B":"The level of production decreased, while labour productivity increased","C":"The level of production increased, while labour productivity decreased","D":"Both the level of production and labour productivity decreased"},"correctOption":"C","correctAnswer":"The level of production increased, while labour productivity decreased","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total output (level of production) rose from 10,000 to 12,000 units, whereas labour productivity fell from 500 units per worker (10,000 / 20) to 400 units per worker (12,000 / 30).","distractor_reasons":{"A":"Incorrect because students often confuse higher total output with higher productivity, ignoring that output per worker actually fell.","B":"Incorrect because total output rose by 2,000 units while output per employee dropped by 100 units.","C":"Correct selection.","D":"Incorrect because total monthly output increased from 10,000 to 12,000 toys."}}},{"id":"P1_U4_MCQ_004","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_004","question":"A manufacturer of electric kettles trains its assembly workers to reduce wasted time, lowering the average cost of producing each kettle while keeping selling prices unchanged. What is the direct benefit of this improved efficiency to the business?","options":{"A":"Higher fixed costs per unit","B":"Increased inventory holding costs","C":"Higher labour turnover","D":"Higher profit margin on each kettle sold"},"correctOption":"D","correctAnswer":"Higher profit margin on each kettle sold","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because greater efficiency lowers the average cost per unit produced, increasing the profit made on every unit sold when selling prices remain constant.","distractor_reasons":{"A":"Incorrect because higher efficiency reduces average costs per unit rather than increasing fixed costs.","B":"Incorrect because improved efficiency streamlines operations and typically reduces rather than increases inventory holding costs.","C":"Incorrect because better training and efficiency often allow higher wages and motivation, reducing rather than increasing labour turnover.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_005","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_005","question":"A garment manufacturer operating in a country with low wage rates employs 250 machinists using basic sewing machines rather than investing in expensive automated robotics. Which type of production process is this business using?","options":{"A":"Labour-intensive production","B":"Capital-intensive production","C":"Flow production","D":"Just-in-time production"},"correctOption":"A","correctAnswer":"Labour-intensive production","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because labour-intensive production relies heavily on employing many workers and relatively little machinery, which is cost-effective where wages are low.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because capital-intensive production relies primarily on expensive machinery and automation with very few employees.","C":"Incorrect because flow production describes continuous mass production of identical items, which is typically capital-intensive.","D":"Incorrect because just-in-time refers to minimizing inventory levels rather than the ratio of labour to capital equipment."}}},{"id":"P1_U4_MCQ_006","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_006","question":"An appliance assembly plant rearranges its workstations so workers no longer have to walk across the factory floor or bend repeatedly to collect screws and components. Which type of lean production waste is the plant eliminating?","options":{"A":"Overproduction","B":"Motion","C":"Defects","D":"Over-processing"},"correctOption":"B","correctAnswer":"Motion","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unnecessary physical movement by employees, such as walking, bending, or stretching between tasks, is classified as waste of motion in lean production.","distractor_reasons":{"A":"Incorrect because overproduction occurs when a business makes more goods than customers have ordered.","B":"Correct selection.","C":"Incorrect because defects refer to faulty products that require reworking or scrapping.","D":"Incorrect because over-processing involves using overly complex machinery or performing unnecessary production steps."}}},{"id":"P1_U4_MCQ_007","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_007","question":"A commercial bakery regularly produces 600 extra loaves of bread every day without confirmed orders from retailers, resulting in unsold loaves taking up storage space and expiring. Which type of waste in lean production does this illustrate?","options":{"A":"Non-utilised skills","B":"Transportation","C":"Overproduction","D":"Waiting"},"correctOption":"C","correctAnswer":"Overproduction","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because overproduction occurs when goods are manufactured before customer orders exist, leading to unnecessary storage costs and spoilage.","distractor_reasons":{"A":"Incorrect because non-utilised skills occur when qualified employees are given simple tasks below their skill level.","B":"Incorrect because transportation waste refers to moving materials or goods unnecessarily around a site.","C":"Correct selection.","D":"Incorrect because waiting waste occurs when goods or workers sit idle between stages of the production process."}}},{"id":"P1_U4_MCQ_008","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_008","question":"A computer manufacturer arranges for suppliers to deliver processors and screens every three hours directly to the assembly line, holding virtually zero raw material inventory in a warehouse. Which method of lean production is being used?","options":{"A":"Batch production","B":"Quality control","C":"Buffer inventory holding","D":"Just-in-time (JIT) inventory control"},"correctOption":"D","correctAnswer":"Just-in-time (JIT) inventory control","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because just-in-time (JIT) inventory control aims to reduce or virtually eliminate inventories of raw materials, work in progress, and finished goods by receiving deliveries right when needed.","distractor_reasons":{"A":"Incorrect because batch production involves making groups of identical products together and typically creates high work-in-progress inventory.","B":"Incorrect because quality control involves inspecting finished goods for faults at the end of production.","C":"Incorrect because buffer inventory holding means keeping extra reserve stock in warehouses in case of delays, the opposite of JIT.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_009","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_009","question":"A fresh sandwich producer switches to just-in-time (JIT) deliveries for bread, salad, and fillings, eliminating the need for a large refrigerated warehouse. What is a major benefit of this change to the business?","options":{"A":"Lower inventory holding costs and improved cash flow","B":"Protection against sudden supplier delivery delays","C":"Larger bulk-buying discounts from ordering huge quantities","D":"Lower reliance on information technology ordering systems"},"correctOption":"A","correctAnswer":"Lower inventory holding costs and improved cash flow","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because JIT reduces warehouse space, insurance, and spoilage costs while preventing cash from being tied up in unsold inventory.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because JIT actually increases vulnerability to supplier delays since no reserve inventory is kept.","C":"Incorrect because JIT involves frequent small deliveries rather than ordering huge bulk quantities to store.","D":"Incorrect because JIT requires a powerful, efficient IT system to coordinate frequent orders accurately."}}},{"id":"P1_U4_MCQ_010","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_010","question":"An automotive assembly plant operates a strict just-in-time (JIT) inventory system when a major motorway closure delays its tyre supplier's delivery trucks by 24 hours. What is the most likely consequence for the car plant?","options":{"A":"The plant will rely on its large warehouse reserve of tyres","B":"Production on the assembly line will have to stop until the tyres arrive","C":"Average fixed costs per car will immediately fall","D":"Employees will switch to batch-producing tyres in-house"},"correctOption":"B","correctAnswer":"Production on the assembly line will have to stop until the tyres arrive","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a key disadvantage of JIT is that holding no extra buffer inventory leaves production highly vulnerable to halting if a supplier is delayed.","distractor_reasons":{"A":"Incorrect because a strict JIT system eliminates warehouse reserves of components.","B":"Correct selection.","C":"Incorrect because halting production reduces output while fixed costs remain unchanged, raising average fixed costs.","D":"Incorrect because a car assembly plant does not have the specialist machinery to manufacture tyres itself during a delivery delay."}}},{"id":"P1_U4_MCQ_011","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_011","question":"At a home appliance factory, small groups of production employees meet weekly to suggest practical, low-cost ways to reduce material waste and speed up assembly tasks. Which lean production technique is being used?","options":{"A":"Automation","B":"Job production","C":"Kaizen","D":"Quality control"},"correctOption":"C","correctAnswer":"Kaizen","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Kaizen ('continuous improvement') relies on regular small-group meetings of employees who identify and eliminate waste in daily processes without needing major capital investment.","distractor_reasons":{"A":"Incorrect because automation replaces human workers with computer-controlled machinery rather than using employee improvement groups.","B":"Incorrect because job production is a method of making unique one-off products to customer order.","C":"Correct selection.","D":"Incorrect because quality control involves specialist inspectors testing finished goods at the end of production."}}},{"id":"P1_U4_MCQ_012","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_012","question":"After adopting Kaizen principles, a furniture manufacturer reorganises its factory floor by grouping machines tightly together into cells and marking colour-coded lines to guide materials. What is the primary purpose of this reorganisation?","options":{"A":"To increase the amount of work-in-progress inventory stored between machines","B":"To isolate workers so they cannot communicate during shifts","C":"To replace skilled workers with fully automated robots","D":"To improve the flow of production and eliminate wasted movement"},"correctOption":"D","correctAnswer":"To improve the flow of production and eliminate wasted movement","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Kaizen reorganises factory layouts into tightly grouped cells with clear flow lines so materials move smoothly and workers waste less time walking between stages.","distractor_reasons":{"A":"Incorrect because Kaizen aims to reduce high inventory levels rather than increase work-in-progress storage.","B":"Incorrect because Kaizen encourages teamwork and regular group discussions among employees.","C":"Incorrect because Kaizen achieves improvements through worker ideas and layout changes rather than buying expensive robotics.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_013","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_013","question":"A toy retailer builds up large inventories of popular board games in its warehouse during October and November ahead of the December holiday shopping rush. Why is the business holding this inventory?","options":{"A":"To ensure it does not run out of goods during peak customer demand","B":"To increase its annual warehouse insurance and storage expenses","C":"To prevent suppliers from offering bulk-buying discounts","D":"To make the board games obsolete before competitors launch rivals"},"correctOption":"A","correctAnswer":"To ensure it does not run out of goods during peak customer demand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because businesses hold inventory to satisfy sudden or seasonal increases in demand without running out of stock or forcing customers to wait.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher insurance and storage expenses are costs of holding inventory, not the reason for holding it.","C":"Incorrect because ordering large quantities to hold as inventory actually helps businesses gain bulk discounts from suppliers.","D":"Incorrect because obsolescence is a risk of holding too much inventory, not an objective."}}},{"id":"P1_U4_MCQ_014","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_014","question":"A fresh seafood wholesaler keeps only one day's supply of fish in cold storage, whereas a hardware wholesaler holds three months' supply of steel nails and screws. Which factor best explains this difference in inventory levels?","options":{"A":"Labour productivity","B":"Perishability of the products","C":"Span of control","D":"Brand loyalty"},"correctOption":"B","correctAnswer":"Perishability of the products","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because perishable goods like fresh fish spoil quickly and must be kept in very low inventory levels to avoid costly waste, unlike durable steel nails.","distractor_reasons":{"A":"Incorrect because labour productivity measures output per worker, not how quickly stored goods spoil.","B":"Correct selection.","C":"Incorrect because span of control is an organisational structure concept relating to management supervision.","D":"Incorrect because brand loyalty relates to marketing and repeat customer purchases rather than product shelf life."}}},{"id":"P1_U4_MCQ_015","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_015","question":"A consumer electronics distributor deliberately holds very low inventories of current-generation laptops because chip manufacturers are about to release much faster processors. Which factor is influencing the distributor's inventory decision?","options":{"A":"High employee absenteeism","B":"Perishability of raw materials","C":"Risk of technological change making inventory obsolete","D":"Lack of bulk-buying discounts"},"correctOption":"C","correctAnswer":"Risk of technological change making inventory obsolete","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because rapid technological innovation can make existing electronic products obsolete, drastically reducing the value of any unsold inventory.","distractor_reasons":{"A":"Incorrect because employee absenteeism affects staffing levels rather than the market value of stored laptops.","B":"Incorrect because laptops do not physically rot or spoil like fresh food; they lose value through technological obsolescence.","C":"Correct selection.","D":"Incorrect because bulk discounts would encourage holding more inventory rather than keeping inventory levels low."}}},{"id":"P1_U4_MCQ_016","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_016","question":"A clothing factory cuts and stitches 500 medium-sized blue shirts in the morning, stops to adjust sewing machine settings and thread colours, and then produces 500 large-sized white shirts in the afternoon. Which production method is being used?","options":{"A":"Job production","B":"Flow production","C":"Just-in-time production","D":"Batch production"},"correctOption":"D","correctAnswer":"Batch production","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because batch production involves making a specific quantity (batch) of one product variant before resetting equipment to make a batch of another product.","distractor_reasons":{"A":"Incorrect because job production makes a single custom item at a time for an individual customer rather than groups of 500 identical shirts.","B":"Incorrect because flow production continuously produces one identical product without stopping to reset machinery for different designs.","C":"Incorrect because just-in-time is an inventory control system, not a method of grouping production runs.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_017","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_017","question":"A craft brewery produces different flavours of bottled drinks in groups of 2,000 bottles, requiring staff to clean and recalibrate filling machines between each flavour. What is a key disadvantage of this batch production method?","options":{"A":"Time is wasted resetting machinery and moving semi-finished goods between batches","B":"Every single bottle must be uniquely designed for an individual customer","C":"The business can only ever produce one standardized flavour","D":"No machinery can be used in the production process"},"correctOption":"A","correctAnswer":"Time is wasted resetting machinery and moving semi-finished goods between batches","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because batch production suffers from downtime when resetting machinery between batches and high work-in-progress inventory.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because making unique one-off items for individual clients is a feature of job production, not batch production.","C":"Incorrect because producing only one standardized product continuously describes flow production.","D":"Incorrect because batch production uses more machinery than job production to produce groups of items efficiently."}}},{"id":"P1_U4_MCQ_018","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_018","question":"A soft-drinks manufacturer operates an automated bottling line that continuously fills, seals, and labels 15,000 identical cans of cola every hour without stopping. Which production method is this business using?","options":{"A":"Batch production","B":"Flow production","C":"Job production","D":"Labour-intensive production"},"correctOption":"B","correctAnswer":"Flow production","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because flow production manufactures large quantities of a standardized product in a continuous process along a production line.","distractor_reasons":{"A":"Incorrect because batch production stops periodically to switch to making a different product group.","B":"Correct selection.","C":"Incorrect because job production creates single bespoke items tailored to individual customer orders.","D":"Incorrect because an automated high-speed bottling line is capital-intensive rather than labour-intensive."}}},{"id":"P1_U4_MCQ_019","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_019","question":"A television assembly plant uses flow production where each worker performs the exact same repetitive task every 30 seconds throughout an eight-hour shift. What is a likely disadvantage of this production method for the business?","options":{"A":"Average cost per television is higher than using job production","B":"The quality of each television varies dramatically","C":"Low employee motivation due to boring, repetitive work","D":"It is impossible to introduce automated machinery"},"correctOption":"C","correctAnswer":"Low employee motivation due to boring, repetitive work","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because performing repetitive, narrow tasks on a flow production line often leads to boredom, low job satisfaction, and poor employee motivation.","distractor_reasons":{"A":"Incorrect because flow production achieves the lowest average unit cost among the three main production methods.","B":"Incorrect because standardized flow production generally achieves consistent product quality.","C":"Correct selection.","D":"Incorrect because repetitive tasks in flow production offer huge scope for automation."}}},{"id":"P1_U4_MCQ_020","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_020","question":"A large consumer goods company plans to manufacture a standardized brand of washing powder for millions of households worldwide with steady, year-round demand. Which production method should the company choose?","options":{"A":"Job production, because every customer wants a unique formula","B":"Batch production, because demand is too small for continuous operation","C":"Job production, because it requires the lowest skilled labour costs","D":"Flow production, because large, steady demand for a standardized product lowers unit costs"},"correctOption":"D","correctAnswer":"Flow production, because large, steady demand for a standardized product lowers unit costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because flow production is ideal when there is large, continuous demand for an identical, mass-market product, allowing the firm to minimize average unit costs.","distractor_reasons":{"A":"Incorrect because standard household washing powder is a uniform mass-market good, not a bespoke item.","B":"Incorrect because millions of households worldwide represent a huge mass market rather than a small niche market.","C":"Incorrect because job production actually requires highly skilled workers and results in high unit labour costs.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_021","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_021","question":"A luxury yacht builder constructs each vessel only after an individual buyer specifies the hull length, cabin layout, and interior wood finishes. Why is job production the most appropriate method for this business?","options":{"A":"Each product must meet the exact requirements of an individual customer","B":"It allows the builder to produce identical yachts 24 hours a day on an assembly line","C":"It eliminates the need to employ skilled craftspeople","D":"It guarantees the shortest possible production time per yacht"},"correctOption":"A","correctAnswer":"Each product must meet the exact requirements of an individual customer","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because job production is specifically suited to unique, high-value products tailored to an individual customer's exact specifications.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because continuous 24-hour production of identical goods describes flow production.","C":"Incorrect because job production typically relies heavily on highly skilled labour.","D":"Incorrect because job production is slower per unit than batch or flow production due to custom specifications."}}},{"id":"P1_U4_MCQ_022","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_022","question":"A food canning factory introduces electric sealing machines to replace manual hand-sealing tools, though an employee must still position each can and press a switch to operate the machine. Which technological change does this represent?","options":{"A":"Automation","B":"Mechanisation","C":"3D printing","D":"Artificial intelligence"},"correctOption":"B","correctAnswer":"Mechanisation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because mechanisation introduces machines into production to assist workers, while employees still directly operate and control the machinery.","distractor_reasons":{"A":"Incorrect because automation uses computer-controlled technology to make processes work automatically without human operator control.","B":"Correct selection.","C":"Incorrect because 3D printing creates physical three-dimensional objects layer-by-layer from digital files.","D":"Incorrect because artificial intelligence involves computer systems performing tasks like conversational customer chatbots."}}},{"id":"P1_U4_MCQ_023","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_023","question":"An automotive factory installs computer-controlled robotic arms that weld and paint car bodies automatically 24 hours a day without human operators controlling the equipment. What is this production technology called?","options":{"A":"Electronic Point of Sale (EPOS)","B":"Job production","C":"Automation","D":"Contactless processing"},"correctOption":"C","correctAnswer":"Automation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because automation uses advanced computer-controlled technology and robotics to run production processes automatically without direct employee operation.","distractor_reasons":{"A":"Incorrect because EPOS is a retail checkout barcode-scanning and inventory-tracking system.","B":"Incorrect because job production is a labour-intensive method of creating unique one-off products.","C":"Correct selection.","D":"Incorrect because contactless technology refers to wireless retail payment terminals rather than factory welding robots."}}},{"id":"P1_U4_MCQ_024","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_024","question":"An architectural practice uses specialist computer software to draw detailed building plans and rotate 3D digital models on screen so clients can view every angle before construction begins. Which technology is the firm using?","options":{"A":"Electronic Point of Sale (EPOS)","B":"Computer-Aided Manufacturing (CAM)","C":"Contactless payment terminals","D":"Computer-Aided Design (CAD)"},"correctOption":"D","correctAnswer":"Computer-Aided Design (CAD)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Computer-Aided Design (CAD) uses IT software to create, modify, rotate, and improve product or building designs quickly.","distractor_reasons":{"A":"Incorrect because EPOS is used at retail checkouts to scan barcodes and update inventory.","B":"Incorrect because CAM refers to computer-controlled factory machinery that manufactures physical goods rather than design software.","C":"Incorrect because contactless terminals process customer payments in shops and cafes.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_025","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_025","question":"A precision engineering firm links its digital design files directly to computer-controlled cutting and milling machines that manufacture metal engine parts with minimal human error. Which technology is being used?","options":{"A":"Computer-Aided Manufacturing (CAM)","B":"Kaizen cell layout","C":"Electronic Point of Sale (EPOS)","D":"Artificial intelligence chatbots"},"correctOption":"A","correctAnswer":"Computer-Aided Manufacturing (CAM)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Computer-Aided Manufacturing (CAM) uses software and computer-controlled machinery to automate physical manufacturing processes with high accuracy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Kaizen is a lean production philosophy based on worker suggestions rather than computer-controlled lathes.","C":"Incorrect because EPOS is a retail checkout system for scanning barcodes.","D":"Incorrect because chatbots handle customer service enquiries rather than machining metal engine components."}}},{"id":"P1_U4_MCQ_026","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_026","question":"A sports footwear designer creates a digital file of a new running shoe sole and produces a physical three-dimensional sample overnight using a machine that builds layers of polymer material. Which technology is being used?","options":{"A":"EPOS scanning","B":"3D printing","C":"Contactless payment","D":"Batch weaving"},"correctOption":"B","correctAnswer":"3D printing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because 3D printing produces a physical three-dimensional object directly from a digital design without requiring skilled manual labour.","distractor_reasons":{"A":"Incorrect because EPOS scanning records retail sales at store checkouts.","B":"Correct selection.","C":"Incorrect because contactless payment is a method for customers to pay for goods or services.","D":"Incorrect because batch weaving refers to traditional textile production rather than digital additive manufacturing."}}},{"id":"P1_U4_MCQ_027","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_027","question":"Previously, an appliance manufacturer waited four weeks and paid high fees to external workshops to build prototype parts, but now creates prototypes in-house within hours using 3D printers. How does 3D printing benefit this business?","options":{"A":"It eliminates the need for any electricity in the design department","B":"It guarantees that competitors cannot copy the final product","C":"It reduces the time and cost required to develop and test new product prototypes","D":"It replaces the need for all marketing and market research"},"correctOption":"C","correctAnswer":"It reduces the time and cost required to develop and test new product prototypes","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because 3D printing allows businesses to produce and adjust prototypes much faster and at a much lower cost than traditional prototype manufacturing.","distractor_reasons":{"A":"Incorrect because 3D printers require electrical power to operate.","B":"Incorrect because 3D printing speeds up internal prototyping; it does not provide legal patent protection against competitors.","C":"Correct selection.","D":"Incorrect because businesses still need market research to verify customer demand even when prototypes are built quickly."}}},{"id":"P1_U4_MCQ_028","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_028","question":"A busy train-station coffee shop installs payment terminals that allow customers to pay by tapping their smartphones or smartwatches in under two seconds. How does this technology improve productivity in the service sector?","options":{"A":"It increases the amount of cash employees must count at closing time","B":"It requires customers to enter long passwords for every small purchase","C":"It allows the cafe to reduce the quality of its coffee beans","D":"It speeds up customer service transactions and reduces operating costs"},"correctOption":"D","correctAnswer":"It speeds up customer service transactions and reduces operating costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because contactless payments increase transaction speed and customer convenience, allowing staff to serve more customers per hour and lowering operating costs.","distractor_reasons":{"A":"Incorrect because contactless payments reduce cash handling rather than increasing cash counting.","B":"Incorrect because contactless payments work quickly by tapping a device or card, avoiding lengthy manual verification for routine purchases.","C":"Incorrect because payment technology improves checkout speed and does not involve lowering ingredient quality.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_029","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_029","question":"At a supermarket checkout, scanning an item's barcode prints the price on the customer's receipt while automatically updating inventory records and ordering new stock when levels run low. Which retail technology is this?","options":{"A":"Electronic Point of Sale (EPOS)","B":"Computer-Aided Design (CAD)","C":"3D printing","D":"Job production"},"correctOption":"A","correctAnswer":"Electronic Point of Sale (EPOS)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because EPOS systems scan product barcodes at checkouts to display prices, print receipts, update inventory records automatically, and trigger reorders.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because CAD is software used by engineers and architects to draw product designs.","C":"Incorrect because 3D printing manufactures physical objects from digital models.","D":"Incorrect because job production is a manufacturing method for one-off bespoke items."}}},{"id":"P1_U4_MCQ_030","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_030","question":"An online airline booking company introduces an artificial intelligence (AI) chatbot on its website to answer routine passenger questions about flight schedules and baggage allowances 24 hours a day. What is a major advantage of this technology to the airline?","options":{"A":"It guarantees that no passenger will ever experience a flight delay","B":"It speeds up responses to customer enquiries while reducing customer service wage costs","C":"It eliminates the need to maintain computer servers or IT systems","D":"It provides face-to-face personal interaction for elderly travellers"},"correctOption":"B","correctAnswer":"It speeds up responses to customer enquiries while reducing customer service wage costs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because AI chatbots provide instant conversational replies to customer queries at any time while greatly reducing the number of call-centre staff needed.","distractor_reasons":{"A":"Incorrect because customer service chatbots answer enquiries; they do not control flight operations or weather delays.","B":"Correct selection.","C":"Incorrect because AI chatbots rely heavily on IT infrastructure and data programming.","D":"Incorrect because AI chatbots replace human interaction with automated text or voice responses."}}},{"id":"P1_U4_MCQ_031","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_031","question":"A steelmaking factory installs automated robotic arms to transport red-hot molten metal between furnaces, replacing workers who previously performed this hazardous task manually. How does this technological change benefit the business?","options":{"A":"It eliminates the initial capital cost of buying equipment","B":"It increases the number of unskilled workers on the factory floor","C":"It improves workplace safety and reduces injury and compensation costs","D":"It allows the factory to avoid training maintenance engineers"},"correctOption":"C","correctAnswer":"It improves workplace safety and reduces injury and compensation costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because automating dangerous tasks removes workers from hazardous environments, reducing workplace accidents and health and safety compensation costs.","distractor_reasons":{"A":"Incorrect because buying automated robotics requires very high initial capital expenditure.","B":"Incorrect because automation reduces rather than increases the number of unskilled manual workers required.","C":"Correct selection.","D":"Incorrect because businesses must invest in training specialist technicians to program and maintain automated equipment."}}},{"id":"P1_U4_MCQ_032","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_032","question":"A packaging manufacturer replaces older manual presses with automated computer-controlled machinery that operates continuously 24 hours a day, 7 days a week. How does this help the business meet rising orders without building a new factory?","options":{"A":"By reducing machine capacity utilisation","B":"By increasing the number of tea breaks required per shift","C":"By switching from flow production to job production","D":"By increasing total output and capacity utilisation from its existing premises"},"correctOption":"D","correctAnswer":"By increasing total output and capacity utilisation from its existing premises","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because 24/7 automated operation significantly increases the output produced within an existing factory, maximizing capacity utilisation without costly premises expansion.","distractor_reasons":{"A":"Incorrect because operating 24/7 increases rather than reduces capacity utilisation.","B":"Incorrect because automated machines operate continuously without needing rest breaks.","C":"Incorrect because 24/7 automated lines are used for continuous flow production, not one-off job production.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_033","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_033","question":"A small family-owned metal workshop decides not to invest in automated robotic welding equipment even though larger rivals use it to lower their unit costs. What is the most likely reason for this small business's decision?","options":{"A":"The high initial capital cost of buying automated equipment and borrowing interest","B":"Automated machinery always produces lower quality welds than hand tools","C":"Government laws ban small businesses from using computer-controlled machines","D":"Automated equipment reduces labour productivity in manufacturing"},"correctOption":"A","correctAnswer":"The high initial capital cost of buying automated equipment and borrowing interest","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automated machinery requires huge upfront capital investment and interest charges on loans, which smaller businesses often cannot afford.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because automated CAM equipment typically produces higher, more consistent quality than manual work.","C":"Incorrect because governments do not prohibit small firms from adopting automation.","D":"Incorrect because automation increases labour productivity rather than reducing it."}}},{"id":"P1_U4_MCQ_034","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_034","question":"A fully automated soft-drinks bottling plant relies on a central computer network to coordinate conveyors, fillers, and packers, when a software fault occurs during peak summer demand. What disadvantage of automation does this illustrate?","options":{"A":"Workers become over-reliant on hand tools","B":"A single technical or machine failure brings the entire production process to a halt","C":"Output quality varies wildly from bottle to bottle","D":"Fixed costs fall to zero whenever a breakdown happens"},"correctOption":"B","correctAnswer":"A single technical or machine failure brings the entire production process to a halt","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because heavy reliance on integrated automated equipment means that a breakdown or computer crash immediately stops the entire production line.","distractor_reasons":{"A":"Incorrect because an automated plant does not use manual hand tools to bottle drinks.","B":"Correct selection.","C":"Incorrect because automation ensures consistent quality during normal operation; the issue here is a total stoppage from system failure.","D":"Incorrect because fixed costs such as rent and loan interest still must be paid even when machinery breaks down."}}},{"id":"P1_U4_MCQ_035","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_035","question":"A high-street bank closes half its branches and replaces telephone advisers with automated voice systems and online chatbots, leading to complaints from older and disabled customers. What disadvantage of service-sector technology does this highlight?","options":{"A":"Higher paperwork costs in local branches","B":"Slower processing of routine digital transfers","C":"Loss of personal human communication can harm customer service and the brand's caring image","D":"Increased need to employ unskilled branch cashiers"},"correctOption":"C","correctAnswer":"Loss of personal human communication can harm customer service and the brand's caring image","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because removing human contact in service businesses can frustrate customers who need personal assistance—such as elderly or disabled clients—damaging the firm's caring reputation.","distractor_reasons":{"A":"Incorrect because digital banking reduces rather than increases paperwork costs.","B":"Incorrect because digital systems process routine transactions faster than manual branch visits.","C":"Correct selection.","D":"Incorrect because automation reduces rather than increases the need for branch cashiers."}}},{"id":"P1_U4_MCQ_036","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_036","question":"A luxury bespoke watchmaker whose wealthy clients pay high prices for hand-engraved movements decides against installing automated assembly robots. Why is automation unsuitable for this business?","options":{"A":"Robots cannot operate for more than four hours per day","B":"Automated machinery always increases variable labour costs per unit","C":"Customers of bespoke luxury goods do not care about product quality","D":"Customers value unique, handmade craftsmanship rather than standardized mass-produced items"},"correctOption":"D","correctAnswer":"Customers value unique, handmade craftsmanship rather than standardized mass-produced items","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because automation is inappropriate for craft-based businesses where customers specifically pay premium prices for unique, handmade items.","distractor_reasons":{"A":"Incorrect because automated robots can operate continuously 24 hours a day.","B":"Incorrect because automation typically lowers variable labour costs per unit produced.","C":"Incorrect because luxury buyers demand exceptional quality, but they associate it with traditional hand craftsmanship rather than mass automation.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_037","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_037","question":"After a biscuit factory installs automated packaging machines to replace the repetitive job of folding boxes by hand, the remaining operators are trained to monitor digital quality controls and adjust machine settings. How does this change benefit the remaining employees?","options":{"A":"Greater job satisfaction from performing more varied, skilled tasks instead of boring work","B":"Elimination of all training requirements in the factory","C":"Guaranteed lifetime employment without any technological changes","D":"Higher risk of repetitive strain injuries from manual box folding"},"correctOption":"A","correctAnswer":"Greater job satisfaction from performing more varied, skilled tasks instead of boring work","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automating routine, repetitive tasks allows remaining employees to develop higher-order technical skills and enjoy more interesting, satisfying work.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because remaining workers actually require training to operate and maintain the new automated equipment.","C":"Incorrect because technological change continues to evolve and does not guarantee lifetime job security.","D":"Incorrect because automating box folding removes rather than increases repetitive manual strain."}}},{"id":"P1_U4_MCQ_038","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_038","question":"Following the introduction of computer-aided manufacturing (CAM) at an electronics plant, labour productivity rises by 60%. How might remaining employees benefit financially from this development?","options":{"A":"By receiving statutory redundancy payments while staying in their jobs","B":"By negotiating higher wages because higher output per worker lowers average unit costs","C":"By working twice as many hours for the same weekly wage","D":"By avoiding income tax on all factory earnings"},"correctOption":"B","correctAnswer":"By negotiating higher wages because higher output per worker lowers average unit costs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher labour productivity allows a business to pay higher wages to skilled remaining staff without increasing its average cost per unit.","distractor_reasons":{"A":"Incorrect because redundancy payments are only paid to employees who lose their jobs, not those who remain employed.","B":"Correct selection.","C":"Incorrect because working twice as many hours for the same pay would be a pay cut per hour, not a financial benefit.","D":"Incorrect because higher productivity does not exempt employees from paying government income tax."}}},{"id":"P1_U4_MCQ_039","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_039","question":"A large distribution warehouse introduces automated robotic pickers to retrieve online orders from shelves, resulting in 60 unskilled warehouse workers losing their jobs. What is a major risk for these displaced employees?","options":{"A":"Higher promotion prospects within the warehouse","B":"Excessive overtime pay from operating the new robots","C":"Long-term unemployment if they lack the skills needed for high-technology roles","D":"Increased job security across the logistics industry"},"correctOption":"C","correctAnswer":"Long-term unemployment if they lack the skills needed for high-technology roles","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because automation often makes unskilled manual workers redundant, leaving them at high risk of long-term unemployment if they cannot retrain for technical roles.","distractor_reasons":{"A":"Incorrect because employees who have been made redundant no longer work at the warehouse.","B":"Incorrect because the unskilled workers lost their jobs rather than operating the new robots.","C":"Correct selection.","D":"Incorrect because widespread automation reduces job security for unskilled manual workers."}}},{"id":"P1_U4_MCQ_040","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_040","question":"Managers at a commercial printing firm announce plans to replace traditional printing presses with fully automated digital systems next year, causing widespread anxiety among long-serving staff. How is this likely to affect the workforce?","options":{"A":"Employees will immediately become more loyal and productive","B":"All employees will welcome the opportunity to work fewer hours for lower pay","C":"Training costs for the business will fall to zero","D":"Fear of change and perceived loss of job security may reduce employee motivation"},"correctOption":"D","correctAnswer":"Fear of change and perceived loss of job security may reduce employee motivation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because employees often fear new technology and worry about losing their jobs, which lowers job satisfaction and motivation.","distractor_reasons":{"A":"Incorrect because anxiety over potential job losses typically reduces rather than increases loyalty and motivation.","B":"Incorrect because employees rarely welcome lower pay or uncertainty about their livelihoods.","C":"Incorrect because introducing digital presses requires significant training expenditure.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_041","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_041","question":"A medical instrument manufacturer switches from manual drilling to computer-aided manufacturing (CAM) when shaping surgical steel tools. How does this technological upgrade affect product quality?","options":{"A":"Higher and more consistent accuracy with fewer defects from human error","B":"Greater variation between individual surgical instruments","C":"Higher scrap rates due to slower machine cutting speeds","D":"Lower reliability because computers cannot follow exact measurements"},"correctOption":"A","correctAnswer":"Higher and more consistent accuracy with fewer defects from human error","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because computer-controlled CAM equipment follows exact digital specifications repeatedly without human fatigue or error, improving quality and consistency.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because CAM reduces variation and makes every unit identical rather than increasing variation.","C":"Incorrect because higher precision lowers scrap and wastage rates.","D":"Incorrect because computers execute precise measurements far more reliably than manual hand tools."}}},{"id":"P1_U4_MCQ_042","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_042","question":"An aerospace component supplier purchases advanced computer-controlled 3D metal printers, only to find that none of its current machinists know how to program or maintain them. What immediate challenge does the business face?","options":{"A":"Lower fixed costs in the first year of operation","B":"Additional costs and time required to train staff or recruit specialists","C":"Excessive demand from customers before the machines are unpacked","D":"A legal ban on operating 3D printers in manufacturing"},"correctOption":"B","correctAnswer":"Additional costs and time required to train staff or recruit specialists","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because introducing advanced technology requires businesses to pay for training existing staff or hiring skilled programmers and maintenance technicians, which takes time and money.","distractor_reasons":{"A":"Incorrect because purchasing expensive new equipment increases rather than lowers fixed costs.","B":"Correct selection.","C":"Incorrect because the immediate internal problem described is the lack of employee skills to run the new equipment.","D":"Incorrect because 3D metal printing is legally and widely used in aerospace engineering."}}},{"id":"P1_U4_MCQ_043","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_043","question":"A textile manufacturer redesigns its dyeing process to eliminate toxic river discharge, reduce water consumption by 40%, and use organic cotton. Which operational approach is this business adopting?","options":{"A":"Quality control inspection","B":"Batch production","C":"Sustainable production","D":"Diseconomies of scale"},"correctOption":"C","correctAnswer":"Sustainable production","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sustainable production involves minimising the use of natural resources and dangerous materials while reducing waste and pollution.","distractor_reasons":{"A":"Incorrect because quality control checks finished goods for defects rather than reducing environmental damage.","B":"Incorrect because batch production is a method of manufacturing goods in groups rather than an environmental strategy.","C":"Correct selection.","D":"Incorrect because diseconomies of scale refer to rising average costs when a business grows too large."}}},{"id":"P1_U4_MCQ_044","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_044","question":"A food distribution warehouse installs solar panels across its roof and large storage batteries to power its refrigeration units and electric delivery vans. Why does this make the business's energy use sustainable?","options":{"A":"Solar power burns fossil fuels more efficiently than coal power stations","B":"Solar panels eliminate all initial capital expenditure for the warehouse","C":"Battery storage allows the business to increase carbon dioxide emissions","D":"Solar power is a renewable energy source that is not used up when generating electricity"},"correctOption":"D","correctAnswer":"Solar power is a renewable energy source that is not used up when generating electricity","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because renewable energy sources such as solar, wind, and hydropower are not depleted when used and do not emit greenhouse gases during generation.","distractor_reasons":{"A":"Incorrect because solar panels generate electricity directly from sunlight without burning fossil fuels.","B":"Incorrect because installing solar panels and storage batteries involves high initial capital costs.","C":"Incorrect because renewable solar energy reduces rather than increases carbon dioxide emissions.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_045","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_045","question":"A refrigerator manufacturer redesigns its outer metal cabinets to use thinner, high-strength steel panels, cutting the amount of iron ore and coal needed per appliance by 18%. Which sustainable production method is being applied?","options":{"A":"Using fewer natural resources","B":"Reusing pre-owned refrigerators","C":"Using biodegradable packaging","D":"Switching to wind energy"},"correctOption":"A","correctAnswer":"Using fewer natural resources","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because redesigning products so fewer raw materials are needed per unit helps preserve finite natural resources for future generations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the manufacturer is producing new appliances with thinner steel rather than refilling or reusing old appliances.","C":"Incorrect because the change involves the steel panels of the product itself rather than its outer packaging.","D":"Incorrect because the scenario describes reducing raw steel materials rather than changing electricity sources."}}},{"id":"P1_U4_MCQ_046","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_046","question":"A clothing manufacturer upgrades to precision laser-cutting machines that arrange shirt patterns more tightly on rolls of fabric, reducing discarded fabric off-cuts by 30%. Which sustainable practice does this demonstrate?","options":{"A":"Developing biodegradable products","B":"Creating less waste through more accurate production methods","C":"Recycling customer clothing into construction materials","D":"Using hydroelectric power"},"correctOption":"B","correctAnswer":"Creating less waste through more accurate production methods","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because improving the accuracy of cutting and manufacturing processes prevents raw materials from being wasted unnecessarily.","distractor_reasons":{"A":"Incorrect because reducing fabric off-cuts is about cutting accuracy, not making biodegradable fabrics.","B":"Correct selection.","C":"Incorrect because the factory is preventing off-cut waste during production rather than reprocessing used clothes into different goods.","D":"Incorrect because the scenario focuses on fabric waste reduction rather than renewable energy."}}},{"id":"P1_U4_MCQ_047","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_047","question":"A local juice bar collects empty glass bottles from regular customers, washes and sterilises them, refills them with fresh juice, and attaches new labels. Which sustainability method is the juice bar using?","options":{"A":"Recycling","B":"Using renewable energy","C":"Reusing","D":"Job production"},"correctOption":"C","correctAnswer":"Reusing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because reusing involves using an item again for the same or another purpose without breaking it down or altering its physical material.","distractor_reasons":{"A":"Incorrect because recycling involves crushing, melting, or reprocessing used materials to manufacture a different product.","B":"Incorrect because washing and refilling bottles is a material-reuse practice rather than an energy generation method.","C":"Correct selection.","D":"Incorrect because job production refers to making one-off bespoke products to customer order."}}},{"id":"P1_U4_MCQ_048","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_048","question":"A car tyre manufacturer collects rejected tyres from its production line, shreds and reprocesses the rubber, and converts it into sound-insulating panels for buildings. Which sustainability method is being used?","options":{"A":"Reusing","B":"Using biodegradable packaging","C":"Just-in-time inventory control","D":"Recycling"},"correctOption":"D","correctAnswer":"Recycling","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because recycling takes previously used or rejected materials and reprocesses them so they can be turned into other, different products.","distractor_reasons":{"A":"Incorrect because reusing uses an item again without altering its form, whereas these tyres are shredded and converted into building panels.","B":"Incorrect because car tyres are made of vulcanised rubber rather than biodegradable packaging.","C":"Incorrect because just-in-time is an inventory management method rather than material reprocessing.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_049","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_049","question":"A tableware company launches a new line of takeaway lunch boxes made from agricultural rice husks and cutlery made from sustainable bamboo to replace single-use plastics. Which sustainable method is this business using?","options":{"A":"Developing environmentally friendly products","B":"Automating its assembly line with robotics","C":"Switching to batch production","D":"Increasing fixed overhead costs"},"correctOption":"A","correctAnswer":"Developing environmentally friendly products","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because developing environmentally friendly products means creating goods made from renewable or non-polluting materials that do not harm the environment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because robotics is a production technology method rather than a sustainable product design strategy.","C":"Incorrect because batch production relates to production volume rather than environmentally friendly materials.","D":"Incorrect because raising fixed costs is a financial drawback, not a sustainable production method."}}},{"id":"P1_U4_MCQ_050","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_050","question":"A tomato ketchup manufacturer replaces its non-recyclable plastic squeeze bottles with compostable, paper-based bottles made from sustainably managed forests. Which sustainable method is being applied?","options":{"A":"Installing wind turbines","B":"Using environmentally friendly packaging","C":"Quality control inspection","D":"Purchasing economies of scale"},"correctOption":"B","correctAnswer":"Using environmentally friendly packaging","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because replacing harmful plastic containers with recyclable or biodegradable materials is an example of using environmentally friendly packaging.","distractor_reasons":{"A":"Incorrect because wind turbines generate renewable electricity rather than addressing product packaging.","B":"Correct selection.","C":"Incorrect because quality control tests finished goods for defects rather than redesigning packaging materials.","D":"Incorrect because purchasing economies refer to bulk-buying discounts rather than sustainable packaging."}}},{"id":"P1_U4_MCQ_051","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_051","question":"After switching to 100% recycled fabrics and zero-plastic packaging, an outdoor clothing brand attracts thousands of eco-conscious customers and sees repeat orders rise sharply. What is the key benefit of sustainability shown here?","options":{"A":"Lower initial research and development costs","B":"Elimination of all employee training expenses","C":"Improved brand image and stronger customer loyalty","D":"Ability to ignore government environmental laws"},"correctOption":"C","correctAnswer":"Improved brand image and stronger customer loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because genuine sustainable practices improve a business's brand image and create goodwill, encouraging environmentally aware consumers to remain loyal.","distractor_reasons":{"A":"Incorrect because developing sustainable products and materials usually increases initial R&D costs.","B":"Incorrect because switching to sustainable practices requires training employees in new procedures.","C":"Correct selection.","D":"Incorrect because sustainable businesses comply with environmental laws rather than ignoring them."}}},{"id":"P1_U4_MCQ_052","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_052","question":"A manufacturing plant spends $300,000 installing on-site wind turbines and solar panels, which subsequently supply free electricity for the next 20 years. How does this investment affect the plant's costs over time?","options":{"A":"Both initial costs and long-run energy costs per unit increase permanently","B":"Initial costs are zero, while long-run energy costs double","C":"Variable raw material costs fall to zero immediately","D":"Initial capital costs are high, but long-run energy and unit production costs fall"},"correctOption":"D","correctAnswer":"Initial capital costs are high, but long-run energy and unit production costs fall","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because renewable energy equipment requires high upfront capital expenditure, but once paid for, sunlight and wind are free, lowering long-run average costs.","distractor_reasons":{"A":"Incorrect because free electricity from solar and wind lowers long-run energy costs per unit once installed.","B":"Incorrect because buying and installing turbines and panels requires substantial upfront finance.","C":"Incorrect because renewable electricity reduces energy expenses, not raw material costs.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_053","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_053","question":"An electric bicycle manufacturer committed to zero-waste production finds it easily attracts highly qualified engineers and experiences very low staff turnover. How does sustainable production explain this advantage?","options":{"A":"Employees feel proud to work for an environmentally responsible business, improving recruitment and retention","B":"Sustainable factories never need to pay competitive wages to skilled engineers","C":"Government laws force engineers to work for sustainable businesses","D":"Sustainable production eliminates all deadlines and performance targets"},"correctOption":"A","correctAnswer":"Employees feel proud to work for an environmentally responsible business, improving recruitment and retention","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because many workers want to work for ethical, environmentally friendly businesses, giving sustainable firms a strong sense of pride that improves recruitment and retention.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses still must offer fair pay alongside strong environmental values to retain skilled staff.","C":"Incorrect because workers choose their employers freely; there are no laws forcing engineers into green firms.","D":"Incorrect because sustainable manufacturers still operate with clear efficiency and production targets."}}},{"id":"P1_U4_MCQ_054","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_054","question":"A chemical processing plant invests in closed-loop water recycling systems so zero pollutants enter nearby rivers, ahead of strict new government environmental regulations. What is a major benefit of taking this action?","options":{"A":"It eliminates all initial equipment installation costs","B":"The business complies with legal controls and avoids heavy fines or forced closure","C":"It allows the plant to double its discharge of toxic waste","D":"It removes the need to monitor water quality"},"correctOption":"B","correctAnswer":"The business complies with legal controls and avoids heavy fines or forced closure","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because adopting sustainable methods ensures the business meets government environmental laws, avoiding legal penalties, fines, and bad publicity.","distractor_reasons":{"A":"Incorrect because installing closed-loop filtration systems requires upfront capital expenditure.","B":"Correct selection.","C":"Incorrect because closed-loop recycling eliminates rather than increases toxic waste discharge.","D":"Incorrect because the plant must continue monitoring water filtration to ensure legal standards are met."}}},{"id":"P1_U4_MCQ_055","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_055","question":"A small independent bakery wants to replace its gas ovens with solar-powered electric ovens and switch to biodegradable packaging, but its bank refuses a loan due to low current profits. Which disadvantage of sustainable production does this show?","options":{"A":"Consumers always boycott businesses that use biodegradable packaging","B":"Solar energy increases carbon emissions in the long run","C":"High initial investment costs can be difficult for small businesses to finance","D":"Governments fine small businesses that switch to renewable energy"},"correctOption":"C","correctAnswer":"High initial investment costs can be difficult for small businesses to finance","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because researching and purchasing sustainable equipment like solar panels and batteries involves high upfront costs that small businesses may struggle to finance.","distractor_reasons":{"A":"Incorrect because consumers generally favour rather than boycott businesses adopting eco-friendly packaging.","B":"Incorrect because solar energy reduces carbon emissions rather than increasing them.","C":"Correct selection.","D":"Incorrect because governments encourage rather than fine businesses adopting renewable energy."}}},{"id":"P1_U4_MCQ_056","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_056","question":"A multinational car manufacturer sets a target to achieve carbon-neutral production across all factories and suppliers, estimating the transition will require 12 years of redesign and investment. Which limitation of becoming sustainable does this highlight?","options":{"A":"Sustainable production always reduces product quality","B":"Renewable energy is illegal in large manufacturing plants","C":"Employees refuse to work in modern, clean factories","D":"Becoming sustainable takes a long time for planning, research, and redevelopment"},"correctOption":"D","correctAnswer":"Becoming sustainable takes a long time for planning, research, and redevelopment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a business cannot become sustainable overnight; switching energy sources, redesigning products, and rebuilding supply chains takes years.","distractor_reasons":{"A":"Incorrect because sustainable redesigns often improve durability and efficiency rather than lowering quality.","B":"Incorrect because renewable energy is encouraged rather than illegal in manufacturing.","C":"Incorrect because cleaner, safer factories generally improve employee recruitment and morale.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_057","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_057","question":"A sustainable furniture manufacturer uses certified replanted timber and pays for safe waste treatment, causing its prices to be 20% higher than an overseas rival operating in a country with no pollution controls. What competitive problem does the sustainable firm face?","options":{"A":"Price-sensitive consumers may buy cheaper products from polluting competitors that avoid environmental costs","B":"Certified timber cannot be used to make chairs or tables","C":"Polluting competitors always have a better brand image among eco-conscious buyers","D":"Sustainable firms are banned from exporting furniture"},"correctOption":"A","correctAnswer":"Price-sensitive consumers may buy cheaper products from polluting competitors that avoid environmental costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because competitors in countries with weak environmental laws can produce more cheaply by polluting, attracting customers who care only about low prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because certified sustainable timber is widely used to manufacture high-quality furniture.","C":"Incorrect because polluting firms suffer a worse, not better, brand image among environmentally aware consumers.","D":"Incorrect because sustainable firms face no export bans for using eco-friendly methods."}}},{"id":"P1_U4_MCQ_058","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_058","question":"A skincare company commits to using only sustainably harvested plant oils and recycled glass jars, forcing it to stop buying from a long-standing, reliable supplier that refused to change its plastic packaging. Which challenge of sustainable production does this illustrate?","options":{"A":"Lower employee pride in the brand","B":"Having to find and switch to new sustainable suppliers, risking higher costs or supply disruption","C":"Immediate elimination of all quality checks","D":"Reduced customer interest in ethical skincare"},"correctOption":"B","correctAnswer":"Having to find and switch to new sustainable suppliers, risking higher costs or supply disruption","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a business is only truly sustainable if its entire supply chain uses sustainable practices, which may require replacing trusted, low-cost suppliers.","distractor_reasons":{"A":"Incorrect because committing to sustainability usually increases employee pride rather than lowering it.","B":"Correct selection.","C":"Incorrect because switching to new suppliers actually requires careful quality checking of incoming materials.","D":"Incorrect because ethical and sustainable skincare typically attracts stronger consumer interest."}}},{"id":"P1_U4_MCQ_059","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_059","question":"A large hotel group introduces strict water-conservation, energy-saving, and waste-sorting procedures across all departments, requiring paid training sessions for 500 staff. Why is this a short-term drawback for the business?","options":{"A":"Trained staff will deliberately waste more water and electricity","B":"Waste sorting increases hotel landfill taxes","C":"Training employees to break old habits and follow sustainable practices adds to short-term costs","D":"Customers dislike hotels that conserve water and energy"},"correctOption":"C","correctAnswer":"Training employees to break old habits and follow sustainable practices adds to short-term costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because becoming sustainable requires employees to change old working habits, which demands time and expenditure on staff training.","distractor_reasons":{"A":"Incorrect because training teaches staff how to conserve resources rather than waste them.","B":"Incorrect because sorting and recycling waste reduces landfill disposal rather than increasing taxes.","C":"Correct selection.","D":"Incorrect because many travellers prefer staying at environmentally responsible hotels."}}},{"id":"P1_U4_MCQ_060","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_060","question":"A beverage bottling plant sets up small weekly Kaizen groups where machine operators suggest ways to capture and reuse rinse water and reduce electricity wastage during shift changes. How does Kaizen support sustainable production?","options":{"A":"By forcing the plant to buy expensive foreign oil","B":"By increasing the amount of plastic packaging per bottle","C":"By replacing all factory workers with solar panels","D":"By using frontline workers' practical ideas to continuously cut resource and energy waste"},"correctOption":"D","correctAnswer":"By using frontline workers' practical ideas to continuously cut resource and energy waste","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Kaizen groups empower employees who work directly with production processes to identify practical ways of eliminating material, water, and energy waste.","distractor_reasons":{"A":"Incorrect because sustainable Kaizen initiatives aim to reduce fossil fuel use rather than buy more oil.","B":"Incorrect because sustainable production seeks to reduce rather than increase plastic packaging.","C":"Incorrect because Kaizen involves employee participation rather than replacing staff with equipment.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_061","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_061","question":"A packaging company collects used aluminium drinks cans, melts them down in a furnace, and rolls the metal into new sheets of household aluminium foil. Why is this classified as recycling rather than reusing?","options":{"A":"The used material is reprocessed and converted into a different product rather than used again as a can","B":"Aluminium cans cannot be melted or reprocessed","C":"Reusing always requires melting metal at high temperatures","D":"Recycling uses more virgin bauxite ore than making brand-new cans"},"correctOption":"A","correctAnswer":"The used material is reprocessed and converted into a different product rather than used again as a can","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because recycling reprocesses used materials into new, different products, whereas reusing uses an item again in its original form without alteration.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because aluminium is highly recyclable through melting and rolling.","C":"Incorrect because reusing cleans and uses an item again without altering or melting it.","D":"Incorrect because recycling existing aluminium reduces the need to mine virgin ore."}}},{"id":"P1_U4_MCQ_062","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_062","question":"A cement factory switches its kilns from burning natural gas to burning coal because coal is currently cheaper to buy locally. Why does this decision fail to make the factory's energy use sustainable?","options":{"A":"Natural gas is a renewable energy source while coal is not","B":"Both coal and natural gas are non-renewable fossil fuels that emit carbon dioxide and cannot be replaced once burnt","C":"Burning coal produces zero greenhouse gases","D":"Sustainable production only applies to service businesses, not cement factories"},"correctOption":"B","correctAnswer":"Both coal and natural gas are non-renewable fossil fuels that emit carbon dioxide and cannot be replaced once burnt","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because coal, oil, and natural gas are all finite fossil fuels that emit carbon dioxide contributing to global warming, unlike renewable solar or wind power.","distractor_reasons":{"A":"Incorrect because natural gas is also a non-renewable fossil fuel, not a renewable energy source.","B":"Correct selection.","C":"Incorrect because burning coal emits large quantities of carbon dioxide and air pollutants.","D":"Incorrect because sustainable production applies to manufacturing and primary industries just as much as services."}}},{"id":"P1_U4_MCQ_063","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_063","question":"An online fashion retailer suffers falling sales after viral social media posts criticise its excessive plastic packaging and factory textile waste, prompting managers to invest in sustainable production. How can this investment increase long-term profit despite higher short-term costs?","options":{"A":"By ensuring the retailer never has to pay suppliers for materials","B":"By allowing the retailer to stop advertising completely","C":"By repairing brand reputation, winning back customers, and reducing material waste costs over time","D":"By eliminating all fixed costs from the business"},"correctOption":"C","correctAnswer":"By repairing brand reputation, winning back customers, and reducing material waste costs over time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because restoring consumer trust boosts sales revenue while cutting material waste reduces long-run unit costs, combining to raise future profit.","distractor_reasons":{"A":"Incorrect because sustainable materials still must be purchased from suppliers.","B":"Incorrect because businesses still promote their sustainable credentials to attract customers.","C":"Correct selection.","D":"Incorrect because fixed costs such as warehouse rent and salaries continue to exist."}}},{"id":"P1_U4_MCQ_064","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_064","question":"A wooden furniture factory pays monthly workshop rent, annual fire insurance, the factory manager's salary, and oak timber used for each table made. Which of these expenses is a variable cost?","options":{"A":"Monthly workshop rent","B":"Annual fire insurance","C":"The factory manager's salary","D":"Oak timber used for each table made"},"correctOption":"D","correctAnswer":"Oak timber used for each table made","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because variable costs change directly with the level of output; the more tables produced, the more oak timber is required.","distractor_reasons":{"A":"Incorrect because workshop rent is a fixed cost that must be paid regardless of how many tables are made.","B":"Incorrect because annual fire insurance is a fixed cost that does not vary with short-run output.","C":"Incorrect because a fixed management salary does not vary directly with the number of units produced.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_065","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_065","question":"A scented candle manufacturer has monthly fixed costs of $2,400 and a variable cost of $1.50 per candle. What is the total cost of producing 1,000 candles in a month?","options":{"A":"$3,900","B":"$1,500","C":"$2,401.50","D":"$3,400"},"correctOption":"A","correctAnswer":"$3,900","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because total variable cost is $1.50 x 1,000 = $1,500, and total cost equals fixed costs ($2,400) plus total variable costs ($1,500) = $3,900.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $1,500 is only the total variable cost, omitting the $2,400 fixed costs.","C":"Incorrect because this adds the variable cost of just one candle ($1.50) to fixed costs instead of multiplying by 1,000 units.","D":"Incorrect because this adds 1,000 units directly to $2,400 without multiplying by the $1.50 variable cost per unit."}}},{"id":"P1_U4_MCQ_066","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_066","question":"A skateboard factory produces 2,000 skateboards per month with monthly fixed costs of $14,000 and total variable costs of $26,000. What is the average cost per skateboard?","options":{"A":"$13","B":"$20","C":"$7","D":"$40,000"},"correctOption":"B","correctAnswer":"$20","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because total cost is $14,000 + $26,000 = $40,000, and dividing total cost ($40,000) by output (2,000 units) gives an average cost of $20 per skateboard.","distractor_reasons":{"A":"Incorrect because $13 is only the variable cost per unit ($26,000 / 2,000), ignoring fixed costs.","B":"Correct selection.","C":"Incorrect because $7 is only the average fixed cost ($14,000 / 2,000), ignoring variable costs.","D":"Incorrect because $40,000 is the total monthly cost rather than the cost per unit."}}},{"id":"P1_U4_MCQ_067","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_067","question":"A cupcake bakery produces 5,000 cupcakes in a week, with ingredients costing $0.40 per cupcake and packaging costing $0.10 per cupcake, alongside weekly fixed costs of $1,200. What is the total variable cost for the week?","options":{"A":"$2,000","B":"$3,700","C":"$2,500","D":"$0.50"},"correctOption":"C","correctAnswer":"$2,500","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because variable cost per unit is $0.40 + $0.10 = $0.50, and multiplying $0.50 by 5,000 cupcakes gives a total variable cost of $2,500.","distractor_reasons":{"A":"Incorrect because $2,000 includes only the $0.40 ingredient cost and omits the $0.10 packaging cost per cupcake.","B":"Incorrect because $3,700 is the total cost ($2,500 variable + $1,200 fixed), not total variable cost alone.","C":"Correct selection.","D":"Incorrect because $0.50 is the variable cost per single cupcake rather than total variable cost for 5,000 units."}}},{"id":"P1_U4_MCQ_068","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_068","question":"During a business class discussion, a student claims that 'fixed costs never change over time for any business.' Why is this statement inaccurate?","options":{"A":"Fixed costs vary every day depending on how many units a factory produces","B":"Raw materials and piece-rate wages are classified as fixed costs","C":"Fixed costs fall to zero whenever a factory closes for the weekend","D":"Fixed costs remain constant only in the short run within existing capacity, and will increase if the business expands into larger premises"},"correctOption":"D","correctAnswer":"Fixed costs remain constant only in the short run within existing capacity, and will increase if the business expands into larger premises","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because fixed costs do not vary with output in the short run at an existing factory, but can rise over time or when a business expands its scale and rents larger buildings.","distractor_reasons":{"A":"Incorrect because costs that vary daily with output are variable costs, not fixed costs.","B":"Incorrect because raw materials and piece-rate wages are variable costs.","C":"Incorrect because fixed costs such as rent and insurance still must be paid even when output is zero over a weekend.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_069","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_069","question":"An electronics manufacturer is choosing between producing Product X or Product Y, both with annual fixed costs of $20,000 and expected sales of 4,000 units: Product X sells for $15 with a variable cost of $8, while Product Y sells for $18 with a variable cost of $12. Based on this cost data, which product should the manufacturer choose?","options":{"A":"Product X, because it generates $4,000 more annual profit than Product Y","B":"Product Y, because it has a higher selling price per unit","C":"Product Y, because it has a higher variable cost per unit","D":"Product X, because its total revenue is higher than Product Y's revenue"},"correctOption":"A","correctAnswer":"Product X, because it generates $4,000 more annual profit than Product Y","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Product X makes a profit of ($15 x 4,000) - [$20,000 + ($8 x 4,000)] = $60,000 - $52,000 = $8,000, whereas Product Y makes ($18 x 4,000) - [$20,000 + ($12 x 4,000)] = $72,000 - $68,000 = $4,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because although Product Y's selling price is $3 higher, its variable cost is $4 higher, resulting in lower contribution and lower profit.","C":"Incorrect because a higher variable cost per unit reduces profit rather than increasing it.","D":"Incorrect because Product X's total revenue ($60,000) is lower than Product Y's ($72,000), yet Product X yields higher profit due to lower variable costs."}}},{"id":"P1_U4_MCQ_070","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_070","question":"A footwear company sells 3,000 pairs of winter boots each year at $40 per pair, with variable costs of $25 per pair and dedicated annual fixed costs of $55,000. Using this cost data, what decision should managers make?","options":{"A":"Continue production because the boots make an annual profit of $10,000","B":"Stop producing the boots because total costs of $130,000 exceed revenue of $120,000, causing a $10,000 loss","C":"Continue production because selling price exceeds variable cost per pair","D":"Stop producing the boots because revenue is $75,000"},"correctOption":"B","correctAnswer":"Stop producing the boots because total costs of $130,000 exceed revenue of $120,000, causing a $10,000 loss","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because total revenue is 3,000 x $40 = $120,000, while total costs are $55,000 + (3,000 x $25) = $130,000, resulting in an annual loss of $10,000.","distractor_reasons":{"A":"Incorrect because total costs ($130,000) are greater than total revenue ($120,000), producing a $10,000 loss rather than a profit.","B":"Correct selection.","C":"Incorrect because although contribution is positive ($15 x 3,000 = $45,000), it is insufficient to cover the $55,000 dedicated fixed costs.","D":"Incorrect because $75,000 is the total variable cost (3,000 x $25), whereas total revenue is $120,000."}}},{"id":"P1_U4_MCQ_071","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_071","question":"After expanding its output, a breakfast cereal manufacturer orders oats and cardboard boxes in huge quantities and negotiates a 15% bulk discount from its suppliers. Which economy of scale has this business achieved?","options":{"A":"Financial economies of scale","B":"Managerial economies of scale","C":"Purchasing economies of scale","D":"Technical economies of scale"},"correctOption":"C","correctAnswer":"Purchasing economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because purchasing economies of scale occur when large businesses buy raw materials or components in bulk and receive discounts that lower unit costs.","distractor_reasons":{"A":"Incorrect because financial economies involve obtaining bank loans at lower interest rates.","B":"Incorrect because managerial economies involve hiring specialist departmental managers to boost efficiency.","C":"Correct selection.","D":"Incorrect because technical economies involve using large-scale specialist machinery and flow production lines."}}},{"id":"P1_U4_MCQ_072","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_072","question":"A large national supermarket chain borrows $15 million from a commercial bank at a 4% annual interest rate, whereas a small independent grocer is charged 8.5% interest by the same bank. Which economy of scale explains the supermarket chain's lower borrowing cost?","options":{"A":"Marketing economies of scale","B":"Technical economies of scale","C":"Purchasing economies of scale","D":"Financial economies of scale"},"correctOption":"D","correctAnswer":"Financial economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because banks view large businesses as lower lending risks and therefore offer them loans at lower interest rates, reducing the cost per dollar borrowed.","distractor_reasons":{"A":"Incorrect because marketing economies relate to lower advertising and transport costs per unit sold.","B":"Incorrect because technical economies relate to high-capacity machinery and automated production lines.","C":"Incorrect because purchasing economies relate to bulk-buying discounts from material suppliers.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_073","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_073","question":"A major car manufacturer invests in an automated robotic welding line that completes 100 welds per minute, whereas a small specialist car maker cannot produce enough cars to keep such expensive machinery busy. Which economy of scale is the major manufacturer benefiting from?","options":{"A":"Technical economies of scale","B":"Financial economies of scale","C":"Purchasing economies of scale","D":"Diseconomies of scale"},"correctOption":"A","correctAnswer":"Technical economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because technical economies of scale occur when large firms afford expensive, indivisible high-capacity machinery and run it at high output levels to lower average costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because financial economies involve lower interest rates on loans for large businesses.","C":"Incorrect because purchasing economies involve bulk discounts on raw materials rather than machinery capacity.","D":"Incorrect because diseconomies of scale cause average costs to rise, whereas this lowers average costs."}}},{"id":"P1_U4_MCQ_074","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_074","question":"As a beverage company grows larger, it hires separate specialist managers for Operations, Marketing, and Finance while using larger delivery lorries to spread transport costs over more cases sold. Which two economies of scale are being achieved?","options":{"A":"Purchasing and financial economies","B":"Managerial and marketing economies","C":"Technical and financial economies","D":"Purchasing and technical economies"},"correctOption":"B","correctAnswer":"Managerial and marketing economies","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because hiring specialist managers for each functional department creates managerial economies, while using larger delivery vehicles lowers transport cost per unit under marketing economies.","distractor_reasons":{"A":"Incorrect because neither bulk-buying discounts (purchasing) nor lower bank interest rates (financial) are described here.","B":"Correct selection.","C":"Incorrect because the scenario highlights specialist managers and distribution transport rather than factory machinery or bank loans.","D":"Incorrect because bulk material discounts and factory production lines are not mentioned in the scenario."}}},{"id":"P1_U4_MCQ_075","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_075","question":"After expanding to 30,000 employees across 20 factories, an appliance manufacturer experiences slow messages between departments, wasted advertising on products not yet built, and rising defect rates due to poor supervision. Which problem is causing its average costs to rise?","options":{"A":"Purchasing economies of scale","B":"Technical economies of scale","C":"Diseconomies of scale","D":"Break-even margin of safety"},"correctOption":"C","correctAnswer":"Diseconomies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because poor communication, weak co-ordination between Marketing and Operations, and lack of control are classic diseconomies of scale that raise average costs as a firm becomes too large.","distractor_reasons":{"A":"Incorrect because purchasing economies reduce average costs through bulk buying.","B":"Incorrect because technical economies reduce average costs through high-capacity equipment.","C":"Correct selection.","D":"Incorrect because margin of safety measures how far actual sales exceed break-even output."}}},{"id":"P1_U4_MCQ_076","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_076","question":"A wooden toy manufacturer sells each toy train for $18, incurs variable material and piece-rate labour costs of $7 per train, and pays weekly fixed costs of $3,300. What is the contribution per unit?","options":{"A":"$25","B":"$300","C":"$7","D":"$11"},"correctOption":"D","correctAnswer":"$11","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because contribution per unit equals selling price per unit ($18) minus variable cost per unit ($7), which is $11.","distractor_reasons":{"A":"Incorrect because this adds variable cost ($7) to selling price ($18) instead of subtracting it.","B":"Incorrect because 300 units is the break-even output ($3,300 / $11), not the contribution per unit.","C":"Incorrect because $7 is the variable cost per unit rather than the contribution toward fixed costs.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_077","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_077","question":"A specialty coffee roaster has monthly fixed costs of $4,500, sells each bag of roasted beans for $15, and incurs variable costs of $6 per bag. What is the monthly break-even output?","options":{"A":"500 bags","B":"300 bags","C":"750 bags","D":"214 bags"},"correctOption":"A","correctAnswer":"500 bags","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because contribution per bag is $15 - $6 = $9, and dividing fixed costs ($4,500) by contribution per unit ($9) gives a break-even output of 500 bags.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this divides fixed costs ($4,500) by selling price ($15) instead of contribution per unit ($9).","C":"Incorrect because this divides fixed costs ($4,500) by variable cost ($6) instead of contribution per unit ($9).","D":"Incorrect because this adds selling price and variable cost ($21) before dividing into $4,500."}}},{"id":"P1_U4_MCQ_078","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_078","question":"A backpack manufacturer calculates its monthly break-even output at 1,200 backpacks and currently produces and sells 1,650 backpacks per month. What is the manufacturer's margin of safety?","options":{"A":"2,850 backpacks","B":"450 backpacks","C":"1,200 backpacks","D":"1,650 backpacks"},"correctOption":"B","correctAnswer":"450 backpacks","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because margin of safety is calculated as actual sales/output (1,650) minus break-even sales/output (1,200), which equals 450 backpacks.","distractor_reasons":{"A":"Incorrect because this adds actual sales and break-even output instead of subtracting break-even output from actual sales.","B":"Correct selection.","C":"Incorrect because 1,200 is the break-even output rather than the margin of safety.","D":"Incorrect because 1,650 is the actual sales volume rather than the buffer above break-even."}}},{"id":"P1_U4_MCQ_079","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_079","question":"A smartphone case maker has weekly fixed costs of $1,600, variable costs of $2 per case, and a selling price of $6 per case. If the business sells 600 cases in a week, how much profit does it make?","options":{"A":"$2,000","B":"$3,600","C":"$800","D":"$2,800"},"correctOption":"C","correctAnswer":"$800","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total revenue is 600 x $6 = $3,600 and total costs are $1,600 + (600 x $2) = $2,800, leaving a weekly profit of $800.","distractor_reasons":{"A":"Incorrect because $2,000 subtracts only fixed costs ($1,600) from revenue ($3,600), forgetting total variable costs ($1,200).","B":"Incorrect because $3,600 is total revenue before deducting fixed and variable costs.","C":"Correct selection.","D":"Incorrect because $2,800 is total weekly costs rather than profit."}}},{"id":"P1_U4_MCQ_080","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_080","question":"A smoothie bar has monthly fixed costs of $3,000, sells smoothies for $5 each, and currently has variable costs of $2 per smoothie (break-even output = 1,000 smoothies). If fruit ingredient costs rise by $0.50 per smoothie while the selling price stays at $5, what will be the new break-even output?","options":{"A":"1,000 smoothies","B":"600 smoothies","C":"857 smoothies","D":"1,200 smoothies"},"correctOption":"D","correctAnswer":"1,200 smoothies","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the new variable cost is $2.50, reducing contribution per unit to $5.00 - $2.50 = $2.50, so new break-even output is $3,000 / $2.50 = 1,200 smoothies.","distractor_reasons":{"A":"Incorrect because higher variable costs reduce contribution per unit and therefore increase break-even output.","B":"Incorrect because 600 divides $3,000 by the $5 selling price without subtracting variable costs.","C":"Incorrect because 857 adds $0.50 to contribution ($3.50) instead of subtracting $0.50 from contribution ($2.50).","D":"Correct selection."}}},{"id":"P1_U4_MCQ_081","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_081","question":"When examining a factory's break-even chart, a manager looks at an output level to the left of the point where the total revenue line crosses the total cost line. What does this position on the chart indicate?","options":{"A":"The business is making a loss because total costs exceed total revenue","B":"The business is making maximum profit","C":"Total fixed costs are equal to zero at this output","D":"The business has a positive margin of safety"},"correctOption":"A","correctAnswer":"The business is making a loss because total costs exceed total revenue","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because at any output level below (to the left of) the break-even point, the total cost line lies above the total revenue line, meaning the business makes a loss.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profit is only made to the right of (above) the break-even point.","C":"Incorrect because fixed costs remain positive and horizontal across all output levels on the chart.","D":"Incorrect because a positive margin of safety only exists when actual output is above the break-even output."}}},{"id":"P1_U4_MCQ_082","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_082","question":"A student is completing a break-even chart for a bakery where fixed costs are $4,000 per week and variable costs are $2 per cake. At zero output on the vertical axis, where should the total cost line begin?","options":{"A":"At the origin ($0)","B":"At $4,000 (the level of total fixed costs)","C":"At $2 (the variable cost per unit)","D":"At the break-even point"},"correctOption":"B","correctAnswer":"At $4,000 (the level of total fixed costs)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because total cost equals fixed costs plus total variable costs; at zero output, variable costs are $0, so total cost equals total fixed costs ($4,000).","distractor_reasons":{"A":"Incorrect because the total revenue line and total variable cost line start at the origin ($0), whereas total cost starts at fixed costs.","B":"Correct selection.","C":"Incorrect because $2 is the gradient (slope) per unit of the total cost line, not its starting point on the y-axis.","D":"Incorrect because the break-even point is where total revenue intersects total cost at a positive output level."}}},{"id":"P1_U4_MCQ_083","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_083","question":"A restaurant manager uses break-even analysis to test the effect of raising meal prices from $10 to $12 while fixed costs and variable costs per meal stay constant. What does the amended break-even chart show?","options":{"A":"The total cost line becomes steeper and break-even output increases","B":"The fixed cost line shifts upward and the margin of safety falls","C":"The total revenue line becomes steeper, lowering break-even output and increasing the margin of safety","D":"Customers will definitely buy more meals at the higher price"},"correctOption":"C","correctAnswer":"The total revenue line becomes steeper, lowering break-even output and increasing the margin of safety","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a higher selling price increases the slope of the total revenue line and raises contribution per unit, which reduces break-even output and increases the margin of safety.","distractor_reasons":{"A":"Incorrect because changing the selling price affects the total revenue line, not the total cost line.","B":"Incorrect because fixed costs are unaffected by a change in selling price.","C":"Correct selection.","D":"Incorrect because break-even charts do not predict customer demand reactions, and higher prices often reduce demand."}}},{"id":"P1_U4_MCQ_084","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_084","question":"A toy manufacturer relies on a break-even chart to forecast annual profits, ignoring the risk that 15% of toys produced may remain unsold in storage and that overtime wages will raise unit labour costs at high output. Which two limitations of break-even analysis are shown here?","options":{"A":"It ignores fixed costs and assumes zero revenue at all output levels","B":"It can only be used by service businesses and cannot calculate contribution","C":"It assumes fixed costs vary with every unit and selling prices always fall","D":"It assumes all output produced is sold and assumes variable costs per unit remain constant"},"correctOption":"D","correctAnswer":"It assumes all output produced is sold and assumes variable costs per unit remain constant","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because standard break-even analysis assumes no unsold inventories build up and assumes straight-line variable costs per unit (ignoring overtime rates or bulk discounts).","distractor_reasons":{"A":"Incorrect because break-even charts explicitly include fixed costs and plot total revenue rising with output.","B":"Incorrect because break-even analysis is widely used in manufacturing and relies directly on contribution per unit.","C":"Incorrect because break-even charts assume fixed costs are constant within existing scale and selling prices are constant.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_085","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_085","question":"A budget bus company charges very low ticket fares and offers no free refreshments, yet passengers rate its service highly because buses are clean, safe, and arrive on time. Why is this considered a quality service?","options":{"A":"Quality means meeting customer expectations and being fit for purpose, rather than being high-priced luxury","B":"Quality only depends on charging the highest price in the market","C":"Budget transport companies are exempt from customer expectations","D":"Quality is measured solely by the number of buses a company owns"},"correctOption":"A","correctAnswer":"Quality means meeting customer expectations and being fit for purpose, rather than being high-priced luxury","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because in Business Studies, quality means a good or service is of a standard that meets customer expectations and is fit for purpose, even at a low price.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because students often confuse quality with luxury or high price; a low-priced product is good quality if it meets customer expectations.","C":"Incorrect because customers still expect low-priced services to be reliable, safe, and fit for purpose.","D":"Incorrect because fleet size measures business scale rather than service quality."}}},{"id":"P1_U4_MCQ_086","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_086","question":"A blender manufacturer sells a batch of appliances with faulty motors, leading to widespread negative reviews on social media and hundreds of warranty returns. What are two immediate consequences for this business?","options":{"A":"Higher brand loyalty and lower unit production costs","B":"Damage to brand reputation and higher costs of replacing or repairing faulty goods","C":"Reduced customer complaints and higher market share","D":"Lower scrappage rates and increased employee motivation"},"correctOption":"B","correctAnswer":"Damage to brand reputation and higher costs of replacing or repairing faulty goods","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because failing to maintain quality leads to negative publicity, lost customers, and higher business costs from replacing or reworking defective products.","distractor_reasons":{"A":"Incorrect because faulty products destroy brand loyalty and raise costs rather than lowering them.","B":"Correct selection.","C":"Incorrect because poor quality increases customer complaints and causes market share to fall.","D":"Incorrect because defective batches increase scrappage and reworking rates."}}},{"id":"P1_U4_MCQ_087","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_087","question":"At the end of a smartphone assembly line, specialist technicians test samples of completed phones for screen clarity, battery charging, and camera focus before the boxes are shipped. Which quality method is being used?","options":{"A":"Quality assurance","B":"Just-in-time inventory control","C":"Quality control","D":"Kaizen"},"correctOption":"C","correctAnswer":"Quality control","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because quality control involves specialist inspectors testing finished products or samples at the end of the production process before they reach customers.","distractor_reasons":{"A":"Incorrect because quality assurance sets standards and checks quality at every stage throughout production by all employees.","B":"Incorrect because just-in-time focuses on minimizing inventory levels rather than testing finished phones.","C":"Correct selection.","D":"Incorrect because Kaizen involves regular employee improvement meetings to reduce waste."}}},{"id":"P1_U4_MCQ_088","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_088","question":"An aircraft engine manufacturer sets strict quality standards at every stage—from inspecting raw alloys to checking every weld—requiring all employees to verify their own work before passing it to the next stage. Which method of achieving quality is this?","options":{"A":"Final-stage quality control","B":"Mystery customer sampling","C":"Batch reworking","D":"Quality assurance"},"correctOption":"D","correctAnswer":"Quality assurance","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because quality assurance establishes agreed quality standards throughout every stage of the production process, with all workers responsible for checking their own work.","distractor_reasons":{"A":"Incorrect because final-stage quality control checks goods only at the very end of production using specialist inspectors.","B":"Incorrect because mystery customers are used in service businesses to test customer service experience.","C":"Incorrect because reworking means fixing faulty finished items after a defect has already occurred.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_089","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_089","question":"During end-of-line inspection at a wooden furniture factory, quality inspectors discover uneven varnish on 12 dining tables and send them back to the workshop to be sanded and re-varnished. What is this corrective process called?","options":{"A":"Reworking","B":"Quality assurance","C":"Lean elimination","D":"Prototyping"},"correctOption":"A","correctAnswer":"Reworking","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reworking means revising or repairing a defective product found during inspection until it reaches a satisfactory quality standard.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality assurance aims to prevent defects from occurring at each stage so no reworking is needed.","C":"Incorrect because lean production views reworking defects as a form of waste to be eliminated.","D":"Incorrect because prototyping involves building early test models of a new product design."}}},{"id":"P1_U4_MCQ_090","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_090","question":"A national restaurant chain hires anonymous 'mystery diners' to visit branches unannounced and report on waiting times, food temperature, and staff politeness. Which quality method is the restaurant chain using?","options":{"A":"Computer-aided manufacturing","B":"Quality control","C":"3D prototyping","D":"Just-in-time delivery"},"correctOption":"B","correctAnswer":"Quality control","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because employing an anonymous mystery customer to inspect and test the delivered service is a service-sector application of quality control.","distractor_reasons":{"A":"Incorrect because CAM refers to automated factory machinery.","B":"Correct selection.","C":"Incorrect because 3D prototyping builds physical sample models from digital designs.","D":"Incorrect because just-in-time delivery manages ingredient inventory arrival."}}},{"id":"P1_U4_MCQ_091","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_091","question":"A toy factory employs two specialist inspectors at the end of its assembly line rather than spending money training 150 temporary production workers to check quality. What is a main advantage of using quality control in this situation?","options":{"A":"It identifies the exact root cause of defects early in the production process","B":"It completely eliminates the cost of scrapping faulty finished toys","C":"Production workers can focus on output without needing expensive quality-checking training","D":"Every single toy is guaranteed to have zero manufacturing errors during assembly"},"correctOption":"C","correctAnswer":"Production workers can focus on output without needing expensive quality-checking training","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because under quality control, specialist inspectors handle final testing, allowing assembly workers to concentrate on production without extensive quality training.","distractor_reasons":{"A":"Incorrect because identifying and fixing root causes throughout production is an advantage of quality assurance, not end-of-line quality control.","B":"Incorrect because quality control often results in high scrappage or reworking costs when defects are found at the end.","C":"Correct selection.","D":"Incorrect because end-of-line inspection catches faults after they happen rather than preventing errors during assembly."}}},{"id":"P1_U4_MCQ_092","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_092","question":"At a jam factory, final quality inspectors reject 6% of finished jars every week because the lids are sealed crookedly, yet the problem continues month after month. Which disadvantage of quality control does this illustrate?","options":{"A":"All assembly workers spend too much time inspecting their own jars","B":"Quality inspectors lack experience in spotting faulty products","C":"It requires extensive off-the-job training for all factory staff","D":"It identifies faulty finished products at the end without necessarily fixing the cause of the fault in the process"},"correctOption":"D","correctAnswer":"It identifies faulty finished products at the end without necessarily fixing the cause of the fault in the process","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because quality control checks finished goods at the end of the line, so it catches defective jars without correcting the misaligned capping machine causing the fault.","distractor_reasons":{"A":"Incorrect because workers checking their own work at every stage is a feature of quality assurance, not quality control.","B":"Incorrect because the inspectors are successfully spotting the crooked lids; the problem is that the production fault persists.","C":"Incorrect because high employee training costs are a drawback of quality assurance rather than quality control.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_093","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_093","question":"A fireworks manufacturer wants to be certain that every rocket ignites safely, but firing a finished rocket destroys it so it cannot be sold to customers. Why is 100% final quality control testing impossible here?","options":{"A":"Testing every finished product destroys it and makes it unsellable","B":"Fireworks are always made using quality assurance","C":"Quality inspectors are not allowed to test hazardous products","D":"Customers expect fireworks to fail half the time"},"correctOption":"A","correctAnswer":"Testing every finished product destroys it and makes it unsellable","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when testing a finished product destroys it (such as fireworks or matches), testing every item leaves nothing to sell, so only samples can be tested.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because while quality assurance helps during assembly, the specific reason 100% final testing fails is destructive testing.","C":"Incorrect because trained safety inspectors do test samples of fireworks.","D":"Incorrect because customers expect fireworks to be safe and reliable."}}},{"id":"P1_U4_MCQ_094","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_094","question":"After introducing quality assurance across its cutting, stitching, and finishing departments, a luxury leather bag maker reduces its scrapped leather and reworking costs by 65%. Why does quality assurance achieve this saving?","options":{"A":"By employing twice as many end-of-line quality inspectors","B":"By detecting and correcting errors at each stage before faulty components move further through production","C":"By stopping all quality checks so production moves faster","D":"By using cheaper synthetic plastic instead of leather"},"correctOption":"B","correctAnswer":"By detecting and correcting errors at each stage before faulty components move further through production","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because quality assurance checks standards at every production stage, stopping faulty work from progressing and avoiding costly end-of-line scrappage or reworking.","distractor_reasons":{"A":"Incorrect because employing end-of-line inspectors is quality control, whereas quality assurance makes every worker responsible at each stage.","B":"Correct selection.","C":"Incorrect because quality assurance increases stage-by-stage checks rather than removing them.","D":"Incorrect because switching to cheaper materials would lower luxury quality rather than preventing defects."}}},{"id":"P1_U4_MCQ_095","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_095","question":"Under a new quality assurance system at an electronics plant, every assembly worker is given responsibility for checking their own work against agreed quality standards. How is this likely to affect the employees?","options":{"A":"Employees feel less trusted because inspectors watch them constantly","B":"Employees no longer need to follow any quality standards","C":"Employees accept responsibility for quality, increasing pride and motivation in their work","D":"Employee training requirements fall to zero"},"correctOption":"C","correctAnswer":"Employees accept responsibility for quality, increasing pride and motivation in their work","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because trusting employees to maintain quality standards at their own stage increases ownership, job satisfaction, and motivation.","distractor_reasons":{"A":"Incorrect because quality assurance empowers workers to check their own work rather than relying on external inspectors.","B":"Incorrect because quality assurance requires all employees to follow strict pre-set quality standards.","C":"Correct selection.","D":"Incorrect because quality assurance requires extensive training so workers know how to check standards."}}},{"id":"P1_U4_MCQ_096","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_096","question":"A medium-sized appliance manufacturer decides to switch from final quality control inspections to full quality assurance across 250 factory workers. What is a major short-term disadvantage of making this change?","options":{"A":"Increased customer complaints about faulty appliances","B":"Higher costs of hiring external mystery shoppers","C":"Complete elimination of quality standards in raw material supplies","D":"High costs and time required to train all employees to check quality standards"},"correctOption":"D","correctAnswer":"High costs and time required to train all employees to check quality standards","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because implementing quality assurance is expensive initially as every employee must be trained to understand, meet, and monitor quality standards.","distractor_reasons":{"A":"Incorrect because quality assurance reduces rather than increases customer complaints.","B":"Incorrect because mystery shoppers are used in retail/service quality control, not appliance manufacturing.","C":"Incorrect because quality assurance includes checking incoming raw materials against strict standards.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_097","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_097","question":"A furniture factory introduces quality assurance, but unmotivated workers rush their stage checks, and when an early-stage fault is found, the entire assembly line slows down while it is fixed. Which disadvantages of quality assurance does this illustrate?","options":{"A":"It relies on employee commitment and checking at every stage can slow down or hold up production","B":"It requires no employee involvement in quality standards","C":"It always increases end-of-line scrappage costs compared to quality control","D":"It can only be used in automated factories with zero employees"},"correctOption":"A","correctAnswer":"It relies on employee commitment and checking at every stage can slow down or hold up production","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality assurance depends heavily on motivated, committed employees and can slow down output when quality checks and early-stage fixes occur at each step.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality assurance requires 100% employee involvement at every stage.","C":"Incorrect because quality assurance reduces end-of-line scrappage costs rather than increasing them.","D":"Incorrect because quality assurance relies on employees checking standards throughout production."}}},{"id":"P1_U4_MCQ_098","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_098","question":"A medical device manufacturer produces heart pacemakers using expensive titanium components where any finished defect endangers human life and cannot be repaired. Why should this business choose quality assurance over quality control?","options":{"A":"Because quality assurance requires zero staff training","B":"Because patient safety is critical and the cost of scrapping a faulty finished device is extremely high","C":"Because pacemakers are low-priced mass-market items","D":"Because quality assurance allows faulty parts to be hidden inside the finished casing"},"correctOption":"B","correctAnswer":"Because patient safety is critical and the cost of scrapping a faulty finished device is extremely high","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when safety is paramount and scrapping a completed product is very costly, quality assurance prevents faults at early stages before expensive assembly finishes.","distractor_reasons":{"A":"Incorrect because quality assurance actually requires substantial staff training.","B":"Correct selection.","C":"Incorrect because pacemakers are high-value, precision medical devices, not low-priced mass goods.","D":"Incorrect because quality assurance prevents faulty parts from ever moving to the next stage."}}},{"id":"P1_U4_MCQ_099","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_099","question":"An exclusive fine-dining restaurant charges $180 per meal, making it impossible for the head chef to taste every customer's dish before it leaves the kitchen. Why is quality assurance the most suitable method for this restaurant?","options":{"A":"Tasting every finished meal is a form of quality assurance","B":"Fine-dining customers do not expect high food standards","C":"Setting strict standards for ingredients, preparation, cooking, and plating ensures consistent quality","D":"Quality assurance eliminates the need to hire trained chefs"},"correctOption":"C","correctAnswer":"Setting strict standards for ingredients, preparation, cooking, and plating ensures consistent quality","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when final testing of every meal is impossible and customer expectations are very high, setting and checking standards at every stage ensures consistent excellence.","distractor_reasons":{"A":"Incorrect because testing the finished product at the end is quality control, not quality assurance.","B":"Incorrect because customers paying $180 per meal have very high quality expectations.","C":"Correct selection.","D":"Incorrect because fine-dining restaurants still require skilled chefs trained to follow strict quality standards."}}},{"id":"P1_U4_MCQ_100","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_100","question":"A factory mass-produces inexpensive disposable plastic pens where material costs per pen are tiny and assembly staff turnover is very high. Why might the manager choose quality control rather than quality assurance?","options":{"A":"Quality control prevents every single defect from ever happening","B":"Disposable pens have high scrappage costs if a batch is faulty","C":"Quality assurance is illegal for plastic stationery products","D":"Training constantly changing staff for quality assurance is too expensive compared to sampling finished batches"},"correctOption":"D","correctAnswer":"Training constantly changing staff for quality assurance is too expensive compared to sampling finished batches","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when unit scrap costs are very low and staff turnover is high, training every worker for quality assurance is uneconomical compared to end-of-line sample inspections.","distractor_reasons":{"A":"Incorrect because quality control detects faults after production rather than preventing them.","B":"Incorrect because inexpensive disposable pens have very low material and scrappage costs.","C":"Incorrect because there are no laws banning quality assurance in stationery manufacturing.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_101","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_101","question":"A luxury electric car manufacturer requires workers to verify quality standards at every assembly station AND puts every finished vehicle through a four-hour track and safety test before delivery. Why does this business combine quality assurance and quality control?","options":{"A":"Quality assurance prevents early-stage faults while final quality control guarantees zero safety defects reach high-paying buyers","B":"Quality assurance only checks the paintwork while quality control checks the suppliers","C":"Combining both methods eliminates all labour and training costs","D":"Quality control is used to train workers while quality assurance is used to scrap cars"},"correctOption":"A","correctAnswer":"Quality assurance prevents early-stage faults while final quality control guarantees zero safety defects reach high-paying buyers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high-value, safety-critical manufacturers often use quality assurance to prevent costly errors during assembly alongside final quality control testing to guarantee total safety.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality assurance covers all stages including suppliers, while quality control tests the finished product.","C":"Incorrect because using both methods involves both training costs and final inspection costs.","D":"Incorrect because quality assurance aims to prevent scrap, and final inspectors perform quality control testing."}}},{"id":"P1_U4_MCQ_102","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_102","question":"A household appliance brand builds a strong reputation for durable, fault-free washing machines, resulting in 80% of customers buying from the brand again when upgrading. Which benefit of quality does this demonstrate?","options":{"A":"Higher warranty replacement costs","B":"Stronger brand loyalty and repeat sales","C":"Increased negative feedback on social media","D":"Higher employee absenteeism"},"correctOption":"B","correctAnswer":"Stronger brand loyalty and repeat sales","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consistently meeting customer expectations builds trust, brand loyalty, and repeat purchases.","distractor_reasons":{"A":"Incorrect because durable, fault-free products reduce rather than increase warranty replacement costs.","B":"Correct selection.","C":"Incorrect because reliable products generate positive rather than negative customer reviews.","D":"Incorrect because product reliability does not increase employee absenteeism."}}},{"id":"P1_U4_MCQ_103","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_103","question":"In a revision quiz, a student writes that 'quality assurance means hiring specialist inspectors at the end of the production line to remove faulty goods.' Why is this definition incorrect?","options":{"A":"Quality assurance is only used by retail shops, never by factories","B":"Quality inspectors only check raw materials, never finished goods","C":"That describes quality control; quality assurance sets and checks standards at every stage of production by all employees","D":"Quality assurance means lowering product prices so customers accept defects"},"correctOption":"C","correctAnswer":"That describes quality control; quality assurance sets and checks standards at every stage of production by all employees","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because students frequently confuse the two terms: end-of-line testing by specialist inspectors is quality control, whereas quality assurance is stage-by-stage responsibility by all workers.","distractor_reasons":{"A":"Incorrect because quality assurance is widely used in both manufacturing and service industries.","B":"Incorrect because quality control inspectors test finished products (or samples) at the end of production.","C":"Correct selection.","D":"Incorrect because quality assurance aims to eliminate defects rather than asking customers to accept them."}}},{"id":"P1_U4_MCQ_104","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_104","question":"A hairdressing salon rushes appointments during weekends, leading to uneven haircuts and unhappy clients demanding free re-cuts and posting poor reviews online. How does poor quality specifically affect this service business?","options":{"A":"It lowers the salon's rent and electricity bills","B":"It increases the number of new walk-in clients","C":"It eliminates the need to train junior stylists","D":"It raises costs by forcing staff to repeat services free of charge and damages future bookings"},"correctOption":"D","correctAnswer":"It raises costs by forcing staff to repeat services free of charge and damages future bookings","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because in service businesses, poor quality forces staff to spend unpaid time repeating the service while negative reviews drive away future customers.","distractor_reasons":{"A":"Incorrect because poor service quality does not reduce fixed overheads like rent.","B":"Incorrect because negative reviews reduce rather than increase new customer bookings.","C":"Incorrect because uneven haircuts indicate a greater need for staff training.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_105","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_105","question":"A gourmet chocolate manufacturer operating a quality assurance system rejects a delivery of cocoa beans because moisture levels exceed its agreed specification. Why is inspecting incoming supplies essential in quality assurance?","options":{"A":"High-quality finished chocolates cannot be produced if defective raw materials enter the first stage of production","B":"Rejecting raw materials eliminates the need to check quality during cooking and moulding","C":"Quality assurance only checks raw materials and ignores finished products","D":"Suppliers are legally required to provide raw materials free of charge if rejected"},"correctOption":"A","correctAnswer":"High-quality finished chocolates cannot be produced if defective raw materials enter the first stage of production","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality assurance begins at the very first stage—ensuring raw materials and components meet quality standards before entering production.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality assurance requires checks at every subsequent stage of production as well.","C":"Incorrect because quality assurance monitors all stages from incoming supplies through to final packaging.","D":"Incorrect because suppliers replace faulty deliveries under contract terms rather than supplying future orders for free."}}},{"id":"P1_U4_MCQ_106","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_106","question":"An aluminium smelting company processes heavy bauxite ore into pure aluminium metal that weighs 75% less than the extracted rock. Where should the company locate its smelting factory to minimize transport costs?","options":{"A":"In a city centre close to retail shopping malls","B":"Close to the bauxite mine where the heavy raw material is extracted","C":"On an island with no port or railway connections","D":"Next to a luxury tourist resort"},"correctOption":"B","correctAnswer":"Close to the bauxite mine where the heavy raw material is extracted","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when raw materials are much heavier and bulkier than the finished product (weight-losing), locating near the raw material source avoids paying to transport heavy waste rock long distances.","distractor_reasons":{"A":"Incorrect because transporting heavy bauxite ore into a high-rent city centre would create huge transport and land costs.","B":"Correct selection.","C":"Incorrect because lack of transport infrastructure would make shipping finished aluminium impossible.","D":"Incorrect because heavy smelting near a tourist resort would face pollution restrictions and high transport costs."}}},{"id":"P1_U4_MCQ_107","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_107","question":"A soft-drinks manufacturer mixes concentrated fruit syrup with large volumes of local water and glass bottles, making the filled bottles far heavier than the imported syrup. Where is the most cost-effective location for the bottling factory?","options":{"A":"Next to the overseas fruit farm where the syrup is made","B":"In a remote mountain region far from roads and towns","C":"Close to the main consumer markets to reduce distribution costs of heavy filled bottles","D":"In an area with no reliable water supply"},"correctOption":"C","correctAnswer":"Close to the main consumer markets to reduce distribution costs of heavy filled bottles","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when a product gains weight or bulk during production (by adding water and bottles), locating near the main market minimizes expensive transport of the heavy finished goods.","distractor_reasons":{"A":"Incorrect because shipping heavy water-filled glass bottles long distances from the fruit farm is far costlier than shipping concentrated syrup.","B":"Incorrect because poor transport links and distance from customers would raise distribution costs dramatically.","C":"Correct selection.","D":"Incorrect because a soft-drinks bottling plant requires an extensive, reliable water supply."}}},{"id":"P1_U4_MCQ_108","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_108","question":"A food-processing company cans freshly harvested sweetcorn and peaches that begin to spoil within 18 hours of picking. Which location factor is most critical when choosing a site for this factory?","options":{"A":"Proximity to luxury fashion boutiques","B":"Availability of university aerospace researchers","C":"High city-centre pedestrian footfall","D":"Locating close to the farms supplying the perishable raw materials"},"correctOption":"D","correctAnswer":"Locating close to the farms supplying the perishable raw materials","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because perishable agricultural raw materials must be processed quickly while still fresh, requiring factories to locate near the growing areas.","distractor_reasons":{"A":"Incorrect because fashion retailers are unrelated to agricultural food canning.","B":"Incorrect because aerospace research centres are irrelevant to fruit and vegetable canning.","C":"Incorrect because a food-canning factory sells through supermarkets rather than direct high-street footfall.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_109","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_109","question":"A commercial bakery produces fresh cream pastries and crusty bread loaves each morning for immediate delivery to supermarkets across a large city. Why does the bakery locate close to its urban retail market?","options":{"A":"Because the finished baked goods perish quickly and must reach stores while fresh","B":"Because wheat farms are always located inside city centres","C":"Because factory rent is cheapest in the middle of large cities","D":"Because bakeries use job production for mass-market supermarket loaves"},"correctOption":"A","correctAnswer":"Because the finished baked goods perish quickly and must reach stores while fresh","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because finished goods that perish quickly (such as fresh bread, cakes, and milk) need to be manufactured near their retail outlets so they arrive fresh.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because wheat is grown in rural agricultural regions, not city centres.","C":"Incorrect because urban land and rent costs are higher, not cheaper, than rural areas.","D":"Incorrect because supermarket bread is produced using batch or flow production, not job production."}}},{"id":"P1_U4_MCQ_110","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_110","question":"A microchip manufacturer plans to build a large-scale flow-production facility requiring vast single-storey buildings, uninterrupted high-voltage electricity, and millions of litres of purified water daily. Which location factors are most important?","options":{"A":"High-street shopping footfall and tourist attractions","B":"Large areas of flat land and reliable, extensive power and water supplies","C":"Proximity to small craft workshops and historical monuments","D":"High local unemployment with no technical education facilities"},"correctOption":"B","correctAnswer":"Large areas of flat land and reliable, extensive power and water supplies","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because large-scale flow production typically requires large areas of flat land alongside reliable, extensive water and electricity supplies.","distractor_reasons":{"A":"Incorrect because semiconductor factories sell to electronics manufacturers rather than passing high-street shoppers.","B":"Correct selection.","C":"Incorrect because craft workshops and monuments do not provide the industrial infrastructure required for microchip fabrication.","D":"Incorrect because microchip plants need reliable utilities and skilled technicians rather than lacking technical infrastructure."}}},{"id":"P1_U4_MCQ_111","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_111","question":"Several high-performance motorsport engineering firms locate in the same industrial region as specialist wind-tunnel testing facilities, precision engine suppliers, and a university automotive research department. Which location factor is attracting these manufacturers?","options":{"A":"Government bans on industrial manufacturing","B":"Low-cost unskilled agricultural labour","C":"Proximity to supporting businesses and specialist research institutions","D":"Perishable raw materials"},"correctOption":"C","correctAnswer":"Proximity to supporting businesses and specialist research institutions","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because manufacturers benefit from locating near supporting businesses (such as equipment maintenance, specialist suppliers, and university R&D departments).","distractor_reasons":{"A":"Incorrect because government bans prevent businesses from locating in an area rather than attracting them.","B":"Incorrect because motorsport engineering requires highly skilled technical specialists rather than unskilled farm labour.","C":"Correct selection.","D":"Incorrect because racing car components are durable engineered parts, not perishable raw materials."}}},{"id":"P1_U4_MCQ_112","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_112","question":"A biotechnology company plans to open a new laboratory and pharmaceutical production plant requiring 180 graduate chemists and lab technicians. Which location would be most suitable?","options":{"A":"A remote island with no schools, colleges, or transport links","B":"A rural farming village where workers only have agricultural experience","C":"A congested shopping mall with no laboratory facilities","D":"Close to leading universities and technical colleges that train science graduates"},"correctOption":"D","correctAnswer":"Close to leading universities and technical colleges that train science graduates","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when a business needs labour with specialist skills, locating near universities or training colleges makes recruiting qualified staff much easier.","distractor_reasons":{"A":"Incorrect because an isolated island would lack skilled science graduates and transport infrastructure.","B":"Incorrect because agricultural villages lack a pool of trained chemists and lab technicians.","C":"Incorrect because shopping malls are designed for retail services rather than pharmaceutical laboratories.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_113","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_113","question":"A domestic appliance manufacturer is offered a $3 million non-repayable government grant and subsidised factory premises if it builds its new assembly plant in a region with high unemployment. Which location factor is influencing the business?","options":{"A":"Government financial incentives aimed at creating jobs in deprived areas","B":"Personal preference of customers for remote factories","C":"Strict environmental laws banning factories in high-unemployment zones","D":"Higher wage rates in high-unemployment regions"},"correctOption":"A","correctAnswer":"Government financial incentives aimed at creating jobs in deprived areas","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because governments frequently offer state-funded grants and low-cost premises to encourage manufacturers to locate and create jobs in areas of high unemployment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because consumers rarely care where washing machines are assembled; the driver here is the government grant.","C":"Incorrect because the government is encouraging rather than banning factory construction in this region.","D":"Incorrect because areas of high unemployment typically have lower, not higher, wage rates."}}},{"id":"P1_U4_MCQ_114","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_114","question":"A chemical fertiliser company is refused planning permission by government authorities to build a new factory beside a protected coastal wildlife reserve and tourist beach. Why did government controls prevent this location choice?","options":{"A":"To force the company to increase its pollution emissions","B":"To preserve areas of natural beauty and prevent pollution risks to the environment and tourism","C":"To ensure the company pays higher rent in the city centre","D":"Because chemical factories are required to locate inside national parks"},"correctOption":"B","correctAnswer":"To preserve areas of natural beauty and prevent pollution risks to the environment and tourism","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because governments use planning laws and controls to prevent polluting or noisy factories from locating in areas of natural beauty or tourist destinations.","distractor_reasons":{"A":"Incorrect because government controls aim to reduce rather than increase pollution.","B":"Correct selection.","C":"Incorrect because the purpose of environmental zoning is protecting nature and communities, not raising company rent.","D":"Incorrect because polluting industries are banned from national parks, not required to locate there."}}},{"id":"P1_U4_MCQ_115","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_115","question":"A sofa manufacturer considers locating in a remote rural area where land rent is 65% cheaper than near its main urban market, but finds motorway connections are poor and 500 km away from customers. What risk does the business face if it selects the rural site?","options":{"A":"Land purchase prices will be higher than in the city centre","B":"Local government will ban rural furniture workshops","C":"Higher transport costs for raw materials and bulky finished sofas could outweigh the savings in rent","D":"Customers will visit the rural factory daily to buy single cushions"},"correctOption":"C","correctAnswer":"Higher transport costs for raw materials and bulky finished sofas could outweigh the savings in rent","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because while land and rent costs are lower in remote areas, high transport costs for bulky finished products and materials can cancel out the rent savings.","distractor_reasons":{"A":"Incorrect because remote rural land is cheaper, not more expensive, than urban land.","B":"Incorrect because there is no general ban on rural workshops; the core issue is the rent-versus-transport trade-off.","C":"Correct selection.","D":"Incorrect because a sofa manufacturer distributes to retail stores rather than relying on walk-in footfall."}}},{"id":"P1_U4_MCQ_116","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_116","question":"A new hairdressing salon and coffee bar are choosing between a high-rent unit on a busy shopping street and a cheap warehouse on an out-of-town industrial estate. Why should they choose the shopping street despite higher rent?","options":{"A":"Service businesses need large areas of flat land for flow production","B":"Industrial estates have too many passing shoppers","C":"High-street shops never have to pay local business taxes","D":"Service businesses requiring direct personal contact must locate where customer footfall and access are high"},"correctOption":"D","correctAnswer":"Service businesses requiring direct personal contact must locate where customer footfall and access are high","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because service businesses that deliver face-to-face services (such as hairdressers, cafes, and shops) must be located conveniently close to customers.","distractor_reasons":{"A":"Incorrect because hairdressers and cafes provide personal services rather than operating large flow-production factories.","B":"Incorrect because industrial estates have very low pedestrian footfall compared to shopping streets.","C":"Incorrect because high-street premises typically face higher rent and local taxes, which are justified by higher sales revenue.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_117","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_117","question":"A national insurance company relocates its 400-person customer telephone and online claims centre from an expensive capital city to a smaller town with fast internet infrastructure and lower office rents. How has technology influenced this service location decision?","options":{"A":"IT and telecommunications allow service businesses without face-to-face contact to locate in lower-cost areas","B":"Insurance customers now prefer visiting physical call centres in small towns","C":"Fast internet eliminates the need to employ any customer service staff","D":"Capital cities no longer have telephone or internet networks"},"correctOption":"A","correctAnswer":"IT and telecommunications allow service businesses without face-to-face contact to locate in lower-cost areas","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because modern IT and telecommunications enable service operations like call centres and online banking to serve customers anywhere while locating in low-rent, low-wage regions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because call centre and online customers interact remotely rather than visiting the building in person.","C":"Incorrect because the company is relocating 400 employees rather than eliminating all staff.","D":"Incorrect because capital cities have extensive networks, but high rents make relocating remote services profitable."}}},{"id":"P1_U4_MCQ_118","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_118","question":"A commercial accounting firm and an IT consultancy rent offices in the central financial district of a major city alongside major banks and corporate headquarters. Why is locating near other businesses beneficial for these service providers?","options":{"A":"It reduces the weight of raw materials transported to their offices","B":"They are close to corporate clients and supporting business services","C":"Office rents in central financial districts are the lowest in the country","D":"It allows them to operate 24-hour automated assembly lines"},"correctOption":"B","correctAnswer":"They are close to corporate clients and supporting business services","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because business-to-business service providers benefit from locating near corporate clients and supporting services such as banks and specialist firms.","distractor_reasons":{"A":"Incorrect because accounting and IT firms provide intangible services rather than processing heavy raw materials.","B":"Correct selection.","C":"Incorrect because central financial districts have the highest, not lowest, office rents.","D":"Incorrect because professional service firms do not operate physical manufacturing assembly lines."}}},{"id":"P1_U4_MCQ_119","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_119","question":"An international hospitality group invests $80 million to build a luxury beachfront resort and diving centre on a tropical island with warm weather all year round. Which location factor is most important for this service business?","options":{"A":"Proximity to coal mines and steel mills","B":"Availability of heavy railway freight terminals","C":"Favourable climate and natural attractions for holidaymakers","D":"Strict government bans on foreign tourists"},"correctOption":"C","correctAnswer":"Favourable climate and natural attractions for holidaymakers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because climate is a decisive location factor for tourism and hospitality businesses such as holiday resorts and hotels.","distractor_reasons":{"A":"Incorrect because heavy mining and steel industries would deter tourists rather than attract them.","B":"Incorrect because island resorts rely on passenger airports and ferry links rather than heavy freight railways.","C":"Correct selection.","D":"Incorrect because bans on tourists would prevent a holiday resort from operating."}}},{"id":"P1_U4_MCQ_120","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_120","question":"A self-employed web designer sets up her studio in a quiet lakeside town where she grew up so she can live near her family and walk to work. Which location factor determined this choice?","options":{"A":"Bulk-reducing raw materials","B":"Government enterprise zone grants","C":"Proximity to heavy shipping ports","D":"Personal preference of the business owner"},"correctOption":"D","correctAnswer":"Personal preference of the business owner","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because small service-business owners who are not tied to specific physical resources often choose locations based on personal lifestyle and family preferences.","distractor_reasons":{"A":"Incorrect because a web designer provides digital services and uses no heavy raw materials.","B":"Incorrect because the scenario highlights family ties and lifestyle rather than government financial grants.","C":"Incorrect because web design is delivered online without needing maritime shipping ports.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_121","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_121","question":"A South Korean car manufacturer builds an assembly factory inside the European Union so its vehicles can be sold to European buyers without paying import taxes. Which reason for locating operations in another country does this illustrate?","options":{"A":"Avoiding import tariffs and trade barriers by producing inside a trade bloc","B":"Paying higher hourly wage rates than in South Korea","C":"Increasing shipping distances to European dealerships","D":"Avoiding all European safety and environmental regulations"},"correctOption":"A","correctAnswer":"Avoiding import tariffs and trade barriers by producing inside a trade bloc","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because locating a factory inside a foreign country or trade bloc allows a business to bypass import tariffs and quotas on imported goods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses seek lower rather than higher wage costs when expanding internationally.","C":"Incorrect because building inside Europe shortens rather than increases shipping distances to European buyers.","D":"Incorrect because factories operating inside the EU must still comply fully with EU safety and environmental laws."}}},{"id":"P1_U4_MCQ_122","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_122","question":"A European sportswear brand relocates its labour-intensive garment stitching plants to a developing country in Southeast Asia where factory wages are 70% lower. What is the main operational advantage of this international location decision?","options":{"A":"Elimination of all shipping times back to European stores","B":"Significantly lower labour costs, reducing average production costs per garment","C":"Higher corporate tax rates in the host country","D":"Greater ease of face-to-face communication with European head-office managers"},"correctOption":"B","correctAnswer":"Significantly lower labour costs, reducing average production costs per garment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because labour-intensive manufacturers frequently locate in countries with lower wage rates to substantially reduce unit labour costs and remain price-competitive.","distractor_reasons":{"A":"Incorrect because shipping garments from Southeast Asia to Europe increases rather than eliminates shipping times.","B":"Correct selection.","C":"Incorrect because businesses prefer lower, not higher, tax rates when choosing international locations.","D":"Incorrect because distance, time zones, and language differences make communication harder rather than easier."}}},{"id":"P1_U4_MCQ_123","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_123","question":"A German manufacturer of heavy agricultural tractors opens a new assembly plant in Brazil to serve growing farm demand across South America. Besides accessing a large new market, what operational benefit does this provide?","options":{"A":"Higher import tariffs on tractors sold in South America","B":"Increased reliance on shipping heavy tractors across the Atlantic Ocean","C":"Lower transport costs and faster delivery times to South American customers","D":"Complete elimination of cultural and language differences"},"correctOption":"C","correctAnswer":"Lower transport costs and faster delivery times to South American customers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because manufacturing heavy machinery inside the target overseas region avoids expensive transoceanic freight costs and speeds up delivery to local buyers.","distractor_reasons":{"A":"Incorrect because producing locally reduces or avoids import tariffs rather than increasing them.","B":"Incorrect because local assembly reduces the need to ship finished heavy tractors across the ocean.","C":"Correct selection.","D":"Incorrect because operating in a new country still requires managing cultural and language differences."}}},{"id":"P1_U4_MCQ_124","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_124","question":"A British food manufacturer opens a processing plant in another country without researching local employment laws or translating safety manuals into the local language, resulting in accidents and government fines. Which drawback of locating abroad does this highlight?","options":{"A":"Excessive government grants in the host country","B":"Too many bulk-buying discounts from local suppliers","C":"Zero transport costs between countries","D":"Lack of knowledge of local laws alongside language and cultural barriers"},"correctOption":"D","correctAnswer":"Lack of knowledge of local laws alongside language and cultural barriers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because operating in another country exposes businesses to unfamiliar legal requirements as well as language and communication barriers.","distractor_reasons":{"A":"Incorrect because government grants are an advantage of international location, not a cause of legal fines.","B":"Incorrect because bulk-buying discounts lower costs rather than causing safety accidents.","C":"Incorrect because international operations typically involve higher, not zero, transport costs.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_125","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_125","question":"A clothing retailer moves production to an overseas factory with weak safety enforcement, leading to media reports of poor worker conditions and high rates of faulty stitching. Which two risks of locating operations in another country are shown here?","options":{"A":"Damage to brand reputation from ethical concerns and difficulty maintaining consistent quality standards","B":"Higher domestic wage rates and lower import quotas","C":"Excessive automation and lack of customer demand","D":"Lower transport costs and stronger employee loyalty"},"correctOption":"A","correctAnswer":"Damage to brand reputation from ethical concerns and difficulty maintaining consistent quality standards","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because locating in countries with weak regulations can create ethical scandals that harm brand image while distance makes monitoring product quality harder.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the problems described are worker welfare publicity and defective stitching, not domestic wages.","C":"Incorrect because the scenario involves poor working conditions and quality failures rather than excessive automation.","D":"Incorrect because negative media publicity harms brand image and employee morale rather than improving them."}}},{"id":"P1_U4_MCQ_126","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_126","question":"A furniture workshop purchases raw timber, employs skilled carpenters, and uses electric saws to manufacture finished oak dining tables that sell for four times the cost of the raw materials. Which core function of operations management does this illustrate?","options":{"A":"Managing inputs to produce outputs while adding value","B":"Conducting primary market research among competitors","C":"Issuing new ordinary shares on a stock exchange","D":"Setting national interest rates to control inflation"},"correctOption":"A","correctAnswer":"Managing inputs to produce outputs while adding value","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because operations management transforms inputs (land, labour, capital) into finished goods and services while adding value so outputs can be sold profitably.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because conducting market research is a marketing function rather than an operations management process.","C":"Incorrect because raising share capital is a corporate finance activity.","D":"Incorrect because setting interest rates is a macroeconomic responsibility of a central bank."}}},{"id":"P1_U4_MCQ_127","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_127","question":"A telecommunications call centre employs 25 customer service agents who handle a combined total of 1,500 customer enquiries during an 8-hour shift. What is the daily labour productivity of this call centre?","options":{"A":"1,500 enquiries per day","B":"60 enquiries per agent","C":"200 enquiries per agent","D":"37,500 enquiries per day"},"correctOption":"B","correctAnswer":"60 enquiries per agent","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because labour productivity is calculated by dividing total output (1,500 enquiries) by the number of employees (25 agents), which equals 60 enquiries per agent.","distractor_reasons":{"A":"Incorrect because 1,500 enquiries is the total level of production (output), not output per employee.","B":"Correct selection.","C":"Incorrect because 200 divides 1,500 by 7.5 instead of dividing by the 25 agents employed.","D":"Incorrect because this multiplies output by the number of agents rather than dividing output by agents."}}},{"id":"P1_U4_MCQ_128","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_128","question":"A cardboard box factory wants to increase its labour productivity without hiring any extra production workers. Which action is most likely to achieve this goal?","options":{"A":"Increasing the selling price of cardboard boxes by 15%","B":"Spending more on television advertising campaigns","C":"Providing specialist machinery training and introducing performance-related bonuses","D":"Holding larger inventories of finished boxes in the warehouse"},"correctOption":"C","correctAnswer":"Providing specialist machinery training and introducing performance-related bonuses","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because training improves worker skill and speed while financial bonuses motivate higher effort, increasing output per employee.","distractor_reasons":{"A":"Incorrect because raising selling prices affects revenue rather than the physical output produced per worker.","B":"Incorrect because advertising promotes sales demand rather than improving production efficiency per worker.","C":"Correct selection.","D":"Incorrect because storing more unsold boxes increases inventory costs without raising output per worker."}}},{"id":"P1_U4_MCQ_129","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_129","question":"An electronics manufacturer introduces lean production methods across its assembly plants. What is the primary objective of lean production?","options":{"A":"To maximize the amount of buffer inventory stored in case of delays","B":"To increase the number of supervisors checking workers on the factory floor","C":"To switch from flow production to bespoke job production","D":"To cut down on waste and increase efficiency while maintaining product quality"},"correctOption":"D","correctAnswer":"To cut down on waste and increase efficiency while maintaining product quality","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because lean production covers techniques designed to eliminate wasted time, materials, and space while maintaining high quality.","distractor_reasons":{"A":"Incorrect because lean production aims to minimize or eliminate inventory rather than maximize buffer stock.","B":"Incorrect because lean production empowers workers through teamwork rather than adding extra layers of supervision.","C":"Incorrect because lean production can be applied to any production method and does not require switching to job production.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_130","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_130","question":"At a bicycle assembly plant, painted frames sit idle for two hours between the paint shop and the wheel-fitting station because the wheel team works slower than the painters. Which type of lean production waste does this represent?","options":{"A":"Waiting","B":"Over-processing","C":"Non-utilised skills","D":"Motion"},"correctOption":"A","correctAnswer":"Waiting","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because waiting waste occurs when goods or workers sit idle between stages of the production process instead of flowing smoothly.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because over-processing involves performing unnecessary operations or using overly complex machinery.","C":"Incorrect because non-utilised skills occur when qualified staff are given simple tasks below their capability.","D":"Incorrect because motion waste refers to unnecessary physical bending, stretching, or walking by workers."}}},{"id":"P1_U4_MCQ_131","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_131","question":"A food manufacturer cooks sauces in one building, loads them onto lorries to be bottled in a second building 15 kilometres away, and then trucks them back to the first building for labelling. Which type of lean production waste is occurring?","options":{"A":"Defects","B":"Transportation","C":"Overproduction","D":"Non-utilised skills"},"correctOption":"B","correctAnswer":"Transportation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because moving materials or semi-finished goods unnecessarily between buildings or around a site is classified as waste of transportation.","distractor_reasons":{"A":"Incorrect because defects refer to faulty products that must be scrapped or reworked.","B":"Correct selection.","C":"Incorrect because overproduction means making more goods than customers have ordered.","D":"Incorrect because non-utilised skills refer to underusing employee qualifications and talents."}}},{"id":"P1_U4_MCQ_132","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_132","question":"A smartphone manufacturer discovers that 4% of assembled handsets have scratched glass screens caused by rough handling on the conveyor belt, forcing technicians to disassemble and replace the screens. Which type of lean production waste is this?","options":{"A":"Overproduction","B":"Waiting","C":"Defects","D":"Inventory"},"correctOption":"C","correctAnswer":"Defects","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because defects are faulty products that do not meet quality standards and waste time and money through scrapping or reworking.","distractor_reasons":{"A":"Incorrect because overproduction occurs when more phones are built than demanded by customers.","B":"Incorrect because waiting refers to idle time between production stages.","C":"Correct selection.","D":"Incorrect because inventory waste refers to holding excessive quantities of raw materials or finished goods."}}},{"id":"P1_U4_MCQ_133","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_133","question":"A washing machine manufacturer spends extra time and expensive paint applying a glossy finish to internal metal brackets that are completely hidden inside the machine and add no value for the customer. Which waste in lean production does this illustrate?","options":{"A":"Motion","B":"Transportation","C":"Waiting","D":"Over-processing"},"correctOption":"D","correctAnswer":"Over-processing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because over-processing involves performing unnecessary production steps or using overly complex methods that add no value to the customer.","distractor_reasons":{"A":"Incorrect because motion waste refers to unnecessary physical movements by workers.","B":"Incorrect because transportation waste refers to moving materials unnecessarily between locations.","C":"Incorrect because waiting waste refers to products or staff sitting idle between tasks.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_134","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_134","question":"A software company hires computer science graduates to write code, but assigns them to spend three hours every afternoon manually folding envelopes and sticking postage stamps on invoices. Which lean production waste is taking place?","options":{"A":"Non-utilised skills","B":"Overproduction","C":"Defects","D":"Inventory"},"correctOption":"A","correctAnswer":"Non-utilised skills","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because non-utilised skills occur when qualified, skilled employees are given routine tasks that do not make use of their abilities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because overproduction involves producing more goods than customers have ordered.","C":"Incorrect because defects refer to faulty outputs requiring repair or disposal.","D":"Incorrect because inventory waste refers to holding excess stock."}}},{"id":"P1_U4_MCQ_135","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_135","question":"A car parts distributor keeps $2 million worth of excess exhaust pipes sitting in a rented warehouse for over a year, tying up cash and risking rust damage. Which type of lean production waste does this represent?","options":{"A":"Motion","B":"Inventory","C":"Waiting","D":"Over-processing"},"correctOption":"B","correctAnswer":"Inventory","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because holding excessive inventory wastes warehouse space, ties up working capital, and increases the risk of damage or obsolescence.","distractor_reasons":{"A":"Incorrect because motion waste involves unnecessary worker movements during tasks.","B":"Correct selection.","C":"Incorrect because waiting waste refers to idle time between consecutive production operations.","D":"Incorrect because over-processing refers to unnecessary work performed on a product."}}},{"id":"P1_U4_MCQ_136","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_136","question":"Why does the Kaizen approach focus on many small, continuous improvements suggested by factory workers rather than occasional large changes imposed by senior managers?","options":{"A":"Small changes require expensive automated robotics from overseas","B":"Workers refuse to attend short weekly improvement meetings","C":"Frontline workers understand daily tasks best and low-cost ideas are implemented quickly without resistance","D":"Large changes never improve efficiency in manufacturing businesses"},"correctOption":"C","correctAnswer":"Frontline workers understand daily tasks best and low-cost ideas are implemented quickly without resistance","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because employees doing the daily jobs spot practical sources of waste easily, and involving them builds commitment without needing major capital spending.","distractor_reasons":{"A":"Incorrect because Kaizen specifically avoids relying on expensive capital equipment.","B":"Incorrect because Kaizen relies on regular small-group meetings where employees actively contribute ideas.","C":"Correct selection.","D":"Incorrect because large technological changes can improve efficiency, though they are costly and slower to implement than Kaizen."}}},{"id":"P1_U4_MCQ_137","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_137","question":"A laptop manufacturer wants to switch from holding large warehouse stocks to operating a just-in-time (JIT) inventory control system. Which condition is essential for this switch to succeed?","options":{"A":"Purchasing a much larger warehouse to store extra components","B":"Switching from flow production to bespoke job production","C":"Eliminating all information technology links with component suppliers","D":"Establishing close relationships with reliable suppliers who deliver exact quantities on time"},"correctOption":"D","correctAnswer":"Establishing close relationships with reliable suppliers who deliver exact quantities on time","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because JIT holds virtually zero buffer inventory, making reliable suppliers and accurate IT ordering essential to avoid halting production.","distractor_reasons":{"A":"Incorrect because JIT reduces or eliminates the need for warehouse storage space.","B":"Incorrect because JIT is most commonly used alongside flow or batch manufacturing rather than requiring job production.","C":"Incorrect because JIT requires strong IT links to automatically trigger frequent component deliveries.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_138","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_138","question":"Inside an electric car factory, accountants record the value of steel coils waiting to be pressed, half-assembled car chassis on the welding line, and completed cars parked outside awaiting delivery. Which three forms of inventory are being recorded?","options":{"A":"Raw materials, work-in-progress, and finished goods","B":"Fixed costs, variable costs, and average costs","C":"Job output, batch output, and flow output","D":"Land, labour, and enterprise"},"correctOption":"A","correctAnswer":"Raw materials, work-in-progress, and finished goods","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because business inventory takes three forms: raw materials/components, work-in-progress (partly finished goods), and finished goods ready for sale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fixed, variable, and average costs are classifications of business expenditure, not types of inventory.","C":"Incorrect because job, batch, and flow are methods of production, not forms of inventory.","D":"Incorrect because land, labour, and enterprise are factors of production."}}},{"id":"P1_U4_MCQ_139","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_139","question":"A bicycle manufacturer imports specialist gear systems by cargo ship from overseas, taking six weeks from placing an order to delivery at the factory. How does this long supplier lead time affect the manufacturer's inventory decision?","options":{"A":"It allows the factory to operate with zero buffer inventory","B":"It requires the factory to hold higher buffer inventory of gears to prevent production stoppages","C":"It eliminates all warehouse storage and insurance expenses","D":"It makes the gear systems perish within two days of arrival"},"correctOption":"B","correctAnswer":"It requires the factory to hold higher buffer inventory of gears to prevent production stoppages","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when supplier delivery lead times are long or uncertain, businesses must hold higher buffer inventory so production continues while waiting for shipments.","distractor_reasons":{"A":"Incorrect because a six-week shipping delay makes zero-buffer JIT extremely risky.","B":"Correct selection.","C":"Incorrect because holding higher buffer inventory increases warehouse storage and insurance costs.","D":"Incorrect because metal bicycle gears are durable components, not perishable food items."}}},{"id":"P1_U4_MCQ_140","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_140","question":"A city-centre fashion boutique pays extremely high commercial rent per square metre and has a tiny back storeroom. Which factor limits the amount of inventory this boutique can hold?","options":{"A":"High storage costs and limited warehouse space","B":"Excessive bulk-buying discounts from clothing suppliers","C":"Low labour productivity among sales assistants","D":"High capital-intensive automation in the shop"},"correctOption":"A","correctAnswer":"High storage costs and limited warehouse space","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because expensive rent and limited physical storage space restrict the volume of inventory a business can afford to hold.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because bulk discounts encourage holding more inventory, whereas space and rent constraints restrict it.","C":"Incorrect because sales assistant productivity does not determine physical storeroom capacity.","D":"Incorrect because a small fashion boutique is a labour-intensive retail service rather than an automated factory."}}},{"id":"P1_U4_MCQ_141","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_141","question":"A custom wedding dress designer makes each gown individually to match the bride's exact measurements and fabric choices. What is a major disadvantage of this job production method?","options":{"A":"Customers receive identical dresses with no personalisation","B":"Employees become bored doing the exact same repetitive task every minute","C":"Unit production costs are high due to skilled labour and inability to buy materials in bulk","D":"The business must invest millions in automated assembly lines"},"correctOption":"C","correctAnswer":"Unit production costs are high due to skilled labour and inability to buy materials in bulk","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because job production relies on highly skilled craftspeople and small material purchases per order, resulting in high average unit costs.","distractor_reasons":{"A":"Incorrect because job production provides maximum personalisation for each customer.","B":"Incorrect because repetitive boredom is a disadvantage of flow production, whereas job production is varied and skilled.","C":"Correct selection.","D":"Incorrect because job production is labour-intensive and uses general-purpose tools rather than expensive automated assembly lines."}}},{"id":"P1_U4_MCQ_142","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_142","question":"A cosmetics manufacturer produces batches of 3,000 bottles of lavender shampoo, cleans the mixing vats, and then produces batches of 3,000 bottles of citrus shampoo. What is a key advantage of batch production over job production for this business?","options":{"A":"Every single bottle is custom-mixed for an individual shopper","B":"It eliminates all downtime when switching between shampoo scents","C":"It requires zero semi-finished work-in-progress inventory","D":"It allows greater use of machinery and bulk purchasing, lowering unit costs while still offering variety"},"correctOption":"D","correctAnswer":"It allows greater use of machinery and bulk purchasing, lowering unit costs while still offering variety","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because batch production achieves lower unit costs than job production through larger material orders and specialized machinery while still offering product variety.","distractor_reasons":{"A":"Incorrect because individual customisation is a feature of job production, not batch production.","B":"Incorrect because batch production still incurs downtime when cleaning and resetting equipment between batches.","C":"Incorrect because batch production typically creates high work-in-progress inventory between stages.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_143","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_143","question":"A global manufacturer of standard AA alkaline batteries operates an automated production line producing 40,000 identical batteries every hour. What is the main financial advantage of this flow production method?","options":{"A":"Average cost per battery is very low due to high output and economies of scale","B":"Initial machinery setup costs are negligible","C":"Each battery can be customized to an individual buyer's voltage request","D":"The factory needs no electricity or maintenance technicians"},"correctOption":"A","correctAnswer":"Average cost per battery is very low due to high output and economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because flow production spreads high fixed capital costs over massive standardized output and gains purchasing economies, achieving the lowest unit costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because flow production requires very high initial capital investment in specialized machinery.","C":"Incorrect because flow production manufactures identical, standardized goods rather than bespoke items.","D":"Incorrect because automated flow lines require substantial electrical power and skilled maintenance engineers."}}},{"id":"P1_U4_MCQ_144","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_144","question":"A mid-market clothing brand sells seasonal summer dresses in five colours and four sizes where consumer tastes change every few months. Which production method is most appropriate for this business?","options":{"A":"Flow production, because identical dresses can be made continuously for five years","B":"Batch production, because it allows flexible production runs of different sizes and colours without excessive unsold stock","C":"Job production, because mass-market high-street shoppers pay bespoke couture prices","D":"Capital-intensive heavy steel smelting"},"correctOption":"B","correctAnswer":"Batch production, because it allows flexible production runs of different sizes and colours without excessive unsold stock","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because batch production suits seasonal clothing where businesses need groups of different sizes and colours and must adapt quickly to changing fashions.","distractor_reasons":{"A":"Incorrect because continuous flow production of one unchanging design would leave the brand stuck with outdated fashion stock.","B":"Correct selection.","C":"Incorrect because job production would make mid-market summer dresses far too expensive for high-street customers.","D":"Incorrect because steel smelting is unrelated to clothing manufacturing."}}},{"id":"P1_U4_MCQ_145","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_145","question":"A civil engineering firm wins a government contract to design and construct a unique suspension bridge across a wide river gorge with specific geological conditions. Which method of production will be used?","options":{"A":"Flow production","B":"Batch production","C":"Job production","D":"Just-in-time retail distribution"},"correctOption":"C","correctAnswer":"Job production","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because large one-off construction projects such as bridges, ships, and custom buildings are built to unique client specifications using job production.","distractor_reasons":{"A":"Incorrect because flow production mass-produces identical standardized items on a factory line.","B":"Incorrect because batch production makes groups of identical products rather than a single bespoke bridge.","C":"Correct selection.","D":"Incorrect because retail distribution moves consumer goods to shops rather than constructing civil engineering projects."}}},{"id":"P1_U4_MCQ_146","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_146","question":"A pharmaceutical manufacturer operating in Germany, where factory wage rates are high, invests in automated tablet-pressing and blister-packing machines operated by a small team of technicians. Why is capital-intensive production chosen here?","options":{"A":"Because labour costs are high and automated machinery ensures high precision, hygiene, and lower unit costs","B":"Because automated machinery is free to purchase and requires no maintenance","C":"Because pharmaceutical tablets are made using bespoke job production","D":"Because Germany has a shortage of electricity and modern factories"},"correctOption":"A","correctAnswer":"Because labour costs are high and automated machinery ensures high precision, hygiene, and lower unit costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because in high-wage economies, capital-intensive automation reduces expensive labour costs per unit while guaranteeing strict pharmaceutical hygiene and accuracy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because automated pharmaceutical machinery requires substantial capital investment and regular maintenance.","C":"Incorrect because standard medicinal tablets are mass-produced via batch or flow production, not bespoke job production.","D":"Incorrect because capital-intensive factories rely on reliable power infrastructure, which Germany possesses."}}},{"id":"P1_U4_MCQ_147","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_147","question":"A large e-commerce fulfilment centre deploys self-driving robotic trolleys that use sensors and central computers to navigate aisles and transport shelves to packing stations without human drivers. Which technology is this?","options":{"A":"Manual mechanisation","B":"Automation","C":"Electronic Point of Sale (EPOS)","D":"Job production"},"correctOption":"B","correctAnswer":"Automation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because automation uses computer-controlled equipment and robotics to perform tasks automatically without direct human operation.","distractor_reasons":{"A":"Incorrect because mechanisation uses machines that still require a human worker to steer or operate them directly.","B":"Correct selection.","C":"Incorrect because EPOS is a retail store checkout barcode system.","D":"Incorrect because job production creates single bespoke products for individual clients."}}},{"id":"P1_U4_MCQ_148","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_148","question":"An aerospace engineering firm uses Computer-Aided Design (CAD) software to test how a new aircraft wing shape responds to extreme wind speeds on a computer screen before building any physical parts. What is a major benefit of using CAD in this way?","options":{"A":"It manufactures the finished metal aircraft wings automatically in the factory","B":"It scans customer barcodes at airport duty-free shops","C":"It saves time and money by spotting design flaws digitally before expensive physical prototyping","D":"It eliminates the need to employ qualified aerospace engineers"},"correctOption":"C","correctAnswer":"It saves time and money by spotting design flaws digitally before expensive physical prototyping","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because CAD allows engineers to simulate, test, and modify product designs digitally, avoiding the high cost and delay of building flawed physical prototypes.","distractor_reasons":{"A":"Incorrect because physical manufacturing by computer-controlled machinery is CAM, whereas CAD is design software.","B":"Incorrect because retail checkout scanning is EPOS.","C":"Correct selection.","D":"Incorrect because skilled engineers are still essential to create and interpret CAD simulations."}}},{"id":"P1_U4_MCQ_149","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_149","question":"A kitchen cabinet maker uses Computer-Aided Manufacturing (CAM) routers controlled directly by digital design files to cut wooden panels to millimetre accuracy. How does CAM improve operations?","options":{"A":"It allows customers to pay using contactless wristbands","B":"It increases wood wastage because computers cut slower than hand saws","C":"It answers customer emails automatically using artificial intelligence","D":"It reduces human cutting errors, lowers material scrap, and speeds up production"},"correctOption":"D","correctAnswer":"It reduces human cutting errors, lowers material scrap, and speeds up production","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because CAM executes digital cutting instructions with consistent precision, minimizing human mistakes, reducing timber waste, and increasing speed.","distractor_reasons":{"A":"Incorrect because contactless payment is a retail checkout technology, not a manufacturing router.","B":"Incorrect because CAM cuts faster and far more accurately than hand tools, reducing wood wastage.","C":"Incorrect because answering customer queries is done by AI chatbots, not CAM cutting machines.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_150","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_150","question":"When a consumer electronics firm integrates Computer-Aided Design (CAD) directly with Computer-Aided Manufacturing (CAM), engineers can send updated smartphone casing designs straight to factory milling machines within minutes. What competitive advantage does this create?","options":{"A":"Faster development and launch of new or updated products in response to changing market trends","B":"Complete elimination of electricity costs in the factory","C":"Ability to operate without any computer hardware or software","D":"Guaranteed protection against all foreign competitors"},"correctOption":"A","correctAnswer":"Faster development and launch of new or updated products in response to changing market trends","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because linking CAD directly to CAM drastically shortens product development cycles, enabling the firm to bring new designs to market ahead of rivals.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because running CAD workstations and CAM machinery consumes electricity.","C":"Incorrect because CAD/CAM integration depends entirely on computer hardware and software.","D":"Incorrect because speed to market improves competitiveness but does not prevent foreign rivals from competing."}}},{"id":"P1_U4_MCQ_151","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_151","question":"A dental laboratory scans a patient's teeth digitally and uses a 3D printer to build a custom-fitted ceramic crown in two hours rather than sculpting it by hand over several days. Which advantage of 3D printing does this show?","options":{"A":"Fast, accurate production of bespoke items without needing skilled manual sculpting","B":"Ability to mass-produce millions of identical crowns per minute","C":"Zero cost for digital scanning equipment and ceramic resin","D":"Automatic delivery of the crown to the patient's home"},"correctOption":"A","correctAnswer":"Fast, accurate production of bespoke items without needing skilled manual sculpting","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 3D printing creates complex, customized physical objects directly from digital files quickly and without traditional manual craft labour.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 3D printing builds layers relatively slowly per item and is suited to prototypes or bespoke parts rather than millions per minute.","C":"Incorrect because 3D printers, scanners, and printing resins involve significant equipment and material costs.","D":"Incorrect because 3D printing manufactures the physical item; logistics still handles delivery."}}},{"id":"P1_U4_MCQ_152","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_152","question":"A toy company uses 3D printing to create five sample action figures for market research, but switches to traditional steel injection-moulding machines to manufacture 2 million identical toys for retail sale. Why is 3D printing not used for the mass-production run?","options":{"A":"3D printers cannot produce plastic objects","B":"3D printing is too slow per unit compared with high-speed flow-production moulding for millions of identical items","C":"3D printing is illegal for commercial toy manufacturing","D":"Injection moulding produces a different unique toy every time"},"correctOption":"B","correctAnswer":"3D printing is too slow per unit compared with high-speed flow-production moulding for millions of identical items","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because while 3D printing excels at rapid prototyping and bespoke items, its layer-by-layer process is much slower per unit than traditional mass-production machinery.","distractor_reasons":{"A":"Incorrect because plastics and polymers are the most common materials used in 3D printing.","B":"Correct selection.","C":"Incorrect because there is no law banning 3D printing for toys.","D":"Incorrect because injection moulding produces millions of identical standardized units."}}},{"id":"P1_U4_MCQ_153","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_153","question":"A supermarket chain analyses daily data from its Electronic Point of Sale (EPOS) checkout scanners and notices that umbrella sales surge immediately whenever rain is forecast. How does EPOS help operations managers?","options":{"A":"By automatically manufacturing umbrellas in the back of the supermarket","B":"By providing real-time sales data so inventory can be restocked accurately before shelves empty","C":"By eliminating the need for delivery trucks between warehouses and stores","D":"By allowing customers to take groceries without paying"},"correctOption":"B","correctAnswer":"By providing real-time sales data so inventory can be restocked accurately before shelves empty","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because EPOS records exact item-by-item sales in real time, enabling managers to monitor demand trends and reorder stock automatically.","distractor_reasons":{"A":"Incorrect because supermarkets are retailers that order goods from suppliers rather than manufacturing umbrellas.","B":"Correct selection.","C":"Incorrect because physical goods still must be transported by delivery trucks to replenish stores.","D":"Incorrect because EPOS calculates the total bill so customers pay accurately at the checkout."}}},{"id":"P1_U4_MCQ_154","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_154","question":"During a 15-minute half-time break at a football stadium, refreshment kiosks accept only contactless card and mobile-wallet payments. Why does this technology improve service operations during peak demand?","options":{"A":"It eliminates the need to cook or prepare food before half-time","B":"It increases the amount of physical coins and banknotes stored in tills","C":"It speeds up checkout queues so more fans are served in 15 minutes and reduces cash-handling errors","D":"It forces customers to fill out paper forms before buying drinks"},"correctOption":"C","correctAnswer":"It speeds up checkout queues so more fans are served in 15 minutes and reduces cash-handling errors","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because contactless payments take seconds, greatly increasing customer throughput during short peak intervals while removing cash-counting delays and theft risks.","distractor_reasons":{"A":"Incorrect because food still must be prepared in advance; contactless technology speeds up the payment transaction.","B":"Incorrect because cashless contactless systems eliminate rather than increase physical cash in tills.","C":"Correct selection.","D":"Incorrect because contactless payment requires only tapping a card or phone, with no paperwork."}}},{"id":"P1_U4_MCQ_155","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_155","question":"A bottling factory installs artificial intelligence (AI) software that analyses vibration and temperature data from conveyor motors to predict when a bearing will fail, allowing engineers to replace it during scheduled weekend maintenance. What benefit does this AI application provide?","options":{"A":"It prevents unexpected mid-week breakdowns that would halt the entire production line","B":"It eliminates the need to employ any maintenance engineers","C":"It replaces glass bottles with biodegradable paper bags","D":"It reduces the factory's fixed rent payments"},"correctOption":"A","correctAnswer":"It prevents unexpected mid-week breakdowns that would halt the entire production line","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because AI predictive maintenance detects early signs of equipment wear before a breakdown occurs, avoiding costly unplanned production stoppages.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because maintenance engineers are still required to physically replace the worn parts.","C":"Incorrect because predictive maintenance monitors machinery health rather than changing product packaging.","D":"Incorrect because equipment monitoring software does not change property lease agreements."}}},{"id":"P1_U4_MCQ_156","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_156","question":"A parcel delivery company relies entirely on an automated AI chatbot for customer service, leaving customers whose urgent medical packages were lost unable to reach a human adviser. What limitation of AI customer service technology does this highlight?","options":{"A":"AI chatbots cannot operate outside normal office hours","B":"AI chatbots struggle with complex, urgent, or sensitive problems that require human judgement and empathy","C":"AI chatbots cost more per hour in wages than call-centre employees","D":"AI chatbots physically deliver parcels to the wrong addresses"},"correctOption":"B","correctAnswer":"AI chatbots struggle with complex, urgent, or sensitive problems that require human judgement and empathy","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because while AI handles routine queries well, complex or emotionally sensitive issues require human empathy and flexible problem-solving to retain customer trust.","distractor_reasons":{"A":"Incorrect because a major advantage of AI chatbots is that they operate 24/7.","B":"Correct selection.","C":"Incorrect because AI chatbots reduce wage costs compared with employing human staff.","D":"Incorrect because chatbots handle online customer communication, not physical van driving."}}},{"id":"P1_U4_MCQ_157","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_157","question":"An automotive supplier adopts automated welding and laser inspection technology, lowering its defect rate to near zero and cutting average cost per component by 22%. How does this strengthen the business's market position?","options":{"A":"It allows the firm to offer lower prices or earn higher profit margins while winning contracts through superior quality","B":"It guarantees that competitors will exit the industry immediately","C":"It eliminates the need to sign supply contracts with car manufacturers","D":"It allows the firm to stop training its technical workforce"},"correctOption":"A","correctAnswer":"It allows the firm to offer lower prices or earn higher profit margins while winning contracts through superior quality","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lower unit costs combined with higher, consistent quality make the business more competitive on both price and reliability.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because rivals may also invest in technology rather than exiting immediately.","C":"Incorrect because business-to-business suppliers still negotiate formal contracts with vehicle manufacturers.","D":"Incorrect because automated equipment requires ongoing technical training for operators and engineers."}}},{"id":"P1_U4_MCQ_158","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_158","question":"A multinational clothing retailer uses cloud-based inventory and design software linking its London design studio, Vietnamese factories, and 300 global stores in real time. How does this information technology benefit operations?","options":{"A":"It eliminates ocean shipping times between Vietnam and London","B":"It speeds up communication and improves co-ordination across global design, manufacturing, and retail teams","C":"It removes the need for quality checks in overseas factories","D":"It ensures clothing fashions never change from season to season"},"correctOption":"B","correctAnswer":"It speeds up communication and improves co-ordination across global design, manufacturing, and retail teams","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because modern IT networks enable instant sharing of design updates, production schedules, and store sales data across distant locations.","distractor_reasons":{"A":"Incorrect because digital software transmits data instantly, not physical garments.","B":"Correct selection.","C":"Incorrect because physical clothing items still require quality inspection.","D":"Incorrect because consumer fashion tastes still change, though IT helps the business respond faster."}}},{"id":"P1_U4_MCQ_159","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_159","question":"A commercial printing company buys expensive digital presses, but within three years rivals adopt faster, higher-resolution machines that make the company's presses outdated. Which disadvantage of technology does this illustrate?","options":{"A":"Rapid technological change can quickly make expensive equipment obsolete, requiring further capital investment","B":"Digital printing presses always produce lower quality than hand-carved wooden blocks","C":"Employees prefer using outdated machines that break down frequently","D":"Governments ban printing businesses from upgrading equipment"},"correctOption":"A","correctAnswer":"Rapid technological change can quickly make expensive equipment obsolete, requiring further capital investment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because technology evolves rapidly; equipment that is state-of-the-art today can soon become obsolete, forcing businesses to invest again to remain competitive.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because modern digital presses produce far higher speed and quality than manual printing methods.","C":"Incorrect because unreliable equipment frustrates employees and lowers productivity.","D":"Incorrect because governments encourage rather than ban technological upgrading."}}},{"id":"P1_U4_MCQ_160","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_160","question":"A logistics company whose automated warehouse sorting systems and delivery schedules are controlled by central servers suffers a cyberattack that locks its computer network for 48 hours. What operational risk of heavy reliance on technology does this show?","options":{"A":"Higher manual paperwork costs during normal operations","B":"Vulnerability to IT system failures or cyberattacks that can paralyse operations","C":"Excessive employee overtime from sorting parcels by hand every day","D":"Lower customer expectations for fast delivery"},"correctOption":"B","correctAnswer":"Vulnerability to IT system failures or cyberattacks that can paralyse operations","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when operations depend completely on integrated IT networks, technical crashes or cyberattacks can bring the entire business to a standstill.","distractor_reasons":{"A":"Incorrect because automated IT systems reduce paperwork during normal operation.","B":"Correct selection.","C":"Incorrect because automated systems sort parcels mechanically during normal operation.","D":"Incorrect because modern technology raises rather than lowers customer expectations for fast delivery."}}},{"id":"P1_U4_MCQ_161","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_161","question":"A beverage warehouse introduces automated pallet-lifting robots to stack heavy crates onto high shelving racks, replacing manual lifting by warehouse staff. How does this benefit employees?","options":{"A":"It increases back injuries and workplace accidents","B":"It reduces physical strain and improves workplace health and safety","C":"It forces every warehouse worker to work 14-hour shifts","D":"It eliminates all breaks during the working day"},"correctOption":"B","correctAnswer":"It reduces physical strain and improves workplace health and safety","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because automating heavy lifting and hazardous tasks protects workers from musculoskeletal injuries and creates a safer working environment.","distractor_reasons":{"A":"Incorrect because robotic lifting reduces rather than increases physical back injuries.","B":"Correct selection.","C":"Incorrect because automation reduces physical workload and does not impose illegal shift lengths.","D":"Incorrect because employment laws still require regular rest breaks for staff."}}},{"id":"P1_U4_MCQ_162","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_162","question":"When a car parts factory introduces computer-controlled CNC machines, several assembly operators are sponsored by the company to complete college courses in robotics programming and maintenance. How does this benefit those employees?","options":{"A":"They gain valuable technical skills that improve their employability and promotion prospects","B":"They receive lower hourly pay after becoming qualified technicians","C":"They are guaranteed never to work with computers again","D":"They avoid all responsibility for product quality"},"correctOption":"A","correctAnswer":"They gain valuable technical skills that improve their employability and promotion prospects","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because employer-funded technical training upgrades employee skills, leading to higher earning potential and stronger career prospects.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because skilled technical roles typically pay higher, not lower, wages than unskilled assembly work.","C":"Incorrect because CNC programming and maintenance directly involve working with computer systems.","D":"Incorrect because technical operators play an important role in maintaining quality standards."}}},{"id":"P1_U4_MCQ_163","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_163","question":"An insurance company introduces automated document-scanning and AI claims-processing software, reducing its administrative data-entry workforce from 120 clerks to 25 specialists. Which negative impact on employees does this represent?","options":{"A":"Excessive physical lifting injuries in the office","B":"Redundancy and job losses for employees performing routine clerical tasks","C":"Higher job security for unskilled data-entry clerks","D":"Increased boredom from manually typing paper forms all day"},"correctOption":"B","correctAnswer":"Redundancy and job losses for employees performing routine clerical tasks","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because automation in offices and factories frequently replaces routine, repetitive roles, causing redundancies among displaced workers.","distractor_reasons":{"A":"Incorrect because office data-entry clerks do not perform heavy physical lifting.","B":"Correct selection.","C":"Incorrect because automation reduced the clerical workforce by 95 jobs, lowering job security.","D":"Incorrect because the software took over manual data entry rather than increasing it."}}},{"id":"P1_U4_MCQ_164","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_164","question":"A hospital introduces a new electronic patient-record system, and many experienced nurses report feeling stressed and frustrated because they were given only a brief manual and struggle to use the software during busy shifts. What problem does this show?","options":{"A":"New technology can cause employee stress and lower productivity if insufficient training and support are provided","B":"Electronic records always take up more physical filing cabinet space than paper folders","C":"Nurses no longer need to care for patients once computers are installed","D":"Paper records are faster to share between different hospital departments"},"correctOption":"A","correctAnswer":"New technology can cause employee stress and lower productivity if insufficient training and support are provided","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because introducing new IT systems without thorough practical training causes anxiety, errors, and resistance among employees.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because digital records save physical filing space rather than taking up more room.","C":"Incorrect because computers assist administrative record-keeping while nurses still provide direct patient care.","D":"Incorrect because electronic records are shared much faster across departments than physical paper files."}}},{"id":"P1_U4_MCQ_165","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_165","question":"A supermarket replaces half of its staffed checkout lanes with self-service scanning machines, lowering wage costs but causing queues when machines repeatedly flash 'unexpected item in bagging area' and require staff intervention. What does this illustrate?","options":{"A":"Service-sector technology can save labour costs, but technical glitches or poor usability can frustrate customers","B":"Self-service checkouts require zero electricity or software maintenance","C":"Customers prefer waiting 20 minutes for a malfunctioning machine over speaking to a cashier","D":"Supermarkets are legally required to remove all human cashiers"},"correctOption":"A","correctAnswer":"Service-sector technology can save labour costs, but technical glitches or poor usability can frustrate customers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because self-service technology reduces payroll expenses, but frequent system alerts and lack of human help can irritate shoppers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because self-service machines require continuous electrical power and IT maintenance.","C":"Incorrect because frustrating machine delays negatively affect customer satisfaction.","D":"Incorrect because no law requires supermarkets to eliminate human cashiers."}}},{"id":"P1_U4_MCQ_166","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_166","question":"An independent artisan chocolatier produces small batches of hand-painted truffles sold in luxury gift boxes at $45 per box. Why would installing a $500,000 automated chocolate-moulding line be a poor decision for this business?","options":{"A":"Automated lines cannot melt chocolate","B":"High capital costs cannot be recovered from small output volumes, and customers value hand-crafted uniqueness","C":"Luxury customers prefer cheap mass-produced supermarket chocolate","D":"Artisan chocolatiers are banned from using electricity"},"correctOption":"B","correctAnswer":"High capital costs cannot be recovered from small output volumes, and customers value hand-crafted uniqueness","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because expensive automation requires high output volume to lower unit costs and would destroy the handmade artisan appeal that justifies luxury pricing.","distractor_reasons":{"A":"Incorrect because industrial chocolate lines do melt and mould chocolate for mass-market brands.","B":"Correct selection.","C":"Incorrect because buyers paying $45 for gift truffles seek exclusivity and hand-crafted artistry.","D":"Incorrect because artisan kitchens use electrical appliances such as tempering machines and refrigerators."}}},{"id":"P1_U4_MCQ_167","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_167","question":"A bottling factory borrows $800,000 to buy automated filling machines, replacing 20 hourly-paid assembly workers. How does this technological investment alter the factory's cost structure?","options":{"A":"Both fixed costs and variable labour costs fall to zero","B":"Fixed costs fall while variable labour costs per bottle double","C":"Fixed costs increase due to machinery depreciation and loan interest, while variable labour costs per unit decrease","D":"Variable raw material costs disappear completely"},"correctOption":"C","correctAnswer":"Fixed costs increase due to machinery depreciation and loan interest, while variable labour costs per unit decrease","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because purchasing expensive equipment raises fixed costs (loan interest, depreciation), while replacing hourly workers lowers variable labour costs per unit produced.","distractor_reasons":{"A":"Incorrect because buying machinery adds substantial fixed costs rather than reducing them to zero.","B":"Incorrect because fixed costs rise and variable labour costs per unit fall, not the reverse.","C":"Correct selection.","D":"Incorrect because the factory still must purchase bottles, caps, and beverages as variable material costs."}}},{"id":"P1_U4_MCQ_168","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_168","question":"A forestry and paper company plants three new trees for every tree it harvests and uses closed-loop water treatment so river ecosystems remain unharmed. Which core principle of sustainability does this demonstrate?","options":{"A":"Maximizing short-term resource extraction regardless of environmental damage","B":"Meeting current production needs without compromising the ability of future generations to meet their needs","C":"Eliminating all fixed costs by avoiding environmental regulations","D":"Switching from renewable timber to non-renewable plastic packaging"},"correctOption":"B","correctAnswer":"Meeting current production needs without compromising the ability of future generations to meet their needs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sustainable production ensures natural resources and ecosystems are preserved so future generations can continue to use them.","distractor_reasons":{"A":"Incorrect because depleting resources without replanting is unsustainable.","B":"Correct selection.","C":"Incorrect because sustainable practices comply with environmental standards rather than avoiding them.","D":"Incorrect because plastic is made from non-renewable fossil fuels and creates pollution."}}},{"id":"P1_U4_MCQ_169","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_169","question":"An aluminium smelter locates near a fast-flowing mountain river to power its furnaces using electricity generated by a hydroelectric dam rather than a coal-fired power station. Why is hydroelectric power a sustainable energy choice?","options":{"A":"It relies on burning imported coal more slowly","B":"It is a renewable energy source replenished naturally by rainfall without emitting greenhouse gases during generation","C":"It requires zero initial construction cost to build a dam","D":"It uses up river water permanently so the river dries out"},"correctOption":"B","correctAnswer":"It is a renewable energy source replenished naturally by rainfall without emitting greenhouse gases during generation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because hydropower is a renewable energy source that generates electricity from flowing water without depleting fossil fuels or emitting carbon dioxide.","distractor_reasons":{"A":"Incorrect because hydroelectric dams use water flow, not coal.","B":"Correct selection.","C":"Incorrect because constructing hydroelectric facilities involves very high initial capital expenditure.","D":"Incorrect because water flows through turbines and continues downstream rather than being consumed."}}},{"id":"P1_U4_MCQ_170","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_170","question":"A steel rolling mill installs a closed-loop cooling system that filters, cools, and recirculates the same water continuously instead of drawing millions of litres of fresh river water every day. Which sustainable production method is this?","options":{"A":"Using fewer natural resources","B":"Using biodegradable packaging","C":"Switching to batch production","D":"Increasing labour-intensive production"},"correctOption":"A","correctAnswer":"Using fewer natural resources","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because recirculating cooling water drastically cuts the consumption of fresh natural water resources.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the closed-loop system conserves water during steel manufacturing rather than changing product packaging.","C":"Incorrect because batch production is an output organization method, not a water conservation technique.","D":"Incorrect because automated water filtration does not involve increasing manual labour."}}},{"id":"P1_U4_MCQ_171","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_171","question":"An accounting consultancy replaces printed client reports, paper invoices, and physical filing folders with secure digital PDF statements and cloud signatures, cutting paper consumption by 90%. Which sustainable practice does this illustrate?","options":{"A":"Creating less waste in service operations","B":"Installing solar panels on factory roofs","C":"Recycling scrap steel into car parts","D":"Switching from flow production to job production"},"correctOption":"A","correctAnswer":"Creating less waste in service operations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because eliminating unnecessary paper printing prevents solid waste and reduces demand for wood pulp.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the scenario describes paperless office practices rather than solar electricity generation.","C":"Incorrect because an accounting firm deals with office paper rather than scrap steel.","D":"Incorrect because job and flow production are manufacturing classifications."}}},{"id":"P1_U4_MCQ_172","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_172","question":"A supermarket chain delivers fresh fruit and vegetables to its stores in heavy-duty foldable plastic crates that are collected empty, washed, and used hundreds of times instead of disposable cardboard boxes. Which sustainability method is this?","options":{"A":"Recycling","B":"Reusing","C":"Quality control sampling","D":"Overproduction"},"correctOption":"B","correctAnswer":"Reusing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because reusing involves cleaning and using an item repeatedly for the same purpose without melting or reprocessing its material.","distractor_reasons":{"A":"Incorrect because recycling breaks down or melts used materials to make a new product, whereas these crates are simply folded, washed, and refilled.","B":"Correct selection.","C":"Incorrect because quality control tests products for defects.","D":"Incorrect because overproduction is a lean production waste."}}},{"id":"P1_U4_MCQ_173","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_173","question":"An outdoor apparel company collects used plastic drinking bottles, shreds them into flakes, melts them down, and spins the fibres into yarn to manufacture fleece jackets. Which sustainability method is being applied?","options":{"A":"Reusing","B":"Just-in-time inventory control","C":"Recycling","D":"Mechanisation"},"correctOption":"C","correctAnswer":"Recycling","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because recycling reprocesses waste materials (plastic bottles) into a completely different finished product (fleece jackets).","distractor_reasons":{"A":"Incorrect because reusing uses an item again in its original form without melting or reprocessing.","B":"Incorrect because JIT manages inventory delivery timing.","C":"Correct selection.","D":"Incorrect because mechanisation refers to assisting workers with machinery."}}},{"id":"P1_U4_MCQ_174","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_174","question":"A household cleaning company reformulates its laundry detergent using plant-based, phosphate-free ingredients that break down harmlessly in waterways after use. Which sustainable production method does this demonstrate?","options":{"A":"Developing environmentally friendly products","B":"Automating its warehouse with robotics","C":"Increasing fixed overhead costs through luxury branding","D":"Switching to coal-fired heating"},"correctOption":"A","correctAnswer":"Developing environmentally friendly products","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because designing non-toxic, biodegradable products made from renewable plant sources reduces environmental pollution.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the scenario focuses on product formulation rather than warehouse robotics.","C":"Incorrect because reformulating detergent for eco-friendliness is not about raising fixed overhead costs.","D":"Incorrect because coal is a polluting fossil fuel."}}},{"id":"P1_U4_MCQ_175","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_175","question":"An online electronics retailer stops using expanded polystyrene foam blocks to cushion parcels and switches to moulded pulp trays made from recycled newspapers that dissolve cleanly in compost. Which sustainable practice is this?","options":{"A":"Installing wind turbines","B":"Using environmentally friendly packaging","C":"Job production","D":"Quality assurance inspection"},"correctOption":"B","correctAnswer":"Using environmentally friendly packaging","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because replacing non-biodegradable polystyrene with recycled, compostable protective trays is an example of environmentally friendly packaging.","distractor_reasons":{"A":"Incorrect because wind turbines generate renewable electricity rather than addressing parcel packaging.","B":"Correct selection.","C":"Incorrect because job production refers to bespoke one-off manufacturing.","D":"Incorrect because quality assurance monitors production standards."}}},{"id":"P1_U4_MCQ_176","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_176","question":"A renewable-energy building materials manufacturer receives lower-interest 'green loans' from ethical banks and attracts strong investment from sustainability-focused investment funds. What advantage of sustainable production does this illustrate?","options":{"A":"Easier access to finance and investment from ethical lenders and shareholders","B":"Zero variable raw material costs","C":"Exemption from paying employee wages","D":"Complete elimination of market competition"},"correctOption":"A","correctAnswer":"Easier access to finance and investment from ethical lenders and shareholders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because many banks and institutional investors actively favour environmentally responsible businesses, offering preferential green finance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sustainable businesses still pay for raw materials.","C":"Incorrect because all businesses must pay employees fairly.","D":"Incorrect because sustainable firms still compete against rivals in the market."}}},{"id":"P1_U4_MCQ_177","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_177","question":"A specialty coffee roaster gains Rainforest Alliance and organic certification for its zero-emission roasting plant, enabling it to sell coffee beans at $18 per bag compared with $12 for standard brands. How does sustainability benefit this business?","options":{"A":"It allows the business to add value and charge a premium price to eco-conscious consumers","B":"It eliminates the cost of buying coffee beans from farmers","C":"It guarantees that no competitor can ever sell coffee","D":"It removes the need for quality checks during roasting"},"correctOption":"A","correctAnswer":"It allows the business to add value and charge a premium price to eco-conscious consumers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because credible sustainability credentials differentiate a brand and justify a higher selling price among environmentally aware buyers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because certified organic coffee beans actually cost more, not zero, to purchase.","C":"Incorrect because rival coffee roasters remain free to compete.","D":"Incorrect because premium coffee requires strict quality control to maintain customer trust."}}},{"id":"P1_U4_MCQ_178","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_178","question":"A packaging factory reduces its solid landfill waste by 80% through recycling off-cuts and cuts carbon emissions by installing heat-recovery boilers, saving $95,000 a year in government landfill taxes and carbon levies. Which benefit of sustainability is shown here?","options":{"A":"Avoiding environmental taxes, levies, and regulatory fines","B":"Higher initial research and development expenses","C":"Increased reliance on non-renewable fossil fuels","D":"Higher employee absenteeism"},"correctOption":"A","correctAnswer":"Avoiding environmental taxes, levies, and regulatory fines","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because governments impose landfill taxes and carbon charges on waste and pollution; sustainable operations directly reduce these tax liabilities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because high R&D costs are a disadvantage, whereas saving $95,000 in taxes is a financial benefit.","C":"Incorrect because heat-recovery boilers reduce rather than increase fossil fuel consumption.","D":"Incorrect because sustainability initiatives do not increase absenteeism."}}},{"id":"P1_U4_MCQ_179","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_179","question":"Over five years, a supermarket chain's investment in LED lighting, solar rooftops, and energy-efficient refrigeration lowers its annual electricity bill by $1.4 million. Which long-term advantage of sustainability does this demonstrate?","options":{"A":"Lower long-run operating and energy costs, increasing profit margins","B":"Zero upfront installation costs","C":"Elimination of all supplier payments","D":"Ability to close all physical stores"},"correctOption":"A","correctAnswer":"Lower long-run operating and energy costs, increasing profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because energy-saving and renewable technologies substantially reduce ongoing utility expenses once the initial investment is made.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because installing solar panels and LED systems requires significant upfront capital.","C":"Incorrect because the supermarket still must pay suppliers for groceries.","D":"Incorrect because energy upgrades reduce store running costs rather than closing stores."}}},{"id":"P1_U4_MCQ_180","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_180","question":"A sportswear company spends $4 million over three years testing plant-based waterproof membranes to replace harmful fluorochemical coatings before a single jacket is sold. Which disadvantage of sustainable production does this illustrate?","options":{"A":"High research and development (R&D) costs before any financial return is earned","B":"Consumers refuse to buy waterproof jackets","C":"Governments fine companies that research eco-friendly materials","D":"Plant-based coatings require zero testing"},"correctOption":"A","correctAnswer":"High research and development (R&D) costs before any financial return is earned","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because inventing and testing new sustainable materials requires heavy upfront R&D spending with no immediate revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because outdoor consumers strongly favour eco-friendly waterproof performance.","C":"Incorrect because governments support rather than fine sustainable R&D.","D":"Incorrect because new eco-materials require extensive durability and safety testing."}}},{"id":"P1_U4_MCQ_181","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_181","question":"A chocolate manufacturer switches from conventional cocoa and plastic wrappers to certified organic cocoa and compostable foil, causing the variable cost per chocolate bar to rise by 35%. Which challenge does this create?","options":{"A":"Higher unit production costs that either squeeze profit margins or force higher selling prices","B":"Immediate reduction in all fixed factory rent","C":"Lower quality chocolate bars that taste worse","D":"Complete elimination of packaging suppliers"},"correctOption":"A","correctAnswer":"Higher unit production costs that either squeeze profit margins or force higher selling prices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because certified sustainable raw materials and biodegradable packaging are often more expensive per unit, raising variable costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ingredient and wrapper costs are variable costs and do not reduce fixed factory rent.","C":"Incorrect because organic ingredients typically maintain or improve product quality.","D":"Incorrect because the manufacturer still buys compostable wrappers from packaging suppliers."}}},{"id":"P1_U4_MCQ_182","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_182","question":"During an economic recession when household incomes fall, an eco-friendly household cleaner brand sees sales drop as shoppers switch to cheaper non-sustainable supermarket brands. Which limitation of sustainable production is shown here?","options":{"A":"When incomes are tight, price-sensitive consumers often prioritize low prices over environmental credentials","B":"Eco-friendly cleaners do not clean surfaces effectively","C":"Supermarkets are banned from selling sustainable cleaning products","D":"Recessions eliminate all environmental regulations"},"correctOption":"A","correctAnswer":"When incomes are tight, price-sensitive consumers often prioritize low prices over environmental credentials","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustainable products often carry higher prices, making them vulnerable when price-conscious consumers cut spending during downturns.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because modern eco-cleaners are formulated to clean effectively.","C":"Incorrect because supermarkets actively stock sustainable brands alongside budget lines.","D":"Incorrect because environmental laws remain in force during recessions."}}},{"id":"P1_U4_MCQ_183","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_183","question":"A European electronics brand claims its smartphones are sustainably produced, but an investigation reveals an overseas cobalt supplier is polluting rivers without supervision. What difficulty in achieving sustainability does this highlight?","options":{"A":"Monitoring and enforcing sustainable standards across long, complex international supply chains is difficult and costly","B":"Cobalt is a renewable agricultural crop grown in Europe","C":"Consumers ignore environmental scandals involving smartphone brands","D":"Electronics manufacturers do not use raw minerals"},"correctOption":"A","correctAnswer":"Monitoring and enforcing sustainable standards across long, complex international supply chains is difficult and costly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because true sustainability covers the entire supply chain, and auditing distant overseas suppliers requires costly inspections and verification.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cobalt is a mined mineral resource, not a renewable agricultural crop.","C":"Incorrect because supply-chain pollution scandals severely damage brand reputation.","D":"Incorrect because smartphones require numerous mined metals and minerals."}}},{"id":"P1_U4_MCQ_184","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_184","question":"A printing factory introduces strict rules requiring staff to separate five types of paper, ink, and plastic waste and switch off idle machinery, but initially productivity drops as workers complain about the extra steps. Which drawback does this illustrate?","options":{"A":"Changing established employee habits requires training, supervision, and time, which can slow operations initially","B":"Separating waste increases landfill disposal fees","C":"Switching off idle machinery increases electricity bills","D":"Workers are legally forbidden from sorting factory waste"},"correctOption":"A","correctAnswer":"Changing established employee habits requires training, supervision, and time, which can slow operations initially","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because adopting sustainable procedures requires workers to unlearn old routines and spend time following new environmental protocols.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sorting waste for recycling reduces rather than increases landfill fees.","C":"Incorrect because switching off idle machines saves electricity.","D":"Incorrect because employees are encouraged and trained to sort workplace waste."}}},{"id":"P1_U4_MCQ_185","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_185","question":"A commercial airline invests in modern lightweight composite aircraft that burn 20% less aviation fuel per passenger kilometre and offers passengers a voluntary carbon-offsetting scheme. How does this benefit the service business?","options":{"A":"It lowers fuel costs per flight while improving its environmental reputation among travellers","B":"It eliminates the need to employ pilots or cabin crew","C":"It allows planes to fly without any fuel","D":"It removes all airport landing charges"},"correctOption":"A","correctAnswer":"It lowers fuel costs per flight while improving its environmental reputation among travellers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fuel-efficient aircraft directly reduce a major variable operating cost (jet fuel) while reducing emissions and boosting brand image.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because modern commercial aircraft still require qualified pilots and cabin crew.","C":"Incorrect because the aircraft still burn aviation fuel, though 20% less than older models.","D":"Incorrect because airlines still pay airport landing fees."}}},{"id":"P1_U4_MCQ_186","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_186","question":"A fast-fashion retailer prints 'Eco-Conscious' on its swing tags while continuing to manufacture disposable synthetic garments in polluting factories, leading to public backlash when exposed. Why must sustainability involve genuine operational changes rather than just marketing claims?","options":{"A":"Misleading environmental claims ('greenwashing') destroy customer trust and damage brand reputation permanently","B":"Consumers never read product labels or news reports","C":"Synthetic disposable clothing is completely biodegradable in two days","D":"Polluting factories always produce the highest-quality luxury garments"},"correctOption":"A","correctAnswer":"Misleading environmental claims ('greenwashing') destroy customer trust and damage brand reputation permanently","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumers and regulators quickly expose false environmental claims, turning intended brand promotion into severe reputational damage.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because modern shoppers and media closely scrutinize corporate environmental claims.","C":"Incorrect because synthetic plastics like polyester take decades or centuries to degrade.","D":"Incorrect because pollution levels do not equate to luxury product quality."}}},{"id":"P1_U4_MCQ_187","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_187","question":"How does adopting lean production techniques—such as eliminating overproduction and reducing manufacturing defects—directly support a business's environmental sustainability goals?","options":{"A":"Fewer raw materials and less energy are wasted making unsold or faulty goods that end up in landfill","B":"Lean production encourages factories to burn coal instead of using solar power","C":"Lean production increases the amount of packaging wrapped around every product","D":"Lean production requires shipping components twice around the world before assembly"},"correctOption":"A","correctAnswer":"Fewer raw materials and less energy are wasted making unsold or faulty goods that end up in landfill","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because preventing overproduction and defects means fewer natural resources and less electricity are wasted on goods that are scrapped or never sold.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lean production seeks to minimize energy waste rather than promoting fossil fuels.","C":"Incorrect because lean production eliminates unnecessary packaging and materials.","D":"Incorrect because lean production eliminates unnecessary transportation waste."}}},{"id":"P1_U4_MCQ_188","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_188","question":"A newly launched start-up selling takeaway salads has limited cash reserves and finds that biodegradable plant-plastic bowls cost $0.45 each compared with $0.12 for standard plastic bowls. What trade-off must the entrepreneur consider?","options":{"A":"Balancing higher unit packaging costs and tighter cash flow against stronger brand appeal to eco-minded customers","B":"Choosing whether to pay zero rent or zero wages","C":"Deciding whether salads should be manufactured using heavy steel smelting","D":"Eliminating all food hygiene checks to pay for the bowls"},"correctOption":"A","correctAnswer":"Balancing higher unit packaging costs and tighter cash flow against stronger brand appeal to eco-minded customers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because small start-ups must weigh higher short-term variable costs and cash-flow pressure against long-term brand differentiation and customer loyalty.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because rent and wages must still be paid regardless of packaging choice.","C":"Incorrect because steel smelting is unrelated to takeaway food preparation.","D":"Incorrect because food hygiene regulations are mandatory and cannot be skipped."}}},{"id":"P1_U4_MCQ_189","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_189","question":"A printing business incurs the following monthly expenses: local property taxes, ink and paper used per brochure printed, overtime wages for extra print runs, and shipping boxes per order. Which of these is a fixed cost?","options":{"A":"Local property taxes","B":"Ink and paper used per brochure","C":"Overtime wages for extra print runs","D":"Shipping boxes per order"},"correctOption":"A","correctAnswer":"Local property taxes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because local property taxes are fixed overheads that do not vary with the number of brochures printed in a month.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ink and paper vary directly with the quantity of brochures produced.","C":"Incorrect because overtime wages for extra production runs vary with output volume.","D":"Incorrect because shipping boxes vary directly with the number of customer orders dispatched."}}},{"id":"P1_U4_MCQ_190","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_190","question":"A jewellery maker pays a workshop lease, annual business insurance, silver beads used in each bracelet, and an accountant's annual retainer fee. Which of these is a variable cost?","options":{"A":"Workshop lease","B":"Silver beads used in each bracelet","C":"Annual business insurance","D":"Accountant's annual retainer fee"},"correctOption":"B","correctAnswer":"Silver beads used in each bracelet","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the quantity and cost of silver beads increase or decrease directly with the number of bracelets manufactured.","distractor_reasons":{"A":"Incorrect because the workshop lease is a fixed cost independent of monthly bracelet output.","B":"Correct selection.","C":"Incorrect because annual insurance is a fixed cost.","D":"Incorrect because a fixed annual retainer fee does not change with each bracelet made."}}},{"id":"P1_U4_MCQ_191","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_191","question":"A craft soap manufacturer has monthly fixed costs of $12,000 and incurs variable costs of $4.50 per bar of soap. What is the total cost of producing 4,000 bars of soap in a month?","options":{"A":"$18,000","B":"$16,000","C":"$30,000","D":"$12,004.50"},"correctOption":"C","correctAnswer":"$30,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total variable cost is $4.50 x 4,000 = $18,000, and adding fixed costs of $12,000 gives a total cost of $30,000.","distractor_reasons":{"A":"Incorrect because $18,000 is only the total variable cost, omitting the $12,000 fixed costs.","B":"Incorrect because this adds 4,000 units directly to $12,000 without multiplying by the $4.50 variable cost per unit.","C":"Correct selection.","D":"Incorrect because this adds the variable cost of a single bar ($4.50) rather than 4,000 bars."}}},{"id":"P1_U4_MCQ_192","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_192","question":"A ceramic mug factory produces 3,000 mugs per week with weekly fixed costs of $15,000 and variable costs of $5 per mug. What is the average cost per mug?","options":{"A":"$5","B":"$30,000","C":"$15","D":"$10"},"correctOption":"D","correctAnswer":"$10","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because total variable cost is 3,000 x $5 = $15,000, total cost is $15,000 + $15,000 = $30,000, and dividing $30,000 by 3,000 mugs equals $10 per mug.","distractor_reasons":{"A":"Incorrect because $5 is only the variable cost per mug, ignoring average fixed cost ($5).","B":"Incorrect because $30,000 is the total weekly cost rather than the average cost per mug.","C":"Incorrect because this divides fixed costs by 1,000 instead of 3,000 before adding variable cost.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_193","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_193","question":"A bakery has monthly fixed costs of $20,000. When monthly output increases from 2,000 cakes to 5,000 cakes within its existing premises, what happens to the average fixed cost per cake?","options":{"A":"It falls from $10 to $4 per cake because fixed costs are spread over more units","B":"It rises from $4 to $10 per cake","C":"It remains unchanged at $10 per cake","D":"It falls to $0 per cake"},"correctOption":"A","correctAnswer":"It falls from $10 to $4 per cake because fixed costs are spread over more units","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because at 2,000 cakes, average fixed cost is $20,000 / 2,000 = $10, whereas at 5,000 cakes it drops to $20,000 / 5,000 = $4.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher output spreads fixed costs thinner, reducing average fixed cost rather than raising it.","C":"Incorrect because total fixed cost remains $20,000, so fixed cost per unit decreases as output grows.","D":"Incorrect because fixed costs are still positive ($4 per cake) at 5,000 units."}}},{"id":"P1_U4_MCQ_194","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_194","question":"A backpack manufacturer calculates that the average total cost of producing each backpack is $14.00 and decides to set its selling price by adding a 25% profit mark-up. What selling price will the manufacturer set?","options":{"A":"$14.25","B":"$17.50","C":"$10.50","D":"$39.00"},"correctOption":"B","correctAnswer":"$17.50","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because 25% of $14.00 is $3.50, and adding $3.50 profit mark-up to the $14.00 unit cost gives a selling price of $17.50.","distractor_reasons":{"A":"Incorrect because this adds 25 cents instead of 25% of $14.00 ($3.50).","B":"Correct selection.","C":"Incorrect because $10.50 subtracts 25% ($3.50) instead of adding it.","D":"Incorrect because this adds $25 directly instead of 25%."}}},{"id":"P1_U4_MCQ_195","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_195","question":"A towel factory has spare production capacity and all its monthly fixed costs are already covered by regular orders. A hotel chain offers to buy 500 extra towels at $9 per towel when the variable cost is $6 per towel. Based on cost data, should the factory accept this special order?","options":{"A":"No, because $9 is below the factory's normal retail price","B":"No, because total variable costs of $3,000 exceed the revenue earned","C":"Yes, because each towel contributes $3 toward profit ($1,500 total) since fixed costs are already covered","D":"Yes, because accepting the order will reduce fixed costs by $4,500"},"correctOption":"C","correctAnswer":"Yes, because each towel contributes $3 toward profit ($1,500 total) since fixed costs are already covered","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when spare capacity exists and fixed costs are covered, any selling price ($9) above variable cost ($6) generates positive contribution ($3 x 500 = $1,500) that adds directly to profit.","distractor_reasons":{"A":"Incorrect because accepting a discounted one-off order using spare capacity increases total profit as long as price exceeds variable cost.","B":"Incorrect because revenue is 500 x $9 = $4,500, which exceeds variable costs of $3,000 by $1,500.","C":"Correct selection.","D":"Incorrect because fixed costs remain unchanged; the order increases profit through positive contribution."}}},{"id":"P1_U4_MCQ_196","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_196","question":"As a bottled-water company expands its annual output from 1 million to 10 million bottles, its average cost per bottle falls from $0.45 to $0.22. Which economic concept explains this fall in unit costs?","options":{"A":"Diseconomies of scale","B":"Margin of safety","C":"Just-in-time inventory control","D":"Economies of scale"},"correctOption":"D","correctAnswer":"Economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because economies of scale are the factors that lead to a reduction in average cost per unit as a business increases its scale of production.","distractor_reasons":{"A":"Incorrect because diseconomies of scale cause average costs to rise rather than fall.","B":"Incorrect because margin of safety measures the gap between actual output and break-even output.","C":"Incorrect because JIT is a lean inventory system rather than a scale-of-production cost effect.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_197","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_197","question":"A global smartphone brand spends $20 million on a nationwide television advertising campaign, which works out to just $2 per phone across its 10 million sales, whereas a small rival selling 100,000 phones would pay $200 per phone for the same campaign. Which economy of scale is this?","options":{"A":"Marketing economies of scale","B":"Purchasing economies of scale","C":"Financial economies of scale","D":"Technical economies of scale"},"correctOption":"A","correctAnswer":"Marketing economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because marketing economies occur when large firms spread high fixed advertising and promotion costs across huge sales volumes, lowering marketing cost per unit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because purchasing economies refer to bulk-buying discounts on raw materials.","C":"Incorrect because financial economies refer to lower interest rates on bank loans.","D":"Incorrect because technical economies refer to high-capacity factory machinery."}}},{"id":"P1_U4_MCQ_198","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_198","question":"In a small sole-trader business, the owner handles accounting, marketing, and operations personally, whereas a large firm hires a qualified Finance Director, Operations Director, and Marketing Director to run each area efficiently. Which economy of scale does the large firm gain?","options":{"A":"Purchasing economies of scale","B":"Managerial economies of scale","C":"Financial economies of scale","D":"Marketing economies of scale"},"correctOption":"B","correctAnswer":"Managerial economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because managerial economies occur when larger businesses can afford specialist functional managers whose expertise improves efficiency and lowers unit costs.","distractor_reasons":{"A":"Incorrect because purchasing economies involve bulk discounts on materials.","B":"Correct selection.","C":"Incorrect because financial economies involve lower borrowing interest rates.","D":"Incorrect because marketing economies involve spreading advertising and delivery costs over higher sales."}}},{"id":"P1_U4_MCQ_199","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_199","question":"A large public limited company raises $50 million for factory expansion by issuing new shares on the stock exchange and securing a low-interest corporate bond, options unavailable to small private firms. Which economy of scale does this illustrate?","options":{"A":"Technical economies of scale","B":"Marketing economies of scale","C":"Financial economies of scale","D":"Purchasing economies of scale"},"correctOption":"C","correctAnswer":"Financial economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because financial economies occur when large firms access wider sources of finance (such as share issues) and borrow at lower interest rates.","distractor_reasons":{"A":"Incorrect because technical economies involve specialized production equipment.","B":"Incorrect because marketing economies involve lower advertising and transport costs per unit.","C":"Correct selection.","D":"Incorrect because purchasing economies involve bulk-buying discounts on supplies."}}},{"id":"P1_U4_MCQ_200","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_200","question":"Following a mega-merger, a 60,000-employee corporation becomes so impersonal that factory workers feel disconnected from senior directors, leading to low morale, higher absenteeism, and rising unit costs. Which diseconomy of scale is this?","options":{"A":"Poor communication across regional sales offices","B":"Bulk-buying discounts from component suppliers","C":"Lower interest rates on international bank loans","D":"Low employee morale and alienation in a very large workforce"},"correctOption":"D","correctAnswer":"Low employee morale and alienation in a very large workforce","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because in giant organizations, workers often feel unimportant and distant from top management, reducing motivation and productivity and raising unit costs.","distractor_reasons":{"A":"Incorrect because the scenario specifically describes worker alienation and absenteeism rather than inter-office communication delays.","B":"Incorrect because bulk-buying discounts are purchasing economies of scale, not diseconomies.","C":"Incorrect because lower interest rates are financial economies of scale.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_201","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_201","question":"At a huge multinational electronics group, a simple request to change a supplier takes six months because it must pass through nine layers of management approval, causing the firm to miss market opportunities. Which diseconomy of scale is causing this inefficiency?","options":{"A":"Slow decision-making and weak co-ordination due to long chains of command","B":"Technical economies from automated assembly lines","C":"Managerial economies from hiring specialist engineers","D":"Marketing economies from global brand advertising"},"correctOption":"A","correctAnswer":"Slow decision-making and weak co-ordination due to long chains of command","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because oversized organizations develop tall hierarchies and bureaucratic procedures that slow down decisions and raise average costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because technical economies lower average costs rather than slowing down decisions.","C":"Incorrect because managerial economies improve efficiency rather than causing six-month delays.","D":"Incorrect because marketing economies reduce unit promotion costs."}}},{"id":"P1_U4_MCQ_202","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_202","question":"A wireless headphone manufacturer sells each pair of headphones for $25, incurs variable costs of $13 per pair, and has monthly fixed costs of $24,000. What is the contribution per unit?","options":{"A":"$38","B":"$12","C":"$13","D":"$2,000"},"correctOption":"B","correctAnswer":"$12","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because contribution per unit equals selling price ($25) minus variable cost per unit ($13), which is $12.","distractor_reasons":{"A":"Incorrect because this adds variable cost ($13) to selling price ($25) instead of subtracting it.","B":"Correct selection.","C":"Incorrect because $13 is the variable cost per unit rather than the contribution toward fixed costs.","D":"Incorrect because 2,000 units is the break-even output ($24,000 / $12), not the contribution per unit."}}},{"id":"P1_U4_MCQ_203","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_203","question":"A desk lamp manufacturer has monthly fixed costs of $36,000, sells each lamp for $30, and incurs variable costs of $18 per lamp. How many lamps must the manufacturer sell each month to break even?","options":{"A":"1,200 lamps","B":"2,000 lamps","C":"3,000 lamps","D":"750 lamps"},"correctOption":"C","correctAnswer":"3,000 lamps","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because contribution per lamp is $30 - $18 = $12, and dividing fixed costs ($36,000) by contribution per unit ($12) equals 3,000 lamps.","distractor_reasons":{"A":"Incorrect because this divides $36,000 by the $30 selling price without deducting the $18 variable cost.","B":"Incorrect because this divides $36,000 by the $18 variable cost instead of contribution per unit ($12).","C":"Correct selection.","D":"Incorrect because this adds selling price and variable cost ($48) before dividing into $36,000."}}},{"id":"P1_U4_MCQ_204","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_204","question":"A bicycle helmet factory has a monthly break-even output of 3,000 helmets and currently sells 4,200 helmets per month. What is the factory's margin of safety and what does it tell managers?","options":{"A":"7,200 helmets; total capacity before overtime begins","B":"3,000 helmets; minimum sales required to earn maximum profit","C":"4,200 helmets; total revenue earned in a month","D":"1,200 helmets; sales can fall by 1,200 units before the factory starts making a loss"},"correctOption":"D","correctAnswer":"1,200 helmets; sales can fall by 1,200 units before the factory starts making a loss","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because margin of safety equals actual sales (4,200) minus break-even output (3,000) = 1,200 helmets, showing the buffer by which sales can drop before incurring a loss.","distractor_reasons":{"A":"Incorrect because 7,200 adds actual sales and break-even output instead of subtracting them.","B":"Incorrect because 3,000 is the break-even point where profit is zero, not maximum profit.","C":"Incorrect because 4,200 is current sales volume in units, not total revenue.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_205","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_205","question":"A water-bottle manufacturer has monthly fixed costs of $10,000 and generates a contribution of $8 per bottle sold. If the company sells 2,000 bottles in a month, what is its monthly profit?","options":{"A":"$6,000","B":"$16,000","C":"$26,000","D":"$10,000"},"correctOption":"A","correctAnswer":"$6,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because total contribution is 2,000 x $8 = $16,000, and subtracting fixed costs of $10,000 leaves a monthly profit of $6,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $16,000 is total contribution before deducting the $10,000 fixed costs.","C":"Incorrect because this adds fixed costs ($10,000) to total contribution ($16,000) instead of subtracting them.","D":"Incorrect because $10,000 is the monthly fixed cost rather than profit."}}},{"id":"P1_U4_MCQ_206","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_206","question":"On a break-even chart, at an output level to the right of the break-even point, what does the vertical distance between the Total Revenue line and the Total Cost line represent?","options":{"A":"Total fixed costs","B":"The amount of profit made at that output level","C":"The amount of loss made at that output level","D":"Total variable costs"},"correctOption":"B","correctAnswer":"The amount of profit made at that output level","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because to the right of the break-even point, the Total Revenue line lies above the Total Cost line, and the vertical gap between them equals total profit.","distractor_reasons":{"A":"Incorrect because total fixed costs are represented by the horizontal fixed cost line.","B":"Correct selection.","C":"Incorrect because losses occur to the left of the break-even point where Total Cost is above Total Revenue.","D":"Incorrect because total variable costs equal the vertical distance between the Total Cost line and the Fixed Cost line."}}},{"id":"P1_U4_MCQ_207","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_207","question":"A commercial bakery's landlord increases annual rent by $5,000 while flour costs and bread selling prices stay unchanged. How does this rent increase change the bakery's break-even chart?","options":{"A":"The total revenue line shifts downward and break-even output falls","B":"The total cost line becomes steeper and margin of safety increases","C":"Both the fixed cost line and total cost line shift upward parallel, raising break-even output and reducing the margin of safety","D":"The break-even point remains completely unchanged"},"correctOption":"C","correctAnswer":"Both the fixed cost line and total cost line shift upward parallel, raising break-even output and reducing the margin of safety","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because rent is a fixed cost; raising it shifts the fixed cost and total cost lines upward by $5,000, requiring more sales to break even.","distractor_reasons":{"A":"Incorrect because rent does not affect selling prices or the total revenue line.","B":"Incorrect because variable cost per unit determines the slope of the total cost line; higher fixed costs reduce, not increase, the margin of safety.","C":"Correct selection.","D":"Incorrect because higher fixed costs increase the break-even output."}}},{"id":"P1_U4_MCQ_208","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_208","question":"A smartphone assembler negotiates a 20% discount on screen components per phone produced while fixed factory rent and phone selling prices stay constant. How does this affect the firm's break-even position?","options":{"A":"The total cost line becomes steeper and break-even output rises","B":"The fixed cost line shifts downward while variable costs stay the same","C":"The total revenue line shifts upward","D":"The total cost line becomes less steep, lowering break-even output and increasing profit at full capacity"},"correctOption":"D","correctAnswer":"The total cost line becomes less steep, lowering break-even output and increasing profit at full capacity","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because lower variable cost per unit flattens the slope of the total cost line, increases contribution per unit, and lowers the break-even point.","distractor_reasons":{"A":"Incorrect because a lower variable cost per unit makes the total cost line flatter, not steeper.","B":"Incorrect because component costs per phone are variable costs, not fixed costs.","C":"Incorrect because selling prices did not change, so the total revenue line is unaffected.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_209","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_209","question":"A supermarket stocks 25,000 different grocery products with constantly changing promotional discounts, making standard break-even charts unhelpful for the whole store. Which limitation of break-even analysis does this highlight?","options":{"A":"Break-even analysis assumes a business produces and sells a single standardized product at one constant price","B":"Break-even analysis cannot calculate fixed costs for retail businesses","C":"Break-even charts assume total revenue is always zero","D":"Break-even analysis only works when a business makes a loss"},"correctOption":"A","correctAnswer":"Break-even analysis assumes a business produces and sells a single standardized product at one constant price","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because simple break-even models assume one product sold at a single unvarying price, limiting their usefulness for multi-product firms offering price discounts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fixed costs such as store rent and salaries are easily identified in retail.","C":"Incorrect because total revenue rises diagonally from the origin on break-even charts.","D":"Incorrect because break-even charts display loss regions, the break-even point, and profit regions."}}},{"id":"P1_U4_MCQ_210","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_210","question":"A $12 plastic kitchen timer keeps accurate time for five years without breaking, satisfying everyday home cooks. In Business Studies, why is this inexpensive timer considered a quality product?","options":{"A":"Because quality means a product is fit for purpose and meets customer expectations","B":"Because any product costing over $10 is legally classified as luxury quality","C":"Because home cooks do not care whether kitchen timers work accurately","D":"Because quality depends solely on gold-plated packaging"},"correctOption":"A","correctAnswer":"Because quality means a product is fit for purpose and meets customer expectations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality refers to whether a good or service meets customer expectations and performs its intended function reliably, regardless of price tier.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality is defined by meeting customer expectations, not by an arbitrary price threshold.","C":"Incorrect because keeping accurate time is the core customer expectation for a kitchen timer.","D":"Incorrect because packaging alone does not make a product fit for purpose."}}},{"id":"P1_U4_MCQ_211","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_211","question":"In a crowded market where five rival brands sell identically priced wireless earbuds, one brand gains market share because its earbuds never disconnect and have clear sound. How does quality help this business?","options":{"A":"It provides a competitive advantage and attracts customers away from less reliable rivals without cutting prices","B":"It eliminates all advertising and distribution expenses","C":"It guarantees that raw material costs fall to zero","D":"It prevents competitors from launching new products"},"correctOption":"A","correctAnswer":"It provides a competitive advantage and attracts customers away from less reliable rivals without cutting prices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because superior reliability differentiates a product from similarly priced competitors, winning market share without eroding profit margins via price cuts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the firm still pays for marketing and distribution.","C":"Incorrect because high-quality components still must be purchased.","D":"Incorrect because competitors can still launch products in the market."}}},{"id":"P1_U4_MCQ_212","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_212","question":"A washing machine manufacturer improves its build quality, cutting customer warranty repair call-outs and free replacement parts by 75% within a year. What direct benefit does this create?","options":{"A":"Lower after-sales warranty and replacement costs, increasing overall profitability","B":"Higher customer complaints on consumer forums","C":"Increased scrappage of finished washing machines","D":"Higher labour turnover among repair technicians"},"correctOption":"A","correctAnswer":"Lower after-sales warranty and replacement costs, increasing overall profitability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fewer faulty machines leaving the factory directly reduces expensive warranty repairs, refunds, and replacement shipments.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because reliable appliances reduce rather than increase customer complaints.","C":"Incorrect because improved build quality reduces scrappage.","D":"Incorrect because fewer warranty call-outs lower repair costs rather than increasing turnover."}}},{"id":"P1_U4_MCQ_213","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_213","question":"A luggage brand is famous for ultra-durable suitcases that withstand decades of air travel, allowing it to sell suitcases for $450 while average brands sell for $120. Which advantage of quality is shown here?","options":{"A":"The ability to charge a premium price and earn higher added value per unit","B":"Elimination of all fixed factory costs","C":"Zero spending on research and materials","D":"Guaranteed protection against economic recessions"},"correctOption":"A","correctAnswer":"The ability to charge a premium price and earn higher added value per unit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a strong reputation for exceptional quality enables a business to charge premium prices, increasing added value and profit margins.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fixed costs such as factory rent and salaries still exist.","C":"Incorrect because durable luggage requires investment in strong materials and testing.","D":"Incorrect because even premium brands can see demand slow during severe recessions."}}},{"id":"P1_U4_MCQ_214","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_214","question":"A car manufacturer discovers a faulty brake sensor after selling 40,000 vehicles, forcing it to issue a global product recall to replace the part free of charge. What are the consequences of this quality failure?","options":{"A":"Huge recall repair costs, negative media publicity, and loss of customer trust","B":"Higher profit margins and stronger brand loyalty","C":"Lower variable costs and faster assembly speeds","D":"Increased demand from safety-conscious buyers"},"correctOption":"A","correctAnswer":"Huge recall repair costs, negative media publicity, and loss of customer trust","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because product recalls impose massive logistical and repair expenses while severely damaging brand reputation and future sales.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because recalls reduce profits and harm brand loyalty.","C":"Incorrect because fixing defects increases costs rather than lowering them.","D":"Incorrect because brake safety recalls deter safety-conscious buyers."}}},{"id":"P1_U4_MCQ_215","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_215","question":"At a lightbulb factory producing 50,000 bulbs per day, specialist inspectors select 100 finished bulbs every hour and test their brightness and lifespan before packing. Which quality method is being used?","options":{"A":"Quality assurance","B":"Quality control","C":"Kaizen","D":"Just-in-time inventory control"},"correctOption":"B","correctAnswer":"Quality control","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because quality control involves specialist inspectors testing finished products or random samples at the end of production.","distractor_reasons":{"A":"Incorrect because quality assurance involves all workers checking quality standards at every stage throughout production.","B":"Correct selection.","C":"Incorrect because Kaizen refers to continuous improvement meetings by employees.","D":"Incorrect because JIT manages inventory delivery timing."}}},{"id":"P1_U4_MCQ_216","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_216","question":"A canned soup factory uses quality control by opening and tasting only 10 cans out of every batch of 10,000 cans at the end of the line. What is a major risk of relying on sample testing?","options":{"A":"Defective cans outside the tested sample can still reach supermarket shelves and upset customers","B":"All 10,000 cans are destroyed during testing so nothing can be sold","C":"Production workers spend too much time checking their own cans at every stage","D":"Training all 200 factory staff in quality assurance costs too much"},"correctOption":"A","correctAnswer":"Defective cans outside the tested sample can still reach supermarket shelves and upset customers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when only a small sample of finished output is inspected, faulty units in the untested portion may still be shipped to customers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because only 10 cans are opened for testing, leaving 9,990 cans to sell.","C":"Incorrect because workers checking every stage describes quality assurance, not end-of-line quality control.","D":"Incorrect because quality control uses a few specialist inspectors rather than training all production staff."}}},{"id":"P1_U4_MCQ_217","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_217","question":"At a clothing factory using end-of-line quality control, sewing machinists rush their stitching without checking seams because they believe 'catching mistakes is the quality inspector's job.' Which disadvantage of quality control does this show?","options":{"A":"Production workers take less personal responsibility for quality, leading to higher defect and reworking rates","B":"Quality inspectors cost nothing to employ","C":"Customers prefer garments with loose stitching","D":"Inspectors prevent every single defect before sewing begins"},"correctOption":"A","correctAnswer":"Production workers take less personal responsibility for quality, leading to higher defect and reworking rates","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because separating inspection from production encourages workers to focus solely on speed rather than taking ownership of quality.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because specialist quality inspectors add to wage costs.","C":"Incorrect because loose stitching fails customer expectations.","D":"Incorrect because end-of-line inspectors check goods after sewing is finished, not before."}}},{"id":"P1_U4_MCQ_218","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_218","question":"An automotive parts supplier documents exact operating standards for raw steel testing, machine calibration, assembly checks, and packaging, requiring every employee to verify their stage before passing parts onward. Which quality system is this?","options":{"A":"End-of-line quality control","B":"Quality assurance","C":"Batch reworking","D":"Mystery shopping"},"correctOption":"B","correctAnswer":"Quality assurance","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because quality assurance sets agreed quality standards across every stage of operations and makes all employees responsible for meeting them.","distractor_reasons":{"A":"Incorrect because quality control only inspects finished goods at the end of the line.","B":"Correct selection.","C":"Incorrect because reworking fixes faulty goods after defects occur.","D":"Incorrect because mystery shopping tests customer service in retail or hospitality."}}},{"id":"P1_U4_MCQ_219","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_219","question":"A precision engineering firm gains internationally recognized quality assurance accreditation (such as ISO 9001), proving its processes meet strict standards at every stage. How does this help the firm win major corporate clients?","options":{"A":"Corporate buyers trust that the firm will reliably deliver consistent, defect-free components on schedule","B":"Accreditation guarantees the firm charges the lowest price in the world","C":"Accreditation eliminates the need to buy raw materials","D":"Corporate clients are legally forced to buy from accredited suppliers"},"correctOption":"A","correctAnswer":"Corporate buyers trust that the firm will reliably deliver consistent, defect-free components on schedule","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because formal quality assurance systems assure business customers that every stage of production is controlled, reducing supply risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality assurance focuses on reliability and consistency rather than guaranteeing the lowest price.","C":"Incorrect because the firm still must purchase raw materials.","D":"Incorrect because corporate buyers choose accredited suppliers voluntarily to protect their own product quality."}}},{"id":"P1_U4_MCQ_220","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_220","question":"In a tailored suit factory using quality assurance, a cutter notices a weave flaw in a roll of wool fabric before cutting any suit panels and replaces the roll immediately. How does quality assurance save money here?","options":{"A":"It prevents wasted tailoring labour and linings from being spent on faulty fabric that would later be scrapped","B":"It allows the factory to sell flawed suits at full luxury prices","C":"It eliminates the cost of employing fabric cutters","D":"It doubles the amount of fabric wasted per suit"},"correctOption":"A","correctAnswer":"It prevents wasted tailoring labour and linings from being spent on faulty fabric that would later be scrapped","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because catching defects at the earliest stage prevents additional labour and component costs from being wasted on a flawed item.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality assurance prevents flawed suits from being made or sold.","C":"Incorrect because skilled cutters are still employed and perform the quality check.","D":"Incorrect because early detection reduces rather than doubles fabric waste."}}},{"id":"P1_U4_MCQ_221","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_221","question":"A small family-owned bakery introduces a formal quality assurance system that requires staff to complete 15 pages of temperature, ingredient, and cleaning checklists every shift. What disadvantage of quality assurance does this highlight?","options":{"A":"Excessive paperwork and bureaucracy can consume staff time and slow down daily operations","B":"Customers dislike bakeries that keep clean kitchens","C":"Checklists always increase food poisoning risks","D":"Quality assurance eliminates all employee wages"},"correctOption":"A","correctAnswer":"Excessive paperwork and bureaucracy can consume staff time and slow down daily operations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because documenting and verifying standards at every stage can create heavy administrative paperwork, especially burdensome for small firms.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because customers strongly value hygiene and cleanliness.","C":"Incorrect because hygiene checklists reduce rather than increase food safety risks.","D":"Incorrect because employees still receive their normal wages."}}},{"id":"P1_U4_MCQ_222","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_222","question":"A manufacturing firm spends heavily on quality assurance manuals, but managers still pressure workers to prioritize hitting hourly output quotas even if parts are slightly misaligned. Why will quality assurance fail in this factory?","options":{"A":"Quality assurance only works when every employee and manager is genuinely committed to putting quality first","B":"Quality assurance manuals cannot be read by factory workers","C":"Misaligned parts always fit together properly at the end of the line","D":"Quality assurance requires hiring external mystery shoppers"},"correctOption":"A","correctAnswer":"Quality assurance only works when every employee and manager is genuinely committed to putting quality first","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality assurance relies on a shared workplace culture where staff and managers consistently enforce standards rather than cutting corners for speed.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because employees are trained to understand and follow the standards.","C":"Incorrect because misaligned parts cause defects and product failures.","D":"Incorrect because mystery shoppers are used for service-sector quality control."}}},{"id":"P1_U4_MCQ_223","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_223","question":"An international airline trains check-in agents, baggage handlers, cabin crew, and engineers to follow strict punctuality, safety, and courtesy checklists at every stage of a passenger's journey. Which quality approach is the airline applying?","options":{"A":"Quality assurance across every stage of service delivery","B":"Destructive quality control testing","C":"Job production manufacturing","D":"Diseconomies of scale"},"correctOption":"A","correctAnswer":"Quality assurance across every stage of service delivery","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because setting and verifying standards at every customer touchpoint ensures consistent service quality before problems reach the passenger.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because destructive testing applies to physical goods like fireworks, not passenger flights.","C":"Incorrect because scheduled flights are a mass-market service rather than bespoke manufacturing.","D":"Incorrect because diseconomies of scale refer to rising average costs from excessive size."}}},{"id":"P1_U4_MCQ_224","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_224","question":"After guests check out, a hotel chain emails a short satisfaction questionnaire asking them to rate room cleanliness, breakfast quality, and reception helpfulness so managers can identify underperforming branches. Which quality method does this represent?","options":{"A":"Quality control feedback after the service has been delivered","B":"Computer-Aided Design (CAD)","C":"Just-in-time raw material ordering","D":"Batch production"},"correctOption":"A","correctAnswer":"Quality control feedback after the service has been delivered","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because inspecting customer satisfaction after service delivery monitors whether standards were met, functioning as post-delivery quality control.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because CAD is engineering design software.","C":"Incorrect because JIT manages physical inventory arrival.","D":"Incorrect because batch production is a manufacturing method."}}},{"id":"P1_U4_MCQ_225","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_225","question":"When an end-of-line fault is discovered, a luxury Swiss watchmaker disassembles and repairs the watch ('reworking'), whereas a clay brick factory crushes cracked bricks into dust ('scrapping'). Why do the two businesses treat defective items differently?","options":{"A":"A luxury watch has high value that justifies repair labour, whereas a cracked brick cannot be repaired and has very low unit value","B":"Watchmakers are legally banned from throwing away broken parts","C":"Cracked clay bricks can easily be glued back together and sold at full price","D":"Clay bricks are much more expensive per unit than luxury watches"},"correctOption":"A","correctAnswer":"A luxury watch has high value that justifies repair labour, whereas a cracked brick cannot be repaired and has very low unit value","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reworking is economical when the product's high value exceeds the repair cost, whereas low-value or unrepairable goods must be scrapped.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because there is no law banning scrapping watch components; it is an economic decision based on high unit value.","C":"Incorrect because glued bricks lack structural strength and cannot be sold as sound bricks.","D":"Incorrect because luxury watches cost thousands of dollars while bricks cost pennies."}}},{"id":"P1_U4_MCQ_226","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_226","question":"A shopping mall hires 40 temporary workers for just three weeks in December to wrap customer gifts, employing two supervisors to check wrapped parcels before handing them to shoppers. Why is quality control better than quality assurance here?","options":{"A":"Training temporary three-week staff for full quality assurance is too costly and time-consuming compared with supervisor checks","B":"Shoppers expect December gifts to be torn and poorly wrapped","C":"Quality assurance cannot be used for any retail service","D":"Supervisors work for free during December"},"correctOption":"A","correctAnswer":"Training temporary three-week staff for full quality assurance is too costly and time-consuming compared with supervisor checks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when staff are temporary and unit error costs (a sheet of wrapping paper) are tiny, final inspection by a supervisor is far more practical than lengthy staff training.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shoppers expect neat gift wrapping.","C":"Incorrect because quality assurance is widely used in retail services with permanent staff.","D":"Incorrect because supervisors are paid wages, though checking finished parcels is cheaper than training 40 temp staff."}}},{"id":"P1_U4_MCQ_227","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_227","question":"A commercial passenger aircraft manufacturer enforces strict quality assurance across every supplier, rivet, wiring loom, and engine assembly stage. Why is quality assurance essential in aviation manufacturing?","options":{"A":"Any undetected defect poses catastrophic safety risks and dismantling a finished airliner to fix early faults is prohibitively expensive","B":"Aircraft are low-priced disposable items","C":"Quality assurance eliminates the need to test finished aircraft before delivery","D":"Aviation engineers require zero training under quality assurance"},"correctOption":"A","correctAnswer":"Any undetected defect poses catastrophic safety risks and dismantling a finished airliner to fix early faults is prohibitively expensive","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because where human lives and multimillion-dollar assemblies are at stake, preventing defects at every stage is vital.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because commercial airliners are among the most expensive, complex products manufactured.","C":"Incorrect because aircraft manufacturers combine stage-by-stage quality assurance with rigorous final flight testing.","D":"Incorrect because aviation engineers undergo extensive training to maintain quality assurance standards."}}},{"id":"P1_U4_MCQ_228","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_228","question":"A soft-drinks bottling line installs automated optical laser sensors that scan 1,000 bottles per minute and automatically push any underfilled or crookedly capped bottle off the conveyor belt. How does technology improve quality management here?","options":{"A":"It inspects 100% of output at high speed without human fatigue or sampling gaps","B":"It eliminates the need to clean bottling pipes","C":"It increases the number of faulty bottles shipped to supermarkets","D":"It allows the factory to use dirty water"},"correctOption":"A","correctAnswer":"It inspects 100% of output at high speed without human fatigue or sampling gaps","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automated optical inspection checks every single unit instantaneously with consistent accuracy, overcoming the limits of human sample checking.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because bottling equipment still requires regular sanitation.","C":"Incorrect because rejecting faulty bottles prevents them from reaching supermarkets.","D":"Incorrect because beverage safety laws require purified water."}}},{"id":"P1_U4_MCQ_229","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_229","question":"At an audio equipment manufacturer, assembly teams empowered under a quality assurance system celebrate achieving six consecutive months with zero customer returns. How does quality assurance positively influence workforce motivation?","options":{"A":"Being trusted to monitor standards and solve quality issues gives employees pride, ownership, and job satisfaction","B":"Employees receive zero wages whenever a defect is prevented","C":"Quality assurance removes all teamwork from the factory floor","D":"Employees no longer have to follow any production schedules"},"correctOption":"A","correctAnswer":"Being trusted to monitor standards and solve quality issues gives employees pride, ownership, and job satisfaction","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because empowering workers to manage quality rather than policing them with inspectors boosts self-esteem, teamwork, and motivation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because employees are paid their normal wages and often receive bonuses for strong quality performance.","C":"Incorrect because quality assurance relies on collaboration across consecutive production stages.","D":"Incorrect because quality assurance operates alongside planned production schedules."}}},{"id":"P1_U4_MCQ_230","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_230","question":"A luxury sports car costing $220,000 suffers repeated electrical breakdowns during its first month on the road, infuriating buyers. Why does this car fail the Business Studies definition of quality despite its high price?","options":{"A":"Quality depends on meeting customer expectations and reliability, not merely charging a high price","B":"Sports cars are never expected to run reliably","C":"Only budget cars under $15,000 can be classified as good quality","D":"Electrical faults improve a sports car's brand image"},"correctOption":"A","correctAnswer":"Quality depends on meeting customer expectations and reliability, not merely charging a high price","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because customers paying $220,000 expect exceptional reliability; breaking down repeatedly means the car fails to meet customer expectations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because buyers of luxury cars have very high expectations for performance and reliability.","C":"Incorrect because any price tier can achieve good quality if it meets its target customers' expectations.","D":"Incorrect because frequent breakdowns severely damage brand reputation."}}},{"id":"P1_U4_MCQ_231","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_231","question":"A sugar refining company extracts raw sugar from bulky sugar cane stalks, where 10 tonnes of harvested cane yield only 1 tonne of refined sugar. Where should the company locate its refinery to minimize transport costs?","options":{"A":"Right next to the sugar cane plantations so heavy waste plant material is not transported long distances","B":"In the centre of a distant capital city far from farms","C":"On a mountain peak with no road access","D":"Next to a luxury shopping mall"},"correctOption":"A","correctAnswer":"Right next to the sugar cane plantations so heavy waste plant material is not transported long distances","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sugar refining is a weight-losing (bulk-reducing) process; locating at the raw material source avoids paying freight on 9 tonnes of waste cane per tonne of sugar.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because transporting 10 times more weight in raw cane to a high-rent city centre would be prohibitively costly.","C":"Incorrect because lack of road infrastructure makes shipping sugar impossible.","D":"Incorrect because industrial sugar refineries do not locate beside retail shopping malls."}}},{"id":"P1_U4_MCQ_232","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_232","question":"A flat-pack furniture manufacturer imports compact sheets of compressed wood and assembles them into bulky wardrobes and sofas that take up four times more lorry space than the flat sheets. Where is the most economical location for its assembly factory?","options":{"A":"Inside the remote forest where the trees are felled","B":"Close to major urban consumer markets to minimize expensive transport of bulky assembled furniture","C":"On a small island with no ferry or bridge links","D":"In an area with no roads or railway connections"},"correctOption":"B","correctAnswer":"Close to major urban consumer markets to minimize expensive transport of bulky assembled furniture","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because assembling bulky finished furniture near major population centres minimizes high distribution costs for large, space-consuming items.","distractor_reasons":{"A":"Incorrect because shipping bulky assembled wardrobes long distances from a remote forest costs far more than shipping compact wood sheets.","B":"Correct selection.","C":"Incorrect because lack of transport links would prevent delivering furniture to customers.","D":"Incorrect because bulky furniture distribution requires good road and rail networks."}}},{"id":"P1_U4_MCQ_233","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_233","question":"A precision optical lens manufacturer plans to open a new factory requiring 120 master lens grinders and optical engineers. Which location factor is most decisive for this business?","options":{"A":"Proximity to a region with an established pool of workers possessing specialist optical engineering skills","B":"Availability of low-wage seasonal fruit pickers","C":"High pedestrian shopping footfall outside the factory gate","D":"Proximity to open-cast coal mines"},"correctOption":"A","correctAnswer":"Proximity to a region with an established pool of workers possessing specialist optical engineering skills","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because precision industries depend on specialist technical labour, making locations with an existing skilled workforce or technical institutes ideal.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because seasonal agricultural workers lack precision optical grinding skills.","C":"Incorrect because optical lens manufacturers supply camera and medical companies rather than passing pedestrians.","D":"Incorrect because modern optical factories do not rely on coal mines."}}},{"id":"P1_U4_MCQ_234","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_234","question":"A hand-stitched football manufacturer relies heavily on manual stitching and plans to build a new factory employing 600 workers. Which location factor will most reduce its unit production costs?","options":{"A":"Locating in a city financial district with the highest salaries in the country","B":"Locating in a region with an abundant supply of low-cost labour","C":"Locating next to an aerospace wind-tunnel research facility","D":"Locating inside a protected national wildlife park"},"correctOption":"B","correctAnswer":"Locating in a region with an abundant supply of low-cost labour","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because labour-intensive manufacturers keep unit costs competitive by locating where large numbers of workers are available at lower wage rates.","distractor_reasons":{"A":"Incorrect because high salaries in financial districts would make labour-intensive football stitching uneconomical.","B":"Correct selection.","C":"Incorrect because aerospace research facilities are irrelevant to hand-stitched footballs.","D":"Incorrect because factories are banned from locating inside protected wildlife reserves."}}},{"id":"P1_U4_MCQ_235","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_235","question":"A parcel distribution and logistics hub chooses a site directly adjacent to a major motorway intersection, a freight railway terminal, and an international cargo airport. Which location factor is driving this decision?","options":{"A":"Excellent transport and infrastructure links for fast nationwide and international distribution","B":"Proximity to perishable agricultural farms","C":"High local pedestrian shopping footfall","D":"Warm tropical beach climate for holidaymakers"},"correctOption":"A","correctAnswer":"Excellent transport and infrastructure links for fast nationwide and international distribution","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because logistics hubs depend on fast, reliable road, rail, and air infrastructure to receive and dispatch goods efficiently.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because general parcel hubs handle diverse goods rather than perishable crops.","C":"Incorrect because freight hubs operate with trucks and planes rather than walk-in shoppers.","D":"Incorrect because beach climate is relevant to tourism rather than freight logistics."}}},{"id":"P1_U4_MCQ_236","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_236","question":"A data-centre operator builds a massive server facility in Iceland because cold ambient temperatures naturally cool the servers and abundant geothermal energy provides cheap, continuous electricity. Which location factor is most important here?","options":{"A":"Reliable, low-cost power supply and favourable natural cooling conditions","B":"High walk-in retail footfall from local shoppers","C":"Proximity to heavy iron-ore mines","D":"Abundant unskilled agricultural labour"},"correctOption":"A","correctAnswer":"Reliable, low-cost power supply and favourable natural cooling conditions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because data centres consume vast amounts of electricity for servers and cooling, making cheap, reliable power and cool climates decisive.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because data centres serve global internet traffic remotely without walk-in customers.","C":"Incorrect because server farms do not process iron ore.","D":"Incorrect because data centres are capital-intensive and employ few unskilled workers."}}},{"id":"P1_U4_MCQ_237","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_237","question":"To attract manufacturers to an old shipbuilding town with 18% unemployment, the government designates it an 'Enterprise Zone' offering five years of zero property taxes and cash grants for machinery purchases. How does this influence business location decisions?","options":{"A":"Government financial incentives lower setup and operating costs, encouraging firms to locate in deprived areas","B":"Government grants force businesses to pay higher corporate taxes","C":"Enterprise zones ban factories from hiring local unemployed workers","D":"Financial incentives only apply to high-street coffee shops"},"correctOption":"A","correctAnswer":"Government financial incentives lower setup and operating costs, encouraging firms to locate in deprived areas","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because governments use tax breaks and grants to offset location disadvantages and stimulate job creation in high-unemployment regions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because enterprise zones reduce rather than increase tax burdens.","C":"Incorrect because the goal of enterprise zones is to employ local jobseekers.","D":"Incorrect because industrial grants specifically target manufacturing and job-creating enterprises."}}},{"id":"P1_U4_MCQ_238","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_238","question":"A concrete-mixing plant operating heavy lorries 24 hours a day is denied permission to locate next to a suburban housing estate and primary school. Which location factor prevented this choice?","options":{"A":"Government planning and environmental controls protecting residential areas from noise, dust, and traffic","B":"Lack of concrete demand in suburban towns","C":"Excessive government subsidies in residential neighbourhoods","D":"High pedestrian footfall outside primary schools"},"correctOption":"A","correctAnswer":"Government planning and environmental controls protecting residential areas from noise, dust, and traffic","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because local planning laws restrict noisy, dusty, heavy-traffic industrial sites from operating beside homes and schools.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because suburbs actually have strong construction demand, but zoning laws forbid noisy plants beside homes.","C":"Incorrect because governments do not subsidize heavy concrete plants inside residential areas.","D":"Incorrect because high footfall near schools is a safety hazard for heavy lorries, not an advantage."}}},{"id":"P1_U4_MCQ_239","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_239","question":"A chain of convenience supermarkets opens new stores next to busy commuter railway stations and densely populated apartment complexes. Why is this location strategy essential for a retail service business?","options":{"A":"Customers buy convenience groceries frequently and require easy, immediate access near home or travel routes","B":"Supermarkets need large coal mines nearby to power their tills","C":"Rent next to commuter stations is the cheapest land in the country","D":"Convenience stores operate 24-hour heavy steel assembly lines"},"correctOption":"A","correctAnswer":"Customers buy convenience groceries frequently and require easy, immediate access near home or travel routes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retail services rely on direct customer visits and high footfall, making convenient proximity to shoppers decisive.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supermarkets connect to standard electrical grids and do not need coal mines.","C":"Incorrect because prime commuter sites have high rents, which are justified by high customer volume.","D":"Incorrect because supermarkets are retail service outlets rather than heavy factories."}}},{"id":"P1_U4_MCQ_240","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_240","question":"A cloud-accounting software firm serves 15,000 small business clients across the country entirely online, allowing it to locate its headquarters in a scenic, low-rent regional town rather than an expensive capital city. How has technology influenced this location decision?","options":{"A":"High-speed internet allows digital service businesses without face-to-face contact to locate in lower-cost areas","B":"Clients travel to the regional town every week to collect floppy disks","C":"Capital cities no longer allow software companies to rent offices","D":"Cloud software requires proximity to heavy shipping ports"},"correctOption":"A","correctAnswer":"High-speed internet allows digital service businesses without face-to-face contact to locate in lower-cost areas","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internet and telecommunications remove the need for physical proximity to customers for digital service firms, reducing premises costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cloud software is delivered and supported entirely online.","C":"Incorrect because software firms can locate in cities, but high rents make regional towns more cost-effective.","D":"Incorrect because digital software does not require physical maritime freight."}}},{"id":"P1_U4_MCQ_241","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_241","question":"An independent physiotherapy clinic owner opens her practice in the coastal village where she lives so she can spend more time with her young children and avoid commuting. Which location factor is most evident here?","options":{"A":"Personal preference of the business owner","B":"Proximity to weight-losing raw materials","C":"Access to deep-water container ports","D":"Government export tariff exemptions"},"correctOption":"A","correctAnswer":"Personal preference of the business owner","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sole traders and small service owners often prioritize family life, commute times, and personal lifestyle when choosing a business location.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because physiotherapy is a personal healthcare service using no heavy raw materials.","C":"Incorrect because a local clinic does not import or export shipping containers.","D":"Incorrect because local healthcare services do not export physical goods."}}},{"id":"P1_U4_MCQ_242","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_242","question":"Several artificial intelligence and cybersecurity start-ups locate in a science park right next to a world-renowned computer science university. What is the main advantage of this location?","options":{"A":"Easy recruitment of highly skilled computing graduates and access to university research facilities","B":"Abundant supply of low-paid manual farm workers","C":"Proximity to heavy railway freight yards for coal deliveries","D":"Zero rent and zero electricity bills"},"correctOption":"A","correctAnswer":"Easy recruitment of highly skilled computing graduates and access to university research facilities","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because knowledge-intensive service firms cluster near leading universities to recruit specialist graduates and collaborate on research.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because AI start-ups require specialist computer scientists rather than manual farm workers.","C":"Incorrect because software start-ups do not use coal freight.","D":"Incorrect because science park tenants still pay rent and utility bills."}}},{"id":"P1_U4_MCQ_243","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_243","question":"A sports injury clinic and a healthy smoothie bar both rent units inside a busy multi-sport leisure centre and gym complex. Why is locating near complementary businesses advantageous for these services?","options":{"A":"The gym attracts a high concentration of fitness-minded customers who are likely to buy smoothies and physiotherapy","B":"Complementary businesses pay each other's staff wages","C":"Rent inside busy leisure complexes is completely free","D":"It reduces the weight of raw steel transported to the gym"},"correctOption":"A","correctAnswer":"The gym attracts a high concentration of fitness-minded customers who are likely to buy smoothies and physiotherapy","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because locating beside complementary services shares customer footfall from the same target market, boosting sales.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because each business remains independent and pays its own staff.","C":"Incorrect because prime retail units inside busy complexes charge commercial rent.","D":"Incorrect because these are consumer service businesses, not steel processors."}}},{"id":"P1_U4_MCQ_244","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_244","question":"An online-only book retailer sells exclusively via its website and dispatches parcels by courier, so it locates its distribution warehouse on an inexpensive out-of-town industrial estate rather than a high street. Why is this location optimal?","options":{"A":"Since customers order online rather than visiting in person, the retailer avoids expensive high-street rent while keeping good lorry access","B":"Books are perishable products that spoil within two hours","C":"High streets ban delivery vans from ever entering towns","D":"Out-of-town industrial estates have the highest pedestrian shopping footfall"},"correctOption":"A","correctAnswer":"Since customers order online rather than visiting in person, the retailer avoids expensive high-street rent while keeping good lorry access","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because e-commerce retailers do not need costly high-street footfall; out-of-town warehouses offer much lower rent per square metre and easy motorway access.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because books are durable goods, not perishable food.","C":"Incorrect because delivery vans service high streets, though out-of-town estates offer far easier motorway access.","D":"Incorrect because industrial estates have low pedestrian footfall compared with high streets."}}},{"id":"P1_U4_MCQ_245","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_245","question":"A Japanese television manufacturer opens an assembly plant in Mexico to supply North American retailers duty-free under a regional trade agreement, avoiding heavy import tariffs charged on TVs shipped from Asia. Which reason for international location does this show?","options":{"A":"Avoiding import tariffs and trade barriers by producing inside a free-trade area","B":"Increasing shipping distances to North American stores","C":"Paying higher corporate tax rates than in Japan","D":"Avoiding all product safety testing"},"correctOption":"A","correctAnswer":"Avoiding import tariffs and trade barriers by producing inside a free-trade area","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because locating production inside a trade bloc allows foreign manufacturers to bypass import tariffs and quotas.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because producing in Mexico shortens rather than increases shipping distances to North America.","C":"Incorrect because firms seek lower, not higher, tax burdens when locating abroad.","D":"Incorrect because products sold in North America must still pass all safety regulations."}}},{"id":"P1_U4_MCQ_246","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_246","question":"A European wood-pulp and paper producer builds a new mill in Brazil close to fast-growing eucalyptus plantations where timber is abundant and inexpensive. Which advantage of locating operations abroad does this illustrate?","options":{"A":"Direct access to abundant, lower-cost raw materials at the source","B":"Elimination of all language differences between Europe and Brazil","C":"Higher transport costs for raw timber logs","D":"Zero initial capital cost to construct the paper mill"},"correctOption":"A","correctAnswer":"Direct access to abundant, lower-cost raw materials at the source","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because locating close to overseas raw material supplies secures reliable inputs at lower cost and avoids shipping bulky raw timber.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because operating in Brazil still requires managing Portuguese-English language differences.","C":"Incorrect because locating beside the plantations reduces rather than increases raw timber transport costs.","D":"Incorrect because building a paper mill requires substantial capital expenditure."}}},{"id":"P1_U4_MCQ_247","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_247","question":"A technology hardware firm establishes its regional assembly and distribution hub in Singapore because of low corporate tax rates, streamlined business regulations, and world-class port infrastructure. Which international location factors are attracting this business?","options":{"A":"Lower taxation, supportive regulatory environment, and strong infrastructure","B":"High import tariffs and strict quotas on electronics","C":"Abundant cheap agricultural land for cattle farming","D":"Severe shortages of electricity and internet connectivity"},"correctOption":"A","correctAnswer":"Lower taxation, supportive regulatory environment, and strong infrastructure","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because favourable tax regimes, transparent laws, and efficient transport/IT infrastructure make countries attractive for multinational operations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Singapore is a free-trade hub with low tariffs rather than strict trade barriers.","C":"Incorrect because Singapore is an urban city-state focused on high-tech industry and trade, not cattle farming.","D":"Incorrect because Singapore possesses highly reliable power and telecommunications infrastructure."}}},{"id":"P1_U4_MCQ_248","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_248","question":"A UK-based manufacturer opens a factory in another country, but when the foreign currency suddenly depreciates by 25% against the British pound, the value of profits sent back to the UK falls sharply. Which risk of locating abroad does this illustrate?","options":{"A":"Exchange rate fluctuations reducing the home-currency value of overseas profits or raising imported input costs","B":"Excessive bulk-buying discounts from local suppliers","C":"Too many government grants in the host country","D":"Complete elimination of competition in the UK"},"correctOption":"A","correctAnswer":"Exchange rate fluctuations reducing the home-currency value of overseas profits or raising imported input costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because operating across borders exposes businesses to exchange rate movements that can erode repatriated profits or inflate imported component bills.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because bulk discounts increase profits rather than reducing them.","C":"Incorrect because government grants are a financial advantage, not a currency risk.","D":"Incorrect because domestic UK competition still exists."}}},{"id":"P1_U4_MCQ_249","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_249","question":"A foreign mining company invests $150 million in a developing country, only for a newly elected government to suddenly triple mining royalties and impose strict export bans. Which drawback of international location does this demonstrate?","options":{"A":"Political instability and sudden changes in host-country government policies or regulations","B":"Low domestic wage rates in the mining company's home country","C":"Lack of mineral deposits in the host country","D":"Excessive customer loyalty among local shoppers"},"correctOption":"A","correctAnswer":"Political instability and sudden changes in host-country government policies or regulations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because political instability or unexpected regulatory and tax changes by foreign governments can jeopardize major overseas investments.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the problem stems from sudden foreign tax and export changes, not home-country wages.","C":"Incorrect because the mine has mineral deposits, but government policy changes threaten profitability.","D":"Incorrect because customer loyalty is unrelated to government mining royalties."}}},{"id":"P1_U4_MCQ_250","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_250","question":"A heritage British vacuum-cleaner brand closes its UK assembly plant—making 800 local workers redundant—to move production to a lower-wage country, sparking boycotts from angry domestic consumers. Which risk of relocating abroad is shown here?","options":{"A":"Negative publicity and customer boycotts in the home market due to domestic job losses","B":"Higher hourly factory wages in the new overseas plant","C":"Inability to sell vacuum cleaners outside the UK","D":"Immediate elimination of all shipping costs"},"correctOption":"A","correctAnswer":"Negative publicity and customer boycotts in the home market due to domestic job losses","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because closing domestic factories to move jobs overseas often provokes trade union protests, negative media coverage, and consumer boycotts at home.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the firm moved abroad specifically to pay lower, not higher, hourly wages.","C":"Incorrect because relocating production abroad does not prevent global sales.","D":"Incorrect because shipping finished vacuum cleaners back to the UK increases rather than eliminates shipping costs."}}},{"id":"P1_U4_MCQ_251","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_251","question":"An artisan bakery buys flour, butter, and sugar for $0.80 per loaf, pays bakers $1.20 per loaf in wages, and sells each finished loaf for $4.50. What is the added value per loaf created by the bakery's operations?","options":{"A":"$2.50","B":"$3.70","C":"$4.50","D":"$2.00"},"correctOption":"B","correctAnswer":"$3.70","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value is the difference between the selling price of the finished product ($4.50) and the cost of bought-in raw materials ($0.80), which equals $3.70.","distractor_reasons":{"A":"Incorrect because $2.50 subtracts both raw materials ($0.80) and internal labour wages ($1.20), which gives profit per unit rather than added value.","B":"Correct selection.","C":"Incorrect because $4.50 is the selling price before deducting the cost of bought-in ingredients.","D":"Incorrect because $2.00 is the sum of ingredient and wage costs ($0.80 + $1.20) rather than added value."}}},{"id":"P1_U4_MCQ_252","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_252","question":"A bottling plant employs 45 production workers who together produce 18,000 bottles of mineral water per day. What is the daily labour productivity of this plant?","options":{"A":"18,000 bottles per day","B":"400 bottles per employee","C":"45 bottles per employee","D":"810,000 bottles per day"},"correctOption":"B","correctAnswer":"400 bottles per employee","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because labour productivity equals total output per period (18,000 bottles) divided by the number of employees (45), giving 400 bottles per employee.","distractor_reasons":{"A":"Incorrect because 18,000 bottles is the total level of production (output), not output per employee.","B":"Correct selection.","C":"Incorrect because 45 is the number of workers rather than the output produced per worker.","D":"Incorrect because this multiplies output by the number of employees instead of dividing output by employees."}}},{"id":"P1_U4_MCQ_253","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_253","question":"In Year 1, a furniture workshop made 8,000 chairs using 16 workers, and in Year 2 it made 9,000 chairs after hiring 4 extra workers. How did production and labour productivity change between Year 1 and Year 2?","options":{"A":"Both production and labour productivity increased","B":"Production fell, while labour productivity rose","C":"Production rose, while labour productivity fell from 500 to 450 chairs per worker","D":"Both production and labour productivity fell"},"correctOption":"C","correctAnswer":"Production rose, while labour productivity fell from 500 to 450 chairs per worker","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total output (production) increased from 8,000 to 9,000 chairs, while labour productivity decreased from 500 (8,000 / 16) to 450 (9,000 / 20) chairs per worker.","distractor_reasons":{"A":"Incorrect because although total output rose by 1,000 chairs, output per employee fell by 50 chairs.","B":"Incorrect because total production increased from 8,000 to 9,000 chairs.","C":"Correct selection.","D":"Incorrect because total output increased rather than decreased."}}},{"id":"P1_U4_MCQ_254","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_254","question":"A shoe manufacturer introduces piece-rate pay bonuses and upgrades its leather-cutting machines, causing labour productivity to rise by 25%. Why does higher labour productivity make the business more competitive?","options":{"A":"It lowers average labour costs per pair of shoes, allowing the firm to cut prices or earn higher profit margins","B":"It forces competitors to pay higher rent for their factories","C":"It eliminates the need to buy leather and rubber soles","D":"It increases the number of defective shoes made per shift"},"correctOption":"A","correctAnswer":"It lowers average labour costs per pair of shoes, allowing the firm to cut prices or earn higher profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because producing more output per worker reduces average unit labour costs, enabling lower prices or higher profits per unit sold.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because one firm's productivity does not change competitors' property rent.","C":"Incorrect because raw materials still must be purchased for every shoe manufactured.","D":"Incorrect because improved equipment and efficiency generally reduce rather than increase defects."}}},{"id":"P1_U4_MCQ_255","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_255","question":"An automotive components plant operates in a country with high minimum wages and strict union agreements, so managers invest heavily in automated robotic welders operated by a few technicians. Which type of production process is this?","options":{"A":"Labour-intensive production","B":"Job production","C":"Capital-intensive production","D":"Batch weaving"},"correctOption":"C","correctAnswer":"Capital-intensive production","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital-intensive production relies heavily on machinery, automation, and equipment rather than large numbers of manual workers.","distractor_reasons":{"A":"Incorrect because labour-intensive production uses a high proportion of human workers relative to machinery.","B":"Incorrect because job production refers to creating unique one-off items for individual clients.","C":"Correct selection.","D":"Incorrect because batch weaving describes textile manufacturing in groups."}}},{"id":"P1_U4_MCQ_256","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_256","question":"A hand-crafted rug manufacturer operates in a region with abundant, low-wage skilled weavers and uses traditional wooden looms rather than automated machinery. What is a main advantage of this labour-intensive approach?","options":{"A":"Average costs remain very low without requiring huge upfront capital spending on expensive machinery","B":"Every rug is produced automatically 24 hours a day without human workers","C":"The business achieves the highest possible hourly output per employee","D":"Workers never require rest breaks or holidays"},"correctOption":"A","correctAnswer":"Average costs remain very low without requiring huge upfront capital spending on expensive machinery","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because where wages are low and products benefit from manual flexibility, labour-intensive production avoids heavy capital expenditure and loan interest.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 24-hour automatic production describes capital-intensive automation.","C":"Incorrect because capital-intensive machinery achieves higher output per worker than manual looms.","D":"Incorrect because human workers always require rest breaks and leave."}}},{"id":"P1_U4_MCQ_257","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_257","question":"In a commercial kitchen, chefs spend 45 minutes every hour walking back and forth between the stove and a walk-in refrigerator located at the far end of the building. Which lean production waste is occurring?","options":{"A":"Overproduction","B":"Defects","C":"Non-utilised skills","D":"Motion"},"correctOption":"D","correctAnswer":"Motion","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because unnecessary physical walking, reaching, or bending by workers during their tasks is classified as waste of motion.","distractor_reasons":{"A":"Incorrect because overproduction means cooking more meals than customers have ordered.","B":"Incorrect because defects refer to burnt or spoiled dishes that must be thrown away.","C":"Incorrect because non-utilised skills occur when qualified staff perform tasks below their skill level.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_258","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_258","question":"At a metal stamping plant, presses punch out 1,000 steel panels in 20 minutes, but the painting booth can only paint 400 panels per hour, leaving 600 panels sitting idle in queues between stages. Which lean production waste does this show?","options":{"A":"Waiting","B":"Over-processing","C":"Transportation","D":"Non-utilised skills"},"correctOption":"A","correctAnswer":"Waiting","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because waiting waste occurs when work-in-progress or workers sit idle between consecutive stages due to uneven production speeds.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because over-processing means performing unnecessary steps or excessive finishing on a product.","C":"Incorrect because transportation waste refers to moving materials unnecessarily across distances.","D":"Incorrect because non-utilised skills refer to underusing employee qualifications."}}},{"id":"P1_U4_MCQ_259","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_259","question":"A toy factory polishes the underside of plastic battery compartments to a mirror shine even though the plastic is permanently hidden beneath a screwed-on cover. Which waste in lean production is this?","options":{"A":"Transportation","B":"Over-processing","C":"Motion","D":"Inventory"},"correctOption":"B","correctAnswer":"Over-processing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because over-processing involves spending time and resources on extra features or finishes that add no value to the customer.","distractor_reasons":{"A":"Incorrect because transportation waste refers to moving goods unnecessarily between locations.","B":"Correct selection.","C":"Incorrect because motion waste refers to unnecessary physical movements by workers.","D":"Incorrect because inventory waste refers to storing excessive quantities of stock."}}},{"id":"P1_U4_MCQ_260","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_260","question":"A dairy processor produces 5,000 extra cartons of fresh yogurt every week beyond supermarket orders, forcing the firm to pay for extra refrigerated storage and throw away expired cartons. Which lean production waste is this?","options":{"A":"Non-utilised skills","B":"Waiting","C":"Overproduction","D":"Motion"},"correctOption":"C","correctAnswer":"Overproduction","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because overproduction occurs when a business manufactures goods without confirmed customer demand, resulting in excess storage and spoilage.","distractor_reasons":{"A":"Incorrect because non-utilised skills occur when qualified staff are given menial tasks.","B":"Incorrect because waiting waste refers to idle time between production stages.","C":"Correct selection.","D":"Incorrect because motion waste refers to unnecessary worker movement."}}},{"id":"P1_U4_MCQ_261","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_261","question":"A furniture manufacturer adopts Kaizen by holding 15-minute daily team huddles where carpenters suggest repositioning glue stations and grouping machines into U-shaped cells. What is the key benefit of Kaizen to this business?","options":{"A":"Continuous efficiency gains and waste reduction achieved at low cost while boosting worker motivation","B":"Complete replacement of all carpenters with expensive imported robots","C":"Elimination of the need to buy timber or varnish","D":"Guaranteed monopoly control over the national furniture market"},"correctOption":"A","correctAnswer":"Continuous efficiency gains and waste reduction achieved at low cost while boosting worker motivation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Kaizen uses workers' practical ideas to eliminate waste continuously without heavy capital expenditure, while raising employee morale through involvement.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Kaizen relies on worker ideas and layout improvements rather than buying expensive robotics.","C":"Incorrect because raw materials like timber and varnish are still required.","D":"Incorrect because internal efficiency gains do not legally eliminate market competitors."}}},{"id":"P1_U4_MCQ_262","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_262","question":"An electronics assembler introduces just-in-time (JIT) inventory control so microchips arrive at the factory every two hours directly from the supplier, eliminating its component warehouse. What is a major advantage of this change?","options":{"A":"Warehouse rent, insurance, and obsolescence costs fall sharply, freeing up cash flow","B":"The factory becomes completely immune to supplier transport strikes","C":"The business receives larger bulk-buying discounts from ordering once a year","D":"The factory no longer needs computerised stock-ordering software"},"correctOption":"A","correctAnswer":"Warehouse rent, insurance, and obsolescence costs fall sharply, freeing up cash flow","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because JIT reduces inventory holding costs (warehouse space, insurance, damage/obsolescence) and avoids tying up working capital in stored components.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because holding zero buffer inventory makes JIT highly vulnerable to supplier transport delays.","C":"Incorrect because JIT requires frequent small deliveries rather than huge annual bulk orders.","D":"Incorrect because JIT relies heavily on automated IT ordering systems."}}},{"id":"P1_U4_MCQ_263","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_263","question":"Why might a toy manufacturer choose NOT to adopt a strict just-in-time (JIT) inventory system when its plastic mouldings are shipped by sea from a supplier 8,000 kilometres away?","options":{"A":"Frequent small sea shipments have high delivery costs, and any shipping delay would halt the entire factory due to zero buffer stock","B":"Just-in-time systems always increase warehouse storage costs","C":"Plastic toy mouldings rot within 24 hours of manufacture","D":"Just-in-time systems are illegal for toy manufacturers"},"correctOption":"A","correctAnswer":"Frequent small sea shipments have high delivery costs, and any shipping delay would halt the entire factory due to zero buffer stock","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because long-distance international shipping has unpredictable lead times and high transport costs per small delivery, making zero-buffer JIT very risky.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because JIT reduces warehouse storage costs rather than increasing them.","C":"Incorrect because plastic mouldings are durable goods, not perishable food.","D":"Incorrect because there is no law banning JIT in toy production."}}},{"id":"P1_U4_MCQ_264","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_264","question":"A hardware wholesaler holds substantial buffer inventories of copper pipes and brass valves in its regional depot. What is the main purpose of holding this buffer inventory?","options":{"A":"To protect against unexpected surges in customer orders or sudden supplier delivery delays","B":"To maximize warehouse insurance and security expenses","C":"To ensure pipes become outdated before plumbers can buy them","D":"To reduce cash flow and increase bank overdraft interest"},"correctOption":"A","correctAnswer":"To protect against unexpected surges in customer orders or sudden supplier delivery delays","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because buffer inventory acts as a safety reserve so the business can satisfy sudden demand spikes or continue operating if a supplier is late.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher insurance and security costs are drawbacks of holding inventory, not the purpose.","C":"Incorrect because obsolescence is a risk of holding excess inventory, not an objective.","D":"Incorrect because tied-up cash is a cost of holding stock, not the reason for holding it."}}},{"id":"P1_U4_MCQ_265","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_265","question":"A luxury fashion house holds very low inventories of designer handbags at the end of each season, whereas a brick manufacturer holds three months' supply of clay bricks in its yard. Which factor best explains this difference?","options":{"A":"Fashion handbags face high risk of changing tastes making unsold stock obsolete, whereas standard clay bricks do not go out of fashion","B":"Clay bricks spoil and rot faster than leather handbags","C":"Designer handbags cost less per unit to store than clay bricks","D":"Brick manufacturers use bespoke job production for every single brick"},"correctOption":"A","correctAnswer":"Fashion handbags face high risk of changing tastes making unsold stock obsolete, whereas standard clay bricks do not go out of fashion","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fashion items quickly lose value when seasonal trends change, whereas standardized construction bricks remain sellable over long periods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because clay bricks are durable building materials and do not rot.","C":"Incorrect because luxury handbags have high value and theft-insurance costs, whereas bricks are stored outdoors in a yard.","D":"Incorrect because standard bricks are mass-produced via flow production."}}},{"id":"P1_U4_MCQ_266","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_266","question":"A portrait artist paints individual oil portraits commissioned by clients who specify the size, pose, and background scenery. Which production method is the artist using?","options":{"A":"Flow production","B":"Batch production","C":"Job production","D":"Mass customisation on an assembly line"},"correctOption":"C","correctAnswer":"Job production","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because job production creates a single, unique item tailored to an individual customer's exact specifications.","distractor_reasons":{"A":"Incorrect because flow production continuously produces large numbers of identical items.","B":"Incorrect because batch production makes groups of identical items together.","C":"Correct selection.","D":"Incorrect because a portrait painter works individually by hand rather than on an assembly line."}}},{"id":"P1_U4_MCQ_267","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_267","question":"A biscuit factory bakes 10,000 chocolate-chip biscuits in the morning, cleans and resets the dough mixers and ovens, and then bakes 10,000 oat-and-raisin biscuits in the afternoon. Which production method is this?","options":{"A":"Job production","B":"Batch production","C":"Flow production","D":"Just-in-time retail service"},"correctOption":"B","correctAnswer":"Batch production","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because batch production manufactures a set quantity (batch) of one product before resetting machinery to make a batch of another variant.","distractor_reasons":{"A":"Incorrect because job production creates single bespoke items for individual customers.","B":"Correct selection.","C":"Incorrect because flow production runs continuously making a single standardized item without stopping to switch recipes.","D":"Incorrect because this is a food manufacturing process, not a retail service."}}},{"id":"P1_U4_MCQ_268","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_268","question":"A cement manufacturer runs an automated rotary kiln and bagging line 24 hours a day, 365 days a year, producing millions of identical 50 kg bags of standard Portland cement. Which production method is being used?","options":{"A":"Job production","B":"Batch production","C":"Flow production","D":"Labour-intensive craft production"},"correctOption":"C","correctAnswer":"Flow production","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because flow production manufactures large volumes of a standardized product continuously without interruption.","distractor_reasons":{"A":"Incorrect because job production makes unique one-off products to individual customer orders.","B":"Incorrect because batch production stops periodically to switch to a different product group.","C":"Correct selection.","D":"Incorrect because a 24-hour rotary kiln and bagging line is capital-intensive flow production."}}},{"id":"P1_U4_MCQ_269","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_269","question":"A glass-bottle factory uses continuous flow production where furnaces must stay heated at 1,500°C around the clock. What is a major risk of this production method if a conveyor belt breaks down or demand suddenly drops?","options":{"A":"Stoppages are very expensive because the entire integrated line halts while high fixed costs continue, and unsold stock builds up if demand falls","B":"The factory can switch immediately to hand-blowing bespoke vases at zero cost","C":"Variable raw material costs disappear whenever a machine stops","D":"Workers become overly excited by the high variety of daily tasks"},"correctOption":"A","correctAnswer":"Stoppages are very expensive because the entire integrated line halts while high fixed costs continue, and unsold stock builds up if demand falls","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because flow production is inflexible and capital-intensive: a breakdown halts the whole line, and falling demand creates huge unsold inventories or costly furnace shutdowns.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because specialized automated flow machinery cannot easily switch to bespoke manual glassblowing.","C":"Incorrect because keeping furnaces heated and paying fixed overheads still incurs heavy costs during stoppages.","D":"Incorrect because flow production tasks are repetitive and monotonous rather than varied."}}},{"id":"P1_U4_MCQ_270","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_270","question":"A small start-up jewellery business has very little capital to buy machinery and makes custom-engraved silver rings only after receiving individual customer orders. Which production method should it use?","options":{"A":"Flow production, because start-ups always have huge mass-market demand","B":"Job production, because it requires low capital investment and suits unique customer-ordered pieces","C":"Batch production of 50,000 identical rings before testing customer interest","D":"Automated 24-hour robotic assembly"},"correctOption":"B","correctAnswer":"Job production, because it requires low capital investment and suits unique customer-ordered pieces","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because job production suits small businesses with limited capital making customized items to individual customer specifications.","distractor_reasons":{"A":"Incorrect because start-ups rarely have huge immediate mass demand or the capital for flow lines.","B":"Correct selection.","C":"Incorrect because producing 50,000 identical rings upfront would tie up cash in unsold stock and prevent custom engraving.","D":"Incorrect because automated robotics requires large capital expenditure unsuitable for a small bespoke start-up."}}},{"id":"P1_U4_MCQ_271","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_271","question":"Compared with job production, why does batch production allow a clothing manufacturer to charge lower prices for school uniforms?","options":{"A":"Making groups of identical uniforms allows bulk fabric discounts and faster specialized sewing machines, lowering average unit cost","B":"Batch production eliminates all fabric and thread costs","C":"Every single student's uniform is designed from scratch by a luxury fashion designer","D":"Batch production requires zero quality checks"},"correctOption":"A","correctAnswer":"Making groups of identical uniforms allows bulk fabric discounts and faster specialized sewing machines, lowering average unit cost","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because producing groups of identical items spreads setup time over larger runs and unlocks bulk material discounts, lowering average cost per uniform.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fabric and thread are still required for every uniform.","C":"Incorrect because individual bespoke design describes job production, which increases costs.","D":"Incorrect because quality checks are still needed in batch production."}}},{"id":"P1_U4_MCQ_272","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_272","question":"A restaurant kitchen prepares 30 litres of tomato soup base each morning in a large kettle, then ladles portions into individual bowls and adds custom toppings when diners order. Which combination of production methods is shown here?","options":{"A":"Batch production for the soup base followed by job production to customize each diner's bowl","B":"Flow production for the soup base followed by heavy steel smelting","C":"Job production for the soup base followed by flow production for individual bowls","D":"Pure automated flow production with zero chefs"},"correctOption":"A","correctAnswer":"Batch production for the soup base followed by job production to customize each diner's bowl","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cooking 30 litres of identical soup base together is batch production, while finishing individual bowls to each customer's topping request is job production.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because steel smelting has nothing to do with restaurant food preparation.","C":"Incorrect because the order is reversed: the base is made in a batch first, then customized per order.","D":"Incorrect because chefs prepare and finish the dishes in the restaurant kitchen."}}},{"id":"P1_U4_MCQ_273","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_273","question":"A timber mill replaces hand axes and two-person manual saws with electric circular saws that workers guide and switch on for each log. How does this mechanisation differ from full automation?","options":{"A":"In mechanisation, human workers still directly operate and control the machines, whereas automation uses computers to run processes automatically","B":"Mechanisation requires computers to run the mill with zero human staff","C":"Mechanisation is always more expensive than installing full robotics","D":"Automation uses only hand tools without electricity"},"correctOption":"A","correctAnswer":"In mechanisation, human workers still directly operate and control the machines, whereas automation uses computers to run processes automatically","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mechanisation provides workers with power-driven machines that they operate directly, while automation relies on computer-controlled systems operating independently.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because running processes via computers without human operators defines automation, not mechanisation.","C":"Incorrect because full computer-controlled automation is far costlier than basic mechanised power tools.","D":"Incorrect because automation relies heavily on electrical power and computerised machinery."}}},{"id":"P1_U4_MCQ_274","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_274","question":"An automotive styling team uses Computer-Aided Design (CAD) software to adjust the curves of a new electric car's body and calculate wind resistance instantly on screen. Which advantage of CAD does this illustrate?","options":{"A":"Designs can be modified and tested quickly without repeatedly building expensive physical clay models","B":"CAD software automatically stamps metal car doors on the factory floor","C":"CAD scans customer credit cards at car dealerships","D":"CAD eliminates the need for electricity in the design studio"},"correctOption":"A","correctAnswer":"Designs can be modified and tested quickly without repeatedly building expensive physical clay models","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because CAD allows designers to alter dimensions, view 3D models, and run performance simulations rapidly at low cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because physical manufacturing on the factory floor is CAM, not CAD.","C":"Incorrect because payment processing at retail outlets uses EFTPOS/contactless terminals.","D":"Incorrect because CAD runs on powerful computer workstations that require electricity."}}},{"id":"P1_U4_MCQ_275","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_275","question":"A furniture factory feeds digital cabinet measurements directly into Computer-Aided Manufacturing (CAM) drilling and routing machines that cut hundreds of identical panels without human measurement errors. What is a major benefit of CAM?","options":{"A":"Higher precision, consistent quality, and faster production speeds than manual cutting","B":"Zero initial purchase cost for the computer-controlled machines","C":"Elimination of the need to buy wooden boards","D":"Greater variation between each cabinet panel produced"},"correctOption":"A","correctAnswer":"Higher precision, consistent quality, and faster production speeds than manual cutting","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because CAM automates physical machining directly from digital instructions, achieving consistent accuracy and higher speed.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because CAM equipment requires significant upfront capital expenditure.","C":"Incorrect because raw timber boards are still required to make cabinets.","D":"Incorrect because CAM reduces variation so every panel matches exact specifications."}}},{"id":"P1_U4_MCQ_276","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_276","question":"A hearing-aid manufacturer scans the exact shape of a patient's ear canal and uses a 3D printer to produce a custom-fitted plastic shell overnight. Why is 3D printing ideal for this product?","options":{"A":"It produces complex, individually customized shapes directly from digital scans without expensive custom moulds","B":"It produces 100,000 identical hearing aids per minute on a flow line","C":"It requires no digital design file or computer software","D":"It uses zero raw materials to create the plastic shell"},"correctOption":"A","correctAnswer":"It produces complex, individually customized shapes directly from digital scans without expensive custom moulds","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 3D printing excels at manufacturing unique, bespoke shapes layer-by-layer from digital files without needing costly traditional tooling.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because each patient's ear canal is unique, and 3D printing builds items one layer at a time rather than 100,000 per minute.","C":"Incorrect because 3D printers operate directly from digital 3D CAD/scan files.","D":"Incorrect because 3D printers consume polymer or metal printing materials."}}},{"id":"P1_U4_MCQ_277","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_277","question":"A clothing retailer uses Electronic Point of Sale (EPOS) scanners at its store checkouts linked directly to its central warehouse computer system. How does EPOS support lean inventory management?","options":{"A":"It automatically deducts sold items from stock records and triggers reorders only when needed, preventing overstocking and stockouts","B":"It sews extra shirts automatically in the store stockroom","C":"It forces customers to wait longer at checkout queues","D":"It eliminates the need to transport clothes from the warehouse to stores"},"correctOption":"A","correctAnswer":"It automatically deducts sold items from stock records and triggers reorders only when needed, preventing overstocking and stockouts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because EPOS tracks exact sales in real time and sends automated reorder signals, keeping inventory levels lean and accurate.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because EPOS is a retail sales and inventory tracking system, not a sewing machine.","C":"Incorrect because barcode scanning speeds up checkouts rather than slowing them down.","D":"Incorrect because physical stock still must be delivered by trucks to replenish stores."}}},{"id":"P1_U4_MCQ_278","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_278","question":"A metro rail operator replaces paper ticket booths with contactless card and smartphone tap-in gates across all stations. What are two benefits of this technology for the service business?","options":{"A":"Faster passenger flow through gates and lower wage and cash-handling costs","B":"Higher paper ticket printing bills and longer queues at stations","C":"Increased need to employ ticket-booth cashiers at every entrance","D":"Elimination of the need to maintain trains and tracks"},"correctOption":"A","correctAnswer":"Faster passenger flow through gates and lower wage and cash-handling costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because contactless tap-in gates process passengers within fractions of a second while reducing ticket-printing, cash-counting, and booth staffing expenses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because contactless tap-in eliminates paper tickets and shortens queues.","C":"Incorrect because automated tap-in gates reduce rather than increase the need for booth cashiers.","D":"Incorrect because physical trains and tracks still require regular engineering maintenance."}}},{"id":"P1_U4_MCQ_279","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_279","question":"A fast-food restaurant chain installs touchscreen self-ordering kiosks in its branches so customers can customize burgers and pay electronically without waiting at a counter. How does this improve service operations?","options":{"A":"It speeds up order taking, reduces order miscommunication errors, and allows staff to focus on food preparation","B":"It cooks the burgers automatically inside the touchscreen","C":"It guarantees that electricity bills fall to zero","D":"It prevents customers from choosing meal upgrades or drinks"},"correctOption":"A","correctAnswer":"It speeds up order taking, reduces order miscommunication errors, and allows staff to focus on food preparation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because touchscreen kiosks send accurate customer orders straight to the kitchen, cutting counter queues and freeing staff for food assembly.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because kitchen staff and cooking equipment still prepare the food.","C":"Incorrect because running touchscreen kiosks consumes electricity.","D":"Incorrect because digital kiosks typically prompt customers with meal upgrades and add-ons, increasing average spend."}}},{"id":"P1_U4_MCQ_280","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_280","question":"An e-commerce fashion retailer uses artificial intelligence (AI) software to analyse millions of past customer purchases and return rates so it can forecast how many units of each coat size to manufacture next winter. How does this AI tool help operations?","options":{"A":"It reduces overproduction and unsold excess inventory by matching production quantities more closely to predicted demand","B":"It eliminates the need to buy fabric or employ garment workers","C":"It guarantees that weather will never be warm in winter","D":"It replaces delivery vans with customer chatbots"},"correctOption":"A","correctAnswer":"It reduces overproduction and unsold excess inventory by matching production quantities more closely to predicted demand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because AI demand forecasting identifies buying patterns accurately, helping operations avoid costly overproduction or stockouts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because physical coats still must be manufactured from fabric.","C":"Incorrect because AI forecasts demand patterns; it cannot control external weather.","D":"Incorrect because physical parcels still require courier delivery."}}},{"id":"P1_U4_MCQ_281","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_281","question":"A small independent bookshop wants to stay competitive against large online retailers, so it launches a simple website allowing local customers to check book stock and reserve copies for same-day pickup. Why is this moderate use of technology sensible for a small business?","options":{"A":"It improves customer convenience and sales at an affordable cost without requiring multimillion-dollar warehouse robotics","B":"Small bookshops are legally banned from having websites","C":"A reservation website eliminates the need to pay shop rent","D":"Customers only buy books if they are printed by 3D printers"},"correctOption":"A","correctAnswer":"It improves customer convenience and sales at an affordable cost without requiring multimillion-dollar warehouse robotics","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because small businesses can adopt cost-effective digital tools like stock-checking websites to enhance customer service without unaffordable capital outlay.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because any business can operate an e-commerce or reservation website.","C":"Incorrect because the physical bookshop still pays rent for its premises.","D":"Incorrect because books are produced via commercial printing presses, not 3D printers."}}},{"id":"P1_U4_MCQ_282","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_282","question":"A chemical plant installs computer-controlled robotic valves and automated sensors to mix hazardous acids inside sealed chambers, removing human operators from toxic fumes. What is a primary benefit of this technology?","options":{"A":"Improved employee health and safety and lower risk of costly industrial accidents","B":"Elimination of all initial machinery purchase costs","C":"Increased number of unskilled workers exposed to hazardous chemicals","D":"Zero need for software maintenance or sensor calibration"},"correctOption":"A","correctAnswer":"Improved employee health and safety and lower risk of costly industrial accidents","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automating dangerous chemical handling protects worker health, reduces workplace injuries, and lowers safety liability costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because automated chemical handling equipment requires substantial initial capital investment.","C":"Incorrect because automation removes workers from hazardous areas rather than exposing more staff.","D":"Incorrect because precision chemical sensors require regular calibration and technical maintenance."}}},{"id":"P1_U4_MCQ_283","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_283","question":"A car manufacturer invests $50 million in automated assembly robots, lowering variable labour costs per car, but faces a sharp economic downturn where car sales drop by 40%. Why does high automation create financial pressure during a sales slump?","options":{"A":"High fixed costs from loan interest and depreciation on expensive machinery must still be paid even when output is low","B":"Robots demand higher hourly overtime wages when the factory is closed","C":"Automated factories cannot reduce output below 100% capacity","D":"Variable raw material costs double when fewer cars are made"},"correctOption":"A","correctAnswer":"High fixed costs from loan interest and depreciation on expensive machinery must still be paid even when output is low","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because expensive automation converts variable labour costs into high fixed capital costs, raising break-even output and squeezing profits when demand falls.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because robots do not receive hourly wages.","C":"Incorrect because automated lines can slow down or run fewer shifts, though fixed capital costs remain.","D":"Incorrect because total raw material costs fall when fewer cars are produced."}}},{"id":"P1_U4_MCQ_284","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_284","question":"When a supermarket introduces automated warehouse picking and self-checkout tills, 150 routine jobs are cut, while 30 new higher-paid roles are created for IT technicians and robotics engineers. What broader effect does technology have on the workforce?","options":{"A":"It reduces demand for unskilled routine labour while increasing demand for skilled technical staff","B":"It increases demand for unskilled manual workers and eliminates all technical jobs","C":"It guarantees lifetime employment for every existing cashier","D":"It removes the need for any training or education in the economy"},"correctOption":"A","correctAnswer":"It reduces demand for unskilled routine labour while increasing demand for skilled technical staff","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automation typically displaces repetitive, low-skilled roles while creating new opportunities for employees with IT and engineering skills.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the opposite occurs: routine manual jobs shrink while skilled technical roles grow.","C":"Incorrect because 150 routine roles were eliminated.","D":"Incorrect because technological change increases the importance of education and retraining."}}},{"id":"P1_U4_MCQ_285","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_285","question":"At a telecommunications firm, managers monitor call-centre staff through AI software that tracks every second spent between calls and flags any pause over ten seconds. How might this use of workplace technology negatively affect employees?","options":{"A":"Constant digital surveillance can cause high stress, low morale, and increased staff turnover","B":"Employees become overly relaxed because managers never check performance","C":"Staff receive higher pay every time the software flags a pause","D":"Call-centre workers no longer need to speak to customers"},"correctOption":"A","correctAnswer":"Constant digital surveillance can cause high stress, low morale, and increased staff turnover","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because intrusive technological monitoring can make employees feel micromanaged and stressed, reducing job satisfaction and increasing absenteeism or turnover.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because second-by-second tracking represents intense scrutiny rather than a lack of supervision.","C":"Incorrect because automated alerts are used for performance discipline rather than bonuses.","D":"Incorrect because call-centre agents still handle customer calls while being monitored."}}},{"id":"P1_U4_MCQ_286","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_286","question":"A courier company launches a mobile app giving customers live GPS map tracking of their parcel van and a 15-minute delivery window alert. How does this technology benefit customers?","options":{"A":"Greater convenience, transparency, and certainty about when their delivery will arrive","B":"Higher delivery prices and slower shipping times","C":"Customers must drive to the warehouse to collect every parcel themselves","D":"Elimination of all physical delivery vans"},"correctOption":"A","correctAnswer":"Greater convenience, transparency, and certainty about when their delivery will arrive","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because real-time tracking apps improve customer service by reducing uncertainty and letting recipients plan around exact arrival times.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because route-tracking technology usually improves delivery speed and efficiency rather than slowing it down.","C":"Incorrect because GPS tracking follows home-delivery vans bringing parcels to the customer.","D":"Incorrect because physical vans are still required to transport parcels."}}},{"id":"P1_U4_MCQ_287","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_287","question":"A dental clinic introduces an automated online appointment booking portal, freeing receptionists from answering routine phone calls so they can spend more time welcoming anxious patients in the waiting room. How does this technology balance efficiency and customer care?","options":{"A":"Technology automates routine administrative tasks while preserving personal human support where customers value it most","B":"Touchscreen portals perform dental fillings automatically without dentists","C":"The clinic closes its reception desk and locks its front door","D":"Patients are banned from speaking to receptionists in person"},"correctOption":"A","correctAnswer":"Technology automates routine administrative tasks while preserving personal human support where customers value it most","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automating repetitive scheduling lowers administrative workload while enabling staff to deliver higher-quality personal care in person.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because qualified dentists still perform clinical treatments.","C":"Incorrect because receptionists remain present to welcome patients face-to-face.","D":"Incorrect because receptionists have more time to talk with patients in the waiting room."}}},{"id":"P1_U4_MCQ_288","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_288","question":"A metal-stamping factory considers buying a $1.2 million robotic press that saves $300,000 per year in labour and scrap costs, but the factory's product is expected to be replaced by a new design in two years that cannot use the press. Why should managers reject this investment?","options":{"A":"The machine will only save $600,000 over two years before becoming obsolete, failing to recover its $1.2 million capital cost","B":"Robotic presses never improve stamping accuracy","C":"Saving $300,000 per year increases average unit costs","D":"Governments ban factories from buying machinery costing over $1 million"},"correctOption":"A","correctAnswer":"The machine will only save $600,000 over two years before becoming obsolete, failing to recover its $1.2 million capital cost","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high capital expenditure on specialized automation is unprofitable if rapid product or technological change makes the equipment obsolete before it pays for itself.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because robotic presses do improve accuracy; the issue is the short two-year product lifespan.","C":"Incorrect because annual savings reduce average costs, though not enough within two years to cover the $1.2 million outlay.","D":"Incorrect because there is no legal cap on machinery spending."}}},{"id":"P1_U4_MCQ_289","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_289","question":"A high-end architectural model-making studio uses 3D printers to build intricate miniature scale models of skyscrapers for property developers within 48 hours. How does 3D printing enhance the service offered to clients?","options":{"A":"Clients receive highly detailed physical models far faster and can request rapid design revisions","B":"The studio can construct full-sized concrete skyscrapers using desktop 3D printers","C":"Architects no longer need to create digital building drawings","D":"Clients receive models for free because 3D printing has zero material cost"},"correctOption":"A","correctAnswer":"Clients receive highly detailed physical models far faster and can request rapid design revisions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 3D printing turns digital architectural CAD models into accurate physical scale models rapidly, accelerating client presentations and revisions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because desktop 3D printers make scale models rather than full-sized skyscrapers.","C":"Incorrect because 3D printers require digital CAD models as input.","D":"Incorrect because printing resins and equipment incur costs that are charged to clients."}}},{"id":"P1_U4_MCQ_290","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_290","question":"After an automated warehouse system is installed, existing warehouse pickers are retrained as system controllers who monitor computer dashboards and resolve robotic alerts, receiving a 15% pay rise. What positive impact on employees does this illustrate?","options":{"A":"Upskilling into more interesting technical roles with higher pay and safer working conditions","B":"Complete loss of employment for every warehouse worker","C":"Increased physical exhaustion from carrying heavy boxes","D":"Elimination of all training opportunities"},"correctOption":"A","correctAnswer":"Upskilling into more interesting technical roles with higher pay and safer working conditions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when businesses retrain staff to manage new technology, employees gain higher-level skills, better pay, and less physically strenuous work.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because these workers were retrained and retained rather than made redundant.","C":"Incorrect because robots handle the physical lifting while staff monitor dashboards.","D":"Incorrect because the company invested in retraining the employees."}}},{"id":"P1_U4_MCQ_291","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_291","question":"A regional bus operator introduces a mobile ticketing app, but many elderly passengers without smartphones struggle to buy tickets and complain when cash payment on buses is removed. What customer-service issue does this create?","options":{"A":"Excluding non-digital or older customers can cause frustration, negative publicity, and lost sales","B":"Mobile ticketing apps increase paper printing costs for the bus company","C":"Elderly passengers prefer paying triple fares on mobile apps","D":"Bus drivers no longer need to drive the buses"},"correctOption":"A","correctAnswer":"Excluding non-digital or older customers can cause frustration, negative publicity, and lost sales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because replacing traditional payment options entirely with app-only technology can alienate customers who lack smartphones or digital skills.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because mobile apps reduce rather than increase paper printing costs.","C":"Incorrect because the issue is accessibility for customers without smartphones, not higher fares.","D":"Incorrect because qualified drivers still operate the buses."}}},{"id":"P1_U4_MCQ_292","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_292","question":"A large bakery installs automated dough-mixing and oven-temperature sensors linked to a central computer, ensuring every loaf is baked at the exact same temperature and humidity. How does this benefit the business?","options":{"A":"Consistent product quality and fewer burnt or underbaked loaves requiring disposal","B":"Higher flour wastage and unpredictable baking times","C":"Zero electricity or gas consumption in the ovens","D":"Ability to switch to bespoke job production for every single loaf"},"correctOption":"A","correctAnswer":"Consistent product quality and fewer burnt or underbaked loaves requiring disposal","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automated process control maintains exact temperature and timing, minimizing human error and ensuring uniform product quality.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because automated sensors reduce waste and make baking times highly predictable.","C":"Incorrect because industrial ovens still consume gas or electricity to bake bread.","D":"Incorrect because automated sensor-controlled ovens are used for consistent batch or flow production."}}},{"id":"P1_U4_MCQ_293","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_293","question":"When evaluating whether to automate a production line, why must operations managers consider the nature of customer demand alongside machinery costs?","options":{"A":"Automation is only economical when there is large, steady demand for standardized products to spread high fixed capital costs","B":"Automated machinery works best when demand is tiny and every item is completely unique","C":"High customer demand makes automated machines break down every hour","D":"Customer demand has no effect on average unit costs"},"correctOption":"A","correctAnswer":"Automation is only economical when there is large, steady demand for standardized products to spread high fixed capital costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automated flow lines require high, continuous output of standardized goods to lower average fixed costs per unit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because small, bespoke demand suits labour-intensive job production rather than costly automation.","C":"Incorrect because automated lines are built for continuous high-volume operation.","D":"Incorrect because higher output spreads fixed machinery costs across more units, lowering average unit cost."}}},{"id":"P1_U4_MCQ_294","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_294","question":"A coastal salt-extraction and packaging plant builds a wind farm on adjacent hills to generate 100% of the electricity used by its drying and packing machines. Why is wind energy classified as a renewable energy source?","options":{"A":"Wind is naturally replenished and is not used up when generating electricity, unlike finite fossil fuels","B":"Wind turbines burn natural gas more cleanly than coal power stations","C":"Wind turbines require zero initial capital investment to build","D":"Wind energy can only be used by businesses located in deserts"},"correctOption":"A","correctAnswer":"Wind is naturally replenished and is not used up when generating electricity, unlike finite fossil fuels","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because renewable energy sources such as wind, solar, and hydropower are inexhaustible natural flows that emit no carbon dioxide during electricity generation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because wind turbines generate electricity from air currents without burning natural gas.","C":"Incorrect because purchasing and installing wind turbines involves high upfront capital costs.","D":"Incorrect because wind turbines operate in coastal, hilly, and offshore locations worldwide."}}},{"id":"P1_U4_MCQ_295","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_295","question":"A smartphone manufacturer redesigns its aluminium casings so each phone uses 22% less mined aluminium and replaces rare-earth magnets with recycled alternatives. Which sustainable production method is this?","options":{"A":"Using fewer natural resources","B":"Switching to coal-fired power stations","C":"Increasing overproduction in factories","D":"Using non-recyclable plastic shrink-wrap"},"correctOption":"A","correctAnswer":"Using fewer natural resources","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because designing products to require smaller quantities of virgin minerals conserves finite natural resources.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because coal is a polluting non-renewable fossil fuel.","C":"Incorrect because overproduction wastes materials rather than conserving them.","D":"Incorrect because non-recyclable plastic increases landfill waste."}}},{"id":"P1_U4_MCQ_296","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_296","question":"A commercial bakery donates unsold fresh bread at the end of each day to local food charities and converts stale dough trimmings into animal feed rather than sending food to landfill. Which sustainable practice does this demonstrate?","options":{"A":"Creating less waste and diverting organic materials away from landfill","B":"Installing solar panels on delivery vans","C":"Switching from batch production to job production","D":"Increasing plastic packaging per loaf"},"correctOption":"A","correctAnswer":"Creating less waste and diverting organic materials away from landfill","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because finding productive uses for surplus food and trimmings eliminates landfill waste and reduces methane emissions from decomposing food.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the scenario focuses on food waste reduction rather than solar panels.","C":"Incorrect because production batching is unrelated to food donation and animal feed conversion.","D":"Incorrect because increasing plastic packaging would harm sustainability."}}},{"id":"P1_U4_MCQ_297","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_297","question":"A refillery grocery shop encourages customers to bring their own empty glass jars and stainless-steel containers to fill with pasta, rice, and olive oil. Which sustainability principle is this business promoting?","options":{"A":"Reusing containers repeatedly without manufacturing new packaging","B":"Melting glass jars down after every single shopping trip","C":"Increasing single-use plastic bag consumption","D":"Automating grocery farming with heavy diesel tractors"},"correctOption":"A","correctAnswer":"Reusing containers repeatedly without manufacturing new packaging","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because refilling existing containers uses them again for the same purpose without energy-intensive reprocessing or new packaging production.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because melting glass down is recycling, whereas refilling intact jars is reusing.","C":"Incorrect because refillery shops eliminate single-use packaging.","D":"Incorrect because the scenario describes retail container reuse rather than diesel farm machinery."}}},{"id":"P1_U4_MCQ_298","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_298","question":"A furniture manufacturer collects off-cuts of scrap wood and sawdust from its workshop, compresses them with natural resin under heat, and turns them into chipboard sheets for making bookshelves. Which sustainable method is this?","options":{"A":"Recycling waste wood materials into new products","B":"Reusing intact chairs without alteration","C":"Using hydroelectric electricity","D":"Just-in-time timber ordering"},"correctOption":"A","correctAnswer":"Recycling waste wood materials into new products","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because recycling reprocesses waste materials (sawdust and off-cuts) to manufacture a different useful product (chipboard bookshelves).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sawdust is physically reprocessed into chipboard rather than reused in its original form.","C":"Incorrect because the scenario describes wood reprocessing rather than hydroelectric power.","D":"Incorrect because JIT relates to delivery timing rather than material reprocessing."}}},{"id":"P1_U4_MCQ_299","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_299","question":"A garden-products company develops plant pots made from compressed coconut husks that can be planted directly into soil where they decompose naturally into organic fertilizer. Which sustainable method does this illustrate?","options":{"A":"Developing environmentally friendly, biodegradable products","B":"Installing wind turbines on garden centres","C":"Increasing variable plastic moulding costs","D":"Switching to batch welding of steel pots"},"correctOption":"A","correctAnswer":"Developing environmentally friendly, biodegradable products","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because creating products from natural, biodegradable agricultural by-products eliminates plastic waste and enriches soil.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the scenario focuses on product design rather than wind electricity.","C":"Incorrect because coconut husk pots replace plastic rather than increasing plastic moulding.","D":"Incorrect because the pots are made from biodegradable coconut husks, not welded steel."}}},{"id":"P1_U4_MCQ_300","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_300","question":"A skincare brand switches from virgin plastic tubes to infinitely recyclable aluminium tubes and unbleached cardboard boxes printed with soy-based inks. Which sustainable method is being applied?","options":{"A":"Using environmentally friendly packaging","B":"Automating skincare mixing with robotics","C":"Increasing coal consumption in factories","D":"Eliminating all product labels"},"correctOption":"A","correctAnswer":"Using environmentally friendly packaging","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because replacing virgin plastics and toxic inks with recyclable aluminium, cardboard, and soy inks reduces packaging waste and pollution.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the change involves packaging materials rather than factory robotics.","C":"Incorrect because sustainable practices move away from coal.","D":"Incorrect because product labels are still printed using eco-friendly soy inks."}}},{"id":"P1_U4_MCQ_301","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_301","question":"A major supermarket group announces it will only stock seafood certified as sustainably caught and coffee from zero-deforestation farms, winning positive media coverage and attracting new shoppers. What benefit of sustainability does this show?","options":{"A":"Enhanced brand reputation and competitive differentiation that attracts ethically conscious consumers","B":"Zero cost for purchasing seafood and coffee from suppliers","C":"Elimination of all store refrigeration electricity bills","D":"Legal exemption from food hygiene inspections"},"correctOption":"A","correctAnswer":"Enhanced brand reputation and competitive differentiation that attracts ethically conscious consumers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because credible sustainable sourcing strengthens brand image, generates positive publicity, and wins market share from less responsible rivals.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because certified sustainable products still must be purchased from suppliers.","C":"Incorrect because sustainable sourcing does not eliminate store refrigeration power usage.","D":"Incorrect because supermarkets must still pass all statutory food hygiene checks."}}},{"id":"P1_U4_MCQ_302","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_302","question":"A logistics company replaces 100 diesel delivery vans with electric vans charged by solar panels at its depot, spending $2 million upfront but saving $550,000 per year in diesel fuel and maintenance. How does this affect the firm's long-term financial position?","options":{"A":"Once the initial capital cost is recovered in under four years, lower annual running costs permanently boost profit margins","B":"The company makes an immediate profit in Month 1 before saving any diesel","C":"Electricity bills from solar panels exceed diesel fuel costs every year","D":"The company no longer needs drivers to deliver parcels"},"correctOption":"A","correctAnswer":"Once the initial capital cost is recovered in under four years, lower annual running costs permanently boost profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustainable energy investments often have high upfront costs that pay back over several years, after which lower operating costs increase long-run profitability.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a $2 million upfront outlay takes nearly four years of $550,000 annual savings to pay back.","C":"Incorrect because depot solar power lowers annual running costs by $550,000 compared with diesel.","D":"Incorrect because electric delivery vans still require human drivers."}}},{"id":"P1_U4_MCQ_303","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_303","question":"A government passes strict new carbon-emission caps imposing heavy fines on factories that exceed pollution limits, while offering tax credits to firms installing clean filtration equipment. How does adopting sustainable production benefit a manufacturer here?","options":{"A":"It ensures legal compliance, avoids punitive fines, and captures government tax credits","B":"It allows the manufacturer to dump unlimited chemical waste into rivers","C":"It eliminates all employee wages and factory rent","D":"It guarantees that competitors will never lower their prices"},"correctOption":"A","correctAnswer":"It ensures legal compliance, avoids punitive fines, and captures government tax credits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because proactive sustainability keeps the business compliant with tightening environmental laws, avoiding fines and qualifying for state tax incentives.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sustainable production eliminates toxic dumping rather than permitting it.","C":"Incorrect because wages and rent still must be paid.","D":"Incorrect because competitors remain free to set their own prices."}}},{"id":"P1_U4_MCQ_304","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_304","question":"A small craft brewery wants to install a $120,000 wastewater treatment and heat-recovery system, but struggles to afford it because its annual net profit is only $35,000. Which disadvantage of sustainable production does this illustrate?","options":{"A":"High upfront capital expenditure can strain cash flow and be unaffordable for smaller businesses","B":"Customers boycott breweries that treat their wastewater cleanly","C":"Heat-recovery systems increase natural gas bills every month","D":"Small breweries are banned from purchasing sustainability equipment"},"correctOption":"A","correctAnswer":"High upfront capital expenditure can strain cash flow and be unaffordable for smaller businesses","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because environmental technologies often require large initial investments relative to a small firm's profits and cash reserves.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because consumers favour environmentally responsible breweries.","C":"Incorrect because heat recovery reduces gas bills rather than increasing them.","D":"Incorrect because no laws prevent small businesses from buying green equipment."}}},{"id":"P1_U4_MCQ_305","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_305","question":"A packaging manufacturer switches to biodegradable cornstarch film for wrapping vegetables, only to discover that the film tears easily on high-speed packing machines and costs 40% more than conventional plastic. What operational challenges does this show?","options":{"A":"Sustainable materials can have higher unit costs and technical performance limitations that slow production","B":"Biodegradable film always increases machine speed and lowers material prices","C":"Supermarkets prefer torn packaging on fresh vegetables","D":"Cornstarch film is made from non-renewable crude oil"},"correctOption":"A","correctAnswer":"Sustainable materials can have higher unit costs and technical performance limitations that slow production","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because eco-friendly substitute materials can be costlier per unit and may require adjusting machinery or accepting performance trade-offs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because in this scenario the film tore on machines and cost 40% more.","C":"Incorrect because torn packaging causes food spoilage and customer complaints.","D":"Incorrect because cornstarch is a plant-based renewable material, not crude oil."}}},{"id":"P1_U4_MCQ_306","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_306","question":"A paper mill located beside a river releases untreated chemical bleach into the water to keep its paper prices 15% cheaper than a sustainable rival that filters all wastewater. What external cost and competitive problem does this create?","options":{"A":"The polluting mill imposes environmental damage on the community while undercutting responsible rivals on price","B":"The sustainable mill suffers from lower product quality because it filters wastewater","C":"River pollution increases local fishing tourism profits","D":"Both mills have identical production costs"},"correctOption":"A","correctAnswer":"The polluting mill imposes environmental damage on the community while undercutting responsible rivals on price","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because businesses that ignore environmental responsibilities avoid treatment costs and undercut sustainable firms, harming ecosystems and communities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because filtering wastewater protects the environment without lowering paper quality.","C":"Incorrect because chemical river pollution kills fish and harms tourism.","D":"Incorrect because the sustainable mill incurs higher waste-treatment costs."}}},{"id":"P1_U4_MCQ_307","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_307","question":"A construction company adopts modular off-site prefabrication, cutting timber and steel beams to exact CAD dimensions in a factory so on-site building waste drops by 70%. How does this benefit both profit and sustainability?","options":{"A":"Lower raw material purchases and skip-hire disposal fees reduce total costs while conserving natural resources","B":"It eliminates the need to hire architects or structural engineers","C":"It increases landfill waste at construction sites","D":"It forces buildings to be constructed without foundations"},"correctOption":"A","correctAnswer":"Lower raw material purchases and skip-hire disposal fees reduce total costs while conserving natural resources","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because precision cutting reduces both material purchase costs and waste disposal fees while preserving timber and iron ore.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because architects and engineers are essential to create precision CAD plans.","C":"Incorrect because on-site building waste dropped by 70%.","D":"Incorrect because buildings still require proper foundations."}}},{"id":"P1_U4_MCQ_308","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_308","question":"A smartphone manufacturer designs its latest phones with modular batteries and screens that can be easily unscrewed and replaced by repair shops rather than glued permanently shut. How does this support sustainability?","options":{"A":"It extends product lifespan, reduces electronic waste, and encourages repair and reuse of components","B":"It forces customers to throw away their entire phone every six months","C":"It increases the amount of toxic battery waste in landfills","D":"It eliminates the need for electricity to charge the phone"},"correctOption":"A","correctAnswer":"It extends product lifespan, reduces electronic waste, and encourages repair and reuse of components","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because designing products for easy repair and component replacement slows resource depletion and reduces electronic waste.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because modular repairability helps customers keep phones longer rather than discarding them.","C":"Incorrect because replaceable batteries allow proper battery recycling without discarding the whole handset.","D":"Incorrect because smartphones still require electrical charging."}}},{"id":"P1_U4_MCQ_309","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_309","question":"A tyre manufacturer collects worn-out truck tyres from haulage companies, strips off the worn outer rubber, and vulcanises a brand-new tread layer onto the intact steel-belted tyre casing ('retreading'). Is this an example of reusing or recycling?","options":{"A":"Reusing, because the intact tyre casing is refurbished and used again for its original purpose as a truck tyre","B":"Recycling, because the entire tyre is melted into liquid fuel","C":"Overproduction, because too many tyres are manufactured","D":"Quality control sampling"},"correctOption":"A","correctAnswer":"Reusing, because the intact tyre casing is refurbished and used again for its original purpose as a truck tyre","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retreading refurbishes the intact tyre casing so it can be used again as a tyre without shredding or melting the whole product into a different material.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the casing is kept intact and reused as a tyre rather than broken down into a different product.","C":"Incorrect because retreading extends the life of existing casings rather than overproducing new ones.","D":"Incorrect because quality control tests finished goods for defects."}}},{"id":"P1_U4_MCQ_310","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_310","question":"An automotive battery maker collects dead lead-acid car batteries, crushes them, smelts the lead plates, and uses the recovered lead to manufacture brand-new batteries. Why is this classified as recycling?","options":{"A":"The used material is broken down and reprocessed to manufacture a new product","B":"The dead battery is recharged and placed straight back into a car without opening it","C":"Recycling uses more newly mined lead ore than making batteries from scratch","D":"Lead-acid batteries are biodegradable in garden soil"},"correctOption":"A","correctAnswer":"The used material is broken down and reprocessed to manufacture a new product","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because recycling involves breaking down and reprocessing waste materials into raw inputs for new products.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because recharging an intact battery without dismantling it would be reusing.","C":"Incorrect because recycling recovered lead reduces the need for virgin lead mining.","D":"Incorrect because lead and acid are toxic pollutants that must be safely recycled, not composted."}}},{"id":"P1_U4_MCQ_311","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_311","question":"A multinational food company pledges to achieve 'net-zero' carbon emissions across its farms, factories, and delivery fleets by 2040, requiring new supplier contracts, redesigned factories, and electric trucks. Why is a 14-year transition period realistic?","options":{"A":"Transforming global supply chains, re-engineering factories, and replacing vehicle fleets takes years of planning and capital investment","B":"Net-zero emissions can be achieved in five minutes simply by changing the company logo","C":"Governments ban companies from reducing emissions before 2040","D":"Electric trucks and renewable power plants can be built overnight at zero cost"},"correctOption":"A","correctAnswer":"Transforming global supply chains, re-engineering factories, and replacing vehicle fleets takes years of planning and capital investment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because genuine operational sustainability across complex supply chains requires years of R&D, capital investment, and supplier transition.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because changing a logo without operational change is misleading greenwashing.","C":"Incorrect because governments encourage immediate emission reductions.","D":"Incorrect because infrastructure and fleet transitions require substantial time and capital."}}},{"id":"P1_U4_MCQ_312","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_312","question":"A university campus cafe introduces a $0.50 surcharge on disposable paper cups while offering a $0.50 discount to students bringing reusable mugs, cutting disposable cup waste by 75%. How does this benefit the cafe?","options":{"A":"It lowers cup purchasing and waste-disposal expenses while appealing to environmentally conscious students","B":"It increases the number of disposable paper cups thrown into campus bins","C":"It forces the cafe to close every afternoon","D":"It eliminates the cost of coffee beans and milk"},"correctOption":"A","correctAnswer":"It lowers cup purchasing and waste-disposal expenses while appealing to environmentally conscious students","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reducing disposable cup usage directly saves packaging and waste collection costs while enhancing the cafe's eco-friendly reputation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because disposable cup waste fell by 75%.","C":"Incorrect because higher student goodwill supports sales rather than closing the cafe.","D":"Incorrect because coffee beans and milk still must be purchased."}}},{"id":"P1_U4_MCQ_313","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_313","question":"A textile dyeing factory invests in waterless supercritical carbon-dioxide dyeing machines that eliminate water pollution and cut energy use by 50%, helping it win supply contracts with major global clothing brands. Which strategic benefit of sustainability does this show?","options":{"A":"Meeting corporate buyers' strict environmental standards opens access to major business-to-business contracts","B":"Waterless dyeing machines require zero electricity to operate","C":"Global clothing brands prefer suppliers that pollute rivers","D":"The factory no longer needs to buy plain fabric rolls"},"correctOption":"A","correctAnswer":"Meeting corporate buyers' strict environmental standards opens access to major business-to-business contracts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because large retailers increasingly require their suppliers to prove sustainable production before awarding contracts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the machines use 50% less energy, not zero electricity.","C":"Incorrect because major brands avoid polluting suppliers to protect their own brand image.","D":"Incorrect because plain fabric rolls are still dyed and finished."}}},{"id":"P1_U4_MCQ_314","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_314","question":"Why do many governments offer subsidies and grants to businesses that adopt renewable energy and sustainable production methods?","options":{"A":"To help overcome high initial investment barriers and reduce national pollution and resource depletion","B":"To encourage businesses to burn more coal and crude oil","C":"To increase landfill waste across cities","D":"To force small businesses into bankruptcy"},"correctOption":"A","correctAnswer":"To help overcome high initial investment barriers and reduce national pollution and resource depletion","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because subsidies lower the high upfront capital hurdle of green technologies, accelerating environmental protection across the economy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because subsidies aim to replace fossil fuels with renewable energy.","C":"Incorrect because governments seek to reduce landfill waste.","D":"Incorrect because grants financially support businesses rather than harming them."}}},{"id":"P1_U4_MCQ_315","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_315","question":"A bicycle repair shop pays monthly shop rent, annual public liability insurance, replacement inner tubes fitted to customers' bikes, and the owner's fixed monthly salary. Which expense is a variable cost?","options":{"A":"Replacement inner tubes fitted to customers' bikes","B":"Monthly shop rent","C":"Annual public liability insurance","D":"The owner's fixed monthly salary"},"correctOption":"A","correctAnswer":"Replacement inner tubes fitted to customers' bikes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the number and cost of replacement inner tubes vary directly with the number of bicycle repairs carried out.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because monthly shop rent is a fixed cost independent of repair volume.","C":"Incorrect because annual insurance is a fixed cost.","D":"Incorrect because a fixed monthly salary does not vary directly with the number of repairs."}}},{"id":"P1_U4_MCQ_316","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_316","question":"A greeting-card printer has monthly fixed costs of $8,500 and incurs variable costs of $3.20 per box of cards printed. What is the total cost of producing 2,500 boxes of cards in a month?","options":{"A":"$8,000","B":"$16,500","C":"$11,000","D":"$8,503.20"},"correctOption":"B","correctAnswer":"$16,500","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because total variable cost is 2,500 x $3.20 = $8,000, and adding fixed costs of $8,500 gives a total cost of $16,500.","distractor_reasons":{"A":"Incorrect because $8,000 is only the total variable cost, omitting the $8,500 fixed costs.","B":"Correct selection.","C":"Incorrect because this adds 2,500 units directly to $8,500 without multiplying by $3.20.","D":"Incorrect because this adds the variable cost of just one box ($3.20) instead of 2,500 boxes."}}},{"id":"P1_U4_MCQ_317","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_317","question":"A backpack factory produces 4,000 backpacks per month with monthly fixed costs of $18,000 and total variable costs of $34,000. What is the average cost per backpack?","options":{"A":"$8.50","B":"$4.50","C":"$13.00","D":"$52,000"},"correctOption":"C","correctAnswer":"$13.00","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total cost is $18,000 + $34,000 = $52,000, and dividing $52,000 by 4,000 backpacks gives an average cost of $13.00 per backpack.","distractor_reasons":{"A":"Incorrect because $8.50 is only the average variable cost ($34,000 / 4,000), ignoring fixed costs.","B":"Incorrect because $4.50 is only the average fixed cost ($18,000 / 4,000), ignoring variable costs.","C":"Correct selection.","D":"Incorrect because $52,000 is the total monthly cost rather than the cost per unit."}}},{"id":"P1_U4_MCQ_318","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_318","question":"A juice bottling plant has weekly fixed costs of $6,000 and variable costs of $1.50 per bottle. If weekly output increases from 1,000 bottles to 3,000 bottles within existing plant capacity, how does average total cost per bottle change?","options":{"A":"It falls from $7.50 to $3.50 per bottle because fixed costs are spread over three times as many bottles","B":"It rises from $3.50 to $7.50 per bottle","C":"It stays constant at $7.50 per bottle","D":"It falls to $1.50 per bottle because fixed costs disappear"},"correctOption":"A","correctAnswer":"It falls from $7.50 to $3.50 per bottle because fixed costs are spread over three times as many bottles","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because at 1,000 bottles, average cost is ($6,000 / 1,000) + $1.50 = $7.50, whereas at 3,000 bottles it drops to ($6,000 / 3,000) + $1.50 = $3.50.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher output lowers average cost per unit rather than increasing it.","C":"Incorrect because average fixed cost drops from $6.00 to $2.00 per bottle.","D":"Incorrect because fixed costs remain $6,000 ($2.00 per bottle at 3,000 units)."}}},{"id":"P1_U4_MCQ_319","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_319","question":"A wireless keyboard manufacturer has monthly fixed costs of $32,000, sells each keyboard for $22, and incurs variable costs of $14 per keyboard. What is the monthly break-even output?","options":{"A":"1,455 keyboards","B":"2,286 keyboards","C":"889 keyboards","D":"4,000 keyboards"},"correctOption":"D","correctAnswer":"4,000 keyboards","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because contribution per unit is $22 - $14 = $8, and dividing fixed costs ($32,000) by contribution per unit ($8) equals 4,000 keyboards.","distractor_reasons":{"A":"Incorrect because this divides $32,000 by the $22 selling price instead of contribution per unit ($8).","B":"Incorrect because this divides $32,000 by the $14 variable cost instead of contribution per unit ($8).","C":"Incorrect because this adds selling price and variable cost ($36) before dividing into $32,000.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_320","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_320","question":"A manufacturer is comparing two factory locations for producing 10,000 units per year: Location A has annual fixed costs of $50,000 and variable costs of $6 per unit, while Location B has annual fixed costs of $80,000 and variable costs of $2 per unit. Based purely on total costs, which location should be chosen?","options":{"A":"Location B, because its total annual cost is $100,000 compared with $110,000 at Location A","B":"Location A, because its fixed costs are $30,000 lower","C":"Location A, because its total annual cost is $60,000","D":"Location B, because its total annual cost is $80,000"},"correctOption":"A","correctAnswer":"Location B, because its total annual cost is $100,000 compared with $110,000 at Location A","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Location A's total cost is $50,000 + (10,000 x $6) = $110,000, whereas Location B's total cost is $80,000 + (10,000 x $2) = $100,000, saving $10,000 per year.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because although fixed costs are lower at Location A, its higher variable costs ($60,000 vs $20,000) make total cost $10,000 higher.","C":"Incorrect because $60,000 is only Location A's variable cost, omitting $50,000 fixed costs.","D":"Incorrect because $80,000 is only Location B's fixed cost, omitting $20,000 variable costs."}}},{"id":"P1_U4_MCQ_321","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_321","question":"A clothing retailer sells a jacket for $50 that has a variable cost of $35 and generates $15,000 in annual contribution from 1,000 sales, while its dedicated department fixed costs are $12,000 per year. Should the retailer continue selling this jacket?","options":{"A":"Yes, because total contribution of $15,000 exceeds dedicated fixed costs of $12,000, earning $3,000 annual profit","B":"No, because variable cost of $35 is higher than $15 contribution","C":"No, because total revenue is less than fixed costs","D":"Yes, because it makes $15,000 net profit after all fixed costs"},"correctOption":"A","correctAnswer":"Yes, because total contribution of $15,000 exceeds dedicated fixed costs of $12,000, earning $3,000 annual profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 1,000 jackets generate $15,000 in contribution, which covers the $12,000 dedicated fixed costs and leaves $3,000 profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profitability depends on whether total contribution exceeds fixed costs, not whether variable cost exceeds unit contribution.","C":"Incorrect because total revenue is 1,000 x $50 = $50,000, far above $12,000 fixed costs.","D":"Incorrect because $15,000 is total contribution before deducting $12,000 fixed costs; net profit is $3,000."}}},{"id":"P1_U4_MCQ_322","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_322","question":"A national hotel chain buys bedsheets, towels, and toiletries in bulk for all 120 of its hotels, paying 25% less per item than a small independent guest house. Which economy of scale is the hotel chain enjoying?","options":{"A":"Purchasing economies of scale","B":"Technical economies of scale","C":"Financial economies of scale","D":"Managerial economies of scale"},"correctOption":"A","correctAnswer":"Purchasing economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because purchasing economies occur when large businesses buy supplies in large quantities and obtain bulk discounts that lower unit costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because technical economies involve using large-scale specialist machinery.","C":"Incorrect because financial economies involve borrowing money at lower interest rates.","D":"Incorrect because managerial economies involve employing specialist departmental managers."}}},{"id":"P1_U4_MCQ_323","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_323","question":"A major supermarket group operates a fleet of massive 44-tonne articulated lorries to deliver groceries across the country, lowering the transport cost per crate compared with small shops using small delivery vans. Which economy of scale does this represent?","options":{"A":"Marketing economies of scale","B":"Financial economies of scale","C":"Managerial economies of scale","D":"Diseconomies of scale"},"correctOption":"A","correctAnswer":"Marketing economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because marketing economies include lower distribution and transport costs per unit when large firms use high-capacity delivery vehicles, alongside lower unit advertising costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because financial economies relate to lower interest rates on loans.","C":"Incorrect because managerial economies relate to specialist functional managers.","D":"Incorrect because diseconomies of scale increase average unit costs rather than lowering them."}}},{"id":"P1_U4_MCQ_324","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_324","question":"A small start-up cafe is charged 11% annual interest on a bank loan, whereas an established multinational restaurant chain borrows at 4.5% interest because banks view it as much safer. Which economy of scale is this?","options":{"A":"Financial economies of scale","B":"Purchasing economies of scale","C":"Technical economies of scale","D":"Marketing economies of scale"},"correctOption":"A","correctAnswer":"Financial economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because financial economies occur when large firms secure loans at lower interest rates and access wider sources of capital.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because purchasing economies refer to bulk-buying discounts from suppliers.","C":"Incorrect because technical economies refer to specialized high-output machinery.","D":"Incorrect because marketing economies refer to lower unit advertising and distribution costs."}}},{"id":"P1_U4_MCQ_325","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_325","question":"A large confectionery manufacturer installs a high-speed chocolate-wrapping machine capable of wrapping 800 bars per minute, which would sit idle most of the week at a small sweet shop. Which economy of scale does the large manufacturer gain?","options":{"A":"Technical economies of scale","B":"Financial economies of scale","C":"Marketing economies of scale","D":"Purchasing economies of scale"},"correctOption":"A","correctAnswer":"Technical economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because technical economies arise when large firms can afford and fully utilize high-capacity, indivisible machinery to lower average unit costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because financial economies involve lower borrowing rates.","C":"Incorrect because marketing economies involve spreading advertising and transport costs.","D":"Incorrect because purchasing economies involve bulk discounts on ingredients."}}},{"id":"P1_U4_MCQ_326","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_326","question":"After acquiring four rival chains, a giant retail corporation develops long chains of command where store managers rarely see senior directors and instructions become distorted across regions, causing rising unit costs. Which problem is occurring?","options":{"A":"Diseconomies of scale caused by poor communication and weak co-ordination","B":"Managerial economies of scale","C":"Purchasing economies of scale","D":"Technical economies of scale"},"correctOption":"A","correctAnswer":"Diseconomies of scale caused by poor communication and weak co-ordination","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because communication breakdowns and slow co-ordination in oversized businesses are classic diseconomies of scale that push average costs upward.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because managerial economies lower unit costs through specialist management.","C":"Incorrect because purchasing economies lower unit costs through bulk buying.","D":"Incorrect because technical economies lower unit costs through high-capacity equipment."}}},{"id":"P1_U4_MCQ_327","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_327","question":"To overcome diseconomies of scale in its 25,000-employee manufacturing group, senior directors split the business into smaller, semi-autonomous regional divisions with shorter chains of command. Why does this help reduce average costs?","options":{"A":"It speeds up communication and decision-making while making employees feel more connected to local managers","B":"It eliminates all fixed rent and electricity expenses across every factory","C":"It forces suppliers to give 90% bulk discounts","D":"It stops customers from buying rivals' products"},"correctOption":"A","correctAnswer":"It speeds up communication and decision-making while making employees feel more connected to local managers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because decentralizing into smaller operating units restores fast communication, accountability, and worker motivation, reversing diseconomies of scale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because factory rent and electricity expenses still must be paid.","C":"Incorrect because splitting into divisions does not force suppliers to give 90% discounts.","D":"Incorrect because internal restructuring does not restrict customer choice."}}},{"id":"P1_U4_MCQ_328","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_328","question":"A wooden bookshelf maker sells each bookshelf for $45, incurs variable costs of $27 per bookshelf, and pays monthly fixed costs of $54,000. What is the contribution per unit?","options":{"A":"$18","B":"$72","C":"$27","D":"$3,000"},"correctOption":"A","correctAnswer":"$18","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because contribution per unit equals selling price ($45) minus variable cost per unit ($27), which is $18.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this adds variable cost ($27) to selling price ($45) instead of subtracting it.","C":"Incorrect because $27 is the variable cost per unit rather than contribution.","D":"Incorrect because 3,000 units is the break-even output ($54,000 / $18), not unit contribution."}}},{"id":"P1_U4_MCQ_329","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_329","question":"A camping tent manufacturer has monthly fixed costs of $54,000, sells each tent for $45, and incurs variable costs of $27 per tent. How many tents must the manufacturer sell each month to break even?","options":{"A":"1,200 tents","B":"2,000 tents","C":"3,000 tents","D":"750 tents"},"correctOption":"C","correctAnswer":"3,000 tents","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because contribution per tent is $45 - $27 = $18, and dividing fixed costs ($54,000) by unit contribution ($18) equals 3,000 tents.","distractor_reasons":{"A":"Incorrect because this divides $54,000 by the $45 selling price instead of contribution per unit ($18).","B":"Incorrect because this divides $54,000 by the $27 variable cost instead of contribution per unit ($18).","C":"Correct selection.","D":"Incorrect because this adds selling price and variable cost ($72) before dividing into $54,000."}}},{"id":"P1_U4_MCQ_330","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_330","question":"A stainless-steel thermos manufacturer has a monthly break-even output of 2,400 flasks and currently sells 3,150 flasks per month. What is the manufacturer's margin of safety?","options":{"A":"5,550 flasks","B":"750 flasks","C":"2,400 flasks","D":"3,150 flasks"},"correctOption":"B","correctAnswer":"750 flasks","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because margin of safety equals actual sales (3,150) minus break-even output (2,400), which is 750 flasks.","distractor_reasons":{"A":"Incorrect because this adds actual sales and break-even output instead of subtracting break-even output from actual sales.","B":"Correct selection.","C":"Incorrect because 2,400 is the break-even output rather than the margin of safety.","D":"Incorrect because 3,150 is actual monthly sales rather than the safety buffer."}}},{"id":"P1_U4_MCQ_331","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_331","question":"A ceramic planter manufacturer has monthly fixed costs of $14,000 and earns a contribution of $9 per planter sold. If the company sells 2,200 planters in a month, what is its monthly profit?","options":{"A":"$19,800","B":"$33,800","C":"$5,800","D":"$14,000"},"correctOption":"C","correctAnswer":"$5,800","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total contribution is 2,200 x $9 = $19,800, and subtracting fixed costs of $14,000 leaves a profit of $5,800.","distractor_reasons":{"A":"Incorrect because $19,800 is total contribution before deducting the $14,000 fixed costs.","B":"Incorrect because this adds fixed costs ($14,000) to total contribution ($19,800) instead of subtracting them.","C":"Correct selection.","D":"Incorrect because $14,000 is the monthly fixed cost rather than profit."}}},{"id":"P1_U4_MCQ_332","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_332","question":"An artisan pizza shop has weekly fixed costs of $9,000, variable costs of $6 per pizza, and currently sells pizzas at $12 each (break-even output = 1,500 pizzas). If the shop raises its selling price to $15 per pizza while costs stay unchanged, what will be the new break-even output?","options":{"A":"1,000 pizzas","B":"1,500 pizzas","C":"600 pizzas","D":"3,000 pizzas"},"correctOption":"A","correctAnswer":"1,000 pizzas","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because raising the price to $15 increases contribution per pizza to $15 - $6 = $9, so new break-even output falls to $9,000 / $9 = 1,000 pizzas.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 1,500 pizzas was the old break-even output at the $12 selling price.","C":"Incorrect because 600 divides $9,000 by the $15 selling price without deducting the $6 variable cost.","D":"Incorrect because raising the price increases contribution and lowers break-even output rather than doubling it."}}},{"id":"P1_U4_MCQ_333","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_333","question":"On a break-even chart, how is the Fixed Cost line drawn across the horizontal output axis?","options":{"A":"As a flat, horizontal line parallel to the horizontal output axis","B":"As a steep upward-sloping line starting from the origin ($0)","C":"As a downward-sloping line that reaches $0 at maximum capacity","D":"As a vertical line running straight up from the break-even point"},"correctOption":"A","correctAnswer":"As a flat, horizontal line parallel to the horizontal output axis","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because total fixed costs remain constant regardless of output level within existing capacity, forming a horizontal line.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because an upward-sloping line starting at the origin represents Total Revenue or Total Variable Cost.","C":"Incorrect because total fixed costs do not fall as output rises.","D":"Incorrect because a vertical dashed line from the intersection marks the break-even output on the x-axis, not fixed costs."}}},{"id":"P1_U4_MCQ_334","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_334","question":"At the exact break-even point on a break-even chart, which financial statement is true?","options":{"A":"Total Revenue equals Total Costs, so profit is zero and total contribution equals total fixed costs","B":"Total Revenue is double Total Costs","C":"Total Variable Costs equal zero","D":"The business earns its maximum possible profit"},"correctOption":"A","correctAnswer":"Total Revenue equals Total Costs, so profit is zero and total contribution equals total fixed costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because at the break-even point, Total Revenue intersects Total Costs, meaning the business makes neither a profit nor a loss.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because if Total Revenue were double Total Costs, the firm would be earning a large profit.","C":"Incorrect because variable costs are positive at any positive output level.","D":"Incorrect because profit is zero at break-even and increases to the right of the break-even point."}}},{"id":"P1_U4_MCQ_335","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_335","question":"Why is break-even analysis particularly helpful for an entrepreneur applying for a bank loan to launch a new manufacturing business?","options":{"A":"It shows the minimum sales volume required to avoid losses and demonstrates the safety margin at forecast sales levels","B":"It legally guarantees that customers will buy the forecast number of units","C":"It eliminates all fixed and variable costs during the first year","D":"It proves that raw material prices will never change"},"correctOption":"A","correctAnswer":"It shows the minimum sales volume required to avoid losses and demonstrates the safety margin at forecast sales levels","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because banks examine break-even figures in a business plan to assess risk—specifically how many units must sell to cover costs and how much cushion exists.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because break-even charts show profit/loss at different sales levels; they do not guarantee actual demand.","C":"Incorrect because start-ups still incur fixed and variable costs.","D":"Incorrect because break-even assumes constant unit costs as a simplifying model rather than preventing real-world price changes."}}},{"id":"P1_U4_MCQ_336","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_336","question":"A toy manufacturer receives a 10% bulk discount from plastic suppliers once output exceeds 5,000 toys per month, causing the real total cost line to bend slightly flatter above 5,000 units. Which assumption of simple break-even charts does this violate?","options":{"A":"Simple break-even charts assume variable costs per unit remain constant (a straight line) at all output levels","B":"Simple break-even charts assume total revenue is always horizontal","C":"Simple break-even charts assume fixed costs start at zero","D":"Simple break-even charts cannot show output above 1,000 units"},"correctOption":"A","correctAnswer":"Simple break-even charts assume variable costs per unit remain constant (a straight line) at all output levels","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because standard linear break-even charts plot straight lines assuming constant unit variable costs, ignoring purchasing economies or overtime pay rates.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because total revenue is plotted as an upward-sloping line, not horizontal.","C":"Incorrect because total costs start at the positive level of fixed costs on the y-axis.","D":"Incorrect because break-even charts can be scaled to any output volume."}}},{"id":"P1_U4_MCQ_337","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_337","question":"A budget smartphone priced at $90 makes clear phone calls, sends messages reliably, and lasts a full day on one battery charge, matching what budget-conscious buyers expect. Why is this phone regarded as good quality?","options":{"A":"Quality means a product is fit for purpose and meets the expectations of its target customers","B":"Quality is determined solely by charging over $1,000 per phone","C":"Budget phones are never tested for defects","D":"Quality only applies to luxury goods sold in designer boutiques"},"correctOption":"A","correctAnswer":"Quality means a product is fit for purpose and meets the expectations of its target customers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality in Business Studies means meeting customer expectations and being fit for purpose at the intended price tier.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because price alone does not define quality; an expensive product that fails is poor quality.","C":"Incorrect because budget manufacturers still test phones to ensure reliability.","D":"Incorrect because quality standards apply across all price segments and industries."}}},{"id":"P1_U4_MCQ_338","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_338","question":"An outdoor tent manufacturer earns a reputation for storm-proof stitching and durable zippers, allowing it to expand into international markets and rely on positive word-of-mouth recommendations. Which advantage of quality does this illustrate?","options":{"A":"Stronger brand reputation and organic customer referrals that boost sales without excessive advertising spend","B":"Elimination of all fabric and zipper material costs","C":"Zero need to train sewing machinists","D":"Guaranteed exemption from import tariffs abroad"},"correctOption":"A","correctAnswer":"Stronger brand reputation and organic customer referrals that boost sales without excessive advertising spend","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consistently high quality builds trust, encourages satisfied customers to recommend the brand, and supports market expansion.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because durable materials still must be purchased.","C":"Incorrect because high stitching standards require well-trained workers.","D":"Incorrect because product quality does not exempt exports from customs tariffs."}}},{"id":"P1_U4_MCQ_339","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_339","question":"A bicycle manufacturer discovers that 8% of finished bikes have poorly aligned brakes during final inspection, forcing mechanics to spend two extra hours per bike fixing them before dispatch. How does this quality failure harm the business?","options":{"A":"Reworking faulty bikes increases labour costs per unit and delays customer deliveries","B":"It reduces total variable costs per bicycle","C":"It increases labour productivity across the factory","D":"It improves brand loyalty among retail bike shops"},"correctOption":"A","correctAnswer":"Reworking faulty bikes increases labour costs per unit and delays customer deliveries","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reworking defective items wastes paid technician hours, increases unit costs, and slows down order fulfilment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because reworking increases rather than reduces unit costs.","C":"Incorrect because spending extra hours fixing mistakes lowers output per worker.","D":"Incorrect because delayed shipments frustrate retail bike shops."}}},{"id":"P1_U4_MCQ_340","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_340","question":"At the end of a television assembly line, a team of specialist inspectors switches on every completed TV and checks picture colour, sound clarity, and remote-control pairing before boxing. Which quality method is being used?","options":{"A":"Quality control","B":"Quality assurance","C":"Kaizen","D":"Batch reworking"},"correctOption":"A","correctAnswer":"Quality control","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality control relies on specialist inspectors testing finished products at the end of production before dispatch.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality assurance involves all workers checking standards throughout every stage of production.","C":"Incorrect because Kaizen refers to continuous improvement meetings by staff.","D":"Incorrect because reworking means repairing a defect after it is discovered."}}},{"id":"P1_U4_MCQ_341","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_341","question":"A chocolate factory uses end-of-line quality control where inspectors check finished boxes of chocolates, frequently finding melted or misshapen chocolates caused by an overheated cooling tunnel earlier in the line. What is the key weakness of this approach?","options":{"A":"Faults are only detected after ingredients, packaging, and labour have already been wasted on ruined chocolates","B":"Every worker on the line spends too much time checking cooling tunnel temperatures","C":"Training costs for all factory employees are excessively high","D":"Quality inspectors prevent the cooling tunnel from overheating"},"correctOption":"A","correctAnswer":"Faults are only detected after ingredients, packaging, and labour have already been wasted on ruined chocolates","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because end-of-line quality control catches defects only after the entire production process is complete, resulting in high scrappage waste.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because stage-by-stage monitoring by workers describes quality assurance, not end-of-line quality control.","C":"Incorrect because quality control requires minimal quality training for general production workers.","D":"Incorrect because end-of-line inspectors check finished boxes rather than controlling earlier machinery."}}},{"id":"P1_U4_MCQ_342","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_342","question":"A bank employs anonymous 'mystery callers' to phone its customer helpline and rate how quickly calls are answered, how politely staff speak, and whether accurate financial advice is given. Which quality method does this represent?","options":{"A":"Quality control in a service business","B":"Computer-Aided Manufacturing (CAM)","C":"3D prototyping","D":"Just-in-time inventory control"},"correctOption":"A","correctAnswer":"Quality control in a service business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mystery callers or mystery shoppers inspect and test the finished service experience, functioning as service-sector quality control.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because CAM refers to automated factory machinery.","C":"Incorrect because 3D prototyping builds physical sample models.","D":"Incorrect because JIT manages physical stock arrival."}}},{"id":"P1_U4_MCQ_343","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_343","question":"An electric vehicle battery manufacturer implements quality assurance, requiring every team—from chemical mixing and cell assembly to module testing—to verify strict quality standards before passing batteries onward. What is a major advantage of this system?","options":{"A":"Defects are prevented or caught immediately at each stage, drastically reducing costly end-of-line scrappage and warranty recalls","B":"It requires zero training for factory employees","C":"It completely eliminates the need for raw lithium and cobalt","D":"It allows workers to ignore quality standards whenever production is busy"},"correctOption":"A","correctAnswer":"Defects are prevented or caught immediately at each stage, drastically reducing costly end-of-line scrappage and warranty recalls","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality assurance builds quality into every step of production, preventing faulty components from progressing and reducing waste.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality assurance requires comprehensive staff training.","C":"Incorrect because raw materials are still required to build batteries.","D":"Incorrect because quality assurance enforces strict adherence to standards at all times."}}},{"id":"P1_U4_MCQ_344","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_344","question":"Under quality assurance, an assembly worker spots a slightly bent metal bracket at Station 2, stops the station immediately, and replaces the bracket before the unit moves to Station 3. How does this improve efficiency?","options":{"A":"It stops additional components and labour from being wasted assembling a product that would fail final inspection","B":"It eliminates the need for Station 3 workers to check their own work","C":"It allows bent brackets to be hidden inside finished products","D":"It guarantees zero training costs for new hires"},"correctOption":"A","correctAnswer":"It stops additional components and labour from being wasted assembling a product that would fail final inspection","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because catching and fixing errors early avoids adding further value to a defective item that would later be scrapped or dismantled.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because every station continues checking its own stage under quality assurance.","C":"Incorrect because quality assurance removes defective parts rather than hiding them.","D":"Incorrect because training is still needed so workers recognize defects."}}},{"id":"P1_U4_MCQ_345","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_345","question":"A food-processing company introduces quality assurance across its 400 factory staff, spending $180,000 on training courses and halting lines briefly whenever workers conduct stage checks. Which drawbacks of quality assurance does this highlight?","options":{"A":"High upfront staff training costs and potential slowdowns in production output during checks","B":"Higher end-of-line scrappage costs than quality control","C":"Lower employee motivation and reduced pride in work","D":"Increased customer complaints about contaminated food"},"correctOption":"A","correctAnswer":"High upfront staff training costs and potential slowdowns in production output during checks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because training all workers to monitor quality standards is costly initially, and stage-by-stage verification can slow down output speed.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality assurance lowers end-of-line scrappage compared with quality control.","C":"Incorrect because empowering staff usually increases motivation rather than lowering it.","D":"Incorrect because strict stage checks reduce food safety issues and complaints."}}},{"id":"P1_U4_MCQ_346","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_346","question":"A pharmaceutical company produces sterile injectable vaccines where a single contaminated vial could harm patients and destroy the company's licence to operate. Which quality system is essential here and why?","options":{"A":"Quality assurance (combined with strict testing), because preventing contamination at every stage is vital when human health is at risk","B":"End-of-line visual inspection only, because vaccines are inexpensive disposable items","C":"No quality checks at all, so vaccines reach hospitals faster","D":"Destructive testing of 100% of finished vaccine vials"},"correctOption":"A","correctAnswer":"Quality assurance (combined with strict testing), because preventing contamination at every stage is vital when human health is at risk","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because in life-critical pharmaceutical production, rigorous quality assurance at every stage from raw ingredients to sterile sealing prevents fatal contamination.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because visual inspection at the end cannot detect microscopic contamination inside sealed vials.","C":"Incorrect because skipping quality checks in medicine is illegal and dangerous.","D":"Incorrect because testing 100% of vials destructively would leave zero vaccines to administer to patients."}}},{"id":"P1_U4_MCQ_347","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_347","question":"A seasonal fruit-packing warehouse hires 80 casual workers for four weeks each summer to pack apples into boxes, employing three supervisors to inspect packed boxes before loading lorries. Why is quality control more suitable than quality assurance here?","options":{"A":"Training 80 short-term workers for formal quality assurance is uneconomical compared with supervisor inspection of finished boxes","B":"Apples cannot be inspected by supervisors","C":"Quality assurance is illegal in agricultural packing","D":"Supermarkets do not care if apples are bruised or rotten"},"correctOption":"A","correctAnswer":"Training 80 short-term workers for formal quality assurance is uneconomical compared with supervisor inspection of finished boxes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when staff are temporary and unit error costs are low, end-of-line inspection by experienced supervisors is faster and cheaper than extensive staff training.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supervisors easily inspect packed apple boxes.","C":"Incorrect because there is no law banning quality assurance in agriculture.","D":"Incorrect because supermarkets reject bruised produce, which is why supervisors inspect boxes."}}},{"id":"P1_U4_MCQ_348","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_348","question":"A national chain of dental clinics sets standardized hygiene, equipment sterilization, patient consultation, and follow-up care checklists that every dentist and nurse must sign off for every appointment. How does this benefit the service business?","options":{"A":"It ensures a consistently safe, high-standard patient experience across every branch, building trust and repeat visits","B":"It eliminates the need to buy dental equipment or sterilization fluids","C":"It allows unqualified staff to perform complex dental surgery","D":"It removes the need for dentists to speak to patients"},"correctOption":"A","correctAnswer":"It ensures a consistently safe, high-standard patient experience across every branch, building trust and repeat visits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because service-sector quality assurance standardizes delivery across all locations, protecting patient safety and brand reputation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because dental supplies and sterilization fluids are still required.","C":"Incorrect because only licensed dentists can perform dental procedures.","D":"Incorrect because clear patient communication is part of the consultation standard."}}},{"id":"P1_U4_MCQ_349","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_349","question":"During final quality control at a smartphone factory, inspectors discover loose charging ports on 50 phones and send them back to technicians to resolder the ports ('reworking'), whereas phones with cracked motherboards are discarded ('scrapping'). What determines whether a faulty product is reworked or scrapped?","options":{"A":"Whether the product can be safely repaired for less than its resale value","B":"Whether the factory uses job production or flow production","C":"Whether the inspector prefers morning or afternoon shifts","D":"Whether the factory pays fixed rent or variable rent"},"correctOption":"A","correctAnswer":"Whether the product can be safely repaired for less than its resale value","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reworking makes financial sense when a fault is fixable and repair costs are lower than the item's value, whereas unrepairable or low-value items are scrapped.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the rework-versus-scrap decision depends on repair feasibility and unit value, not production method.","C":"Incorrect because quality decisions follow objective technical and cost criteria.","D":"Incorrect because factory rent does not determine whether a phone is repairable."}}},{"id":"P1_U4_MCQ_350","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_350","question":"A toy manufacturer reduces its defect rate from 5% to 0.2% after adopting quality assurance, cutting warranty returns and material waste significantly. How does improved quality affect the business's break-even position?","options":{"A":"Lower scrappage and reworking costs reduce variable costs per unit, increasing contribution and lowering break-even output","B":"Lower waste increases variable costs per unit and raises break-even output","C":"Improved quality shifts the total revenue line downward","D":"Improved quality has zero effect on business costs or sales"},"correctOption":"A","correctAnswer":"Lower scrappage and reworking costs reduce variable costs per unit, increasing contribution and lowering break-even output","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fewer scrapped materials and less rework labour per good unit sold lowers average variable cost, raising contribution and lowering break-even output.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because reducing waste lowers rather than increases unit costs.","C":"Incorrect because better quality supports higher sales or prices rather than reducing revenue.","D":"Incorrect because quality directly impacts waste costs, warranty expenses, and customer demand."}}},{"id":"P1_U4_MCQ_351","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_351","question":"A hotel group introduces a '100% Satisfaction Guarantee' promising to refund a guest's stay if any room or service standard falls short, alongside rigorous housekeeping checklists before check-in. Why does the hotel combine strict quality assurance with this guarantee?","options":{"A":"Stage-by-stage housekeeping checks prevent room faults from happening so the hotel rarely has to pay out refunds while building guest confidence","B":"The hotel wants to pay refunds to every single guest who stays","C":"Housekeeping checklists eliminate the need to clean hotel bedrooms","D":"Refund guarantees are legally required for all hotels worldwide"},"correctOption":"A","correctAnswer":"Stage-by-stage housekeeping checks prevent room faults from happening so the hotel rarely has to pay out refunds while building guest confidence","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reliable quality assurance keeps defect rates near zero, allowing the business to offer a bold customer guarantee that wins bookings without heavy refund costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because paying frequent refunds would lose money; preventing faults makes the guarantee profitable.","C":"Incorrect because checklists verify that bedrooms are thoroughly cleaned before guests arrive.","D":"Incorrect because satisfaction guarantees are voluntary marketing/quality commitments rather than universal laws."}}},{"id":"P1_U4_MCQ_352","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_352","question":"A car manufacturer tracks customer complaints and discovers that 70% of warranty claims stem from faulty dashboard touchscreens supplied by an external electronics firm. What action should a quality-assured manufacturer take?","options":{"A":"Work with the supplier to enforce stricter quality standards on incoming screens or switch to a more reliable supplier","B":"Stop inspecting dashboard touchscreens so production moves faster","C":"Ignore customer warranty claims and blame car buyers","D":"Remove dashboards from all future cars"},"correctOption":"A","correctAnswer":"Work with the supplier to enforce stricter quality standards on incoming screens or switch to a more reliable supplier","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality assurance begins with incoming components; ensuring suppliers meet strict specifications prevents downstream product failures.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ignoring incoming defects would allow faulty cars to reach customers.","C":"Incorrect because refusing valid warranty claims destroys brand reputation.","D":"Incorrect because cars require functioning instrument displays."}}},{"id":"P1_U4_MCQ_353","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_353","question":"At a traditional craft pottery studio, each potter signs their initials on the base of every handmade bowl after checking its glaze and shape personally. How does this practice support quality?","options":{"A":"Personal accountability motivates craftspeople to take pride in their work and ensure every piece meets high standards","B":"Signing bowls eliminates the need to fire clay in a kiln","C":"It replaces skilled potters with automated assembly robots","D":"It allows cracked bowls to be sold at double price"},"correctOption":"A","correctAnswer":"Personal accountability motivates craftspeople to take pride in their work and ensure every piece meets high standards","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because linking an employee's identity directly to their output fosters personal pride, ownership, and careful self-inspection.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because pottery still must be fired in a kiln.","C":"Incorrect because individual signing is a hallmark of skilled human craftsmanship.","D":"Incorrect because cracked pottery fails quality standards."}}},{"id":"P1_U4_MCQ_354","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_354","question":"Why is maintaining consistent quality often more challenging in a service business (such as a restaurant chain) than in an automated bottling factory?","options":{"A":"Services are delivered directly by human staff whose mood, speed, and interactions can vary from customer to customer","B":"Automated bottling factories never use any quality standards","C":"Restaurant customers do not care about food temperature or waiting times","D":"Service businesses cannot train their employees"},"correctOption":"A","correctAnswer":"Services are delivered directly by human staff whose mood, speed, and interactions can vary from customer to customer","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because services are intangible and produced simultaneously by people, making standardization harder than in automated manufacturing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because automated factories enforce strict standardized tolerances.","C":"Incorrect because diners strongly evaluate food quality, speed, and staff friendliness.","D":"Incorrect because service chains invest heavily in staff training and checklists to overcome variability."}}},{"id":"P1_U4_MCQ_355","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_355","question":"A consumer electronics company rushes a new smartwatch to market before completing battery-life and software-stability testing, leading to overheating complaints and a humiliating product recall. What lesson does this teach operations managers?","options":{"A":"Sacrificing quality to hit an early launch deadline causes far greater financial and reputational damage than delaying launch to fix faults","B":"Product testing is unnecessary for electronic devices","C":"Overheating batteries improve customer loyalty","D":"Recalls are the cheapest way to test new products"},"correctOption":"A","correctAnswer":"Sacrificing quality to hit an early launch deadline causes far greater financial and reputational damage than delaying launch to fix faults","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because releasing unverified, defective goods triggers costly recalls, warranty claims, and long-term brand damage.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because thorough testing is essential for safety and customer satisfaction.","C":"Incorrect because safety hazards destroy customer trust.","D":"Incorrect because recalls are far costlier than pre-launch quality testing."}}},{"id":"P1_U4_MCQ_356","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_356","question":"An industrial valve manufacturer trains its machine operators in statistical process checks so they can adjust cutting tools as soon as measurements drift slightly, before any valve falls outside tolerance limits. Which quality philosophy does this represent?","options":{"A":"Quality assurance focused on defect prevention during production","B":"End-of-line quality control focused solely on scrapping finished valves","C":"Mystery customer shopping","D":"Diseconomies of scale"},"correctOption":"A","correctAnswer":"Quality assurance focused on defect prevention during production","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because monitoring processes continuously and correcting minor drifts before defects occur exemplifies preventative quality assurance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because end-of-line quality control waits until production finishes rather than preventing faults mid-process.","C":"Incorrect because mystery shopping evaluates retail or hospitality customer service.","D":"Incorrect because diseconomies of scale refer to rising average costs from excessive organizational size."}}},{"id":"P1_U4_MCQ_357","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_357","question":"A timber sawmill processes heavy, bulky raw tree trunks into lighter, neatly stacked planks of sawn lumber, losing 45% of the log's weight as bark and sawdust. Where should the sawmill locate to minimize transport costs?","options":{"A":"Close to the forest where the heavy timber logs are felled","B":"In the centre of a crowded capital city far from forests","C":"On an offshore island with no timber or port links","D":"Inside a suburban shopping mall"},"correctOption":"A","correctAnswer":"Close to the forest where the heavy timber logs are felled","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sawmilling is a weight-losing (bulk-reducing) process; locating near the forest avoids paying to transport heavy bark and waste wood long distances.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because hauling heavy whole logs into an expensive city centre incurs high freight and rent costs.","C":"Incorrect because lack of raw materials and transport links makes operating a sawmill impossible.","D":"Incorrect because heavy industrial sawmills cannot locate in shopping malls."}}},{"id":"P1_U4_MCQ_358","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_358","question":"A corrugated cardboard box factory buys compact rolls of flat paper and glues and folds them into bulky, air-filled shipping boxes for e-commerce warehouses. Where is the most economical location for this box factory?","options":{"A":"Close to the major e-commerce distribution hubs that buy the bulky finished boxes","B":"Inside a remote mountain forest 900 kilometres away from customers","C":"On a small island with no road or ferry access","D":"In a city-centre luxury boutique street"},"correctOption":"A","correctAnswer":"Close to the major e-commerce distribution hubs that buy the bulky finished boxes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because assembled cardboard boxes are bulky and expensive to transport over long distances compared with compact paper rolls, favouring location near customers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shipping bulky empty boxes 900 km would incur huge freight costs.","C":"Incorrect because lack of transport links prevents delivering boxes to buyers.","D":"Incorrect because luxury shopping streets have prohibitively high rent and lack lorry access."}}},{"id":"P1_U4_MCQ_359","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_359","question":"A fish-canning company processes freshly caught tuna and sardines that deteriorate rapidly once unloaded from fishing trawlers. Which location factor is most decisive for this factory?","options":{"A":"Locating right beside the fishing port so perishable catch is canned while fresh","B":"Locating in an inland desert city 600 kilometres from the sea","C":"Proximity to university aerospace laboratories","D":"High pedestrian shopping footfall outside the cannery"},"correctOption":"A","correctAnswer":"Locating right beside the fishing port so perishable catch is canned while fresh","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because perishable raw materials like fresh fish must be processed immediately upon landing to prevent spoilage.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because transporting fresh fish 600 km inland before canning increases spoilage and refrigerated freight costs.","C":"Incorrect because aerospace laboratories are irrelevant to fish canning.","D":"Incorrect because canned fish is distributed to supermarkets rather than sold to walk-in factory pedestrians."}}},{"id":"P1_U4_MCQ_360","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_360","question":"A semiconductor fabrication plant requires an uninterrupted ultra-stable electricity supply, millions of gallons of pure water daily, and cleanroom engineers. Which location factors are essential when selecting a site?","options":{"A":"Reliable high-capacity power and water utilities alongside access to specialist engineering graduates","B":"Proximity to open-cast coal mines and seasonal fruit pickers","C":"High street-level tourist footfall outside the cleanroom","D":"Cheap agricultural grazing land with no power grid"},"correctOption":"A","correctAnswer":"Reliable high-capacity power and water utilities alongside access to specialist engineering graduates","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because microchip plants depend critically on continuous power, pure water supplies, and highly skilled technical staff.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fruit pickers lack semiconductor engineering skills and coal dust would ruin cleanrooms.","C":"Incorrect because microchip plants sell to electronics manufacturers rather than passing tourists.","D":"Incorrect because a plant without a reliable power grid cannot operate."}}},{"id":"P1_U4_MCQ_361","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_361","question":"An automotive assembly plant locates in an industrial corridor surrounded by independent tyre makers, seat manufacturers, paint suppliers, and specialist robotics maintenance firms. Which location factor is benefiting the car plant?","options":{"A":"External economies of scale from locating close to supporting component suppliers and specialist service firms","B":"Government bans on automotive manufacturing","C":"High city-centre retail rents","D":"Perishability of finished steel car bodies"},"correctOption":"A","correctAnswer":"External economies of scale from locating close to supporting component suppliers and specialist service firms","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because clustering near component suppliers and maintenance specialists lowers transport costs, enables JIT deliveries, and speeds up equipment repairs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because government bans would prevent locating in the corridor.","C":"Incorrect because industrial corridors sit outside expensive retail city centres.","D":"Incorrect because steel car bodies are durable rather than perishable."}}},{"id":"P1_U4_MCQ_362","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_362","question":"A national government offers a 10-year exemption from corporate profit taxes and subsidised worker training grants to any manufacturer opening a factory in a rural region suffering from factory closures. How does this influence location decisions?","options":{"A":"Government financial incentives lower operating costs and attract businesses to create jobs in high-unemployment areas","B":"Tax exemptions force manufacturers to charge higher selling prices","C":"Government grants prevent factories from hiring local workers","D":"Financial incentives only apply to companies that pollute rivers"},"correctOption":"A","correctAnswer":"Government financial incentives lower operating costs and attract businesses to create jobs in high-unemployment areas","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because governments use tax holidays and training subsidies to attract investment and reduce regional unemployment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lower tax and training costs improve profitability rather than forcing higher prices.","C":"Incorrect because grants are conditional on creating local employment.","D":"Incorrect because governments attach environmental compliance conditions to grants."}}},{"id":"P1_U4_MCQ_363","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_363","question":"A waste-incineration and recycling facility is refused planning approval to build next to a freshwater reservoir and residential suburb. Which location factor blocked this site?","options":{"A":"Government environmental and planning regulations protecting public health, water supplies, and residential communities","B":"Lack of household waste in suburban cities","C":"Excessive government subsidies beside freshwater reservoirs","D":"High pedestrian shopping footfall"},"correctOption":"A","correctAnswer":"Government environmental and planning regulations protecting public health, water supplies, and residential communities","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because government zoning and environmental laws prevent potentially polluting facilities from locating near water supplies and homes.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because suburbs generate substantial waste, but planning laws forbid incinerators beside homes and reservoirs.","C":"Incorrect because governments do not subsidize incinerators beside drinking-water reservoirs.","D":"Incorrect because waste incinerators do not seek pedestrian footfall."}}},{"id":"P1_U4_MCQ_364","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_364","question":"A dental practice, a pharmacy, and a coffee shop open in a newly built suburban shopping plaza surrounded by 3,000 new family homes and ample car parking. Why is this location ideal for these service businesses?","options":{"A":"Direct personal services depend on convenient customer access, high local footfall, and easy parking","B":"Dentists and coffee shops require heavy freight railway sidings","C":"Rent in busy suburban shopping plazas is zero","D":"These businesses use automated flow production for mass exports"},"correctOption":"A","correctAnswer":"Direct personal services depend on convenient customer access, high local footfall, and easy parking","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumer services requiring face-to-face visits succeed when located conveniently close to residential populations with easy access.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because local retail and healthcare services do not use freight railways.","C":"Incorrect because shopping plaza units charge commercial rent.","D":"Incorrect because these are local personal services rather than export factories."}}},{"id":"P1_U4_MCQ_365","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_365","question":"A digital marketing agency serves clients across Europe entirely via video calls and cloud collaboration tools, so its founders locate their office in a low-rent seaside town with high-speed fibre broadband. How has technology shaped this location choice?","options":{"A":"Fast telecommunications remove the need to pay high city-centre rents when services are delivered remotely online","B":"Clients travel to the seaside town every morning for face-to-face meetings","C":"Seaside towns have zero electricity or internet costs","D":"Digital marketing agencies must locate next to deep-water container ports"},"correctOption":"A","correctAnswer":"Fast telecommunications remove the need to pay high city-centre rents when services are delivered remotely online","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because modern broadband and video conferencing allow remote service businesses to locate in lower-cost, attractive towns without losing client access.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because client meetings take place via video calls rather than daily travel.","C":"Incorrect because businesses still pay for electricity and broadband.","D":"Incorrect because digital marketing delivers online campaigns rather than physical shipping containers."}}},{"id":"P1_U4_MCQ_366","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_366","question":"A ski-equipment rental shop and mountain guiding service open in an alpine village with heavy winter snowfall and popular ski slopes. Which location factor is most critical for this service business?","options":{"A":"Climate and natural geographical conditions suitable for winter sports tourism","B":"Proximity to tropical sandy beaches","C":"Availability of low-cost textile factory machinists","D":"Access to heavy iron-ore smelting plants"},"correctOption":"A","correctAnswer":"Climate and natural geographical conditions suitable for winter sports tourism","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because climate and natural terrain directly determine customer demand for seasonal tourism and outdoor recreation services.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tropical beaches lack snow for skiing.","C":"Incorrect because ski rental shops need ski technicians and guides rather than textile machinists.","D":"Incorrect because heavy smelting plants are unrelated to alpine tourism."}}},{"id":"P1_U4_MCQ_367","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_367","question":"A corporate law firm rents offices on the same street as major investment banks, audit firms, and the commercial court in a capital city, despite paying very high office rent. Why is this location worth the high rent?","options":{"A":"Close proximity to corporate clients, supporting financial institutions, and courts facilitates face-to-face meetings and prestige","B":"Law firms manufacture heavy steel girders in their city offices","C":"High office rent reduces the firm's corporate tax rate to zero","D":"Investment banks pay the law firm's office rent"},"correctOption":"A","correctAnswer":"Close proximity to corporate clients, supporting financial institutions, and courts facilitates face-to-face meetings and prestige","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because professional B2B service firms benefit from locating near corporate clients, courts, and complementary business services.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because law firms provide intangible legal services rather than manufacturing steel.","C":"Incorrect because paying higher rent is a business expense, not a zero-tax exemption.","D":"Incorrect because the law firm pays its own rent out of client fees."}}},{"id":"P1_U4_MCQ_368","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_368","question":"A freelance graphic designer works from a converted spare room in his home in a rural village so he can care for his elderly parents while serving clients nationwide by email. Which two location factors explain this choice?","options":{"A":"Personal family preference and modern IT/internet communication","B":"Proximity to weight-losing raw materials and heavy freight ports","C":"Government enterprise zone grants and high street pedestrian footfall","D":"Warm tropical climate and proximity to coal mines"},"correctOption":"A","correctAnswer":"Personal family preference and modern IT/internet communication","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because family responsibilities reflect personal preference, while email and cloud tools make working from a rural home feasible.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a freelance designer uses no heavy physical raw materials or freight ports.","C":"Incorrect because a home-based designer does not rely on walk-in high-street shoppers.","D":"Incorrect because climate and coal mines are irrelevant to home-based graphic design."}}},{"id":"P1_U4_MCQ_369","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_369","question":"A retail clothing chain compares two sites for a new store: Site X in a busy city mall costs $25,000/month in rent and generates $180,000/month in sales, while Site Y on a quiet side street costs $6,000/month in rent and generates $40,000/month in sales. Why is Site X the better location despite much higher rent?","options":{"A":"High customer footfall at Site X generates $140,000 more monthly revenue, easily outweighing the $19,000 extra rent","B":"Site Y has higher rent than Site X","C":"Retail shops never need customers to visit their stores","D":"Rent at Site X will fall to zero after one month"},"correctOption":"A","correctAnswer":"High customer footfall at Site X generates $140,000 more monthly revenue, easily outweighing the $19,000 extra rent","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retail location decisions must weigh rent costs against revenue potential; high footfall in prime malls generates far more sales than the extra rent.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Site X ($25,000) has higher rent than Site Y ($6,000).","C":"Incorrect because physical retail stores rely directly on shopper footfall.","D":"Incorrect because commercial mall rent continues every month."}}},{"id":"P1_U4_MCQ_370","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_370","question":"A US electric vehicle manufacturer builds a giant battery and car factory in Germany to sell directly to European customers. Besides avoiding European Union import tariffs, what operational benefit does this international location provide?","options":{"A":"Eliminating expensive transoceanic shipping of heavy vehicles and speeding up delivery to European buyers","B":"Paying lower shipping costs than transporting cars across the Atlantic Ocean","C":"Eliminating all German environmental and labour laws","D":"Ensuring German workers speak only English"},"correctOption":"A","correctAnswer":"Eliminating expensive transoceanic shipping of heavy vehicles and speeding up delivery to European buyers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because manufacturing heavy vehicles inside the European market avoids costly sea freight and port delays while improving responsiveness to local demand.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Option A already states the core freight and delivery benefit clearly without awkward phrasing.","C":"Incorrect because foreign-owned factories in Germany must obey all German and EU laws.","D":"Incorrect because the firm must still manage German-English communication in the workplace."}}},{"id":"P1_U4_MCQ_371","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_371","question":"A toy manufacturer moves assembly from a high-wage European country to Vietnam, where factory wages are much lower and the government offers five years of tax breaks. Which two advantages of locating abroad are driving this move?","options":{"A":"Lower unit labour costs and host-country government financial incentives","B":"Higher corporate tax rates and slower shipping to Europe","C":"Elimination of all language and cultural differences","D":"Higher hourly wages for assembly workers"},"correctOption":"A","correctAnswer":"Lower unit labour costs and host-country government financial incentives","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lower wage rates reduce variable labour costs in toy assembly while host-government tax breaks increase net profitability.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tax breaks lower taxes rather than raising them.","C":"Incorrect because operating in Vietnam requires managing language and cultural differences.","D":"Incorrect because the business moved specifically to benefit from lower hourly wages."}}},{"id":"P1_U4_MCQ_372","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_372","question":"A European food company builds a fruit-juice processing plant in Costa Rica right next to pineapple and orange farms. Why is locating near overseas raw materials advantageous?","options":{"A":"Fresh fruit can be processed immediately before spoiling, and shipping concentrated juice costs far less than shipping whole raw fruit","B":"Pineapples grow faster inside European factories","C":"Costa Rica has zero transport infrastructure","D":"It eliminates the need to pay farmers for fruit"},"correctOption":"A","correctAnswer":"Fresh fruit can be processed immediately before spoiling, and shipping concentrated juice costs far less than shipping whole raw fruit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because processing perishable, bulky fruit at the overseas agricultural source prevents spoilage and reduces international freight weight.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tropical fruits grow naturally in Costa Rica's climate.","C":"Incorrect because exporting concentrated juice requires ports and transport links.","D":"Incorrect because the company still purchases fruit from local growers."}}},{"id":"P1_U4_MCQ_373","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_373","question":"A fast-food chain expands into a new country without adapting its menu to local dietary customs and translates its advertising slogans poorly, resulting in weak sales and public embarrassment. Which challenge of international location does this illustrate?","options":{"A":"Language and cultural barriers requiring local market knowledge and adaptation","B":"Excessive bulk-buying discounts from local ingredient suppliers","C":"Lower corporate tax rates in the host country","D":"Too many government grants for new restaurants"},"correctOption":"A","correctAnswer":"Language and cultural barriers requiring local market knowledge and adaptation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because failing to understand local language nuances, culture, and consumer preferences can cause costly marketing and operational mistakes abroad.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because bulk discounts lower costs rather than causing cultural embarrassment.","C":"Incorrect because lower taxes are a financial advantage, not a cultural barrier.","D":"Incorrect because government grants support expansion rather than causing menu failures."}}},{"id":"P1_U4_MCQ_374","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_374","question":"A precision medical-device company decides to keep manufacturing in its high-wage home country rather than relocating to a low-wage country overseas, even though labour costs would be 60% lower. What is the most likely operational reason for this decision?","options":{"A":"Maintaining strict quality assurance, protecting intellectual property, and retaining highly skilled specialist engineers","B":"Low-wage countries have zero ports or airports","C":"Medical devices require zero quality or safety checks","D":"High-wage countries charge zero corporate taxes"},"correctOption":"A","correctAnswer":"Maintaining strict quality assurance, protecting intellectual property, and retaining highly skilled specialist engineers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because for complex, safety-critical products, access to specialist engineers, tight quality control, and IP protection often outweigh lower foreign wages.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because many low-wage countries have major ports and airports.","C":"Incorrect because medical devices face the strictest safety and quality regulations.","D":"Incorrect because high-wage countries still levy corporate taxes."}}},{"id":"P1_U4_MCQ_375","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_375","question":"An international electronics manufacturer operates factories in four countries across Asia and Europe, giving it flexibility to shift production if one country experiences a natural disaster, strike, or sudden tariff increase. What strategic advantage of multi-country location does this demonstrate?","options":{"A":"Spreading operational risk so a disruption or trade barrier in one country does not halt global supply","B":"Eliminating all fixed factory costs across all four countries","C":"Ensuring every country uses the exact same currency and language","D":"Removing the need for international logistics and quality management"},"correctOption":"A","correctAnswer":"Spreading operational risk so a disruption or trade barrier in one country does not halt global supply","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because operating production sites in multiple countries diversifies supply-chain risk against localized strikes, disasters, currency shocks, or tariffs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because running four factories involves fixed costs at each site.","C":"Incorrect because operating across Asia and Europe involves multiple currencies and languages.","D":"Incorrect because multi-country operations require strong logistics and quality coordination."}}},{"id":"P1_U4_MCQ_376","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_376","question":"A ceramic studio buys clay, glaze, and a protective gift box for $2.40 per vase, pays potters $4.10 per vase in wages, and sells each finished vase for $14.00. What is the added value per vase created by the studio?","options":{"A":"$7.50","B":"$11.60","C":"$6.50","D":"$14.00"},"correctOption":"B","correctAnswer":"$11.60","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value is the selling price of the finished product ($14.00) minus the cost of bought-in materials and packaging ($2.40), which equals $11.60.","distractor_reasons":{"A":"Incorrect because $7.50 deducts internal labour wages ($4.10) as well as bought-in materials ($2.40), calculating profit per unit rather than added value.","B":"Correct selection.","C":"Incorrect because $6.50 is the sum of bought-in material costs and wages ($2.40 + $4.10).","D":"Incorrect because $14.00 is the selling price before subtracting the cost of bought-in inputs."}}},{"id":"P1_U4_MCQ_377","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_377","question":"A specialty tea producer buys loose tea leaves for $1.50 per tin and sells each tin for $6.00. Which operational action would directly increase the added value per tin without raising the selling price?","options":{"A":"Sourcing equally aromatic tea leaves from a lower-cost grower at $1.10 per tin while maintaining the $6.00 selling price","B":"Increasing factory supervisor salaries by 15%","C":"Spending more on expensive gold-plated tins while keeping the price at $6.00","D":"Reducing the selling price to $5.00 per tin"},"correctOption":"A","correctAnswer":"Sourcing equally aromatic tea leaves from a lower-cost grower at $1.10 per tin while maintaining the $6.00 selling price","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lowering the cost of bought-in raw materials from $1.50 to $1.10 while holding the selling price at $6.00 increases added value from $4.50 to $4.90 per tin.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because internal supervisor salaries are a business expense paid out of added value, not a bought-in material cost.","C":"Incorrect because spending more on bought-in tin packaging without raising price reduces added value.","D":"Incorrect because lowering the selling price to $5.00 reduces added value from $4.50 to $3.50."}}},{"id":"P1_U4_MCQ_378","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_378","question":"A garment factory employs 60 sewing machinists who produce a total of 15,000 cotton shirts per week. What is the weekly labour productivity of this factory?","options":{"A":"15,000 shirts per week","B":"60 shirts per worker","C":"250 shirts per worker","D":"900,000 shirts per week"},"correctOption":"C","correctAnswer":"250 shirts per worker","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because labour productivity equals total output (15,000 shirts) divided by the number of workers (60), which gives 250 shirts per worker per week.","distractor_reasons":{"A":"Incorrect because 15,000 shirts is total production (output), not output per employee.","B":"Incorrect because 60 is the number of machinists rather than output per worker.","C":"Correct selection.","D":"Incorrect because this multiplies output by the number of employees instead of dividing."}}},{"id":"P1_U4_MCQ_379","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_379","question":"Factory X employs 40 workers and produces 12,000 wooden toys per month, while Factory Y employs 50 workers and produces 14,000 identical toys per month. Which statement accurately compares the two factories?","options":{"A":"Factory Y has both higher total production and higher labour productivity","B":"Factory X has lower total production (12,000 vs 14,000) but higher labour productivity (300 vs 280 toys per worker)","C":"Both factories have identical labour productivity of 300 toys per worker","D":"Factory X has higher total production than Factory Y"},"correctOption":"B","correctAnswer":"Factory X has lower total production (12,000 vs 14,000) but higher labour productivity (300 vs 280 toys per worker)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Factory X's total output is 12,000 (lower than Factory Y's 14,000), while its labour productivity is 12,000 / 40 = 300 toys per worker compared with Factory Y's 14,000 / 50 = 280 toys per worker.","distractor_reasons":{"A":"Incorrect because Factory Y's labour productivity is 280 toys per worker, which is lower than Factory X's 300.","B":"Correct selection.","C":"Incorrect because 14,000 / 50 equals 280 toys per worker, not 300.","D":"Incorrect because 12,000 toys is less than 14,000 toys."}}},{"id":"P1_U4_MCQ_380","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_380","question":"A packaging plant wants to increase its labour productivity without hiring extra staff. Which action is most likely to achieve this goal?","options":{"A":"Providing targeted machine-operation training and reorganising workstations to eliminate walking between machines","B":"Reducing employee rest breaks so workers become exhausted","C":"Replacing electric carton-folding machines with manual scissors","D":"Stopping routine maintenance on conveyor belts"},"correctOption":"A","correctAnswer":"Providing targeted machine-operation training and reorganising workstations to eliminate walking between machines","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because improving worker skills through training and streamlining factory layout enable each employee to produce more output per hour.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because overtired workers work more slowly and make more mistakes, lowering productivity.","C":"Incorrect because reverting to manual scissors slows down output per worker.","D":"Incorrect because neglecting maintenance causes frequent machine breakdowns that reduce output."}}},{"id":"P1_U4_MCQ_381","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_381","question":"A soft-drinks canning plant uses high-speed automated filling, sealing, and palletising lines supervised by six engineers, whereas a bespoke tailor shop employs twenty skilled tailors cutting and stitching suits by hand. How do their production approaches differ?","options":{"A":"The canning plant uses capital-intensive production, whereas the tailor shop uses labour-intensive production","B":"Both businesses use capital-intensive production","C":"The canning plant uses labour-intensive production, whereas the tailor shop uses capital-intensive production","D":"Neither business uses any factors of production"},"correctOption":"A","correctAnswer":"The canning plant uses capital-intensive production, whereas the tailor shop uses labour-intensive production","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the canning plant relies predominantly on expensive automated machinery (capital-intensive), while the tailor shop relies mainly on skilled human labour (labour-intensive).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because twenty tailors stitching suits by hand rely primarily on human labour rather than heavy machinery.","C":"Incorrect because the descriptions are reversed.","D":"Incorrect because both businesses combine labour, capital, land, and enterprise."}}},{"id":"P1_U4_MCQ_382","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_382","question":"Why do multinational electronics manufacturers often use capital-intensive robotic lines in countries with high minimum wages, while using more labour-intensive assembly in countries with abundant, lower-wage workers?","options":{"A":"Businesses choose the mix of capital and labour that minimizes average production cost per unit given local wage rates and machinery costs","B":"Robotic machinery is legally banned in countries with low minimum wages","C":"Workers in high-wage countries refuse to work in factories","D":"Labour-intensive production always has higher fixed loan interest costs than robotics"},"correctOption":"A","correctAnswer":"Businesses choose the mix of capital and labour that minimizes average production cost per unit given local wage rates and machinery costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit-seeking operations select the combination of machinery and labour that achieves the lowest unit cost based on relative factor prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no law bans robotics in low-wage economies; it is simply often less economical than hiring affordable labour.","C":"Incorrect because workers in high-wage countries work in manufacturing, though often operating automated equipment.","D":"Incorrect because capital-intensive robotics incurs high fixed capital and loan interest costs."}}},{"id":"P1_U4_MCQ_383","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_383","question":"At an appliance factory, metal casings are stamped in Building A, driven by lorry two kilometres across town to Building B for powder-coating, and driven back to Building A for final assembly. Which lean production waste is occurring?","options":{"A":"Transportation","B":"Over-processing","C":"Non-utilised skills","D":"Defects"},"correctOption":"A","correctAnswer":"Transportation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because moving materials or work-in-progress unnecessarily between separate sites or distant areas adds cost, time, and damage risk without adding customer value.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because over-processing means adding unnecessary features or extra finishing steps.","C":"Incorrect because non-utilised skills occur when qualified staff perform menial tasks.","D":"Incorrect because defects refer to faulty items requiring scrap or rework."}}},{"id":"P1_U4_MCQ_384","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_384","question":"A clothing manufacturer keeps six months' worth of dyed fabric rolls stacked in rented overflow warehouses, where many rolls fade in sunlight or go out of fashion before being cut. Which lean production waste does this illustrate?","options":{"A":"Waiting","B":"Motion","C":"Inventory","D":"Non-utilised skills"},"correctOption":"C","correctAnswer":"Inventory","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because holding excess inventory ties up working capital, requires expensive warehouse rent, and exposes stock to damage and obsolescence.","distractor_reasons":{"A":"Incorrect because waiting waste refers to idle workers or machines paused between production stages.","B":"Incorrect because motion waste refers to unnecessary physical reaching or walking by workers.","C":"Correct selection.","D":"Incorrect because non-utilised skills refer to underusing employee qualifications."}}},{"id":"P1_U4_MCQ_385","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_385","question":"A printed circuit board factory discovers that 12% of soldered boards fail electrical testing and must be thrown into scrap bins. Which lean production waste is reducing the plant's efficiency?","options":{"A":"Defects","B":"Transportation","C":"Waiting","D":"Motion"},"correctOption":"A","correctAnswer":"Defects","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because producing faulty items that must be scrapped or reworked wastes materials, machine time, and labour hours.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because transportation waste involves unnecessary movement of goods between locations.","C":"Incorrect because waiting waste involves idle queues between operations.","D":"Incorrect because motion waste involves unnecessary body movements by staff."}}},{"id":"P1_U4_MCQ_386","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_386","question":"A logistics firm assigns two university-trained supply-chain analysts to spend four hours every afternoon taping cardboard boxes and printing address stickers. Which waste in lean production is taking place?","options":{"A":"Overproduction","B":"Non-utilised skills","C":"Transportation","D":"Defects"},"correctOption":"B","correctAnswer":"Non-utilised skills","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because failing to use employees' specialist training, qualifications, and creative problem-solving abilities wastes human potential and lowers morale.","distractor_reasons":{"A":"Incorrect because overproduction means making more goods than customers ordered.","B":"Correct selection.","C":"Incorrect because transportation waste refers to moving materials unnecessarily.","D":"Incorrect because defects refer to damaged or faulty output."}}},{"id":"P1_U4_MCQ_387","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_387","question":"Under a Kaizen programme, workers at a bicycle assembly plant suggest rearranging straight assembly benches into compact U-shaped cells so components pass directly from hand to hand. What is the main operational result of this change?","options":{"A":"Reduced waiting and motion waste, faster throughput times, and stronger teamwork among cell members","B":"Increased floor space needed for storing half-finished bicycles","C":"Complete elimination of human workers from the assembly plant","D":"Higher borrowing costs from purchasing multimillion-dollar robots"},"correctOption":"A","correctAnswer":"Reduced waiting and motion waste, faster throughput times, and stronger teamwork among cell members","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cell production arranged in U-shaped teams minimizes movement and waiting between steps while empowering workers to solve problems together.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because compact U-shaped cells require less floor space and hold minimal work-in-progress.","C":"Incorrect because cell production relies on multi-skilled human teams.","D":"Incorrect because reorganising existing benches is a low-cost Kaizen improvement rather than expensive robotics."}}},{"id":"P1_U4_MCQ_388","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_388","question":"Which set of conditions is essential for a car manufacturer to operate a just-in-time (JIT) inventory system successfully?","options":{"A":"Highly reliable suppliers nearby, accurate computerized ordering links, and multi-skilled workers","B":"Huge warehouses holding six months of spare engines and tyres","C":"Frequent transport strikes and unpredictable overseas shipping times","D":"Producing millions of cars in advance without customer orders"},"correctOption":"A","correctAnswer":"Highly reliable suppliers nearby, accurate computerized ordering links, and multi-skilled workers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because with zero buffer stock, JIT depends on punctual suppliers, real-time IT coordination, and flexible staff able to prevent bottlenecks.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because holding six months of buffer inventory is the exact opposite of JIT.","C":"Incorrect because transport strikes and unpredictable delays cause immediate production shutdowns under JIT.","D":"Incorrect because JIT pulls production based on actual demand rather than building huge speculative stock."}}},{"id":"P1_U4_MCQ_389","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_389","question":"An inventory control chart for a clothing factory shows a maximum inventory level of 1,200 rolls of fabric, a reorder level of 500 rolls, and a minimum (buffer) inventory level of 200 rolls. If an order is placed on Day 4 when inventory reaches 500 rolls and the delivery arrives on Day 7 when inventory reaches 200 rolls, what is the supplier's lead time shown on the chart?","options":{"A":"3 days","B":"4 days","C":"7 days","D":"200 rolls"},"correctOption":"A","correctAnswer":"3 days","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lead time on an inventory control chart is the time elapsed between placing the order (Day 4) and receiving the delivery (Day 7), which is 3 days.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Day 4 is the day the reorder is placed rather than the duration of the wait.","C":"Incorrect because Day 7 is the day the delivery arrives rather than the time elapsed since ordering.","D":"Incorrect because 200 rolls measures the minimum buffer inventory quantity rather than delivery time."}}},{"id":"P1_U4_MCQ_390","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_390","question":"A consumer electronics distributor holds $4 million worth of unsold tablets and laptops in a climate-controlled warehouse. Besides warehouse rent and insurance, what is a major hidden cost of holding this large inventory?","options":{"A":"Opportunity cost of $4 million in tied-up cash and high risk of models becoming technologically obsolete","B":"Increased bulk-buying discounts from tablet manufacturers","C":"Lower risk of stockouts during holiday shopping peaks","D":"Reduced security guard expenses at the warehouse"},"correctOption":"A","correctAnswer":"Opportunity cost of $4 million in tied-up cash and high risk of models becoming technologically obsolete","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash locked up in slow-moving stock cannot be invested elsewhere, and electronics rapidly lose value when newer models launch.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because bulk discounts are a potential benefit of large orders, not a cost of holding stock.","C":"Incorrect because avoiding stockouts is an advantage of holding stock, not a cost.","D":"Incorrect because high-value electronics require more security, not less."}}},{"id":"P1_U4_MCQ_391","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_391","question":"A hardware store keeps minimal inventory of snow shovels to save storeroom space, so when an unexpected heavy blizzard hits the city, it sells out within two hours and turns away 300 customers. What consequence of low inventory does this show?","options":{"A":"Stockouts during sudden demand spikes cause lost sales revenue and disappointed customers switching to rivals","B":"Excessive warehouse heating and insurance costs","C":"High obsolescence losses from unsold snow shovels","D":"Overproduction of winter hardware"},"correctOption":"A","correctAnswer":"Stockouts during sudden demand spikes cause lost sales revenue and disappointed customers switching to rivals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because holding insufficient buffer stock leaves a business unable to meet unexpected surges in demand, forfeiting sales and customer goodwill.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because minimal inventory lowers storage costs rather than raising them.","C":"Incorrect because all shovels sold out immediately; there was no unsold stock.","D":"Incorrect because the store under-stocked rather than overproduced."}}},{"id":"P1_U4_MCQ_392","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_392","question":"A master carpenter designs and builds a curved solid-oak spiral staircase specifically measured to fit the dimensions of a client's newly built villa. Which production method is being used?","options":{"A":"Flow production","B":"Job production","C":"Batch production","D":"Continuous mass assembly"},"correctOption":"B","correctAnswer":"Job production","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because job production creates a single, unique item made to an individual customer's exact specifications.","distractor_reasons":{"A":"Incorrect because flow production manufactures large volumes of identical standardized products continuously.","B":"Correct selection.","C":"Incorrect because batch production makes groups of identical items together.","D":"Incorrect because continuous mass assembly applies to standardized mass-market goods."}}},{"id":"P1_U4_MCQ_393","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_393","question":"A decorative paint factory mixes 5,000 litres of matte sky-blue wall paint, drains and flushes the mixing tanks, and then mixes 5,000 litres of gloss forest-green paint. Which production method is this?","options":{"A":"Job production","B":"Batch production","C":"Flow production","D":"Just-in-time bespoke tailoring"},"correctOption":"B","correctAnswer":"Batch production","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because batch production manufactures a set quantity (batch) of one product variant before cleaning and resetting machinery for another variant.","distractor_reasons":{"A":"Incorrect because job production creates single one-off items for individual buyers.","B":"Correct selection.","C":"Incorrect because flow production runs continuously making one standardized product without stopping to change colours.","D":"Incorrect because this is bulk paint manufacturing, not bespoke tailoring."}}},{"id":"P1_U4_MCQ_394","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_394","question":"A paper mill operates a continuous automated paper-making machine 24 hours a day, turning wood pulp into thousands of identical rolls of standard white printer paper. What is a major advantage of this flow production method?","options":{"A":"Economies of scale and continuous high-speed output result in very low average cost per roll of paper","B":"Every roll of paper is uniquely watermarked for individual retail shoppers","C":"The paper machine requires zero upfront capital investment","D":"Machinery can be switched off every ten minutes at zero cost"},"correctOption":"A","correctAnswer":"Economies of scale and continuous high-speed output result in very low average cost per roll of paper","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because continuous flow production maximizes output of a standardized product, spreading high fixed equipment costs over huge volumes to achieve low unit costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because flow production produces standardized identical goods rather than bespoke items.","C":"Incorrect because continuous paper-making machines require massive capital investment.","D":"Incorrect because stopping a continuous flow line is costly and disruptive."}}},{"id":"P1_U4_MCQ_395","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_395","question":"A craft hot-sauce maker originally cooked 200 bottles per week in batches, but after winning a national supermarket contract for 80,000 identical bottles every week, it invests in a continuous automated bottling and labelling line. Why is switching from batch to flow production justified?","options":{"A":"High, steady mass-market demand for a standardized product allows the firm to lower unit costs and meet large weekly volumes","B":"Supermarkets require every single bottle of hot sauce to have a different recipe","C":"Flow production eliminates the need to purchase chilli peppers and glass bottles","D":"Batch production has lower average unit costs than flow production at 80,000 bottles per week"},"correctOption":"A","correctAnswer":"High, steady mass-market demand for a standardized product allows the firm to lower unit costs and meet large weekly volumes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because large, predictable orders for an identical product make capital-intensive flow production economical and capable of fulfilling high volumes on time.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the contract is for 80,000 identical standardized bottles.","C":"Incorrect because raw ingredients and bottles still must be purchased.","D":"Incorrect because batch setup downtime makes batch production far costlier per unit at massive volumes."}}},{"id":"P1_U4_MCQ_396","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_396","question":"How does worker job satisfaction typically compare between bespoke job production and repetitive assembly-line flow production?","options":{"A":"Job production usually offers higher job satisfaction due to varied, skilled tasks and visible end results, whereas flow production can cause boredom","B":"Flow production gives workers complete freedom to design every product from scratch","C":"Job production involves repeating the exact same 5-second bolt-tightening motion all day","D":"Worker motivation is identical under all production methods"},"correctOption":"A","correctAnswer":"Job production usually offers higher job satisfaction due to varied, skilled tasks and visible end results, whereas flow production can cause boredom","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because skilled workers in job production see a unique item completed from start to finish, whereas narrow, repetitive tasks in flow production often lead to monotony.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because flow production follows strict standardized assembly steps.","C":"Incorrect because repeating a 5-second motion describes assembly-line flow production, not job production.","D":"Incorrect because task variety and autonomy vary greatly across production methods."}}},{"id":"P1_U4_MCQ_397","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_397","question":"Aerospace engineers use Computer-Aided Design (CAD) software to test how a new aircraft wing shape bends under extreme wind speeds on a computer screen before building any physical prototype. What is the main benefit of using CAD here?","options":{"A":"Design flaws can be spotted and modified rapidly at low cost without building expensive physical models","B":"CAD software automatically rivets aluminium wing panels in the factory","C":"CAD scans passenger boarding passes at airport gates","D":"CAD eliminates the need to employ qualified aerospace engineers"},"correctOption":"A","correctAnswer":"Design flaws can be spotted and modified rapidly at low cost without building expensive physical models","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because CAD enables digital 3D modelling and stress simulation, accelerating design iterations and saving prototype costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because physical factory machining and assembly are CAM/robotics, not CAD.","C":"Incorrect because gate scanners are barcode/QR readers.","D":"Incorrect because skilled engineers operate CAD software to create and evaluate designs."}}},{"id":"P1_U4_MCQ_398","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_398","question":"A sheet-metal fabricator sends digital blueprints straight to Computer-Aided Manufacturing (CAM) laser cutters that slice stainless-steel kitchen countertops to 0.05 mm accuracy. Which advantage of CAM does this demonstrate?","options":{"A":"Consistent, high-precision manufacturing with less scrap material than manual cutting","B":"Zero electricity consumption during laser cutting","C":"Elimination of the need to buy stainless-steel sheets","D":"Zero initial cost to purchase the laser-cutting machines"},"correctOption":"A","correctAnswer":"Consistent, high-precision manufacturing with less scrap material than manual cutting","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because CAM translates digital designs directly into automated machine movements, achieving exact repeatability and minimizing cutting errors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because industrial laser cutters require substantial electrical power.","C":"Incorrect because stainless-steel sheets are still the primary raw material.","D":"Incorrect because CAM laser cutters require heavy upfront capital investment."}}},{"id":"P1_U4_MCQ_399","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_399","question":"When a sports-shoe manufacturer links its digital 3D footwear design software (CAD) directly to automated computer-controlled cutting and stitching machines (CAM) on the factory floor, what integrated system is it using?","options":{"A":"Computer-Integrated Manufacturing (CIM)","B":"Manual craft job production","C":"Electronic Point of Sale (EPOS)","D":"Quality control mystery shopping"},"correctOption":"A","correctAnswer":"Computer-Integrated Manufacturing (CIM)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Computer-Integrated Manufacturing (CIM) combines CAD and CAM into a unified digital workflow from design through production.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because manual craft production uses hand tools rather than integrated CAD/CAM systems.","C":"Incorrect because EPOS operates at retail store checkouts.","D":"Incorrect because mystery shopping evaluates customer service in retail or hospitality."}}},{"id":"P1_U4_MCQ_400","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_400","question":"A medical clinic scans a patient's fractured forearm and uses a 3D printer to produce a lightweight, ventilated plastic cast tailored precisely to the patient's arm shape. Why is 3D printing suited to this application?","options":{"A":"It manufactures unique, custom-fitted items directly from digital scans without needing expensive moulds","B":"It mass-produces 50,000 identical casts per hour on an assembly line","C":"It requires no computer scan or digital file","D":"It uses zero plastic polymer material"},"correctOption":"A","correctAnswer":"It manufactures unique, custom-fitted items directly from digital scans without needing expensive moulds","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 3D printing builds bespoke shapes layer-by-layer from digital scans, making individual customization affordable without custom tooling.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because each patient's arm is unique and 3D printers print items individually rather than 50,000 per hour.","C":"Incorrect because 3D printers rely on digital 3D scan/CAD files.","D":"Incorrect because 3D printers consume polymer filament or resin."}}},{"id":"P1_U4_MCQ_401","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_401","question":"An automotive plant installs robotic arms to spray-paint car bodies inside sealed booths, applying exact paint thickness without breaks or exposure to toxic paint fumes. What are two benefits of using robotics here?","options":{"A":"Consistent paint finish with less wasted paint and improved worker health and safety","B":"Zero initial purchase cost and zero maintenance requirements","C":"Greater variation in paint colour between cars and higher wage bills","D":"Increased exposure of human sprayers to toxic fumes"},"correctOption":"A","correctAnswer":"Consistent paint finish with less wasted paint and improved worker health and safety","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because industrial robots perform repetitive spraying with uniform accuracy while keeping human workers out of hazardous paint booths.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because industrial robots have high upfront purchase and maintenance costs.","C":"Incorrect because robots ensure uniform finish and reduce direct spraying wages.","D":"Incorrect because robots replace human workers inside the toxic spray booth."}}},{"id":"P1_U4_MCQ_402","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_402","question":"A supermarket chain uses Electronic Point of Sale (EPOS) barcode scanners at every checkout. Besides speeding up customer queues, how does EPOS help operations managers?","options":{"A":"It tracks exact product sales in real time and automatically sends stock replenishment orders to warehouses","B":"It bakes fresh bread automatically inside the checkout scanner","C":"It eliminates the need for delivery trucks to bring groceries to stores","D":"It forces customers to pay only with physical cash"},"correctOption":"A","correctAnswer":"It tracks exact product sales in real time and automatically sends stock replenishment orders to warehouses","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because EPOS updates inventory records instantaneously as items are scanned, triggering timely reorders and preventing stockouts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because EPOS is an information and checkout system, not baking equipment.","C":"Incorrect because physical goods still require truck deliveries from warehouses.","D":"Incorrect because EPOS integrates with card and contactless payment terminals."}}},{"id":"P1_U4_MCQ_403","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_403","question":"A busy coffee shop switches to contactless EFTPOS card and smartphone payments at its counter. What operational advantage does EFTPOS provide over cash-only payments?","options":{"A":"Faster customer transactions, reduced cash-counting labour, and lower risk of till theft or counterfeit notes","B":"Zero bank transaction fees and slower customer queues","C":"Elimination of the need for an internet or phone network connection","D":"Higher risk of cash robbery from the till"},"correctOption":"A","correctAnswer":"Faster customer transactions, reduced cash-counting labour, and lower risk of till theft or counterfeit notes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because contactless EFTPOS processes payments in seconds, reduces end-of-day cash reconciliation time, and improves security.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because card processors charge small transaction fees, and contactless payments speed up queues.","C":"Incorrect because EFTPOS terminals require telecommunications connectivity to authorize payments.","D":"Incorrect because holding less physical cash lowers theft risk."}}},{"id":"P1_U4_MCQ_404","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_404","question":"A retail bank introduces a mobile banking app allowing customers to check balances, transfer funds, and deposit cheques by photo 24 hours a day. How does this technology affect the bank's operations?","options":{"A":"Routine transactions are handled automatically at very low unit cost, allowing the bank to operate fewer high-street branches","B":"The bank must hire twice as many branch tellers to process routine balance checks","C":"Customers can only check their bank balance between 9 AM and 3 PM on weekdays","D":"The bank no longer needs cybersecurity protection"},"correctOption":"A","correctAnswer":"Routine transactions are handled automatically at very low unit cost, allowing the bank to operate fewer high-street branches","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because self-service mobile banking shifts routine transactions away from expensive physical branches and staff onto automated digital channels.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because mobile apps reduce routine counter transactions, leading to fewer branch tellers.","C":"Incorrect because mobile banking operates 24/7 rather than restricted branch hours.","D":"Incorrect because digital banking increases the critical importance of cybersecurity."}}},{"id":"P1_U4_MCQ_405","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_405","question":"A casual dining restaurant places QR codes on every table so diners can browse the digital menu, order dishes, and pay on their phones, sending orders straight to kitchen display screens. What is a potential drawback of this system?","options":{"A":"Some diners miss personal hospitality from waiters, and customers without smartphones or battery power struggle to order","B":"Handwritten paper order tickets get lost more frequently in the kitchen","C":"Waiters spend more time walking back and forth carrying paper bills","D":"Printing paper menus every single day becomes more expensive"},"correctOption":"A","correctAnswer":"Some diners miss personal hospitality from waiters, and customers without smartphones or battery power struggle to order","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because replacing table service with QR ordering reduces human warmth and can frustrate customers who lack smartphones or prefer traditional service.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because digital kitchen screens eliminate lost handwritten paper tickets.","C":"Incorrect because phone payments reduce waiters walking back and forth with bills.","D":"Incorrect because digital menus reduce paper menu printing costs."}}},{"id":"P1_U4_MCQ_406","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_406","question":"A global parcel courier attaches Radio Frequency Identification (RFID) tags to every shipping container and uses automated conveyor scanners to route parcels onto delivery trucks. How does RFID improve logistics operations?","options":{"A":"Hundreds of parcels can be scanned and tracked simultaneously without line-of-sight barcode scanning, reducing sorting errors and delays","B":"RFID tags transport parcels physically without needing delivery vans or aircraft","C":"RFID eliminates the need for warehouse buildings","D":"RFID tags prevent parcels from having any weight"},"correctOption":"A","correctAnswer":"Hundreds of parcels can be scanned and tracked simultaneously without line-of-sight barcode scanning, reducing sorting errors and delays","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because RFID chips transmit location data wirelessly as pallets pass readers, dramatically accelerating sorting accuracy and inventory visibility.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because physical vans and aircraft are still needed to move parcels.","C":"Incorrect because sorting hubs and warehouses are still required.","D":"Incorrect because RFID tags track parcels; they do not alter physical weight."}}},{"id":"P1_U4_MCQ_407","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_407","question":"An online retailer installs automated warehouse picking robots that operate 24 hours a day under dim lighting without heating, fulfilling 300% more orders per hour. What is a primary financial benefit of this technology?","options":{"A":"Lower labour, heating, and lighting costs per order dispatched, increasing profit margins on high sales volumes","B":"Zero upfront capital cost for purchasing the warehouse robots","C":"Elimination of all courier delivery charges to customers' homes","D":"Higher hourly overtime wages paid to robots at night"},"correctOption":"A","correctAnswer":"Lower labour, heating, and lighting costs per order dispatched, increasing profit margins on high sales volumes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 24-hour robotic fulfilment dramatically raises output per hour while reducing ongoing wage and utility expenses per order.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because automated warehouse robotics requires heavy upfront capital investment.","C":"Incorrect because last-mile courier delivery costs still apply.","D":"Incorrect because robots do not receive hourly or overtime wages."}}},{"id":"P1_U4_MCQ_408","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_408","question":"A fully automated car-parts factory suffers a ransomware cyberattack that locks its central production computers for four days, halting all robotic assembly lines. Which risk of high-technology production does this highlight?","options":{"A":"Heavy reliance on interconnected IT systems makes operations vulnerable to costly shutdowns from cyberattacks or software failures","B":"Manual hand tools cannot operate without an internet connection","C":"Cyberattacks increase labour productivity on robotic lines","D":"Automated factories have zero fixed overhead costs during shutdowns"},"correctOption":"A","correctAnswer":"Heavy reliance on interconnected IT systems makes operations vulnerable to costly shutdowns from cyberattacks or software failures","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when production depends completely on networked computers, any software bug, power outage, or cyberattack halts the entire operation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because simple hand tools do not rely on computers or the internet.","C":"Incorrect because a four-day shutdown reduces output to zero.","D":"Incorrect because fixed rent, loan interest, and salaried staff costs continue during a shutdown."}}},{"id":"P1_U4_MCQ_409","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_409","question":"A steel foundry installs automated robotic arms to pour molten metal into moulds, removing human workers from extreme heat and sparks while training them to operate air-conditioned control consoles. How does this benefit employees?","options":{"A":"Safer, cleaner working conditions with lower injury risk and upgraded technical skills","B":"Increased exposure to molten metal burns","C":"Elimination of all training and career development","D":"Lower pay due to working in dangerous heat"},"correctOption":"A","correctAnswer":"Safer, cleaner working conditions with lower injury risk and upgraded technical skills","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automating hazardous foundry tasks protects workers from physical injury while upskilling them into higher-value technical roles.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because robots handle the molten metal while workers sit in safe control rooms.","C":"Incorrect because workers received technical training to operate the control consoles.","D":"Incorrect because upskilled technical operators typically earn higher, not lower, pay."}}},{"id":"P1_U4_MCQ_410","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_410","question":"When an insurance company introduces AI claims-processing software that automatically approves simple car-repair claims in seconds, 90 clerical data-entry staff are made redundant. Which negative impact on employees is shown here?","options":{"A":"Technological unemployment for routine administrative workers and increased job insecurity among remaining staff","B":"Increased demand for manual paper-filing clerks","C":"Higher physical injury risk from lifting heavy paper folders","D":"Guaranteed promotion for all 90 data-entry staff"},"correctOption":"A","correctAnswer":"Technological unemployment for routine administrative workers and increased job insecurity among remaining staff","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automation of routine white-collar data tasks often leads to redundancies and anxiety among staff whose skills are replaced.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because digital AI processing reduces rather than increases paper-filing jobs.","C":"Incorrect because automation eliminates physical paper handling.","D":"Incorrect because the 90 staff were made redundant rather than promoted."}}},{"id":"P1_U4_MCQ_411","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_411","question":"An athletic footwear brand launches an online 3D sneaker configurator allowing shoppers to pick custom sole colours, laces, and embroidered initials, with automated factory machines producing the custom pair in five days. How does this technology benefit customers?","options":{"A":"Customers enjoy personalized products tailored to their tastes at affordable prices and fast delivery times","B":"Customers are forced to buy only one plain black sneaker design","C":"Customers must wait six months for hand-stitched shoes","D":"Customers cannot order online outside shop opening hours"},"correctOption":"A","correctAnswer":"Customers enjoy personalized products tailored to their tastes at affordable prices and fast delivery times","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because CAD/CAM mass customization enables businesses to offer individualized designs quickly without bespoke luxury prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the configurator expands customer choice rather than restricting it.","C":"Incorrect because automated production delivers the custom pair in five days.","D":"Incorrect because the online configurator operates 24/7."}}},{"id":"P1_U4_MCQ_412","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_412","question":"An airline replaces its human customer-service phone agents with an automated chatbot that fails to understand complex flight rebooking requests during a snowstorm, leaving stranded passengers frustrated. What customer-service lesson does this illustrate?","options":{"A":"Over-automating complex, high-stress customer interactions without easy access to human staff damages customer satisfaction","B":"Chatbots always resolve unusual travel emergencies better than experienced human agents","C":"Airlines should cancel all flights whenever snow falls","D":"Passengers prefer repeating themselves to an automated bot for two hours"},"correctOption":"A","correctAnswer":"Over-automating complex, high-stress customer interactions without easy access to human staff damages customer satisfaction","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automated bots handle simple queries well, but complex or urgent problems require empathetic human staff to prevent customer anger.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because rigid automated scripts often struggle with complex, non-standard emergencies.","C":"Incorrect because flight cancellations are unrelated to customer service channel design.","D":"Incorrect because struggling with an unhelpful bot frustrates stranded passengers."}}},{"id":"P1_U4_MCQ_413","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_413","question":"A small family bakery producing 300 loaves a day considers buying an industrial robotic dough-forming line costing $450,000, while a national bakery producing 200,000 loaves a day installs the exact same system. Why is the investment viable for the national bakery but not the family bakery?","options":{"A":"The national bakery spreads the $450,000 fixed capital cost across 200,000 loaves daily, whereas 300 loaves cannot generate enough savings to pay back the machine","B":"Small family bakeries are legally forbidden from using electric mixers or ovens","C":"Robotic dough lines produce lower-quality bread when run at high volume","D":"The national bakery gets the $450,000 robotic line completely free"},"correctOption":"A","correctAnswer":"The national bakery spreads the $450,000 fixed capital cost across 200,000 loaves daily, whereas 300 loaves cannot generate enough savings to pay back the machine","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because expensive automation requires high output volumes (technical economies of scale) to spread fixed capital costs and achieve low unit cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because small bakeries can use standard electric equipment; the barrier here is the $450,000 capital cost relative to tiny output.","C":"Incorrect because automated lines maintain consistent quality at high volumes.","D":"Incorrect because the national bakery still pays the $450,000 capital cost."}}},{"id":"P1_U4_MCQ_414","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_414","question":"Warehouse A uses electric pallet trucks steered and operated by human drivers, whereas Warehouse B uses computer-guided Autonomous Mobile Robots (AMRs) that navigate aisles and transport pallets without drivers. Which statement accurately describes Warehouse A and Warehouse B?","options":{"A":"Warehouse A uses mechanisation, whereas Warehouse B uses automation","B":"Warehouse A uses automation, whereas Warehouse B uses mechanisation","C":"Both warehouses rely purely on manual hand-carrying","D":"Warehouse B uses job production"},"correctOption":"A","correctAnswer":"Warehouse A uses mechanisation, whereas Warehouse B uses automation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mechanisation uses powered machines controlled directly by human operators, whereas automation uses computer-controlled systems operating independently.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the definitions of mechanisation and automation are reversed.","C":"Incorrect because both warehouses use powered equipment rather than hand-carrying.","D":"Incorrect because warehouse pallet transport is logistics handling, not bespoke job production."}}},{"id":"P1_U4_MCQ_415","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_415","question":"A glass-bottle factory installs high-speed optical cameras linked to AI image-recognition software that inspects 600 bottles per minute and automatically ejects any bottle with a microscopic crack. How does this improve operations?","options":{"A":"It detects tiny defects faster and more reliably than human eyes at high line speeds, preventing faulty bottles reaching beverage companies","B":"It eliminates the need to melt silica sand in furnaces","C":"It slows the production line down to 5 bottles per hour","D":"It increases the number of cracked bottles delivered to customers"},"correctOption":"A","correctAnswer":"It detects tiny defects faster and more reliably than human eyes at high line speeds, preventing faulty bottles reaching beverage companies","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because AI visual inspection operates tirelessly at high speeds, catching microscopic flaws human inspectors might miss due to fatigue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because glass bottles still must be formed from molten glass.","C":"Incorrect because optical AI cameras inspect 600 bottles per minute without slowing the line.","D":"Incorrect because defective bottles are automatically ejected before packing."}}},{"id":"P1_U4_MCQ_416","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_416","question":"A chain of 40 optical clinics uses cloud-based operations software so an optometrist in any branch can view a patient's prescription history and order lenses directly from the central lab. How does cloud technology improve service delivery?","options":{"A":"Seamless data sharing across all branches speeds up lens ordering, reduces errors, and lets customers visit any clinic conveniently","B":"Each clinic must post paper patient files by mail between branches","C":"Cloud software physically grinds glass lenses inside the patient's home","D":"Clinics no longer need qualified optometrists to test eyesight"},"correctOption":"A","correctAnswer":"Seamless data sharing across all branches speeds up lens ordering, reduces errors, and lets customers visit any clinic conveniently","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because centralized cloud software connects multi-site operations in real time, improving coordination, accuracy, and customer convenience.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cloud software replaces slow paper mailing with instant digital access.","C":"Incorrect because lenses are still manufactured at the central optical lab.","D":"Incorrect because qualified optometrists still perform eye examinations."}}},{"id":"P1_U4_MCQ_417","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_417","question":"A plastics manufacturer plans to borrow $2 million to buy automated injection-moulding machines that will save $220,000 per year in labour costs, but central bank interest rates have just risen from 3% to 12%. How should this interest rate rise affect the investment decision?","options":{"A":"Managers should delay or reconsider the purchase because annual interest payments ($240,000 at 12%) now exceed the $220,000 annual labour savings","B":"Managers should borrow immediately because higher interest rates make machinery cheaper","C":"Interest rates only affect variable raw material costs, never loan repayments","D":"Higher interest rates double the speed of injection-moulding machines"},"correctOption":"A","correctAnswer":"Managers should delay or reconsider the purchase because annual interest payments ($240,000 at 12%) now exceed the $220,000 annual labour savings","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because at 12% interest, annual financing charges ($240,000) outweigh the $220,000 labour savings, making the debt-financed technology unprofitable right now.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher interest rates increase the cost of borrowing to buy machinery.","C":"Incorrect because interest rates directly determine fixed loan interest expenses.","D":"Incorrect because interest rates are a financial cost and do not change machine speed."}}},{"id":"P1_U4_MCQ_418","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_418","question":"Which definition best describes sustainable production of goods and services?","options":{"A":"Producing goods and services in ways that meet current needs while minimizing environmental harm and conserving resources for future generations","B":"Maximizing short-term factory output regardless of pollution or resource depletion","C":"Using exclusively non-renewable coal and crude oil to keep energy costs low","D":"Designing products to break immediately after warranty expiry so customers buy replacements"},"correctOption":"A","correctAnswer":"Producing goods and services in ways that meet current needs while minimizing environmental harm and conserving resources for future generations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustainable production balances economic output with environmental protection and resource conservation over the long term.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ignoring pollution and resource depletion is unsustainable.","C":"Incorrect because relying on finite fossil fuels increases carbon emissions and resource exhaustion.","D":"Incorrect because planned obsolescence creates excessive waste and is unsustainable."}}},{"id":"P1_U4_MCQ_419","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_419","question":"A frozen-food warehouse covers its vast flat roof with solar photovoltaic panels that supply 85% of the electricity required by its industrial freezers. Which sustainable production method is this?","options":{"A":"Using renewable energy","B":"Recycling plastic packaging","C":"Switching to batch production","D":"Increasing fossil-fuel consumption"},"correctOption":"A","correctAnswer":"Using renewable energy","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because solar energy harnesses inexhaustible sunlight to generate clean electricity without burning finite fossil fuels.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because solar panels generate electricity rather than reprocessing plastic waste.","C":"Incorrect because warehouse solar generation is an energy choice, not a manufacturing batch method.","D":"Incorrect because solar electricity reduces rather than increases fossil-fuel usage."}}},{"id":"P1_U4_MCQ_420","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_420","question":"A Nordic aluminium smelter locates beside a large hydroelectric dam so all electricity used in electrolysis comes from river water turbines rather than coal-fired power stations. Why is this more sustainable?","options":{"A":"Hydropower is a renewable energy source that generates electricity without greenhouse gas emissions from burning coal","B":"Hydroelectric dams burn natural gas more efficiently than coal plants","C":"River water turbines require zero initial construction cost","D":"Aluminium smelters use zero electricity when located near rivers"},"correctOption":"A","correctAnswer":"Hydropower is a renewable energy source that generates electricity without greenhouse gas emissions from burning coal","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because hydroelectricity uses the natural water cycle repeatedly without carbon emissions, making energy-intensive smelting far cleaner.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because hydroelectric turbines are driven by flowing water, not burning natural gas.","C":"Incorrect because building hydroelectric dams involves large upfront capital expenditure.","D":"Incorrect because aluminium smelting consumes huge amounts of electricity, which is why clean hydropower is chosen."}}},{"id":"P1_U4_MCQ_421","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_421","question":"A beverage company redesigns its glass juice bottles so each bottle weighs 410 grams instead of 500 grams while maintaining the same strength, saving 18% of silica sand and furnace fuel per bottle. Which sustainable practice does this demonstrate?","options":{"A":"Using fewer natural resources per unit produced","B":"Reusing intact bottles without washing","C":"Switching from flow production to job production","D":"Increasing landfill waste"},"correctOption":"A","correctAnswer":"Using fewer natural resources per unit produced","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 'lightweighting' products reduces the raw materials and energy extracted from nature for each unit manufactured.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the change involves manufacturing lighter new bottles rather than refilling old ones.","C":"Incorrect because glass bottles are still mass-produced via flow production.","D":"Incorrect because lighter bottles reduce material consumption and waste."}}},{"id":"P1_U4_MCQ_422","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_422","question":"A commercial car-wash operator installs a closed-loop filtration and purification system that cleans and recirculates 90% of wash water instead of draining it into sewers. What are two benefits of this sustainable investment?","options":{"A":"Conserves scarce freshwater resources and lowers monthly mains water and wastewater utility bills","B":"Increases mains water consumption by 90% and raises water bills","C":"Eliminates the need for electricity to run filtration pumps","D":"Prevents customers from washing their cars during summer"},"correctOption":"A","correctAnswer":"Conserves scarce freshwater resources and lowers monthly mains water and wastewater utility bills","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because closed-loop water recycling dramatically cuts freshwater extraction and reduces ongoing water utility costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because recirculating 90% of water cuts freshwater use rather than increasing it.","C":"Incorrect because filtration pumps still consume electricity.","D":"Incorrect because water recycling helps the car wash keep operating even during summer water restrictions."}}},{"id":"P1_U4_MCQ_423","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_423","question":"A clothing manufacturer uses computerised pattern-nesting software to arrange shirt pieces tightly on fabric rolls, cutting fabric off-cut waste from 22% down to 6%. How does this support sustainable production?","options":{"A":"It creates less textile waste while reducing the amount of cotton fabric needed for the same number of shirts","B":"It increases the quantity of fabric scraps sent to incinerators","C":"It forces workers to cut fabric slowly with blunt scissors","D":"It replaces cotton fabric with non-recyclable PVC plastic"},"correctOption":"A","correctAnswer":"It creates less textile waste while reducing the amount of cotton fabric needed for the same number of shirts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because minimizing cutting off-cuts reduces solid landfill waste and conserves agricultural water and land used to grow cotton.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because off-cut waste dropped from 22% to 6%.","C":"Incorrect because CAD pattern nesting guides automated fabric cutters.","D":"Incorrect because the firm still uses cotton fabric, just far more efficiently."}}},{"id":"P1_U4_MCQ_424","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_424","question":"A local dairy farm delivers milk in thick glass bottles to households, collects the empty bottles from doorsteps, sterilizes them, and refills them up to 30 times each. Which sustainable method is this?","options":{"A":"Reusing containers repeatedly for the same purpose","B":"Recycling glass by crushing and melting it after every delivery","C":"Using single-use plastic milk pouches","D":"Increasing carbon emissions through air-freighting milk"},"correctOption":"A","correctAnswer":"Reusing containers repeatedly for the same purpose","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because washing and refilling intact glass bottles uses the product again without energy-intensive melting or remanufacturing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because crushing and melting glass is recycling, whereas washing intact bottles is reusing.","C":"Incorrect because reusable glass bottles replace single-use plastic.","D":"Incorrect because local doorstep delivery avoids air freight."}}},{"id":"P1_U4_MCQ_425","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_425","question":"An automotive parts supplier ships engine components to an assembly plant in heavy-duty collapsible plastic crates that are returned empty on the return truck trip and reused for five years. Why is this preferable to single-use cardboard cartons?","options":{"A":"It eliminates thousands of discarded cardboard boxes, saves tree pulp, and lowers long-term packaging costs","B":"Collapsible plastic crates are thrown in landfill after a single delivery","C":"Cardboard cartons last longer than heavy-duty plastic crates","D":"Returnable crates require separate empty lorries to drive 1,000 km daily"},"correctOption":"A","correctAnswer":"It eliminates thousands of discarded cardboard boxes, saves tree pulp, and lowers long-term packaging costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because returnable transit packaging reuses durable crates hundreds of times, preventing recurring packaging waste and lowering unit packaging costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the crates are reused for five years rather than discarded.","C":"Incorrect because single-use cardboard wears out quickly compared with durable plastic crates.","D":"Incorrect because collapsed crates return on trucks already making the return journey."}}},{"id":"P1_U4_MCQ_426","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_426","question":"An outdoor fleece jacket brand collects discarded plastic PET water bottles, shreds and melts them into polyester fibres, and weaves them into warm fleece fabric. Which sustainable production method is this?","options":{"A":"Recycling waste plastic into a new product","B":"Reusing intact water bottles as jacket buttons","C":"Using coal-fired steam looms","D":"Just-in-time inventory ordering"},"correctOption":"A","correctAnswer":"Recycling waste plastic into a new product","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because recycling reprocesses waste materials (plastic bottles) into raw fibres to manufacture a different product (fleece jackets).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the bottles are shredded and melted into polyester yarn rather than kept intact.","C":"Incorrect because the scenario describes material recycling rather than coal energy.","D":"Incorrect because JIT relates to inventory timing rather than material reprocessing."}}},{"id":"P1_U4_MCQ_427","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_427","question":"A drinks-can manufacturer produces new cans from recycled scrap aluminium rather than mining virgin bauxite ore, cutting electricity consumption by 95%. How does this benefit both the business and the environment?","options":{"A":"Lower energy and raw material costs improve profitability while reducing mining destruction and carbon emissions","B":"Recycled aluminium uses 95% more electricity than mining virgin ore","C":"Aluminium cans cannot be recycled more than once","D":"Recycling scrap aluminium increases landfill volume"},"correctOption":"A","correctAnswer":"Lower energy and raw material costs improve profitability while reducing mining destruction and carbon emissions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because recycling aluminium requires only 5% of the energy needed to smelt virgin ore, saving substantial utility costs and avoiding bauxite mining.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because recycling cuts electricity use by 95% rather than increasing it.","C":"Incorrect because aluminium is infinitely recyclable without losing quality.","D":"Incorrect because recycling diverts cans away from landfills."}}},{"id":"P1_U4_MCQ_428","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_428","question":"A household cleaning company develops concentrated laundry detergent strips that dissolve completely in washing machines without plastic jugs and are made from plant-derived biodegradable ingredients. Which sustainable practice does this show?","options":{"A":"Developing environmentally friendly products that eliminate plastic containers and water pollution","B":"Increasing water weight shipped in heavy plastic bottles","C":"Using toxic phosphate chemicals that harm river fish","D":"Switching to bespoke job production for every laundry strip"},"correctOption":"A","correctAnswer":"Developing environmentally friendly products that eliminate plastic containers and water pollution","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because designing concentrated, biodegradable products eliminates single-use plastic bottles, lowers transport emissions, and avoids waterway pollution.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because dry strips remove heavy water weight and plastic jugs.","C":"Incorrect because plant-derived biodegradable ingredients protect aquatic life.","D":"Incorrect because laundry strips are mass-produced rather than handmade individually."}}},{"id":"P1_U4_MCQ_429","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_429","question":"An electronics manufacturer replaces expanded polystyrene foam blocks inside television boxes with protective cushioning moulded from agricultural hemp husks and mushroom roots that can be composted in home gardens. Which sustainable method is this?","options":{"A":"Using environmentally friendly, compostable packaging","B":"Installing wind turbines on retail stores","C":"Increasing non-biodegradable plastic foam waste","D":"Eliminating all protective packaging so TVs break in transit"},"correctOption":"A","correctAnswer":"Using environmentally friendly, compostable packaging","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because replacing petroleum-based polystyrene foam with home-compostable mycelium packaging protects goods while eliminating persistent plastic waste.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the scenario focuses on packaging materials rather than wind turbines.","C":"Incorrect because polystyrene foam was replaced rather than increased.","D":"Incorrect because the moulded hemp/mushroom cushioning protects the TVs effectively."}}},{"id":"P1_U4_MCQ_430","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_430","question":"A specialty coffee roaster switches to 100% shade-grown, bird-friendly coffee beans packaged in compostable pouches, allowing it to charge $16 per bag instead of $11 and grow sales by 30%. What commercial benefit of sustainability is demonstrated here?","options":{"A":"Differentiating the brand to attract eco-conscious customers willing to pay a higher price","B":"Paying zero money to coffee farmers for beans","C":"Eliminating all roasting energy costs","D":"Legal monopoly preventing any other coffee roaster from operating"},"correctOption":"A","correctAnswer":"Differentiating the brand to attract eco-conscious customers willing to pay a higher price","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because strong environmental credentials create a unique selling point that builds customer loyalty and supports premium pricing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because certified sustainable beans actually cost more to purchase from farmers.","C":"Incorrect because coffee beans still require roasting energy.","D":"Incorrect because sustainability differentiates the brand rather than creating a legal monopoly."}}},{"id":"P1_U4_MCQ_431","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_431","question":"A hotel chain installs smart occupancy sensors that turn off air-conditioning and lights automatically when guests leave their rooms, reducing annual electricity bills by $420,000. How does this sustainability measure affect the business?","options":{"A":"Reducing wasted energy directly lowers operating costs and increases profitability while cutting carbon emissions","B":"Guests are forced to sit in dark, hot rooms while inside their bedrooms","C":"Electricity bills increase by $420,000 per year","D":"The hotel no longer needs housekeeping staff"},"correctOption":"A","correctAnswer":"Reducing wasted energy directly lowers operating costs and increases profitability while cutting carbon emissions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because energy-efficiency technologies eliminate unnecessary power usage in empty rooms, saving substantial money and lowering carbon footprint.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because occupancy sensors only turn power off after guests leave the room.","C":"Incorrect because electricity bills fell by $420,000 rather than rising.","D":"Incorrect because housekeeping staff are still needed to clean rooms."}}},{"id":"P1_U4_MCQ_432","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_432","question":"A renewable-energy engineering firm publishes independently audited sustainability reports showing zero landfill waste and 100% clean power, helping it attract top university engineering graduates and ethical investment funds. What benefit of sustainability does this show?","options":{"A":"Stronger recruitment and retention of motivated employees and easier access to ethical capital","B":"Lower salaries paid to engineers because graduates work for free","C":"Exemption from paying employee income taxes","D":"Guaranteed zero competition in the engineering industry"},"correctOption":"A","correctAnswer":"Stronger recruitment and retention of motivated employees and easier access to ethical capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because many skilled workers and institutional investors prefer companies with genuine environmental commitment, easing hiring and fundraising.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because skilled engineers still receive competitive salaries.","C":"Incorrect because businesses and workers still pay standard taxes.","D":"Incorrect because competitors still operate in the sector."}}},{"id":"P1_U4_MCQ_433","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_433","question":"A country introduces a heavy landfill tax per tonne of commercial waste and a carbon tax on fossil-fuel emissions. How does adopting sustainable production protect a manufacturer from these taxes?","options":{"A":"Minimizing waste and switching to renewable energy directly lowers tax liabilities and avoids regulatory penalties","B":"Sustainable factories are allowed to dump unlimited toxic waste in forests","C":"Carbon taxes reward factories that burn the most coal","D":"Landfill taxes apply only to companies that recycle 100% of their waste"},"correctOption":"A","correctAnswer":"Minimizing waste and switching to renewable energy directly lowers tax liabilities and avoids regulatory penalties","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because environmental taxes penalize pollution and landfill dumping; firms that cut waste and emissions avoid those extra costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because illegal dumping incurs severe fines and prosecution.","C":"Incorrect because carbon taxes penalize rather than reward coal burning.","D":"Incorrect because firms that recycle all waste send zero tonnes to landfill and pay zero landfill tax."}}},{"id":"P1_U4_MCQ_434","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_434","question":"A budget supermarket chain considers replacing all low-cost plastic-wrapped vegetables with organic produce in compostable trays, which would raise shelf prices by 35% for low-income shoppers. What commercial risk does this create?","options":{"A":"Price-sensitive shoppers may switch to cheaper rival supermarkets if higher sustainable production costs are passed on in retail prices","B":"Low-income shoppers always prefer paying 35% more for groceries","C":"Compostable trays cost less than zero to manufacture","D":"Organic vegetables never spoil even without refrigeration"},"correctOption":"A","correctAnswer":"Price-sensitive shoppers may switch to cheaper rival supermarkets if higher sustainable production costs are passed on in retail prices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because higher sustainable input costs can reduce price competitiveness, causing cost-conscious customers to defect to cheaper competitors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because price-sensitive shoppers are strongly affected by a 35% price hike.","C":"Incorrect because compostable trays cost more than conventional plastic wrap, raising prices.","D":"Incorrect because organic produce still perishes naturally."}}},{"id":"P1_U4_MCQ_435","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_435","question":"A cement producer wants to install carbon-capture technology on its kilns to eliminate CO2 emissions, but the system costs $80 million to build and increases electricity consumption by 25%. Which limitation of sustainable production does this illustrate?","options":{"A":"Extreme upfront capital expenditure and higher ongoing energy costs can make green technologies financially unviable without government support","B":"Carbon-capture equipment reduces electricity usage to zero","C":"Cement factories emit zero carbon dioxide without carbon capture","D":"Customers pay ten times more for cement made with carbon capture"},"correctOption":"A","correctAnswer":"Extreme upfront capital expenditure and higher ongoing energy costs can make green technologies financially unviable without government support","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because heavy industrial decarbonization often requires massive capital outlay and higher operating costs that are hard to recover in competitive commodity markets.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the scenario states electricity consumption increases by 25%.","C":"Incorrect because conventional cement production is a major source of CO2 emissions.","D":"Incorrect because construction buyers rarely pay ten times the market price for standard cement."}}},{"id":"P1_U4_MCQ_436","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_436","question":"A furniture maker commits to using only certified sustainably harvested oak timber, but faces repeated production delays because certified sawmills have limited supply during winter months. What operational challenge does this show?","options":{"A":"Restricted availability of certified sustainable raw materials can disrupt production schedules and limit output growth","B":"Certified sustainable timber grows overnight inside furniture workshops","C":"Sustainable sawmills always have unlimited cheap timber","D":"Customers prefer waiting six months late for furniture deliveries"},"correctOption":"A","correctAnswer":"Restricted availability of certified sustainable raw materials can disrupt production schedules and limit output growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical and sustainable raw materials often have tighter supply chains than conventional commodities, creating potential bottlenecks.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because oak trees take decades to grow sustainably.","C":"Incorrect because sustainable harvesting limits annual logging volumes.","D":"Incorrect because delivery delays frustrate customers."}}},{"id":"P1_U4_MCQ_437","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_437","question":"A fast-fashion retailer prints 'Eco-Conscious Collection' on its clothing tags even though 98% of the garments are made from virgin fossil-fuel polyester in coal-powered factories, sparking consumer outrage and regulatory fines. What is this misleading practice called, and why is it risky?","options":{"A":"Greenwashing; it destroys consumer trust, triggers negative publicity, and can result in legal fines for deceptive marketing","B":"Kaizen; it reduces factory waste continuously","C":"Quality assurance; it prevents defects at every stage","D":"Purchasing economies of scale; it lowers bulk fabric prices"},"correctOption":"A","correctAnswer":"Greenwashing; it destroys consumer trust, triggers negative publicity, and can result in legal fines for deceptive marketing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because greenwashing exaggerates or fabricates environmental credentials, backfiring severely when exposed by consumers, media, or regulators.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Kaizen is genuine continuous operational improvement.","C":"Incorrect because quality assurance prevents product faults.","D":"Incorrect because purchasing economies refer to bulk-buying discounts."}}},{"id":"P1_U4_MCQ_438","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_438","question":"When evaluating whether a manufacturer should invest in sustainable production methods, why is the time horizon of the business important?","options":{"A":"Sustainable investments often raise short-term costs but generate long-term cost savings, brand loyalty, and regulatory compliance","B":"Sustainable investments always lose money forever and never save energy or waste","C":"Short-term profits are completely unaffected by buying expensive solar panels","D":"Environmental laws are being abolished in every country"},"correctOption":"A","correctAnswer":"Sustainable investments often raise short-term costs but generate long-term cost savings, brand loyalty, and regulatory compliance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustainability involves a short-term versus long-term trade-off: upfront spending weighs on short-term cash flow before paying off over future years.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because energy efficiency, waste reduction, and brand strength typically yield strong long-run financial returns.","C":"Incorrect because upfront capital spending reduces short-term cash flow and increases depreciation.","D":"Incorrect because environmental regulations worldwide are tightening rather than disappearing."}}},{"id":"P1_U4_MCQ_439","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_439","question":"A bakery pays annual property tax on its building, monthly interest on a bank loan, flour and yeast for each loaf baked, and annual fire insurance. Which of these is a variable cost?","options":{"A":"Flour and yeast for each loaf baked","B":"Annual property tax on its building","C":"Monthly interest on a bank loan","D":"Annual fire insurance"},"correctOption":"A","correctAnswer":"Flour and yeast for each loaf baked","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ingredient usage (flour and yeast) rises and falls directly in proportion to the number of loaves baked.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because property tax is a fixed overhead regardless of output.","C":"Incorrect because loan interest is a fixed financial cost independent of loaves baked.","D":"Incorrect because annual fire insurance does not vary directly with daily bread production."}}},{"id":"P1_U4_MCQ_440","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_440","question":"A specialty coffee roaster incurs monthly fixed costs of $6,400 and variable costs of $4.50 per kilogram of coffee roasted. What is the total cost of roasting 1,800 kilograms of coffee in a month?","options":{"A":"$8,100","B":"$14,500","C":"$6,400","D":"$8,200"},"correctOption":"B","correctAnswer":"$14,500","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because total variable cost is 1,800 x $4.50 = $8,100, and adding fixed costs of $6,400 gives a total cost of $14,500.","distractor_reasons":{"A":"Incorrect because $8,100 is only total variable cost, omitting the $6,400 fixed costs.","B":"Correct selection.","C":"Incorrect because $6,400 is only fixed costs, omitting variable roasting costs.","D":"Incorrect because this adds 1,800 kg directly to $6,400 without multiplying by $4.50."}}},{"id":"P1_U4_MCQ_441","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_441","question":"A scented-candle workshop manufactures 5,000 candles per month with monthly fixed costs of $12,500 and total variable costs of $17,500. What is the average cost per candle?","options":{"A":"$3.50","B":"$2.50","C":"$6.00","D":"$30,000"},"correctOption":"C","correctAnswer":"$6.00","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total cost is $12,500 + $17,500 = $30,000, and dividing $30,000 by 5,000 candles equals $6.00 per candle.","distractor_reasons":{"A":"Incorrect because $3.50 is only average variable cost ($17,500 / 5,000), ignoring fixed costs.","B":"Incorrect because $2.50 is only average fixed cost ($12,500 / 5,000), ignoring variable costs.","C":"Correct selection.","D":"Incorrect because $30,000 is total monthly cost rather than cost per candle."}}},{"id":"P1_U4_MCQ_442","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_442","question":"A notebook printer has monthly fixed costs of $10,000 and variable costs of $3.00 per notebook. When monthly output rises from 2,000 notebooks to 5,000 notebooks within existing capacity, what happens to average total cost per notebook?","options":{"A":"It falls from $8.00 to $5.00 per notebook because fixed costs are spread across more units","B":"It rises from $5.00 to $8.00 per notebook","C":"It stays constant at $8.00 per notebook","D":"It falls to $3.00 per notebook because fixed costs become zero"},"correctOption":"A","correctAnswer":"It falls from $8.00 to $5.00 per notebook because fixed costs are spread across more units","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because at 2,000 notebooks average cost is ($10,000 / 2,000) + $3.00 = $8.00, while at 5,000 notebooks it falls to ($10,000 / 5,000) + $3.00 = $5.00.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher output lowers average cost per unit rather than raising it.","C":"Incorrect because average fixed cost decreases from $5.00 to $2.00 per notebook.","D":"Incorrect because fixed costs remain $10,000 ($2.00 per notebook at 5,000 units)."}}},{"id":"P1_U4_MCQ_443","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_443","question":"A luggage factory normally sells suitcases for $40 each, has variable costs of $22 per suitcase, and already covers all $30,000 of monthly fixed costs from regular sales. A travel agency offers to buy 500 extra suitcases at $28 each using the factory's spare capacity. Should the factory accept this special order?","options":{"A":"Yes, because the $28 price exceeds the $22 variable cost, generating $6 contribution per suitcase ($3,000 extra profit)","B":"No, because $28 is lower than the normal $40 selling price","C":"No, because total revenue of $14,000 is less than $30,000 fixed costs","D":"Yes, because it generates $14,000 in pure net profit"},"correctOption":"A","correctAnswer":"Yes, because the $28 price exceeds the $22 variable cost, generating $6 contribution per suitcase ($3,000 extra profit)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fixed costs are already covered and spare capacity exists, so any price above variable cost ($28 > $22) generates positive contribution ($6 x 500 = $3,000) directly to profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because accepting a discounted order on spare capacity is profitable as long as price exceeds variable cost and does not cannibalize regular sales.","C":"Incorrect because fixed costs of $30,000 are already paid for by existing regular orders.","D":"Incorrect because variable costs of 500 x $22 = $11,000 must be subtracted from $14,000 revenue, leaving $3,000 profit."}}},{"id":"P1_U4_MCQ_444","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_444","question":"A global fast-food chain purchases 50,000 tonnes of potatoes and cooking oil each year, negotiating a 30% bulk discount from agricultural suppliers that small independent diners cannot obtain. Which economy of scale is this?","options":{"A":"Purchasing economies of scale","B":"Technical economies of scale","C":"Managerial economies of scale","D":"Financial economies of scale"},"correctOption":"A","correctAnswer":"Purchasing economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because purchasing economies occur when large firms buy materials in high volumes and receive bulk discounts that reduce average unit costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because technical economies involve large-scale specialist machinery.","C":"Incorrect because managerial economies involve employing specialist departmental managers.","D":"Incorrect because financial economies involve borrowing money at lower interest rates."}}},{"id":"P1_U4_MCQ_445","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_445","question":"As a regional supermarket group grows to 80 stores, it replaces generalist store owners with dedicated specialist directors for supply-chain logistics, IT systems, and human resources, improving efficiency across all branches. Which economy of scale is this?","options":{"A":"Managerial economies of scale","B":"Purchasing economies of scale","C":"Financial economies of scale","D":"Marketing economies of scale"},"correctOption":"A","correctAnswer":"Managerial economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managerial economies arise when large businesses can afford specialist managers in each function, improving decision quality and lowering unit costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because purchasing economies involve bulk discounts on goods bought from suppliers.","C":"Incorrect because financial economies involve cheaper loans and easier capital raising.","D":"Incorrect because marketing economies involve lower unit advertising and distribution costs."}}},{"id":"P1_U4_MCQ_446","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_446","question":"A large chemical producer builds a giant distillation tower that holds eight times more liquid than a small tower while costing only three times as much steel to construct, dramatically lowering processing cost per litre. Which economy of scale does this illustrate?","options":{"A":"Technical economies of scale","B":"Financial economies of scale","C":"Marketing economies of scale","D":"Purchasing economies of scale"},"correctOption":"A","correctAnswer":"Technical economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because technical economies include engineering advantages where large-scale industrial equipment delivers disproportionately higher capacity relative to construction cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because financial economies relate to lower borrowing interest rates.","C":"Incorrect because marketing economies relate to advertising and transport cost per unit.","D":"Incorrect because purchasing economies relate to bulk discounts on raw inputs."}}},{"id":"P1_U4_MCQ_447","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_447","question":"A national telecom provider spends $2 million on a nationwide television advertising campaign across its 5 million subscribers ($0.40 per customer), whereas a small local broadband provider selling to 20,000 households would pay $100 per customer for the same TV slot. Which economy of scale is this?","options":{"A":"Marketing economies of scale","B":"Purchasing economies of scale","C":"Technical economies of scale","D":"Diseconomies of scale"},"correctOption":"A","correctAnswer":"Marketing economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because marketing economies allow large firms to spread fixed promotional and advertising budgets over a much larger sales volume, reducing marketing cost per unit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because purchasing economies involve bulk discounts on supplies.","C":"Incorrect because technical economies involve specialized production equipment.","D":"Incorrect because diseconomies of scale increase average unit costs rather than lowering them."}}},{"id":"P1_U4_MCQ_448","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_448","question":"A large public limited manufacturing company issues $100 million in corporate bonds at 3.8% annual interest to fund factory expansion, whereas a small sole trader can only obtain a bank loan at 10.5% interest. Which economy of scale is benefiting the PLC?","options":{"A":"Financial economies of scale","B":"Managerial economies of scale","C":"Technical economies of scale","D":"Purchasing economies of scale"},"correctOption":"A","correctAnswer":"Financial economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because financial economies enable large, established firms to borrow at lower interest rates and access capital markets unavailable to small firms.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because managerial economies involve hiring specialist functional managers.","C":"Incorrect because technical economies involve large-scale machinery.","D":"Incorrect because purchasing economies involve bulk-buying discounts."}}},{"id":"P1_U4_MCQ_449","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_449","question":"In a massive assembly complex employing 18,000 workers, shop-floor staff feel like anonymous numbers, never meet senior managers, and experience high absenteeism and high staff turnover, pushing average unit costs upward. Which diseconomy of scale is occurring?","options":{"A":"Worker alienation and low morale resulting in falling productivity and higher recruitment costs","B":"Managerial economies of scale","C":"Purchasing economies of scale","D":"Financial economies of scale"},"correctOption":"A","correctAnswer":"Worker alienation and low morale resulting in falling productivity and higher recruitment costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because oversized workplaces often cause employees to feel disconnected and demotivated, reducing productivity and raising unit labour costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because managerial economies reduce average costs rather than raising them.","C":"Incorrect because purchasing economies lower input costs.","D":"Incorrect because financial economies lower borrowing costs."}}},{"id":"P1_U4_MCQ_450","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_450","question":"After merging with three competitors, an insurance corporation requires six layers of committee approval before changing a single policy price, causing it to lose customers to agile rivals and suffer rising unit costs. Which problem does this illustrate?","options":{"A":"Diseconomies of scale caused by slow decision-making and bureaucratic red tape","B":"Technical economies of scale","C":"Purchasing economies of scale","D":"Marketing economies of scale"},"correctOption":"A","correctAnswer":"Diseconomies of scale caused by slow decision-making and bureaucratic red tape","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because excessive organizational size creates bureaucratic delays and sluggish responses to market changes, increasing average unit costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because technical economies lower costs through specialized equipment.","C":"Incorrect because purchasing economies lower costs through bulk buying.","D":"Incorrect because marketing economies lower unit promotional costs."}}},{"id":"P1_U4_MCQ_451","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_451","question":"A solar garden-lamp manufacturer sells each lamp for $34, incurs variable costs of $19 per lamp, and pays monthly fixed costs of $45,000. What is the contribution per lamp?","options":{"A":"$15","B":"$53","C":"$19","D":"$3,000"},"correctOption":"A","correctAnswer":"$15","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because contribution per unit equals selling price ($34) minus variable cost per unit ($19), which is $15.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $53 adds variable cost ($19) to selling price ($34) instead of subtracting it.","C":"Incorrect because $19 is the variable cost per unit rather than contribution.","D":"Incorrect because 3,000 lamps is the break-even output ($45,000 / $15), not contribution per unit."}}},{"id":"P1_U4_MCQ_452","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_452","question":"A wireless mouse manufacturer sells each mouse for $28, incurs variable costs of $16 per mouse, and sells 3,500 mice in a month. What is the total contribution earned that month?","options":{"A":"$98,000","B":"$56,000","C":"$42,000","D":"$12"},"correctOption":"C","correctAnswer":"$42,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because contribution per unit is $28 - $16 = $12, and multiplying by 3,500 mice gives a total contribution of $42,000.","distractor_reasons":{"A":"Incorrect because $98,000 is total sales revenue (3,500 x $28) before subtracting variable costs.","B":"Incorrect because $56,000 is total variable cost (3,500 x $16).","C":"Correct selection.","D":"Incorrect because $12 is the contribution per single mouse rather than total contribution."}}},{"id":"P1_U4_MCQ_453","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_453","question":"A stainless-steel water bottle maker has monthly fixed costs of $48,000, sells each bottle for $25, and incurs variable costs of $13 per bottle. What is the monthly break-even output?","options":{"A":"1,920 bottles","B":"3,692 bottles","C":"4,000 bottles","D":"1,263 bottles"},"correctOption":"C","correctAnswer":"4,000 bottles","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because contribution per bottle is $25 - $13 = $12, and dividing fixed costs ($48,000) by unit contribution ($12) equals 4,000 bottles.","distractor_reasons":{"A":"Incorrect because this divides $48,000 by the $25 selling price without deducting variable costs.","B":"Incorrect because this divides $48,000 by the $13 variable cost instead of unit contribution ($12).","C":"Correct selection.","D":"Incorrect because this adds selling price and variable cost ($38) before dividing into $48,000."}}},{"id":"P1_U4_MCQ_454","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_454","question":"A skateboard manufacturer has a monthly break-even output of 3,200 skateboards and currently sells 4,150 skateboards per month. What is the manufacturer's margin of safety?","options":{"A":"7,350 skateboards","B":"950 skateboards","C":"3,200 skateboards","D":"4,150 skateboards"},"correctOption":"B","correctAnswer":"950 skateboards","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because margin of safety equals actual sales (4,150) minus break-even output (3,200), showing sales can drop by 950 skateboards before a loss occurs.","distractor_reasons":{"A":"Incorrect because this adds actual sales and break-even output instead of subtracting.","B":"Correct selection.","C":"Incorrect because 3,200 is the break-even output rather than the margin of safety.","D":"Incorrect because 4,150 is actual sales rather than the safety buffer above break-even."}}},{"id":"P1_U4_MCQ_455","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_455","question":"A yoga-mat producer has monthly fixed costs of $26,000 and earns a contribution of $14 per mat sold. If the business sells 2,500 mats in a month, what is its monthly profit?","options":{"A":"$35,000","B":"$9,000","C":"$61,000","D":"$26,000"},"correctOption":"B","correctAnswer":"$9,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because total contribution is 2,500 x $14 = $35,000, and subtracting fixed costs of $26,000 gives a profit of $9,000.","distractor_reasons":{"A":"Incorrect because $35,000 is total contribution before deducting fixed costs.","B":"Correct selection.","C":"Incorrect because this adds fixed costs ($26,000) to total contribution ($35,000) instead of subtracting them.","D":"Incorrect because $26,000 is monthly fixed costs rather than profit."}}},{"id":"P1_U4_MCQ_456","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_456","question":"A furniture workshop earns a contribution of $15 per chair sold and has monthly fixed costs of $30,000 (break-even output = 2,000 chairs). If the landlord increases monthly factory rent by $6,000, how does the break-even output change?","options":{"A":"It rises by 400 chairs to 2,400 chairs per month","B":"It falls by 400 chairs to 1,600 chairs per month","C":"It stays unchanged at 2,000 chairs per month","D":"It rises to 6,000 chairs per month"},"correctOption":"A","correctAnswer":"It rises by 400 chairs to 2,400 chairs per month","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because new fixed costs are $30,000 + $6,000 = $36,000, and dividing $36,000 by $15 contribution per chair increases break-even output to 2,400 chairs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher fixed costs require more sales to break even, not fewer.","C":"Incorrect because an increase in fixed rent raises the break-even point.","D":"Incorrect because $6,000 is the rent increase in dollars, not the new break-even unit volume."}}},{"id":"P1_U4_MCQ_457","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_457","question":"When cotton fabric prices rise, a t-shirt manufacturer's variable cost per shirt increases while its selling price remains fixed. How does this affect contribution per shirt and the break-even point?","options":{"A":"Contribution per shirt decreases, which raises the break-even output required to cover fixed costs","B":"Contribution per shirt increases, which lowers the break-even output","C":"Neither contribution per shirt nor break-even output changes","D":"Fixed costs automatically drop to zero"},"correctOption":"A","correctAnswer":"Contribution per shirt decreases, which raises the break-even output required to cover fixed costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a higher variable cost with an unchanged selling price shrinks unit contribution (Price - VC), so more units must be sold to cover fixed costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher variable costs reduce rather than increase unit contribution.","C":"Incorrect because variable cost directly determines unit contribution.","D":"Incorrect because higher fabric prices do not eliminate fixed factory overheads."}}},{"id":"P1_U4_MCQ_458","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_458","question":"On a break-even chart, what does the vertical distance between the Total Revenue line and the Total Cost line to the LEFT of the break-even point represent?","options":{"A":"The size of the financial loss made at that output level","B":"The size of the net profit made at that output level","C":"Total fixed costs at maximum capacity","D":"The margin of safety in units"},"correctOption":"A","correctAnswer":"The size of the financial loss made at that output level","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because to the left of the break-even intersection, the Total Cost line lies above the Total Revenue line, so the vertical gap measures the loss incurred.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because net profit is shown to the right of the break-even point where Total Revenue exceeds Total Cost.","C":"Incorrect because fixed costs are shown by the horizontal fixed cost line.","D":"Incorrect because the margin of safety is measured horizontally along the output axis to the right of break-even."}}},{"id":"P1_U4_MCQ_459","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_459","question":"A toy factory manufactures 10,000 action figures in November, but retailers only buy 6,000 of them while 4,000 remain unsold in the warehouse. Why does a simple break-even chart give a misleading profit estimate here?","options":{"A":"Break-even analysis assumes that every single unit produced is immediately sold, ignoring changes in unsold inventory","B":"Break-even charts assume selling price is always $0","C":"Break-even charts cannot be drawn for toy factories","D":"Break-even analysis assumes fixed costs equal variable costs at zero output"},"correctOption":"A","correctAnswer":"Break-even analysis assumes that every single unit produced is immediately sold, ignoring changes in unsold inventory","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because standard break-even models plot output on the x-axis assuming output equals sales volume, ignoring unsold stock build-up.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Total Revenue slopes upward based on a positive selling price.","C":"Incorrect because break-even charts can be constructed for any manufacturing business.","D":"Incorrect because variable costs are zero at zero output while fixed costs are positive."}}},{"id":"P1_U4_MCQ_460","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_460","question":"In Business Studies, what is the most accurate definition of 'quality' for a good or service?","options":{"A":"Producing a good or service that is fit for purpose and meets or exceeds customer expectations","B":"Using only solid gold and diamonds in every manufactured product","C":"Charging the highest price in the industry regardless of product performance","D":"Inspecting finished goods only after customers complain"},"correctOption":"A","correctAnswer":"Producing a good or service that is fit for purpose and meets or exceeds customer expectations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality means consistency, reliability, and fitness for purpose relative to what target customers expect at that price level.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because luxury materials are unnecessary for everyday goods to be high quality.","C":"Incorrect because a high price without reliability represents poor value and poor quality.","D":"Incorrect because effective quality management prevents or detects faults before customers receive goods."}}},{"id":"P1_U4_MCQ_461","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_461","question":"A German kitchen-knife manufacturer builds a global reputation for blades that stay razor-sharp for decades without rusting. How does achieving consistently high quality benefit the company?","options":{"A":"It enables the company to charge a premium price, win repeat customers, and expand into new export markets","B":"It eliminates the need to purchase stainless steel","C":"It removes all factory electricity and wage expenses","D":"It prevents competitors from advertising their own knives"},"correctOption":"A","correctAnswer":"It enables the company to charge a premium price, win repeat customers, and expand into new export markets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because superior, reliable quality differentiates a brand, supports higher profit margins via premium pricing, and drives customer loyalty.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because high-grade steel still must be purchased.","C":"Incorrect because manufacturing wages and power costs still apply.","D":"Incorrect because rivals remain free to advertise."}}},{"id":"P1_U4_MCQ_462","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_462","question":"A pet-food manufacturer discovers after shipping 50,000 tins to supermarkets that a batch contains spoiled meat, forcing an urgent nationwide product recall and compensation payments. Which consequences of poor quality does this demonstrate?","options":{"A":"Heavy recall and compensation costs, severe damage to brand reputation, and lost supermarket shelf space","B":"Lower variable costs per tin and higher customer trust","C":"Increased labour productivity on the canning line","D":"Higher profit margins from selling spoiled pet food"},"correctOption":"A","correctAnswer":"Heavy recall and compensation costs, severe damage to brand reputation, and lost supermarket shelf space","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because product recalls after dispatch incur huge logistics, refund, and legal expenses while destroying retailer and consumer trust.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because recalls increase total costs and destroy trust.","C":"Incorrect because recalling and destroying 50,000 tins wastes output rather than raising productivity.","D":"Incorrect because recalled goods must be refunded and destroyed, causing heavy losses."}}},{"id":"P1_U4_MCQ_463","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_463","question":"At a wooden furniture factory, 15% of assembled dining chairs wobble due to uneven leg cutting, forcing carpenters to disassemble, recut, and reglue them before shipping. How does this quality failure affect operational costs?","options":{"A":"Reworking defective chairs wastes paid carpenter hours and glue, raising average cost per chair sold","B":"Reworking chairs lowers fixed factory rent","C":"Wobbly chairs increase labour productivity per worker","D":"Reworking eliminates the need to inspect timber before cutting"},"correctOption":"A","correctAnswer":"Reworking defective chairs wastes paid carpenter hours and glue, raising average cost per chair sold","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fixing mistakes after assembly consumes extra labour time and materials without producing additional sellable chairs, pushing unit costs up.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because factory rent is unaffected by chair rework.","C":"Incorrect because spending hours fixing errors lowers good output per employee.","D":"Incorrect because inspecting timber earlier would prevent uneven cutting."}}},{"id":"P1_U4_MCQ_464","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_464","question":"At a sports-shoe factory, dedicated quality inspectors pull every 20th pair of trainers off the end of the conveyor belt to test sole adhesion and stitching strength before boxing. Which quality method is being used?","options":{"A":"Quality control","B":"Quality assurance","C":"Kaizen cell production","D":"Just-in-time inventory"},"correctOption":"A","correctAnswer":"Quality control","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality control relies on specialist inspectors testing finished outputs (or samples) at the end of production to catch defects before shipping.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality assurance involves all workers checking quality throughout every production stage.","C":"Incorrect because Kaizen refers to continuous improvement suggestions by teams.","D":"Incorrect because JIT manages stock arrival timing."}}},{"id":"P1_U4_MCQ_465","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_465","question":"Why might a small toy-assembling workshop choose end-of-line quality control by two trained inspectors rather than full company-wide quality assurance?","options":{"A":"It is quicker and cheaper to implement because general assembly workers do not require extensive quality-management training","B":"Quality control guarantees zero wasted materials during assembly","C":"Quality assurance is illegal in small workshops","D":"Quality control inspectors prevent machines from ever breaking down"},"correctOption":"A","correctAnswer":"It is quicker and cheaper to implement because general assembly workers do not require extensive quality-management training","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality control concentrates inspection skills in a few specialists, avoiding the high training cost and time needed to train every worker.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality control only finds defects at the end, after materials have been used.","C":"Incorrect because small businesses are permitted to use quality assurance if they wish.","D":"Incorrect because end-of-line inspectors check finished toys rather than maintaining machinery."}}},{"id":"P1_U4_MCQ_466","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_466","question":"Under traditional quality control, assembly-line workers rush to hit hourly output targets, leaving it entirely to end-of-line inspectors to spot errors. What behavioural drawback does this create?","options":{"A":"Production workers feel no personal responsibility for quality, leading to higher defect and scrap rates","B":"Assembly workers spend too much time training each other in quality standards","C":"End-of-line inspectors become bored because zero faults ever occur","D":"Total output falls because workers stop every minute to check their own work"},"correctOption":"A","correctAnswer":"Production workers feel no personal responsibility for quality, leading to higher defect and scrap rates","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because separating 'making' from 'checking' encourages workers to treat quality as someone else's job, increasing defects and waste.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because workers receive minimal quality training under pure quality control.","C":"Incorrect because careless rushing typically produces numerous defects for inspectors to find.","D":"Incorrect because workers do not stop to self-inspect under traditional quality control."}}},{"id":"P1_U4_MCQ_467","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_467","question":"An aircraft engine manufacturer implements quality assurance, requiring certified engineering checks on raw titanium alloys, turbine blade machining, assembly torque, and test-bed runs before any engine is cleared. What defines quality assurance?","options":{"A":"Building agreed quality standards into every single stage of production so defects are prevented rather than discovered at the end","B":"Hiring one inspector to glance at engines only after they are loaded onto delivery trucks","C":"Eliminating all documentation and engineering checks to speed up assembly","D":"Allowing each mechanic to invent different bolt-tightening standards"},"correctOption":"A","correctAnswer":"Building agreed quality standards into every single stage of production so defects are prevented rather than discovered at the end","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality assurance establishes systematic procedures across all stages of design, sourcing, production, and delivery to prevent faults.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because checking only at the end describes quality control, not quality assurance.","C":"Incorrect because quality assurance relies on documented standards and stage verification.","D":"Incorrect because quality assurance enforces uniform, agreed standards across all staff."}}},{"id":"P1_U4_MCQ_468","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_468","question":"A precision electronics firm achieves international ISO quality assurance certification after embedding stage-by-stage quality checks across its factory. Besides reducing scrap waste, what commercial advantage does this bring?","options":{"A":"Recognized quality assurance accreditation wins trust and supply contracts from major corporate buyers","B":"ISO certification exempts the firm from paying electricity bills","C":"The firm no longer needs to train new production operators","D":"Component suppliers give the firm free microchips"},"correctOption":"A","correctAnswer":"Recognized quality assurance accreditation wins trust and supply contracts from major corporate buyers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because formal quality assurance accreditation proves reliable processes to business customers, opening doors to major contracts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because utility bills still must be paid.","C":"Incorrect because ongoing staff training is required to maintain quality assurance standards.","D":"Incorrect because suppliers still charge for microchips."}}},{"id":"P1_U4_MCQ_469","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_469","question":"A medium-sized furniture manufacturer transitions from quality control to quality assurance, spending $95,000 on training all 120 employees and developing stage checklists. What is a primary disadvantage during the first year of this transition?","options":{"A":"High upfront training and administrative costs, plus resistance from workers used to old habits","B":"Higher end-of-line scrappage than before","C":"Reduced employee involvement in workplace standards","D":"Increased customer returns of faulty furniture"},"correctOption":"A","correctAnswer":"High upfront training and administrative costs, plus resistance from workers used to old habits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because implementing quality assurance requires significant investment in training every employee and changing workplace culture.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality assurance lowers end-of-line scrap rates.","C":"Incorrect because quality assurance increases worker involvement rather than reducing it.","D":"Incorrect because better stage checks reduce customer returns."}}},{"id":"P1_U4_MCQ_470","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_470","question":"What is the fundamental difference between quality control and quality assurance?","options":{"A":"Quality control detects defects in finished products through specialist inspection, whereas quality assurance prevents defects at every stage through all employees","B":"Quality control is only used in hospitals, whereas quality assurance is only used in farms","C":"Quality control requires training every worker, whereas quality assurance requires zero training","D":"Quality control lowers scrap waste more effectively than quality assurance"},"correctOption":"A","correctAnswer":"Quality control detects defects in finished products through specialist inspection, whereas quality assurance prevents defects at every stage through all employees","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality control is an inspection-based 'detection' model at the end, while quality assurance is a process-based 'prevention' model throughout.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both methods are used across manufacturing and service industries.","C":"Incorrect because the training requirement is reversed: quality assurance requires extensive worker training.","D":"Incorrect because quality assurance prevents defects early, resulting in lower scrap waste."}}},{"id":"P1_U4_MCQ_471","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_471","question":"How does quality assurance differ from quality control in a manufacturing business?","options":{"A":"Quality control relies on inspecting finished items to find faults, whereas quality assurance prevents faults by building agreed quality standards into every stage of production","B":"Quality control prevents defects during design, whereas quality assurance only checks products after customers return them","C":"Quality control trains all employees to check their own work, whereas quality assurance hires end-of-line inspectors","D":"Quality control is only used by service businesses, whereas quality assurance is only used by farms"},"correctOption":"A","correctAnswer":"Quality control relies on inspecting finished items to find faults, whereas quality assurance prevents faults by building agreed quality standards into every stage of production","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality control detects faults through inspection (usually at the end of production), whereas quality assurance prevents faults across every production stage.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because prevention across stages defines quality assurance rather than quality control.","C":"Incorrect because the descriptions of quality control and quality assurance are reversed.","D":"Incorrect because both manufacturers and service businesses can use either approach."}}},{"id":"P1_U4_MCQ_472","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_472","question":"A toy factory relies solely on quality control inspectors checking finished toys at the end of the assembly line. What is a major disadvantage of this approach?","options":{"A":"Inspectors cannot detect any broken parts at the end of the line","B":"Raw materials, wages, and machine time have already been wasted on defective toys before the fault is discovered","C":"Workers need expensive training in quality standards at every stage","D":"Customers always receive faulty toys without any inspection"},"correctOption":"B","correctAnswer":"Raw materials, wages, and machine time have already been wasted on defective toys before the fault is discovered","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because end-of-line quality control finds defects only after full production costs have already been spent on making the faulty items.","distractor_reasons":{"A":"Incorrect because end-of-line inspection does detect visible defects before dispatch.","B":"Correct selection.","C":"Incorrect because comprehensive multi-stage staff training is a cost of quality assurance rather than end-of-line quality control.","D":"Incorrect because quality control filters out defective items before dispatch."}}},{"id":"P1_U4_MCQ_473","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_473","question":"How does a commercial airline measure and maintain quality in its passenger service operations?","options":{"A":"By tracking on-time departure rates, cabin cleanliness, baggage delivery accuracy, and staff responsiveness to passenger needs","B":"By weighing finished aluminium bars at the end of a smelter","C":"By cancelling flights whenever a plane is only 80% full","D":"By banning passengers from leaving post-flight feedback"},"correctOption":"A","correctAnswer":"By tracking on-time departure rates, cabin cleanliness, baggage delivery accuracy, and staff responsiveness to passenger needs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because service quality in aviation depends on punctuality, safety, cleanliness, reliable baggage handling, and attentive customer care.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because weighing aluminium bars applies to metal manufacturing, not passenger airlines.","C":"Incorrect because arbitrary cancellations destroy reliability and customer trust.","D":"Incorrect because passenger surveys are vital for monitoring service quality."}}},{"id":"P1_U4_MCQ_474","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_474","question":"A five-star resort trains all receptionists, housekeeping staff, and waiters in standardized hospitality procedures and uses a 40-point digital room checklist before clearing any suite for guest check-in. Which quality approach is this?","options":{"A":"Quality assurance in a service business","B":"Destructive product testing","C":"Computer-Aided Manufacturing (CAM)","D":"Batch reworking of hotel beds"},"correctOption":"A","correctAnswer":"Quality assurance in a service business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because training all service staff and verifying standards at every stage before guest arrival prevents service failures.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because destructive testing destroys physical samples to test breaking limits.","C":"Incorrect because CAM refers to computer-controlled factory machinery.","D":"Incorrect because hotel room preparation is a hospitality service process."}}},{"id":"P1_U4_MCQ_475","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_475","question":"A telecommunications company hires an independent agency to send mystery shoppers into its 60 retail stores to evaluate staff product knowledge, greeting speed, and store tidiness. How does this help the retailer?","options":{"A":"It provides objective feedback on actual customer experience across stores so managers can identify training gaps","B":"Mystery shoppers manufacture smartphones inside the retail stores","C":"It eliminates the need to pay store managers","D":"Mystery shoppers buy all store stock so shelves remain empty"},"correctOption":"A","correctAnswer":"It provides objective feedback on actual customer experience across stores so managers can identify training gaps","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mystery shopping tests real-world service delivery from a customer's perspective, highlighting branches that need coaching.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retail stores sell rather than manufacture phones.","C":"Incorrect because store managers are still needed to act on mystery-shopper findings.","D":"Incorrect because mystery shoppers evaluate service interactions rather than clearing shelves."}}},{"id":"P1_U4_MCQ_476","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_476","question":"Why do quality-assured manufacturers carefully audit and certify their raw-material suppliers before signing supply contracts?","options":{"A":"Substandard incoming raw materials or components will cause defects in finished products even if factory workers make no mistakes","B":"Certified suppliers deliver raw materials completely free of charge","C":"Auditing suppliers eliminates the need for factory machinery","D":"Poor-quality raw materials always improve finished product durability"},"correctOption":"A","correctAnswer":"Substandard incoming raw materials or components will cause defects in finished products even if factory workers make no mistakes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality assurance begins at the supply chain: reliable, defect-free inputs are essential to producing reliable finished goods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because suppliers still charge for certified materials.","C":"Incorrect because factory machinery is still required to transform inputs.","D":"Incorrect because defective inputs compromise final product quality."}}},{"id":"P1_U4_MCQ_477","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_477","question":"A motorcycle helmet manufacturer takes 5 helmets out of every batch of 1,000 and smashes them with heavy steel weights in a laboratory to verify impact protection, while using X-ray scanners on the remaining 995 helmets. Why does it test only a small sample destructively?","options":{"A":"Destructive testing ruins the tested helmets, so testing 100% destructively would leave zero helmets left to sell","B":"X-ray scanners destroy every helmet they scan","C":"Motorcycle helmets do not need to meet safety regulations","D":"Destructive testing costs zero money"},"correctOption":"A","correctAnswer":"Destructive testing ruins the tested helmets, so testing 100% destructively would leave zero helmets left to sell","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because destructive impact tests prove batch safety standards using a small sample while preserving the rest of the batch for sale via non-destructive X-rays.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because X-ray scanning is non-destructive and leaves helmets intact.","C":"Incorrect because helmets face strict legal safety standards.","D":"Incorrect because destroying 5 helmets per batch incurs material and lab testing costs."}}},{"id":"P1_U4_MCQ_478","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_478","question":"A chilled-soup manufacturer supplies three major supermarket chains, which permanently cancel their contracts after discovering leaky plastic lids on two consecutive deliveries. What business risk of poor quality does this highlight?","options":{"A":"Losing major B2B retail buyers can immediately wipe out a large share of revenue and threaten business survival","B":"Leaky soup lids increase customer satisfaction in supermarkets","C":"Supermarkets pay higher prices when packaging leaks","D":"Cancelling contracts lowers the soup manufacturer's average fixed costs"},"correctOption":"A","correctAnswer":"Losing major B2B retail buyers can immediately wipe out a large share of revenue and threaten business survival","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because major retail buyers enforce strict quality standards; repeated defects lead to delisting and sudden loss of vital sales volume.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because messy, leaking packaging angers shoppers and store staff.","C":"Incorrect because supermarkets reject and fine suppliers for faulty packaging.","D":"Incorrect because losing sales volume spreads fixed costs over fewer units, raising average fixed cost."}}},{"id":"P1_U4_MCQ_479","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_479","question":"A budget short-haul airline charges $35 for a one-hour flight with basic non-reclining seats and paid snacks, while consistently arriving on time in clean, well-maintained aircraft. Why do passengers consider this airline good quality?","options":{"A":"It reliably delivers safe, punctual air travel that matches customer expectations for a $35 budget ticket","B":"Budget airlines never perform safety or maintenance checks","C":"Quality only exists when airlines serve free five-course meals","D":"Passengers expect luxury beds on a $35 one-hour flight"},"correctOption":"A","correctAnswer":"It reliably delivers safe, punctual air travel that matches customer expectations for a $35 budget ticket","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality is judged relative to price and customer expectations: safe, clean, punctual flights fulfill the promise of a budget airline.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because all airlines must meet identical strict aviation safety standards.","C":"Incorrect because free gourmet meals are expected on expensive full-service flights, not $35 budget flights.","D":"Incorrect because customer expectations are shaped by the low $35 ticket price."}}},{"id":"P1_U4_MCQ_480","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_480","question":"A manufacturer of implanted cardiac pacemakers must ensure 100% reliability because any device failure could be fatal to a patient. Which quality management approach is essential and why?","options":{"A":"Rigorous quality assurance across every component, cleanroom assembly step, and test so defects are prevented before implantation","B":"Checking only 1% of finished pacemakers visually at the end of the line","C":"Eliminating quality checks so pacemakers reach hospitals faster","D":"Relying solely on patient complaints after surgery to spot faults"},"correctOption":"A","correctAnswer":"Rigorous quality assurance across every component, cleanroom assembly step, and test so defects are prevented before implantation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because life-critical medical devices require zero-defect prevention built into every stage of sourcing, cleanroom manufacturing, and testing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because visual sampling of 1% cannot prevent fatal internal electronic faults.","C":"Incorrect because skipping safety checks in medical manufacturing is illegal and life-threatening.","D":"Incorrect because discovering a pacemaker fault after surgery could cost a patient's life."}}},{"id":"P1_U4_MCQ_481","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_481","question":"A manufacturer plans to produce 8,000 units per year and compares three factory sites: Site 1 has annual fixed costs of $40,000 and variable costs of $5.00/unit; Site 2 has fixed costs of $55,000 and variable costs of $2.50/unit; Site 3 has fixed costs of $30,000 and variable costs of $7.00/unit. Which site has the lowest total annual cost?","options":{"A":"Site 1 ($80,000)","B":"Site 2 ($75,000)","C":"Site 3 ($86,000)","D":"All three sites have identical total costs"},"correctOption":"B","correctAnswer":"Site 2 ($75,000)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because at 8,000 units: Site 1 = $40,000 + $40,000 = $80,000; Site 2 = $55,000 + $20,000 = $75,000; Site 3 = $30,000 + $56,000 = $86,000, making Site 2 cheapest.","distractor_reasons":{"A":"Incorrect because $80,000 is $5,000 higher than Site 2's $75,000 total cost.","B":"Correct selection.","C":"Incorrect because despite having the lowest fixed costs ($30,000), Site 3's high variable costs ($56,000) make it the most expensive overall.","D":"Incorrect because total costs are $80,000, $75,000, and $86,000 respectively."}}},{"id":"P1_U4_MCQ_482","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_482","question":"A carbonated soft-drinks company ships concentrated flavour syrup in small drums and mixes it with local tap water and carbon dioxide to bottle millions of heavy drinks. Where should its bottling plants locate?","options":{"A":"Close to major urban population centres (markets) to avoid transporting heavy water-filled bottles long distances","B":"Inside remote mountain areas 800 km away from cities","C":"On an uninhabited island with no customers","D":"Inside a city-centre luxury jewellery arcade"},"correctOption":"A","correctAnswer":"Close to major urban population centres (markets) to avoid transporting heavy water-filled bottles long distances","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bottling adds heavy local water to light syrup (weight-gaining production), so locating near large consumer markets minimizes distribution freight costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shipping heavy water-filled bottles 800 km to cities incurs huge transport expenses.","C":"Incorrect because there are no local customers or transport links.","D":"Incorrect because industrial bottling lines require affordable industrial land and lorry access."}}},{"id":"P1_U4_MCQ_483","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_483","question":"A copper-mining company extracts raw copper ore containing only 1.5% copper and 98.5% waste rock, smelting it into pure copper ingots. Where should the smelting plant be located?","options":{"A":"Right next to the copper mine so 98.5% waste rock is not transported long distances","B":"In a distant capital city 1,200 kilometres away from the mine","C":"Inside a suburban retail shopping park","D":"On a cruise ship"},"correctOption":"A","correctAnswer":"Right next to the copper mine so 98.5% waste rock is not transported long distances","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because smelting is a heavily weight-losing process; locating at the raw material source avoids paying freight on massive quantities of waste rock.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because hauling 98.5% waste rock 1,200 km would be prohibitively expensive.","C":"Incorrect because heavy smelting plants cannot operate in suburban shopping parks.","D":"Incorrect because smelting requires fixed industrial infrastructure beside the mine."}}},{"id":"P1_U4_MCQ_484","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_484","question":"An artificial-intelligence software company decides to open its new research and development hub in a city with three top technical universities, despite high office rents. Which location factor is driving this decision?","options":{"A":"Availability of a large pool of highly skilled computer science and engineering graduates","B":"Proximity to open-cast iron ore mines","C":"Low-cost unskilled agricultural labour","D":"High walk-in tourist footfall"},"correctOption":"A","correctAnswer":"Availability of a large pool of highly skilled computer science and engineering graduates","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because knowledge-intensive technology firms prioritize access to specialist graduate talent over cheap land or rent.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because software R&D uses no iron ore.","C":"Incorrect because AI research requires highly qualified specialists rather than unskilled farm labour.","D":"Incorrect because software R&D offices do not rely on passing tourists."}}},{"id":"P1_U4_MCQ_485","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_485","question":"A mass-market clothing manufacturer opens a new garment-stitching plant in an industrial region with high unemployment and abundant semi-skilled machinists willing to work at competitive wages. Which location factor is most important here?","options":{"A":"Availability and affordable cost of suitable production labour","B":"Proximity to deep-sea oil rigs","C":"High luxury shopping-mall pedestrian footfall","D":"Cold alpine snow climate"},"correctOption":"A","correctAnswer":"Availability and affordable cost of suitable production labour","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because garment stitching is relatively labour-intensive, making an ample supply of affordable, skilled machinists decisive.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because garment stitching is unrelated to offshore oil rigs.","C":"Incorrect because factories distribute to retailers rather than selling to mall pedestrians.","D":"Incorrect because alpine snow is irrelevant to indoor garment stitching."}}},{"id":"P1_U4_MCQ_486","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_486","question":"An e-commerce parcel distributor builds its national sorting hub at the intersection of two major motorways and 10 minutes from an international cargo airport. Why is transport infrastructure vital for this business?","options":{"A":"Fast road and air connections minimize transit times and fuel costs so parcels reach nationwide and overseas customers next day","B":"Motorway intersections provide free electricity for warehouse lights","C":"Cargo airports supply raw timber for making cardboard boxes","D":"Customers walk along the motorway to collect parcels in person"},"correctOption":"A","correctAnswer":"Fast road and air connections minimize transit times and fuel costs so parcels reach nationwide and overseas customers next day","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because e-commerce logistics relies on rapid, uncongested road and air links to meet tight next-day delivery promises at low freight cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because warehouses still pay for electricity.","C":"Incorrect because airports provide air-freight links, not raw timber.","D":"Incorrect because parcels are delivered by vans and aircraft rather than collected by pedestrians."}}},{"id":"P1_U4_MCQ_487","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_487","question":"A commercial data-centre operator building massive AI server farms chooses a site beside a major geothermal power plant in a cool climate. Which two location factors explain this choice?","options":{"A":"Abundant, low-cost renewable electricity and naturally cool climate reducing server cooling expenses","B":"High pedestrian shopping footfall and proximity to cotton farms","C":"Availability of low-wage manual sewing machinists","D":"Proximity to deep-water fishing trawlers"},"correctOption":"A","correctAnswer":"Abundant, low-cost renewable electricity and naturally cool climate reducing server cooling expenses","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because AI data centres consume huge amounts of power for servers and cooling; reliable clean power and cool ambient air cut utility bills dramatically.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because data centres do not serve walk-in shoppers or use cotton.","C":"Incorrect because data centres employ IT engineers rather than sewing machinists.","D":"Incorrect because fishing trawlers are unrelated to cloud computing."}}},{"id":"P1_U4_MCQ_488","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_488","question":"To regenerate an old coal-mining town with 18% unemployment, a government designates an Enterprise Zone offering zero business property taxes for five years and $10,000 grants per new job created. How does this influence business location?","options":{"A":"Government financial incentives lower start-up and operating costs, encouraging firms to locate in the depressed region","B":"Grants force businesses to pay double property taxes","C":"Enterprise Zones ban factories from hiring local residents","D":"Government subsidies increase raw material transport costs"},"correctOption":"A","correctAnswer":"Government financial incentives lower start-up and operating costs, encouraging firms to locate in the depressed region","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tax holidays and job-creation grants offset regional disadvantages and attract inward investment to reduce unemployment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the zone offers zero property taxes for five years.","C":"Incorrect because grants reward hiring local workers.","D":"Incorrect because subsidies reduce financial outlays rather than raising freight rates."}}},{"id":"P1_U4_MCQ_489","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_489","question":"A fertiliser factory producing ammonia gas is prohibited by national law from building within 10 kilometres of schools, hospitals, or residential towns. Which location factor is restricting the firm's choice of site?","options":{"A":"Government health, safety, and zoning regulations protecting communities from hazardous industrial emissions","B":"Lack of farmers needing fertiliser","C":"High street retail rent inside hospitals","D":"Excessive government subsidies to build next to schools"},"correctOption":"A","correctAnswer":"Government health, safety, and zoning regulations protecting communities from hazardous industrial emissions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because planning and safety laws restrict hazardous chemical facilities to isolated industrial zones away from populated areas.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because agricultural demand exists, but safety laws dictate where the plant may be built.","C":"Incorrect because factories do not rent space inside hospitals.","D":"Incorrect because governments prohibit rather than subsidize chemical plants beside schools."}}},{"id":"P1_U4_MCQ_490","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_490","question":"A fashion boutique decides to open inside a major city-centre shopping mall beside popular cafés, cinemas, and department stores rather than on a quiet industrial estate. Why is this location advantageous for a retailer?","options":{"A":"High shopper footfall and complementary neighbouring stores attract impulse buyers and target customers","B":"City-centre shopping malls charge zero rent","C":"The boutique uses heavy freight trains to deliver dresses to shoppers","D":"Industrial estates have too many passing window-shoppers"},"correctOption":"A","correctAnswer":"High shopper footfall and complementary neighbouring stores attract impulse buyers and target customers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retail stores thrive where large numbers of shoppers already gather for leisure and complementary shopping.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because prime mall locations charge high commercial rent.","C":"Incorrect because retail boutiques sell directly to shoppers in store.","D":"Incorrect because industrial estates have very low pedestrian shopper footfall."}}},{"id":"P1_U4_MCQ_491","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_491","question":"A physiotherapy clinic must rent ground-floor premises on a busy main road with wheelchair access, whereas an online tax-software consultancy operates from a small rented office in a quiet rural town. What explains their different location needs?","options":{"A":"Physical personal services require direct face-to-face customer accessibility, whereas digital services can be delivered remotely online","B":"Online tax consultants require wheelchair ramps for heavy lorry deliveries","C":"Physiotherapy clinics treat patients exclusively via video games","D":"Rural towns have no internet connectivity"},"correctOption":"A","correctAnswer":"Physical personal services require direct face-to-face customer accessibility, whereas digital services can be delivered remotely online","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because services requiring physical customer presence depend on convenient local access, while digital services are location-independent.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because online software consultants deliver services electronically.","C":"Incorrect because hands-on physiotherapy requires patients to visit the clinic in person.","D":"Incorrect because the online consultancy relies on broadband internet in the rural town."}}},{"id":"P1_U4_MCQ_492","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_492","question":"A biotechnology start-up locates in a science park surrounded by medical research institutes, specialist laboratory equipment suppliers, and venture-capital investors. Which location advantage does this illustrate?","options":{"A":"External economies of scale gained from clustering near specialist suppliers, research talent, and industry partners","B":"Diseconomies of scale from excessive internal bureaucracy","C":"Low-cost unskilled farm labour","D":"Proximity to coal mines and steel mills"},"correctOption":"A","correctAnswer":"External economies of scale gained from clustering near specialist suppliers, research talent, and industry partners","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because external economies of scale occur when firms in the same industry cluster together, sharing specialist infrastructure, talent pools, and suppliers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because diseconomies of scale arise when an individual firm grows too large internally.","C":"Incorrect because biotechnology requires PhD scientists rather than unskilled farm labour.","D":"Incorrect because coal mines and steel mills are unrelated to biotechnology."}}},{"id":"P1_U4_MCQ_493","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_493","question":"A retired chef opens a small artisan patisserie in the coastal town where she grew up so she can walk to work and live near her grandchildren, even though another city might offer slightly higher profits. Which location factor is influencing her decision?","options":{"A":"Personal preferences and lifestyle priorities of the business owner","B":"Government enterprise zone tax holidays","C":"Proximity to bauxite mines and hydroelectric dams","D":"Avoidance of international import tariffs"},"correctOption":"A","correctAnswer":"Personal preferences and lifestyle priorities of the business owner","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sole traders and small business owners frequently prioritize personal family ties and quality of life alongside financial returns.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no government enterprise zone was mentioned.","C":"Incorrect because bauxite mines and dams are irrelevant to a small patisserie.","D":"Incorrect because a local coastal patisserie serves local residents and visitors rather than exporting."}}},{"id":"P1_U4_MCQ_494","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_494","question":"A rapidly growing craft brewery outgrows its cramped, high-rent city-centre unit where delivery lorries struggle with narrow streets, so it relocates to a spacious out-of-town industrial estate. Which two factors explain this relocation?","options":{"A":"Need for larger premises to expand output and lower rent with easier heavy-lorry access","B":"Desire to pay higher rent and restrict lorry deliveries","C":"Need for higher pedestrian shopping-mall footfall inside the brewery","D":"Legal ban on brewing beer outside city centres"},"correctOption":"A","correctAnswer":"Need for larger premises to expand output and lower rent with easier heavy-lorry access","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because expanding manufacturers often relocate from congested urban sites to out-of-town estates to gain room for growth, lower rent, and motorway access.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because out-of-town estates offer lower rent and better lorry access.","C":"Incorrect because a production brewery distributes kegs and bottles by lorry rather than relying on mall footfall.","D":"Incorrect because no law restricts brewing to city centres."}}},{"id":"P1_U4_MCQ_495","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_495","question":"When a printing company relocates its factory 70 kilometres away to a cheaper rural industrial park, 40% of its experienced print technicians resign because the commute is too far. What drawback of relocation does this show?","options":{"A":"Losing skilled, loyal staff and incurring high redundancy, recruitment, and retraining costs alongside temporary production disruption","B":"Lower rural land rent increases fixed costs","C":"Experienced technicians require zero training when replaced by new hires","D":"Relocating never disrupts customer order deliveries"},"correctOption":"A","correctAnswer":"Losing skilled, loyal staff and incurring high redundancy, recruitment, and retraining costs alongside temporary production disruption","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because moving a business away from its existing workforce often triggers staff departures, redundancy payouts, and costly retraining of replacements.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lower rural land rent reduces rather than increases fixed costs.","C":"Incorrect because new hires require significant training to match experienced technicians.","D":"Incorrect because dismantling, moving, and reinstalling printing presses causes temporary disruption."}}},{"id":"P1_U4_MCQ_496","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_496","question":"A Japanese automotive manufacturer opens an assembly plant inside the United States after a 25% import tariff is imposed on foreign-built cars. How does locating production inside the US overcome this trade barrier?","options":{"A":"Vehicles assembled inside the US are treated as domestic output and avoid the 25% import tariff","B":"Japanese workers commute daily across the Pacific Ocean to the US factory","C":"US factories pay zero corporate taxes or employee wages","D":"Import tariffs apply only to cars built inside the United States"},"correctOption":"A","correctAnswer":"Vehicles assembled inside the US are treated as domestic output and avoid the 25% import tariff","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because establishing local manufacturing inside a foreign market or trading bloc bypasses import tariffs and quotas levied on imported finished goods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the plant employs local US workers.","C":"Incorrect because US plants pay US wages and taxes.","D":"Incorrect because tariffs are taxes on imported foreign goods, not domestic production."}}},{"id":"P1_U4_MCQ_497","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_497","question":"A European clothing brand moves manufacturing to an overseas country whose currency suddenly appreciates by 20% against the euro, making factory wages and local bills 20% more expensive when converted back into euros. Which international location risk is this?","options":{"A":"Exchange rate fluctuations can unexpectedly wipe out overseas cost savings and squeeze profit margins","B":"Appreciating foreign currencies make overseas factories completely free to run","C":"Exchange rates never change between countries","D":"Language barriers disappear when currencies appreciate"},"correctOption":"A","correctAnswer":"Exchange rate fluctuations can unexpectedly wipe out overseas cost savings and squeeze profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because volatile exchange rates alter the home-currency cost of overseas wages, utilities, and repatriated profits.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a stronger foreign currency makes overseas costs more expensive in the home currency.","C":"Incorrect because most global currencies fluctuate daily on foreign exchange markets.","D":"Incorrect because exchange rate movements are financial and do not remove language differences."}}},{"id":"P1_U4_MCQ_498","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_498","question":"A multinational sportswear brand relocates production to a country with weak labour and environmental enforcement, and media investigations later expose unsafe factory conditions and river pollution, sparking global consumer boycotts. What risk of overseas location does this illustrate?","options":{"A":"Ethical and reputational damage if overseas operations or suppliers fail to uphold responsible safety and environmental standards","B":"Excessive bulk-buying discounts on organic cotton","C":"Higher customer loyalty resulting from media investigations","D":"Lower transport costs from shipping goods across oceans"},"correctOption":"A","correctAnswer":"Ethical and reputational damage if overseas operations or suppliers fail to uphold responsible safety and environmental standards","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because global consumers hold multinational brands accountable for working conditions and environmental practices across their overseas factories.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the issue was unsafe conditions and pollution, not cotton discounts.","C":"Incorrect because media exposés triggered consumer boycotts rather than loyalty.","D":"Incorrect because long-distance ocean shipping increases rather than lowers transport costs."}}},{"id":"P1_U4_MCQ_499","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_499","question":"A European home-appliances firm manufactures washing machines in a single overseas factory 10,000 kilometres away, but a blocked shipping canal delays container ships by six weeks, leaving European retailers without stock. What operational weakness of distant international location is shown here?","options":{"A":"Long international supply chains increase lead times and expose the business to severe shipping bottlenecks and stockouts","B":"Container ships travel faster than local delivery vans","C":"Distant overseas factories eliminate all sea-freight insurance costs","D":"European retailers prefer empty shelves for six weeks"},"correctOption":"A","correctAnswer":"Long international supply chains increase lead times and expose the business to severe shipping bottlenecks and stockouts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because relying on a single distant overseas plant stretches supply lines, making inventory vulnerable to port congestion, canal blockages, and long lead times.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because transoceanic container shipping takes weeks compared with hours or days by local van.","C":"Incorrect because long ocean voyages require marine cargo insurance.","D":"Incorrect because six-week stockouts cause lost sales and retailer penalties."}}},{"id":"P1_U4_MCQ_500","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_500","question":"When deciding whether to relocate production to a low-wage country overseas, why must managers combine quantitative cost calculations with qualitative factors?","options":{"A":"Because lower foreign wages and taxes can be outweighed by qualitative risks such as quality control problems, communication barriers, IP theft, and supply delays","B":"Because quantitative wage and transport costs are completely irrelevant to business profit","C":"Because qualitative factors like language and political stability can always be ignored","D":"Because overseas factories never require quality inspections or transport links"},"correctOption":"A","correctAnswer":"Because lower foreign wages and taxes can be outweighed by qualitative risks such as quality control problems, communication barriers, IP theft, and supply delays","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sound location decisions balance measurable financial savings (wages, rent, taxes) against non-financial operational risks (quality, communication, stability, lead times).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quantitative cost comparisons are a core starting point for location decisions.","C":"Incorrect because ignoring language, legal, or political risks can cause major operational failures.","D":"Incorrect because distant overseas plants require even stronger quality monitoring and logistics coordination."}}},{"id":"P1_U4_MCQ_501","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_501","question":"What is meant by the term 'production' in Business Studies?","options":{"A":"The process of converting inputs such as raw materials and labour into finished goods and services","B":"The amount of output produced by each employee in a given time period","C":"The practice of holding large quantities of finished goods in a warehouse","D":"The process of inspecting finished goods at the end of a factory line"},"correctOption":"A","correctAnswer":"The process of converting inputs such as raw materials and labour into finished goods and services","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because production is the transformation of resources (factors of production) into goods and services that satisfy customer needs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because output per employee per time period defines labour productivity rather than total production.","C":"Incorrect because storing finished goods refers to inventory holding rather than the production process itself.","D":"Incorrect because end-of-line inspection defines quality control rather than production."}}},{"id":"P1_U4_MCQ_502","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_502","question":"How is 'added value' defined in operations management?","options":{"A":"Total sales revenue minus all fixed and variable business costs","B":"The difference between the selling price of a product and the cost of bought-in materials and components","C":"The total output divided by the number of production workers","D":"The extra buffer stock kept to prevent unexpected factory stoppages"},"correctOption":"B","correctAnswer":"The difference between the selling price of a product and the cost of bought-in materials and components","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value measures the increase in worth created during production by subtracting the cost of bought-in inputs from the selling price.","distractor_reasons":{"A":"Incorrect because subtracting all fixed and variable costs (including wages and rent) calculates profit rather than added value.","B":"Correct selection.","C":"Incorrect because dividing output by worker numbers measures labour productivity.","D":"Incorrect because safety stock refers to buffer inventory."}}},{"id":"P1_U4_MCQ_503","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_503","question":"What is meant by 'labour productivity'?","options":{"A":"The total value of all machinery used inside a factory","B":"The total number of hours employees work each week","C":"The quantity of output produced per employee over a specific period of time","D":"The total volume of goods manufactured by a business in one year"},"correctOption":"C","correctAnswer":"The quantity of output produced per employee over a specific period of time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because labour productivity measures workforce efficiency by calculating output per worker in a given time period.","distractor_reasons":{"A":"Incorrect because machinery value measures capital investment rather than labour efficiency.","B":"Incorrect because total hours worked measures labour input rather than output per worker.","C":"Correct selection.","D":"Incorrect because total annual output measures the level of production rather than productivity."}}},{"id":"P1_U4_MCQ_504","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_504","question":"How does 'production' differ from 'productivity'?","options":{"A":"Production applies only to services, whereas productivity applies only to manufactured goods","B":"Production measures average unit cost, whereas productivity measures total sales revenue","C":"Production can never be increased, whereas productivity increases automatically every year","D":"Production is the total amount of output made, whereas productivity measures how efficiently inputs are used to create output"},"correctOption":"D","correctAnswer":"Production is the total amount of output made, whereas productivity measures how efficiently inputs are used to create output","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because production refers to the total volume of output, while productivity measures the rate of output per unit of input (such as per worker).","distractor_reasons":{"A":"Incorrect because both goods and services involve production and productivity.","B":"Incorrect because neither term is defined as unit cost or sales revenue.","C":"Incorrect because both production and productivity can rise or fall depending on resources and management.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_505","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_505","question":"What is meant by 'operational efficiency'?","options":{"A":"Producing output at the lowest possible average cost with minimal waste of time and resources","B":"Maximizing the amount of raw materials stored in warehouses","C":"Hiring the largest possible workforce regardless of output levels","D":"Charging the highest price in the market for every product"},"correctOption":"A","correctAnswer":"Producing output at the lowest possible average cost with minimal waste of time and resources","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because efficiency means achieving maximum output from minimum inputs, keeping average unit costs and waste as low as possible.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because holding excessive stock ties up cash and increases storage costs, reducing efficiency.","C":"Incorrect because employing unnecessary workers lowers productivity and raises unit costs.","D":"Incorrect because pricing strategy does not measure how efficiently resources are used in operations."}}},{"id":"P1_U4_MCQ_506","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_506","question":"What is meant by 'capital-intensive production'?","options":{"A":"A production process that relies mainly on manual human skills and hand tools","B":"A production process that uses a high proportion of machinery and equipment relative to human labour","C":"A production method where unique one-off items are crafted for individual clients","D":"A system where zero machinery or electricity is used in manufacturing"},"correctOption":"B","correctAnswer":"A production process that uses a high proportion of machinery and equipment relative to human labour","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because capital-intensive production relies heavily on automated machinery, technology, and equipment rather than large numbers of workers.","distractor_reasons":{"A":"Incorrect because relying mainly on human workers defines labour-intensive production.","B":"Correct selection.","C":"Incorrect because crafting one-off items defines job production, which is usually labour-intensive.","D":"Incorrect because capital-intensive production uses extensive machinery and power."}}},{"id":"P1_U4_MCQ_507","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_507","question":"Which situation makes 'labour-intensive production' most suitable for a business?","options":{"A":"When wage rates are very high and the product is completely standardized","B":"When the business operates 24 hours a day producing millions of identical steel cans","C":"When skilled labour is plentiful and inexpensive, or when products require personalized hand-crafting","D":"When the business wants to minimize direct wage costs through heavy robotics"},"correctOption":"C","correctAnswer":"When skilled labour is plentiful and inexpensive, or when products require personalized hand-crafting","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because labour-intensive methods are economical where wages are low and advantageous where delicate, bespoke human craftsmanship is valued.","distractor_reasons":{"A":"Incorrect because high wages and standardized mass products favour capital-intensive automation.","B":"Incorrect because continuous 24-hour mass production of identical cans is capital-intensive.","C":"Correct selection.","D":"Incorrect because heavy robotics characterizes capital-intensive production."}}},{"id":"P1_U4_MCQ_508","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_508","question":"What is the primary aim of 'lean production'?","options":{"A":"To increase buffer stock levels so warehouses are always full","B":"To lengthen the time taken to manufacture each unit","C":"To replace all quality checks with faster assembly speeds","D":"To eliminate all forms of waste in the production process while maintaining quality"},"correctOption":"D","correctAnswer":"To eliminate all forms of waste in the production process while maintaining quality","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because lean production systematically removes wasted time, materials, inventory, and effort to lower costs and improve quality.","distractor_reasons":{"A":"Incorrect because excess inventory is considered a major waste in lean production.","B":"Incorrect because lean production aims to shorten lead times rather than lengthen them.","C":"Incorrect because lean production builds quality into processes to eliminate defect waste.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_509","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_509","question":"What is meant by the lean production concept of 'Kaizen'?","options":{"A":"Continuous improvement achieved through small, regular efficiency ideas suggested by workers","B":"Ordering raw materials only at the exact moment they are needed on the assembly line","C":"Testing finished goods at the end of production to detect faults","D":"Grouping identical products together to manufacture them in fixed quantities"},"correctOption":"A","correctAnswer":"Continuous improvement achieved through small, regular efficiency ideas suggested by workers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Kaizen means 'continuous improvement' and empowers employees to suggest regular, low-cost improvements to eliminate waste.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ordering materials only as needed defines just-in-time (JIT) inventory control.","C":"Incorrect because end-of-line testing defines quality control.","D":"Incorrect because manufacturing fixed groups of identical items defines batch production."}}},{"id":"P1_U4_MCQ_510","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_510","question":"What is meant by 'just-in-time' (JIT) inventory control?","options":{"A":"Holding six months of spare raw materials in case suppliers go on strike","B":"Arranging for raw materials and components to arrive precisely as they are needed in production, eliminating buffer stocks","C":"Manufacturing goods months in advance before any customer orders are received","D":"Inspecting raw materials only after finished goods are delivered to shops"},"correctOption":"B","correctAnswer":"Arranging for raw materials and components to arrive precisely as they are needed in production, eliminating buffer stocks","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because JIT avoids holding warehouse inventory by synchronizing supplier deliveries directly with production schedules.","distractor_reasons":{"A":"Incorrect because holding large reserve stocks is buffer inventory, the opposite of JIT.","B":"Correct selection.","C":"Incorrect because making goods without orders causes overproduction waste, which JIT prevents.","D":"Incorrect because incoming materials must still be reliable before assembly begins."}}},{"id":"P1_U4_MCQ_511","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_511","question":"What is a major risk of operating a 'just-in-time' (JIT) inventory system?","options":{"A":"High warehouse rent and insurance costs from storing excess stock","B":"Increased risk of stored raw materials becoming obsolete in warehouses","C":"Any unexpected supplier delay or transport disruption immediately halts the entire production line","D":"Working capital is permanently tied up in large stockpiles of components"},"correctOption":"C","correctAnswer":"Any unexpected supplier delay or transport disruption immediately halts the entire production line","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because JIT eliminates buffer stock, leaving production completely vulnerable to late deliveries or supply-chain disruptions.","distractor_reasons":{"A":"Incorrect because JIT reduces or eliminates warehouse storage costs.","B":"Incorrect because holding minimal stock lowers obsolescence risk rather than increasing it.","C":"Correct selection.","D":"Incorrect because JIT frees up working capital rather than tying it up in inventory."}}},{"id":"P1_U4_MCQ_512","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_512","question":"What is the purpose of holding 'buffer inventory'?","options":{"A":"To maximize warehouse storage and security expenses","B":"To ensure the business has zero stock available when orders arrive","C":"To replace all computerized stock-control systems","D":"To act as a safety reserve that protects against sudden surges in customer demand or late supplier deliveries"},"correctOption":"D","correctAnswer":"To act as a safety reserve that protects against sudden surges in customer demand or late supplier deliveries","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because buffer inventory prevents stockouts and production stoppages when demand rises unexpectedly or deliveries are delayed.","distractor_reasons":{"A":"Incorrect because higher storage costs are a disadvantage of holding inventory, not its purpose.","B":"Incorrect because buffer stock ensures stock is available rather than zero.","C":"Incorrect because businesses still use stock-control systems to monitor buffer levels.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_513","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_513","question":"Which of the following is a significant financial drawback of holding high levels of inventory?","options":{"A":"Cash is tied up in unsold stock, creating an opportunity cost alongside warehouse rent, insurance, and obsolescence risks","B":"The business loses bulk-buying discounts from suppliers","C":"The business frequently suffers stockouts when customer demand rises","D":"Delivery transport costs increase due to ordering tiny quantities every hour"},"correctOption":"A","correctAnswer":"Cash is tied up in unsold stock, creating an opportunity cost alongside warehouse rent, insurance, and obsolescence risks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because large inventories lock up working capital that could be used elsewhere and incur ongoing storage, insurance, and spoilage/obsolescence costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ordering large quantities usually earns bulk-buying discounts.","C":"Incorrect because high inventory reduces the risk of stockouts.","D":"Incorrect because frequent small deliveries describe JIT rather than holding large inventories."}}},{"id":"P1_U4_MCQ_514","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_514","question":"What is meant by 'job production'?","options":{"A":"Continuously manufacturing millions of identical products on an assembly line","B":"Producing a single, unique item made to an individual customer's exact specifications","C":"Making a fixed group of identical items before resetting machines to make another variant","D":"Employing workers on zero-hours contracts to pack supermarket shelves"},"correctOption":"B","correctAnswer":"Producing a single, unique item made to an individual customer's exact specifications","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because job production creates bespoke, one-off products tailored to a specific customer order.","distractor_reasons":{"A":"Incorrect because continuous mass production of identical items defines flow production.","B":"Correct selection.","C":"Incorrect because making groups of identical items before switching defines batch production.","D":"Incorrect because employment contract types are unrelated to production methods."}}},{"id":"P1_U4_MCQ_515","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_515","question":"What is a key advantage of 'job production'?","options":{"A":"It achieves the lowest average unit cost through mass-production economies of scale","B":"It requires zero skilled workers because machines run automatically","C":"Each product meets the exact requirements of the customer, allowing high added value and premium prices","D":"Large inventories of finished goods can be stockpiled years in advance"},"correctOption":"C","correctAnswer":"Each product meets the exact requirements of the customer, allowing high added value and premium prices","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because bespoke customization yields high customer satisfaction and allows the business to charge premium prices.","distractor_reasons":{"A":"Incorrect because low unit cost via economies of scale is an advantage of flow production, not job production.","B":"Incorrect because job production usually relies heavily on highly skilled workers.","C":"Correct selection.","D":"Incorrect because job production starts only after an individual customer places an order."}}},{"id":"P1_U4_MCQ_516","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_516","question":"What is a major disadvantage of 'job production'?","options":{"A":"Workers become demotivated by repeating the exact same 5-second task all day","B":"Every product is completely identical with zero customization","C":"A single breakdown on a conveyor belt halts millions of units","D":"Production is slow and labour-intensive, resulting in high average costs per unit"},"correctOption":"D","correctAnswer":"Production is slow and labour-intensive, resulting in high average costs per unit","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because bespoke design, skilled labour, and lack of bulk standardization make job production slow and expensive per unit.","distractor_reasons":{"A":"Incorrect because monotonous repetition is a drawback of flow production; job production offers high task variety.","B":"Incorrect because job production specializes in unique customization.","C":"Incorrect because continuous conveyor lines belong to flow production.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_517","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_517","question":"What is meant by 'batch production'?","options":{"A":"Producing a set quantity of identical items together before stopping and resetting equipment to produce another group","B":"Crafting one single custom item to an individual client's unique design","C":"Running an automated assembly line non-stop 24 hours a day for a single standardized product","D":"Buying finished goods from wholesalers and reselling them online"},"correctOption":"A","correctAnswer":"Producing a set quantity of identical items together before stopping and resetting equipment to produce another group","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because batch production manufactures items in groups (batches), allowing a business to offer variety while gaining some economies of scale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because crafting one unique item defines job production.","C":"Incorrect because non-stop production of a single standardized item defines flow production.","D":"Incorrect because reselling finished goods is retail/wholesale distribution rather than a manufacturing method."}}},{"id":"P1_U4_MCQ_518","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_518","question":"What is a primary disadvantage of 'batch production' compared with flow production?","options":{"A":"It cannot produce more than one product flavour, size, or colour","B":"Time and money are lost cleaning, resetting, and retooling machinery between different batches, and work-in-progress inventory builds up","C":"It requires zero machinery or equipment","D":"Every single unit must be hand-carved from scratch"},"correctOption":"B","correctAnswer":"Time and money are lost cleaning, resetting, and retooling machinery between different batches, and work-in-progress inventory builds up","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because switching between batches causes non-productive setup downtime and requires storing semi-finished work-in-progress.","distractor_reasons":{"A":"Incorrect because offering product variety across different batches is a key advantage of batch production.","B":"Correct selection.","C":"Incorrect because batch production regularly uses specialized machines and ovens.","D":"Incorrect because hand-crafting individual units describes job production."}}},{"id":"P1_U4_MCQ_519","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_519","question":"What is meant by 'flow production'?","options":{"A":"Producing bespoke one-off items only when individual clients request them","B":"Manufacturing small groups of varied items with frequent machine resets","C":"Continuous, large-scale production of standardized, identical products along an integrated assembly line","D":"Delivering personal face-to-face consulting services to corporate clients"},"correctOption":"C","correctAnswer":"Continuous, large-scale production of standardized, identical products along an integrated assembly line","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because flow (mass) production moves standardized products continuously from one operation to the next without interruption.","distractor_reasons":{"A":"Incorrect because bespoke one-off manufacturing defines job production.","B":"Incorrect because manufacturing groups with frequent resets defines batch production.","C":"Correct selection.","D":"Incorrect because personal consulting is a tailored professional service."}}},{"id":"P1_U4_MCQ_520","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_520","question":"What is a major advantage of 'flow production'?","options":{"A":"Every item can be customized individually at zero extra cost","B":"It requires very little upfront capital expenditure on machinery","C":"Workers experience high variety and autonomy in every task","D":"High-speed automated output and economies of scale result in very low average cost per unit"},"correctOption":"D","correctAnswer":"High-speed automated output and economies of scale result in very low average cost per unit","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because continuous high-volume output spreads fixed equipment costs and unlocks bulk purchasing discounts, minimizing unit cost.","distractor_reasons":{"A":"Incorrect because flow production is inflexible and designed for standardized items.","B":"Incorrect because flow production requires heavy upfront investment in specialized machinery.","C":"Incorrect because assembly-line tasks in flow production are typically repetitive.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_521","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_521","question":"What is a key disadvantage of 'flow production'?","options":{"A":"High initial capital setup costs, inflexibility to alter product designs, and costly disruption if any machine breaks down","B":"Average cost per unit is much higher than in job production","C":"Output levels are too low to supply national or global mass markets","D":"Machinery must be stopped and cleaned after every single item"},"correctOption":"A","correctAnswer":"High initial capital setup costs, inflexibility to alter product designs, and costly disruption if any machine breaks down","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because flow lines are expensive to build, difficult to adapt to new products, and vulnerable to complete stoppages if one stage fails.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because flow production achieves much lower unit costs than job production.","C":"Incorrect because flow production generates the highest output volumes for mass markets.","D":"Incorrect because stopping and resetting between runs characterizes batch production."}}},{"id":"P1_U4_MCQ_522","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_522","question":"What is meant by 'automation' in production?","options":{"A":"Providing workers with hand-held electric drills that they guide manually","B":"Using computer-controlled machinery and equipment to operate production processes with minimal human intervention","C":"Replacing all factory computers with handwritten paper ledgers","D":"Inspecting every finished product visually using a magnifying glass"},"correctOption":"B","correctAnswer":"Using computer-controlled machinery and equipment to operate production processes with minimal human intervention","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because automation relies on computers and sensors to control machines and processes automatically.","distractor_reasons":{"A":"Incorrect because human workers directly operating powered tools defines mechanisation rather than automation.","B":"Correct selection.","C":"Incorrect because automation replaces manual paper tasks with digital computer control.","D":"Incorrect because manual visual inspection is traditional quality control."}}},{"id":"P1_U4_MCQ_523","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_523","question":"How does 'mechanisation' differ from 'automation'?","options":{"A":"Mechanisation uses computers to run factories without people, whereas automation uses only hand tools","B":"Mechanisation is used only in banks, whereas automation is used only in farms","C":"In mechanisation, human workers directly operate powered machines, whereas in automation, computers control machines automatically","D":"There is no difference between mechanisation and automation"},"correctOption":"C","correctAnswer":"In mechanisation, human workers directly operate powered machines, whereas in automation, computers control machines automatically","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because mechanisation assists human labour with powered machines, whereas automation uses programmed computer control to run operations independently.","distractor_reasons":{"A":"Incorrect because the definitions are reversed.","B":"Incorrect because both mechanisation and automation are used across many industries.","C":"Correct selection.","D":"Incorrect because the level of computer autonomy distinguishes automation from mechanisation."}}},{"id":"P1_U4_MCQ_524","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_524","question":"What is the function of 'Computer-Aided Design' (CAD)?","options":{"A":"Scanning customer barcodes at supermarket checkouts","B":"Automatically welding car frames on a factory assembly line","C":"Processing contactless debit card payments in retail shops","D":"Using computer software to create, modify, analyse, and test 2D and 3D product designs on screen"},"correctOption":"D","correctAnswer":"Using computer software to create, modify, analyse, and test 2D and 3D product designs on screen","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because CAD enables engineers and designers to draft and simulate product designs digitally before physical production.","distractor_reasons":{"A":"Incorrect because barcode scanning at checkouts is Electronic Point of Sale (EPOS).","B":"Incorrect because automated physical manufacturing on the factory floor is CAM/robotics.","C":"Incorrect because electronic card payment processing is EFTPOS.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_525","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_525","question":"What is a key advantage of using 'Computer-Aided Design' (CAD)?","options":{"A":"Product designs can be altered and tested rapidly without repeatedly building expensive physical prototypes","B":"It eliminates the need to buy raw materials when manufacturing the product","C":"It physically assembles products on the factory floor without any machinery","D":"It guarantees that competitors cannot copy product ideas"},"correctOption":"A","correctAnswer":"Product designs can be altered and tested rapidly without repeatedly building expensive physical prototypes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because CAD speeds up design revisions and runs digital stress/performance simulations, saving time and prototype costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raw materials are still required once physical manufacturing begins.","C":"Incorrect because CAD is design software rather than physical manufacturing equipment.","D":"Incorrect because intellectual property protection requires patents or copyrights, not CAD software."}}},{"id":"P1_U4_MCQ_526","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_526","question":"What is meant by 'Computer-Aided Manufacturing' (CAM)?","options":{"A":"Using software to create 3D product drawings on a designer's screen","B":"Using computers to control and guide factory machinery and tools directly during physical production","C":"Using mobile apps to advertise products on social media","D":"Using spreadsheet software to calculate employee monthly salaries"},"correctOption":"B","correctAnswer":"Using computers to control and guide factory machinery and tools directly during physical production","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because CAM uses computer software and digital instructions to operate manufacturing machinery such as cutters, drills, and lathes.","distractor_reasons":{"A":"Incorrect because on-screen digital drafting is Computer-Aided Design (CAD).","B":"Correct selection.","C":"Incorrect because social media promotion is digital marketing.","D":"Incorrect because calculating wages is human-resource/finance payroll administration."}}},{"id":"P1_U4_MCQ_527","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_527","question":"What is a primary advantage of 'Computer-Aided Manufacturing' (CAM)?","options":{"A":"It requires zero upfront capital investment to purchase machines","B":"It eliminates all electricity costs in the factory","C":"It delivers consistent precision, lower defect rates, and faster output speeds than manual machining","D":"It prevents machines from ever requiring maintenance"},"correctOption":"C","correctAnswer":"It delivers consistent precision, lower defect rates, and faster output speeds than manual machining","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because computer-controlled machines follow exact digital tolerances repeatedly without fatigue, reducing errors and waste.","distractor_reasons":{"A":"Incorrect because CAM equipment requires substantial upfront capital expenditure.","B":"Incorrect because CAM machinery consumes electrical power.","C":"Correct selection.","D":"Incorrect because precision CAM equipment still needs regular specialist maintenance."}}},{"id":"P1_U4_MCQ_528","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_528","question":"What is meant by 'Computer-Integrated Manufacturing' (CIM)?","options":{"A":"Using standalone cash registers with no connection to warehouse computers","B":"Hiring external consultants to inspect finished products manually","C":"Replacing all computers with manual job production","D":"Linking Computer-Aided Design (CAD) directly with Computer-Aided Manufacturing (CAM) into a single seamless automated system"},"correctOption":"D","correctAnswer":"Linking Computer-Aided Design (CAD) directly with Computer-Aided Manufacturing (CAM) into a single seamless automated system","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because CIM integrates digital design, production planning, and automated manufacturing machinery into one connected computer network.","distractor_reasons":{"A":"Incorrect because disconnected registers lack integration.","B":"Incorrect because manual inspection is traditional quality control.","C":"Incorrect because CIM maximizes digital integration rather than reverting to manual craft work.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_529","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_529","question":"How does '3D printing' (additive manufacturing) create physical objects?","options":{"A":"By building up three-dimensional objects layer by layer directly from a digital CAD file","B":"By melting large blocks of iron ore in blast furnaces","C":"By scanning product barcodes at retail checkouts","D":"By sewing cotton fabric rolls together using manual pedal machines"},"correctOption":"A","correctAnswer":"By building up three-dimensional objects layer by layer directly from a digital CAD file","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 3D printers deposit material in thin successive layers guided by a 3D digital model, making prototypes and customized shapes quickly.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because blast furnaces are used in traditional heavy steel smelting.","C":"Incorrect because barcode scanning is EPOS technology.","D":"Incorrect because manual sewing is traditional textile work."}}},{"id":"P1_U4_MCQ_530","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_530","question":"What is a major operational benefit of using industrial 'robotics' on an assembly line?","options":{"A":"Robots never require electricity or software programming","B":"Robots can perform repetitive, heavy, or hazardous tasks continuously with high accuracy and zero fatigue","C":"Robots cost nothing to purchase or install","D":"Robots can invent new marketing slogans independently"},"correctOption":"B","correctAnswer":"Robots can perform repetitive, heavy, or hazardous tasks continuously with high accuracy and zero fatigue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because industrial robots operate 24/7 in dangerous or repetitive environments while maintaining uniform precision.","distractor_reasons":{"A":"Incorrect because robots require electrical power and skilled programming.","B":"Correct selection.","C":"Incorrect because robotics requires heavy initial capital expenditure.","D":"Incorrect because factory robots perform physical tasks such as welding, painting, and lifting."}}},{"id":"P1_U4_MCQ_531","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_531","question":"What is the primary operational function of an 'Electronic Point of Sale' (EPOS) system in retail?","options":{"A":"To design 3D packaging models for manufacturers","B":"To manufacture plastic bags automatically behind the counter","C":"To scan product barcodes at checkouts, calculate customer bills, and automatically update inventory records in real time","D":"To replace delivery lorries with automated drones"},"correctOption":"C","correctAnswer":"To scan product barcodes at checkouts, calculate customer bills, and automatically update inventory records in real time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because EPOS captures exact sales data at the till and links directly to stock-control systems to trigger timely reorders.","distractor_reasons":{"A":"Incorrect because 3D design is performed by CAD software.","B":"Incorrect because EPOS is a retail sales and stock-tracking system.","C":"Correct selection.","D":"Incorrect because physical goods still require transport to stores."}}},{"id":"P1_U4_MCQ_532","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_532","question":"What is meant by 'EFTPOS' (Electronic Funds Transfer at Point of Sale)?","options":{"A":"A software tool used to test aerodynamics of aircraft wings","B":"A warehouse robot that lifts heavy pallets onto shelves","C":"A tax levied by governments on imported electronic goods","D":"A payment system allowing customers to pay for goods electronically using debit/credit cards or mobile devices at the checkout"},"correctOption":"D","correctAnswer":"A payment system allowing customers to pay for goods electronically using debit/credit cards or mobile devices at the checkout","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because EFTPOS transfers funds electronically from the customer's bank account to the retailer's account at the point of purchase.","distractor_reasons":{"A":"Incorrect because aerodynamic testing is a CAD simulation function.","B":"Incorrect because warehouse lifting is automated material handling.","C":"Incorrect because import taxes are customs tariffs.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_533","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_533","question":"How does 'Radio Frequency Identification' (RFID) improve inventory and supply-chain operations?","options":{"A":"Small electronic tags transmit wireless data so hundreds of items can be tracked and scanned simultaneously without direct line-of-sight","B":"RFID tags physically transport boxes between warehouses without trucks","C":"RFID eliminates the need for any computer database","D":"RFID tags manufacture raw materials inside shipping containers"},"correctOption":"A","correctAnswer":"Small electronic tags transmit wireless data so hundreds of items can be tracked and scanned simultaneously without direct line-of-sight","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because RFID uses radio waves to identify and locate tagged pallets or products rapidly, reducing stocktaking time and shipping errors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because physical transport vehicles are still required.","C":"Incorrect because RFID readers feed data directly into computer inventory databases.","D":"Incorrect because RFID is a tracking technology rather than a manufacturing process."}}},{"id":"P1_U4_MCQ_534","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_534","question":"How is 'Artificial Intelligence' (AI) commonly used to improve operations management?","options":{"A":"By physically replacing delivery vans and cargo ships","B":"By analysing large datasets to forecast customer demand accurately, optimize delivery routes, and predict machine maintenance needs","C":"By eliminating the need for electricity in factories","D":"By guaranteeing zero competition in every industry"},"correctOption":"B","correctAnswer":"By analysing large datasets to forecast customer demand accurately, optimize delivery routes, and predict machine maintenance needs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because AI algorithms detect patterns in sales and sensor data to prevent overproduction, avoid breakdowns, and streamline logistics.","distractor_reasons":{"A":"Incorrect because AI is software and still relies on physical vehicles for freight.","B":"Correct selection.","C":"Incorrect because AI data centres and factories consume electrical power.","D":"Incorrect because AI improves operational efficiency rather than creating a legal monopoly."}}},{"id":"P1_U4_MCQ_535","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_535","question":"How does introducing modern production technology typically affect labour productivity and average unit costs at high output levels?","options":{"A":"Labour productivity falls and average unit costs rise","B":"Both labour productivity and average unit costs remain completely unchanged","C":"Labour productivity rises significantly and average unit costs fall as high output spreads fixed machinery costs","D":"Labour productivity falls to zero while variable material costs disappear"},"correctOption":"C","correctAnswer":"Labour productivity rises significantly and average unit costs fall as high output spreads fixed machinery costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because automation allows fewer workers to produce much higher output, lowering average labour and unit costs at scale.","distractor_reasons":{"A":"Incorrect because technology increases output per worker and lowers unit cost at high volume.","B":"Incorrect because new technology transforms output rates and cost structures.","C":"Correct selection.","D":"Incorrect because productivity rises and raw materials are still consumed."}}},{"id":"P1_U4_MCQ_536","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_536","question":"Why does automated production technology often improve product quality?","options":{"A":"Because machines never require raw materials to make products","B":"Because automated lines eliminate all customer expectations","C":"Because machines can guess customer preferences without any programming","D":"Because computer-controlled machines repeat tasks to exact tolerances without human fatigue or measurement errors"},"correctOption":"D","correctAnswer":"Because computer-controlled machines repeat tasks to exact tolerances without human fatigue or measurement errors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because automated precision reduces human variation, leading to uniform quality and fewer defective units.","distractor_reasons":{"A":"Incorrect because raw materials are still needed in automated factories.","B":"Incorrect because customers still demand high quality standards.","C":"Incorrect because machines operate according to programmed instructions and data.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_537","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_537","question":"What is a major financial disadvantage of investing in advanced production technology?","options":{"A":"High upfront capital expenditure and fixed loan interest/depreciation costs, which raise the break-even output","B":"Higher variable direct labour wages per unit produced","C":"Slower production speeds compared with manual hand tools","D":"Inability to operate machines outside standard daytime office hours"},"correctOption":"A","correctAnswer":"High upfront capital expenditure and fixed loan interest/depreciation costs, which raise the break-even output","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because expensive automation increases fixed overhead costs, making the business vulnerable if sales fall below break-even.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because automation typically reduces direct variable labour cost per unit.","C":"Incorrect because automated technology increases rather than slows production speeds.","D":"Incorrect because automated machinery can run 24 hours a day."}}},{"id":"P1_U4_MCQ_538","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_538","question":"How does the introduction of automation and IT typically change the skill requirements of a business's workforce?","options":{"A":"It increases demand for unskilled manual workers and eliminates all technical jobs","B":"It reduces demand for routine, low-skilled manual labour while increasing demand for skilled IT, engineering, and maintenance staff","C":"It eliminates the need for any staff training or education","D":"It ensures every unskilled worker automatically becomes a senior director"},"correctOption":"B","correctAnswer":"It reduces demand for routine, low-skilled manual labour while increasing demand for skilled IT, engineering, and maintenance staff","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because machines replace repetitive manual tasks while creating roles for technicians who program, monitor, and repair equipment.","distractor_reasons":{"A":"Incorrect because the shift moves away from routine manual roles toward technical roles.","B":"Correct selection.","C":"Incorrect because new technology requires ongoing employee training and upskilling.","D":"Incorrect because technological change often causes redundancies unless workers are retrained."}}},{"id":"P1_U4_MCQ_539","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_539","question":"What is a positive impact of workplace technology and robotics on employees?","options":{"A":"Increased exposure to toxic chemicals and heavy physical lifting","B":"Complete elimination of rest breaks during shifts","C":"Improved health and safety as robots handle dangerous tasks, alongside opportunities to retrain into higher-paid technical roles","D":"Guaranteed lifetime employment without ever needing to learn new skills"},"correctOption":"C","correctAnswer":"Improved health and safety as robots handle dangerous tasks, alongside opportunities to retrain into higher-paid technical roles","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because automating hazardous or strenuous tasks reduces workplace injuries and enables workers to upskill.","distractor_reasons":{"A":"Incorrect because robots remove humans from toxic or heavy-lifting environments.","B":"Incorrect because employment laws still protect worker rest breaks.","C":"Correct selection.","D":"Incorrect because technology requires continuous learning and adaptation."}}},{"id":"P1_U4_MCQ_540","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_540","question":"Which of the following is a negative impact of new workplace technology on employees?","options":{"A":"Higher physical injury rates from operating safer automated equipment","B":"Excessive freedom from any management supervision","C":"Elimination of all financial bonuses and pay rises","D":"Technological redundancy for displaced staff, job insecurity, and stress from constant digital performance monitoring"},"correctOption":"D","correctAnswer":"Technological redundancy for displaced staff, job insecurity, and stress from constant digital performance monitoring","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because automation can lead to job losses for routine workers and intrusive software tracking can lower morale.","distractor_reasons":{"A":"Incorrect because automation generally reduces physical injury rates.","B":"Incorrect because digital systems often increase rather than reduce performance monitoring.","C":"Incorrect because businesses still offer bonuses and pay rises to skilled staff.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_541","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_541","question":"How do modern technologies such as e-commerce, mobile apps, and CAD/CAM benefit customers?","options":{"A":"Greater convenience with 24/7 ordering, faster delivery tracking, better product quality, and mass-customized options","B":"Restricted shopping hours limited strictly to weekday mornings","C":"Higher prices caused by inefficient manual production","D":"Slower checkout queues and fewer payment choices"},"correctOption":"A","correctAnswer":"Greater convenience with 24/7 ordering, faster delivery tracking, better product quality, and mass-customized options","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because digital platforms and automated production enhance convenience, speed, reliability, and product choice for consumers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because online platforms enable 24/7 access rather than restricted hours.","C":"Incorrect because efficient technology tends to improve quality and keep prices competitive.","D":"Incorrect because contactless EFTPOS and self-checkouts speed up payments."}}},{"id":"P1_U4_MCQ_542","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_542","question":"What is a potential disadvantage of service-sector automation (such as chatbots and app-only services) for customers?","options":{"A":"Customers receive instant answers 24 hours a day","B":"Loss of personal human interaction and exclusion of older or non-digital customers who lack smartphones or internet access","C":"Lower prices resulting from reduced branch staffing costs","D":"Greater accuracy in digital order transmission to kitchens"},"correctOption":"B","correctAnswer":"Loss of personal human interaction and exclusion of older or non-digital customers who lack smartphones or internet access","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because replacing human staff entirely with self-service tech can frustrate customers seeking personal help or lacking digital devices.","distractor_reasons":{"A":"Incorrect because 24/7 instant responses are an advantage of automation, not a disadvantage.","B":"Correct selection.","C":"Incorrect because lower prices are a consumer benefit rather than a drawback.","D":"Incorrect because higher order accuracy is a benefit of digital ordering."}}},{"id":"P1_U4_MCQ_543","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_543","question":"What is meant by 'sustainable production of goods and services'?","options":{"A":"Maximizing short-term output regardless of pollution or resource exhaustion","B":"Using only non-renewable fossil fuels to keep energy bills low","C":"Producing goods and services in ways that meet present needs while minimizing environmental damage and conserving resources for future generations","D":"Designing products to wear out quickly so customers buy replacements frequently"},"correctOption":"C","correctAnswer":"Producing goods and services in ways that meet present needs while minimizing environmental damage and conserving resources for future generations","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sustainable production balances economic activity with environmental stewardship and long-term resource conservation.","distractor_reasons":{"A":"Incorrect because ignoring pollution and depletion is unsustainable.","B":"Incorrect because relying on finite fossil fuels accelerates resource depletion and climate harm.","C":"Correct selection.","D":"Incorrect because planned obsolescence generates excessive waste and contradicts sustainability."}}},{"id":"P1_U4_MCQ_544","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_544","question":"Which of the following is a 'renewable energy source' used in sustainable production?","options":{"A":"Coal-fired steam power","B":"Natural gas turbines","C":"Diesel-powered generators","D":"Solar photovoltaic panels and wind turbines"},"correctOption":"D","correctAnswer":"Solar photovoltaic panels and wind turbines","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because sunlight and wind are naturally replenished energy flows that do not run out or emit greenhouse gases during generation.","distractor_reasons":{"A":"Incorrect because coal is a finite, high-emission fossil fuel.","B":"Incorrect because natural gas is a finite non-renewable fossil fuel.","C":"Incorrect because diesel is refined from finite crude oil.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_545","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_545","question":"Why is the heavy use of 'non-renewable resources' (such as crude oil, coal, and rare minerals) a concern for sustainable production?","options":{"A":"Their supply is finite and will eventually run out, and extracting or burning them often causes severe pollution and carbon emissions","B":"They replenish themselves automatically overnight","C":"They emit zero carbon dioxide when burned in power stations","D":"They can be created out of thin air at zero cost"},"correctOption":"A","correctAnswer":"Their supply is finite and will eventually run out, and extracting or burning them often causes severe pollution and carbon emissions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because non-renewable resources take millions of years to form, meaning rapid extraction depletes reserves for future generations and harms ecosystems.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because finite fossil fuels and minerals do not replenish on human timescales.","C":"Incorrect because burning fossil fuels releases large amounts of carbon dioxide.","D":"Incorrect because mining and drilling require costly extraction and finite reserves."}}},{"id":"P1_U4_MCQ_546","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_546","question":"How does 'reusing' differ from 'recycling' in sustainable operations?","options":{"A":"Reusing melts materials down into new products, whereas recycling uses items again without alteration","B":"Reusing uses an intact item again for the same or another purpose without reprocessing, whereas recycling breaks waste materials down to make new products","C":"Reusing applies only to toxic chemicals, whereas recycling applies only to food","D":"There is no difference between reusing and recycling"},"correctOption":"B","correctAnswer":"Reusing uses an intact item again for the same or another purpose without reprocessing, whereas recycling breaks waste materials down to make new products","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because reusing keeps the existing item intact (e.g., refilling glass bottles or returnable crates), while recycling reprocesses waste material into new goods.","distractor_reasons":{"A":"Incorrect because the definitions of reusing and recycling are reversed.","B":"Correct selection.","C":"Incorrect because both practices apply widely to glass, plastics, metals, wood, and textiles.","D":"Incorrect because reusing requires far less energy than melting or reprocessing materials in recycling."}}},{"id":"P1_U4_MCQ_547","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_547","question":"Which action best illustrates 'recycling' in manufacturing?","options":{"A":"Washing and refilling intact glass milk bottles","B":"Sending all factory off-cuts directly to a landfill site","C":"Collecting scrap aluminium cans, melting them down, and rolling the metal into new cans","D":"Burning coal to power assembly-line machinery"},"correctOption":"C","correctAnswer":"Collecting scrap aluminium cans, melting them down, and rolling the metal into new cans","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because melting scrap aluminium to produce new metal sheets reprocesses waste material into fresh raw input.","distractor_reasons":{"A":"Incorrect because washing and refilling intact bottles is reusing rather than recycling.","B":"Incorrect because landfilling is waste disposal rather than recycling.","C":"Correct selection.","D":"Incorrect because burning coal is non-renewable energy use."}}},{"id":"P1_U4_MCQ_548","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_548","question":"Which practice is an example of 'reusing' in business operations?","options":{"A":"Shredding plastic bottles into polyester yarn for clothing","B":"Smelting old car batteries to extract lead ore","C":"Composting vegetable peelings into garden soil","D":"Using durable returnable plastic crates repeatedly to transport components between supplier and factory"},"correctOption":"D","correctAnswer":"Using durable returnable plastic crates repeatedly to transport components between supplier and factory","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because returnable transit crates are used over and over in their original form without being broken down or remanufactured.","distractor_reasons":{"A":"Incorrect because shredding and melting plastic into yarn is recycling.","B":"Incorrect because smelting batteries to recover lead is recycling.","C":"Incorrect because biological decomposition into soil is composting/biodegradation.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_549","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_549","question":"What is meant by 'using fewer natural resources' in sustainable product design?","options":{"A":"Redesigning products and processes to require smaller quantities of virgin raw materials, water, and energy per unit","B":"Increasing the thickness and weight of single-use plastic packaging","C":"Leaving taps and factory machines running overnight when unused","D":"Replacing renewable timber with finite mined plastics"},"correctOption":"A","correctAnswer":"Redesigning products and processes to require smaller quantities of virgin raw materials, water, and energy per unit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because resource efficiency reduces raw material extraction, water consumption, and energy intensity for every good produced.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because heavier packaging increases resource consumption.","C":"Incorrect because wasting water and electricity increases resource depletion.","D":"Incorrect because switching from renewable timber to fossil-fuel plastics harms sustainability."}}},{"id":"P1_U4_MCQ_550","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_550","question":"How does 'waste minimization' contribute to both sustainability and business profitability?","options":{"A":"It increases landfill dumping fees while wasting raw materials","B":"It reduces raw material purchases and waste disposal costs while lowering environmental pollution","C":"It forces businesses to overproduce unsold inventory","D":"It eliminates the need for quality assurance checks"},"correctOption":"B","correctAnswer":"It reduces raw material purchases and waste disposal costs while lowering environmental pollution","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because generating less scrap and off-cuts directly saves input and disposal expenses while reducing landfill and emissions.","distractor_reasons":{"A":"Incorrect because waste minimization lowers rather than increases landfill fees.","B":"Correct selection.","C":"Incorrect because overproduction creates waste rather than minimizing it.","D":"Incorrect because quality assurance helps achieve waste minimization by preventing defects."}}},{"id":"P1_U4_MCQ_551","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_551","question":"Which characteristic defines 'environmentally friendly packaging'?","options":{"A":"Multiple layers of non-recyclable polystyrene foam and PVC shrink-wrap","B":"Oversized cardboard boxes filled with single-use plastic air pillows","C":"Minimalist packaging made from recycled, recyclable, or biodegradable materials printed with non-toxic inks","D":"Packaging designed to persist in oceans for thousands of years"},"correctOption":"C","correctAnswer":"Minimalist packaging made from recycled, recyclable, or biodegradable materials printed with non-toxic inks","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because eco-friendly packaging minimizes material volume and uses inputs that can be safely recycled or composted without pollution.","distractor_reasons":{"A":"Incorrect because polystyrene and PVC create persistent non-recyclable landfill waste.","B":"Incorrect because oversized packaging with plastic air pillows wastes materials and transport space.","C":"Correct selection.","D":"Incorrect because persistent marine waste harms wildlife and ecosystems."}}},{"id":"P1_U4_MCQ_552","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_552","question":"Which feature makes a physical product more 'environmentally friendly' over its lifecycle?","options":{"A":"Gluing components shut so batteries and screens can never be repaired or replaced","B":"Using toxic heavy metals that cannot be safely disposed of","C":"High electricity consumption when switched on","D":"Modular design for easy repair, energy-efficient operation, and biodegradable or recyclable components"},"correctOption":"D","correctAnswer":"Modular design for easy repair, energy-efficient operation, and biodegradable or recyclable components","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because eco-designed products last longer through repairability, consume less energy in use, and can be safely recovered at end-of-life.","distractor_reasons":{"A":"Incorrect because unrepairable designs force premature disposal and increase electronic waste.","B":"Incorrect because toxic metals cause environmental contamination.","C":"Incorrect because high energy use increases carbon emissions.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_553","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_553","question":"What is a major marketing and brand benefit of adopting genuine sustainable production methods?","options":{"A":"Enhanced brand image and customer loyalty, attracting eco-conscious buyers willing to pay a premium price","B":"Legal exemption from paying employee wages or corporate taxes","C":"Guaranteed zero competition in the marketplace","D":"Elimination of the need to advertise or promote products"},"correctOption":"A","correctAnswer":"Enhanced brand image and customer loyalty, attracting eco-conscious buyers willing to pay a premium price","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because strong environmental credentials differentiate a business positively, strengthening reputation and supporting sales growth.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sustainable businesses must still pay wages and taxes.","C":"Incorrect because competitors remain free to compete in the market.","D":"Incorrect because businesses still communicate their sustainability efforts through marketing."}}},{"id":"P1_U4_MCQ_554","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_554","question":"How can sustainable production methods improve a business's long-term financial performance?","options":{"A":"By permanently increasing monthly electricity and landfill disposal bills","B":"By lowering ongoing energy, water, raw material, and waste-disposal expenses once initial investments are paid back","C":"By eliminating all upfront capital expenditure on green equipment","D":"By reducing product quality so goods break faster"},"correctOption":"B","correctAnswer":"By lowering ongoing energy, water, raw material, and waste-disposal expenses once initial investments are paid back","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because energy efficiency, renewable power, and waste reduction reduce recurring operating costs over the long run.","distractor_reasons":{"A":"Incorrect because sustainable efficiency lowers rather than raises utility and disposal bills.","B":"Correct selection.","C":"Incorrect because green technologies usually involve high upfront capital costs.","D":"Incorrect because sustainable products emphasize durability and quality."}}},{"id":"P1_U4_MCQ_555","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_555","question":"How does adopting sustainable production help a business manage legal and regulatory risks?","options":{"A":"It allows factories to ignore workplace health and safety laws","B":"It exempts the business from consumer protection legislation","C":"It ensures compliance with tightening environmental laws, avoiding heavy pollution fines, carbon taxes, and forced closures","D":"It gives the business legal authority to fine its competitors"},"correctOption":"C","correctAnswer":"It ensures compliance with tightening environmental laws, avoiding heavy pollution fines, carbon taxes, and forced closures","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because proactive environmental compliance protects firms from regulatory penalties, carbon levies, and reputational crises.","distractor_reasons":{"A":"Incorrect because health and safety laws remain strictly enforceable.","B":"Incorrect because consumer laws apply to all businesses.","C":"Correct selection.","D":"Incorrect because only government regulators have legal enforcement powers."}}},{"id":"P1_U4_MCQ_556","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_556","question":"Besides customers, which two stakeholder groups are positively influenced when a business commits to sustainable production?","options":{"A":"Illegal waste dumpers and coal-mining monopolies","B":"Competitors wishing to undercut prices using dirty fuels","C":"Tax authorities looking to increase pollution fines","D":"Motivated employees who take pride in ethical employers and ethical investment funds seeking responsible businesses"},"correctOption":"D","correctAnswer":"Motivated employees who take pride in ethical employers and ethical investment funds seeking responsible businesses","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because strong environmental values help attract and retain talented staff and unlock finance from sustainability-focused investors.","distractor_reasons":{"A":"Incorrect because sustainable firms avoid illegal waste disposal and fossil fuels.","B":"Incorrect because rivals are not positively supported by a firm's sustainability.","C":"Incorrect because sustainable firms minimize pollution fines rather than paying more.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_557","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_557","question":"What is a major short-term financial challenge of switching to sustainable production methods?","options":{"A":"High upfront capital expenditure for renewable energy systems, clean machinery, and research & development can strain cash flow","B":"Immediate elimination of all fixed overhead costs","C":"Guaranteed overnight doubling of net profit in Week 1","D":"Lower customer awareness of environmental issues"},"correctOption":"A","correctAnswer":"High upfront capital expenditure for renewable energy systems, clean machinery, and research & development can strain cash flow","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because green technologies often require large initial investments that take several years to pay back.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because upfront capital spending increases depreciation and financing fixed costs.","C":"Incorrect because high initial outlays usually weigh on short-term cash flow before long-term savings materialize.","D":"Incorrect because consumer awareness of sustainability is rising rather than falling."}}},{"id":"P1_U4_MCQ_558","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_558","question":"Why might switching to eco-friendly raw materials and packaging create a competitive challenge for a business?","options":{"A":"Sustainable materials are always completely free","B":"Sustainable materials often cost more per unit, forcing the business either to accept lower profit margins or raise prices and risk losing price-sensitive customers","C":"Customers boycott businesses that use recyclable packaging","D":"Governments ban businesses from using biodegradable packaging"},"correctOption":"B","correctAnswer":"Sustainable materials often cost more per unit, forcing the business either to accept lower profit margins or raise prices and risk losing price-sensitive customers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher variable costs for certified or biodegradable inputs can squeeze margins or reduce price competitiveness against non-sustainable rivals.","distractor_reasons":{"A":"Incorrect because sustainable inputs typically cost more than conventional alternatives.","B":"Correct selection.","C":"Incorrect because consumers generally favour recyclable packaging unless prices rise too sharply.","D":"Incorrect because governments encourage rather than ban biodegradable packaging."}}},{"id":"P1_U4_MCQ_559","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_559","question":"What supply-chain difficulty can arise when a manufacturer commits to using only certified sustainable raw materials?","options":{"A":"Unlimited instant supply of certified inputs at zero transport cost","B":"Complete elimination of supplier lead times","C":"Limited availability of certified sustainable suppliers can cause input shortages, higher prices, or production delays","D":"Certified materials never require quality checks"},"correctOption":"C","correctAnswer":"Limited availability of certified sustainable suppliers can cause input shortages, higher prices, or production delays","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sustainably harvested or audited materials often have smaller global supply volumes than conventional commodities.","distractor_reasons":{"A":"Incorrect because certified inputs are often scarcer and costlier to source.","B":"Incorrect because sourcing from approved suppliers can lengthen lead times.","C":"Correct selection.","D":"Incorrect because all incoming inputs still require quality assurance checks."}}},{"id":"P1_U4_MCQ_560","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_560","question":"What operational problem can occur when replacing conventional plastics with biodegradable packaging substitutes?","options":{"A":"Biodegradable packaging lasts forever in landfill without breaking down","B":"Biodegradable substitutes always double factory machine speeds","C":"Biodegradable packaging eliminates the need for product labels","D":"Eco-friendly substitutes may be less durable, tear on high-speed packing machines, or reduce product shelf life"},"correctOption":"D","correctAnswer":"Eco-friendly substitutes may be less durable, tear on high-speed packing machines, or reduce product shelf life","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because bio-based materials can have lower moisture resistance or tensile strength, requiring machine adjustments or risking spoilage.","distractor_reasons":{"A":"Incorrect because biodegradable materials are designed to decompose naturally.","B":"Incorrect because fragile bio-films may require slowing down packing machines.","C":"Incorrect because products still require statutory ingredient and brand labels.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_561","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_561","question":"What is meant by 'greenwashing', and why is it dangerous for a business?","options":{"A":"Making misleading or exaggerated claims about environmental sustainability; when exposed, it destroys consumer trust and risks regulatory fines","B":"Cleaning factory machinery with biodegradable plant-based soaps","C":"Investing 100% of company profits into solar and wind farms","D":"Recycling greywater to wash delivery lorries"},"correctOption":"A","correctAnswer":"Making misleading or exaggerated claims about environmental sustainability; when exposed, it destroys consumer trust and risks regulatory fines","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because greenwashing deceives stakeholders with false eco-claims, leading to severe reputational backlash and legal sanctions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because using biodegradable cleaning products is a genuine eco-friendly practice.","C":"Incorrect because investing in renewable energy is authentic sustainability.","D":"Incorrect because water recycling is a genuine sustainable operation."}}},{"id":"P1_U4_MCQ_562","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_562","question":"Why do governments provide grants, subsidies, and tax credits to businesses adopting renewable energy and clean technology?","options":{"A":"To encourage businesses to burn more coal and crude oil","B":"To lower the high upfront capital cost barrier so more firms transition to environmentally sustainable production","C":"To increase commercial waste sent to landfill sites","D":"To reduce competition by bankrupting small businesses"},"correctOption":"B","correctAnswer":"To lower the high upfront capital cost barrier so more firms transition to environmentally sustainable production","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because financial support helps businesses overcome initial investment hurdles and accelerates national emission reductions.","distractor_reasons":{"A":"Incorrect because subsidies aim to replace fossil fuels with clean energy.","B":"Correct selection.","C":"Incorrect because governments aim to reduce landfill waste.","D":"Incorrect because grants financially assist businesses with capital purchases."}}},{"id":"P1_U4_MCQ_563","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_563","question":"How do government 'carbon taxes' and 'landfill taxes' influence business operations?","options":{"A":"They reward businesses that emit the highest levels of greenhouse gases","B":"They eliminate all costs associated with waste disposal","C":"They increase the financial cost of polluting and dumping waste, creating a strong incentive to adopt cleaner, low-waste production","D":"They apply only to businesses that use 100% renewable solar power"},"correctOption":"C","correctAnswer":"They increase the financial cost of polluting and dumping waste, creating a strong incentive to adopt cleaner, low-waste production","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because environmental taxes internalize pollution costs, making energy efficiency and waste reduction financially attractive.","distractor_reasons":{"A":"Incorrect because carbon taxes penalize rather than reward emissions.","B":"Incorrect because landfill taxes raise the cost of dumping waste.","C":"Correct selection.","D":"Incorrect because 100% solar-powered firms pay zero carbon tax on electricity."}}},{"id":"P1_U4_MCQ_564","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_564","question":"What is meant by 'fixed costs' (overheads)?","options":{"A":"Costs that rise and fall directly in proportion to the volume of output produced","B":"The cost of raw materials used in each individual unit","C":"Costs that equal zero whenever the factory closes for the weekend","D":"Costs that do not change with the level of output produced in the short run"},"correctOption":"D","correctAnswer":"Costs that do not change with the level of output produced in the short run","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because fixed costs remain constant regardless of output volume within existing capacity (e.g., rent, insurance, salaried management).","distractor_reasons":{"A":"Incorrect because costs that vary directly with output volume are variable costs.","B":"Incorrect because raw materials per unit are variable costs.","C":"Incorrect because fixed costs must still be paid even when output is zero.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_565","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_565","question":"Which of the following is an example of a 'fixed cost' for a manufacturing business?","options":{"A":"Annual factory building rent and business property insurance","B":"Direct raw materials such as steel sheets and plastic pellets","C":"Piece-rate wages paid per unit assembled by workers","D":"Cardboard packaging boxes used for each finished item shipped"},"correctOption":"A","correctAnswer":"Annual factory building rent and business property insurance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because building rent and property insurance do not vary with the number of items manufactured each month.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raw material usage rises directly with output, making it a variable cost.","C":"Incorrect because piece-rate pay varies directly with units produced, making it a variable cost.","D":"Incorrect because packaging box usage varies directly with units shipped, making it a variable cost."}}},{"id":"P1_U4_MCQ_566","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_566","question":"What is meant by 'variable costs'?","options":{"A":"Costs that remain completely unchanged regardless of how many units are produced","B":"Costs that change directly in proportion to the level of output produced","C":"Annual interest payments on a fixed-rate bank mortgage","D":"The fixed monthly salary of the chief executive officer"},"correctOption":"B","correctAnswer":"Costs that change directly in proportion to the level of output produced","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because variable costs increase as output rises and fall to zero when output is zero.","distractor_reasons":{"A":"Incorrect because costs unchanged by output are fixed costs.","B":"Correct selection.","C":"Incorrect because fixed-rate mortgage interest is a fixed cost.","D":"Incorrect because executive salaries are fixed overheads."}}},{"id":"P1_U4_MCQ_567","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_567","question":"Which of the following is an example of a 'variable cost' for a restaurant?","options":{"A":"Monthly lease rent for the restaurant premises","B":"Annual public liability insurance premium","C":"Fresh food ingredients and takeaway containers used for customer meals","D":"Fixed annual salary of the restaurant general manager"},"correctOption":"C","correctAnswer":"Fresh food ingredients and takeaway containers used for customer meals","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because ingredient and takeaway container costs vary directly with the number of meals prepared and sold.","distractor_reasons":{"A":"Incorrect because monthly lease rent is a fixed cost.","B":"Incorrect because annual insurance is a fixed cost.","C":"Correct selection.","D":"Incorrect because a fixed annual salary is an overhead cost."}}},{"id":"P1_U4_MCQ_568","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_568","question":"How is 'total cost' calculated for any given level of output?","options":{"A":"Total revenue minus total variable costs","B":"Fixed costs divided by total output produced","C":"Selling price minus variable cost per unit","D":"Total fixed costs plus total variable costs"},"correctOption":"D","correctAnswer":"Total fixed costs plus total variable costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because total cost combines all fixed overheads and all variable production costs at that output level.","distractor_reasons":{"A":"Incorrect because total revenue minus total variable costs equals total contribution.","B":"Incorrect because fixed costs divided by output equals average fixed cost.","C":"Incorrect because selling price minus unit variable cost equals unit contribution.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_569","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_569","question":"What is meant by 'average cost' (unit cost)?","options":{"A":"Total cost divided by the total number of units produced","B":"Total fixed costs minus total variable costs","C":"Total sales revenue multiplied by output volume","D":"The selling price of a single unit minus profit per unit"},"correctOption":"A","correctAnswer":"Total cost divided by the total number of units produced","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because average cost measures the cost of producing each single unit (Total Cost / Output).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fixed costs and variable costs are added together, never subtracted.","C":"Incorrect because multiplying revenue by output is meaningless.","D":"Incorrect because average cost is determined from production costs and output volume."}}},{"id":"P1_U4_MCQ_570","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_570","question":"What happens to 'average fixed cost' per unit as a business increases its output within existing factory capacity?","options":{"A":"It rises steadily because total fixed costs double with every unit","B":"It falls continuously because the constant total fixed cost is spread across a larger number of units","C":"It stays completely unchanged at every output level","D":"It immediately becomes negative once break-even is reached"},"correctOption":"B","correctAnswer":"It falls continuously because the constant total fixed cost is spread across a larger number of units","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because total fixed costs remain constant while output rises, reducing the fixed overhead burden carried by each individual unit.","distractor_reasons":{"A":"Incorrect because total fixed costs stay constant rather than doubling.","B":"Correct selection.","C":"Incorrect because total fixed cost stays constant, whereas average fixed cost per unit falls.","D":"Incorrect because average fixed cost remains positive at all positive output levels."}}},{"id":"P1_U4_MCQ_571","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_571","question":"What is meant by 'economies of scale'?","options":{"A":"Increases in average unit costs when a business grows too large and hard to manage","B":"Increases in total fixed costs when a business rents a second warehouse","C":"Reductions in average cost per unit achieved as a business expands its scale of production","D":"Reductions in total output caused by machine breakdowns"},"correctOption":"C","correctAnswer":"Reductions in average cost per unit achieved as a business expands its scale of production","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because economies of scale occur when expanding output lowers the average cost of producing each unit.","distractor_reasons":{"A":"Incorrect because rising average costs from excessive growth define diseconomies of scale.","B":"Incorrect because total costs always rise with expansion; economies of scale refer to falling average unit cost.","C":"Correct selection.","D":"Incorrect because machine breakdowns reduce efficiency and raise unit costs."}}},{"id":"P1_U4_MCQ_572","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_572","question":"What is meant by 'purchasing economies of scale'?","options":{"A":"Borrowing money from banks at lower interest rates than small firms","B":"Spreading television advertising budgets over millions of product sales","C":"Employing specialist managers for finance, marketing, and HR","D":"Obtaining bulk-buying discounts from suppliers when ordering raw materials and components in large quantities"},"correctOption":"D","correctAnswer":"Obtaining bulk-buying discounts from suppliers when ordering raw materials and components in large quantities","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because suppliers offer lower unit prices on large bulk orders due to lower packing, transport, and administrative costs per unit.","distractor_reasons":{"A":"Incorrect because lower interest rates on loans define financial economies of scale.","B":"Incorrect because spreading advertising costs defines marketing economies of scale.","C":"Incorrect because employing specialist managers defines managerial economies of scale.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_573","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_573","question":"What is meant by 'technical economies of scale'?","options":{"A":"Using large-scale, high-capacity specialist machinery and automated flow lines that operate efficiently only at high output volumes","B":"Receiving bulk discounts when buying stationery supplies","C":"Issuing shares on a stock exchange at lower administrative cost","D":"Hiring specialist legal advisors to negotiate contracts"},"correctOption":"A","correctAnswer":"Using large-scale, high-capacity specialist machinery and automated flow lines that operate efficiently only at high output volumes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because large firms can afford indivisible, high-speed machinery and run it at full capacity, lowering unit production costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because bulk discounts on supplies are purchasing economies of scale.","C":"Incorrect because raising share capital cheaply is a financial economy of scale.","D":"Incorrect because hiring specialist staff is a managerial economy of scale."}}},{"id":"P1_U4_MCQ_574","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_574","question":"What is meant by 'financial economies of scale'?","options":{"A":"Paying lower electricity tariffs by operating factories at night","B":"Larger businesses accessing wider sources of finance and borrowing at lower interest rates because lenders view them as lower risk","C":"Using giant articulated lorries to lower delivery cost per box","D":"Buying raw cotton in bulk at discounted prices"},"correctOption":"B","correctAnswer":"Larger businesses accessing wider sources of finance and borrowing at lower interest rates because lenders view them as lower risk","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because large, asset-rich firms are considered more creditworthy by banks and capital markets, securing cheaper loans.","distractor_reasons":{"A":"Incorrect because electricity tariffs are utility operating costs rather than financing costs.","B":"Correct selection.","C":"Incorrect because lower unit distribution costs are marketing economies of scale.","D":"Incorrect because bulk material discounts are purchasing economies of scale."}}},{"id":"P1_U4_MCQ_575","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_575","question":"What is meant by 'managerial economies of scale'?","options":{"A":"Operating high-speed robotic welders on an assembly line","B":"Negotiating lower interest rates on long-term bank loans","C":"Affording to employ specialist functional managers (such as finance, IT, and operations directors) who improve efficiency and decision-making","D":"Spreading national TV advertising costs over higher sales volumes"},"correctOption":"C","correctAnswer":"Affording to employ specialist functional managers (such as finance, IT, and operations directors) who improve efficiency and decision-making","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because large organizations can divide management tasks among qualified specialists rather than relying on one generalist owner.","distractor_reasons":{"A":"Incorrect because robotic equipment represents technical economies of scale.","B":"Incorrect because cheaper bank borrowing represents financial economies of scale.","C":"Correct selection.","D":"Incorrect because spreading advertising costs represents marketing economies of scale."}}},{"id":"P1_U4_MCQ_576","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_576","question":"What is meant by 'marketing economies of scale'?","options":{"A":"Buying raw materials in bulk from overseas suppliers","B":"Installing larger industrial ovens in a commercial bakery","C":"Borrowing funds at lower interest rates than smaller rivals","D":"Spreading fixed advertising, promotion, and bulk distribution costs across a larger volume of sales, lowering marketing cost per unit"},"correctOption":"D","correctAnswer":"Spreading fixed advertising, promotion, and bulk distribution costs across a larger volume of sales, lowering marketing cost per unit","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because national ad campaigns and large delivery fleets cost much less per unit sold when spread over high output.","distractor_reasons":{"A":"Incorrect because bulk material buying is a purchasing economy of scale.","B":"Incorrect because large ovens are a technical economy of scale.","C":"Incorrect because cheaper borrowing is a financial economy of scale.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_577","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_577","question":"What is meant by 'diseconomies of scale'?","options":{"A":"Factors that cause average cost per unit to rise when a business expands beyond its optimal size","B":"Factors that cause average cost per unit to fall as a business grows larger","C":"Bulk-buying discounts gained from ordering large quantities of supplies","D":"Lower interest rates charged by banks to large public limited companies"},"correctOption":"A","correctAnswer":"Factors that cause average cost per unit to rise when a business expands beyond its optimal size","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because excessive organizational size leads to management, communication, and motivation problems that push unit costs upward.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because falling unit costs from growth define economies of scale.","C":"Incorrect because bulk-buying discounts are purchasing economies of scale.","D":"Incorrect because lower interest rates are financial economies of scale."}}},{"id":"P1_U4_MCQ_578","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_578","question":"Which of the following is a primary cause of 'diseconomies of scale' in very large organizations?","options":{"A":"Faster face-to-face communication between directors and shop-floor staff","B":"Poor communication across long chains of command, slow bureaucratic decision-making, and low worker morale from feeling alienated","C":"Higher bulk-buying discounts from raw material suppliers","D":"Full utilization of specialist automated machinery"},"correctOption":"B","correctAnswer":"Poor communication across long chains of command, slow bureaucratic decision-making, and low worker morale from feeling alienated","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because tall hierarchies and vast workforces slow down decisions, distort messages, and reduce employee engagement.","distractor_reasons":{"A":"Incorrect because fast face-to-face communication is a strength of small businesses.","B":"Correct selection.","C":"Incorrect because bulk-buying discounts reduce unit costs (economies of scale).","D":"Incorrect because full utilization of specialist machinery reduces unit costs (technical economies)."}}},{"id":"P1_U4_MCQ_579","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_579","question":"What is meant by 'contribution per unit' in break-even analysis?","options":{"A":"Selling price per unit minus fixed cost per unit","B":"Total sales revenue minus total fixed costs","C":"Selling price per unit minus variable cost per unit, showing how much each unit sold contributes toward paying fixed costs and profit","D":"Total variable costs divided by total fixed costs"},"correctOption":"C","correctAnswer":"Selling price per unit minus variable cost per unit, showing how much each unit sold contributes toward paying fixed costs and profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unit contribution (Price - Unit Variable Cost) is the surplus from each sale available to cover fixed overheads first and then generate profit.","distractor_reasons":{"A":"Incorrect because unit contribution subtracts variable cost per unit, not fixed cost per unit.","B":"Incorrect because fixed costs are subtracted from total contribution to find profit.","C":"Correct selection.","D":"Incorrect because dividing variable costs by fixed costs is not a meaningful formula."}}},{"id":"P1_U4_MCQ_580","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_580","question":"What is meant by the 'break-even point' of a business?","options":{"A":"The output level at which the business achieves its maximum possible profit","B":"The output level at which total variable costs equal zero","C":"The output level at which total revenue is double total costs","D":"The level of output and sales at which total revenue equals total costs, so the business makes neither a profit nor a loss"},"correctOption":"D","correctAnswer":"The level of output and sales at which total revenue equals total costs, so the business makes neither a profit nor a loss","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because at break-even, total contribution equals total fixed costs, resulting in zero profit and zero loss.","distractor_reasons":{"A":"Incorrect because profit is zero at the break-even point.","B":"Incorrect because variable costs are positive whenever positive output is produced.","C":"Incorrect because if total revenue were double total costs, the firm would make a large profit.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_581","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_581","question":"What is meant by the 'margin of safety'?","options":{"A":"The amount by which actual or forecast sales exceed the break-even level of output","B":"The extra buffer stock kept inside a warehouse in case of supplier delays","C":"The vertical distance between the fixed cost line and zero on a break-even chart","D":"The amount by which total costs exceed total revenue when making a loss"},"correctOption":"A","correctAnswer":"The amount by which actual or forecast sales exceed the break-even level of output","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the margin of safety (Actual Sales - Break-Even Output) shows how far sales can fall before the business begins making a loss.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because safety stock in a warehouse is buffer inventory rather than break-even margin of safety.","C":"Incorrect because the vertical distance from zero to the fixed cost line represents total fixed costs.","D":"Incorrect because total costs exceeding total revenue measures a financial loss."}}},{"id":"P1_U4_MCQ_582","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_582","question":"Assuming selling price and variable cost per unit remain unchanged, how does an increase in 'fixed costs' affect the break-even point?","options":{"A":"The break-even output decreases because unit contribution rises","B":"The break-even output increases because more units must be sold to cover the higher fixed overheads","C":"The break-even output remains completely unchanged","D":"The margin of safety automatically increases"},"correctOption":"B","correctAnswer":"The break-even output increases because more units must be sold to cover the higher fixed overheads","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Break-Even Output = Fixed Costs / Unit Contribution; a larger numerator raises the required break-even volume.","distractor_reasons":{"A":"Incorrect because higher fixed costs raise rather than lower break-even output, and unit contribution is unaffected.","B":"Correct selection.","C":"Incorrect because fixed costs directly determine break-even output.","D":"Incorrect because a higher break-even point reduces rather than increases the margin of safety."}}},{"id":"P1_U4_MCQ_583","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_583","question":"Assuming fixed costs and variable cost per unit stay constant, how does an increase in 'selling price' affect the break-even point?","options":{"A":"The break-even output increases because customers buy fewer units","B":"The break-even output stays unchanged because fixed costs did not change","C":"The break-even output decreases because contribution per unit increases, so fewer sales are needed to cover fixed costs","D":"The Total Revenue line becomes completely horizontal"},"correctOption":"C","correctAnswer":"The break-even output decreases because contribution per unit increases, so fewer sales are needed to cover fixed costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because raising the selling price increases unit contribution (Price - VC), reducing the number of units required to pay off fixed costs.","distractor_reasons":{"A":"Incorrect because mathematically a higher selling price lowers the break-even threshold.","B":"Incorrect because selling price changes unit contribution, which alters break-even output.","C":"Correct selection.","D":"Incorrect because a higher selling price makes the Total Revenue line slope upward more steeply."}}},{"id":"P1_U4_MCQ_584","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_584","question":"Which of the following is a key limitation (unrealistic assumption) of simple break-even charts?","options":{"A":"They assume fixed costs rise steeply with every unit produced","B":"They cannot be drawn for businesses that produce physical goods","C":"They assume selling price is always zero","D":"They assume all output produced is immediately sold and that costs and revenues always follow straight linear lines"},"correctOption":"D","correctAnswer":"They assume all output produced is immediately sold and that costs and revenues always follow straight linear lines","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because simple break-even models ignore unsold inventory build-up, bulk-buying discounts, overtime pay rates, and price discounts at high volumes.","distractor_reasons":{"A":"Incorrect because break-even charts plot fixed costs as a flat horizontal line.","B":"Incorrect because break-even charts are widely used by manufacturing businesses.","C":"Incorrect because Total Revenue slopes upward based on a positive selling price.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_585","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_585","question":"What is meant by 'quality' in Business Studies?","options":{"A":"A good or service being fit for purpose and consistently meeting or exceeding customer expectations","B":"Using only the most expensive luxury raw materials regardless of customer needs","C":"Charging the highest price in the industry for every product","D":"Producing the largest possible quantity of goods even if many are faulty"},"correctOption":"A","correctAnswer":"A good or service being fit for purpose and consistently meeting or exceeding customer expectations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality means reliability, consistency, and fitness for intended use relative to target customer expectations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because budget goods can still be high quality if they are reliable and fit for purpose.","C":"Incorrect because high price alone does not guarantee reliability or customer satisfaction.","D":"Incorrect because producing faulty items represents poor quality and waste."}}},{"id":"P1_U4_MCQ_586","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_586","question":"What is a major commercial benefit of maintaining consistently high quality?","options":{"A":"Elimination of all raw material and employee wage costs","B":"Strong brand reputation, higher customer loyalty, repeat purchases, and the ability to charge premium prices","C":"Exemption from consumer protection laws and safety regulations","D":"Zero need to train workers or maintain machinery"},"correctOption":"B","correctAnswer":"Strong brand reputation, higher customer loyalty, repeat purchases, and the ability to charge premium prices","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because reliable quality differentiates a business from rivals, builds trust, and supports higher profit margins.","distractor_reasons":{"A":"Incorrect because businesses still pay for materials and staff wages.","B":"Correct selection.","C":"Incorrect because statutory consumer and safety laws apply to all firms.","D":"Incorrect because sustaining high quality requires ongoing training and maintenance."}}},{"id":"P1_U4_MCQ_587","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_587","question":"How does achieving high quality improve operational efficiency and lower unit costs?","options":{"A":"By increasing the number of faulty items thrown into scrap bins","B":"By increasing warranty repairs and customer refunds","C":"By reducing material wastage, reworking time, and costly product recalls","D":"By eliminating all electricity usage in factories"},"correctOption":"C","correctAnswer":"By reducing material wastage, reworking time, and costly product recalls","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because 'getting it right first time' prevents wasted materials, extra repair labour, and expensive after-sales returns.","distractor_reasons":{"A":"Incorrect because high quality reduces rather than increases scrap.","B":"Incorrect because high quality minimizes warranty claims and refunds.","C":"Correct selection.","D":"Incorrect because factories still consume electricity."}}},{"id":"P1_U4_MCQ_588","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_588","question":"Which of the following is an internal operational consequence of poor quality during manufacturing?","options":{"A":"Higher labour productivity and faster order fulfilment","B":"Lower variable raw material costs per sellable unit","C":"Higher employee motivation and pride in work","D":"Higher costs from scrapping ruined items and paying workers extra hours to rework defective goods"},"correctOption":"D","correctAnswer":"Higher costs from scrapping ruined items and paying workers extra hours to rework defective goods","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because defects waste raw materials and consume additional technician time for disassembly and repair, pushing average unit costs up.","distractor_reasons":{"A":"Incorrect because fixing defects slows down output and reduces productivity.","B":"Incorrect because scrapped items waste raw materials, raising material cost per good unit sold.","C":"Incorrect because frequent defects frustrate workers and lower morale.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_589","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_589","question":"What is a severe external market consequence when defective goods reach customers?","options":{"A":"Costly product recalls, warranty compensation, negative word-of-mouth, damaged brand reputation, and lost sales","B":"Increased customer willingness to pay higher prices","C":"Stronger long-term contracts with major retail supermarkets","D":"Lower marketing expenses due to positive media publicity"},"correctOption":"A","correctAnswer":"Costly product recalls, warranty compensation, negative word-of-mouth, damaged brand reputation, and lost sales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because poor quality delivered to buyers triggers refunds, recalls, legal claims, and customers switching to competitors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because dissatisfied buyers refuse to pay premium prices.","C":"Incorrect because retail buyers cancel contracts with unreliable suppliers.","D":"Incorrect because faulty products generate damaging negative publicity."}}},{"id":"P1_U4_MCQ_590","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_590","question":"What is meant by 'quality control'?","options":{"A":"Training every worker to check quality standards at every stage of production","B":"Checking and inspecting finished products (or samples) at the end of the production process to detect defects before dispatch","C":"Holding regular team meetings to suggest continuous layout improvements","D":"Ordering raw materials just in time for assembly"},"correctOption":"B","correctAnswer":"Checking and inspecting finished products (or samples) at the end of the production process to detect defects before dispatch","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because quality control relies on specialist inspectors testing completed outputs before they reach customers.","distractor_reasons":{"A":"Incorrect because stage-by-stage self-checking by all workers defines quality assurance.","B":"Correct selection.","C":"Incorrect because continuous improvement meetings define Kaizen.","D":"Incorrect because synchronized material arrival defines JIT."}}},{"id":"P1_U4_MCQ_591","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_591","question":"What is a key advantage of 'quality control' over quality assurance?","options":{"A":"It prevents defects from ever occurring during earlier stages of production","B":"It eliminates all scrap and reworking waste completely","C":"It is quicker and cheaper to set up because general production workers do not require extensive quality training","D":"It gives every factory worker high personal responsibility for quality"},"correctOption":"C","correctAnswer":"It is quicker and cheaper to set up because general production workers do not require extensive quality training","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because quality control concentrates inspection in a few trained inspectors, avoiding costly company-wide training.","distractor_reasons":{"A":"Incorrect because preventing defects mid-process is an advantage of quality assurance.","B":"Incorrect because quality control finds defects only after resources have already been used.","C":"Correct selection.","D":"Incorrect because separating inspection from production often reduces general worker responsibility."}}},{"id":"P1_U4_MCQ_592","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_592","question":"What is a primary operational disadvantage of relying solely on end-of-line 'quality control'?","options":{"A":"Training costs for all shop-floor workers are excessively high","B":"Production lines stop every five minutes while workers inspect their own tools","C":"Finished goods are never tested before being shipped to customers","D":"Defects are discovered only after materials, labour, and time have already been wasted making faulty products"},"correctOption":"D","correctAnswer":"Defects are discovered only after materials, labour, and time have already been wasted making faulty products","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because end-of-line inspection detects faults too late to prevent scrap and rework costs.","distractor_reasons":{"A":"Incorrect because high workforce training costs are a drawback of quality assurance.","B":"Incorrect because workers do not pause to self-inspect under traditional quality control.","C":"Incorrect because end-of-line inspectors do test finished items.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_593","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_593","question":"How can traditional 'quality control' negatively affect worker motivation and attitudes?","options":{"A":"Production workers may view quality as solely the inspectors' job, leading to carelessness and friction between workers and inspectors","B":"Workers become exhausted from checking every stage of production themselves","C":"Workers receive too much autonomy and decision-making power over quality standards","D":"Inspectors refuse to check any finished products"},"correctOption":"A","correctAnswer":"Production workers may view quality as solely the inspectors' job, leading to carelessness and friction between workers and inspectors","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because separating production from inspection removes personal ownership for quality among assembly workers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because workers checking every stage themselves is a feature of quality assurance, not traditional quality control.","C":"Incorrect because traditional quality control offers low worker autonomy over quality.","D":"Incorrect because inspectors' primary role is checking finished outputs."}}},{"id":"P1_U4_MCQ_594","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_594","question":"What is meant by 'quality assurance'?","options":{"A":"Hiring one inspector to check finished boxes right before loading lorries","B":"Establishing agreed quality standards at every stage of production so all employees prevent defects throughout the process","C":"Offering a lower price on slightly damaged goods","D":"Replacing all human workers with automated 3D printers"},"correctOption":"B","correctAnswer":"Establishing agreed quality standards at every stage of production so all employees prevent defects throughout the process","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because quality assurance builds quality verification into every step—from raw material sourcing to final delivery—to stop faults occurring.","distractor_reasons":{"A":"Incorrect because end-of-line checking defines quality control.","B":"Correct selection.","C":"Incorrect because discounting damaged goods is clearance pricing rather than quality assurance.","D":"Incorrect because 3D printing is a manufacturing technology."}}},{"id":"P1_U4_MCQ_595","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_595","question":"What is a major advantage of 'quality assurance'?","options":{"A":"It requires zero training for production staff","B":"It eliminates the need to audit raw material suppliers","C":"Defects are prevented or caught immediately at each stage, reducing scrap waste, increasing worker motivation, and earning recognized quality accreditation","D":"It allows workers to ignore quality rules when orders are urgent"},"correctOption":"C","correctAnswer":"Defects are prevented or caught immediately at each stage, reducing scrap waste, increasing worker motivation, and earning recognized quality accreditation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because preventing defects early cuts waste costs, empowers staff, and builds customer confidence via standards like ISO.","distractor_reasons":{"A":"Incorrect because quality assurance requires comprehensive employee training.","B":"Incorrect because checking supplier quality is a vital part of quality assurance.","C":"Correct selection.","D":"Incorrect because quality assurance enforces strict adherence to standards at all times."}}},{"id":"P1_U4_MCQ_596","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_596","question":"What is a key disadvantage of introducing 'quality assurance'?","options":{"A":"Higher end-of-line scrappage rates than traditional quality control","B":"Lower product reliability and more customer complaints","C":"Reduced employee involvement in workplace improvements","D":"High upfront costs and time required to train all employees and set up documented stage-by-stage procedures"},"correctOption":"D","correctAnswer":"High upfront costs and time required to train all employees and set up documented stage-by-stage procedures","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because training every staff member and overcoming resistance to new working practices requires significant time and expense.","distractor_reasons":{"A":"Incorrect because quality assurance lowers scrap rates.","B":"Incorrect because quality assurance improves reliability and reduces complaints.","C":"Incorrect because quality assurance increases employee involvement.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_597","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_597","question":"What is the fundamental difference between 'quality control' and 'quality assurance'?","options":{"A":"Quality control focuses on detecting defects in finished items via specialist inspectors, whereas quality assurance focuses on preventing defects at every stage via all staff","B":"Quality control is used only in factories, whereas quality assurance is used only in retail shops","C":"Quality control requires extensive staff training, whereas quality assurance requires no training","D":"Quality control prevents all waste, whereas quality assurance creates high scrap"},"correctOption":"A","correctAnswer":"Quality control focuses on detecting defects in finished items via specialist inspectors, whereas quality assurance focuses on preventing defects at every stage via all staff","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality control is an end-of-line 'detection' system, whereas quality assurance is a whole-process 'prevention' system.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both approaches apply across manufacturing and service businesses.","C":"Incorrect because quality assurance requires far more workforce training than quality control.","D":"Incorrect because quality assurance reduces waste more effectively than quality control."}}},{"id":"P1_U4_MCQ_598","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_598","question":"Why is maintaining consistently high product quality especially important for a business selling premium branded headphones?","options":{"A":"High quality eliminates the need for any marketing or advertising","B":"High quality allows the business to stop checking raw material suppliers","C":"High quality builds customer trust and brand loyalty, supporting repeat purchases and a premium selling price","D":"High quality reduces the price customers are willing to pay"},"correctOption":"C","correctAnswer":"High quality builds customer trust and brand loyalty, supporting repeat purchases and a premium selling price","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because reliable quality meets customer expectations, strengthens brand reputation, and justifies premium pricing.","distractor_reasons":{"A":"Incorrect because marketing remains necessary to communicate product benefits.","B":"Incorrect because maintaining high quality requires ongoing checks on suppliers.","C":"Correct selection.","D":"Incorrect because high quality increases rather than reduces perceived value and willingness to pay."}}},{"id":"P1_U4_MCQ_599","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_599","question":"A bakery introduces quality assurance by setting strict ingredient-weighing standards, oven-temperature checks, and staff hygiene routines at every stage. What is a key benefit of this approach?","options":{"A":"Fewer burnt or misshapen batches are produced, reducing wasted ingredients and customer complaints","B":"The bakery no longer needs to pay employees for training","C":"All inspection and standard-setting costs fall to zero immediately","D":"Finished loaves can be sold without checking ingredient freshness"},"correctOption":"A","correctAnswer":"Fewer burnt or misshapen batches are produced, reducing wasted ingredients and customer complaints","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because preventing errors at each stage cuts scrapped food batches, lowers waste costs, and protects customer satisfaction.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality assurance requires investing in staff training.","C":"Incorrect because setting up quality assurance procedures involves upfront training and monitoring costs.","D":"Incorrect because checking raw ingredient quality is a core part of quality assurance."}}},{"id":"P1_U4_MCQ_600","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_600","question":"What is a common disadvantage for a small manufacturing business when introducing a quality assurance system for the first time?","options":{"A":"Defect rates increase permanently because workers check their own work","B":"Customers prefer buying products made without any quality standards","C":"It prevents the business from checking supplier deliveries","D":"High upfront costs and time are required to train all staff and establish documented quality procedures across every department"},"correctOption":"D","correctAnswer":"High upfront costs and time are required to train all staff and establish documented quality procedures across every department","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because implementing quality assurance requires significant training time, financial investment, and full workforce cooperation.","distractor_reasons":{"A":"Incorrect because quality assurance reduces defect rates over time.","B":"Incorrect because customers value consistent quality standards.","C":"Incorrect because quality assurance actively includes supplier quality checks.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_601","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_601","question":"What is the difference between 'reworking' and 'scrapping' a defective item discovered during inspection?","options":{"A":"Reworking repairs the fault so the item can be sold, whereas scrapping discards the item because it cannot be economically or safely repaired","B":"Reworking throws the item into landfill, whereas scrapping sells it at double price","C":"Reworking applies only to services, whereas scrapping applies only to software","D":"Neither reworking nor scrapping costs the business any money"},"correctOption":"A","correctAnswer":"Reworking repairs the fault so the item can be sold, whereas scrapping discards the item because it cannot be economically or safely repaired","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because firms rework fixable faults when repair cost is less than resale value, and scrap unrepairable items.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the meanings of reworking and scrapping are reversed.","C":"Incorrect because both terms apply primarily to physical manufactured goods.","D":"Incorrect because both reworking (extra labour) and scrapping (wasted materials) increase costs."}}},{"id":"P1_U4_MCQ_602","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_602","question":"Why do manufacturers use 'sample testing' rather than testing 100% of output when conducting destructive quality tests?","options":{"A":"Because testing 100% of output destructively would destroy every item made, leaving nothing to sell","B":"Because destructive testing never damages the product being tested","C":"Because testing a small sample costs more than destroying the entire batch","D":"Because governments ban testing more than one product per year"},"correctOption":"A","correctAnswer":"Because testing 100% of output destructively would destroy every item made, leaving nothing to sell","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because destructive tests (such as crash-testing or breaking-point stress tests) ruin the tested sample to verify batch safety.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because destructive testing deliberately tests items to destruction.","C":"Incorrect because testing a small sample preserves the rest of the batch for sale.","D":"Incorrect because no law caps quality testing."}}},{"id":"P1_U4_MCQ_603","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_603","question":"Which method is commonly used as 'quality control' in a service business such as a retail chain or hotel?","options":{"A":"Weighing steel ingots at the end of a smelting furnace","B":"Using mystery shoppers and post-service customer satisfaction surveys to check whether service standards were met","C":"Running 3D printers overnight to produce plastic prototypes","D":"Smelting scrap aluminium cans into new sheets"},"correctOption":"B","correctAnswer":"Using mystery shoppers and post-service customer satisfaction surveys to check whether service standards were met","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because mystery shoppers and customer feedback evaluate the delivered service experience after or during delivery.","distractor_reasons":{"A":"Incorrect because weighing steel ingots applies to heavy metal manufacturing.","B":"Correct selection.","C":"Incorrect because 3D printing is a manufacturing prototyping tool.","D":"Incorrect because smelting aluminium is industrial recycling."}}},{"id":"P1_U4_MCQ_604","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_604","question":"How can a service business (such as a hospital or airline) implement 'quality assurance'?","options":{"A":"By eliminating all staff training and letting each employee improvise","B":"By waiting for customer complaints before checking safety procedures","C":"By implementing standardized staff training, clear service protocols, and mandatory stage-by-stage checklists before serving customers","D":"By inspecting finished products on a factory conveyor belt"},"correctOption":"C","correctAnswer":"By implementing standardized staff training, clear service protocols, and mandatory stage-by-stage checklists before serving customers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because standardizing training and verifying checklists at every step prevents service failures before they affect passengers or patients.","distractor_reasons":{"A":"Incorrect because lack of training causes inconsistent service quality.","B":"Incorrect because waiting for complaints is reactive rather than preventative quality assurance.","C":"Correct selection.","D":"Incorrect because hospitals and airlines deliver intangible services rather than conveyor-belt goods."}}},{"id":"P1_U4_MCQ_605","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_605","question":"Why is auditing and certifying raw-material suppliers an essential part of 'quality assurance'?","options":{"A":"Because defective incoming materials or components will cause finished products to fail even if internal factory processes are accurate","B":"Because certified suppliers provide raw materials completely free of charge","C":"Because auditing suppliers eliminates the need for any internal staff training","D":"Because poor-quality components always improve finished product reliability"},"correctOption":"A","correctAnswer":"Because defective incoming materials or components will cause finished products to fail even if internal factory processes are accurate","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality assurance covers the entire value chain, starting with reliable, specification-compliant inputs from suppliers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because certified inputs still must be paid for.","C":"Incorrect because internal staff training remains essential.","D":"Incorrect because substandard inputs cause product defects."}}},{"id":"P1_U4_MCQ_606","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_606","question":"What is meant by 'quantitative location factors'?","options":{"A":"Non-financial factors such as the owner's personal family preferences and local climate","B":"Factors that can be measured in financial or numerical terms, such as land rent, wage rates, transport costs, and government grants","C":"Factors that have zero impact on a business's profit or costs","D":"Cultural traditions and language differences in foreign countries"},"correctOption":"B","correctAnswer":"Factors that can be measured in financial or numerical terms, such as land rent, wage rates, transport costs, and government grants","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because quantitative factors can be calculated in monetary or numerical units to compare total costs across sites.","distractor_reasons":{"A":"Incorrect because owner preferences and climate are qualitative factors.","B":"Correct selection.","C":"Incorrect because quantitative factors directly affect business costs and profitability.","D":"Incorrect because cultural and language barriers are qualitative factors."}}},{"id":"P1_U4_MCQ_607","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_607","question":"Which of the following is a 'qualitative location factor'?","options":{"A":"Monthly factory lease cost per square metre","B":"Hourly wage rates of local assembly workers","C":"Quality of local infrastructure, political stability, language barriers, and the owner's personal lifestyle preference","D":"Value of a government tax-exemption grant in dollars"},"correctOption":"C","correctAnswer":"Quality of local infrastructure, political stability, language barriers, and the owner's personal lifestyle preference","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because qualitative factors are non-numerical considerations that still strongly influence operational success and risk.","distractor_reasons":{"A":"Incorrect because lease cost per square metre is a quantitative financial factor.","B":"Incorrect because hourly wage rates are quantitative financial factors.","C":"Correct selection.","D":"Incorrect because a dollar tax grant is a quantitative financial factor."}}},{"id":"P1_U4_MCQ_608","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_608","question":"Where should a 'weight-losing' (bulk-reducing) manufacturing industry—such as timber sawmilling or mineral smelting—locate to minimize transport costs?","options":{"A":"In the centre of a crowded capital city far from mines or forests","B":"On a small island with no raw materials or freight links","C":"Inside a suburban retail shopping mall","D":"Close to the source of heavy, bulky raw materials so waste rock or bark is not transported long distances"},"correctOption":"D","correctAnswer":"Close to the source of heavy, bulky raw materials so waste rock or bark is not transported long distances","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because processing bulky raw inputs at the source removes waste weight early, reducing freight costs on the lighter finished output.","distractor_reasons":{"A":"Incorrect because hauling heavy raw ores or logs into a distant city incurs massive freight costs.","B":"Incorrect because lack of raw materials and transport links makes operations unviable.","C":"Incorrect because heavy primary processing cannot locate in shopping malls.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_609","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_609","question":"Where should a 'weight-gaining' or 'bulk-increasing' manufacturing industry—such as soft-drinks bottling or cardboard box assembly—locate?","options":{"A":"Close to major customer markets to minimize the high freight cost of transporting heavy or bulky finished goods","B":"In a remote desert hundreds of kilometres away from customers","C":"Inside a deep underground coal mine","D":"Next to a remote forest with no motorway connections"},"correctOption":"A","correctAnswer":"Close to major customer markets to minimize the high freight cost of transporting heavy or bulky finished goods","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because finished bottled drinks or assembled boxes are far heavier or bulkier than compact syrup or flat paper rolls, making proximity to buyers essential.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shipping heavy or bulky finished products across long distances is very expensive.","C":"Incorrect because consumer bottling or box plants have no reason to locate inside mines.","D":"Incorrect because poor road links and distance from urban markets raise distribution costs."}}},{"id":"P1_U4_MCQ_610","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_610","question":"Why do food-processing industries that use fresh, perishable raw materials (such as fish canning or fruit freezing) locate close to fishing ports or farms?","options":{"A":"Because perishable ingredients never spoil regardless of travel time","B":"So raw produce can be processed and preserved immediately before spoiling, avoiding waste and expensive refrigerated transport","C":"Because city centres offer free rent to fish canneries","D":"Because farmers deliver crops for free if the factory is nearby"},"correctOption":"B","correctAnswer":"So raw produce can be processed and preserved immediately before spoiling, avoiding waste and expensive refrigerated transport","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because rapid deterioration of fresh catch or harvested crops requires immediate processing right at the source.","distractor_reasons":{"A":"Incorrect because fresh fish and fruit spoil rapidly without immediate preservation.","B":"Correct selection.","C":"Incorrect because city centres have high rent and zoning restrictions against food-processing plants.","D":"Incorrect because farmers still charge market prices for their produce."}}},{"id":"P1_U4_MCQ_611","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_611","question":"How does 'labour availability and skill level' influence a business's location decision?","options":{"A":"High-tech research firms locate in regions with zero universities or graduates","B":"Labour-intensive factories always choose locations with the highest wage rates","C":"Labour-intensive firms seek areas with abundant affordable workers, whereas high-tech firms locate near universities and specialist talent pools","D":"Worker skills have no effect on production quality or productivity"},"correctOption":"C","correctAnswer":"Labour-intensive firms seek areas with abundant affordable workers, whereas high-tech firms locate near universities and specialist talent pools","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because businesses match their site choice to the specific type, skill level, and cost of labour required by their operations.","distractor_reasons":{"A":"Incorrect because high-tech firms cluster near universities to recruit specialist graduates.","B":"Incorrect because labour-intensive firms seek competitive, affordable wage rates to keep unit costs low.","C":"Correct selection.","D":"Incorrect because worker skills directly affect productivity and product quality."}}},{"id":"P1_U4_MCQ_612","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_612","question":"Why is good 'transport infrastructure' (motorways, railways, ports, and cargo airports) vital for manufacturing and distribution businesses?","options":{"A":"It eliminates the need to pay for fuel or delivery vehicles","B":"It prevents competitors from selling similar products","C":"It guarantees zero corporate income taxes","D":"It ensures fast, reliable arrival of raw materials and timely, low-cost delivery of finished goods to customers"},"correctOption":"D","correctAnswer":"It ensures fast, reliable arrival of raw materials and timely, low-cost delivery of finished goods to customers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because efficient transport links shorten lead times, enable JIT deliveries, and reduce freight expenses.","distractor_reasons":{"A":"Incorrect because businesses still pay for vehicles, fuel, and freight services.","B":"Incorrect because public transport infrastructure is open to all competing firms.","C":"Incorrect because tax rates are set by government fiscal policy rather than road networks.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_613","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_613","question":"What is meant by 'external economies of scale' in location decisions?","options":{"A":"Cost and efficiency advantages gained when many firms in the same industry cluster in one area, sharing specialist suppliers, skilled labour, and infrastructure","B":"Cost savings achieved inside a single company when it buys its own larger factory","C":"Rising unit costs caused by internal communication breakdowns inside a giant corporation","D":"Tariffs imposed by foreign governments on imported goods"},"correctOption":"A","correctAnswer":"Cost and efficiency advantages gained when many firms in the same industry cluster in one area, sharing specialist suppliers, skilled labour, and infrastructure","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because geographic clustering attracts specialist component suppliers, maintenance engineers, and trained workers that benefit all local firms.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cost savings from a single firm's own growth are internal economies of scale.","C":"Incorrect because rising costs from internal management problems are internal diseconomies of scale.","D":"Incorrect because import tariffs are trade barriers."}}},{"id":"P1_U4_MCQ_614","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_614","question":"Which location factor is typically most critical for physical retail shops and face-to-face consumer service businesses?","options":{"A":"Proximity to open-cast iron ore mines","B":"High customer footfall, convenient access, parking, and visibility to target shoppers","C":"Access to deep-water heavy container ports","D":"Isolation from all residential neighbourhoods"},"correctOption":"B","correctAnswer":"High customer footfall, convenient access, parking, and visibility to target shoppers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because retail stores, cafes, and clinics rely directly on customers visiting their premises easily.","distractor_reasons":{"A":"Incorrect because retail shops do not process raw iron ore.","B":"Correct selection.","C":"Incorrect because container ports serve bulk import/export logistics rather than walk-in retail shoppers.","D":"Incorrect because isolating a shop from neighbourhoods eliminates local customers."}}},{"id":"P1_U4_MCQ_615","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_615","question":"How have modern telecommunications and high-speed broadband affected location decisions for online and digital service businesses?","options":{"A":"They force all digital businesses to rent expensive city-centre offices","B":"They require every online customer to visit the company's headquarters in person","C":"They allow service firms to locate in low-rent rural towns or overseas regions while serving clients worldwide online","D":"They eliminate the need for computers or internet connections"},"correctOption":"C","correctAnswer":"They allow service firms to locate in low-rent rural towns or overseas regions while serving clients worldwide online","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cloud tools, email, and video conferencing decouple digital service delivery from physical customer proximity, cutting rent costs.","distractor_reasons":{"A":"Incorrect because broadband removes the necessity to pay high city-centre rents.","B":"Incorrect because digital services are delivered electronically without in-person visits.","C":"Correct selection.","D":"Incorrect because online businesses depend entirely on computers and broadband."}}},{"id":"P1_U4_MCQ_616","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_616","question":"How do 'government financial incentives' (such as enterprise zone tax holidays and job-creation grants) influence location choices?","options":{"A":"They raise operating costs to discourage firms from investing in depressed regions","B":"They ban businesses from hiring local workers","C":"They eliminate all transport costs for raw materials","D":"They reduce start-up and tax expenses, attracting businesses to locate in regions with high unemployment"},"correctOption":"D","correctAnswer":"They reduce start-up and tax expenses, attracting businesses to locate in regions with high unemployment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because governments use subsidies and tax breaks to stimulate economic regeneration and job creation in disadvantaged areas.","distractor_reasons":{"A":"Incorrect because incentives lower costs to encourage investment.","B":"Incorrect because grants are usually conditional on creating local jobs.","C":"Incorrect because freight costs still apply.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_617","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_617","question":"How can 'government planning and environmental regulations' restrict a business's location options?","options":{"A":"Zoning and pollution laws prohibit noisy, hazardous, or polluting factories from locating near residential areas, schools, or water supplies","B":"Planning laws force chemical plants to locate inside city-centre shopping malls","C":"Environmental laws exempt factories from all waste disposal rules","D":"Regulations guarantee free land in national parks for every manufacturer"},"correctOption":"A","correctAnswer":"Zoning and pollution laws prohibit noisy, hazardous, or polluting factories from locating near residential areas, schools, or water supplies","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because governments protect public health and local environments by restricting industrial operations to designated zones.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because chemical plants are barred from retail and residential areas.","C":"Incorrect because environmental laws strictly regulate waste disposal.","D":"Incorrect because national parks are protected from industrial development."}}},{"id":"P1_U4_MCQ_618","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_618","question":"Why do 'personal preferences' of the owner often play a significant role in the location of sole traders and small businesses?","options":{"A":"Small business owners never care about making a profit","B":"Owners often choose sites near their home, family, or preferred lifestyle environment even if another location offers slightly higher profits","C":"Large multinational corporations are controlled by a single sole trader","D":"Governments legally require sole traders to work inside their own bedrooms"},"correctOption":"B","correctAnswer":"Owners often choose sites near their home, family, or preferred lifestyle environment even if another location offers slightly higher profits","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because independent owners have full control over location choices and frequently balance financial returns with family and lifestyle goals.","distractor_reasons":{"A":"Incorrect because small businesses still need profit to survive, though owners balance it with personal priorities.","B":"Correct selection.","C":"Incorrect because multinational corporations are owned by shareholders and run by boards of directors.","D":"Incorrect because no law restricts sole traders to working from home."}}},{"id":"P1_U4_MCQ_619","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_619","question":"Why do expanding manufacturing businesses frequently relocate from cramped city-centre sites to out-of-town industrial estates?","options":{"A":"To pay higher rent per square metre and restrict heavy-lorry access","B":"To attract more walk-in window shoppers onto the factory floor","C":"To gain larger premises for expansion at lower rent with easier motorway and heavy-lorry access","D":"To eliminate all employee wages and electricity bills"},"correctOption":"C","correctAnswer":"To gain larger premises for expansion at lower rent with easier motorway and heavy-lorry access","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because out-of-town industrial parks provide space for growth, lower property costs, and uncongested road links for freight.","distractor_reasons":{"A":"Incorrect because out-of-town sites offer lower rent and better lorry access.","B":"Incorrect because factories distribute to buyers rather than relying on walk-in shoppers.","C":"Correct selection.","D":"Incorrect because wages and electricity expenses still apply."}}},{"id":"P1_U4_MCQ_620","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_620","question":"What is a major operational risk when relocating an existing business to a distant new site?","options":{"A":"Lower rent at the new site automatically doubles product defects","B":"The business no longer needs to serve existing customers","C":"Relocating eliminates all moving and machinery installation expenses","D":"Experienced, skilled workers may resign due to longer commutes, causing redundancy, recruitment, and retraining costs alongside temporary production disruption"},"correctOption":"D","correctAnswer":"Experienced, skilled workers may resign due to longer commutes, causing redundancy, recruitment, and retraining costs alongside temporary production disruption","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because moving away from an established workforce risks losing valuable skills and incurs high transition costs.","distractor_reasons":{"A":"Incorrect because lower rent does not cause product defects.","B":"Incorrect because retaining existing customers is vital during relocation.","C":"Incorrect because dismantling, transporting, and reinstalling equipment is expensive.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_621","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_621","question":"Why do many multinational companies relocate labour-intensive assembly plants to lower-wage countries overseas?","options":{"A":"Lower wage rates and lower land/utility costs reduce average production cost per unit, boosting price competitiveness and profit margins","B":"Overseas workers never require wages, training, or safe working conditions","C":"Shipping finished goods back across oceans costs zero money","D":"Lower-wage countries never have any language or legal differences"},"correctOption":"A","correctAnswer":"Lower wage rates and lower land/utility costs reduce average production cost per unit, boosting price competitiveness and profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because substantially lower labour costs in developing economies reduce variable costs in labour-intensive manufacturing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because overseas employees still receive wages, training, and legal protections.","C":"Incorrect because international freight incurs transport and insurance expenses.","D":"Incorrect because operating abroad requires managing language, cultural, and legal differences."}}},{"id":"P1_U4_MCQ_622","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_622","question":"How does establishing a factory inside a foreign country or trading bloc help a business overcome trade barriers?","options":{"A":"It forces the foreign government to abolish all corporate taxes","B":"Goods produced locally inside the host country or trading bloc are treated as domestic output, bypassing import tariffs and quotas","C":"It eliminates all competition from local businesses","D":"It allows the firm to ignore local employment and safety laws"},"correctOption":"B","correctAnswer":"Goods produced locally inside the host country or trading bloc are treated as domestic output, bypassing import tariffs and quotas","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because producing within a protected market avoids customs duties and import limits levied on foreign-made imports.","distractor_reasons":{"A":"Incorrect because foreign-owned factories still pay local corporate taxes unless granted specific incentives.","B":"Correct selection.","C":"Incorrect because local competitors remain active in the market.","D":"Incorrect because foreign subsidiaries must obey all host-country laws."}}},{"id":"P1_U4_MCQ_623","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_623","question":"Besides lower labour costs and tariff avoidance, what is another strategic reason for locating operations in a fast-growing overseas market?","options":{"A":"To increase shipping times and freight expenses when serving overseas buyers","B":"To avoid adapting products to local customer tastes","C":"Proximity to rapidly expanding consumer demand and local raw materials, reducing delivery lead times and international freight costs","D":"To ensure the business relies on only one single currency worldwide"},"correctOption":"C","correctAnswer":"Proximity to rapidly expanding consumer demand and local raw materials, reducing delivery lead times and international freight costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because producing close to growing foreign markets or raw material sources speeds up delivery and lowers long-haul transport expenses.","distractor_reasons":{"A":"Incorrect because locating near foreign buyers reduces rather than increases shipping times.","B":"Incorrect because local presence helps businesses adapt products to regional tastes.","C":"Correct selection.","D":"Incorrect because international operations expose the firm to multiple currencies."}}},{"id":"P1_U4_MCQ_624","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_624","question":"Which qualitative risk must a business manage carefully when expanding operations into a foreign country?","options":{"A":"Excessive bulk-buying discounts from local suppliers","B":"Guaranteed political stability in every country worldwide","C":"Complete absence of environmental or labour regulations","D":"Language barriers, cultural misunderstandings, different legal/tax systems, and potential political instability"},"correctOption":"D","correctAnswer":"Language barriers, cultural misunderstandings, different legal/tax systems, and potential political instability","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because unfamiliar laws, communication barriers, cultural norms, and political risks can disrupt overseas operations if poorly managed.","distractor_reasons":{"A":"Incorrect because bulk discounts are a financial advantage rather than a risk.","B":"Incorrect because political stability varies across countries and poses real investment risks.","C":"Incorrect because host countries enforce their own legal and regulatory frameworks.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_625","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_625","question":"How can 'exchange rate fluctuations' and 'long global supply chains' negatively affect a business that relocates manufacturing overseas?","options":{"A":"An appreciation of the host country's currency raises foreign wage and operating costs in home-currency terms, while distant shipping routes increase lead times and disruption risks","B":"Exchange rate changes always make overseas factories completely free to run","C":"Long ocean shipping routes deliver goods faster than local road transport","D":"Overseas factories never require quality monitoring or logistics planning"},"correctOption":"A","correctAnswer":"An appreciation of the host country's currency raises foreign wage and operating costs in home-currency terms, while distant shipping routes increase lead times and disruption risks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because currency movements can erode expected overseas cost savings, and long sea/air routes increase vulnerability to port delays and stockouts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a stronger foreign currency increases home-currency costs.","C":"Incorrect because international shipping takes much longer than local delivery.","D":"Incorrect because distant operations require stronger quality control and supply-chain coordination."}}},{"id":"P1_U4_MCQ_626","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_626","question":"What are the four stages of the production transformation process in operations management?","options":{"A":"Inputs, transformation process, outputs, and feedback","B":"Recruitment, training, appraisal, and redundancy","C":"Market research, pricing, promotion, and distribution","D":"Invoice, ledger, balance sheet, and cash flow"},"correctOption":"A","correctAnswer":"Inputs, transformation process, outputs, and feedback","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because operations management takes inputs (land, labour, capital, enterprise), transforms them through manufacturing or service delivery, produces outputs, and uses customer/quality feedback to improve.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because recruitment, training, appraisal, and redundancy belong to human resource management.","C":"Incorrect because market research and the marketing mix belong to marketing management.","D":"Incorrect because ledgers and balance sheets belong to financial accounting."}}},{"id":"P1_U4_MCQ_627","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_627","question":"Which operational action directly increases the 'added value' of a physical product without changing its selling price?","options":{"A":"Increasing factory managers' annual salaries","B":"Reducing the cost of bought-in raw materials and packaging while maintaining product quality","C":"Spending more on expensive bought-in components while keeping the price fixed","D":"Increasing business property insurance premiums"},"correctOption":"B","correctAnswer":"Reducing the cost of bought-in raw materials and packaging while maintaining product quality","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus bought-in material and component costs; lowering bought-in input costs widens this gap.","distractor_reasons":{"A":"Incorrect because internal manager salaries are paid out of added value and do not change the formula for added value.","B":"Correct selection.","C":"Incorrect because higher bought-in component costs reduce added value if the selling price is unchanged.","D":"Incorrect because property insurance is an internal fixed overhead rather than a bought-in material cost."}}},{"id":"P1_U4_MCQ_628","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_628","question":"Why is 'added value' important for the survival and profitability of a business?","options":{"A":"Because added value is identical to net profit after tax","B":"Because businesses with high added value never pay wages or rent","C":"Because internal expenses such as wages, rent, electricity, and profit must all be paid out of the added value created","D":"Because added value eliminates the need to purchase raw materials"},"correctOption":"C","correctAnswer":"Because internal expenses such as wages, rent, electricity, and profit must all be paid out of the added value created","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because added value represents the wealth generated above bought-in inputs, from which all internal operating expenses and profit are funded.","distractor_reasons":{"A":"Incorrect because profit is calculated only after deducting internal wages, overheads, and taxes from added value.","B":"Incorrect because wages and rent still must be paid out of added value.","C":"Correct selection.","D":"Incorrect because raw materials are still purchased and subtracted when calculating added value."}}},{"id":"P1_U4_MCQ_629","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_629","question":"Which method is an effective way to raise 'labour productivity' in a manufacturing business?","options":{"A":"Reducing employee rest breaks so staff work without pause","B":"Replacing modern electric machinery with manual hand tools","C":"Stopping routine maintenance on assembly-line equipment","D":"Improving employee skills through targeted training and reorganising factory layout to eliminate unnecessary movement"},"correctOption":"D","correctAnswer":"Improving employee skills through targeted training and reorganising factory layout to eliminate unnecessary movement","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because better-trained workers operating in an efficient workspace produce higher output per hour with fewer errors.","distractor_reasons":{"A":"Incorrect because overtired workers slow down and make more mistakes, lowering productivity.","B":"Incorrect because reverting to hand tools reduces output per worker.","C":"Incorrect because neglecting maintenance causes breakdowns that halt output.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_630","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_630","question":"How does higher 'labour productivity' improve a business's price competitiveness?","options":{"A":"Higher output per worker reduces average labour cost per unit, enabling lower selling prices or higher profit margins","B":"Higher productivity automatically forces suppliers to give free raw materials","C":"Higher productivity increases fixed factory rent per unit produced","D":"Higher productivity eliminates all variable costs of production"},"correctOption":"A","correctAnswer":"Higher output per worker reduces average labour cost per unit, enabling lower selling prices or higher profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when each worker produces more units per hour, wage cost per unit falls, lowering total average unit cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because internal workforce efficiency does not make raw materials free.","C":"Incorrect because higher output spreads fixed rent over more units, lowering average fixed cost.","D":"Incorrect because raw materials and packaging are still consumed for each unit made."}}},{"id":"P1_U4_MCQ_631","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_631","question":"What is a key advantage of 'capital-intensive production' compared with labour-intensive production?","options":{"A":"It requires very low initial capital investment to set up","B":"Machinery can operate continuously at high speed with consistent quality and low variable labour cost per unit","C":"Every individual product can be hand-crafted differently at zero extra cost","D":"It never experiences costly technical breakdowns or maintenance expenses"},"correctOption":"B","correctAnswer":"Machinery can operate continuously at high speed with consistent quality and low variable labour cost per unit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because automated machinery works tirelessly at high speed and uniform precision, lowering unit costs at large output scales.","distractor_reasons":{"A":"Incorrect because capital-intensive production requires heavy upfront spending on machinery.","B":"Correct selection.","C":"Incorrect because capital-intensive lines usually produce standardized rather than hand-crafted items.","D":"Incorrect because complex machinery requires specialist maintenance and suffers costly downtime if it breaks."}}},{"id":"P1_U4_MCQ_632","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_632","question":"What is a major disadvantage of 'capital-intensive production'?","options":{"A":"Output speeds are too slow to supply mass markets","B":"Product quality varies widely due to human fatigue","C":"High upfront capital costs, fixed loan interest charges, and inflexibility to adapt machinery to rapidly changing designs","D":"Direct variable wage costs per unit are much higher than in manual craft work"},"correctOption":"C","correctAnswer":"High upfront capital costs, fixed loan interest charges, and inflexibility to adapt machinery to rapidly changing designs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because specialized equipment is expensive to buy, creates high fixed overheads, and is difficult to reprogram for completely different products.","distractor_reasons":{"A":"Incorrect because capital-intensive lines generate very high output volumes.","B":"Incorrect because machines do not suffer human fatigue and maintain consistent quality.","C":"Correct selection.","D":"Incorrect because direct wage costs per unit are typically much lower in capital-intensive production."}}},{"id":"P1_U4_MCQ_633","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_633","question":"Which of the following is a primary advantage of 'labour-intensive production'?","options":{"A":"It achieves the lowest unit cost when manufacturing millions of standardized metal bolts","B":"It operates 24 hours a day without human rest breaks or shift premiums","C":"It eliminates all recruitment, training, and employee motivation challenges","D":"Low upfront machinery costs and high flexibility to adjust output levels or customize products using skilled human judgement"},"correctOption":"D","correctAnswer":"Low upfront machinery costs and high flexibility to adjust output levels or customize products using skilled human judgement","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because human workers can adapt quickly to bespoke designs and output changes without heavy capital expenditure.","distractor_reasons":{"A":"Incorrect because mass-producing standardized bolts is far cheaper with capital-intensive automation.","B":"Incorrect because human workers require rest breaks, holidays, and shift allowances.","C":"Incorrect because labour-intensive firms face significant HR management and wage-inflation challenges.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_634","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_634","question":"In lean production, which type of waste occurs when a factory manufactures more goods than customers have ordered?","options":{"A":"Overproduction waste","B":"Motion waste","C":"Non-utilised skills waste","D":"Waiting waste"},"correctOption":"A","correctAnswer":"Overproduction waste","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because overproduction ties up materials, labour, and storage space in unsold stock that may become obsolete.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because motion waste refers to unnecessary physical walking or reaching by workers.","C":"Incorrect because non-utilised skills occur when qualified staff perform low-skill tasks.","D":"Incorrect because waiting waste occurs when workers or machines sit idle between stages."}}},{"id":"P1_U4_MCQ_635","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_635","question":"In lean production, what is meant by 'waiting waste'?","options":{"A":"Moving semi-finished parts several kilometres between separate buildings","B":"Idle time when workers or machines are paused waiting for materials, instructions, or a preceding process to finish","C":"Adding extra product features that customers neither want nor pay for","D":"Scrapping faulty items at the end of an assembly line"},"correctOption":"B","correctAnswer":"Idle time when workers or machines are paused waiting for materials, instructions, or a preceding process to finish","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unbalanced production stages leave staff or equipment unproductive while paying fixed wages and overheads.","distractor_reasons":{"A":"Incorrect because moving materials unnecessarily between sites is transportation waste.","B":"Correct selection.","C":"Incorrect because adding unnecessary features is over-processing waste.","D":"Incorrect because faulty items requiring scrap or rework represent defect waste."}}},{"id":"P1_U4_MCQ_636","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_636","question":"In lean production, what is meant by 'over-processing waste'?","options":{"A":"Storing six months of spare components in rented warehouses","B":"Workers walking long distances across a factory to fetch tools","C":"Performing unnecessary extra work, overly tight tolerances, or redundant steps that add no value to the customer","D":"Failing to use the problem-solving qualifications of trained staff"},"correctOption":"C","correctAnswer":"Performing unnecessary extra work, overly tight tolerances, or redundant steps that add no value to the customer","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because over-processing consumes extra machine time, energy, and labour on features or finishes customers do not require.","distractor_reasons":{"A":"Incorrect because holding excessive stock is inventory waste.","B":"Incorrect because unnecessary worker walking is motion waste.","C":"Correct selection.","D":"Incorrect because underusing employee abilities is non-utilised skills waste."}}},{"id":"P1_U4_MCQ_637","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_637","question":"How does 'transportation waste' differ from 'motion waste' in lean production?","options":{"A":"Transportation waste applies only to services, whereas motion waste applies only to farms","B":"Transportation waste is caused by defective raw materials, whereas motion waste is caused by excess buffer stock","C":"There is no difference between transportation waste and motion waste","D":"Transportation waste refers to unnecessary movement of materials and goods between locations, whereas motion waste refers to unnecessary physical movements by workers"},"correctOption":"D","correctAnswer":"Transportation waste refers to unnecessary movement of materials and goods between locations, whereas motion waste refers to unnecessary physical movements by workers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because transportation tracks the movement of inventory/parts, whereas motion tracks human ergonomic movement (reaching, bending, walking).","distractor_reasons":{"A":"Incorrect because both wastes occur across manufacturing, warehousing, and service operations.","B":"Incorrect because neither is defined by defective materials or buffer stock.","C":"Incorrect because lean production separates material movement from human movement.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_638","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_638","question":"What is meant by 'cell production' in lean manufacturing?","options":{"A":"Splitting an assembly line into self-contained, multi-skilled team units (often U-shaped) that complete a whole stage or product together","B":"Isolating every worker in a separate locked room with no communication","C":"Replacing all human teams with a single giant conveyor belt","D":"Manufacturing batteries and fuel cells exclusively"},"correctOption":"A","correctAnswer":"Splitting an assembly line into self-contained, multi-skilled team units (often U-shaped) that complete a whole stage or product together","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cell production organizes multi-skilled workers into compact teams responsible for a complete unit of work, boosting teamwork and cutting waste.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cell production promotes close team collaboration rather than isolation.","C":"Incorrect because cell production replaces rigid straight lines with flexible team cells.","D":"Incorrect because 'cell' refers to a workstation layout, not electrical batteries."}}},{"id":"P1_U4_MCQ_639","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_639","question":"How does 'Kaizen' improve worker motivation as well as operational efficiency?","options":{"A":"By eliminating all team meetings and ignoring worker opinions","B":"By empowering shop-floor employees to contribute improvement ideas, giving them greater ownership and pride in their work","C":"By forcing workers to buy expensive new robotic machinery themselves","D":"By increasing repetitive assembly-line boredom"},"correctOption":"B","correctAnswer":"By empowering shop-floor employees to contribute improvement ideas, giving them greater ownership and pride in their work","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because valuing employees' practical insights satisfies esteem needs, strengthens engagement, and continuously eliminates small inefficiencies.","distractor_reasons":{"A":"Incorrect because Kaizen relies on regular team discussions and worker suggestions.","B":"Correct selection.","C":"Incorrect because Kaizen focuses on low-cost process improvements funded by the business.","D":"Incorrect because involvement in problem-solving reduces boredom."}}},{"id":"P1_U4_MCQ_640","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_640","question":"Which requirement is essential for a business to implement 'just-in-time' (JIT) inventory control successfully?","options":{"A":"Massive warehouses filled with six months of reserve stock","B":"Frequent transport strikes and unpredictable overseas shipping schedules","C":"Highly reliable suppliers located nearby, accurate real-time IT ordering systems, and flexible multi-skilled staff","D":"Producing huge batches of goods without waiting for customer demand"},"correctOption":"C","correctAnswer":"Highly reliable suppliers located nearby, accurate real-time IT ordering systems, and flexible multi-skilled staff","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because operating without buffer stock demands punctual deliveries, instant data links, and workers able to prevent bottlenecks.","distractor_reasons":{"A":"Incorrect because holding six months of reserve stock contradicts JIT.","B":"Incorrect because unpredictable delays cause immediate shutdowns under JIT.","C":"Correct selection.","D":"Incorrect because JIT is a demand-pull system triggered by actual orders."}}},{"id":"P1_U4_MCQ_641","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_641","question":"What is a major financial advantage of 'just-in-time' (JIT) inventory control?","options":{"A":"It guarantees maximum bulk-buying discounts on giant annual orders","B":"It eliminates all transport delivery charges from suppliers","C":"It protects the factory completely against sudden supplier bankruptcies","D":"It eliminates warehouse storage costs and frees up working capital previously tied up in inventory"},"correctOption":"D","correctAnswer":"It eliminates warehouse storage costs and frees up working capital previously tied up in inventory","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because holding near-zero stock reduces warehouse rent, insurance, spoilage, and cash locked in raw materials.","distractor_reasons":{"A":"Incorrect because frequent small JIT deliveries often forfeit bulk-buying discounts.","B":"Incorrect because frequent small deliveries can actually raise transport administration costs.","C":"Incorrect because zero buffer stock makes a firm more vulnerable to sudden supplier failure.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_642","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_642","question":"What are the three main categories of inventory held by a manufacturing business?","options":{"A":"Raw materials and components, work-in-progress, and finished goods","B":"Fixed assets, bank loans, and retained profit","C":"Fixed costs, variable costs, and break-even output","D":"Market research, advertising, and personal selling"},"correctOption":"A","correctAnswer":"Raw materials and components, work-in-progress, and finished goods","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because manufacturers hold stocks at three stages: unprocessed inputs, partially assembled items (work-in-progress), and completed goods awaiting dispatch.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fixed assets, loans, and retained profit are balance-sheet items rather than inventory categories.","C":"Incorrect because these are cost and break-even concepts.","D":"Incorrect because these are marketing activities."}}},{"id":"P1_U4_MCQ_643","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_643","question":"In inventory control, what is meant by 'lead time'?","options":{"A":"The total time a finished product lasts before wearing out","B":"The time delay between placing an order with a supplier and receiving the delivery","C":"The time spent inspecting finished goods at the end of a conveyor belt","D":"The total number of hours workers spend on lunch breaks"},"correctOption":"B","correctAnswer":"The time delay between placing an order with a supplier and receiving the delivery","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because managers must know the supplier delivery lead time to place reorder requests early enough before stock runs out.","distractor_reasons":{"A":"Incorrect because product durability is product lifespan rather than lead time.","B":"Correct selection.","C":"Incorrect because end-of-line testing is quality control inspection time.","D":"Incorrect because break time is unrelated to stock replenishment."}}},{"id":"P1_U4_MCQ_644","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_644","question":"In a standard inventory control chart, what is the purpose of setting a 'reorder level'?","options":{"A":"To ensure the warehouse never holds any buffer inventory","B":"To stop all production whenever inventory reaches its maximum capacity","C":"To trigger a new stock order early enough so fresh supplies arrive during the lead time before inventory falls below the buffer level","D":"To force suppliers to deliver raw materials free of charge"},"correctOption":"C","correctAnswer":"To trigger a new stock order early enough so fresh supplies arrive during the lead time before inventory falls below the buffer level","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because setting the reorder level to cover lead-time consumption plus buffer stock prevents stockouts while awaiting delivery.","distractor_reasons":{"A":"Incorrect because the reorder level is specifically designed to protect buffer inventory.","B":"Incorrect because maximum inventory limits over-ordering rather than halting production.","C":"Correct selection.","D":"Incorrect because reorder triggers are internal stock thresholds, not pricing agreements."}}},{"id":"P1_U4_MCQ_645","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_645","question":"What is a major risk of holding insufficient inventory (too little stock)?","options":{"A":"Excessive warehouse rent, heating, and security bills","B":"Large amounts of cash locked up in slow-moving goods","C":"High losses from unsold stock going out of fashion","D":"Stockouts during sudden demand spikes, leading to lost sales, idle workers, and dissatisfied customers switching to rivals"},"correctOption":"D","correctAnswer":"Stockouts during sudden demand spikes, leading to lost sales, idle workers, and dissatisfied customers switching to rivals","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because inadequate stock leaves a business unable to fulfill unexpected orders or absorb supplier delays.","distractor_reasons":{"A":"Incorrect because high storage expenses are a risk of holding too much stock.","B":"Incorrect because tied-up cash is a cost of holding excess stock.","C":"Incorrect because obsolescence is a risk of over-stocking.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_646","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_646","question":"Which combination of factors best determines whether a business should choose job, batch, or flow production?","options":{"A":"The level of customer demand, degree of product customization required, size of the business, and capital available","B":"The colour of the factory walls and the age of the marketing director","C":"Whether the business is located in the northern or southern hemisphere","D":"The number of pages in the company's annual financial report"},"correctOption":"A","correctAnswer":"The level of customer demand, degree of product customization required, size of the business, and capital available","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because production method choice depends on market size, standardization vs customization, and financial capacity to fund equipment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because wall colours and director age have no operational bearing on production methods.","C":"Incorrect because geographic hemisphere does not dictate production systems.","D":"Incorrect because report length is unrelated to operations."}}},{"id":"P1_U4_MCQ_647","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_647","question":"How does 'batch production' balance the trade-off between job production and flow production?","options":{"A":"It offers zero product variety while requiring zero machinery","B":"It allows a business to produce different product varieties in groups while achieving lower unit costs than bespoke job production","C":"It manufactures every single item uniquely for an individual buyer","D":"It runs 24 hours a day without ever stopping to change product specifications"},"correctOption":"B","correctAnswer":"It allows a business to produce different product varieties in groups while achieving lower unit costs than bespoke job production","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because batch production sits between job and flow, providing moderate variety and moderate economies of scale.","distractor_reasons":{"A":"Incorrect because batch production offers variety across batches and uses machinery.","B":"Correct selection.","C":"Incorrect because individual one-off customization defines job production.","D":"Incorrect because continuous unvaried operation defines flow production."}}},{"id":"P1_U4_MCQ_648","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_648","question":"Why does 'job production' typically result in higher employee job satisfaction than assembly-line flow production?","options":{"A":"Because workers repeat the exact same simple task every few seconds","B":"Because workers never have to use any specialist skills or judgement","C":"Because skilled workers perform varied tasks and see a unique product completed from start to finish","D":"Because job production eliminates all deadlines and customer expectations"},"correctOption":"C","correctAnswer":"Because skilled workers perform varied tasks and see a unique product completed from start to finish","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because task variety, autonomy, and visible craftsmanship fulfill higher-level motivational needs.","distractor_reasons":{"A":"Incorrect because repeating the same simple task describes flow production.","B":"Incorrect because job production requires high technical skill and problem-solving.","C":"Correct selection.","D":"Incorrect because bespoke clients set strict deadlines and specifications."}}},{"id":"P1_U4_MCQ_649","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_649","question":"What operational risk makes 'flow production' vulnerable when a single machine on the assembly line breaks down?","options":{"A":"Workers can immediately hand-carve every component at the same speed","B":"Breakdowns automatically reduce fixed overhead costs to zero","C":"Customers prefer waiting extra weeks for standardized goods","D":"Because operations are tightly linked sequentially, a fault at one stage can halt the entire production line"},"correctOption":"D","correctAnswer":"Because operations are tightly linked sequentially, a fault at one stage can halt the entire production line","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because continuous flow lines depend on synchronized stages; any bottleneck stops downstream assembly while fixed costs continue.","distractor_reasons":{"A":"Incorrect because manual work cannot match automated assembly speeds.","B":"Incorrect because fixed costs continue during downtime.","C":"Incorrect because delays frustrate customers and retailers.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_650","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_650","question":"When a successful small business switches from batch production to flow production as demand grows, what major challenge must it overcome?","options":{"A":"Raising substantial finance for expensive automated machinery and managing worker resistance to more repetitive tasks","B":"Finding ways to increase average cost per unit","C":"Reducing total output volume to serve fewer customers","D":"Eliminating all standardized product specifications"},"correctOption":"A","correctAnswer":"Raising substantial finance for expensive automated machinery and managing worker resistance to more repetitive tasks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because transitioning to flow production demands heavy capital investment, retraining, and addressing lower task variety.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the goal of switching to flow production is to reduce unit costs.","C":"Incorrect because flow production expands output to meet large demand.","D":"Incorrect because flow production requires standardized specifications."}}},{"id":"P1_U4_MCQ_651","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_651","question":"What is meant by 'mass customization' in modern operations management?","options":{"A":"Hand-building one single bridge or ship over three years","B":"Combining flexible computer-controlled production with modular components to offer personalized products at near-mass-production unit costs","C":"Forcing every customer to buy an identical uncustomized product","D":"Producing huge quantities of goods with zero quality checks"},"correctOption":"B","correctAnswer":"Combining flexible computer-controlled production with modular components to offer personalized products at near-mass-production unit costs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because flexible CAD/CAM systems allow individual customer options without losing the speed and cost efficiency of flow production.","distractor_reasons":{"A":"Incorrect because building a single bridge is traditional job production.","B":"Correct selection.","C":"Incorrect because uncustomized output is traditional mass production.","D":"Incorrect because mass customization still relies on strict quality assurance."}}},{"id":"P1_U4_MCQ_652","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_652","question":"In lean production, why is 'excess inventory' classified as one of the seven wastes?","options":{"A":"Because inventory increases customer satisfaction during busy seasons","B":"Because inventory reduces warehouse rent and insurance bills","C":"Because excess stock ties up cash, occupies costly space, hides production inefficiencies, and risks damage or obsolescence","D":"Because suppliers charge extra penalties whenever businesses order in bulk"},"correctOption":"C","correctAnswer":"Because excess stock ties up cash, occupies costly space, hides production inefficiencies, and risks damage or obsolescence","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because lean principles view unnecessary stock as a costly buffer that drains working capital and conceals underlying bottlenecks.","distractor_reasons":{"A":"Incorrect because lean production distinguishes necessary minimal stock from wasteful excess stock.","B":"Incorrect because excess stock increases warehouse rent and insurance.","C":"Correct selection.","D":"Incorrect because suppliers usually offer discounts rather than penalties for bulk orders."}}},{"id":"P1_U4_MCQ_653","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_653","question":"What is the primary operational benefit of 'work-in-progress' (WIP) minimization in lean manufacturing?","options":{"A":"Longer waiting times between workstations","B":"More floor space required to store half-finished items","C":"Slower detection of manufacturing defects","D":"Shorter throughput times, less tied-up working capital, and immediate detection of faults at the next stage"},"correctOption":"D","correctAnswer":"Shorter throughput times, less tied-up working capital, and immediate detection of faults at the next stage","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because keeping work-in-progress minimal speeds up order completion and prevents large batches of faulty semi-finished goods accumulating.","distractor_reasons":{"A":"Incorrect because minimizing WIP reduces waiting times.","B":"Incorrect because less WIP frees up factory floor space.","C":"Incorrect because smaller WIP queues expose defects immediately rather than hiding them.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_654","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_654","question":"Why do businesses that produce seasonal goods (such as winter coats or holiday decorations) often hold higher inventory before peak seasons?","options":{"A":"To smooth production throughout the year at steady capacity and meet sudden peak customer demand without stockouts","B":"To maximize warehouse insurance premiums and obsolescence losses","C":"Because seasonal products never go out of fashion","D":"Because seasonal factories are legally banned from operating during summer"},"correctOption":"A","correctAnswer":"To smooth production throughout the year at steady capacity and meet sudden peak customer demand without stockouts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because building inventory gradually avoids paying overtime or buying extra capacity solely for short seasonal spikes.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because insurance and obsolescence are costs to be managed, not the reason for holding stock.","C":"Incorrect because seasonal fashion goods do carry obsolescence risk if over-produced.","D":"Incorrect because factories operate year-round specifically to build seasonal stock."}}},{"id":"P1_U4_MCQ_655","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_655","question":"How does 'capital productivity' differ from 'labour productivity'?","options":{"A":"Capital productivity measures total profit, whereas labour productivity measures total sales","B":"Capital productivity measures output produced per unit of machinery/equipment (or per dollar of capital), whereas labour productivity measures output per worker","C":"Capital productivity applies only to small sole traders, whereas labour productivity applies only to PLCs","D":"There is no difference between capital productivity and labour productivity"},"correctOption":"B","correctAnswer":"Capital productivity measures output produced per unit of machinery/equipment (or per dollar of capital), whereas labour productivity measures output per worker","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because productivity can be measured against any factor input, comparing output to machine hours/capacity (capital) or employee numbers/hours (labour).","distractor_reasons":{"A":"Incorrect because productivity measures physical or value output per input, not profit or total sales.","B":"Correct selection.","C":"Incorrect because both measures apply to businesses of all sizes.","D":"Incorrect because one evaluates equipment efficiency and the other evaluates workforce efficiency."}}},{"id":"P1_U4_MCQ_656","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_656","question":"Which drawback can arise if a business pushes 'labour productivity' aggressively without supporting workers?","options":{"A":"Average wage cost per unit increases dramatically","B":"Machines automatically stop requiring electricity","C":"Excessive work pace can cause employee stress, burnout, higher absenteeism, and increased product defects","D":"Customer demand immediately drops to zero"},"correctOption":"C","correctAnswer":"Excessive work pace can cause employee stress, burnout, higher absenteeism, and increased product defects","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unsustainable speed targets harm employee wellbeing and encourage rushing that undermines quality.","distractor_reasons":{"A":"Incorrect because higher output per worker lowers wage cost per unit.","B":"Incorrect because equipment still requires power.","C":"Correct selection.","D":"Incorrect because higher productivity does not inherently eliminate demand."}}},{"id":"P1_U4_MCQ_657","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_657","question":"How does investing in off-the-job and on-the-job training improve operational efficiency in a furniture workshop?","options":{"A":"Skilled workers assemble joints faster with fewer mistakes, raising output per worker and lowering unit costs","B":"Training reduces the total number of chairs each worker can make per week","C":"Training eliminates the need for wood, glue, or tools","D":"Trained workers never require wages or salaries"},"correctOption":"A","correctAnswer":"Skilled workers assemble joints faster with fewer mistakes, raising output per worker and lowering unit costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because improving labour skills increases labour productivity and reduces wasted timber and reworking time.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher skill increases rather than reduces weekly output per worker.","C":"Incorrect because physical raw materials and tools are still required.","D":"Incorrect because skilled workers must still be paid fair wages."}}},{"id":"P1_U4_MCQ_658","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_658","question":"A shoe factory increases monthly output from 10,000 pairs to 12,000 pairs by hiring 50% more workers. Which statement accurately describes this change?","options":{"A":"Both total production and labour productivity increased","B":"Total production increased, but labour productivity fell because output rose by 20% while the workforce grew by 50%","C":"Total production fell, while labour productivity increased","D":"Neither total production nor labour productivity changed"},"correctOption":"B","correctAnswer":"Total production increased, but labour productivity fell because output rose by 20% while the workforce grew by 50%","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because total production rose from 10,000 to 12,000 pairs (+20%), whereas output per worker fell since the number of workers grew faster (+50%) than output.","distractor_reasons":{"A":"Incorrect because labour productivity fell when workforce growth outpaced output growth.","B":"Correct selection.","C":"Incorrect because total production rose by 2,000 pairs.","D":"Incorrect because both total output and output per worker changed."}}},{"id":"P1_U4_MCQ_659","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_659","question":"Why does a seasonal umbrella manufacturer hold buffer inventory of waterproof fabric and metal frames in its warehouse?","options":{"A":"To increase warehouse rent and insurance expenses intentionally","B":"To guarantee that fabric becomes damaged before production begins","C":"To keep production running smoothly if a supplier delivery is delayed or if sudden wet weather causes an unexpected surge in orders","D":"To avoid selling umbrellas during rainy seasons"},"correctOption":"C","correctAnswer":"To keep production running smoothly if a supplier delivery is delayed or if sudden wet weather causes an unexpected surge in orders","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because buffer inventory protects the business against unexpected demand spikes and late supplier deliveries.","distractor_reasons":{"A":"Incorrect because storage and insurance expenses are costs of holding stock, not reasons to hold it.","B":"Incorrect because businesses aim to prevent inventory damage.","C":"Correct selection.","D":"Incorrect because buffer stock helps the firm meet peak rainy-season demand."}}},{"id":"P1_U4_MCQ_660","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_660","question":"A fashion retailer orders six months' worth of summer dresses in advance, leaving large quantities unsold in storage. What is a major risk of holding this excessive inventory?","options":{"A":"Cash is tied up in unsold stock and dresses may go out of fashion, forcing heavy clearance discounts","B":"Customers can never find any dresses in stock","C":"Supplier bulk-buying discounts become impossible to negotiate","D":"Warehouse storage and insurance costs fall to zero"},"correctOption":"A","correctAnswer":"Cash is tied up in unsold stock and dresses may go out of fashion, forcing heavy clearance discounts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because holding excess inventory ties up working capital and exposes seasonal goods to obsolescence and storage costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because excessive stock means surplus inventory rather than stockouts.","C":"Incorrect because large advance orders usually qualify for bulk discounts.","D":"Incorrect because storing large inventories increases warehouse and insurance costs."}}},{"id":"P1_U4_MCQ_661","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_661","question":"A commercial bakery supplies supermarkets with 2,000 loaves of white bread in the morning, 1,500 wholemeal loaves at midday, and 1,000 seeded rolls in the afternoon using the same ovens. Which production method is it using?","options":{"A":"Job production","B":"Flow production","C":"Bespoke one-off production","D":"Batch production"},"correctOption":"D","correctAnswer":"Batch production","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because batch production manufactures identical groups (batches) of one product before resetting equipment to make a batch of another product.","distractor_reasons":{"A":"Incorrect because job production makes single, unique items tailored to individual customer orders.","B":"Incorrect because flow production manufactures one standardized product continuously without stopping to change recipes.","C":"Incorrect because bespoke one-off production is another term for job production.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_662","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_662","question":"In lean production, why is 'non-utilised skills' (underused talent) considered a form of waste?","options":{"A":"Because skilled workers cost zero wages when hired","B":"Because only senior directors are capable of noticing factory inefficiencies","C":"Because failing to involve trained employees in problem-solving wastes valuable ideas and causes frustration and high staff turnover","D":"Because machines work faster when workers are forbidden from speaking"},"correctOption":"C","correctAnswer":"Because failing to involve trained employees in problem-solving wastes valuable ideas and causes frustration and high staff turnover","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because front-line workers understand daily bottlenecks best; ignoring their skills wastes improvement potential and lowers morale.","distractor_reasons":{"A":"Incorrect because qualified staff receive higher salaries, making underuse especially wasteful.","B":"Incorrect because shop-floor employees frequently spot practical improvements directors miss.","C":"Correct selection.","D":"Incorrect because open team communication drives Kaizen and quality circles."}}},{"id":"P1_U4_MCQ_663","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_663","question":"Which characteristic distinguishes service operations (such as banking or hospitality) from goods manufacturing?","options":{"A":"Services can be stored in warehouses for years before being sold","B":"Services never require any capital equipment or technology","C":"Services never involve quality standards or productivity","D":"Services are intangible, consumed at the moment of delivery, and often involve direct customer participation"},"correctOption":"D","correctAnswer":"Services are intangible, consumed at the moment of delivery, and often involve direct customer participation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because services cannot be stockpiled in advance; capacity management and staff-customer interaction are critical.","distractor_reasons":{"A":"Incorrect because services are perishable at the moment of delivery and cannot be stored as physical stock.","B":"Incorrect because banks, airlines, and hotels rely heavily on IT and physical infrastructure.","C":"Incorrect because quality and productivity are vital in service industries.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_664","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_664","question":"How does 'Computer-Aided Design' (CAD) shorten the product development cycle?","options":{"A":"Engineers can test digital 3D models for stress, fit, and performance on screen immediately rather than waiting weeks for physical prototypes","B":"CAD software automatically mines raw iron ore from the ground","C":"CAD eliminates the need for market research before launching a product","D":"CAD physically delivers finished goods to customers' homes"},"correctOption":"A","correctAnswer":"Engineers can test digital 3D models for stress, fit, and performance on screen immediately rather than waiting weeks for physical prototypes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid digital simulation and instant editing accelerate design iterations before physical tooling begins.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because CAD is design software rather than mining equipment.","C":"Incorrect because market research is still needed to identify customer preferences.","D":"Incorrect because logistics and couriers handle physical delivery."}}},{"id":"P1_U4_MCQ_665","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_665","question":"How does 'Computer-Aided Manufacturing' (CAM) reduce raw material wastage during cutting and shaping?","options":{"A":"By using zero raw materials to make physical products","B":"Computer-guided precision cutting tools optimize material layouts and follow exact dimensions without human cutting errors","C":"By allowing untrained workers to cut metal freehand","D":"By banning all quality inspections on finished parts"},"correctOption":"B","correctAnswer":"Computer-guided precision cutting tools optimize material layouts and follow exact dimensions without human cutting errors","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because digital toolpaths nest parts tightly on raw sheets and cut accurately every time, minimizing scrap off-cuts.","distractor_reasons":{"A":"Incorrect because physical goods still require raw materials.","B":"Correct selection.","C":"Incorrect because CAM automates tool control rather than relying on freehand cutting.","D":"Incorrect because CAM works alongside quality assurance checks."}}},{"id":"P1_U4_MCQ_666","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_666","question":"What is the main operational advantage of integrating CAD and CAM into 'Computer-Integrated Manufacturing' (CIM)?","options":{"A":"Designers must manually redraw blueprints on paper before factory machines can read them","B":"It eliminates the need for electrical power in the factory","C":"Design changes made in CAD flow automatically to CAM production machinery without manual re-entry, preventing transcription errors and delays","D":"It ensures every product is handmade without computers"},"correctOption":"C","correctAnswer":"Design changes made in CAD flow automatically to CAM production machinery without manual re-entry, preventing transcription errors and delays","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because seamless digital integration eliminates manual data translation between design and manufacturing departments.","distractor_reasons":{"A":"Incorrect because CIM removes paper redrawing through direct digital transfer.","B":"Incorrect because CIM systems require continuous electrical power.","C":"Correct selection.","D":"Incorrect because CIM maximizes computer automation."}}},{"id":"P1_U4_MCQ_667","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_667","question":"Why is '3D printing' particularly advantageous for producing bespoke medical implants or rapid prototypes?","options":{"A":"It prints 100,000 identical items per minute faster than injection moulding","B":"It requires zero digital design files or raw polymer/metal powders","C":"It is always cheaper per unit than flow production for mass-market plastic bottles","D":"It manufactures complex, one-off custom shapes directly from digital scans without needing expensive custom moulds or tooling"},"correctOption":"D","correctAnswer":"It manufactures complex, one-off custom shapes directly from digital scans without needing expensive custom moulds or tooling","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because additive layer-by-layer printing eliminates high fixed tooling costs for unique or small-batch items.","distractor_reasons":{"A":"Incorrect because 3D printing is slower per unit than high-speed injection moulding.","B":"Incorrect because 3D printers require CAD files and printing filaments/powders.","C":"Incorrect because mass-market plastic bottles are much cheaper via flow blow-moulding.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_668","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_668","question":"What is a major limitation of '3D printing' for large-scale mass production?","options":{"A":"Relatively slow printing speeds per unit and limited range of suitable raw materials compared with traditional flow production","B":"Inability to produce customized shapes from CAD files","C":"Excessive need for expensive custom metal moulds for every item","D":"Complete inability to produce prototypes"},"correctOption":"A","correctAnswer":"Relatively slow printing speeds per unit and limited range of suitable raw materials compared with traditional flow production","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because building objects layer by layer takes time, making 3D printing uneconomical for millions of standardized everyday items.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because custom shapes from CAD files are 3D printing's primary strength.","C":"Incorrect because 3D printing avoids custom moulds.","D":"Incorrect because rapid prototyping is a core use of 3D printing."}}},{"id":"P1_U4_MCQ_669","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_669","question":"How do 'Automated Guided Vehicles' (AGVs) and Autonomous Mobile Robots (AMRs) improve warehouse operations?","options":{"A":"They eliminate the need to store any products inside warehouses","B":"They transport and pick pallets or parcels 24 hours a day with high accuracy, reducing human lifting injuries and order-picking errors","C":"They manufacture raw materials inside delivery vans","D":"They replace all customer service call centres"},"correctOption":"B","correctAnswer":"They transport and pick pallets or parcels 24 hours a day with high accuracy, reducing human lifting injuries and order-picking errors","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because autonomous warehouse robots optimize picking routes, operate continuously, and reduce manual handling accidents.","distractor_reasons":{"A":"Incorrect because warehouses still store inventory for distribution.","B":"Correct selection.","C":"Incorrect because AGVs/AMRs handle material movement rather than manufacturing.","D":"Incorrect because call centres use telecommunications/AI chatbots rather than warehouse vehicles."}}},{"id":"P1_U4_MCQ_670","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_670","question":"Besides updating inventory levels, what valuable marketing and operational information does an 'EPOS' system provide to managers?","options":{"A":"Exact data on which products sell fastest, peak shopping hours, and promotional effectiveness, aiding accurate demand forecasting","B":"Live weather forecasts for overseas farming regions","C":"Automatic repair of broken delivery lorries","D":"Guaranteed zero shoplifting across all retail branches"},"correctOption":"A","correctAnswer":"Exact data on which products sell fastest, peak shopping hours, and promotional effectiveness, aiding accurate demand forecasting","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because EPOS records time-stamped sales data by item, helping managers schedule staff rosters and order stock accurately.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because EPOS tracks retail point-of-sale transactions rather than weather.","C":"Incorrect because EPOS is a checkout and inventory IT system.","D":"Incorrect because security prevention requires dedicated loss-prevention measures."}}},{"id":"P1_U4_MCQ_671","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_671","question":"What is a potential operational risk of relying on 'EPOS' and 'EFTPOS' systems in retail stores?","options":{"A":"Customers pay slower with contactless cards than counting coins","B":"Power outages, internet network failures, or software crashes can prevent checkouts from scanning items or processing card payments","C":"Cashiers must manually calculate every item price using mental arithmetic","D":"Inventory records never update when items are scanned"},"correctOption":"B","correctAnswer":"Power outages, internet network failures, or software crashes can prevent checkouts from scanning items or processing card payments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because digital checkout and payment terminals depend on continuous electricity and network connectivity to process transactions.","distractor_reasons":{"A":"Incorrect because contactless EFTPOS is much faster than counting cash.","B":"Correct selection.","C":"Incorrect because EPOS automatically looks up prices from barcode scans.","D":"Incorrect because EPOS updates inventory records automatically."}}},{"id":"P1_U4_MCQ_672","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_672","question":"How does 'predictive maintenance' using Internet of Things (IoT) sensors and AI improve factory reliability?","options":{"A":"Machines never wear out or require spare parts","B":"It waits until a machine breaks down completely before ordering repair engineers","C":"Sensors monitor vibration and temperature in real time to detect early wear, allowing planned repairs before costly unexpected breakdowns occur","D":"It eliminates the need to employ maintenance technicians"},"correctOption":"C","correctAnswer":"Sensors monitor vibration and temperature in real time to detect early wear, allowing planned repairs before costly unexpected breakdowns occur","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because catching abnormal sensor readings early lets engineers schedule maintenance during planned breaks rather than halting active production.","distractor_reasons":{"A":"Incorrect because mechanical parts still experience wear and require servicing.","B":"Incorrect because waiting for failure is reactive maintenance, whereas predictive maintenance prevents breakdowns.","C":"Correct selection.","D":"Incorrect because skilled technicians are still needed to perform the repairs."}}},{"id":"P1_U4_MCQ_673","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_673","question":"Why is 'cybersecurity' a critical operational concern when a business adopts Computer-Integrated Manufacturing (CIM) and cloud-based software?","options":{"A":"Because cybercriminals can steal physical raw materials through Wi-Fi signals","B":"Because cybersecurity software doubles the speed of physical conveyor belts","C":"Because manual hand tools cannot work without antivirus updates","D":"Because ransomware attacks or data breaches can halt interconnected production lines and compromise confidential designs and customer data"},"correctOption":"D","correctAnswer":"Because ransomware attacks or data breaches can halt interconnected production lines and compromise confidential designs and customer data","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because networked production systems and cloud databases face severe operational disruption and legal penalties if breached.","distractor_reasons":{"A":"Incorrect because cyberattacks target digital systems and data rather than physically teleporting raw materials.","B":"Incorrect because cybersecurity protects systems rather than accelerating conveyor motors.","C":"Incorrect because manual tools do not use computers.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_674","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_674","question":"What is meant by 'rapid technological obsolescence' as a risk for businesses investing in high-tech machinery?","options":{"A":"Expensive newly purchased equipment may quickly become outdated by superior, cheaper rival technology before the business recovers its investment cost","B":"New technology never requires software upgrades or replacement","C":"Customers refuse to buy products made with modern machinery","D":"Governments ban factories from upgrading computers more than once a century"},"correctOption":"A","correctAnswer":"Expensive newly purchased equipment may quickly become outdated by superior, cheaper rival technology before the business recovers its investment cost","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fast innovation in IT and robotics can make current systems uncompetitive before they have paid back their high capital cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because technology evolves rapidly and frequently requires upgrades.","C":"Incorrect because consumers welcome improved quality and features from modern tech.","D":"Incorrect because no law restricts technology upgrades."}}},{"id":"P1_U4_MCQ_675","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_675","question":"Why might a small business with low, fluctuating output choose NOT to invest in full factory automation?","options":{"A":"Automated machinery produces lower quality than tired manual workers","B":"Low output volumes cannot spread the high fixed capital cost of automation, resulting in higher average unit costs and poor return on investment","C":"Small businesses are legally prohibited from using computers","D":"Automation increases variable direct wage costs per unit"},"correctOption":"B","correctAnswer":"Low output volumes cannot spread the high fixed capital cost of automation, resulting in higher average unit costs and poor return on investment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because expensive automation requires high, steady output (economies of scale) to justify its upfront cost.","distractor_reasons":{"A":"Incorrect because automation typically produces higher, more consistent quality.","B":"Correct selection.","C":"Incorrect because small firms can freely use computers; the barrier is financial scale.","D":"Incorrect because automation lowers direct variable labour cost per unit."}}},{"id":"P1_U4_MCQ_676","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_676","question":"How do 'self-service checkouts' and 'mobile ordering apps' affect operations in supermarkets and fast-food restaurants?","options":{"A":"They increase the number of cashiers needed at every counter","B":"They eliminate the need to prepare food or stock supermarket shelves","C":"They shift routine order-taking and scanning to customers, reducing counter labour costs per transaction and speeding up peak queues","D":"They prevent customers from paying by debit or credit card"},"correctOption":"C","correctAnswer":"They shift routine order-taking and scanning to customers, reducing counter labour costs per transaction and speeding up peak queues","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because customer self-service handles higher transaction volumes with fewer front-of-house staff.","distractor_reasons":{"A":"Incorrect because self-service reduces front-counter cashier requirements.","B":"Incorrect because staff are still needed to cook food and restock shelves.","C":"Correct selection.","D":"Incorrect because self-service kiosks rely primarily on electronic card/mobile payments."}}},{"id":"P1_U4_MCQ_677","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_677","question":"How can 'reskilling' and 'redeployment' reduce employee resistance when a business introduces automation?","options":{"A":"By making all displaced workers redundant without notice","B":"By cutting wages for workers who agree to operate new machines","C":"By hiding technological plans from trade unions until machines arrive","D":"By training existing staff to operate, program, or maintain the new equipment and moving them into growing roles, protecting job security"},"correctOption":"D","correctAnswer":"By training existing staff to operate, program, or maintain the new equipment and moving them into growing roles, protecting job security","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because investing in existing employees' skills reduces fear of redundancy and builds trust during technological change.","distractor_reasons":{"A":"Incorrect because sudden redundancies provoke strikes and resistance.","B":"Incorrect because cutting wages demotivates staff and fuels opposition.","C":"Incorrect because secrecy creates distrust and rumours.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_678","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_678","question":"How does 'automated optical inspection' (AI cameras on assembly lines) improve quality assurance?","options":{"A":"High-speed cameras inspect 100% of items at full line speed, detecting microscopic defects more reliably than fatigued human eyes","B":"Cameras physically repair cracked glass bottles using laser beams","C":"It eliminates the need for raw materials to meet quality specifications","D":"It slows the assembly line down to one unit per hour"},"correctOption":"A","correctAnswer":"High-speed cameras inspect 100% of items at full line speed, detecting microscopic defects more reliably than fatigued human eyes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because computer-vision cameras check every unit consistently without fatigue, ejecting faulty items immediately.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because optical inspection detects and rejects defects rather than repairing glass.","C":"Incorrect because incoming materials still must meet quality standards.","D":"Incorrect because AI visual inspection operates at high production speeds."}}},{"id":"P1_U4_MCQ_679","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_679","question":"Why do banks and telecommunications companies use 'automated chatbots' for initial customer enquiries?","options":{"A":"Chatbots understand complex emotional complaints better than experienced human advisors","B":"Chatbots handle thousands of routine, repetitive questions simultaneously 24/7 at very low cost per enquiry","C":"Chatbots eliminate the need for any human customer-service staff","D":"Chatbots physically deliver replacement SIM cards to customers' doors"},"correctOption":"B","correctAnswer":"Chatbots handle thousands of routine, repetitive questions simultaneously 24/7 at very low cost per enquiry","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because AI chatbots resolve simple queries (such as balance checks or password resets) instantaneously at scale.","distractor_reasons":{"A":"Incorrect because complex or sensitive issues still require human empathy and judgement.","B":"Correct selection.","C":"Incorrect because human agents remain essential for escalated complex problems.","D":"Incorrect because physical delivery requires postal/courier services."}}},{"id":"P1_U4_MCQ_680","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_680","question":"How does 'cloud-based Enterprise Resource Planning (ERP)' software benefit multi-site operations?","options":{"A":"Each factory branch keeps separate paper records that are mailed once a year","B":"It physically transports raw materials between branches via the internet","C":"It connects purchasing, inventory, production, and sales data in real time across all locations so managers make coordinated decisions","D":"It eliminates the need for internet access across company offices"},"correctOption":"C","correctAnswer":"It connects purchasing, inventory, production, and sales data in real time across all locations so managers make coordinated decisions","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because integrated cloud ERP gives managers live visibility into stock levels, orders, and capacity across the entire organization.","distractor_reasons":{"A":"Incorrect because cloud ERP replaces slow paper reporting with instant digital sharing.","B":"Incorrect because physical goods still require freight transport.","C":"Correct selection.","D":"Incorrect because cloud software requires reliable internet connectivity."}}},{"id":"P1_U4_MCQ_681","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_681","question":"How do 'GPS route-optimization systems' improve delivery and logistics operations?","options":{"A":"They eliminate the need to pay drivers or buy delivery vans","B":"They teleport parcels directly to customers without using roads","C":"They increase fuel consumption by choosing the longest congested routes","D":"They calculate the shortest, least congested delivery routes in real time, saving fuel, driver hours, and late-delivery penalties"},"correctOption":"D","correctAnswer":"They calculate the shortest, least congested delivery routes in real time, saving fuel, driver hours, and late-delivery penalties","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because dynamic routing cuts mileage, fuel expenses, carbon emissions, and missed delivery windows.","distractor_reasons":{"A":"Incorrect because vehicles and drivers are still required.","B":"Incorrect because parcels still travel physically by road.","C":"Incorrect because route optimization minimizes distance and congestion.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_682","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_682","question":"What negative effect can 'digital surveillance and algorithmic pacing' have on warehouse or call-centre workers?","options":{"A":"Constant second-by-second performance tracking can create high stress, lower morale, and higher staff turnover","B":"Workers never receive any feedback on their work speed","C":"It eliminates all shift schedules and performance targets","D":"Workers automatically earn double hourly wages whenever tracked"},"correctOption":"A","correctAnswer":"Constant second-by-second performance tracking can create high stress, lower morale, and higher staff turnover","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because overly rigid digital monitoring can feel dehumanizing and lead to burnout and absenteeism.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because digital monitoring provides continuous, intense performance metrics.","C":"Incorrect because algorithmic systems enforce strict targets.","D":"Incorrect because monitoring does not automatically double wages."}}},{"id":"P1_U4_MCQ_683","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_683","question":"Why is 'interest rate levels' an important factor when evaluating an investment in automated factory technology?","options":{"A":"Higher interest rates make robotic machinery operate twice as fast","B":"Because most expensive technology is funded through loans; higher interest rates raise monthly financing costs and reduce net financial savings","C":"Interest rates determine the variable cost of raw cotton and steel","D":"Banks charge zero interest on loans used for factory technology"},"correctOption":"B","correctAnswer":"Because most expensive technology is funded through loans; higher interest rates raise monthly financing costs and reduce net financial savings","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high borrowing costs can make debt-financed automation unprofitable until interest rates fall.","distractor_reasons":{"A":"Incorrect because interest rates are a financial cost, not a mechanical speed setting.","B":"Correct selection.","C":"Incorrect because raw material prices are driven by commodity supply and demand.","D":"Incorrect because commercial lenders charge interest on business equipment loans."}}},{"id":"P1_U4_MCQ_684","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_684","question":"How can 'telecommuting and remote collaboration software' affect an organization's office operations?","options":{"A":"It forces the company to rent twice as much city-centre office space","B":"It prevents employees from communicating across different time zones","C":"It allows firms to reduce expensive physical office space and recruit skilled talent from wider geographic areas","D":"It applies only to physical assembly-line welding and smelting"},"correctOption":"C","correctAnswer":"It allows firms to reduce expensive physical office space and recruit skilled talent from wider geographic areas","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because digital collaboration enables knowledge workers to work remotely, cutting overhead rent and expanding recruitment pools.","distractor_reasons":{"A":"Incorrect because remote/hybrid work reduces office floor space requirements.","B":"Incorrect because cloud tools facilitate asynchronous and live global collaboration.","C":"Correct selection.","D":"Incorrect because physical factory tasks require on-site presence."}}},{"id":"P1_U4_MCQ_685","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_685","question":"What is a key difference between 'e-commerce' and traditional brick-and-mortar retail operations?","options":{"A":"E-commerce businesses never hold any inventory or deliver physical parcels","B":"Brick-and-mortar shops operate 24 hours a day without human staff","C":"E-commerce eliminates all cybersecurity and website maintenance costs","D":"E-commerce replaces expensive high-street retail storefronts with centralized fulfilment warehouses and courier delivery networks"},"correctOption":"D","correctAnswer":"E-commerce replaces expensive high-street retail storefronts with centralized fulfilment warehouses and courier delivery networks","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because online retailers save high-street shop rents while investing heavily in websites, automated warehouses, and last-mile delivery.","distractor_reasons":{"A":"Incorrect because e-commerce retailers selling physical goods rely on warehouses and couriers.","B":"Incorrect because physical stores have set opening hours and store staff.","C":"Incorrect because e-commerce depends heavily on website hosting and cybersecurity.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_686","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_686","question":"Why do modern automated factories still require skilled human engineers and technicians?","options":{"A":"To program software, supervise control rooms, diagnose faults, maintain precision equipment, and drive continuous Kaizen improvements","B":"To push heavy conveyor belts manually when electricity is switched off","C":"Because robots cannot perform repetitive tasks accurately","D":"Because laws prohibit any machine from running without a human standing next to it"},"correctOption":"A","correctAnswer":"To program software, supervise control rooms, diagnose faults, maintain precision equipment, and drive continuous Kaizen improvements","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automated systems rely on human expertise for setup, software updates, preventative maintenance, and problem-solving.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because conveyor lines are powered by electric motors.","C":"Incorrect because robots excel at repetitive accuracy.","D":"Incorrect because automated lines run autonomously under control-room supervision."}}},{"id":"P1_U4_MCQ_687","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_687","question":"How does 'digital twin' simulation software help operations managers before reorganising a factory floor?","options":{"A":"It physically moves heavy steel presses using wireless signals","B":"Managers can test layout changes and spot bottlenecks in a virtual computer replica of the factory without disrupting live production","C":"It eliminates the need to hire any factory workers","D":"It manufactures finished products out of computer pixels"},"correctOption":"B","correctAnswer":"Managers can test layout changes and spot bottlenecks in a virtual computer replica of the factory without disrupting live production","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because virtual simulation identifies workflow delays and optimizes layouts safely before spending money on physical changes.","distractor_reasons":{"A":"Incorrect because physical equipment still must be moved mechanically.","B":"Correct selection.","C":"Incorrect because factories still require human operators and technicians.","D":"Incorrect because digital twins simulate physical processes rather than creating physical goods."}}},{"id":"P1_U4_MCQ_688","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_688","question":"What is a potential drawback of 'inflexibility' in specialized automated assembly lines?","options":{"A":"Machines produce identical products too quickly","B":"Direct labour wages per unit are too low","C":"If consumer tastes shift suddenly to a different design, expensive specialized machinery may require costly retooling or replacement","D":"Workers have too much freedom to change product designs hourly"},"correctOption":"C","correctAnswer":"If consumer tastes shift suddenly to a different design, expensive specialized machinery may require costly retooling or replacement","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because dedicated high-speed equipment is built for specific designs, making sudden market shifts expensive to accommodate.","distractor_reasons":{"A":"Incorrect because fast output is an advantage rather than a drawback.","B":"Incorrect because low unit labour cost is a financial benefit.","C":"Correct selection.","D":"Incorrect because automated lines follow fixed programmed specifications."}}},{"id":"P1_U4_MCQ_689","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_689","question":"How do 'electronic inventory reorder systems' reduce the risk of human error in stock management?","options":{"A":"By ordering random quantities of stock regardless of sales","B":"By locking warehouse doors so no stock can ever leave","C":"By eliminating the need for suppliers to deliver goods","D":"By automatically tracking stock levels from barcode/RFID scans and sending exact electronic orders the moment inventory hits the reorder point"},"correctOption":"D","correctAnswer":"By automatically tracking stock levels from barcode/RFID scans and sending exact electronic orders the moment inventory hits the reorder point","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because automated stock triggers prevent forgotten orders, miscounted clipboard tallies, and unexpected stockouts.","distractor_reasons":{"A":"Incorrect because automated systems order exact pre-calculated economic quantities.","B":"Incorrect because inventory systems facilitate smooth stock flow.","C":"Incorrect because suppliers still deliver physical replenishment stock.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_690","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_690","question":"What is a key benefit of 'contactless mobile wallets' (such as NFC phone payments) for retail and transit operators?","options":{"A":"Transactions complete in under a second, speeding up passenger/shopper throughput and reducing cash-handling security risks","B":"Retailers pay zero electricity bills for checkout terminals","C":"Customers can pay without having a bank account or payment card","D":"It slows down queue movement to encourage impulse buying"},"correctOption":"A","correctAnswer":"Transactions complete in under a second, speeding up passenger/shopper throughput and reducing cash-handling security risks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid tap-to-pay processing eliminates cash change delays and lowers cash theft/counting costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because payment terminals consume electricity.","C":"Incorrect because mobile wallets link to underlying bank accounts or cards.","D":"Incorrect because contactless payments accelerate checkout throughput."}}},{"id":"P1_U4_MCQ_691","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_691","question":"How does 'automated packaging machinery' improve food and pharmaceutical manufacturing?","options":{"A":"It eliminates the need to manufacture food or medicine","B":"It seals products rapidly in sterile, airtight conditions without human contact, extending shelf life and preventing contamination","C":"It uses twice as much plastic film as manual wrapping","D":"It slows down production lines to prevent worker boredom"},"correctOption":"B","correctAnswer":"It seals products rapidly in sterile, airtight conditions without human contact, extending shelf life and preventing contamination","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because hygienic automated sealing protects sensitive consumables from bacteria and tampering at high speeds.","distractor_reasons":{"A":"Incorrect because products still must be manufactured before packaging.","B":"Correct selection.","C":"Incorrect because precision machines measure exact film lengths, reducing packaging waste.","D":"Incorrect because automated packaging accelerates line speeds."}}},{"id":"P1_U4_MCQ_692","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_692","question":"Why might employees initially resist the introduction of new computer systems or robotics in a workplace?","options":{"A":"Fear of job loss, anxiety about learning unfamiliar technical skills, and disruption to established team routines","B":"Concern that working conditions will become too safe and clean","C":"Fear that customer satisfaction will rise too high","D":"Belief that new computers will double their annual paid holidays"},"correctOption":"A","correctAnswer":"Fear of job loss, anxiety about learning unfamiliar technical skills, and disruption to established team routines","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fear of redundancy and lack of confidence with new technology are primary drivers of workplace resistance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because employees welcome safer, cleaner workplaces.","C":"Incorrect because workers do not oppose higher customer satisfaction.","D":"Incorrect because new technology does not automatically double holidays."}}},{"id":"P1_U4_MCQ_693","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_693","question":"How can management overcome employee resistance when introducing new production technology?","options":{"A":"By refusing to answer worker questions and threatening immediate dismissal","B":"By consulting workers early, communicating clear reasons for the change, and providing paid training and support","C":"By installing machines overnight without telling anyone","D":"By banning all training so workers learn by trial and error"},"correctOption":"B","correctAnswer":"By consulting workers early, communicating clear reasons for the change, and providing paid training and support","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because open communication, consultation, and thorough training reduce fear and build employee commitment.","distractor_reasons":{"A":"Incorrect because threats provoke hostility, low morale, and industrial action.","B":"Correct selection.","C":"Incorrect because surprise installations destroy trust.","D":"Incorrect because lack of training causes errors, accidents, and stress."}}},{"id":"P1_U4_MCQ_694","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_694","question":"What is a major benefit of 'automated parcel sorting hubs' using optical barcode/RFID scanners and diverter belts?","options":{"A":"Elimination of all delivery vans and cargo aircraft","B":"Zero electricity consumption during night sorting shifts","C":"Tens of thousands of parcels are sorted accurately per hour with minimal misrouted deliveries or manual lifting strain","D":"Customers must visit the central sorting hub to collect their own parcels"},"correctOption":"C","correctAnswer":"Tens of thousands of parcels are sorted accurately per hour with minimal misrouted deliveries or manual lifting strain","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because high-speed automated sortation dramatically increases throughput capacity and routing accuracy.","distractor_reasons":{"A":"Incorrect because vehicles and planes are still needed for transport between hubs and homes.","B":"Incorrect because automated sorting hubs consume substantial electrical power.","C":"Correct selection.","D":"Incorrect because sorted parcels are dispatched to local depots for home delivery."}}},{"id":"P1_U4_MCQ_695","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_695","question":"How does 'online appointment booking and digital queuing software' improve service operations in clinics or salons?","options":{"A":"It eliminates the need for qualified doctors or stylists","B":"It forces all customers to wait in crowded waiting rooms for hours","C":"It prevents customers from cancelling or rescheduling appointments","D":"It fills staff schedules efficiently 24/7, sends automated reminders to reduce missed appointments, and lowers receptionist workload"},"correctOption":"D","correctAnswer":"It fills staff schedules efficiently 24/7, sends automated reminders to reduce missed appointments, and lowers receptionist workload","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because automated scheduling maximizes staff capacity utilization and reduces costly 'no-shows'.","distractor_reasons":{"A":"Incorrect because skilled professionals still deliver the personal service.","B":"Incorrect because scheduled slots and digital queue alerts reduce waiting-room crowding.","C":"Incorrect because self-service portals let clients reschedule easily, freeing slots for others.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_696","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_696","question":"Which statement accurately compares the cost structure of a highly automated factory with a manual labour-intensive workshop?","options":{"A":"The automated factory has higher fixed costs (depreciation, loan interest, IT maintenance) and lower variable labour costs per unit","B":"The automated factory has zero fixed costs and very high variable piece-rate wages","C":"Both operations have identical fixed and variable cost structures","D":"The manual workshop has higher machinery depreciation than the automated factory"},"correctOption":"A","correctAnswer":"The automated factory has higher fixed costs (depreciation, loan interest, IT maintenance) and lower variable labour costs per unit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because replacing variable human labour with expensive capital equipment shifts costs from variable to fixed.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the cost profile is the exact opposite.","C":"Incorrect because automation fundamentally alters the ratio of fixed to variable costs.","D":"Incorrect because a manual workshop owns minimal machinery."}}},{"id":"P1_U4_MCQ_697","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_697","question":"How does 'computer-controlled energy management' in smart factories and offices support both technology adoption and cost control?","options":{"A":"It keeps all lights and heating running at maximum power on weekends","B":"Automated sensors and software adjust lighting, heating, and machine standby power based on occupancy and production schedules, cutting utility waste","C":"It generates free coal and crude oil inside office basements","D":"It disables all safety alarms during night shifts"},"correctOption":"B","correctAnswer":"Automated sensors and software adjust lighting, heating, and machine standby power based on occupancy and production schedules, cutting utility waste","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because smart building and machine controls eliminate idle energy drain, lowering operating expenses and emissions.","distractor_reasons":{"A":"Incorrect because smart systems power down unused zones automatically.","B":"Correct selection.","C":"Incorrect because energy management saves electricity rather than creating fossil fuels.","D":"Incorrect because safety systems remain active at all times."}}},{"id":"P1_U4_MCQ_698","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_698","question":"What is a key advantage of 'digital documentation and paperless workflows' in operations management?","options":{"A":"Paper files are easier to lose in fire or flood disasters","B":"Managers spend more hours searching physical filing cabinets","C":"Instant retrieval of orders, quality checklists, and supplier records across teams while cutting paper, printing, and storage costs","D":"It eliminates the need to back up company data"},"correctOption":"C","correctAnswer":"Instant retrieval of orders, quality checklists, and supplier records across teams while cutting paper, printing, and storage costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because searchable digital records accelerate coordination, reduce errors, and save stationery and filing space.","distractor_reasons":{"A":"Incorrect because cloud-backed digital files are safer from physical fire/flood loss than paper.","B":"Incorrect because digital search takes seconds compared with manual filing cabinets.","C":"Correct selection.","D":"Incorrect because regular automated backups remain essential for digital security."}}},{"id":"P1_U4_MCQ_699","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_699","question":"Why is 'system compatibility and integration' important when a business upgrades its operations technology?","options":{"A":"Because incompatible software systems force workers to re-type data manually between departments, creating delays and errors","B":"Because compatible software eliminates the need to buy raw materials","C":"Because incompatible machines never consume electricity","D":"Because governments fine businesses that use more than one computer"},"correctOption":"A","correctAnswer":"Because incompatible software systems force workers to re-type data manually between departments, creating delays and errors","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because new CAD, EPOS, or warehouse tools must communicate smoothly with existing accounting and inventory systems to deliver full efficiency.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raw materials are still needed for production.","C":"Incorrect because all machines consume power regardless of compatibility.","D":"Incorrect because no law restricts the number of computers a business uses."}}},{"id":"P1_U4_MCQ_700","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_700","question":"How does 'electronic data interchange' (EDI) improve supply-chain coordination between a manufacturer and its component suppliers?","options":{"A":"Purchase orders, shipping notices, and invoices pass automatically between company computers in seconds, enabling reliable JIT deliveries","B":"Orders must be handwritten and sent by sea mail taking six weeks","C":"EDI physically manufactures steel components inside telephone cables","D":"EDI eliminates the need for transport lorries between supplier and factory"},"correctOption":"A","correctAnswer":"Purchase orders, shipping notices, and invoices pass automatically between company computers in seconds, enabling reliable JIT deliveries","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because direct computer-to-computer EDI eliminates postal delays and manual order-entry errors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because EDI replaces slow paper mail with instant digital transmission.","C":"Incorrect because EDI transmits commercial documents rather than physical goods.","D":"Incorrect because physical goods still travel by lorry."}}},{"id":"P1_U4_MCQ_701","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_701","question":"When evaluating whether to invest in new production technology, which combination of factors should managers assess?","options":{"A":"Capital purchase cost, expected labour/waste savings, forecast sales volume, staff training needs, and impact on product quality","B":"Only the colour of the machinery casing and the brand of office coffee","C":"Only short-term savings in Week 1 while ignoring loan interest and maintenance costs","D":"Whether competitors will voluntarily shut down their factories"},"correctOption":"A","correctAnswer":"Capital purchase cost, expected labour/waste savings, forecast sales volume, staff training needs, and impact on product quality","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sound technology investment appraisal weighs upfront and ongoing costs against productivity, quality, and demand volume.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cosmetic preferences are irrelevant to financial and operational viability.","C":"Incorrect because ignoring financing, maintenance, and payback period leads to poor investment decisions.","D":"Incorrect because competitors will respond competitively rather than closing voluntarily."}}},{"id":"P1_U4_MCQ_702","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_702","question":"Which statement best defines 'non-renewable resources'?","options":{"A":"Resources such as sunlight and wind that are continuously replenished by nature","B":"Finite natural resources such as coal, crude oil, natural gas, and metal ores that cannot be replaced once extracted and consumed","C":"Recycled cardboard boxes and compostable food waste","D":"Trees planted in sustainably managed forestry plantations"},"correctOption":"B","correctAnswer":"Finite natural resources such as coal, crude oil, natural gas, and metal ores that cannot be replaced once extracted and consumed","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because non-renewable resources exist in fixed geological quantities and deplete permanently as they are extracted.","distractor_reasons":{"A":"Incorrect because sunlight and wind are renewable energy resources.","B":"Correct selection.","C":"Incorrect because recycled and compostable materials are circular/renewable inputs.","D":"Incorrect because replanted forestry timber is a renewable biological resource."}}},{"id":"P1_U4_MCQ_703","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_703","question":"Why does transitioning from fossil fuels to 'renewable energy' (such as solar, wind, or hydroelectricity) make production more sustainable?","options":{"A":"Renewable power stations burn natural gas more rapidly than coal plants","B":"Renewable energy installations require zero upfront construction cost","C":"Renewable energy relies on naturally replenished sources and generates electricity without greenhouse gas emissions during operation","D":"Renewable energy allows factories to waste unlimited electricity without paying bills"},"correctOption":"C","correctAnswer":"Renewable energy relies on naturally replenished sources and generates electricity without greenhouse gas emissions during operation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because clean renewables conserve finite fossil fuel reserves and cut carbon emissions driving climate change.","distractor_reasons":{"A":"Incorrect because solar, wind, and hydro do not burn fossil fuels.","B":"Incorrect because building solar arrays and wind turbines involves high initial capital outlay.","C":"Correct selection.","D":"Incorrect because sustainable operations still prioritize energy efficiency."}}},{"id":"P1_U4_MCQ_704","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_704","question":"What is a potential operational limitation of relying solely on on-site solar or wind power for a 24-hour factory?","options":{"A":"Solar and wind power emit high levels of toxic smoke","B":"Solar panels and wind turbines use finite coal reserves","C":"Renewable electricity is illegal in industrial zones","D":"Intermittent weather conditions (nighttime or calm winds) mean energy storage batteries or grid backup power are required for continuous operation"},"correctOption":"D","correctAnswer":"Intermittent weather conditions (nighttime or calm winds) mean energy storage batteries or grid backup power are required for continuous operation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because variable weather generation requires battery storage or grid connection to guarantee uninterrupted power.","distractor_reasons":{"A":"Incorrect because solar and wind generate zero smoke or direct emissions.","B":"Incorrect because solar and wind use sunlight and air currents rather than coal.","C":"Incorrect because governments actively encourage industrial renewable generation.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_705","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_705","question":"How does 'closed-loop water recycling' in manufacturing support sustainable production?","options":{"A":"Wastewater is filtered, treated, and reused repeatedly inside the plant, conserving freshwater supplies and preventing river pollution","B":"Untreated chemical wastewater is pumped directly into local rivers","C":"It increases freshwater consumption per unit produced","D":"It eliminates the need for electricity to run pumps"},"correctOption":"A","correctAnswer":"Wastewater is filtered, treated, and reused repeatedly inside the plant, conserving freshwater supplies and preventing river pollution","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because recirculating process water cuts freshwater extraction, lowers utility bills, and protects aquatic ecosystems.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because dumping untreated effluent causes severe pollution and legal penalties.","C":"Incorrect because closed-loop systems reduce freshwater intake.","D":"Incorrect because filtration and pumping still use electrical power."}}},{"id":"P1_U4_MCQ_706","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_706","question":"What is meant by 'product lightweighting' as a method of using fewer natural resources?","options":{"A":"Filling product boxes with heavy lead weights","B":"Redesigning products and containers to use thinner, stronger materials that achieve the same performance with less raw material and lower transport fuel","C":"Making products fragile so they break immediately after purchase","D":"Increasing the amount of virgin plastic used in every bottle"},"correctOption":"B","correctAnswer":"Redesigning products and containers to use thinner, stronger materials that achieve the same performance with less raw material and lower transport fuel","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because reducing material mass per unit saves raw resources at the factory and cuts fuel emissions during freight transport.","distractor_reasons":{"A":"Incorrect because adding unnecessary weight wastes materials and transport fuel.","B":"Correct selection.","C":"Incorrect because sustainable lightweighting maintains strength and durability.","D":"Incorrect because lightweighting decreases rather than increases plastic use."}}},{"id":"P1_U4_MCQ_707","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_707","question":"Why is 'reusing' materials or containers generally even more environmentally friendly than 'recycling' them?","options":{"A":"Because reusing requires melting materials in high-temperature furnaces","B":"Because recycled materials can never be used more than once","C":"Because reusing uses the intact item again with minimal energy (only cleaning/transport), whereas recycling requires energy-intensive shredding, melting, and remanufacturing","D":"Because reusing sends all waste directly to landfill sites"},"correctOption":"C","correctAnswer":"Because reusing uses the intact item again with minimal energy (only cleaning/transport), whereas recycling requires energy-intensive shredding, melting, and remanufacturing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because preserving the product's existing physical structure saves the energy and emissions needed to reprocess raw materials.","distractor_reasons":{"A":"Incorrect because melting in furnaces describes recycling rather than reusing.","B":"Incorrect because metals and glass can be recycled repeatedly.","C":"Correct selection.","D":"Incorrect because reusing keeps items in active circulation and out of landfills."}}},{"id":"P1_U4_MCQ_708","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_708","question":"What is a practical challenge of operating a 'reusable container deposit-and-return scheme' for a beverage or food producer?","options":{"A":"Reusable glass bottles break after a single use","B":"Customers hate receiving deposit refunds when returning bottles","C":"Reusable bottles require no washing or sterilization before refilling","D":"Reverse logistics costs of collecting, transporting, inspecting, and sterilizing empty containers across wide geographic areas"},"correctOption":"D","correctAnswer":"Reverse logistics costs of collecting, transporting, inspecting, and sterilizing empty containers across wide geographic areas","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because managing reverse collection routes and hygiene sterilization adds operational complexity and transport cost.","distractor_reasons":{"A":"Incorrect because returnable glass bottles are made thicker to survive dozens of refill cycles.","B":"Incorrect because deposit refunds incentivize customer returns.","C":"Incorrect because strict food-safety sterilization is mandatory before refilling.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_709","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_709","question":"How does using 'recycled raw materials' (such as recycled aluminium, steel, or paper pulp) benefit a manufacturer?","options":{"A":"It often uses significantly less energy and water than extracting and refining virgin ores or timber, lowering utility costs and environmental impact","B":"It increases mining destruction and deforestation","C":"Recycled metals and paper always cost ten times more than virgin materials","D":"It eliminates the need to manufacture products in factories"},"correctOption":"A","correctAnswer":"It often uses significantly less energy and water than extracting and refining virgin ores or timber, lowering utility costs and environmental impact","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because secondary recycled feedstocks bypass energy-intensive mining and primary smelting.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because recycling reduces the need for virgin mining and logging.","C":"Incorrect because recycled inputs are frequently cost-competitive due to energy savings.","D":"Incorrect because recycled inputs still undergo factory manufacturing."}}},{"id":"P1_U4_MCQ_710","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_710","question":"What is a potential limitation of using 'recycled materials' in manufacturing?","options":{"A":"Recycled inputs always emit more carbon than mining virgin ore","B":"Inconsistent quality, contamination in collected waste streams, or limited supply of clean sorted recyclables can affect product strength or appearance","C":"Consumers boycott products made from recycled materials","D":"Governments impose heavy taxes on companies that use recycled content"},"correctOption":"B","correctAnswer":"Inconsistent quality, contamination in collected waste streams, or limited supply of clean sorted recyclables can affect product strength or appearance","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because post-consumer waste sorting can leave impurities or degraded fibres, requiring careful quality assurance.","distractor_reasons":{"A":"Incorrect because recycled materials typically have a lower carbon footprint than virgin inputs.","B":"Correct selection.","C":"Incorrect because eco-conscious consumers actively support recycled content.","D":"Incorrect because governments often incentivize recycled content."}}},{"id":"P1_U4_MCQ_711","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_711","question":"How does 'lean production' naturally support environmental sustainability?","options":{"A":"By encouraging overproduction of unsold goods","B":"By replacing renewable energy with coal power","C":"By eliminating defects, overproduction, excess inventory, and unnecessary transport, thereby conserving raw materials, energy, and landfill space","D":"By increasing packaging layers on every item"},"correctOption":"C","correctAnswer":"By eliminating defects, overproduction, excess inventory, and unnecessary transport, thereby conserving raw materials, energy, and landfill space","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cutting operational waste directly reduces wasted materials, scrap disposal, and unnecessary freight fuel.","distractor_reasons":{"A":"Incorrect because lean production eliminates overproduction.","B":"Incorrect because lean operations seek energy efficiency rather than fossil fuels.","C":"Correct selection.","D":"Incorrect because lean design minimizes excess packaging."}}},{"id":"P1_U4_MCQ_712","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_712","question":"What is meant by 'biodegradable' or 'compostable' packaging?","options":{"A":"Packaging made from heavy lead and PVC that never breaks down","B":"Packaging that must be burned in open fires after use","C":"Packaging designed to remain intact in oceans for 500 years","D":"Packaging made from natural organic materials that break down safely into water, carbon dioxide, and harmless biomass through natural microorganisms"},"correctOption":"D","correctAnswer":"Packaging made from natural organic materials that break down safely into water, carbon dioxide, and harmless biomass through natural microorganisms","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because biodegradable packaging decomposes naturally without leaving persistent microplastics or toxic residues.","distractor_reasons":{"A":"Incorrect because heavy metals and PVC are non-biodegradable pollutants.","B":"Incorrect because open burning releases toxic smoke.","C":"Incorrect because persistent marine waste is non-biodegradable.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_713","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_713","question":"What is meant by 'designing for durability and repairability' in sustainable product development?","options":{"A":"Building products with high-quality parts and accessible screws/modular components so worn parts can be repaired rather than throwing the whole product away","B":"Designing products to fail immediately after the warranty expires","C":"Gluing batteries permanently inside devices so users must buy a brand-new device when the battery wears out","D":"Using the cheapest, weakest materials to lower product lifespan"},"correctOption":"A","correctAnswer":"Building products with high-quality parts and accessible screws/modular components so worn parts can be repaired rather than throwing the whole product away","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because longer-lasting, repairable goods slow down resource extraction and drastically cut electronic and household waste.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because planned obsolescence is the opposite of sustainable design.","C":"Incorrect because non-replaceable batteries force premature replacement.","D":"Incorrect because weak materials shorten lifespan and increase waste."}}},{"id":"P1_U4_MCQ_714","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_714","question":"What is a potential commercial dilemma for a manufacturer that designs ultra-durable products lasting twice as long?","options":{"A":"Customers complain that the product is too reliable","B":"Repeat replacement sales may occur less frequently, requiring the business to attract new customers or sell spare parts/maintenance services","C":"Governments fine companies whose products last too long","D":"Durable products always cost less to manufacture than disposable ones"},"correctOption":"B","correctAnswer":"Repeat replacement sales may occur less frequently, requiring the business to attract new customers or sell spare parts/maintenance services","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because longer replacement cycles can slow repeat unit sales, prompting sustainable firms to offer repair services, upgrades, or subscription models.","distractor_reasons":{"A":"Incorrect because customers value durability and reliability.","B":"Correct selection.","C":"Incorrect because regulators increasingly encourage 'right to repair' and durability.","D":"Incorrect because durable components often have higher initial manufacturing costs."}}},{"id":"P1_U4_MCQ_715","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_715","question":"How does reducing 'packaging volume' (making boxes more compact) lower a business's transport costs and carbon footprint?","options":{"A":"More units fit into every delivery lorry or shipping container, reducing the total number of journeys and fuel burned","B":"Compact boxes weigh ten times more than oversized boxes","C":"Smaller packages require delivery lorries to drive twice as many trips","D":"Compact packaging eliminates the need for delivery vehicles"},"correctOption":"A","correctAnswer":"More units fit into every delivery lorry or shipping container, reducing the total number of journeys and fuel burned","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because eliminating empty air inside boxes maximizes freight load efficiency per truckload.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because compact boxes use less cardboard and weigh less.","C":"Incorrect because higher packing density reduces total trips.","D":"Incorrect because goods still require physical freight transport."}}},{"id":"P1_U4_MCQ_716","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_716","question":"What is meant by 'carbon footprint' in business operations?","options":{"A":"The physical size of a factory's concrete foundations","B":"The total amount of greenhouse gases (such as carbon dioxide) emitted directly and indirectly by a business's production, transport, and operations","C":"The total weight of coal stored in a power station","D":"The number of employees walking to work each morning"},"correctOption":"B","correctAnswer":"The total amount of greenhouse gases (such as carbon dioxide) emitted directly and indirectly by a business's production, transport, and operations","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because measuring the carbon footprint helps businesses identify energy, manufacturing, and transport hotspots to decarbonize.","distractor_reasons":{"A":"Incorrect because building floor area is physical footprint, not carbon footprint.","B":"Correct selection.","C":"Incorrect because coal stockpile weight is raw material inventory.","D":"Incorrect because walking commutes generate zero carbon emissions."}}},{"id":"P1_U4_MCQ_717","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_717","question":"How can 'sourcing raw materials locally' contribute to sustainable production?","options":{"A":"It increases air-freight emissions across continents","B":"It guarantees that raw materials are completely free","C":"It shortens transport distances ('food/product miles'), cuts fossil-fuel emissions, and supports local communities","D":"It eliminates the need for quality assurance checks"},"correctOption":"C","correctAnswer":"It shortens transport distances ('food/product miles'), cuts fossil-fuel emissions, and supports local communities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because local procurement reduces long-haul freight fuel and strengthens regional supply resilience.","distractor_reasons":{"A":"Incorrect because local sourcing avoids long-distance air freight.","B":"Incorrect because local suppliers still charge market prices.","C":"Correct selection.","D":"Incorrect because local inputs still require quality checks."}}},{"id":"P1_U4_MCQ_718","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_718","question":"Why do many large retail chains now require their suppliers to meet strict environmental and sustainability standards?","options":{"A":"Because retailers want to pay higher wholesale prices for defective goods","B":"Because environmental laws apply only to small corner shops","C":"Because sustainable suppliers never require delivery lorries","D":"To protect the retailer's own brand reputation, meet corporate sustainability targets, and satisfy eco-conscious shoppers"},"correctOption":"D","correctAnswer":"To protect the retailer's own brand reputation, meet corporate sustainability targets, and satisfy eco-conscious shoppers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retailers face scrutiny over their entire supply chain and drop suppliers that cause pollution or deforestation.","distractor_reasons":{"A":"Incorrect because retailers demand high quality and competitive prices alongside sustainability.","B":"Incorrect because large corporations face the strictest environmental reporting laws.","C":"Incorrect because deliveries are still required.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_719","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_719","question":"What is meant by 'circular economy' principles in sustainable operations?","options":{"A":"Designing products and processes so materials are continuously reused, repaired, refurbished, and recycled rather than discarded after single use","B":"Building circular factory buildings with no corners","C":"Extracting raw materials, making products, and dumping them in landfill ('take-make-waste')","D":"Transporting goods in circles around motorways"},"correctOption":"A","correctAnswer":"Designing products and processes so materials are continuously reused, repaired, refurbished, and recycled rather than discarded after single use","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a circular model keeps resources in productive use indefinitely, eliminating waste and virgin resource depletion.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because circular economy refers to resource loops, not building geometry.","C":"Incorrect because 'take-make-waste' describes the unsustainable linear economy.","D":"Incorrect because unnecessary driving is transportation waste."}}},{"id":"P1_U4_MCQ_720","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_720","question":"Why might a business operating in a highly price-competitive mass market hesitate to adopt expensive sustainable production methods?","options":{"A":"Because sustainable production is illegal in mass markets","B":"Because passing higher green production costs onto customers through higher prices could cause price-sensitive buyers to switch to cheaper rivals","C":"Because sustainable methods always double factory output immediately","D":"Because governments tax companies that use renewable solar energy"},"correctOption":"B","correctAnswer":"Because passing higher green production costs onto customers through higher prices could cause price-sensitive buyers to switch to cheaper rivals","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because where price elasticity of demand is high, higher unit costs cannot easily be passed on without losing market share.","distractor_reasons":{"A":"Incorrect because sustainability is encouraged rather than illegal.","B":"Correct selection.","C":"Incorrect because green inputs often raise unit cost without doubling output.","D":"Incorrect because governments subsidize rather than tax solar energy."}}},{"id":"P1_U4_MCQ_721","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_721","question":"How can 'environmental pressure groups' (NGOs) influence a business to adopt sustainable production?","options":{"A":"By passing national laws and imprisoning company directors directly","B":"By providing free raw materials to polluting factories","C":"By organizing consumer boycotts, media campaigns, and protests against polluting firms, threatening sales and brand reputation","D":"By buying all shares of every multinational company"},"correctOption":"C","correctAnswer":"By organizing consumer boycotts, media campaigns, and protests against polluting firms, threatening sales and brand reputation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because public exposure and boycotts force businesses to clean up operations to protect revenue and brand value.","distractor_reasons":{"A":"Incorrect because only governments and courts pass and enforce laws.","B":"Incorrect because pressure groups campaign against polluters rather than subsidizing them.","C":"Correct selection.","D":"Incorrect because NGOs rely on public advocacy rather than buying entire corporations."}}},{"id":"P1_U4_MCQ_722","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_722","question":"What is meant by 'sustainable forestry or fishing certification' (such as FSC timber or MSC seafood)?","options":{"A":"A permit allowing companies to cut down entire rainforests without replanting","B":"A government tax on recycled paper products","C":"A licence to dump industrial waste into oceans","D":"Independent verification that renewable biological resources are harvested at rates allowing natural regeneration without harming ecosystems"},"correctOption":"D","correctAnswer":"Independent verification that renewable biological resources are harvested at rates allowing natural regeneration without harming ecosystems","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because certification assures buyers and consumers that renewable resources are managed responsibly for future generations.","distractor_reasons":{"A":"Incorrect because sustainable forestry requires selective harvesting and replanting.","B":"Incorrect because certification is an ethical supply standard, not a tax.","C":"Incorrect because sustainable certification prohibits pollution.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_723","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_723","question":"How does 'heat recovery' in industrial plants improve both sustainability and profitability?","options":{"A":"Waste heat from furnaces or engines is captured to warm factory buildings or generate electricity, cutting fossil-fuel purchases and emissions","B":"Factories vent all furnace heat directly into the atmosphere to warm the sky","C":"It increases natural gas consumption by 50%","D":"It eliminates the need to insulate factory roofs"},"correctOption":"A","correctAnswer":"Waste heat from furnaces or engines is captured to warm factory buildings or generate electricity, cutting fossil-fuel purchases and emissions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because capturing thermal energy that would otherwise be wasted lowers primary fuel bills and carbon output.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because venting heat wastes energy.","C":"Incorrect because heat recovery reduces fuel consumption.","D":"Incorrect because good building insulation works alongside heat recovery."}}},{"id":"P1_U4_MCQ_724","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_724","question":"Why is 'employee training and engagement' essential for the success of a workplace sustainability programme?","options":{"A":"Because employees pay for all solar panels out of their own wages","B":"Because daily habits—such as sorting recyclables, turning off idle machinery, and spotting leaks—depend on consistent staff participation","C":"Because machines refuse to run unless workers attend sustainability lectures","D":"Because sustainability eliminates the need for operational managers"},"correctOption":"B","correctAnswer":"Because daily habits—such as sorting recyclables, turning off idle machinery, and spotting leaks—depend on consistent staff participation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because environmental policies fail unless front-line staff understand and apply waste and energy rules every day.","distractor_reasons":{"A":"Incorrect because the business funds capital equipment.","B":"Correct selection.","C":"Incorrect because machinery runs mechanically, though operators control idle power.","D":"Incorrect because managers coordinate and monitor sustainability targets."}}},{"id":"P1_U4_MCQ_725","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_725","question":"What is a key difference between 'short-term' and 'long-term' financial impacts of sustainable production?","options":{"A":"Sustainable production always lowers short-term costs in Day 1 and loses money in the long term","B":"Sustainable investments have zero financial impact in either the short term or long term","C":"Sustainable investments often increase short-term capital and training costs, but generate long-term energy/waste savings, brand loyalty, and regulatory resilience","D":"Long-term energy prices never affect business profitability"},"correctOption":"C","correctAnswer":"Sustainable investments often increase short-term capital and training costs, but generate long-term energy/waste savings, brand loyalty, and regulatory resilience","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because evaluating sustainability requires looking beyond immediate upfront outlays to multi-year operational savings and brand value.","distractor_reasons":{"A":"Incorrect because the timeline is reversed: upfront costs occur first, followed by long-term savings.","B":"Incorrect because sustainability affects both capital expenditure and ongoing operating costs.","C":"Correct selection.","D":"Incorrect because energy costs are a major long-term operating expense."}}},{"id":"P1_U4_MCQ_726","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_726","question":"How does 'ethical and sustainable sourcing' reduce long-term supply-chain risk for a business?","options":{"A":"By depleting soil, forests, and water supplies as fast as possible","B":"By relying on a single polluting supplier in an unstable region","C":"By eliminating all supplier contracts and quality audits","D":"By protecting ecosystems and supporting fair supplier livelihoods, ensuring reliable, uninterrupted raw material supplies into the future"},"correctOption":"D","correctAnswer":"By protecting ecosystems and supporting fair supplier livelihoods, ensuring reliable, uninterrupted raw material supplies into the future","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because over-exploiting natural habitats or underpaying farmers eventually destroys supply sources; sustainable sourcing secures future inputs.","distractor_reasons":{"A":"Incorrect because resource depletion causes future shortages and price spikes.","B":"Incorrect because relying on one polluting supplier creates high disruption risk.","C":"Incorrect because ethical sourcing relies on formal contracts and audits.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_727","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_727","question":"Which business practice demonstrates 'reducing water footprint' in agricultural or textile production?","options":{"A":"Using precision drip irrigation and waterless dyeing technologies instead of flooding fields and discharging toxic dye water","B":"Flooding cotton fields continuously during severe droughts","C":"Draining untreated chemical dye vats into local streams","D":"Using single-use plastic water bottles in staff canteens"},"correctOption":"A","correctAnswer":"Using precision drip irrigation and waterless dyeing technologies instead of flooding fields and discharging toxic dye water","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because precision irrigation and waterless processes drastically reduce freshwater depletion and chemical effluent.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because flood irrigation wastes huge volumes of water.","C":"Incorrect because discharging chemical dyes pollutes waterways.","D":"Incorrect because canteen bottles do not address industrial/agricultural water intensity."}}},{"id":"P1_U4_MCQ_728","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_728","question":"How do 'electric delivery vans' charged by renewable electricity improve the sustainability of logistics operations?","options":{"A":"They emit more diesel exhaust fumes in city centres","B":"They eliminate tailpipe greenhouse gas and air-pollutant emissions while reducing fuel and engine maintenance costs per kilometre","C":"They require zero battery charging or maintenance","D":"They carry parcels without needing roads or drivers"},"correctOption":"B","correctAnswer":"They eliminate tailpipe greenhouse gas and air-pollutant emissions while reducing fuel and engine maintenance costs per kilometre","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because zero-emission electric fleets cut urban air pollution, carbon footprint, and ongoing fuel expenses.","distractor_reasons":{"A":"Incorrect because electric vehicles produce zero tailpipe emissions.","B":"Correct selection.","C":"Incorrect because electric vans require charging infrastructure and routine tyre/brake maintenance.","D":"Incorrect because delivery vans still use roads and drivers."}}},{"id":"P1_U4_MCQ_729","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_729","question":"What is a major challenge of transitioning a long-haul freight fleet from diesel lorries to battery-electric trucks?","options":{"A":"Electric trucks emit too much black diesel smoke","B":"Diesel fuel is completely free for transport companies","C":"High upfront vehicle purchase prices, heavy battery weight reducing cargo payload, and limited high-speed roadside charging infrastructure","D":"Electric trucks are banned from driving on motorways"},"correctOption":"C","correctAnswer":"High upfront vehicle purchase prices, heavy battery weight reducing cargo payload, and limited high-speed roadside charging infrastructure","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital cost, charging downtime, and range constraints currently slow heavy-duty electric freight adoption.","distractor_reasons":{"A":"Incorrect because electric trucks have zero tailpipe smoke.","B":"Incorrect because diesel is a major variable expense.","C":"Correct selection.","D":"Incorrect because electric trucks operate freely on motorways."}}},{"id":"P1_U4_MCQ_730","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_730","question":"Why do many companies publish annual 'Environmental, Social, and Governance (ESG) / Sustainability Reports'?","options":{"A":"To hide pollution levels from customers and regulators","B":"To increase paper waste by printing millions of physical copies","C":"To prove they pay zero wages to factory workers","D":"To demonstrate transparency and accountability on carbon emissions, waste, and resource targets to investors, customers, and regulators"},"correctOption":"D","correctAnswer":"To demonstrate transparency and accountability on carbon emissions, waste, and resource targets to investors, customers, and regulators","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because transparent ESG reporting builds stakeholder trust, attracts ethical capital, and avoids accusations of greenwashing.","distractor_reasons":{"A":"Incorrect because sustainability reports disclose rather than hide environmental metrics.","B":"Incorrect because ESG reports are published digitally online.","C":"Incorrect because social metrics demonstrate fair pay and safe working conditions.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_731","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_731","question":"What is meant by 'product-as-a-service' (leasing or subscription models, such as leasing carpets or lighting systems) in sustainable business?","options":{"A":"The manufacturer retains ownership of the product and maintains, repairs, and recycles it at end-of-life, incentivizing durable, recyclable design","B":"Customers buy cheap disposable goods and throw them in rivers after one week","C":"Manufacturers refuse to repair any broken equipment","D":"Businesses give away all products permanently for free"},"correctOption":"A","correctAnswer":"The manufacturer retains ownership of the product and maintains, repairs, and recycles it at end-of-life, incentivizing durable, recyclable design","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when producers own the asset across its lifecycle, they profit from durability, easy repair, and material recovery.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because product-as-a-service eliminates disposable 'throwaway' consumption.","C":"Incorrect because maintenance and repair are central to service contracts.","D":"Incorrect because customers pay ongoing subscription or usage fees."}}},{"id":"P1_U4_MCQ_732","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_732","question":"How does 'reducing food waste' in supermarkets and food manufacturing support sustainability?","options":{"A":"It increases methane emissions from decomposing food in landfills","B":"It avoids wasting the agricultural land, water, fertiliser, and transport energy used to grow food while cutting disposal costs","C":"It forces farmers to burn unsold crops","D":"It eliminates the need for refrigeration in food stores"},"correctOption":"B","correctAnswer":"It avoids wasting the agricultural land, water, fertiliser, and transport energy used to grow food while cutting disposal costs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because food production is resource-intensive and rotting landfill food emits potent methane gas; better forecasting and redistribution save resources.","distractor_reasons":{"A":"Incorrect because reducing food waste cuts landfill methane emissions.","B":"Correct selection.","C":"Incorrect because surplus edible food can be discounted or donated rather than burned.","D":"Incorrect because proper refrigeration helps prevent spoilage."}}},{"id":"P1_U4_MCQ_733","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_733","question":"Which operational practice helps a manufacturer minimize 'hazardous chemical waste'?","options":{"A":"Pouring toxic solvents down municipal storm drains","B":"Increasing the concentration of heavy metals in paints","C":"Substituting water-based, non-toxic inks and adhesives for volatile petroleum solvents and recovering any remaining process chemicals","D":"Eliminating protective ventilation in chemical workshops"},"correctOption":"C","correctAnswer":"Substituting water-based, non-toxic inks and adhesives for volatile petroleum solvents and recovering any remaining process chemicals","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because benign chemical substitutes protect worker health, prevent soil/water contamination, and avoid hazardous waste disposal fees.","distractor_reasons":{"A":"Incorrect because dumping solvents into drains is illegal and environmentally destructive.","B":"Incorrect because heavy metals increase toxicity.","C":"Correct selection.","D":"Incorrect because safe ventilation is essential for worker health."}}},{"id":"P1_U4_MCQ_734","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_734","question":"What is meant by 'industrial symbiosis' in sustainable manufacturing?","options":{"A":"Competing factories sabotaging each other's power lines","B":"All factories in a region dumping waste into the same landfill","C":"Replacing all human workers with biological robots","D":"A network where the waste by-product or excess heat of one factory becomes a valuable raw material or energy input for a neighbouring factory"},"correctOption":"D","correctAnswer":"A network where the waste by-product or excess heat of one factory becomes a valuable raw material or energy input for a neighbouring factory","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because industrial symbiosis turns one firm's waste stream into another's feedstock, cutting disposal and input costs simultaneously.","distractor_reasons":{"A":"Incorrect because symbiosis involves cooperation rather than sabotage.","B":"Incorrect because symbiosis diverts waste away from landfills.","C":"Incorrect because symbiosis describes inter-firm resource sharing.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_735","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_735","question":"Why is 'consumer education and clear eco-labelling' important when a business launches sustainable packaging?","options":{"A":"So customers know how to separate, reuse, recycle, or compost the packaging properly and recognize the genuine environmental benefit","B":"So customers throw recyclable packaging into general landfill bins","C":"Because eco-labels eliminate the need to manufacture durable products","D":"Because laws ban printing recycling symbols on boxes"},"correctOption":"A","correctAnswer":"So customers know how to separate, reuse, recycle, or compost the packaging properly and recognize the genuine environmental benefit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because clear disposal instructions ensure recyclable/compostable materials actually enter recovery streams rather than contaminating waste.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because clear labels guide proper recycling rather than landfilling.","C":"Incorrect because product durability remains vital.","D":"Incorrect because governments encourage standardized recycling labels."}}},{"id":"P1_U4_MCQ_736","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_736","question":"How does 'refurbishing and remanufacturing' returned electronic devices support sustainable operations?","options":{"A":"It destroys valuable rare-earth metals in incinerators","B":"Used devices are tested, repaired with replacement parts, and resold with warranties, conserving rare minerals and creating an affordable product tier","C":"It forces customers to throw broken phones into household rubbish","D":"It increases mining demand for virgin lithium and cobalt"},"correctOption":"B","correctAnswer":"Used devices are tested, repaired with replacement parts, and resold with warranties, conserving rare minerals and creating an affordable product tier","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because remanufacturing recovers high-value electronic components, cuts e-waste, and unlocks new revenue streams.","distractor_reasons":{"A":"Incorrect because incineration destroys recoverable metals.","B":"Correct selection.","C":"Incorrect because trade-in and refurbishment divert phones from household rubbish.","D":"Incorrect because reusing existing components reduces virgin mineral mining."}}},{"id":"P1_U4_MCQ_737","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_737","question":"What is a major risk if a business promotes only one minor eco-friendly product while ignoring severe pollution across its core factories?","options":{"A":"Guaranteed permanent praise from environmental campaigners","B":"Exemption from all national pollution laws","C":"Accusations of greenwashing and hypocrisy, leading to public backlash and loss of credibility","D":"Automatic doubling of share price"},"correctOption":"C","correctAnswer":"Accusations of greenwashing and hypocrisy, leading to public backlash and loss of credibility","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because stakeholders quickly spot tokenism when core operations remain unsustainable.","distractor_reasons":{"A":"Incorrect because campaigners expose superficial green claims.","B":"Incorrect because environmental laws apply across all company operations.","C":"Correct selection.","D":"Incorrect because reputational scandals harm investor confidence."}}},{"id":"P1_U4_MCQ_738","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_738","question":"How does 'increasing product concentration' (such as concentrated liquid detergents) improve sustainability in consumer goods?","options":{"A":"It ships more water in larger plastic bottles","B":"It increases plastic waste per wash","C":"It requires twice as many delivery lorries","D":"Removing unnecessary water shrinks bottle sizes, cutting plastic packaging, warehouse space, and transport fuel emissions per dose"},"correctOption":"D","correctAnswer":"Removing unnecessary water shrinks bottle sizes, cutting plastic packaging, warehouse space, and transport fuel emissions per dose","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shipping concentrated formulas eliminates transporting heavy water weight and reduces plastic container volume.","distractor_reasons":{"A":"Incorrect because concentration removes water rather than adding it.","B":"Incorrect because smaller bottles use less plastic per dose.","C":"Incorrect because smaller bottles fit more doses per lorry, reducing trips.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_739","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_739","question":"Which statement best summarizes why sustainable production has become a strategic priority for modern businesses?","options":{"A":"Rising energy/resource costs, stricter environmental laws, eco-conscious consumers, and ethical investors increasingly reward resource-efficient, low-carbon firms","B":"Fossil fuels have become completely free and unlimited","C":"Consumers no longer care about pollution or climate change","D":"Governments have abolished all environmental regulations worldwide"},"correctOption":"A","correctAnswer":"Rising energy/resource costs, stricter environmental laws, eco-conscious consumers, and ethical investors increasingly reward resource-efficient, low-carbon firms","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because market, regulatory, financial, and cost pressures all converge to make sustainability essential for long-term competitiveness.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fossil fuels are finite and subject to volatile prices and carbon taxes.","C":"Incorrect because consumer environmental awareness continues to grow.","D":"Incorrect because environmental regulations are expanding globally."}}},{"id":"P1_U4_MCQ_740","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_740","question":"Which of the following is a 'fixed cost' for an airline?","options":{"A":"Jet fuel burned on each scheduled flight","B":"Annual aircraft lease payments and hangar insurance premiums","C":"In-flight passenger meals and drinks served per ticket sold","D":"Airport passenger departure taxes paid per traveller"},"correctOption":"B","correctAnswer":"Annual aircraft lease payments and hangar insurance premiums","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because annual aircraft lease and insurance costs must be paid regardless of how many passengers fly.","distractor_reasons":{"A":"Incorrect because jet fuel varies with flight operations.","B":"Correct selection.","C":"Incorrect because passenger meals vary directly with passenger numbers (variable cost).","D":"Incorrect because per-passenger airport taxes vary directly with tickets sold."}}},{"id":"P1_U4_MCQ_741","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_741","question":"Which of the following is a 'variable cost' for an online clothing retailer?","options":{"A":"Annual rent for the central distribution warehouse","B":"Fixed monthly salary of the website IT manager","C":"Wholesale cost of garments sold and courier postage fees per customer order","D":"Annual business property rates on head office"},"correctOption":"C","correctAnswer":"Wholesale cost of garments sold and courier postage fees per customer order","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because garment wholesale purchases and courier delivery fees rise and fall directly with order volume.","distractor_reasons":{"A":"Incorrect because warehouse rent is a fixed overhead.","B":"Incorrect because a fixed monthly salary is a fixed cost.","C":"Correct selection.","D":"Incorrect because property rates are fixed overheads."}}},{"id":"P1_U4_MCQ_742","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_742","question":"What happens to 'total variable costs' when a factory's output falls to zero during a temporary closure?","options":{"A":"Total variable costs remain equal to total fixed costs","B":"Total variable costs double automatically","C":"Total variable costs become negative","D":"Total variable costs fall to zero because no raw materials or direct piece-rate inputs are being used"},"correctOption":"D","correctAnswer":"Total variable costs fall to zero because no raw materials or direct piece-rate inputs are being used","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because variable costs are incurred only when units are produced; at zero output, total cost equals fixed costs alone.","distractor_reasons":{"A":"Incorrect because total variable costs equal zero at zero output, whereas fixed costs remain positive.","B":"Incorrect because variable costs drop rather than double.","C":"Incorrect because costs cannot be negative.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_743","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_743","question":"Why is accurate 'cost classification' (separating fixed and variable costs) important for operations managers?","options":{"A":"It enables managers to calculate unit contribution, determine break-even output, set profitable prices, and evaluate special orders","B":"It eliminates the need to pay suppliers or employees","C":"It guarantees that fixed costs never increase","D":"It prevents competitors from entering the market"},"correctOption":"A","correctAnswer":"It enables managers to calculate unit contribution, determine break-even output, set profitable prices, and evaluate special orders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because understanding how costs behave as output changes is essential for budgeting, pricing, and break-even planning.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cost analysis measures expenses rather than eliminating them.","C":"Incorrect because fixed costs such as rent can still rise over time.","D":"Incorrect because internal cost accounting does not create market entry barriers."}}},{"id":"P1_U4_MCQ_744","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_744","question":"What is meant by 'direct costs' in production?","options":{"A":"Head-office legal fees and general factory heating","B":"Costs that can be clearly and directly traced to the production of a specific unit of output, such as direct raw materials and direct assembly labour","C":"Annual property taxes on corporate headquarters","D":"Advertising campaigns promoting the entire company brand"},"correctOption":"B","correctAnswer":"Costs that can be clearly and directly traced to the production of a specific unit of output, such as direct raw materials and direct assembly labour","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because direct costs are directly attributable to a particular product or job.","distractor_reasons":{"A":"Incorrect because general heating and legal fees are indirect overhead costs.","B":"Correct selection.","C":"Incorrect because property taxes are indirect overheads.","D":"Incorrect because general brand advertising is an indirect marketing overhead."}}},{"id":"P1_U4_MCQ_745","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_745","question":"What is meant by 'indirect costs' (overheads)?","options":{"A":"Raw timber used to build a specific dining table","B":"Piece-rate wages paid per shirt stitched","C":"Costs that cannot be directly linked to a single unit of output, such as factory rent, management salaries, and general building insurance","D":"Cardboard boxes packed around individual shoes"},"correctOption":"C","correctAnswer":"Costs that cannot be directly linked to a single unit of output, such as factory rent, management salaries, and general building insurance","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because indirect costs support overall business operations rather than one specific item.","distractor_reasons":{"A":"Incorrect because raw timber is a direct material cost.","B":"Incorrect because piece-rate wages are direct labour costs.","C":"Correct selection.","D":"Incorrect because individual shoe boxes are direct packaging costs."}}},{"id":"P1_U4_MCQ_746","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_746","question":"Under what condition is it financially worthwhile for a manufacturer with spare capacity to accept a one-off special order priced BELOW average total cost?","options":{"A":"Never, because every order must be priced above average total cost","B":"Whenever the special order price is below variable cost per unit","C":"Only if the business has zero fixed costs","D":"When the special order price exceeds variable cost per unit (generating positive contribution), fixed costs are already covered, and regular full-price sales are unaffected"},"correctOption":"D","correctAnswer":"When the special order price exceeds variable cost per unit (generating positive contribution), fixed costs are already covered, and regular full-price sales are unaffected","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because fixed costs do not rise with spare-capacity output, so any price above unit variable cost adds directly to net profit.","distractor_reasons":{"A":"Incorrect because marginal/contribution pricing uses spare capacity profitably when price exceeds variable cost.","B":"Incorrect because pricing below variable cost incurs an immediate cash loss on every unit.","C":"Incorrect because the rule applies specifically when existing fixed costs are already paid.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_747","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_747","question":"What happens to a business's 'average total cost' curve as it expands output first through economies of scale and later into diseconomies of scale?","options":{"A":"Average cost falls initially as economies of scale lower unit costs, reaches a minimum optimal scale, and then rises if diseconomies of scale set in","B":"Average cost rises continuously from the very first unit produced","C":"Average cost stays completely flat at every possible output level","D":"Average cost falls to zero when output reaches maximum capacity"},"correctOption":"A","correctAnswer":"Average cost falls initially as economies of scale lower unit costs, reaches a minimum optimal scale, and then rises if diseconomies of scale set in","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the long-run average cost curve is U-shaped: falling during economies of scale and rising during diseconomies of scale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because economies of scale initially lower average unit cost.","C":"Incorrect because unit costs vary with scale efficiency.","D":"Incorrect because variable and fixed costs prevent average cost from ever reaching zero."}}},{"id":"P1_U4_MCQ_748","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_748","question":"Which example illustrates a 'risk-bearing economy of scale'?","options":{"A":"Buying flour in bulk sacks at a 20% discount","B":"A large diversified corporation selling many different product lines across multiple countries so a downturn in one market is offset by profits in others","C":"Using a high-speed automated bottling line","D":"Borrowing money at a lower interest rate from a bank"},"correctOption":"B","correctAnswer":"A large diversified corporation selling many different product lines across multiple countries so a downturn in one market is offset by profits in others","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because large firms spread commercial and R&D risks across diverse products and geographic markets.","distractor_reasons":{"A":"Incorrect because bulk discounts are purchasing economies.","B":"Correct selection.","C":"Incorrect because automated bottling lines are technical economies.","D":"Incorrect because lower interest rates are financial economies."}}},{"id":"P1_U4_MCQ_749","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_749","question":"Why do small businesses often struggle to achieve 'technical economies of scale'?","options":{"A":"Because laws ban small firms from buying electric equipment","B":"Because small firms have too many specialist engineers","C":"Because high-capacity automated machinery is expensive and indivisible, so low small-business output cannot keep it utilized enough to lower unit costs","D":"Because small firms always receive huge bulk discounts from suppliers"},"correctOption":"C","correctAnswer":"Because high-capacity automated machinery is expensive and indivisible, so low small-business output cannot keep it utilized enough to lower unit costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because large-scale machinery requires high output volumes to spread fixed capital costs effectively.","distractor_reasons":{"A":"Incorrect because the barrier is capital cost and output volume, not legal bans.","B":"Incorrect because small firms employ fewer specialists.","C":"Correct selection.","D":"Incorrect because bulk discounts belong to large firms (purchasing economies)."}}},{"id":"P1_U4_MCQ_750","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_750","question":"How does 'communication breakdown' cause diseconomies of scale in giant corporations?","options":{"A":"Messages are delivered instantly face-to-face without distortion","B":"Suppliers charge lower prices when orders become confusing","C":"Workers require zero supervision or instructions","D":"Long chains of command across multiple layers and branches distort instructions, causing misunderstandings, duplicated work, and costly mistakes"},"correctOption":"D","correctAnswer":"Long chains of command across multiple layers and branches distort instructions, causing misunderstandings, duplicated work, and costly mistakes","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because tall organizational hierarchies slow down and garble feedback between senior managers and front-line staff.","distractor_reasons":{"A":"Incorrect because fast face-to-face communication characterizes small, flat organizations.","B":"Incorrect because confused orders increase errors and costs.","C":"Incorrect because large teams require clear coordination.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_751","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_751","question":"How can a large business reduce 'diseconomies of scale' without shrinking its total sales?","options":{"A":"By decentralizing decision-making to autonomous regional divisions or production cells and flattening tall management hierarchies","B":"By adding ten extra layers of senior management approval","C":"By banning all communication between managers and shop-floor workers","D":"By stopping all employee training and team briefings"},"correctOption":"A","correctAnswer":"By decentralizing decision-making to autonomous regional divisions or production cells and flattening tall management hierarchies","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because decentralization and flatter structures restore speed, accountability, and worker engagement while retaining large-scale purchasing and financial advantages.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because adding management layers worsens bureaucratic delays.","C":"Incorrect because restricting communication increases alienation and errors.","D":"Incorrect because stopping training lowers productivity."}}},{"id":"P1_U4_MCQ_752","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_752","question":"On a standard break-even chart, where does the 'Total Cost' line begin on the vertical (cost/revenue) axis at zero output?","options":{"A":"At the origin ($0)","B":"At the level of Total Fixed Costs, because fixed costs must be paid even when zero units are produced","C":"At the break-even intersection point","D":"At maximum factory capacity"},"correctOption":"B","correctAnswer":"At the level of Total Fixed Costs, because fixed costs must be paid even when zero units are produced","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Total Cost = Fixed Cost + Variable Cost; at zero output, Variable Cost is zero so Total Cost equals Fixed Cost.","distractor_reasons":{"A":"Incorrect because the Total Revenue line and Variable Cost line start at $0, whereas Total Cost starts at Fixed Costs.","B":"Correct selection.","C":"Incorrect because the break-even point occurs at a positive output level where Total Revenue crosses Total Cost.","D":"Incorrect because maximum capacity is at the far right of the horizontal output axis."}}},{"id":"P1_U4_MCQ_753","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_753","question":"On a standard break-even chart, what is the shape and starting point of the 'Total Revenue' line?","options":{"A":"A flat horizontal line starting at fixed costs","B":"A downward-sloping line starting at maximum output","C":"An upward-sloping straight line starting at the origin ($0) whose steepness depends on the selling price per unit","D":"A vertical line at the break-even point"},"correctOption":"C","correctAnswer":"An upward-sloping straight line starting at the origin ($0) whose steepness depends on the selling price per unit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because at zero sales revenue is $0, and each unit sold adds the selling price to total revenue.","distractor_reasons":{"A":"Incorrect because a flat horizontal line starting at fixed costs represents Total Fixed Costs.","B":"Incorrect because total revenue rises rather than falls as more units are sold.","C":"Correct selection.","D":"Incorrect because break-even output is marked by a vertical reference drop from the intersection."}}},{"id":"P1_U4_MCQ_754","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_754","question":"On a break-even chart, what does the shaded area between the Total Revenue line and the Total Cost line to the RIGHT of the break-even point represent?","options":{"A":"The financial loss made at those output levels","B":"Total fixed overheads","C":"Total variable production costs","D":"The net profit earned at output levels above the break-even point"},"correctOption":"D","correctAnswer":"The net profit earned at output levels above the break-even point","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because above break-even output, Total Revenue exceeds Total Cost, and the vertical gap measures net profit.","distractor_reasons":{"A":"Incorrect because losses appear to the left of the break-even point.","B":"Incorrect because fixed overheads are shown below the fixed cost line.","C":"Incorrect because variable costs are the gap between Total Cost and Fixed Cost.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_755","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_755","question":"Assuming fixed costs and selling price remain unchanged, how does a 'decrease in variable cost per unit' (e.g., cheaper raw materials) affect the break-even chart?","options":{"A":"The Total Cost line slopes upward less steeply, increasing unit contribution and lowering the break-even output","B":"The Total Cost line slopes upward more steeply, raising the break-even output","C":"The Fixed Cost line shifts upward","D":"The Total Revenue line shifts downward"},"correctOption":"A","correctAnswer":"The Total Cost line slopes upward less steeply, increasing unit contribution and lowering the break-even output","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lower variable cost per unit increases unit contribution (Price - VC), allowing fixed costs to be covered at a lower sales volume.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a steeper Total Cost line occurs when variable costs increase.","C":"Incorrect because variable material costs do not move the Fixed Cost line.","D":"Incorrect because the selling price is unchanged, leaving Total Revenue unaffected."}}},{"id":"P1_U4_MCQ_756","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_756","question":"Why is having a large 'margin of safety' reassuring for business owners and bank lenders?","options":{"A":"It guarantees that the business has zero fixed costs","B":"It shows that actual sales can fall substantially during a recession or seasonal dip before the business starts making a loss","C":"It proves the business is operating at 100% capacity with zero spare room","D":"It means the business can ignore all quality and cost controls"},"correctOption":"B","correctAnswer":"It shows that actual sales can fall substantially during a recession or seasonal dip before the business starts making a loss","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a wide buffer above break-even output indicates lower financial risk during demand downturns.","distractor_reasons":{"A":"Incorrect because businesses still have fixed overheads.","B":"Correct selection.","C":"Incorrect because high margin of safety relates to sales relative to break-even, not capacity limits.","D":"Incorrect because ongoing cost and quality control preserve that margin of safety."}}},{"id":"P1_U4_MCQ_757","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_757","question":"How is 'break-even analysis' commonly used by entrepreneurs when launching a new business or applying for a bank loan?","options":{"A":"To prove that customers will definitely buy the product at any price","B":"To calculate exact employee income tax deductions","C":"To estimate the minimum sales volume required to avoid losses and test 'what-if' scenarios for different prices and costs in a business plan","D":"To replace all market research and financial accounting statements"},"correctOption":"C","correctAnswer":"To estimate the minimum sales volume required to avoid losses and test 'what-if' scenarios for different prices and costs in a business plan","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because break-even analysis assesses commercial feasibility and helps lenders evaluate risk.","distractor_reasons":{"A":"Incorrect because break-even shows the target sales needed, not a guarantee that customers will buy.","B":"Incorrect because income tax is calculated via payroll accounting.","C":"Correct selection.","D":"Incorrect because break-even complements rather than replaces market research and financial statements."}}},{"id":"P1_U4_MCQ_758","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_758","question":"Why is the assumption of 'straight linear cost and revenue lines' a limitation of simple break-even analysis?","options":{"A":"Because fixed costs always drop to zero at high output","B":"Because businesses never sell more than ten units","C":"Because selling prices always double automatically at high output","D":"In reality, bulk-buying discounts can bend variable costs downward, overtime wages can bend costs upward, and price discounts may be needed to sell high volumes"},"correctOption":"D","correctAnswer":"In reality, bulk-buying discounts can bend variable costs downward, overtime wages can bend costs upward, and price discounts may be needed to sell high volumes","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because real-world economies of scale, overtime premiums, and volume discounts make cost and revenue curves non-linear.","distractor_reasons":{"A":"Incorrect because fixed costs step up rather than drop to zero at high output.","B":"Incorrect because businesses sell thousands or millions of units.","C":"Incorrect because high volumes often require lower prices rather than double prices.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_759","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_759","question":"Why can simple break-even analysis be difficult to apply directly to a multi-product supermarket or department store?","options":{"A":"Because allocating shared fixed overheads (such as store rent and heating) accurately across thousands of different products with varying prices and margins is complex","B":"Because supermarkets have zero fixed costs","C":"Because supermarkets sell every item at the exact same price","D":"Because break-even analysis is illegal for retail businesses"},"correctOption":"A","correctAnswer":"Because allocating shared fixed overheads (such as store rent and heating) accurately across thousands of different products with varying prices and margins is complex","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because standard single-product break-even charts assume one selling price and one unit variable cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supermarkets pay substantial fixed store rents and salaries.","C":"Incorrect because supermarkets sell thousands of differently priced goods.","D":"Incorrect because no law restricts break-even analysis."}}},{"id":"P1_U4_MCQ_760","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_760","question":"What happens to 'fixed costs' in the long run if a business expands output beyond its current factory capacity?","options":{"A":"Fixed costs remain unchanged forever regardless of how many new factories are built","B":"Fixed costs 'step up' to a higher level as the business rents larger premises, buys extra machinery, and hires more salaried managers","C":"Fixed costs fall to zero once a second factory opens","D":"Fixed costs become variable piece-rate wages"},"correctOption":"B","correctAnswer":"Fixed costs 'step up' to a higher level as the business rents larger premises, buys extra machinery, and hires more salaried managers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because fixed costs are constant only within existing capacity; expanding capacity creates stepped fixed costs.","distractor_reasons":{"A":"Incorrect because fixed costs are fixed only in the short run within capacity limits.","B":"Correct selection.","C":"Incorrect because expanding premises increases fixed overheads.","D":"Incorrect because factory rent and salaries remain fixed overheads at the higher level."}}},{"id":"P1_U4_MCQ_761","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_761","question":"Which cost behaviour defines 'semi-variable costs' (such as a telephone or electricity plan with a fixed monthly standing charge plus a usage charge per unit)?","options":{"A":"Costs that equal zero at all output levels","B":"Costs that never change regardless of usage","C":"Costs containing both a fixed base component independent of output and a variable component that rises with activity","D":"Costs that fall to zero when output doubles"},"correctOption":"C","correctAnswer":"Costs containing both a fixed base component independent of output and a variable component that rises with activity","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because many utility and maintenance expenses combine a fixed standing charge with a usage-dependent charge.","distractor_reasons":{"A":"Incorrect because semi-variable costs are positive even at zero output.","B":"Incorrect because purely unchanged costs are fixed costs.","C":"Correct selection.","D":"Incorrect because higher activity raises the variable portion."}}},{"id":"P1_U4_MCQ_762","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_762","question":"How does 'increasing output within existing capacity' affect profit once a business has passed its break-even point?","options":{"A":"Profit falls because fixed costs double with every extra unit","B":"Profit stays unchanged at zero","C":"Total revenue falls below total cost","D":"Every extra unit sold adds its full unit contribution directly to net profit because fixed costs are already fully paid"},"correctOption":"D","correctAnswer":"Every extra unit sold adds its full unit contribution directly to net profit because fixed costs are already fully paid","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because once fixed overheads are covered at break-even, all subsequent unit contribution becomes pure profit.","distractor_reasons":{"A":"Incorrect because fixed costs do not rise within existing capacity.","B":"Incorrect because profit grows steadily above break-even.","C":"Incorrect because total revenue exceeds total cost above break-even.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_763","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_763","question":"What happens if a business's actual sales fall BELOW its break-even output?","options":{"A":"Total contribution is insufficient to cover total fixed costs, so the business incurs a financial loss","B":"The business achieves a positive margin of safety","C":"Total revenue exceeds total costs","D":"The business earns maximum net profit"},"correctOption":"A","correctAnswer":"Total contribution is insufficient to cover total fixed costs, so the business incurs a financial loss","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because below break-even, Total Cost lies above Total Revenue, generating a loss equal to the shortfall in contribution.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because margin of safety is negative when sales are below break-even.","C":"Incorrect because total revenue is less than total costs below break-even.","D":"Incorrect because the firm is making a loss rather than a profit."}}},{"id":"P1_U4_MCQ_764","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_764","question":"Why do small niche businesses often survive and compete successfully against giant corporations that enjoy economies of scale?","options":{"A":"Because small firms receive lower interest rates than global banks","B":"Because small firms avoid diseconomies of scale, offer personalized customer service, adapt rapidly to niche tastes, and serve small local markets unprofitable for giants","C":"Because large corporations are banned from advertising","D":"Because small businesses never pay rent or wages"},"correctOption":"B","correctAnswer":"Because small firms avoid diseconomies of scale, offer personalized customer service, adapt rapidly to niche tastes, and serve small local markets unprofitable for giants","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because agility, personal relationships, bespoke quality, and low bureaucracy allow small firms to thrive in specialized niches.","distractor_reasons":{"A":"Incorrect because large corporations enjoy financial economies of scale.","B":"Correct selection.","C":"Incorrect because large firms advertise extensively.","D":"Incorrect because small firms still pay rent and wages."}}},{"id":"P1_U4_MCQ_765","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_765","question":"How does 'increasing specialization and division of labour' within a large factory contribute to economies of scale?","options":{"A":"Workers waste time switching tools every two minutes","B":"Workers become less skilled at their tasks","C":"Workers focus on specific tasks with specialized tools, increasing speed, dexterity, and output per hour while reducing training time","D":"It increases average fixed cost per unit"},"correctOption":"C","correctAnswer":"Workers focus on specific tasks with specialized tools, increasing speed, dexterity, and output per hour while reducing training time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because specialization of labour and equipment boosts productivity and lowers average unit production costs.","distractor_reasons":{"A":"Incorrect because specialization eliminates tool-switching time.","B":"Incorrect because repeated practice increases task proficiency.","C":"Correct selection.","D":"Incorrect because higher output lowers average fixed cost."}}},{"id":"P1_U4_MCQ_766","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_766","question":"What is the relationship between 'unit contribution' and 'selling price' when variable cost per unit is constant?","options":{"A":"Lowering the selling price increases unit contribution","B":"Changing the selling price has zero effect on unit contribution","C":"Unit contribution is always higher than the selling price","D":"Raising the selling price increases unit contribution by the exact same amount, lowering the break-even output"},"correctOption":"D","correctAnswer":"Raising the selling price increases unit contribution by the exact same amount, lowering the break-even output","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Unit Contribution = Selling Price - Unit Variable Cost; every dollar added to price adds a dollar to contribution.","distractor_reasons":{"A":"Incorrect because lowering price reduces unit contribution.","B":"Incorrect because selling price directly determines unit contribution.","C":"Incorrect because variable cost is subtracted from selling price, making unit contribution smaller than selling price.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_767","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_767","question":"What trade-off must managers consider before raising the selling price to lower the break-even point?","options":{"A":"A higher price increases contribution per unit, but if demand is price-elastic, total sales volume may drop sharply so the firm fails to reach even the lower break-even target","B":"Raising the price always increases customer demand","C":"Raising the price increases variable raw material costs per unit","D":"Raising the price forces fixed factory rent to increase"},"correctOption":"A","correctAnswer":"A higher price increases contribution per unit, but if demand is price-elastic, total sales volume may drop sharply so the firm fails to reach even the lower break-even target","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because break-even analysis shows the required volume at a given price, not whether customers will actually buy that volume.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher prices typically reduce quantity demanded.","C":"Incorrect because selling price does not change factory material costs.","D":"Incorrect because fixed rent is unaffected by product pricing."}}},{"id":"P1_U4_MCQ_768","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_768","question":"Which action reduces a business's break-even output WITHOUT risking lost sales from raising customer prices?","options":{"A":"Increasing management salaries and office rent","B":"Lowering fixed overheads (e.g., negotiating cheaper rent) or reducing unit variable costs through lean waste reduction and bulk supplier discounts","C":"Paying higher prices for raw materials","D":"Reducing labour productivity across the factory"},"correctOption":"B","correctAnswer":"Lowering fixed overheads (e.g., negotiating cheaper rent) or reducing unit variable costs through lean waste reduction and bulk supplier discounts","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cutting fixed costs or lowering unit variable costs lowers the break-even threshold while keeping prices competitive.","distractor_reasons":{"A":"Incorrect because higher salaries and rent raise fixed costs and increase break-even output.","B":"Correct selection.","C":"Incorrect because costlier materials shrink contribution and raise break-even output.","D":"Incorrect because lower productivity raises unit costs."}}},{"id":"P1_U4_MCQ_769","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_769","question":"How does 'depreciation' of factory machinery behave as a business cost?","options":{"A":"It is a variable cost that equals zero when no goods are sold","B":"It is a direct raw material cost","C":"It is normally treated as a fixed overhead cost because equipment loses value over time regardless of short-term output fluctuations","D":"It is a cash inflow from selling finished products"},"correctOption":"C","correctAnswer":"It is normally treated as a fixed overhead cost because equipment loses value over time regardless of short-term output fluctuations","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because straight-line annual depreciation charges remain constant across short-term output variations.","distractor_reasons":{"A":"Incorrect because machinery continues aging and depreciating even during quiet months.","B":"Incorrect because depreciation reflects capital asset wear rather than raw materials.","C":"Correct selection.","D":"Incorrect because depreciation is a non-cash accounting expense, not revenue."}}},{"id":"P1_U4_MCQ_770","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_770","question":"Why is 'average cost per unit' crucial when a business sets its selling price?","options":{"A":"Because selling price must always be lower than average cost to make a profit","B":"Because average cost equals total sales revenue","C":"Because variable costs can be ignored when pricing products","D":"Because in the long run, the selling price must exceed average total cost per unit for the business to cover all fixed and variable expenses and earn a profit"},"correctOption":"D","correctAnswer":"Because in the long run, the selling price must exceed average total cost per unit for the business to cover all fixed and variable expenses and earn a profit","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because pricing below average total cost over the long term results in continuous losses.","distractor_reasons":{"A":"Incorrect because pricing below average cost causes a loss.","B":"Incorrect because average cost is total cost divided by output.","C":"Incorrect because both fixed and variable costs are included in average total cost.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_771","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_771","question":"What is meant by 'cost-plus pricing' in relation to operations cost data?","options":{"A":"Calculating the average cost per unit of producing a good and adding a percentage mark-up for profit","B":"Setting prices purely by guessing what competitors charge","C":"Selling products below variable cost permanently","D":"Ignoring fixed overheads completely when setting prices"},"correctOption":"A","correctAnswer":"Calculating the average cost per unit of producing a good and adding a percentage mark-up for profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost-plus pricing relies directly on accurate unit cost calculations to ensure every sale covers costs plus a target margin.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because matching rivals is competitive pricing.","C":"Incorrect because selling below variable cost incurs losses.","D":"Incorrect because average total cost includes fixed overheads."}}},{"id":"P1_U4_MCQ_772","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_772","question":"How can 'lack of worker coordination and motivation' in a huge factory lead to diseconomies of scale?","options":{"A":"Workers feel closer to the company founder and work twice as fast","B":"Employees feel anonymous and disconnected from management goals, leading to higher absenteeism, higher staff turnover, lower productivity, and rising unit costs","C":"Bulk-buying discounts disappear when factories grow larger","D":"Banks charge higher interest rates to large profitable firms"},"correctOption":"B","correctAnswer":"Employees feel anonymous and disconnected from management goals, leading to higher absenteeism, higher staff turnover, lower productivity, and rising unit costs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because alienation in oversized workplaces erodes productivity and increases recruitment/training expenses.","distractor_reasons":{"A":"Incorrect because personal closeness to the founder characterizes small businesses.","B":"Correct selection.","C":"Incorrect because bulk discounts increase with size.","D":"Incorrect because large firms typically pay lower interest rates."}}},{"id":"P1_U4_MCQ_773","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_773","question":"What happens to a business's 'break-even point' if BOTH fixed costs increase AND selling price decreases?","options":{"A":"Break-even output falls dramatically","B":"Break-even output remains completely unchanged","C":"Break-even output rises sharply because higher fixed costs must be covered using a smaller contribution per unit","D":"Margin of safety automatically increases"},"correctOption":"C","correctAnswer":"Break-even output rises sharply because higher fixed costs must be covered using a smaller contribution per unit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because both changes work against profitability: the numerator (fixed costs) rises while the denominator (unit contribution) shrinks.","distractor_reasons":{"A":"Incorrect because both changes push break-even output upward.","B":"Incorrect because both fixed costs and selling price alter break-even output.","C":"Correct selection.","D":"Incorrect because a higher break-even point narrows the margin of safety."}}},{"id":"P1_U4_MCQ_774","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_774","question":"Why is 'total contribution' a useful metric for comparing the financial performance of different product lines in a business?","options":{"A":"Because it eliminates the need to pay any fixed overheads","B":"Because total contribution equals net profit after tax","C":"Because variable costs are identical across all products","D":"Because it shows how much cash each product line generates toward paying the business's shared fixed overheads and overall profit"},"correctOption":"D","correctAnswer":"Because it shows how much cash each product line generates toward paying the business's shared fixed overheads and overall profit","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because evaluating contribution avoids arbitrary allocation of shared fixed overheads across multiple products.","distractor_reasons":{"A":"Incorrect because shared fixed overheads still must be paid from combined contribution.","B":"Incorrect because fixed costs and taxes must still be deducted from total contribution.","C":"Incorrect because different products have different variable costs.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_775","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_775","question":"Which statement accurately describes the 'Variable Cost' line if plotted separately on a break-even chart?","options":{"A":"It starts at the origin ($0) at zero output and slopes upward parallel to the Total Cost line","B":"It is a horizontal flat line starting at fixed costs","C":"It slopes downward as output rises","D":"It is identical to the Total Revenue line"},"correctOption":"A","correctAnswer":"It starts at the origin ($0) at zero output and slopes upward parallel to the Total Cost line","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because variable costs are $0 at zero output and rise by the exact same unit variable cost per unit as Total Cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a horizontal line starting at fixed costs is the Fixed Cost line.","C":"Incorrect because variable costs increase with output.","D":"Incorrect because Total Revenue rises according to selling price rather than variable cost."}}},{"id":"P1_U4_MCQ_776","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_776","question":"How does 'horizontal or vertical integration' (merging with or acquiring another business) relate to economies of scale?","options":{"A":"Mergers always reduce output and increase unit costs","B":"Larger combined scale can unlock bulk purchasing discounts, shared distribution networks, and lower borrowing rates, though poor integration can cause diseconomies of scale","C":"Merged firms are legally barred from sharing warehouses or managers","D":"Mergers eliminate all fixed overhead costs immediately"},"correctOption":"B","correctAnswer":"Larger combined scale can unlock bulk purchasing discounts, shared distribution networks, and lower borrowing rates, though poor integration can cause diseconomies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because inorganic growth expands scale rapidly, creating potential economies alongside coordination challenges.","distractor_reasons":{"A":"Incorrect because mergers expand output capacity and can lower unit costs.","B":"Correct selection.","C":"Incorrect because merged businesses actively consolidate warehouses and functions.","D":"Incorrect because fixed overheads are rationalized gradually rather than eliminated overnight."}}},{"id":"P1_U4_MCQ_777","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_777","question":"What does a 'negative margin of safety' indicate about a business's current trading position?","options":{"A":"The business is earning record profits","B":"The business has zero fixed costs","C":"Actual sales are below the break-even point, meaning the business is currently making a financial loss","D":"Actual sales are double the break-even output"},"correctOption":"C","correctAnswer":"Actual sales are below the break-even point, meaning the business is currently making a financial loss","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Margin of Safety = Actual Sales - Break-Even Output; a negative figure means sales fall short of break-even.","distractor_reasons":{"A":"Incorrect because a negative margin of safety indicates a loss.","B":"Incorrect because businesses with fixed costs require positive sales to break even.","C":"Correct selection.","D":"Incorrect because sales double break-even yield a large positive margin of safety."}}},{"id":"P1_U4_MCQ_778","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_778","question":"Why is 'quality' relative to customer expectations and price rather than an absolute luxury standard?","options":{"A":"Because budget shoppers expect solid-gold components in everyday items","B":"Because expensive products never break or contain defects","C":"Because low-priced businesses are exempt from consumer safety laws","D":"Because customers judge quality by whether a product reliably performs its intended function and delivers expected value for the price paid"},"correctOption":"D","correctAnswer":"Because customers judge quality by whether a product reliably performs its intended function and delivers expected value for the price paid","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because both a budget watch and a luxury watch are high quality if each is reliable, durable, and meets its target buyers' expectations.","distractor_reasons":{"A":"Incorrect because customer expectations are calibrated to price positioning.","B":"Incorrect because expensive goods can still suffer quality failures if poorly made.","C":"Incorrect because safety laws apply equally regardless of price.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_779","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_779","question":"How does a strong reputation for 'product quality' create a competitive advantage in crowded markets?","options":{"A":"It differentiates the brand from cheap, unreliable rivals, builds customer trust, encourages positive word-of-mouth, and reduces price sensitivity","B":"It eliminates the need to pay employee wages or raw material suppliers","C":"It legally prohibits competitors from selling similar goods","D":"It ensures products never need any packaging or delivery"},"correctOption":"A","correctAnswer":"It differentiates the brand from cheap, unreliable rivals, builds customer trust, encourages positive word-of-mouth, and reduces price sensitivity","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reliable quality builds brand equity and repeat custom, protecting market share against price-cutting rivals.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because wages and material costs still apply.","C":"Incorrect because quality is a commercial advantage rather than a legal monopoly.","D":"Incorrect because goods still require protective packaging and distribution."}}},{"id":"P1_U4_MCQ_780","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_780","question":"What is meant by the 'cost of poor quality' in operations management?","options":{"A":"The profit earned from selling reliable goods at premium prices","B":"All expenses resulting from quality failures, including scrap waste, reworking labour, warranty repairs, product recalls, legal claims, and lost future sales","C":"The cost of training workers to check quality standards at every stage of quality assurance","D":"The bulk discount received from certified raw material suppliers"},"correctOption":"B","correctAnswer":"All expenses resulting from quality failures, including scrap waste, reworking labour, warranty repairs, product recalls, legal claims, and lost future sales","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because poor quality imposes both visible internal scrap/rework costs and severe external brand and recall losses.","distractor_reasons":{"A":"Incorrect because premium profit is a benefit of high quality.","B":"Correct selection.","C":"Incorrect because staff training is a preventative quality assurance investment rather than a failure cost.","D":"Incorrect because bulk discounts are purchasing economies."}}},{"id":"P1_U4_MCQ_781","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_781","question":"Why are 'product recalls' after goods have been distributed to retail stores especially damaging to a manufacturer?","options":{"A":"Because recalls increase factory productivity and lower unit costs","B":"Because supermarkets pay the manufacturer extra bonuses during recalls","C":"Because the firm incurs massive reverse-logistics, refund, and destruction costs while suffering severe media damage and loss of retailer trust","D":"Because recalled items can be resold immediately without inspection"},"correctOption":"C","correctAnswer":"Because the firm incurs massive reverse-logistics, refund, and destruction costs while suffering severe media damage and loss of retailer trust","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because retrieving faulty items from thousands of shops and consumers is vastly more expensive and damaging than catching faults in the factory.","distractor_reasons":{"A":"Incorrect because recalls destroy output and raise unit costs.","B":"Incorrect because retailers penalize and delist suppliers over recalls.","C":"Correct selection.","D":"Incorrect because recalled goods must be quarantined, repaired, or safely destroyed."}}},{"id":"P1_U4_MCQ_782","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_782","question":"What is a key limitation of relying on 'sample inspection' in quality control rather than inspecting 100% of items?","options":{"A":"Sample inspection destroys every single product made by the factory","B":"Sample inspection takes longer than testing every unit individually","C":"Sample inspection requires training every shop-floor worker in ISO standards","D":"Defective items in the uninspected portion of a batch can still slip through and reach customers"},"correctOption":"D","correctAnswer":"Defective items in the uninspected portion of a batch can still slip through and reach customers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because checking only a statistical sample saves time and money but cannot guarantee 100% defect-free output.","distractor_reasons":{"A":"Incorrect because only the small tested sample is affected.","B":"Incorrect because sample testing is much faster than 100% inspection.","C":"Incorrect because sample inspection is performed by specialist quality inspectors.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_783","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_783","question":"What is a key disadvantage of '100% manual inspection' at the end of a high-speed production line?","options":{"A":"It is expensive, slows down dispatch, and human inspectors suffer eye fatigue and boredom, causing them to miss faults anyway","B":"It prevents defects from ever occurring during earlier manufacturing steps","C":"It eliminates the need to hire any quality inspectors","D":"It increases worker motivation on the assembly line"},"correctOption":"A","correctAnswer":"It is expensive, slows down dispatch, and human inspectors suffer eye fatigue and boredom, causing them to miss faults anyway","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because manually checking every single item adds heavy labour cost and still fails when inspectors tire.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because end-of-line inspection detects faults rather than preventing them upstream.","C":"Incorrect because 100% manual inspection requires hiring many inspectors.","D":"Incorrect because end-of-line policing does not motivate production workers."}}},{"id":"P1_U4_MCQ_784","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_784","question":"How does 'non-destructive testing' (such as X-ray, ultrasonic, or pressure testing) benefit quality management?","options":{"A":"It smashes every item to pieces to verify breaking strength","B":"It detects internal cracks or structural weaknesses inside products without damaging them, allowing 100% of safe items to be sold","C":"It eliminates the need for raw materials","D":"It costs zero money to purchase X-ray or ultrasonic scanners"},"correctOption":"B","correctAnswer":"It detects internal cracks or structural weaknesses inside products without damaging them, allowing 100% of safe items to be sold","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because non-destructive inspection verifies internal integrity without creating scrap waste.","distractor_reasons":{"A":"Incorrect because smashing items describes destructive testing.","B":"Correct selection.","C":"Incorrect because raw materials are still used in manufacturing.","D":"Incorrect because ultrasonic and X-ray testing equipment involves upfront capital investment."}}},{"id":"P1_U4_MCQ_785","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_785","question":"Which elements are typically included in a formal 'quality assurance' system?","options":{"A":"Eliminating all written procedures and letting workers guess measurements","B":"Checking products only after customers complain on social media","C":"Approved supplier checks, documented stage-by-stage operating standards, employee self-inspection, calibration of tools, and regular quality audits","D":"Replacing all quality standards with faster assembly-line speeds"},"correctOption":"C","correctAnswer":"Approved supplier checks, documented stage-by-stage operating standards, employee self-inspection, calibration of tools, and regular quality audits","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because quality assurance builds systematic prevention across inputs, equipment, staff training, and process documentation.","distractor_reasons":{"A":"Incorrect because quality assurance relies on clear documented specifications.","B":"Incorrect because waiting for complaints is reactive rather than preventative.","C":"Correct selection.","D":"Incorrect because quality assurance prioritizes meeting standards over unchecked speed."}}},{"id":"P1_U4_MCQ_786","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_786","question":"Why do many business-to-business (B2B) buyers require suppliers to hold 'ISO 9001' quality assurance certification?","options":{"A":"Because ISO 9001 forces suppliers to sell goods at a financial loss","B":"Because ISO 9001 eliminates the need for delivery transport","C":"Because ISO 9001 is a government tax on imported raw materials","D":"Because independent ISO accreditation proves the supplier operates consistent, audited quality management processes, reducing buyer risk"},"correctOption":"D","correctAnswer":"Because independent ISO accreditation proves the supplier operates consistent, audited quality management processes, reducing buyer risk","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because recognized quality standards assure corporate customers that deliveries will meet specifications reliably.","distractor_reasons":{"A":"Incorrect because ISO certification helps suppliers win profitable contracts.","B":"Incorrect because transport logistics are still required.","C":"Incorrect because ISO 9001 is an international quality management standard, not a tax.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_787","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_787","question":"What is a potential bureaucratic drawback if 'quality assurance' documentation is poorly managed?","options":{"A":"Excessive paperwork, rigid checklists, and time-consuming form-filling can slow down staff and feel overly bureaucratic","B":"Workers have zero guidelines on how to perform their tasks","C":"Customers receive defective products more frequently","D":"Suppliers deliver raw materials without any specification checks"},"correctOption":"A","correctAnswer":"Excessive paperwork, rigid checklists, and time-consuming form-filling can slow down staff and feel overly bureaucratic","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because overly heavy compliance paperwork can frustrate employees unless streamlined digitally.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality assurance provides clear guidelines.","C":"Incorrect because quality assurance reduces customer defects.","D":"Incorrect because quality assurance audits suppliers rigorously."}}},{"id":"P1_U4_MCQ_788","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_788","question":"A smartphone manufacturer ships 5,000 phones with faulty charging ports. Which direct consequence is most likely to reduce the business's profit?","options":{"A":"Higher costs from warranty repairs, product replacements, and customer refunds, alongside damaged brand reputation","B":"Lower customer service workload and higher repeat sales","C":"Immediate reduction in raw material purchase prices","D":"Higher customer loyalty because buyers enjoy returning phones"},"correctOption":"A","correctAnswer":"Higher costs from warranty repairs, product replacements, and customer refunds, alongside damaged brand reputation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because poor quality creates direct repair, replacement, and refund costs while discouraging future sales.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because faulty products increase customer complaints and reduce repeat purchases.","C":"Incorrect because shipping defective goods does not lower supplier prices.","D":"Incorrect because product faults frustrate customers and harm brand loyalty."}}},{"id":"P1_U4_MCQ_789","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_789","question":"How can a hotel chain best apply quality assurance to maintain high service standards across all its branches?","options":{"A":"Only inspect bedrooms after guests complain at checkout","B":"Provide thorough staff induction training, clear room-cleaning checklists, and regular hygiene audits before guests arrive","C":"Stop training reception and housekeeping staff to save money","D":"Allow each branch manager to ignore guest safety standards"},"correctOption":"B","correctAnswer":"Provide thorough staff induction training, clear room-cleaning checklists, and regular hygiene audits before guests arrive","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because quality assurance sets consistent standards and trains staff across every stage of service delivery to prevent guest dissatisfaction.","distractor_reasons":{"A":"Incorrect because reacting after guest complaints fails to prevent poor service experiences.","B":"Correct selection.","C":"Incorrect because cutting staff training leads to inconsistent service quality.","D":"Incorrect because consistent branch-wide standards are essential for hotel chains."}}},{"id":"P1_U4_MCQ_790","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_790","question":"A small start-up workshop makes simple wooden garden crates with a limited budget and a few semi-skilled workers. Why might management initially choose quality control over a full quality assurance system?","options":{"A":"Quality control completely prevents any wood from ever being wasted","B":"Quality control requires zero inspection of finished crates","C":"Checking finished crates before dispatch is simpler and cheaper to set up than training all staff in formal quality assurance procedures","D":"Quality assurance is illegal for small start-up businesses"},"correctOption":"C","correctAnswer":"Checking finished crates before dispatch is simpler and cheaper to set up than training all staff in formal quality assurance procedures","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because end-of-line quality control requires lower initial setup and training expenditure for a small, budget-constrained business.","distractor_reasons":{"A":"Incorrect because end-of-line quality control finds faults after wood has already been cut and nailed.","B":"Incorrect because quality control relies on inspecting finished items.","C":"Correct selection.","D":"Incorrect because quality assurance is legal for businesses of any size."}}},{"id":"P1_U4_MCQ_791","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_791","question":"Why does a high-end chocolate manufacturer carefully vet cocoa-bean suppliers and inspect incoming deliveries as part of its quality assurance?","options":{"A":"Because poor-quality cocoa beans can be turned into luxury chocolate without affecting taste","B":"Because inspecting deliveries increases the number of spoiled beans used","C":"Because supplier checks eliminate the need for factory hygiene standards","D":"Because consistent, high-grade raw ingredients are essential to prevent defects during production and protect product taste"},"correctOption":"D","correctAnswer":"Because consistent, high-grade raw ingredients are essential to prevent defects during production and protect product taste","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because quality assurance begins at the input stage to ensure defective raw materials do not ruin final output.","distractor_reasons":{"A":"Incorrect because inferior ingredients directly harm finished product quality.","B":"Incorrect because incoming checks reject spoiled beans before production.","C":"Incorrect because factory hygiene remains essential throughout manufacturing.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_792","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_792","question":"A bottling factory produces 50,000 cans of sparkling juice per hour. Why do quality control technicians test statistical samples from each production run rather than opening every single can?","options":{"A":"Opening every can would destroy the entire output and halt high-speed flow production, whereas sample testing checks quality efficiently","B":"Technicians are legally forbidden from testing more than one can per year","C":"Unopened cans never have any quality defects","D":"Sample testing increases the cost of wasted product to 100%"},"correctOption":"A","correctAnswer":"Opening every can would destroy the entire output and halt high-speed flow production, whereas sample testing checks quality efficiently","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sample inspection monitors batch consistency without destroying sellable inventory or slowing continuous flow lines.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because factories test regular samples throughout every shift.","C":"Incorrect because sealing or carbonation faults can occur during production.","D":"Incorrect because sample testing sacrifices only a tiny fraction of cans."}}},{"id":"P1_U4_MCQ_793","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_793","question":"In a car assembly plant operating quality assurance, who is responsible for maintaining quality standards?","options":{"A":"Only the external government safety inspector who visits once a year","B":"Every employee at each stage of design, component sourcing, assembly, and testing","C":"Only the final quality control inspector at the factory exit gate","D":"Only the customers after they buy the car"},"correctOption":"B","correctAnswer":"Every employee at each stage of design, component sourcing, assembly, and testing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because quality assurance organizes the whole workforce to follow agreed standards at every stage so faults are prevented.","distractor_reasons":{"A":"Incorrect because external regulators audit compliance rather than running daily factory quality.","B":"Correct selection.","C":"Incorrect because relying solely on a final exit-gate inspector describes quality control.","D":"Incorrect because the manufacturer is responsible for delivering safe, reliable vehicles."}}},{"id":"P1_U4_MCQ_794","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_794","question":"Two rival cafés on the same high street charge identical prices for coffee and pastries. How does superior service and food quality give one café a competitive advantage?","options":{"A":"It allows the café to reduce opening hours to one hour per day","B":"It forces the café to spend more money replacing burnt pastries","C":"Customers enjoy a better experience, return regularly, and recommend the café to friends, increasing market share","D":"It eliminates the need to buy fresh milk or coffee beans"},"correctOption":"C","correctAnswer":"Customers enjoy a better experience, return regularly, and recommend the café to friends, increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because superior quality differentiates the business at the same price point, driving repeat visits and positive word-of-mouth.","distractor_reasons":{"A":"Incorrect because higher customer demand encourages full opening hours.","B":"Incorrect because good quality reduces burnt food waste.","C":"Correct selection.","D":"Incorrect because fresh ingredients are essential to maintain food quality."}}},{"id":"P1_U4_MCQ_795","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_795","question":"Why can relying purely on end-of-line quality control inspectors reduce production workers' care during assembly?","options":{"A":"Workers assume inspectors will catch any mistakes later, reducing their own sense of personal responsibility for getting work right first time","B":"Workers spend too much time inspecting their own work","C":"Quality control inspectors pay workers bonuses for every defect made","D":"Quality control forces workers to design new products"},"correctOption":"A","correctAnswer":"Workers assume inspectors will catch any mistakes later, reducing their own sense of personal responsibility for getting work right first time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because separating inspection from production can encourage workers to leave fault-finding to inspectors instead of preventing errors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because self-checking at each stage is a feature of quality assurance.","C":"Incorrect because defects are penalized or rejected rather than rewarded.","D":"Incorrect because product design is handled by R&D/design teams."}}},{"id":"P1_U4_MCQ_796","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_796","question":"Why is quality assurance strongly recommended over end-of-line quality control for a manufacturer of aircraft engine parts?","options":{"A":"Aircraft engine parts are cheap disposable items where defects do not matter","B":"Quality assurance requires zero staff training or documentation","C":"Quality control prevents faults from occurring during machining","D":"Preventing defects at every manufacturing stage avoids catastrophic safety failures and expensive scrap of precision alloy components"},"correctOption":"D","correctAnswer":"Preventing defects at every manufacturing stage avoids catastrophic safety failures and expensive scrap of precision alloy components","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when defects carry severe safety risks and high scrap costs, stage-by-stage prevention is essential.","distractor_reasons":{"A":"Incorrect because aircraft parts are expensive and safety-critical.","B":"Incorrect because quality assurance relies on rigorous training and documented checks.","C":"Incorrect because quality control detects faults after production rather than preventing them.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_797","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_797","question":"What is a potential drawback of 'mystery shopping' as a quality-control tool in retail or hospitality?","options":{"A":"Mystery shoppers never submit reports to management","B":"It is illegal under consumer protection laws","C":"It provides only a snapshot of a single visit, can be expensive to hire agencies, and may create distrust if staff feel spied upon","D":"It permanently replaces all employee training programmes"},"correctOption":"C","correctAnswer":"It provides only a snapshot of a single visit, can be expensive to hire agencies, and may create distrust if staff feel spied upon","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because mystery shopping is a periodic sample check rather than continuous assurance, and requires constructive coaching follow-up.","distractor_reasons":{"A":"Incorrect because detailed evaluation reports are the core output of mystery shopping.","B":"Incorrect because mystery shopping is a standard, legal business practice.","C":"Correct selection.","D":"Incorrect because mystery shopping identifies where training is needed rather than replacing it."}}},{"id":"P1_U4_MCQ_798","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_798","question":"How do 'online customer reviews and star ratings' affect the importance of quality management today?","options":{"A":"Online reviews make product quality unimportant because customers ignore ratings","B":"Businesses can legally delete all negative customer reviews across the internet","C":"Poor reviews automatically lower a factory's variable raw material costs","D":"Quality failures become instantly visible to millions of prospective buyers worldwide, making consistent quality vital to protect sales"},"correctOption":"D","correctAnswer":"Quality failures become instantly visible to millions of prospective buyers worldwide, making consistent quality vital to protect sales","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because digital word-of-mouth amplifies both excellent quality and quality failures immediately.","distractor_reasons":{"A":"Incorrect because shoppers rely heavily on online ratings before buying.","B":"Incorrect because independent platforms restrict manipulation of genuine customer reviews.","C":"Incorrect because bad reviews reduce sales rather than lowering material costs.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_799","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_799","question":"What is meant by 'traceability' in food, automotive, and pharmaceutical quality assurance?","options":{"A":"Using batch codes and digital records to track every raw material supplier, production date, and distribution destination so any faulty batch can be isolated rapidly","B":"Tracing product sketches onto tracing paper by hand","C":"Refusing to keep records of where raw materials were purchased","D":"Recalling every product ever made over ten years when one single bottle is faulty"},"correctOption":"A","correctAnswer":"Using batch codes and digital records to track every raw material supplier, production date, and distribution destination so any faulty batch can be isolated rapidly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because precise batch traceability limits recalls to the exact affected lot, saving huge costs and protecting public safety.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because traceability is supply-chain batch tracking, not manual sketching.","C":"Incorrect because traceability requires comprehensive supplier and batch records.","D":"Incorrect because traceability prevents unnecessary blanket recalls by isolating the specific affected batch."}}},{"id":"P1_U4_MCQ_800","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_800","question":"Why does a quality assurance system require strong management commitment and support to stay effective over time?","options":{"A":"Because quality assurance eliminates the need for any employee training","B":"If managers prioritize hitting fast output quotas over agreed quality standards, employees stop following stage-by-stage checks and defect rates rise","C":"Because quality assurance is legally required to replace all factory machinery","D":"Because quality assurance transfers all responsibility to end-of-line inspectors"},"correctOption":"B","correctAnswer":"If managers prioritize hitting fast output quotas over agreed quality standards, employees stop following stage-by-stage checks and defect rates rise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because quality assurance succeeds only when management consistently reinforces quality standards and supports workers in maintaining them.","distractor_reasons":{"A":"Incorrect because quality assurance requires ongoing staff training.","B":"Correct selection.","C":"Incorrect because quality assurance focuses on process standards rather than replacing machinery.","D":"Incorrect because end-of-line inspectors define quality control rather than quality assurance."}}},{"id":"P1_U4_MCQ_801","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_801","question":"How does 'preventative machine maintenance' directly support quality assurance?","options":{"A":"It allows machines to operate with worn-out blades and misaligned sensors","B":"It eliminates the need to calibrate measuring gauges","C":"Regular servicing and calibration keep machinery cutting and assembling within exact tolerances, preventing gradual drift into defective output","D":"It increases the number of unplanned breakdowns"},"correctOption":"C","correctAnswer":"Regular servicing and calibration keep machinery cutting and assembling within exact tolerances, preventing gradual drift into defective output","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because worn tools and uncalibrated equipment produce out-of-spec items even when operators follow procedures.","distractor_reasons":{"A":"Incorrect because worn blades are replaced before causing defects.","B":"Incorrect because regular calibration is a core part of preventative maintenance.","C":"Correct selection.","D":"Incorrect because preventative maintenance reduces unplanned breakdowns."}}},{"id":"P1_U4_MCQ_802","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_802","question":"What is the difference between 'internal failure costs' and 'external failure costs' of poor quality?","options":{"A":"Internal failure costs occur after customers buy the product, whereas external failure costs occur inside the factory","B":"Internal failure costs are always higher than external product recalls","C":"There is no difference between internal and external failure costs","D":"Internal failure costs (scrap, rework) are incurred when defects are caught before dispatch, whereas external failure costs (recalls, warranty claims, lost reputation) occur after reaching customers"},"correctOption":"D","correctAnswer":"Internal failure costs (scrap, rework) are incurred when defects are caught before dispatch, whereas external failure costs (recalls, warranty claims, lost reputation) occur after reaching customers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because catching faults internally before shipping is far less damaging than letting faulty goods reach external buyers.","distractor_reasons":{"A":"Incorrect because the definitions are reversed.","B":"Incorrect because external recalls and brand damage are usually far costlier than internal rework.","C":"Incorrect because timing of detection determines whether customer trust is harmed.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_803","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_803","question":"Why might a small start-up business initially use basic 'quality control' before investing in full ISO-certified 'quality assurance'?","options":{"A":"Limited financial capital and small workforce make simple inspection affordable initially, whereas full QA training and certification can be added as the firm scales","B":"Small start-ups are legally banned from producing high-quality goods","C":"Start-ups have unlimited funds for ISO consultants","D":"Customers never care about quality when buying from small businesses"},"correctOption":"A","correctAnswer":"Limited financial capital and small workforce make simple inspection affordable initially, whereas full QA training and certification can be added as the firm scales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash-constrained start-ups often adopt low-cost inspection first and formalize QA systems as order volumes grow.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because start-ups strive for high quality to win early customers.","C":"Incorrect because start-ups typically face tight capital budgets.","D":"Incorrect because early customer satisfaction is vital for start-up survival."}}},{"id":"P1_U4_MCQ_804","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_804","question":"How does 'reducing product defects' improve a business's environmental sustainability as well as its profit margin?","options":{"A":"Defective products require zero raw materials to make","B":"Fewer scrapped items mean less wasted raw materials, energy, and landfill disposal for every good unit sold","C":"Scrapping faulty items reduces carbon emissions","D":"High defect rates conserve natural resources"},"correctOption":"B","correctAnswer":"Fewer scrapped items mean less wasted raw materials, energy, and landfill disposal for every good unit sold","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because every scrapped product wastes all the energy and natural resources embodied in its manufacture.","distractor_reasons":{"A":"Incorrect because scrapped items consume full raw materials.","B":"Correct selection.","C":"Incorrect because scrapping wastes the carbon emitted during production.","D":"Incorrect because high defects deplete resources unnecessarily."}}},{"id":"P1_U4_MCQ_805","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_805","question":"What is a key benefit of 'empowering shop-floor workers to stop the assembly line' (andon cord) when they spot a quality defect?","options":{"A":"The assembly line stays stopped permanently","B":"Faulty parts are hidden inside finished boxes so inspectors cannot find them","C":"The root cause of the defect is fixed immediately before hundreds of faulty units are produced down the line","D":"Workers no longer need any training in quality standards"},"correctOption":"C","correctAnswer":"The root cause of the defect is fixed immediately before hundreds of faulty units are produced down the line","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because stopping briefly to fix an error immediately prevents mass defects and reinforces zero-defect accountability.","distractor_reasons":{"A":"Incorrect because teams resolve the issue quickly and restart the line.","B":"Incorrect because stopping the line exposes defects openly rather than hiding them.","C":"Correct selection.","D":"Incorrect because workers must be trained to recognize deviations immediately."}}},{"id":"P1_U4_MCQ_806","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_806","question":"How do 'warranties and after-sales support' reinforce perceived product quality?","options":{"A":"They prove the product is designed to break within one week","B":"They eliminate the need for factory quality checks","C":"They prevent customers from ever returning faulty goods","D":"Offering a multi-year warranty signals manufacturer confidence in durability and reduces perceived purchase risk for buyers"},"correctOption":"D","correctAnswer":"Offering a multi-year warranty signals manufacturer confidence in durability and reduces perceived purchase risk for buyers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because strong warranties reassure customers and are financially viable only when internal quality assurance keeps failure rates very low.","distractor_reasons":{"A":"Incorrect because long warranties signal durability rather than fragility.","B":"Incorrect because strong internal quality is required so warranty claims stay low.","C":"Incorrect because warranties give customers the right to free repair or replacement.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_807","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_807","question":"Why is 'standardization of procedures' essential for franchise businesses (such as global fast-food or hotel chains) to maintain quality?","options":{"A":"It ensures customers experience the same consistent food taste, hygiene, and service speed regardless of which branch they visit","B":"It allows each franchisee to invent completely different menus and hygiene rules","C":"It eliminates the need to inspect franchise branches","D":"It forces franchisees to buy poor-quality local ingredients"},"correctOption":"A","correctAnswer":"It ensures customers experience the same consistent food taste, hygiene, and service speed regardless of which branch they visit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because brand reputation in franchising depends on uniform quality across hundreds of independently operated locations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because arbitrary variation undermines brand consistency.","C":"Incorrect because franchisors conduct regular quality audits of branches.","D":"Incorrect because franchisors require approved high-quality suppliers."}}},{"id":"P1_U4_MCQ_808","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_808","question":"What happens to a business's 'added value' when it achieves superior quality that allows a higher selling price without raising material costs?","options":{"A":"Added value falls to zero","B":"Added value increases because the gap between selling price and bought-in material costs widens","C":"Added value stays completely unchanged","D":"Added value becomes negative"},"correctOption":"B","correctAnswer":"Added value increases because the gap between selling price and bought-in material costs widens","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high quality strengthens brand differentiation and supports premium pricing above input costs.","distractor_reasons":{"A":"Incorrect because a higher price increases added value.","B":"Correct selection.","C":"Incorrect because selling price directly determines added value.","D":"Incorrect because higher price widens positive added value."}}},{"id":"P1_U4_MCQ_809","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_809","question":"Why is 'cleanroom manufacturing' (filtered air, protective suits, strict dust control) used in semiconductor and medical-device production?","options":{"A":"Because workers enjoy wearing protective suits for fashion","B":"Because cleanrooms eliminate the need for electricity","C":"Because even a single microscopic dust particle or bacterium can ruin a microchip circuit or contaminate a sterile medical implant","D":"Because cleanrooms lower initial factory construction costs"},"correctOption":"C","correctAnswer":"Because even a single microscopic dust particle or bacterium can ruin a microchip circuit or contaminate a sterile medical implant","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because ultra-sensitive products require strict environmental control as a core preventative quality assurance measure.","distractor_reasons":{"A":"Incorrect because cleanroom garments prevent human skin/hair contamination.","B":"Incorrect because cleanroom air filtration consumes substantial electricity.","C":"Correct selection.","D":"Incorrect because cleanrooms are very expensive to build and operate."}}},{"id":"P1_U4_MCQ_810","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_810","question":"How does 'customer complaints analysis' help operations managers improve quality?","options":{"A":"By ignoring customer emails so managers save reading time","B":"By blaming customers for every product malfunction","C":"By eliminating all internal quality assurance checks","D":"By tracking recurring patterns in returns and complaints so engineering and production teams can fix the underlying root causes"},"correctOption":"D","correctAnswer":"By tracking recurring patterns in returns and complaints so engineering and production teams can fix the underlying root causes","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because systematic complaint feedback turns customer problems into actionable design and process improvements.","distractor_reasons":{"A":"Incorrect because ignoring complaints leads to lost customers and repeated faults.","B":"Incorrect because defensive blaming prevents operational learning.","C":"Incorrect because complaint data strengthens internal quality checks.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_811","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_811","question":"What is a potential risk of focusing exclusively on 'cutting production costs' without protecting quality?","options":{"A":"Using inferior raw materials and rushing workers causes defects, returns, and brand damage that reduce sales and profit far more than the cost savings","B":"Lower material quality automatically increases customer loyalty","C":"Cheaper materials always last longer than high-grade inputs","D":"Cutting quality checks eliminates all warranty claims"},"correctOption":"A","correctAnswer":"Using inferior raw materials and rushing workers causes defects, returns, and brand damage that reduce sales and profit far more than the cost savings","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because false economies that degrade quality destroy customer trust and inflate failure costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because inferior quality drives customers away.","C":"Incorrect because substandard materials wear out or break faster.","D":"Incorrect because skipping checks increases defective deliveries and warranty claims."}}},{"id":"P1_U4_MCQ_812","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_812","question":"In a hospital or commercial airline, why is 'quality assurance' far more appropriate than end-of-line quality control?","options":{"A":"Because hospitals and airlines have zero safety regulations","B":"Because a single error during surgery or flight maintenance can be fatal and cannot be 'reworked' after the event; every step must be verified right first time","C":"Because quality assurance requires zero staff training","D":"Because patients and passengers are physical goods on a conveyor belt"},"correctOption":"B","correctAnswer":"Because a single error during surgery or flight maintenance can be fatal and cannot be 'reworked' after the event; every step must be verified right first time","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because safety-critical services demand preventative checklists, certified training, and strict stage verification.","distractor_reasons":{"A":"Incorrect because aviation and healthcare face the strictest safety regulations.","B":"Correct selection.","C":"Incorrect because aviation and medical staff undergo intensive training.","D":"Incorrect because healthcare and aviation are live human services."}}},{"id":"P1_U4_MCQ_813","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_813","question":"How does 'staff retention and low labour turnover' support consistent product and service quality?","options":{"A":"New inexperienced hires make fewer mistakes than veteran staff","B":"High staff turnover eliminates the need for training","C":"Experienced, well-trained employees understand quality standards deeply and make far fewer errors than constantly changing new recruits","D":"Long-serving employees never follow quality checklists"},"correctOption":"C","correctAnswer":"Experienced, well-trained employees understand quality standards deeply and make far fewer errors than constantly changing new recruits","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because retaining skilled staff preserves institutional know-how and consistent execution.","distractor_reasons":{"A":"Incorrect because inexperienced new hires typically have higher error rates during learning.","B":"Incorrect because high turnover increases recurring training costs.","C":"Correct selection.","D":"Incorrect because experienced staff uphold established standards."}}},{"id":"P1_U4_MCQ_814","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_814","question":"Which statement best compares 'quality control' and 'quality assurance'?","options":{"A":"Both rely solely on inspecting finished products at the end of the assembly line","B":"Quality control prevents faults at every stage, while quality assurance only inspects finished goods at the end","C":"Neither approach aims to satisfy customer expectations","D":"Quality control detects defects at the end via specialist inspectors, whereas quality assurance prevents defects at every production stage through all employees"},"correctOption":"D","correctAnswer":"Quality control detects defects at the end via specialist inspectors, whereas quality assurance prevents defects at every production stage through all employees","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because it accurately distinguishes end-of-line inspection (quality control) from stage-by-stage defect prevention (quality assurance).","distractor_reasons":{"A":"Incorrect because only quality control relies on end-of-line inspection.","B":"Incorrect because the definitions are reversed.","C":"Incorrect because meeting or exceeding customer expectations is the core goal of both methods.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_815","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_815","question":"Why do heavy steelworks and cement plants traditionally locate close to coal, iron ore, or limestone deposits?","options":{"A":"Because these industries are weight-losing processes that consume massive quantities of heavy, bulky raw minerals, so locating near sources minimizes inbound freight costs","B":"Because steelworks sell steel girders directly to walk-in mall shoppers","C":"Because mineral deposits are always found inside city centres","D":"Because raw iron ore weighs less than finished steel bars"},"correctOption":"A","correctAnswer":"Because these industries are weight-losing processes that consume massive quantities of heavy, bulky raw minerals, so locating near sources minimizes inbound freight costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because smelting and cement kilns lose huge amounts of waste rock/gas during processing, making raw-material proximity economical.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because steelworks supply industrial B2B buyers rather than retail mall shoppers.","C":"Incorrect because mines and quarries are located in resource-rich rural/industrial regions.","D":"Incorrect because raw iron ore is far heavier than the pure steel extracted from it."}}},{"id":"P1_U4_MCQ_816","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_816","question":"Why do bakeries producing fresh daily bread and newspapers printing daily print editions locate close to major urban markets?","options":{"A":"Because wheat fields and timber forests are located inside city centres","B":"Because their products are time-sensitive and perishable (losing value within hours), requiring rapid local distribution to urban consumers","C":"Because city centres offer free rent for industrial bakeries","D":"Because fresh bread lasts for five years without spoiling"},"correctOption":"B","correctAnswer":"Because their products are time-sensitive and perishable (losing value within hours), requiring rapid local distribution to urban consumers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because perishable or time-critical finished goods must reach consumers immediately after production.","distractor_reasons":{"A":"Incorrect because wheat and timber come from rural farms and forests.","B":"Correct selection.","C":"Incorrect because urban rents are high rather than free.","D":"Incorrect because fresh bread goes stale within days."}}},{"id":"P1_U4_MCQ_817","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_817","question":"Why are 'footloose' light-manufacturing and software businesses able to locate almost anywhere with good broadband and road links?","options":{"A":"Because they consume thousands of tonnes of heavy iron ore daily","B":"Because they rely exclusively on walk-in high-street shoppers","C":"Because their raw materials and finished outputs are light, high-value, and inexpensive to transport, freeing them from raw-material or market proximity constraints","D":"Because governments ban them from locating near universities"},"correctOption":"C","correctAnswer":"Because their raw materials and finished outputs are light, high-value, and inexpensive to transport, freeing them from raw-material or market proximity constraints","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when transport costs are a tiny fraction of total cost, businesses can prioritize talent pools, quality of life, or low rent.","distractor_reasons":{"A":"Incorrect because heavy raw-material users are tied to resource locations.","B":"Incorrect because footloose firms sell nationally/globally rather than to walk-in shoppers.","C":"Correct selection.","D":"Incorrect because high-tech footloose firms frequently locate near universities."}}},{"id":"P1_U4_MCQ_818","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_818","question":"Why do competing car dealerships, furniture stores, or fashion retailers often cluster together in the same retail park or shopping street?","options":{"A":"To prevent any shoppers from visiting the area","B":"Because laws forbid retailers from opening standalone stores","C":"To share the exact same cash register and bank account","D":"Because clustering attracts a large volume of comparison shoppers to one destination, increasing total footfall and sales for all stores"},"correctOption":"D","correctAnswer":"Because clustering attracts a large volume of comparison shoppers to one destination, increasing total footfall and sales for all stores","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumers prefer visiting one location where they can compare multiple brands easily.","distractor_reasons":{"A":"Incorrect because clustering increases shopper traffic.","B":"Incorrect because standalone stores are legal; clustering is a commercial choice.","C":"Incorrect because rival stores remain independent competing businesses.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_819","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_819","question":"Why do motor-vehicle component suppliers often locate right next to major car assembly plants?","options":{"A":"To enable reliable, low-cost Just-in-Time (JIT) deliveries of bulky parts directly to the assembly line with minimal transport delay","B":"To sell car seats directly to passing pedestrians","C":"Because car assembly plants supply free electricity to neighbours","D":"To avoid hiring any delivery drivers"},"correctOption":"A","correctAnswer":"To enable reliable, low-cost Just-in-Time (JIT) deliveries of bulky parts directly to the assembly line with minimal transport delay","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automotive assemblers operate strict JIT schedules where even a 30-minute component delay halts production.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because component makers are B2B suppliers.","C":"Incorrect because suppliers pay their own utility bills.","D":"Incorrect because short-shuttle drivers still transport parts between plants."}}},{"id":"P1_U4_MCQ_820","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_820","question":"What trade-off must a retailer weigh when choosing between a prime city-centre high-street shop and an out-of-town retail park?","options":{"A":"City centres have zero pedestrian footfall, whereas retail parks have millions of pedestrians","B":"City centres offer high pedestrian footfall and public-transit access at very high rent and limited parking, whereas retail parks offer lower rent, large floor space, and free car parking","C":"Retail parks charge ten times higher rent than prime city-centre streets","D":"City-centre shops are banned from selling clothing or electronics"},"correctOption":"B","correctAnswer":"City centres offer high pedestrian footfall and public-transit access at very high rent and limited parking, whereas retail parks offer lower rent, large floor space, and free car parking","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because prime urban locations trade higher fixed rent for walk-in traffic, whereas out-of-town parks suit car-driving bulk shoppers.","distractor_reasons":{"A":"Incorrect because city centres have high pedestrian footfall.","B":"Correct selection.","C":"Incorrect because prime city-centre rents are higher than out-of-town parks.","D":"Incorrect because city centres feature extensive clothing and electronics retail."}}},{"id":"P1_U4_MCQ_821","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_821","question":"Why do multinational banks, law firms, and corporate headquarters cluster in major financial districts (such as London, New York, Singapore, or Kuala Lumpur)?","options":{"A":"To benefit from low-cost agricultural land and cheap farm labour","B":"Because financial districts charge the lowest office rents in the country","C":"To gain prestige, face-to-face proximity to major corporate clients, international airports, regulatory institutions, and deep pools of specialist financial talent","D":"To locate beside open-cast coal mines"},"correctOption":"C","correctAnswer":"To gain prestige, face-to-face proximity to major corporate clients, international airports, regulatory institutions, and deep pools of specialist financial talent","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because prestige, global connectivity, and external economies of scale outweigh high city-centre office rents for corporate headquarters.","distractor_reasons":{"A":"Incorrect because financial districts are dense urban centres.","B":"Incorrect because financial districts command the highest commercial rents.","C":"Correct selection.","D":"Incorrect because coal mines are unrelated to financial services."}}},{"id":"P1_U4_MCQ_822","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_822","question":"How does the 'cost and availability of land' affect the location of large-scale manufacturing plants and logistics warehouses?","options":{"A":"Large single-storey automated factories require vast plots of affordable flat land, making out-of-town or regional industrial sites far more viable than cramped city centres","B":"Automated warehouses operate best inside tiny tenth-floor city apartments","C":"Land prices are identical in city centres and rural industrial parks","D":"Manufacturers never consider land purchase or lease costs"},"correctOption":"D","correctAnswer":"Manufacturers never consider land purchase or lease costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because modern horizontal production flows and heavy-lorry turning yards demand extensive, affordable acreage.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because warehouses require ground-level lorry loading bays and wide floor plates.","C":"Incorrect because urban land is vastly more expensive per square metre than regional industrial land.","D":"Incorrect because property cost is a major quantitative location factor."}}},{"id":"P1_U4_MCQ_823","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_823","question":"Note: Re-checking option alignment—which statement accurately explains why 'power and water supply reliability' is decisive for heavy industries such as aluminium smelting or semiconductor fabrication?","options":{"A":"A brief power outage or voltage fluctuation can solidify molten metal in furnaces or ruin millions of dollars of silicon wafers, requiring uninterrupted high-capacity utilities","B":"Semiconductor factories use zero electricity or ultra-pure water","C":"Aluminium smelters run purely on manual bicycle pedals","D":"Utility companies give unlimited electricity free to every factory"},"correctOption":"A","correctAnswer":"A brief power outage or voltage fluctuation can solidify molten metal in furnaces or ruin millions of dollars of silicon wafers, requiring uninterrupted high-capacity utilities","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because energy-intensive and precision processes suffer catastrophic financial losses if grid power or water supplies fail.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because chip fabrication consumes huge amounts of electricity and ultra-pure water.","C":"Incorrect because aluminium electrolysis requires massive electrical current.","D":"Incorrect because utility tariffs are a major operating cost."}}},{"id":"P1_U4_MCQ_824","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_824","question":"How can 'local community opposition' (NIMBYism — 'Not In My Back Yard') affect a business's location plans?","options":{"A":"Local residents always campaign for noisy 24-hour freight depots next to primary schools","B":"Resident protests and objections to noise, traffic congestion, or pollution can delay or block planning permission, forcing the business to choose another site","C":"Community protests automatically lower the business's corporate tax rate","D":"Businesses never require local government planning permission to build factories"},"correctOption":"B","correctAnswer":"Resident protests and objections to noise, traffic congestion, or pollution can delay or block planning permission, forcing the business to choose another site","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because local councils weigh community objections when granting building permits, making stakeholder consultation important.","distractor_reasons":{"A":"Incorrect because residents strongly oppose heavy traffic and noise near schools.","B":"Correct selection.","C":"Incorrect because protests do not reduce tax rates.","D":"Incorrect because zoning and building permits are legally required."}}},{"id":"P1_U4_MCQ_825","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_825","question":"What is meant by 'offshoring' in international location decisions?","options":{"A":"Building floating factories on ships in the middle of the ocean","B":"Moving a factory from a city centre to a nearby suburb in the same country","C":"Relocating a business's production, assembly, or customer-service operations to another country to reduce costs or access foreign markets","D":"Closing down all international trade and selling only locally"},"correctOption":"C","correctAnswer":"Relocating a business's production, assembly, or customer-service operations to another country to reduce costs or access foreign markets","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because offshoring shifts business processes across national borders to take advantage of lower wages, tax incentives, or market proximity.","distractor_reasons":{"A":"Incorrect because offshoring refers to locating in foreign countries, not floating barges.","B":"Incorrect because moving within the same country is domestic relocation.","C":"Correct selection.","D":"Incorrect because offshoring increases cross-border operations."}}},{"id":"P1_U4_MCQ_826","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_826","question":"What is meant by 'reshoring' (onshoring), and why have some manufacturers recently brought overseas production back to their home country?","options":{"A":"Moving factories further away into remote overseas regions","B":"Selling a business to a foreign government","C":"Eliminating all automation in domestic factories","D":"Bringing previously offshored production back to the domestic country due to rising overseas wages, shipping delays, quality issues, and domestic automation"},"correctOption":"D","correctAnswer":"Bringing previously offshored production back to the domestic country due to rising overseas wages, shipping delays, quality issues, and domestic automation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because rising freight costs, geopolitical supply risks, and domestic robotics have narrowed overseas wage advantages.","distractor_reasons":{"A":"Incorrect because moving further abroad is offshoring.","B":"Incorrect because selling to a foreign state is nationalization/foreign acquisition.","C":"Incorrect because domestic automation often makes reshoring financially viable.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_827","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_827","question":"How do 'import tariffs' and 'import quotas' influence multinational companies' factory location decisions?","options":{"A":"High tariffs or strict quotas make exporting finished goods expensive or restricted, encouraging companies to build local factories inside the target country or trading bloc","B":"Import tariffs make exported foreign goods completely free to buyers","C":"Import quotas force domestic factories to close down","D":"Trade barriers apply only to services delivered over the internet"},"correctOption":"A","correctAnswer":"High tariffs or strict quotas make exporting finished goods expensive or restricted, encouraging companies to build local factories inside the target country or trading bloc","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 'tariff-jumping' foreign direct investment allows firms to serve protected markets competitively without paying import duties.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tariffs add taxes that raise imported prices.","C":"Incorrect because quotas protect domestic production by limiting foreign imports.","D":"Incorrect because tariffs and quotas primarily target physical traded goods."}}},{"id":"P1_U4_MCQ_828","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_828","question":"Why do multinational companies often locate call centres or software-support hubs in overseas countries with strong English (or shared-language) education and lower graduate wages?","options":{"A":"Because telephone calls cannot travel across national borders","B":"Because lower skilled-service wages reduce operating costs while shared language skills enable smooth communication with home-country customers","C":"Because overseas workers never use computers or headsets","D":"Because time-zone differences make 24-hour customer support impossible"},"correctOption":"B","correctAnswer":"Because lower skilled-service wages reduce operating costs while shared language skills enable smooth communication with home-country customers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high-speed telecommunications allow service operations to combine lower labour costs with compatible language fluency.","distractor_reasons":{"A":"Incorrect because global fibre-optic networks carry voice and data instantaneously.","B":"Correct selection.","C":"Incorrect because international service hubs rely heavily on IT and telephony.","D":"Incorrect because different time zones actually help provide 24-hour follow-the-sun support."}}},{"id":"P1_U4_MCQ_829","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_829","question":"What 'quality and communication challenges' can arise when a business locates manufacturing thousands of kilometres away in a foreign country?","options":{"A":"Zero distance between head office and factory floor","B":"Identical time zones, languages, and technical standards worldwide","C":"Time-zone delays, language misunderstandings over technical specifications, and higher travel costs for quality audits can lead to defective batches","D":"Instant 5-minute van delivery of heavy machinery back to headquarters"},"correctOption":"C","correctAnswer":"Time-zone delays, language misunderstandings over technical specifications, and higher travel costs for quality audits can lead to defective batches","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because geographic and linguistic separation makes real-time troubleshooting and quality monitoring more difficult.","distractor_reasons":{"A":"Incorrect because thousands of kilometres separate head office and factory.","B":"Incorrect because international locations differ in time zones and languages.","C":"Correct selection.","D":"Incorrect because transoceanic shipping takes weeks."}}},{"id":"P1_U4_MCQ_830","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_830","question":"How can 'political instability and weak legal protection' in a host country threaten a foreign business's operations?","options":{"A":"Political instability guarantees permanent tax holidays and stable currencies","B":"Weak intellectual property laws prevent competitors from copying product designs","C":"Civil unrest eliminates all transport delays at ports","D":"Sudden changes in government policy, strikes, civil unrest, corruption, or weak patent enforcement can disrupt production and endanger assets"},"correctOption":"D","correctAnswer":"Sudden changes in government policy, strikes, civil unrest, corruption, or weak patent enforcement can disrupt production and endanger assets","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because businesses require predictable rule of law, contract enforcement, and physical security before committing large capital investments.","distractor_reasons":{"A":"Incorrect because political turmoil causes sudden policy reversals and currency volatility.","B":"Incorrect because weak IP laws increase the risk of design piracy.","C":"Incorrect because unrest and strikes frequently block ports and roads.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_831","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_831","question":"Why do differences in 'corporate tax rates' across countries influence where multinational companies locate factories or regional headquarters?","options":{"A":"Lower corporate profit tax rates allow the business to retain a larger share of net profits for reinvestment and shareholder dividends","B":"Higher corporate tax rates increase net profit after tax","C":"Corporate tax rates determine the physical weight of raw materials","D":"Businesses never pay corporate taxes in any country"},"correctOption":"A","correctAnswer":"Lower corporate profit tax rates allow the business to retain a larger share of net profits for reinvestment and shareholder dividends","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because after-tax return on investment is a key quantitative criterion in international location appraisal.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher tax rates reduce retained profit.","C":"Incorrect because tax rates are financial charges on profit.","D":"Incorrect because profitable corporations pay corporate income tax in host jurisdictions."}}},{"id":"P1_U4_MCQ_832","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_832","question":"How can 'cultural and religious differences' affect operations when a business opens branches or factories in a foreign country?","options":{"A":"Cultural differences have zero impact on product recipes, working hours, or holidays","B":"Working hours, public holidays, dietary laws, packaging colours, and management styles must be adapted respectfully to motivate local staff and appeal to local consumers","C":"Foreign workers always follow the exact same national holidays as the home country","D":"Local consumers never care whether products respect cultural norms"},"correctOption":"B","correctAnswer":"Working hours, public holidays, dietary laws, packaging colours, and management styles must be adapted respectfully to motivate local staff and appeal to local consumers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because respecting local customs, prayer/rest schedules, and product preferences is essential for smooth operations and market acceptance.","distractor_reasons":{"A":"Incorrect because culture directly shapes workplace schedules and consumer tastes.","B":"Correct selection.","C":"Incorrect because host countries observe their own national and religious calendars.","D":"Incorrect because cultural insensitivity causes product boycotts and staff conflict."}}},{"id":"P1_U4_MCQ_833","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_833","question":"Why is 'proximity to raw materials' less critical today for many manufacturers than it was a century ago?","options":{"A":"Because manufacturers no longer use any raw materials","B":"Because raw materials are now transported via wireless Wi-Fi","C":"Because modern container shipping, bulk railways, and motorway networks have drastically reduced freight costs per tonne and speeded up global supply chains","D":"Because all mines and forests have moved into city centres"},"correctOption":"C","correctAnswer":"Because modern container shipping, bulk railways, and motorway networks have drastically reduced freight costs per tonne and speeded up global supply chains","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because containerized global transport allows firms to import raw inputs economically while locating near skilled labour or consumer markets.","distractor_reasons":{"A":"Incorrect because physical manufacturing still consumes raw materials.","B":"Incorrect because physical materials travel by ship, train, and lorry.","C":"Correct selection.","D":"Incorrect because natural resources remain fixed geographically."}}},{"id":"P1_U4_MCQ_834","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_834","question":"Why do 'dark stores' and 'micro-fulfilment centres' (small urban warehouses closed to walk-in shoppers) locate inside dense residential neighbourhoods?","options":{"A":"To attract window-shoppers browsing aisles in person","B":"To smelt heavy iron ore inside apartment blocks","C":"Because inner-city rents are cheaper than rural farmland","D":"To enable ultra-fast 15-to-60-minute last-mile courier delivery of online grocery and retail orders to nearby households"},"correctOption":"D","correctAnswer":"To enable ultra-fast 15-to-60-minute last-mile courier delivery of online grocery and retail orders to nearby households","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because rapid-delivery e-commerce requires holding fast-moving stock minutes away from urban customers.","distractor_reasons":{"A":"Incorrect because dark stores are closed to the public and serve only delivery riders.","B":"Incorrect because heavy smelting is banned in residential areas.","C":"Incorrect because urban rents are higher, justified only by fast delivery premiums.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_835","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_835","question":"How does 'availability of local support services' (such as specialist machinery repair engineers, IT technicians, and packaging suppliers) influence location?","options":{"A":"Nearby specialist support services minimize costly machine downtime and supply delays, creating external economies of scale","B":"Support services increase factory fixed rent without offering any help","C":"Modern automated machinery never requires external maintenance or spare parts","D":"Support services are needed only in retail clothing boutiques"},"correctOption":"A","correctAnswer":"Nearby specialist support services minimize costly machine downtime and supply delays, creating external economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid access to spare parts and specialist engineers keeps capital-intensive plants running smoothly.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because support suppliers save money by preventing prolonged breakdowns.","C":"Incorrect because complex equipment relies heavily on specialist technicians.","D":"Incorrect because manufacturing and logistics rely most heavily on technical support networks."}}},{"id":"P1_U4_MCQ_836","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_836","question":"When is 'relocating' an existing profitable business most likely to be justified despite high moving costs?","options":{"A":"When the owner wants a slightly different wall colour in their office","B":"When current premises have zero room for expansion to meet growing demand, lease rents soar, or expiring government tax incentives make another site far more cost-effective","C":"Whenever one single employee asks for a shorter commute","D":"When the business wants to lose its existing loyal customer base"},"correctOption":"B","correctAnswer":"When current premises have zero room for expansion to meet growing demand, lease rents soar, or expiring government tax incentives make another site far more cost-effective","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because relocation is a major strategic decision justified when capacity constraints or structural cost changes block long-term growth.","distractor_reasons":{"A":"Incorrect because minor cosmetic changes do not justify disruptive relocation.","B":"Correct selection.","C":"Incorrect because relocation is driven by whole-business economics rather than one individual request.","D":"Incorrect because businesses try hard to retain loyal customers during a move."}}},{"id":"P1_U4_MCQ_837","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_837","question":"How can a retailer minimize the loss of regular customers when relocating to a nearby new store?","options":{"A":"By closing the old store secretly overnight without telling anyone","B":"By disconnecting all phone lines and deleting the website","C":"By communicating the move well in advance through signs, emails, and social media, choosing a nearby accessible site, and offering grand-reopening promotions","D":"By doubling all product prices on opening day"},"correctOption":"C","correctAnswer":"By communicating the move well in advance through signs, emails, and social media, choosing a nearby accessible site, and offering grand-reopening promotions","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because clear advance communication and accessible location preserve customer loyalty across the transition.","distractor_reasons":{"A":"Incorrect because unannounced closure confuses loyal customers and sends them to rivals.","B":"Incorrect because cutting communication channels prevents customers from finding the new site.","C":"Correct selection.","D":"Incorrect because doubling prices alienates regulars."}}},{"id":"P1_U4_MCQ_838","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_838","question":"Why do 'export processing zones' (free trade zones) established by host governments attract foreign manufacturers?","options":{"A":"They impose double import taxes on raw materials","B":"They forbid companies from exporting finished goods","C":"They require foreign firms to pay 90% corporate income tax","D":"They offer duty-free imports of components, tax holidays, streamlined customs clearance, and ready-built infrastructure for export-oriented production"},"correctOption":"D","correctAnswer":"They offer duty-free imports of components, tax holidays, streamlined customs clearance, and ready-built infrastructure for export-oriented production","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because free trade zones lower operating barriers and attract foreign direct investment and local employment.","distractor_reasons":{"A":"Incorrect because export zones waive rather than double import duties.","B":"Incorrect because export zones specifically encourage export manufacturing.","C":"Incorrect because tax holidays temporarily reduce or waive corporate taxes.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_839","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_839","question":"What ethical and reputational risk must a multinational company evaluate before locating production in a country with weak labour and environmental laws?","options":{"A":"Unsafe factory conditions, child/exploitative labour, or river pollution in its supply chain can trigger global media scandals, consumer boycotts, and loss of brand value","B":"Global consumers never read news about overseas factory disasters","C":"Weak safety laws guarantee higher product quality and worker motivation","D":"Multinational headquarters are legally immune from public criticism"},"correctOption":"A","correctAnswer":"Unsafe factory conditions, child/exploitative labour, or river pollution in its supply chain can trigger global media scandals, consumer boycotts, and loss of brand value","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because modern consumers and investors hold brands accountable for ethical and environmental standards across all global locations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supply-chain scandals spread rapidly across global media.","C":"Incorrect because poor safety lowers morale and harms quality.","D":"Incorrect because reputational damage directly hits global sales and share price."}}},{"id":"P1_U4_MCQ_840","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_840","question":"How does 'exchange rate volatility' affect a business that locates a factory abroad to export goods back to its home country?","options":{"A":"Exchange rates never change between different national currencies","B":"If the host country's currency appreciates (strengthens) sharply, local wages and factory costs become much more expensive when converted back into the home currency","C":"Appreciation of the host currency makes overseas wages completely free","D":"Exchange rates affect only businesses that sell inside one single village"},"correctOption":"B","correctAnswer":"If the host country's currency appreciates (strengthens) sharply, local wages and factory costs become much more expensive when converted back into the home currency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because currency appreciation erodes the labour-cost advantage of an offshore manufacturing base.","distractor_reasons":{"A":"Incorrect because floating exchange rates fluctuate daily.","B":"Correct selection.","C":"Incorrect because appreciation raises rather than eliminates converted wage costs.","D":"Incorrect because domestic single-village firms face no foreign currency conversion."}}},{"id":"P1_U4_MCQ_841","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_841","question":"Why do 'business parks and science parks' near major universities attract biotechnology, robotics, and software companies?","options":{"A":"Because university campuses contain huge coal and iron-ore mines","B":"Because science parks ban companies from hiring university graduates","C":"They provide access to highly skilled graduate talent, university research laboratories, and networking with innovative tech peers","D":"Because science parks have zero internet connectivity"},"correctOption":"C","correctAnswer":"They provide access to highly skilled graduate talent, university research laboratories, and networking with innovative tech peers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because R&D-driven firms value proximity to academic researchers, specialized labs, and graduate recruitment.","distractor_reasons":{"A":"Incorrect because universities provide intellectual capital rather than mineral ores.","B":"Incorrect because recruiting graduates is a primary attraction of university science parks.","C":"Correct selection.","D":"Incorrect because science parks offer ultra-fast fibre broadband."}}},{"id":"P1_U4_MCQ_842","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_842","question":"Which location factor is most critical for a drive-through coffee shop or roadside petrol/EV-charging station?","options":{"A":"Proximity to deep-sea container ports","B":"Low-rent remote mountain tops with no passing roads","C":"Proximity to coal mines and steel foundries","D":"High-visibility frontage along busy commuter roads with easy vehicle entry, exit, and parking"},"correctOption":"D","correctAnswer":"High-visibility frontage along busy commuter roads with easy vehicle entry, exit, and parking","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because convenience-driven roadside services depend entirely on passing traffic flow and effortless vehicle access.","distractor_reasons":{"A":"Incorrect because container ports serve bulk import/export freight.","B":"Incorrect because remote mountain tops lack commuter traffic.","C":"Incorrect because heavy raw materials are irrelevant to roadside retail.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_843","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_843","question":"How can 'long global supply chains' created by distant overseas locations increase inventory costs?","options":{"A":"Long sea transit times (4 to 8 weeks) and customs delays force businesses to hold larger buffer inventories to prevent stockouts, tying up working capital","B":"Sea container ships cross oceans in ten minutes","C":"Long supply chains eliminate all shipping insurance and port charges","D":"Distant overseas factories always operate with zero lead time"},"correctOption":"A","correctAnswer":"Long sea transit times (4 to 8 weeks) and customs delays force businesses to hold larger buffer inventories to prevent stockouts, tying up working capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because long, uncertain international lead times require higher safety stock in domestic warehouses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ocean freight takes weeks.","C":"Incorrect because long international routes add freight, insurance, and customs costs.","D":"Incorrect because international lead times are long rather than zero."}}},{"id":"P1_U4_MCQ_844","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_844","question":"What is the difference between 'quantitative' and 'qualitative' location factors?","options":{"A":"Quantitative factors are personal opinions, whereas qualitative factors are financial numbers","B":"Quantitative factors can be measured financially or numerically (e.g., rent, wage rates, transport costs, tax grants), whereas qualitative factors are non-numerical (e.g., quality of life, brand prestige, owner preference, political stability)","C":"Only qualitative factors affect business profitability","D":"There is no difference between quantitative and qualitative location factors"},"correctOption":"B","correctAnswer":"Quantitative factors can be measured financially or numerically (e.g., rent, wage rates, transport costs, tax grants), whereas qualitative factors are non-numerical (e.g., quality of life, brand prestige, owner preference, political stability)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because effective location appraisal combines measurable cost/revenue figures with strategic non-numerical considerations.","distractor_reasons":{"A":"Incorrect because the definitions are reversed.","B":"Correct selection.","C":"Incorrect because quantitative cost and revenue factors directly govern profit.","D":"Incorrect because one is numerically measurable and the other is descriptive/strategic."}}},{"id":"P1_U4_MCQ_845","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_845","question":"Why might a sole trader or family business choose a location partly based on 'personal preference' (such as living near family or enjoying a scenic coastal town)?","options":{"A":"Because sole traders are legally banned from maximizing profit","B":"Because coastal towns always have the lowest transport costs","C":"Because the owner is not accountable to external shareholders and may prioritize work-life balance alongside profit, provided the location remains financially viable","D":"Because personal preference eliminates the need to attract customers"},"correctOption":"C","correctAnswer":"Because the owner is not accountable to external shareholders and may prioritize work-life balance alongside profit, provided the location remains financially viable","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because independent owners have freedom to weigh lifestyle goals alongside commercial returns, unlike PLCs accountable to institutional shareholders.","distractor_reasons":{"A":"Incorrect because sole traders can pursue profit freely.","B":"Incorrect because coastal locations may have higher transport costs.","C":"Correct selection.","D":"Incorrect because the site must still generate enough demand to survive."}}},{"id":"P1_U4_MCQ_846","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_846","question":"How do 'regional development grants' from national governments work to attract businesses to high-unemployment areas?","options":{"A":"They charge businesses extra taxes for hiring local unemployed workers","B":"They force profitable factories to shut down","C":"They prohibit businesses from buying new machinery","D":"They provide non-repayable cash subsidies, subsidized factory rents, or training grants to offset higher transport/setup costs and create local jobs"},"correctOption":"D","correctAnswer":"They provide non-repayable cash subsidies, subsidized factory rents, or training grants to offset higher transport/setup costs and create local jobs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because governments use financial incentives to steer job-creating investment toward economically depressed regions.","distractor_reasons":{"A":"Incorrect because governments reward rather than tax local job creation.","B":"Incorrect because grants aim to expand employment.","C":"Incorrect because capital grants frequently help fund new machinery.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_847","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_847","question":"What risk exists if a business locates in a remote region purely to capture a short-term government grant?","options":{"A":"Once the temporary grant or tax holiday expires, ongoing high transport costs or shortages of skilled labour may make the site uncompetitive","B":"Government grants always last forever without conditions","C":"Remote regions always have the largest local consumer populations","D":"Taking a government grant makes a business exempt from paying wages"},"correctOption":"A","correctAnswer":"Once the temporary grant or tax holiday expires, ongoing high transport costs or shortages of skilled labour may make the site uncompetitive","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because long-term operational fundamentals (skills, infrastructure, market access) must remain viable after initial subsidies end.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because grants and tax holidays are typically time-limited.","C":"Incorrect because remote areas have smaller local markets.","D":"Incorrect because businesses must still pay full employee wages."}}},{"id":"P1_U4_MCQ_848","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_848","question":"Why do international freight-forwarding and distribution hubs locate near major motorway intersections, railway freight terminals, airports, or deep-water ports?","options":{"A":"To prevent delivery lorries from reaching the warehouse","B":"Multi-modal transport connectivity minimizes transit times, fuel costs, and delays when receiving bulk imports and dispatching orders nationwide","C":"Because airport runways offer free storage for supermarket groceries","D":"To attract walk-in retail window-shoppers"},"correctOption":"B","correctAnswer":"Multi-modal transport connectivity minimizes transit times, fuel costs, and delays when receiving bulk imports and dispatching orders nationwide","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because logistics hubs optimize speed and cost across road, rail, sea, and air freight corridors.","distractor_reasons":{"A":"Incorrect because motorway junctions maximize lorry accessibility.","B":"Correct selection.","C":"Incorrect because commercial logistics parks charge rent near airports.","D":"Incorrect because distribution hubs are B2B logistics facilities."}}},{"id":"P1_U4_MCQ_849","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_849","question":"How has the growth of 'online shopping (e-commerce)' changed location priorities for many retail businesses?","options":{"A":"Retailers now open ten times more expensive high-street shops and close all warehouses","B":"Online retailers require shops located directly inside coal mines","C":"Many retailers have closed costly high-street stores and invested instead in large automated regional fulfilment warehouses near major motorway networks","D":"E-commerce eliminates the need for any physical storage buildings"},"correctOption":"C","correctAnswer":"Many retailers have closed costly high-street stores and invested instead in large automated regional fulfilment warehouses near major motorway networks","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because digital storefronts shift physical space needs from expensive town-centre shops to motorway-connected logistics centres.","distractor_reasons":{"A":"Incorrect because the shift moves away from excessive high-street branches toward warehouses.","B":"Incorrect because coal mines are unrelated to retail logistics.","C":"Correct selection.","D":"Incorrect because physical goods still require storage and packing warehouses."}}},{"id":"P1_U4_MCQ_850","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_850","question":"Which statement best summarizes how senior managers should make a major 'business location decision'?","options":{"A":"Choose the cheapest land available anywhere in the world without checking transport, labour skills, or customer access","B":"Pick the location closest to the managing director's favourite golf course regardless of costs","C":"Copy a competitor's location blindly without checking local capacity or regulations","D":"Weigh both quantitative cost/revenue factors (land, labour, transport, taxes, grants) and qualitative strategic factors (skills, infrastructure, market access, regulations) aligned with business objectives"},"correctOption":"D","correctAnswer":"Weigh both quantitative cost/revenue factors (land, labour, transport, taxes, grants) and qualitative strategic factors (skills, infrastructure, market access, regulations) aligned with business objectives","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because optimal location decisions balance financial return, operational efficiency, market proximity, and long-term strategic fit.","distractor_reasons":{"A":"Incorrect because cheap land with poor transport or no skilled workers leads to high operating costs and failure.","B":"Incorrect because ignoring commercial fundamentals risks business survival.","C":"Incorrect because every business has unique resource, market, and capacity needs.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_851","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_851","question":"A furniture factory employs 40 production workers and manufactures 12,000 chairs per week. What is the weekly labour productivity?","options":{"A":"480 chairs per worker","B":"300 chairs per worker","C":"30 chairs per worker","D":"3,000 chairs per worker"},"correctOption":"B","correctAnswer":"300 chairs per worker","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because labour productivity equals total output divided by the number of workers: 12,000 chairs / 40 workers = 300 chairs per worker per week.","distractor_reasons":{"A":"Incorrect because 480 multiplies 12 by 40 rather than dividing output by workers.","B":"Correct selection.","C":"Incorrect because 30 misplaces a decimal point when dividing 12,000 by 40.","D":"Incorrect because 3,000 divides 12,000 by 4 instead of 40."}}},{"id":"P1_U4_MCQ_852","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_852","question":"Following staff training and new factory layout changes, a business increases weekly output from 8,000 units to 9,600 units while reducing its workforce from 40 workers to 32 workers. By what percentage has labour productivity increased?","options":{"A":"20%","B":"25%","C":"50%","D":"100%"},"correctOption":"C","correctAnswer":"50%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because initial productivity was 8,000 / 40 = 200 units per worker, new productivity is 9,600 / 32 = 300 units per worker, and (300 - 200) / 200 × 100% = 50%.","distractor_reasons":{"A":"Incorrect because 20% measures only the percentage rise in total output (1,600 / 8,000) without accounting for fewer workers.","B":"Incorrect because 25% miscalculates the percentage change using the new figure as the denominator.","C":"Correct selection.","D":"Incorrect because productivity rose by 100 units per worker, which is 50% of the original 200 units."}}},{"id":"P1_U4_MCQ_853","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_853","question":"A skincare manufacturer sells a jar of face cream for $45. Each jar uses $14 of bought-in organic ingredients and $3 of bought-in glass packaging. If the firm sells 500 jars in a month, what is its total added value?","options":{"A":"$14,000","B":"$22,500","C":"$8,500","D":"$15,500"},"correctOption":"A","correctAnswer":"$14,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because added value per jar is $45 - ($14 + $3) = $28, and across 500 jars total added value is 500 × $28 = $14,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $22,500 is total sales revenue (500 × $45) before subtracting bought-in costs.","C":"Incorrect because $8,500 is total bought-in material and packaging cost (500 × $17).","D":"Incorrect because $15,500 forgets to subtract the $3 packaging cost per jar."}}},{"id":"P1_U4_MCQ_854","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_854","question":"A bottled-sauce factory produces 40,000 bottles per week at a total production cost of $60,000. After upgrading its filling machinery, output rises to 50,000 bottles per week while total production cost rises to $65,000. By how much has the average production cost per bottle fallen?","options":{"A":"$0.20 per bottle (from $1.50 to $1.30)","B":"$0.50 per bottle (from $1.50 to $1.00)","C":"$0.10 per bottle (from $1.40 to $1.30)","D":"$0.00 per bottle (average cost stayed the same)"},"correctOption":"A","correctAnswer":"$0.20 per bottle (from $1.50 to $1.30)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because initial average cost was $60,000 / 40,000 = $1.50 per bottle, new average cost is $65,000 / 50,000 = $1.30 per bottle, and $1.50 - $1.30 = $0.20 per bottle.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $65,000 divided by 50,000 equals $1.30 rather than $1.00.","C":"Incorrect because initial average cost ($60,000 / 40,000) was $1.50 rather than $1.40.","D":"Incorrect because higher efficiency lowered unit production cost from $1.50 to $1.30."}}},{"id":"P1_U4_MCQ_855","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_855","question":"A shipyard builds one-off luxury superyachts designed individually to each billionaire buyer's exact interior and hull specifications. Which production method is most appropriate?","options":{"A":"Job production","B":"Flow production","C":"Batch production","D":"Continuous mass production"},"correctOption":"A","correctAnswer":"Job production","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because each yacht is a unique, complex, custom-built product made to individual customer order.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because flow production manufactures identical standardized goods continuously on an assembly line.","C":"Incorrect because batch production makes identical groups of items rather than one-off custom vessels.","D":"Incorrect because mass production suits high-volume standardized consumer goods."}}},{"id":"P1_U4_MCQ_856","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_856","question":"A commercial bakery uses the same industrial mixers and ovens to bake 400 white loaves in the morning, 300 wholemeal rolls at midday, and 250 croissants in the afternoon. What is a key operational challenge of this batch production method?","options":{"A":"Every single loaf must be hand-shaped uniquely for an individual buyer","B":"Time is lost cleaning equipment and resetting oven temperatures between batches, reducing active production hours","C":"The bakery is unable to offer more than one type of baked product","D":"Zero raw material inventory is ever required"},"correctOption":"B","correctAnswer":"Time is lost cleaning equipment and resetting oven temperatures between batches, reducing active production hours","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because switching from one batch recipe to another requires cleaning and machine setup downtime.","distractor_reasons":{"A":"Incorrect because individual bespoke items describe job production.","B":"Correct selection.","C":"Incorrect because product variety across batches is the main strength of batch production.","D":"Incorrect because flour, yeast, and butter stocks are required for each batch."}}},{"id":"P1_U4_MCQ_857","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_857","question":"A mineral water company uses high-speed flow production to fill and cap 30,000 identical bottles per hour. What happens if the supplier of plastic bottle caps fails to deliver on time and buffer stock runs out?","options":{"A":"Workers can switch immediately to carving wooden caps by hand at the same speed","B":"Fixed factory overheads drop to zero automatically","C":"The entire bottling line must halt immediately, causing costly idle machinery and unpaid order delays","D":"Bottles can be shipped uncapped to supermarkets"},"correctOption":"C","correctAnswer":"The entire bottling line must halt immediately, causing costly idle machinery and unpaid order delays","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because flow production depends on uninterrupted input supplies; missing a single component stops the whole line.","distractor_reasons":{"A":"Incorrect because manual work cannot match 30,000 units per hour.","B":"Incorrect because fixed rent, depreciation, and salaries continue during shutdowns.","C":"Correct selection.","D":"Incorrect because uncapped bottles spill and violate hygiene standards."}}},{"id":"P1_U4_MCQ_858","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_858","question":"On a factory's inventory control chart, the maximum inventory level is marked at 2,400 units, the reorder level line is marked at 1,000 units, and the minimum (buffer) inventory line is marked at 400 units. When inventory falls to 1,000 units, what action is triggered on the chart?","options":{"A":"The factory immediately shuts down production permanently","B":"A new order for replacement inventory is placed with the supplier so it arrives before stock drops below the 400-unit buffer","C":"The buffer inventory is sold off at half price","D":"Maximum warehouse capacity is reduced to 400 units"},"correctOption":"B","correctAnswer":"A new order for replacement inventory is placed with the supplier so it arrives before stock drops below the 400-unit buffer","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the reorder level on an inventory chart indicates the stock point at which a new order must be placed to cover usage during supplier lead time.","distractor_reasons":{"A":"Incorrect because placing a timely reorder keeps production running continuously.","B":"Correct selection.","C":"Incorrect because buffer inventory is retained to protect production rather than sold off.","D":"Incorrect because maximum warehouse capacity remains 2,400 units."}}},{"id":"P1_U4_MCQ_859","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_859","question":"Using the same inventory control chart (reorder level 1,000 units, buffer inventory 400 units), why does the chart include a 400-unit buffer level above zero?","options":{"A":"To ensure the warehouse is always 100% full every day","B":"To eliminate the need to ever reorder materials from suppliers","C":"To allow production to continue without stopping if a supplier delivery arrives later than expected or customer orders suddenly rise","D":"To increase the risk of running out of raw materials"},"correctOption":"C","correctAnswer":"To allow production to continue without stopping if a supplier delivery arrives later than expected or customer orders suddenly rise","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because buffer inventory acts as a safety cushion against unexpected delivery delays or sudden spikes in demand.","distractor_reasons":{"A":"Incorrect because stock fluctuates between maximum and minimum levels on the sawtooth chart.","B":"Incorrect because regular reorders are still required whenever stock hits the reorder level.","C":"Correct selection.","D":"Incorrect because buffer stock reduces rather than increases the risk of stockouts."}}},{"id":"P1_U4_MCQ_860","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_860","question":"If port congestion increases a supplier's delivery lead time from 4 days to 7 days while daily factory usage remains constant, how should the inventory manager adjust the inventory control chart?","options":{"A":"Lower the reorder level so orders are placed later","B":"Raise the reorder level (and consider increasing buffer stock) so orders are placed earlier to cover the longer delivery wait","C":"Eliminate buffer inventory completely","D":"Reduce maximum storage capacity to zero"},"correctOption":"B","correctAnswer":"Raise the reorder level (and consider increasing buffer stock) so orders are placed earlier to cover the longer delivery wait","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because longer lead times mean more stock is consumed while waiting for delivery, requiring an earlier reorder trigger.","distractor_reasons":{"A":"Incorrect because ordering later during longer lead times causes guaranteed stockouts.","B":"Correct selection.","C":"Incorrect because longer, less predictable deliveries require greater buffer protection.","D":"Incorrect because higher reorder thresholds require adequate storage capacity."}}},{"id":"P1_U4_MCQ_861","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_861","question":"How does Just-in-Time (JIT) inventory control help a car manufacturer achieve lean production?","options":{"A":"Raw materials and components are delivered directly to the assembly line exactly when needed, minimizing warehouse space, tied-up cash, and stock waste","B":"The factory builds six months' worth of finished cars in advance and stores them in rented fields","C":"Suppliers deliver components once every two years in massive shipments","D":"Workers produce extra parts even when no customer orders exist"},"correctOption":"A","correctAnswer":"Raw materials and components are delivered directly to the assembly line exactly when needed, minimizing warehouse space, tied-up cash, and stock waste","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because JIT eliminates buffer storage by synchronizing frequent supplier deliveries with immediate production needs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because stockpiling finished cars creates heavy storage costs and working capital waste.","C":"Incorrect because infrequent bulk shipments require huge warehouses.","D":"Incorrect because producing without customer demand creates overproduction waste."}}},{"id":"P1_U4_MCQ_862","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_862","question":"Why is 'defect waste' considered especially costly in lean manufacturing?","options":{"A":"Because defective products sell for higher prices than flawless ones","B":"Because defective items consume zero electricity or raw materials","C":"Because defects eliminate the need for customer service","D":"Because every faulty item has already consumed raw materials, labour, and machine time, yet must be scrapped or expensively reworked instead of earning revenue"},"correctOption":"D","correctAnswer":"Because every faulty item has already consumed raw materials, labour, and machine time, yet must be scrapped or expensively reworked instead of earning revenue","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because defects waste every input already invested in the item and risk damaging brand reputation if shipped.","distractor_reasons":{"A":"Incorrect because defective goods cannot be sold at full price.","B":"Incorrect because faulty units consume full production resources.","C":"Incorrect because defects increase customer complaints and service workload.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_863","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_863","question":"Which operational practice directly reduces 'overproduction and waiting waste' in a lean manufacturing business?","options":{"A":"Producing large batches of unsold goods to keep machines busy all night","B":"Producing only to confirmed customer demand and balancing workstation speeds so parts flow smoothly without piling up","C":"Storing raw materials in three separate distant warehouses","D":"Waiting until the end of the month to repair broken conveyor belts"},"correctOption":"B","correctAnswer":"Producing only to confirmed customer demand and balancing workstation speeds so parts flow smoothly without piling up","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because lean production minimizes waste by matching output closely to orders and preventing bottlenecks between stages.","distractor_reasons":{"A":"Incorrect because making unneeded goods creates overproduction waste.","B":"Correct selection.","C":"Incorrect because scattered warehouses increase unnecessary transport and storage waste.","D":"Incorrect because delayed repairs increase machine downtime and waiting waste."}}},{"id":"P1_U4_MCQ_864","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_864","question":"How does 'Kaizen' (continuous improvement) differ from major technological innovation?","options":{"A":"Kaizen requires shutting down the factory for six months every year","B":"Kaizen relies on ongoing, small, low-cost improvements suggested by all employees daily, whereas major innovation involves large, infrequent capital investments in new systems","C":"Kaizen excludes shop-floor employees from participating","D":"Major innovation costs zero money to implement"},"correctOption":"B","correctAnswer":"Kaizen relies on ongoing, small, low-cost improvements suggested by all employees daily, whereas major innovation involves large, infrequent capital investments in new systems","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Kaizen builds cumulative efficiency gains through everyday employee problem-solving without heavy capital spending.","distractor_reasons":{"A":"Incorrect because Kaizen improvements happen continuously during normal operations.","B":"Correct selection.","C":"Incorrect because shop-floor engagement is the foundation of Kaizen.","D":"Incorrect because major R&D and machinery upgrades require heavy capital expenditure."}}},{"id":"P1_U4_MCQ_865","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_865","question":"Why is 'multi-skilling' (cross-training workers to perform several tasks) vital for the success of cell production?","options":{"A":"It ensures every worker knows only one single button to press","B":"It eliminates the need for any tools or machinery inside the cell","C":"Team members can rotate roles to relieve boredom and step in immediately to cover absent colleagues or clear bottlenecks","D":"It forces workers to work 24 hours without breaks"},"correctOption":"C","correctAnswer":"Team members can rotate roles to relieve boredom and step in immediately to cover absent colleagues or clear bottlenecks","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because flexible multi-skilled teams maintain smooth workflow when absences or order variations occur.","distractor_reasons":{"A":"Incorrect because single-task rigidity characterizes traditional assembly lines.","B":"Incorrect because cells still use specialized tools and equipment.","C":"Correct selection.","D":"Incorrect because multi-skilling improves job variety rather than eliminating rest breaks."}}},{"id":"P1_U4_MCQ_866","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_866","question":"Why would strict zero-buffer 'Just-in-Time' (JIT) inventory be risky for a hospital emergency department stocking critical trauma medicines?","options":{"A":"Because hospital medicines never expire","B":"Because hospitals have unlimited warehouse space","C":"Because medical suppliers deliver medicines instantaneously via email","D":"Because sudden, unpredictable emergencies (such as major accidents) require immediate on-site buffer stock where any delivery delay could cost lives"},"correctOption":"D","correctAnswer":"Because sudden, unpredictable emergencies (such as major accidents) require immediate on-site buffer stock where any delivery delay could cost lives","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because JIT works best when demand is reasonably predictable and stockout costs are purely financial rather than life-critical.","distractor_reasons":{"A":"Incorrect because medicines do expire and require stock rotation (FIFO).","B":"Incorrect because hospitals face tight storage space constraints.","C":"Incorrect because physical medicines require physical transport.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_867","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_867","question":"What is meant by the 'opportunity cost' of holding excessive inventory in a warehouse?","options":{"A":"The working capital tied up in unsold stock cannot be used for profitable alternatives such as product development, marketing, or earning bank interest","B":"The discount received from buying goods in bulk","C":"The revenue earned from selling stock quickly to customers","D":"The salaries paid to delivery drivers"},"correctOption":"A","correctAnswer":"The working capital tied up in unsold stock cannot be used for profitable alternatives such as product development, marketing, or earning bank interest","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash locked in idle inventory forfeits the return it could have generated elsewhere in the business.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because bulk discounts are a financial saving rather than an opportunity cost.","C":"Incorrect because selling stock frees up cash.","D":"Incorrect because driver wages are transport operating costs."}}},{"id":"P1_U4_MCQ_868","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_868","question":"What is meant by 'inventory shrinkage' in retail and warehouse operations?","options":{"A":"Compressing cardboard boxes to save lorry space","B":"Loss of recorded inventory caused by shoplifting, employee theft, damage in storage, or perishable spoilage, reducing sellable goods and profit","C":"Reducing buffer stock intentionally through Just-in-Time ordering","D":"Selling products at a 10% seasonal discount"},"correctOption":"B","correctAnswer":"Loss of recorded inventory caused by shoplifting, employee theft, damage in storage, or perishable spoilage, reducing sellable goods and profit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because holding large volumes of stock increases exposure to theft, damage, and expiry losses.","distractor_reasons":{"A":"Incorrect because compacting packaging is waste management.","B":"Correct selection.","C":"Incorrect because planned stock reduction is lean inventory control.","D":"Incorrect because promotional discounting generates sales revenue."}}},{"id":"P1_U4_MCQ_869","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_869","question":"Why do manufacturers in countries with high minimum wages often invest more heavily in capital-intensive production than firms in low-wage economies?","options":{"A":"Because machinery is free in high-wage economies","B":"Because workers in high-wage economies are banned from working in factories","C":"Because high wage rates make manual labour expensive per unit, making automated machinery comparatively more cost-effective","D":"Because low-wage economies have unlimited supplies of free robots"},"correctOption":"C","correctAnswer":"Because high wage rates make manual labour expensive per unit, making automated machinery comparatively more cost-effective","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because businesses choose the factor mix (labour vs capital) that minimizes average cost per unit given local factor prices.","distractor_reasons":{"A":"Incorrect because capital equipment is expensive everywhere.","B":"Incorrect because people work alongside automation in high-wage countries.","C":"Correct selection.","D":"Incorrect because abundant affordable labour reduces the financial incentive to automate."}}},{"id":"P1_U4_MCQ_870","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_870","question":"What is a significant limitation of adopting Just-in-Time (JIT) inventory control for a manufacturer that relies on overseas suppliers?","options":{"A":"JIT requires building huge expensive warehouses next to the factory","B":"JIT increases the amount of working capital locked in unsold stock","C":"JIT prevents suppliers from ever using computer ordering systems","D":"Any shipping delay, port strike, or supplier fault halts the entire production line immediately because there is no buffer inventory to fall back on"},"correctOption":"D","correctAnswer":"Any shipping delay, port strike, or supplier fault halts the entire production line immediately because there is no buffer inventory to fall back on","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because zero-buffer JIT creates high vulnerability to any disruption in supplier reliability or transport links.","distractor_reasons":{"A":"Incorrect because JIT reduces rather than increases warehouse space needs.","B":"Incorrect because JIT frees up working capital by holding minimal stock.","C":"Incorrect because JIT relies heavily on reliable electronic communication with suppliers.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_871","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_871","question":"How can a service business such as a hotel or parcel courier manage short-term seasonal demand spikes without buying permanent extra buildings?","options":{"A":"By hiring temporary seasonal staff, offering overtime shifts, and subcontracting overflow deliveries to partner carriers","B":"By refusing to serve any customers during busy holiday periods","C":"By building permanent hotels that remain 90% empty for eleven months of the year","D":"By storing hotel room nights in a warehouse during winter"},"correctOption":"A","correctAnswer":"By hiring temporary seasonal staff, offering overtime shifts, and subcontracting overflow deliveries to partner carriers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because flexible staffing and subcontracting expand short-term capacity without locking the firm into year-round fixed costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because turning away peak demand sacrifices peak profits.","C":"Incorrect because permanent buildings for brief peaks create crippling fixed overheads.","D":"Incorrect because services are perishable and cannot be stockpiled."}}},{"id":"P1_U4_MCQ_872","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_872","question":"A specialty coffee shop buys $0.45 worth of coffee beans, milk, and paper cup per drink and sells each latte for $4.50. How does the coffee shop create this $4.05 of added value?","options":{"A":"By forcing customers to roast and grind raw coffee beans themselves","B":"Through skilled barista preparation, welcoming store ambience, convenient city-centre location, and strong brand reputation","C":"By paying zero rent or barista wages","D":"By selling unroasted raw beans in plastic bags"},"correctOption":"B","correctAnswer":"Through skilled barista preparation, welcoming store ambience, convenient city-centre location, and strong brand reputation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because transformation skill, customer experience, convenience, and branding justify a selling price far above raw ingredient cost.","distractor_reasons":{"A":"Incorrect because convenient ready-to-drink service adds value.","B":"Correct selection.","C":"Incorrect because rent and wages are paid out of the added value created.","D":"Incorrect because raw beans without transformation command much lower added value."}}},{"id":"P1_U4_MCQ_873","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_873","question":"On a three-stage production line, Cutting processes 500 units/hour, Welding processes 300 units/hour, and Painting processes 600 units/hour. Why will speeding up Painting to 800 units/hour fail to increase total factory output?","options":{"A":"Because paint dries faster at slower speeds","B":"Because Cutting is producing too slowly","C":"Because Welding (300 units/hour) is the bottleneck limiting total line throughput; output cannot rise until Welding capacity is expanded","D":"Because factories are legally capped at 300 units per hour"},"correctOption":"C","correctAnswer":"Because Welding (300 units/hour) is the bottleneck limiting total line throughput; output cannot rise until Welding capacity is expanded","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total system output is governed by its slowest bottleneck stage (300 units/hour).","distractor_reasons":{"A":"Incorrect because the constraint is upstream welding volume, not drying speed.","B":"Incorrect because Cutting (500/hr) already outpaces Welding (300/hr).","C":"Correct selection.","D":"Incorrect because no law caps output at 300 units/hour."}}},{"id":"P1_U4_MCQ_874","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_874","question":"What is a major human-resource drawback of extreme 'division of labour' in traditional flow production?","options":{"A":"Workers take years to learn how to tighten a single bolt","B":"Workers have too much variety and freedom in their daily tasks","C":"Output speed becomes slower than bespoke craft production","D":"Repetitive, monotonous tasks cause worker boredom, lower motivation, higher absenteeism, and careless quality mistakes"},"correctOption":"D","correctAnswer":"Repetitive, monotonous tasks cause worker boredom, lower motivation, higher absenteeism, and careless quality mistakes","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repetitive assembly work reduces intrinsic job satisfaction, prompting firms to introduce job rotation or cell production.","distractor_reasons":{"A":"Incorrect because narrow tasks are quick to learn.","B":"Incorrect because extreme specialization removes task variety.","C":"Incorrect because specialization increases assembly speed.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_875","section":"4","unit":"Unit 4: Operations management","chapter":"4.1 Production of goods and services","questionNumber":"P1_U4_MCQ_875","question":"When deciding whether to switch from labour-intensive to capital-intensive production, which combination of factors should managers evaluate?","options":{"A":"Capital purchase and financing costs versus projected wage savings, forecast demand volume, worker retraining needs, and degree of product customization required","B":"Only the brand name of the machinery manufacturer","C":"Only the colour of employee uniforms","D":"Whether competitors will agree to raise their selling prices"},"correctOption":"A","correctAnswer":"Capital purchase and financing costs versus projected wage savings, forecast demand volume, worker retraining needs, and degree of product customization required","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because switching factor intensity affects fixed vs variable costs, break-even volume, workforce morale, and product flexibility.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because financial and operational metrics matter far more than brand labels.","C":"Incorrect because uniform colours are trivial.","D":"Incorrect because competitors act independently and price fixing is illegal."}}},{"id":"P1_U4_MCQ_876","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_876","question":"How does 'Computer-Aided Design' (CAD) benefit architectural and construction firms?","options":{"A":"CAD software automatically pours wet concrete on building sites","B":"Architects create interactive 3D building models, test structural loads and sunlight angles, and modify layouts instantly for clients before construction begins","C":"CAD eliminates the need for steel, cement, or land","D":"CAD prevents clients from requesting any changes to building plans"},"correctOption":"B","correctAnswer":"Architects create interactive 3D building models, test structural loads and sunlight angles, and modify layouts instantly for clients before construction begins","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because digital 3D visualization and engineering simulation prevent costly structural errors before physical building starts.","distractor_reasons":{"A":"Incorrect because physical construction machinery pours concrete.","B":"Correct selection.","C":"Incorrect because physical materials are still required to construct buildings.","D":"Incorrect because CAD makes client revisions much faster and cheaper."}}},{"id":"P1_U4_MCQ_877","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_877","question":"How do 'Computer Numerical Control' (CNC) machines improve precision metalworking in CAM systems?","options":{"A":"Operators guide cutting blades purely by eye without measurements","B":"CNC machines work only once per week","C":"Computer code guides drills and lathes along exact coordinates, producing thousands of identical components with micron-level accuracy","D":"CNC machines eliminate the need for metal raw materials"},"correctOption":"C","correctAnswer":"Computer code guides drills and lathes along exact coordinates, producing thousands of identical components with micron-level accuracy","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because programmable digital tool control achieves repeatable precision beyond manual machining.","distractor_reasons":{"A":"Incorrect because CNC automates cutting coordinates via software.","B":"Incorrect because CNC equipment can operate continuously across shifts.","C":"Correct selection.","D":"Incorrect because metal billets/sheets are still machined into parts."}}},{"id":"P1_U4_MCQ_878","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_878","question":"Why do automotive and chemical manufacturers assign tasks such as high-temperature welding, toxic spray-painting, and heavy lifting to industrial robots?","options":{"A":"Because robots enjoy breathing toxic fumes","B":"Because human workers are banned from working in any factory","C":"Because robots require zero electrical power or maintenance","D":"To protect human employees from hazardous fumes, burns, and musculoskeletal injuries, improving workplace safety and reducing accident claims"},"correctOption":"D","correctAnswer":"To protect human employees from hazardous fumes, burns, and musculoskeletal injuries, improving workplace safety and reducing accident claims","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because automating dangerous and physically gruelling tasks improves occupational health and safety while maintaining consistent quality.","distractor_reasons":{"A":"Incorrect because robots are machines without biological lungs.","B":"Incorrect because humans perform supervision, programming, and complex assembly.","C":"Incorrect because robots require electricity and regular servicing.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_879","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_879","question":"How do 'collaborative robots' (cobots) differ from traditional heavy industrial robots?","options":{"A":"Cobots feature force sensors and lightweight designs that allow them to work safely right beside human workers without heavy protective safety cages","B":"Cobots are giant machines that must be locked inside isolated concrete bunkers","C":"Cobots operate without electricity using wind power","D":"Cobots replace all human workers across an entire company"},"correctOption":"A","correctAnswer":"Cobots feature force sensors and lightweight designs that allow them to work safely right beside human workers without heavy protective safety cages","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cobots assist human operators with repetitive precision tasks while humans handle delicate judgement steps.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because safety cages are required for traditional high-speed heavy robots, not cobots.","C":"Incorrect because cobots are electrically powered.","D":"Incorrect because cobots are specifically designed to collaborate alongside human workers."}}},{"id":"P1_U4_MCQ_880","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_880","question":"When a supermarket links its 'EPOS' checkout scanners with a digital customer loyalty app, what operational and marketing advantage does it gain?","options":{"A":"Customers receive groceries completely free of charge","B":"The retailer analyzes individual shopping baskets to send targeted coupons and forecast local store stock demand accurately","C":"Cashiers no longer need to scan product barcodes","D":"It eliminates the need for refrigerated delivery lorries"},"correctOption":"B","correctAnswer":"The retailer analyzes individual shopping baskets to send targeted coupons and forecast local store stock demand accurately","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because linking SKU-level EPOS data to customer profiles improves demand forecasting and personalized promotions.","distractor_reasons":{"A":"Incorrect because loyalty apps offer targeted discounts rather than free groceries.","B":"Correct selection.","C":"Incorrect because EPOS relies on barcode/RFID scanning at checkout.","D":"Incorrect because physical cold-chain logistics remain essential."}}},{"id":"P1_U4_MCQ_881","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_881","question":"How does 'EFTPOS' (Electronic Funds Transfer at Point of Sale) improve financial control and security for retail shops?","options":{"A":"It fills the shop's cash drawer with extra banknotes","B":"It allows shoppers to leave without paying","C":"Customer card payments transfer directly into the retailer's bank account, cutting cash theft risks, counterfeit note losses, and manual cash-counting time","D":"It eliminates all bank merchant processing fees"},"correctOption":"C","correctAnswer":"Customer card payments transfer directly into the retailer's bank account, cutting cash theft risks, counterfeit note losses, and manual cash-counting time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because electronic settlement accelerates cash inflow and reduces physical cash-handling vulnerabilities.","distractor_reasons":{"A":"Incorrect because EFTPOS reduces physical cash in the till.","B":"Incorrect because payment is authorized electronically at checkout.","C":"Correct selection.","D":"Incorrect because card processors charge small transaction fees."}}},{"id":"P1_U4_MCQ_882","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_882","question":"Why are 'RFID (Radio-Frequency Identification) tags' faster than traditional optical barcodes in warehouse receiving and retail stocktakes?","options":{"A":"Because RFID tags physically carry boxes onto shelves by themselves","B":"Because RFID tags cost zero money and never use radio waves","C":"Because optical barcodes can be read from 500 metres away through walls","D":"Because RFID scanners read hundreds of tagged items inside sealed pallets simultaneously without needing direct line-of-sight to each label"},"correctOption":"D","correctAnswer":"Because RFID scanners read hundreds of tagged items inside sealed pallets simultaneously without needing direct line-of-sight to each label","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because radio-frequency reading eliminates scanning items one by one, cutting stocktake hours to minutes.","distractor_reasons":{"A":"Incorrect because RFID tags are passive/active tracking chips, not motors.","B":"Incorrect because RFID tags cost slightly more than printed paper barcodes.","C":"Incorrect because optical barcodes require direct line-of-sight laser/camera scanning.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_883","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_883","question":"How does '3D printing' help aerospace and railway companies manage spare replacement parts for older vehicles?","options":{"A":"Instead of paying to warehouse thousands of rarely needed metal/polymer spare parts for decades, engineers 3D-print specific parts on demand from digital files","B":"3D printers melt entire aeroplanes back into liquid fuel","C":"It forces companies to store ten years of spare parts in every airport","D":"It eliminates the need for safety inspections on replacement parts"},"correctOption":"A","correctAnswer":"Instead of paying to warehouse thousands of rarely needed metal/polymer spare parts for decades, engineers 3D-print specific parts on demand from digital files","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because digital inventory of CAD files replaces costly physical storage of slow-moving legacy components.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 3D printing is additive manufacturing, not fuel refining.","C":"Incorrect because on-demand printing drastically reduces physical spare-part storage.","D":"Incorrect because aviation/rail parts undergo strict certification testing."}}},{"id":"P1_U4_MCQ_884","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_884","question":"How does 'Artificial Intelligence (AI) demand forecasting' improve operations for a supermarket selling fresh fruit and dairy?","options":{"A":"It makes fresh milk last for ten years without refrigeration","B":"AI analyzes past sales, weather forecasts, and local holidays to order exact quantities, cutting both empty-shelf stockouts and spoiled food waste","C":"It replaces all delivery lorries with underground pneumatic tubes","D":"It forces shoppers to buy identical groceries every week"},"correctOption":"B","correctAnswer":"AI analyzes past sales, weather forecasts, and local holidays to order exact quantities, cutting both empty-shelf stockouts and spoiled food waste","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because accurate predictive ordering balances availability against perishability.","distractor_reasons":{"A":"Incorrect because AI optimizes order quantities rather than changing food chemistry.","B":"Correct selection.","C":"Incorrect because physical lorries still deliver groceries.","D":"Incorrect because AI adapts to shifting shopper demand."}}},{"id":"P1_U4_MCQ_885","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_885","question":"How do 'Autonomous Mobile Robots (AMRs)' improve operations inside large hospitals or hotels?","options":{"A":"They replace doctors during complex heart surgeries","B":"They eliminate the need to wash bedsheets or cook patient meals","C":"They transport meals, clean linens, and lab samples along corridors autonomously, freeing nurses and staff to focus on patient and guest care","D":"They prevent guests from leaving their hotel rooms"},"correctOption":"C","correctAnswer":"They transport meals, clean linens, and lab samples along corridors autonomously, freeing nurses and staff to focus on patient and guest care","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because automating routine internal transport boosts staff productivity and service responsiveness.","distractor_reasons":{"A":"Incorrect because AMRs handle logistics transport rather than performing surgery.","B":"Incorrect because laundry and catering facilities still operate.","C":"Correct selection.","D":"Incorrect because AMRs navigate safely around guests and staff."}}},{"id":"P1_U4_MCQ_886","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_886","question":"A bakery is considering buying an automated dough-dividing machine costing $60,000 that will save $20,000 per year in labour and flour waste. What is the payback period of this technology investment?","options":{"A":"1 year","B":"2 years","C":"4 years","D":"3 years"},"correctOption":"D","correctAnswer":"3 years","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Payback Period = Initial Investment / Annual Net Cash Savings = $60,000 / $20,000 = 3 years.","distractor_reasons":{"A":"Incorrect because $20,000 saves only one-third of the $60,000 cost in Year 1.","B":"Incorrect because after 2 years only $40,000 has been recovered.","C":"Incorrect because by Year 4 total savings reach $80,000, exceeding the $60,000 cost.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_887","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_887","question":"How can introducing real-time 'digital management information systems' affect a business's organizational structure?","options":{"A":"Managers monitor live output and quality data directly across wider teams, allowing middle-management layers to be removed (delayering) and speeding up decisions","B":"It forces the company to add ten extra tiers of middle supervisors","C":"It prevents senior managers from seeing factory performance data","D":"It eliminates all communication between departments"},"correctOption":"A","correctAnswer":"Managers monitor live output and quality data directly across wider teams, allowing middle-management layers to be removed (delayering) and speeding up decisions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automated reporting replaces manual supervisory information gathering, widening spans of control and flattening hierarchies.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because IT reduces rather than increases intermediate reporting layers.","C":"Incorrect because live dashboards give senior managers instant visibility.","D":"Incorrect because shared digital platforms strengthen cross-departmental coordination."}}},{"id":"P1_U4_MCQ_888","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_888","question":"How have 'mobile banking apps' transformed retail banking operations over the past decade?","options":{"A":"Banks now require customers to visit physical branches in person for every balance check","B":"Customers execute routine transfers, cheque deposits, and bill payments 24/7 via self-service apps, allowing banks to reduce costly high-street branch networks","C":"Mobile apps eliminate the need for bank cybersecurity teams","D":"Banks no longer hold any customer deposits"},"correctOption":"B","correctAnswer":"Customers execute routine transfers, cheque deposits, and bill payments 24/7 via self-service apps, allowing banks to reduce costly high-street branch networks","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because digital self-service shifts routine transactions off expensive branch counters while increasing 24/7 customer convenience.","distractor_reasons":{"A":"Incorrect because apps eliminate branch visits for routine transactions.","B":"Correct selection.","C":"Incorrect because digital banking requires massive cybersecurity investment.","D":"Incorrect because deposit-taking remains central to banking."}}},{"id":"P1_U4_MCQ_889","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_889","question":"What operational risk arises if a business relies blindly on 'automated ordering or pricing algorithms' without human oversight?","options":{"A":"Algorithms never experience software bugs or corrupted input data","B":"Computers always understand sudden unprecedented crises better than experienced managers","C":"A sensor glitch or unusual market shock can trigger massive erroneous stock orders or extreme mispricing before staff intervene","D":"Human oversight slows computers down to one calculation per day"},"correctOption":"C","correctAnswer":"A sensor glitch or unusual market shock can trigger massive erroneous stock orders or extreme mispricing before staff intervene","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because automated algorithms require human exception monitoring and circuit-breakers to prevent runaway errors.","distractor_reasons":{"A":"Incorrect because software glitches and bad data inputs do occur.","B":"Incorrect because algorithms trained on past data can fail during unprecedented events.","C":"Correct selection.","D":"Incorrect because human exception alerts preserve speed while preventing major blunders."}}},{"id":"P1_U4_MCQ_890","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_890","question":"Why do e-commerce retailers use 'scalable cloud computing servers' rather than owning fixed in-house computer servers?","options":{"A":"Because cloud servers never use electricity anywhere in the world","B":"Because fixed in-house servers cost zero money to buy and maintain","C":"Because cloud servers prevent customers from visiting websites during sales","D":"Cloud capacity expands automatically during peak shopping events (such as Black Friday) and scales down afterward, avoiding website crashes and idle hardware costs"},"correctOption":"D","correctAnswer":"Cloud capacity expands automatically during peak shopping events (such as Black Friday) and scales down afterward, avoiding website crashes and idle hardware costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because elastic cloud infrastructure converts fixed IT capacity into flexible pay-as-you-go operating capacity.","distractor_reasons":{"A":"Incorrect because cloud data centres consume significant power.","B":"Incorrect because owning physical servers involves high capital and IT maintenance costs.","C":"Incorrect because cloud scaling keeps websites fast during traffic surges.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_891","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_891","question":"How do 'electronic signatures (e-signatures) and automated digital contracts' improve procurement and sales operations?","options":{"A":"Contracts are signed securely online in minutes rather than printing, posting, and filing paper documents over weeks","B":"They make business agreements legally unenforceable","C":"They require every supplier to fly to headquarters in person","D":"They increase paper and courier postage expenses"},"correctOption":"A","correctAnswer":"Contracts are signed securely online in minutes rather than printing, posting, and filing paper documents over weeks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because digital contract workflows accelerate supplier onboarding, cut stationery/postage costs, and create searchable audit trails.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because authenticated e-signatures are legally recognized in commercial jurisdictions.","C":"Incorrect because e-signatures enable remote signing worldwide.","D":"Incorrect because digital workflows eliminate paper and postage."}}},{"id":"P1_U4_MCQ_892","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_892","question":"How does 'vehicle telematics' (on-board GPS and engine sensors) improve delivery fleet operations?","options":{"A":"It eliminates the need for tyres or roads","B":"Managers monitor fuel consumption, harsh braking, idle engine time, and engine fault alerts in real time, lowering fuel bills, accidents, and breakdowns","C":"It forces drivers to drive above speed limits","D":"It automatically repairs punctured tyres while driving"},"correctOption":"B","correctAnswer":"Managers monitor fuel consumption, harsh braking, idle engine time, and engine fault alerts in real time, lowering fuel bills, accidents, and breakdowns","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because telematics encourages safer, fuel-efficient driving and enables preventative vehicle servicing.","distractor_reasons":{"A":"Incorrect because vans still use roads and tyres.","B":"Correct selection.","C":"Incorrect because telematics alerts managers to speeding to improve safety.","D":"Incorrect because physical roadside assistance is still required for punctures."}}},{"id":"P1_U4_MCQ_893","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_893","question":"How can 'Augmented Reality (AR) smart glasses' improve complex assembly and maintenance operations?","options":{"A":"By blinding technicians so they cannot see the machinery","B":"By replacing physical steel tools with imaginary holograms","C":"By overlaying step-by-step digital wiring diagrams and torque instructions directly onto the technician's field of view, cutting assembly errors and training time","D":"By eliminating the need to manufacture physical machines"},"correctOption":"C","correctAnswer":"By overlaying step-by-step digital wiring diagrams and torque instructions directly onto the technician's field of view, cutting assembly errors and training time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because hands-free visual guidance helps technicians perform intricate tasks accurately on the first attempt.","distractor_reasons":{"A":"Incorrect because AR overlays transparent helpful graphics onto real-world vision.","B":"Incorrect because physical tools are still used.","C":"Correct selection.","D":"Incorrect because AR assists physical assembly and repair."}}},{"id":"P1_U4_MCQ_894","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_894","question":"What legal and reputational responsibility must a retailer uphold when using EPOS, mobile apps, and CCTV analytics to collect shopper data?","options":{"A":"Selling customer bank details to unknown third parties without permission","B":"Storing customer passwords in unencrypted public spreadsheets","C":"Ignoring all national data-protection regulations","D":"Complying with data-protection laws by obtaining consent, securing personal data against cyber breaches, and using information transparently"},"correctOption":"D","correctAnswer":"Complying with data-protection laws by obtaining consent, securing personal data against cyber breaches, and using information transparently","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because mishandling digital customer data triggers heavy regulatory fines and severe loss of consumer trust.","distractor_reasons":{"A":"Incorrect because unauthorized data selling violates privacy laws.","B":"Incorrect because unencrypted storage exposes data to hackers.","C":"Incorrect because statutory privacy compliance is mandatory.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_895","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_895","question":"What operational trade-off occurs on a high-speed automated soft-drink canning line when a company introduces 15 new niche flavours?","options":{"A":"Frequent flushing, sanitization, and label changes between flavours reduce effective line run-time and increase unit production costs","B":"Switching flavours increases machine speed automatically","C":"Canning machines clean and sterilize themselves in zero seconds","D":"Adding 15 flavours reduces raw ingredient inventory requirements"},"correctOption":"A","correctAnswer":"Frequent flushing, sanitization, and label changes between flavours reduce effective line run-time and increase unit production costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high-speed automated flow lines maximize efficiency on long standardized runs, whereas frequent product changeovers erode capacity utilization.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because changeovers interrupt continuous running.","C":"Incorrect because food-grade washdowns take significant downtime.","D":"Incorrect because more flavours require stocking more ingredient and packaging varieties."}}},{"id":"P1_U4_MCQ_896","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_896","question":"How can management work constructively with 'trade unions' when planning major factory automation?","options":{"A":"By banning union representatives from entering the building","B":"By negotiating early on voluntary redeployment, paid retraining programmes, and fair productivity-linked pay shares to prevent strikes","C":"By cutting safety standards to pay for the new robots","D":"By refusing to discuss job security until the day machines arrive"},"correctOption":"B","correctAnswer":"By negotiating early on voluntary redeployment, paid retraining programmes, and fair productivity-linked pay shares to prevent strikes","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because early collective consultation aligns workforce security with technological modernization.","distractor_reasons":{"A":"Incorrect because excluding recognized unions escalates industrial conflict.","B":"Correct selection.","C":"Incorrect because compromising safety is illegal and unethical.","D":"Incorrect because last-minute surprises provoke strikes."}}},{"id":"P1_U4_MCQ_897","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_897","question":"How do 'Automated Storage and Retrieval Systems (AS/RS)' using robotic cranes and high-bay racking benefit logistics hubs on expensive land?","options":{"A":"They spread boxes thinly across 500 acres of single-level floor","B":"They eliminate the need to track where items are stored","C":"They store pallets densely up to 30+ metres high in narrow aisles, maximizing storage capacity per square metre of costly land","D":"They require human workers to climb 30-metre ladders carrying heavy boxes"},"correctOption":"C","correctAnswer":"They store pallets densely up to 30+ metres high in narrow aisles, maximizing storage capacity per square metre of costly land","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because vertical robotic storage minimizes building footprint and accelerates accurate pallet retrieval.","distractor_reasons":{"A":"Incorrect because AS/RS maximizes vertical height rather than horizontal sprawl.","B":"Incorrect because computer software tracks exact coordinates of every pallet.","C":"Correct selection.","D":"Incorrect because automated cranes retrieve loads safely without manual climbing."}}},{"id":"P1_U4_MCQ_898","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_898","question":"How do 'self-order kiosks linked to Kitchen Display Systems (KDS)' improve operations in fast-food restaurants?","options":{"A":"Customers must walk into the kitchen and cook their own burgers","B":"Chefs receive handwritten paper tickets that frequently get lost or misread","C":"It eliminates the need to buy food ingredients","D":"Orders go straight from customer tap to kitchen screens, eliminating cashier mishearing errors and timing burger/fry preparation so hot meals finish together"},"correctOption":"D","correctAnswer":"Orders go straight from customer tap to kitchen screens, eliminating cashier mishearing errors and timing burger/fry preparation so hot meals finish together","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because digital kitchen routing increases order accuracy, speeds throughput, and ensures fresh hot food quality.","distractor_reasons":{"A":"Incorrect because kitchen staff still prepare all food.","B":"Incorrect because KDS replaces paper tickets with clear digital screens.","C":"Incorrect because food ingredients are still consumed.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_899","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_899","question":"What is meant by 'vendor lock-in' as a risk when a manufacturer buys proprietary automated machinery and software?","options":{"A":"The business becomes entirely dependent on one technology supplier for expensive spare parts, software licences, and specialist repairs, limiting future bargaining power","B":"The factory doors lock automatically at 5:00 PM every day","C":"The business can buy cheap generic spare parts from any local hardware shop","D":"The supplier provides lifetime upgrades completely free of charge"},"correctOption":"A","correctAnswer":"The business becomes entirely dependent on one technology supplier for expensive spare parts, software licences, and specialist repairs, limiting future bargaining power","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because proprietary systems can expose buyers to high recurring maintenance and upgrade fees once installed.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because vendor lock-in is a commercial dependency risk, not physical door locks.","C":"Incorrect because proprietary components cannot be sourced from generic shops.","D":"Incorrect because proprietary vendors typically charge high annual support fees."}}},{"id":"P1_U4_MCQ_900","section":"4","unit":"Unit 4: Operations management","chapter":"4.2 Technology and production of goods and services","questionNumber":"P1_U4_MCQ_900","question":"Why might a luxury heritage watchmaker or bespoke tailor choose NOT to automate core craft assembly steps even if it could afford the machinery?","options":{"A":"Because luxury buyers prefer cheap mass-produced plastic watches","B":"Because affluent customers pay premium prices specifically for human craftsmanship, rarity, and artisanal heritage, which full automation would undermine","C":"Because robots are banned from luxury workshops by law","D":"Because hand-crafting costs less per unit than mass automation"},"correctOption":"B","correctAnswer":"Because affluent customers pay premium prices specifically for human craftsmanship, rarity, and artisanal heritage, which full automation would undermine","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because technology choices must align with brand positioning and the specific value customers pay for.","distractor_reasons":{"A":"Incorrect because luxury buyers seek exclusivity and artisanal craft.","B":"Correct selection.","C":"Incorrect because the constraint is brand positioning rather than law.","D":"Incorrect because skilled hand-crafting has higher unit labour cost than mass automation."}}},{"id":"P1_U4_MCQ_901","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_901","question":"Which input combination demonstrates a furniture maker shifting from non-renewable to sustainably managed renewable resources?","options":{"A":"Replacing replanted timber with virgin petroleum-based PVC plastic and mined aluminium","B":"Burning coal to power factory saws instead of solar panels","C":"Replacing petroleum-based synthetic foams and virgin plastics with FSC-certified replanted bamboo/timber and natural latex","D":"Increasing single-use polystyrene packaging around every chair"},"correctOption":"C","correctAnswer":"Replacing petroleum-based synthetic foams and virgin plastics with FSC-certified replanted bamboo/timber and natural latex","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because certified fast-growing bamboo/timber and natural latex regenerate naturally without depleting finite fossil fuels.","distractor_reasons":{"A":"Incorrect because PVC and mined aluminium are non-renewable inputs.","B":"Incorrect because coal is a finite, high-carbon fossil fuel.","C":"Correct selection.","D":"Incorrect because polystyrene is a non-biodegradable fossil-fuel plastic."}}},{"id":"P1_U4_MCQ_902","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_902","question":"What is meant by a 'Life-Cycle Assessment (LCA)' in sustainable operations management?","options":{"A":"Counting only the electricity used on the final assembly line","B":"Measuring how many years employees stay with the company","C":"Calculating the break-even output of a new factory","D":"Evaluating a product's total environmental impact across every stage from raw material extraction and manufacturing through distribution, customer use, and end-of-life disposal"},"correctOption":"D","correctAnswer":"Evaluating a product's total environmental impact across every stage from raw material extraction and manufacturing through distribution, customer use, and end-of-life disposal","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an LCA prevents shifting environmental harm from one stage to another (e.g., cleaner manufacturing but unrecyclable disposal).","distractor_reasons":{"A":"Incorrect because LCA examines upstream and downstream stages beyond factory assembly.","B":"Incorrect because employee tenure is an HR retention metric.","C":"Incorrect because break-even is a financial cost-volume calculation.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_903","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_903","question":"How do 'in-store refill stations' for dry foods, shampoos, and laundry detergents reduce environmental impact?","options":{"A":"Shoppers reuse their own durable containers repeatedly, eliminating single-use plastic pouches and bottles while cutting packaging manufacturing emissions","B":"They require twice as many single-use plastic wrappers per purchase","C":"They increase landfill waste from supermarket shoppers","D":"They eliminate the need for shops to buy products from suppliers"},"correctOption":"A","correctAnswer":"Shoppers reuse their own durable containers repeatedly, eliminating single-use plastic pouches and bottles while cutting packaging manufacturing emissions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bulk dispensers allow customers to buy exact quantities in reusable jars/bottles, eliminating disposable packaging waste.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because refill stations eliminate single-use wrappers.","C":"Incorrect because refill models drastically cut household landfill waste.","D":"Incorrect because supermarkets still purchase bulk supplies from producers."}}},{"id":"P1_U4_MCQ_904","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_904","question":"What is the difference between 'upcycling' and 'downcycling' production waste?","options":{"A":"Upcycling throws waste into landfills, whereas downcycling burns waste in open pits","B":"Upcycling transforms waste by-products into higher-value, durable new products, whereas downcycling breaks materials down into lower-quality, lower-value applications","C":"Downcycling increases material quality permanently","D":"There is no difference between upcycling and downcycling"},"correctOption":"B","correctAnswer":"Upcycling transforms waste by-products into higher-value, durable new products, whereas downcycling breaks materials down into lower-quality, lower-value applications","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because upcycling retains or enhances material value (e.g., turning garment off-cuts into designer bags), whereas downcycling degrades quality.","distractor_reasons":{"A":"Incorrect because both upcycling and downcycling recover waste rather than landfilling or burning it.","B":"Correct selection.","C":"Incorrect because downcycling reduces material grade (e.g., melting mixed plastics into park benches).","D":"Incorrect because the value and quality trajectory of the recovered material differs."}}},{"id":"P1_U4_MCQ_905","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_905","question":"How does retrofitting a factory with 'high-efficiency electric motors and LED lighting' demonstrate a win-win sustainable operational upgrade?","options":{"A":"It increases electricity consumption while lowering output quality","B":"It requires burning extra diesel fuel inside the factory","C":"It lowers kilowatt-hours consumed per unit produced, reducing both greenhouse gas emissions and recurring monthly utility bills","D":"It eliminates the need for preventative maintenance"},"correctOption":"C","correctAnswer":"It lowers kilowatt-hours consumed per unit produced, reducing both greenhouse gas emissions and recurring monthly utility bills","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because energy efficiency directly cuts operating expenses while shrinking the business's carbon footprint.","distractor_reasons":{"A":"Incorrect because high-efficiency equipment reduces electricity consumption.","B":"Incorrect because LEDs and efficient motors replace energy waste rather than burning diesel.","C":"Correct selection.","D":"Incorrect because equipment still receives routine maintenance."}}},{"id":"P1_U4_MCQ_906","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_906","question":"How does 'direct emissions reduction' differ from 'carbon offsetting'?","options":{"A":"Carbon offsetting stops a factory from burning any fuel, whereas direct reduction increases pollution","B":"Direct reduction is illegal, whereas carbon offsetting is mandatory everywhere","C":"There is no difference between direct reduction and carbon offsetting","D":"Direct reduction cuts actual greenhouse gases emitted by the firm's own operations, whereas carbon offsetting pays for external projects (like reforestation) to balance unavoidable emissions"},"correctOption":"D","correctAnswer":"Direct reduction cuts actual greenhouse gases emitted by the firm's own operations, whereas carbon offsetting pays for external projects (like reforestation) to balance unavoidable emissions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because credible net-zero strategies prioritize cutting internal emissions first and use verified offsets only for residual hard-to-abate emissions.","distractor_reasons":{"A":"Incorrect because direct reduction lowers internal fuel/emissions while offsetting compensates externally.","B":"Incorrect because direct emission cuts are strongly encouraged by regulators.","C":"Incorrect because one changes internal operations while the other funds external carbon removal.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_907","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_907","question":"Why do environmental regulators and consumers criticize businesses that rely purely on buying cheap 'carbon offsets' instead of cutting factory emissions?","options":{"A":"Because relying solely on offsets allows the firm to continue polluting locally while risking greenwashing accusations if offset projects fail or are poorly verified","B":"Because planting trees increases atmospheric carbon dioxide","C":"Because cutting factory energy waste is always more expensive than buying offsets","D":"Because consumers want factories to emit more smoke"},"correctOption":"A","correctAnswer":"Because relying solely on offsets allows the firm to continue polluting locally while risking greenwashing accusations if offset projects fail or are poorly verified","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because genuine sustainability requires transforming core production processes rather than buying cheap permits to keep polluting.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because healthy growing forests absorb carbon dioxide.","C":"Incorrect because energy efficiency often saves money directly.","D":"Incorrect because communities and buyers oppose air pollution."}}},{"id":"P1_U4_MCQ_908","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_908","question":"How do 'regenerative agriculture' practices (such as crop rotation, cover crops, and reduced synthetic fertilisers) benefit food and beverage manufacturers?","options":{"A":"They exhaust topsoil nutrients within three years","B":"They maintain healthy, fertile soil and water retention, protecting long-term crop yields and raw ingredient supply security against droughts","C":"They eliminate the need to harvest crops","D":"They double chemical pesticide runoff into rivers"},"correctOption":"B","correctAnswer":"They maintain healthy, fertile soil and water retention, protecting long-term crop yields and raw ingredient supply security against droughts","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because healthy agricultural ecosystems protect food companies against future harvest failures and raw material price shocks.","distractor_reasons":{"A":"Incorrect because regenerative practices rebuild rather than exhaust topsoil.","B":"Correct selection.","C":"Incorrect because crops are still harvested sustainably.","D":"Incorrect because regenerative farming reduces synthetic chemical inputs."}}},{"id":"P1_U4_MCQ_909","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_909","question":"How do 'Extended Producer Responsibility (EPR)' laws influence how manufacturers design product packaging?","options":{"A":"EPR laws reward manufacturers for using unrecyclable multi-layer plastics","B":"EPR laws shift all recycling costs onto local taxpayers while freeing manufacturers","C":"Because manufacturers must pay fees based on the weight and recyclability of packaging they place on the market, they are financially incentivized to minimize and simplify packaging","D":"EPR laws ban companies from selling packaged goods"},"correctOption":"C","correctAnswer":"Because manufacturers must pay fees based on the weight and recyclability of packaging they place on the market, they are financially incentivized to minimize and simplify packaging","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because EPR internalizes end-of-life waste management costs into the producer's budget, rewarding eco-friendly packaging.","distractor_reasons":{"A":"Incorrect because EPR penalizes hard-to-recycle materials with higher fees.","B":"Incorrect because EPR shifts waste recovery costs from municipalities onto producers.","C":"Correct selection.","D":"Incorrect because packaged goods remain legal provided producers fund recovery."}}},{"id":"P1_U4_MCQ_910","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_910","question":"How can adopting verified sustainable production practices help a B2B supplier win large government or corporate contracts?","options":{"A":"Governments award contracts only to the highest-polluting bidders","B":"Sustainable suppliers never have to submit price quotes","C":"Public procurement laws ban sustainable businesses from bidding","D":"Many public-sector and multinational procurement tenders include mandatory sustainability criteria, giving eco-certified suppliers a decisive competitive edge"},"correctOption":"D","correctAnswer":"Many public-sector and multinational procurement tenders include mandatory sustainability criteria, giving eco-certified suppliers a decisive competitive edge","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because green procurement policies turn environmental compliance into a direct revenue-winning advantage.","distractor_reasons":{"A":"Incorrect because governments increasingly exclude high-polluting suppliers.","B":"Incorrect because competitive pricing and quality are still evaluated alongside sustainability.","C":"Incorrect because public tenders actively favour sustainable bidders.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_911","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_911","question":"How do cloud-computing and AI technology companies make large 'data centres' more environmentally sustainable?","options":{"A":"By powering servers with renewable energy contracts, using free cool outside air or closed-loop liquid cooling, and reusing server waste heat for nearby district heating","B":"By building data centres inside hot deserts cooled by diesel generators","C":"By running inactive servers at 100% power when no users are online","D":"By dumping hot cooling water directly into delicate coral reefs"},"correctOption":"A","correctAnswer":"By powering servers with renewable energy contracts, using free cool outside air or closed-loop liquid cooling, and reusing server waste heat for nearby district heating","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because data centres consume vast electricity and water; renewable power and smart thermal engineering cut their footprint dramatically.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because hot climates and diesel power maximize emissions and cooling energy.","C":"Incorrect because smart server management powers down idle capacity.","D":"Incorrect because thermal pollution harms aquatic ecosystems."}}},{"id":"P1_U4_MCQ_912","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_912","question":"How does 'off-site modular prefabrication' in construction reduce environmental waste compared with traditional on-site building?","options":{"A":"It doubles concrete and timber off-cuts thrown into skips","B":"Computer-guided factory cutting optimizes material use, recycles clean off-cuts immediately on-site, and reduces noisy delivery lorry journeys to the building site","C":"It requires tearing down buildings every two years","D":"It eliminates the need for architects or structural engineers"},"correctOption":"B","correctAnswer":"Computer-guided factory cutting optimizes material use, recycles clean off-cuts immediately on-site, and reduces noisy delivery lorry journeys to the building site","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because controlled factory manufacturing eliminates weather damage, cuts material scrap, and consolidates site deliveries.","distractor_reasons":{"A":"Incorrect because factory precision slashes construction waste.","B":"Correct selection.","C":"Incorrect because modular buildings meet permanent durability codes.","D":"Incorrect because CAD engineering is central to prefabrication."}}},{"id":"P1_U4_MCQ_913","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_913","question":"Why does 'designing products for easy disassembly' (using standard screws and single unmixed polymers instead of permanent glues) support a circular economy?","options":{"A":"Because glued mixed plastics are easiest to recycle","B":"Because products fall apart accidentally while customers are using them","C":"Because technicians can quickly separate metals, circuit boards, and pure plastics at end-of-life for high-grade recycling or component reuse","D":"Because disassembly eliminates the need for any raw materials"},"correctOption":"C","correctAnswer":"Because technicians can quickly separate metals, circuit boards, and pure plastics at end-of-life for high-grade recycling or component reuse","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because contaminated, permanently bonded materials cannot be separated economically and usually end up incinerated or landfilled.","distractor_reasons":{"A":"Incorrect because glued mixed plastics contaminate recycling streams.","B":"Incorrect because proper mechanical fasteners hold securely during use.","C":"Correct selection.","D":"Incorrect because disassembly recovers materials for future cycles."}}},{"id":"P1_U4_MCQ_914","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_914","question":"How do government 'carbon taxes' and 'cap-and-trade emissions schemes' influence operations managers' production decisions?","options":{"A":"They reward factories for burning more coal and heavy fuel oil","B":"They make fossil fuels completely free for heavy manufacturers","C":"They apply only to small bakeries and exempt power stations and steelworks","D":"Putting a direct financial price on greenhouse gas emissions makes high-carbon processes more expensive, incentivizing investment in clean energy and energy efficiency"},"correctOption":"D","correctAnswer":"Putting a direct financial price on greenhouse gas emissions makes high-carbon processes more expensive, incentivizing investment in clean energy and energy efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because carbon pricing shifts the financial break-even in favour of low-carbon technologies.","distractor_reasons":{"A":"Incorrect because carbon pricing penalizes fossil fuel emissions.","B":"Incorrect because carbon taxes raise the effective cost of fossil fuels.","C":"Incorrect because emissions trading targets large industrial emitters.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_915","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_915","question":"Which operational practice helps a hotel chain reduce its environmental footprint while lowering operating expenses?","options":{"A":"Installing key-card room electricity cutoffs, low-flow showerheads, solar water heaters, and laundry-on-request towel programmes","B":"Running air conditioning at maximum cold in empty rooms all day","C":"Replacing reusable ceramic plates with single-use foam trays","D":"Flying bottled drinking water halfway around the world when local filtered water is safe"},"correctOption":"A","correctAnswer":"Installing key-card room electricity cutoffs, low-flow showerheads, solar water heaters, and laundry-on-request towel programmes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because hospitality resource controls cut electricity, water, detergent, and heating costs without harming guest comfort.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cooling unoccupied rooms wastes energy and money.","C":"Incorrect because single-use foam increases plastic waste.","D":"Incorrect because importing water adds unnecessary freight emissions."}}},{"id":"P1_U4_MCQ_916","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_916","question":"What practical limitation must a food manufacturer consider before switching from conventional recyclable PET plastic trays to 'industrially compostable bioplastic' trays?","options":{"A":"Compostable trays never break down under any conditions","B":"Bioplastics often cost more per unit and require specialized high-temperature industrial composting facilities rather than decomposing in ordinary home bins or marine environments","C":"Conventional PET plastic is made from 100% organic potatoes","D":"Governments ban supermarkets from selling food in compostable trays"},"correctOption":"B","correctAnswer":"Bioplastics often cost more per unit and require specialized high-temperature industrial composting facilities rather than decomposing in ordinary home bins or marine environments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because if local waste infrastructure lacks industrial composting, compostable plastics may contaminate conventional recycling streams.","distractor_reasons":{"A":"Incorrect because they do break down rapidly in industrial composting plants.","B":"Correct selection.","C":"Incorrect because PET is derived from petrochemicals.","D":"Incorrect because compostable packaging is legal and widely used where composting facilities exist."}}},{"id":"P1_U4_MCQ_917","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_917","question":"Why do global beverage bottlers invest in 'watershed conservation and groundwater replenishment' projects near their bottling plants?","options":{"A":"Because soft drinks do not contain any water","B":"Because polluting local aquifers increases beverage quality","C":"Because freshwater is their essential primary raw material; depleting local aquifers threatens plant shutdowns and sparks severe community and government opposition","D":"Because local communities prefer having dry wells"},"correctOption":"C","correctAnswer":"Because freshwater is their essential primary raw material; depleting local aquifers threatens plant shutdowns and sparks severe community and government opposition","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because protecting shared local water tables safeguards both business continuity and social licence to operate.","distractor_reasons":{"A":"Incorrect because purified water is the main ingredient in beverages.","B":"Incorrect because clean water is vital for product safety.","C":"Correct selection.","D":"Incorrect because water depletion triggers protests and permit revocations."}}},{"id":"P1_U4_MCQ_918","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_918","question":"How does replacing routine international executive flights with 'high-definition video conferencing' support sustainable operations?","options":{"A":"It increases aviation fuel consumption across global airlines","B":"It forces managers to spend three days travelling for a one-hour meeting","C":"It eliminates all communication between international subsidiaries","D":"It eliminates high-altitude aviation carbon emissions while saving thousands of dollars in airfares, hotels, and lost executive working hours"},"correctOption":"D","correctAnswer":"It eliminates high-altitude aviation carbon emissions while saving thousands of dollars in airfares, hotels, and lost executive working hours","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because virtual collaboration cuts Scope 3 business-travel emissions and travel budgets simultaneously.","distractor_reasons":{"A":"Incorrect because fewer flights reduce aviation fuel demand.","B":"Incorrect because video calls take place instantaneously from the office.","C":"Incorrect because digital meetings enable more frequent global check-ins.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_919","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_919","question":"How can genuine 'environmental sustainability' strengthen a business's Human Resource Management (HRM)?","options":{"A":"Purpose-driven employees feel prouder of their employer, making it easier to attract skilled graduates and reducing staff turnover","B":"Sustainable companies never have to pay employee salaries","C":"Environmental sustainability increases workplace toxic chemical exposure","D":"Employees refuse to work for companies that use solar power"},"correctOption":"A","correctAnswer":"Purpose-driven employees feel prouder of their employer, making it easier to attract skilled graduates and reducing staff turnover","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because strong ethical and environmental values enhance employer branding and intrinsic staff motivation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fair wages remain essential.","C":"Incorrect because sustainable operations replace toxic chemicals with safer alternatives.","D":"Incorrect because workers increasingly favour environmentally responsible employers."}}},{"id":"P1_U4_MCQ_920","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_920","question":"How do 'sustainability-linked loans' and 'green bonds' help businesses finance clean technology upgrades?","options":{"A":"Banks charge double interest rates to companies that cut carbon emissions","B":"Lenders offer lower interest rates or dedicated capital pools when the borrower achieves independently verified carbon, water, or waste reduction targets","C":"Green loans never have to be repaid under any circumstances","D":"Green bonds can be used only to build coal-fired power stations"},"correctOption":"B","correctAnswer":"Lenders offer lower interest rates or dedicated capital pools when the borrower achieves independently verified carbon, water, or waste reduction targets","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ethical and institutional investors reward lower long-term environmental risk with cheaper financing.","distractor_reasons":{"A":"Incorrect because hitting sustainability targets lowers rather than raises interest rates.","B":"Correct selection.","C":"Incorrect because loans and bonds still must be repaid with agreed interest.","D":"Incorrect because green finance funds environmental projects and excludes fossil-fuel expansion."}}},{"id":"P1_U4_MCQ_921","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_921","question":"Why do global chocolate, palm-oil, and timber companies use 'satellite monitoring and farm GPS mapping' in their supply chains?","options":{"A":"To locate virgin rainforests to clear illegally","B":"To replace delivery lorries with space rockets","C":"To verify that agricultural suppliers are not clearing protected forests, ensuring compliance with anti-deforestation laws and ethical brand commitments","D":"To eliminate the need to pay farmers for cocoa or timber"},"correctOption":"C","correctAnswer":"To verify that agricultural suppliers are not clearing protected forests, ensuring compliance with anti-deforestation laws and ethical brand commitments","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because satellite traceability proves deforestation-free sourcing to regulators and eco-conscious buyers.","distractor_reasons":{"A":"Incorrect because satellite monitoring prevents rather than encourages illegal clearing.","B":"Incorrect because commodities still travel by ship and lorry.","C":"Correct selection.","D":"Incorrect because ethical sourcing ensures fair payment to compliant farmers."}}},{"id":"P1_U4_MCQ_922","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_922","question":"How does operating an official 'brand trade-in and resale platform' benefit an outdoor clothing manufacturer?","options":{"A":"It encourages customers to burn old jackets after one winter","B":"It increases textile waste sent to municipal incinerators","C":"It eliminates the need to design durable garments","D":"It extends garment lifespans, reduces virgin textile production, attracts budget-conscious eco-shoppers, and captures secondary resale revenue"},"correctOption":"D","correctAnswer":"It extends garment lifespans, reduces virgin textile production, attracts budget-conscious eco-shoppers, and captures secondary resale revenue","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because brand-managed recommerce keeps quality goods in circulation and monetizes durability.","distractor_reasons":{"A":"Incorrect because trade-in schemes recover worn garments for reuse.","B":"Incorrect because resale diverts textiles away from incineration and landfill.","C":"Incorrect because resale requires durable initial construction.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_923","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_923","question":"How can a 24-hour logistics warehouse minimize 'noise and light pollution' affecting nearby residential neighbourhoods and local wildlife?","options":{"A":"Installing acoustic perimeter barriers, switching from noisy diesel forklifts to quiet electric forklifts, and using downward-shielded LED yard lights","B":"Playing loud loudspeaker music throughout the night shift","C":"Pointing bright floodlights directly into neighbours' bedroom windows","D":"Running unmuffled diesel truck engines continuously while parked"},"correctOption":"A","correctAnswer":"Installing acoustic perimeter barriers, switching from noisy diesel forklifts to quiet electric forklifts, and using downward-shielded LED yard lights","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mitigating local noise and light disturbances protects community wellbeing, biodiversity, and operating permits.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because loud noise worsens community disturbance.","C":"Incorrect because upward/outward glare causes light pollution.","D":"Incorrect because idling diesel engines creates noise and exhaust pollution."}}},{"id":"P1_U4_MCQ_924","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_924","question":"How does switching from printed paper bank statements and till receipts to 'digital e-statements and email receipts' improve sustainability?","options":{"A":"It increases deforestation and postal van fuel consumption","B":"It conserves wood pulp and water, eliminates non-recyclable BPA-coated thermal receipt paper, and cuts printing and postage expenses","C":"It forces customers to store boxes of paper in their homes","D":"It eliminates the need for banks to keep financial records"},"correctOption":"B","correctAnswer":"It conserves wood pulp and water, eliminates non-recyclable BPA-coated thermal receipt paper, and cuts printing and postage expenses","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because digital receipts and statements save physical paper, ink, and postal transport while lowering administrative costs.","distractor_reasons":{"A":"Incorrect because paperless billing reduces wood pulp and postal transport.","B":"Correct selection.","C":"Incorrect because digital records are stored electronically.","D":"Incorrect because banks retain secure digital transaction records."}}},{"id":"P1_U4_MCQ_925","section":"4","unit":"Unit 4: Operations management","chapter":"4.3 Sustainable production of goods and services","questionNumber":"P1_U4_MCQ_925","question":"A small artisan coffee roaster is deciding whether to pay $4,000 annually for formal organic and Fairtrade sustainability certification. Which factor is most critical to evaluate?","options":{"A":"Whether the certification logo matches the colour of the delivery van","B":"Whether competitors will voluntarily stop selling coffee","C":"Whether the extra sales revenue and premium price earned from eco-conscious buyers and supermarket buyers will exceed the $4,000 certification fee plus higher bean costs","D":"Whether certification eliminates the need to roast coffee beans"},"correctOption":"C","correctAnswer":"Whether the extra sales revenue and premium price earned from eco-conscious buyers and supermarket buyers will exceed the $4,000 certification fee plus higher bean costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because businesses must weigh the financial costs of certification audits and ethical inputs against expected commercial returns.","distractor_reasons":{"A":"Incorrect because van colours have no financial impact.","B":"Incorrect because competitors remain active in the market.","C":"Correct selection.","D":"Incorrect because core coffee-roasting operations continue."}}},{"id":"P1_U4_MCQ_926","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_926","question":"A manufacturer has monthly fixed costs of $18,000 and a variable cost of $6 per unit. If the factory produces 3,000 units in a month, what is the average total cost per unit?","options":{"A":"$6","B":"$18","C":"$24","D":"$12"},"correctOption":"D","correctAnswer":"$12","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Total Cost = $18,000 + (3,000 × $6) = $18,000 + $18,000 = $36,000, and Average Cost = $36,000 / 3,000 = $12 per unit.","distractor_reasons":{"A":"Incorrect because $6 is only the average variable cost per unit, ignoring fixed costs.","B":"Incorrect because $18 adds $6 to 12 or miscalculates average fixed cost.","C":"Incorrect because $24 adds $18 to $6 without dividing fixed costs by 3,000 units.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_927","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_927","question":"At an output of 2,000 units, a firm's fixed costs are $10,000 and variable cost is $5 per unit. When it expands to 5,000 units, fixed costs rise to $15,000, while bulk discounts cut variable cost to $4 per unit. By how much does average total cost per unit fall?","options":{"A":"$3 per unit (from $10 to $7)","B":"$1 per unit (from $5 to $4)","C":"$5 per unit (from $12 to $7)","D":"$0 per unit (average cost stays unchanged)"},"correctOption":"A","correctAnswer":"$3 per unit (from $10 to $7)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because at 2,000 units AC = ($10,000 + $10,000) / 2,000 = $10; at 5,000 units AC = ($15,000 + $20,000) / 5,000 = $35,000 / 5,000 = $7, a fall of $3 per unit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $1 measures only the drop in variable cost per unit, ignoring average fixed cost.","C":"Incorrect because initial average cost at 2,000 units was $10 rather than $12.","D":"Incorrect because economies of scale lowered average total cost from $10 to $7."}}},{"id":"P1_U4_MCQ_928","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_928","question":"A jacket sells for $25 and has a variable production cost of $11 per jacket. If the company sells 1,500 jackets, what is its total contribution?","options":{"A":"$37,500","B":"$21,000","C":"$16,500","D":"$14,000"},"correctOption":"B","correctAnswer":"$21,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Unit Contribution = $25 - $11 = $14, and Total Contribution = 1,500 × $14 = $21,000.","distractor_reasons":{"A":"Incorrect because $37,500 is total sales revenue (1,500 × $25).","B":"Correct selection.","C":"Incorrect because $16,500 is total variable cost (1,500 × $11).","D":"Incorrect because $14,000 multiplies $14 by 1,000 instead of 1,500."}}},{"id":"P1_U4_MCQ_929","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_929","question":"A business has annual fixed costs of $42,000, sells its product for $30 per unit, and incurs a variable cost of $16 per unit. What is the break-even level of output?","options":{"A":"1,400 units","B":"2,625 units","C":"3,000 units","D":"4,200 units"},"correctOption":"C","correctAnswer":"3,000 units","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Unit Contribution = $30 - $16 = $14, and Break-Even Output = Fixed Costs / Unit Contribution = $42,000 / $14 = 3,000 units.","distractor_reasons":{"A":"Incorrect because 1,400 divides $42,000 by the selling price ($30) without subtracting variable cost.","B":"Incorrect because 2,625 divides $42,000 by the variable cost ($16) instead of contribution.","C":"Correct selection.","D":"Incorrect because 4,200 divides $42,000 by $10."}}},{"id":"P1_U4_MCQ_930","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_930","question":"Using the same figures (fixed costs $42,000, selling price $30, variable cost $16, break-even output 3,000 units), what is the break-even sales revenue?","options":{"A":"$42,000","B":"$48,000","C":"$60,000","D":"$90,000"},"correctOption":"D","correctAnswer":"$90,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Break-Even Revenue = Break-Even Output × Selling Price = 3,000 units × $30 = $90,000.","distractor_reasons":{"A":"Incorrect because $42,000 is total fixed costs.","B":"Incorrect because $48,000 is total variable costs at break-even (3,000 × $16).","C":"Incorrect because $60,000 multiplies 2,000 units by $30.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_931","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_931","question":"If the same business actually sells 4,000 units during the year against its break-even output of 3,000 units, what is its margin of safety?","options":{"A":"1,000 units (25% of actual sales)","B":"7,000 units","C":"3,000 units","D":"-1,000 units"},"correctOption":"A","correctAnswer":"1,000 units (25% of actual sales)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Margin of Safety = Actual Sales - Break-Even Output = 4,000 - 3,000 = 1,000 units (which is 1,000 / 4,000 = 25% of actual sales).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 7,000 adds actual sales and break-even output instead of subtracting.","C":"Incorrect because 3,000 is the break-even output itself.","D":"Incorrect because actual sales exceed break-even output, making the margin positive."}}},{"id":"P1_U4_MCQ_932","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_932","question":"With fixed costs of $42,000 and unit contribution of $14 ($30 price minus $16 variable cost), how much net profit does the business earn if it sells 4,500 units?","options":{"A":"$63,000","B":"$21,000","C":"$14,000","D":"$135,000"},"correctOption":"B","correctAnswer":"$21,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Total Contribution = 4,500 × $14 = $63,000, and Profit = Total Contribution - Fixed Costs = $63,000 - $42,000 = $21,000.","distractor_reasons":{"A":"Incorrect because $63,000 is total contribution before deducting the $42,000 fixed costs.","B":"Correct selection.","C":"Incorrect because $14,000 corresponds to sales of 4,000 units rather than 4,500 units.","D":"Incorrect because $135,000 is total sales revenue (4,500 × $30)."}}},{"id":"P1_U4_MCQ_933","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_933","question":"A company has fixed costs of $30,000, sells its product for $20, and has a variable cost of $11 per unit. How many units must it sell to earn a target profit of $15,000?","options":{"A":"3,333 units","B":"2,250 units","C":"5,000 units","D":"4,091 units"},"correctOption":"C","correctAnswer":"5,000 units","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Target Output = (Fixed Costs + Target Profit) / Unit Contribution = ($30,000 + $15,000) / ($20 - $11) = $45,000 / $9 = 5,000 units.","distractor_reasons":{"A":"Incorrect because 3,333 units covers only fixed costs ($30,000 / $9) with zero profit.","B":"Incorrect because 2,250 divides $45,000 by the selling price ($20) instead of unit contribution ($9).","C":"Correct selection.","D":"Incorrect because 4,091 divides $45,000 by variable cost ($11) instead of unit contribution ($9)."}}},{"id":"P1_U4_MCQ_934","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_934","question":"A firm sells a gadget for $18 with a variable cost of $10 per unit. If annual fixed costs rise from $24,000 to $30,000 due to a rent increase, by how many units does its break-even output increase?","options":{"A":"3,000 units","B":"3,750 units","C":"6,000 units","D":"750 units"},"correctOption":"D","correctAnswer":"750 units","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Unit Contribution = $18 - $10 = $8; initial BEP = $24,000 / $8 = 3,000 units; new BEP = $30,000 / $8 = 3,750 units; increase = 750 units.","distractor_reasons":{"A":"Incorrect because 3,000 is the original break-even output before the rent rise.","B":"Incorrect because 3,750 is the total new break-even output rather than the increase.","C":"Incorrect because $6,000 is the dollar increase in fixed costs rather than units.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_935","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_935","question":"A factory with spare capacity normally sells chairs for $40 (average total cost $32, variable cost $18). An overseas hotel offers a one-off order for 500 chairs at $24 each without affecting regular sales. What is the financial impact of accepting this special order?","options":{"A":"Net profit increases by $3,000","B":"Net profit decreases by $4,000","C":"Net profit decreases by $8,000","D":"Net profit stays unchanged at $0"},"correctOption":"A","correctAnswer":"Net profit increases by $3,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fixed costs are already paid; each special-order chair earns $24 - $18 = $6 contribution, adding 500 × $6 = $3,000 directly to profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because comparing $24 against average total cost ($32) wrongly double-counts fixed overheads that do not rise.","C":"Incorrect because variable cost is $18 rather than $40.","D":"Incorrect because positive contribution ($6/unit) increases net profit."}}},{"id":"P1_U4_MCQ_936","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_936","question":"Why are raw-material suppliers willing to grant 'purchasing economies of scale' (bulk-buying discounts) to large manufacturers?","options":{"A":"Because suppliers lose money intentionally on large orders","B":"Because processing, packaging, invoicing, and transporting one huge order costs the supplier far less per unit than handling thousands of tiny orders","C":"Because governments force suppliers to give 50% discounts to PLCs","D":"Because large orders require zero raw materials to produce"},"correctOption":"B","correctAnswer":"Because processing, packaging, invoicing, and transporting one huge order costs the supplier far less per unit than handling thousands of tiny orders","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because large orders give suppliers their own administrative and logistics savings, which they share through lower unit prices.","distractor_reasons":{"A":"Incorrect because suppliers remain profitable due to lower handling costs per unit.","B":"Correct selection.","C":"Incorrect because bulk discounts are negotiated commercially rather than mandated by law.","D":"Incorrect because large orders still consume raw materials."}}},{"id":"P1_U4_MCQ_937","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_937","question":"Why do commercial banks offer lower loan interest rates to large established corporations than to small start-ups ('financial economies of scale')?","options":{"A":"Because small start-ups never borrow money from banks","B":"Because laws prohibit banks from charging interest to large corporations","C":"Because large firms possess substantial collateral assets, diversified income streams, and lower default risk, while admin costs are spread over bigger loans","D":"Because small start-ups always have higher retained profits than global PLCs"},"correctOption":"C","correctAnswer":"Because large firms possess substantial collateral assets, diversified income streams, and lower default risk, while admin costs are spread over bigger loans","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because lower perceived lending risk and larger loan sizes reduce bank risk premiums and unit administration expenses.","distractor_reasons":{"A":"Incorrect because start-ups frequently seek bank loans.","B":"Incorrect because banks charge interest to all commercial borrowers, just at lower rates for lower-risk firms.","C":"Correct selection.","D":"Incorrect because new start-ups have little or no track record of retained profits."}}},{"id":"P1_U4_MCQ_938","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_938","question":"A national television advertising campaign costs $500,000. How does this demonstrate 'marketing economies of scale' for a giant beverage company selling 2,000,000 cans compared with a small rival selling 100,000 cans?","options":{"A":"The TV station charges the giant company 20 times more for the exact same advert","B":"The small rival reaches 20 times more viewers than the giant company","C":"Advertising costs become a variable cost per can","D":"The fixed $500,000 advert costs the giant company just $0.25 per can sold, compared with $5.00 per can for the small rival"},"correctOption":"D","correctAnswer":"The fixed $500,000 advert costs the giant company just $0.25 per can sold, compared with $5.00 per can for the small rival","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because spreading fixed national marketing budgets across massive sales volumes dramatically lowers marketing cost per unit.","distractor_reasons":{"A":"Incorrect because media airtime rates are independent of the advertiser's unit sales.","B":"Incorrect because both air the same national advert.","C":"Incorrect because TV airtime is a fixed marketing overhead.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_939","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_939","question":"What is meant by 'managerial economies of scale'?","options":{"A":"Large businesses can afford to employ dedicated functional specialists (in logistics, IT, finance, and HR) whose expertise raises efficiency and lowers unit costs across high output","B":"One single owner performs accounting, marketing, cleaning, and production alone","C":"Large businesses eliminate all managers to save salaries","D":"Managers receive lower hourly wages than untrained factory cleaners"},"correctOption":"A","correctAnswer":"Large businesses can afford to employ dedicated functional specialists (in logistics, IT, finance, and HR) whose expertise raises efficiency and lowers unit costs across high output","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because specialization of management functions improves decision quality and operational efficiency at large scale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because one generalist owner characterizes a small sole trader.","C":"Incorrect because large organizations employ specialist departmental managers.","D":"Incorrect because specialist managers earn higher salaries justified by higher total output."}}},{"id":"P1_U4_MCQ_940","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_940","question":"Which example illustrates an 'external economy of scale'?","options":{"A":"A single factory buying larger automated bottling machines","B":"All electronics firms clustering in a technology hub benefit from local universities training specialist engineers and nearby component suppliers setting up locally","C":"A giant corporation suffering communication delays across 15 management layers","D":"A bakery negotiating a bulk discount on its own flour order"},"correctOption":"B","correctAnswer":"All electronics firms clustering in a technology hub benefit from local universities training specialist engineers and nearby component suppliers setting up locally","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because external economies of scale arise from the growth of the whole industry in a region rather than one individual firm's size.","distractor_reasons":{"A":"Incorrect because buying larger machines is an internal technical economy.","B":"Correct selection.","C":"Incorrect because communication delays are an internal diseconomy of scale.","D":"Incorrect because bulk flour discounts are an internal purchasing economy."}}},{"id":"P1_U4_MCQ_941","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_941","question":"Which example illustrates an 'external diseconomy of scale' when too many factories crowd into the same industrial corridor?","options":{"A":"Lower local industrial property rents and empty uncongested motorways","B":"Abundant unemployed engineers willing to work for half the minimum wage","C":"Severe road traffic congestion delaying deliveries and fierce competition among neighbouring firms driving up local wages and industrial rents","D":"Internal disagreements inside one family-owned shop"},"correctOption":"C","correctAnswer":"Severe road traffic congestion delaying deliveries and fierce competition among neighbouring firms driving up local wages and industrial rents","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because overcrowding of an industry in one area creates shared infrastructure bottlenecks and local input price inflation.","distractor_reasons":{"A":"Incorrect because overcrowding raises rents and congestion.","B":"Incorrect because high concentration creates skill shortages that bid wages upward.","C":"Correct selection.","D":"Incorrect because internal family conflict is unrelated to industry-wide scale."}}},{"id":"P1_U4_MCQ_942","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_942","question":"On a break-even chart that displays Total Revenue, Total Cost, and Variable Cost lines, how can you measure 'Total Fixed Costs' at any output level?","options":{"A":"The horizontal distance along the output axis","B":"The vertical gap between Total Revenue and Total Cost","C":"The point where Total Revenue equals zero","D":"The constant vertical distance between the parallel Total Cost line and Variable Cost line"},"correctOption":"D","correctAnswer":"The constant vertical distance between the parallel Total Cost line and Variable Cost line","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Total Cost = Variable Cost + Fixed Cost, so the vertical gap between Total Cost and Variable Cost always equals Fixed Cost.","distractor_reasons":{"A":"Incorrect because the horizontal axis measures output units.","B":"Incorrect because the gap between Total Revenue and Total Cost measures profit or loss.","C":"Incorrect because Total Revenue equals zero at the origin.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_943","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_943","question":"Why does a business with very high fixed costs and low variable costs per unit (such as a software firm or airline) experience large swings in profit when sales volume changes?","options":{"A":"High fixed costs create a high break-even threshold causing steep losses if sales fall short, but high unit contribution generates rapid profit growth once break-even is passed","B":"Because variable costs double every time one ticket or licence is sold","C":"Because high fixed costs guarantee zero losses at every sales level","D":"Because software firms and airlines have zero fixed overheads"},"correctOption":"A","correctAnswer":"High fixed costs create a high break-even threshold causing steep losses if sales fall short, but high unit contribution generates rapid profit growth once break-even is passed","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high operating leverage (high fixed costs, high unit contribution) amplifies both downside losses and upside profits.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because variable cost per unit is very low in airlines and software.","C":"Incorrect because high fixed costs increase risk when demand drops.","D":"Incorrect because aircraft leases and R&D engineers represent high fixed overheads."}}},{"id":"P1_U4_MCQ_944","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_944","question":"Which simplifying assumption about 'inventory' is a well-known limitation of standard break-even charts?","options":{"A":"Break-even charts assume factories never produce any goods","B":"Break-even charts assume all units produced are sold immediately in the same period, ignoring unsold finished-goods inventory","C":"Break-even charts assume selling price equals zero","D":"Break-even charts assume fixed costs are always negative"},"correctOption":"B","correctAnswer":"Break-even charts assume all units produced are sold immediately in the same period, ignoring unsold finished-goods inventory","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because standard break-even models plot output and sales on the same horizontal axis, assuming zero stock accumulation.","distractor_reasons":{"A":"Incorrect because output volume is plotted along the horizontal axis.","B":"Correct selection.","C":"Incorrect because Total Revenue slopes upward based on a positive selling price.","D":"Incorrect because fixed costs are positive."}}},{"id":"P1_U4_MCQ_945","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_945","question":"In a fine-dining restaurant, how are the head chef's fixed annual salary and the cost of fresh salmon fillets classified?","options":{"A":"Both are variable costs","B":"Head chef's salary is a variable cost; fresh salmon is a fixed cost","C":"Head chef's salary is a fixed cost; fresh salmon is a variable cost","D":"Both are zero-cost items"},"correctOption":"C","correctAnswer":"Head chef's salary is a fixed cost; fresh salmon is a variable cost","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the head chef's annual salary is paid regardless of nightly covers, whereas salmon consumption varies directly with meals ordered.","distractor_reasons":{"A":"Incorrect because a fixed annual salary does not vary per meal.","B":"Incorrect because the classifications are reversed.","C":"Correct selection.","D":"Incorrect because both represent real business expenses."}}},{"id":"P1_U4_MCQ_946","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_946","question":"A local bakery's single delivery van can carry up to 500 loaves per day. When daily orders expand to 650 loaves, the bakery must lease a second van and hire a second driver. What type of cost behaviour is this?","options":{"A":"Purely variable cost per loaf","B":"Zero-cost economy of scale","C":"Decreasing average fixed cost","D":"Step-fixed cost, where fixed overheads remain constant within one van's capacity but jump to a higher fixed tier once capacity is exceeded"},"correctOption":"D","correctAnswer":"Step-fixed cost, where fixed overheads remain constant within one van's capacity but jump to a higher fixed tier once capacity is exceeded","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because indivisible capacity additions (like a second van or extra warehouse) cause fixed costs to step upward at capacity thresholds.","distractor_reasons":{"A":"Incorrect because leasing a van is a fixed commitment for 501–1,000 loaves rather than per-loaf.","B":"Incorrect because adding a second van increases total fixed cost.","C":"Incorrect because average fixed cost jumps upward right after the step threshold.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_947","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_947","question":"How does 'slow bureaucratic decision-making' create diseconomies of scale in oversized corporations?","options":{"A":"Proposals must pass through multiple committees and regional headquarters, causing slow reactions to market trends and missed commercial opportunities","B":"Decisions are made instantaneously by one single entrepreneur","C":"Suppliers charge lower prices when committees take six months to approve orders","D":"Customers prefer waiting years for outdated products"},"correctOption":"A","correctAnswer":"Proposals must pass through multiple committees and regional headquarters, causing slow reactions to market trends and missed commercial opportunities","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bureaucratic red tape slows innovation and responsiveness, allowing agile smaller competitors to capture market share.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because instant single-owner decision-making characterizes small businesses.","C":"Incorrect because slow approvals delay orders and raise administrative costs.","D":"Incorrect because customers switch to faster-innovating rivals."}}},{"id":"P1_U4_MCQ_948","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_948","question":"A start-up with $20,000 fixed costs and $5 variable cost compares Pricing Option A ($15 price -> BEP 2,000 units) with Pricing Option B ($25 price -> BEP 1,000 units). Why might managers still choose Option A despite its higher break-even point?","options":{"A":"Because $15 earns higher contribution per unit than $25","B":"If market research shows customers are price-sensitive and 5,000 units can be sold at $15 (earning $30,000 profit) versus only 1,100 units at $25 (earning $2,000 profit)","C":"Because Option A eliminates all fixed costs","D":"Because break-even output is the maximum number of units a firm is allowed to sell"},"correctOption":"B","correctAnswer":"If market research shows customers are price-sensitive and 5,000 units can be sold at $15 (earning $30,000 profit) versus only 1,100 units at $25 (earning $2,000 profit)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because break-even analysis must always be combined with price-elasticity demand forecasts to maximize total profit.","distractor_reasons":{"A":"Incorrect because $15 earns $10 contribution/unit whereas $25 earns $20 contribution/unit.","B":"Correct selection.","C":"Incorrect because fixed costs remain $20,000 under both options.","D":"Incorrect because break-even is the minimum threshold to avoid loss, not a sales cap."}}},{"id":"P1_U4_MCQ_949","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_949","question":"When a manufacturer negotiates cheaper raw material prices per unit while keeping fixed costs and selling price unchanged, how does the break-even chart change?","options":{"A":"The Fixed Cost line shifts downward","B":"The Total Revenue line becomes steeper","C":"The Total Cost line becomes flatter (less steep), moving the break-even intersection to the left at a lower output level","D":"The break-even point moves to the right at a higher output level"},"correctOption":"C","correctAnswer":"The Total Cost line becomes flatter (less steep), moving the break-even intersection to the left at a lower output level","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because lower unit variable cost reduces the slope of Total Cost, widening unit contribution and lowering break-even output.","distractor_reasons":{"A":"Incorrect because raw material prices are variable costs, leaving Fixed Costs unchanged.","B":"Incorrect because selling price is unchanged, leaving Total Revenue unchanged.","C":"Correct selection.","D":"Incorrect because lower variable costs reduce rather than increase break-even output."}}},{"id":"P1_U4_MCQ_950","section":"4","unit":"Unit 4: Operations management","chapter":"4.4 Costs, scale of production and break-even analysis","questionNumber":"P1_U4_MCQ_950","question":"Installing automated machinery increases annual fixed costs from $50,000 to $90,000 but cuts variable cost per unit from $12 to $4 (selling price $20). Under what sales condition is automation financially justified?","options":{"A":"When forecast annual sales are 3,000 units","B":"When forecast annual sales are 4,500 units","C":"When forecast annual sales are exactly 5,000 units","D":"When forecast annual sales exceed 5,000 units (the crossover point where $50,000 + $12Q = $90,000 + $4Q), because above 5,000 units automated total costs are lower"},"correctOption":"D","correctAnswer":"When forecast annual sales exceed 5,000 units (the crossover point where $50,000 + $12Q = $90,000 + $4Q), because above 5,000 units automated total costs are lower","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the $8/unit variable saving ($12 - $4) recovers the $40,000 extra fixed cost ($90,000 - $50,000) at 5,000 units; beyond 5,000 units, automation generates higher profit.","distractor_reasons":{"A":"Incorrect because at 3,000 units manual TC ($86,000) is lower than automated TC ($114,000).","B":"Incorrect because at 4,500 units manual TC ($104,000) is still lower than automated TC ($108,000).","C":"Incorrect because at 5,000 units both options have identical total cost ($110,000) and identical profit (-$10,000).","D":"Correct selection."}}},{"id":"P1_U4_MCQ_951","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_951","question":"How is 'quality' primarily defined and measured in software and mobile-app development?","options":{"A":"Bug-free reliability, fast response speed, intuitive user experience, and strong cybersecurity protection","B":"The physical weight of the cardboard box the app is shipped in","C":"The thickness of steel plating used in the software code","D":"How frequently the app crashes during peak usage"},"correctOption":"A","correctAnswer":"Bug-free reliability, fast response speed, intuitive user experience, and strong cybersecurity protection","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because intangible digital products achieve customer satisfaction through stability, usability, speed, and security.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because apps are distributed digitally without cardboard boxes.","C":"Incorrect because software consists of digital code rather than physical steel.","D":"Incorrect because frequent crashes indicate poor software quality."}}},{"id":"P1_U4_MCQ_952","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_952","question":"Which performance indicators define 'service quality' for an express parcel courier company?","options":{"A":"High percentage of crushed parcels and lost tracking numbers","B":"On-time delivery rate, undamaged parcel arrival, accurate real-time tracking updates, and courteous courier delivery","C":"The colour of the petrol sold at highway service stations","D":"Forcing recipients to wait indoors for seven consecutive days"},"correctOption":"B","correctAnswer":"On-time delivery rate, undamaged parcel arrival, accurate real-time tracking updates, and courteous courier delivery","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because logistics service quality is judged by punctuality, parcel care, communication transparency, and customer interaction.","distractor_reasons":{"A":"Incorrect because damaged and lost parcels represent quality failures.","B":"Correct selection.","C":"Incorrect because fuel colour is irrelevant to customer service quality.","D":"Incorrect because imprecise delivery windows frustrate customers."}}},{"id":"P1_U4_MCQ_953","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_953","question":"When does traditional 'quality control' primarily inspect products?","options":{"A":"Before product designers even sketch the idea","B":"Only after dissatisfied customers return broken goods from shops","C":"At the end of the production line (or at set checkpoints) using dedicated quality inspectors to filter out faulty items before dispatch","D":"Never, because quality control relies solely on customer trust"},"correctOption":"C","correctAnswer":"At the end of the production line (or at set checkpoints) using dedicated quality inspectors to filter out faulty items before dispatch","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because quality control is inspection-based detection aimed at catching defects before goods leave the factory.","distractor_reasons":{"A":"Incorrect because design-stage standards belong to quality assurance.","B":"Incorrect because quality control inspects before dispatch to prevent defective shipments.","C":"Correct selection.","D":"Incorrect because quality control uses formal inspection checkpoints."}}},{"id":"P1_U4_MCQ_954","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_954","question":"Why do car manufacturers and steel-cable producers use 'destructive testing' on small statistical samples?","options":{"A":"Because they want to destroy 100% of their finished inventory","B":"Because customers prefer buying smashed cars","C":"Because non-destructive sensors are illegal","D":"To push sample units to extreme breaking or crash limits so engineers can verify structural safety margins and legal crashworthiness"},"correctOption":"D","correctAnswer":"To push sample units to extreme breaking or crash limits so engineers can verify structural safety margins and legal crashworthiness","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because safety-critical products must be tested to failure on sample units to prove extreme durability.","distractor_reasons":{"A":"Incorrect because destructive testing is applied only to tiny statistical samples.","B":"Incorrect because tested samples are scrapped while unharmed batch units are sold.","C":"Incorrect because both destructive and non-destructive tests are used for different purposes.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_955","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_955","question":"How does 'Statistical Process Control (SPC)' help operators maintain quality assurance during active production?","options":{"A":"Operators plot periodic measurements on control charts to spot gradual machine drift early and recalibrate tools before out-of-tolerance defects occur","B":"Operators wait until 10,000 faulty items pile up before checking machine settings","C":"SPC eliminates the need for measuring tools or tolerances","D":"SPC allows machines to operate without electricity"},"correctOption":"A","correctAnswer":"Operators plot periodic measurements on control charts to spot gradual machine drift early and recalibrate tools before out-of-tolerance defects occur","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because SPC detects subtle process variation trends early, preventing defective batches from ever being made.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because SPC intervenes proactively before defects breach specification limits.","C":"Incorrect because SPC relies on precise measurement data.","D":"Incorrect because machines still require electrical power."}}},{"id":"P1_U4_MCQ_956","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_956","question":"Why is 'incoming raw-material inspection and supplier auditing' a vital first step in quality assurance?","options":{"A":"Because substandard raw materials can easily be turned into luxury goods","B":"Because defective ingredients or off-spec components entering the factory inevitably cause downstream assembly faults ('garbage in, garbage out')","C":"Because suppliers give free refunds even if the buyer never checks deliveries","D":"Because supplier audits eliminate the need for employee training"},"correctOption":"B","correctAnswer":"Because defective ingredients or off-spec components entering the factory inevitably cause downstream assembly faults ('garbage in, garbage out')","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because catching faulty inputs at the loading dock prevents wasting processing time on defective materials.","distractor_reasons":{"A":"Incorrect because poor inputs compromise final product reliability.","B":"Correct selection.","C":"Incorrect because buyers must document incoming non-conformance promptly to claim credit.","D":"Incorrect because internal staff training remains essential."}}},{"id":"P1_U4_MCQ_957","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_957","question":"In a garment factory using quality assurance, sewing machinists inspect fabric panels before stitching and check seams before passing garments to pressing. How does this prevent waste?","options":{"A":"Stitching faults are spotted and corrected immediately at the workstation rather than sewing buttons and labels onto a defective garment","B":"Machinists no longer need to follow size measurements","C":"It increases the number of rejected garments at the end of the day","D":"It eliminates the need to buy thread or sewing needles"},"correctOption":"A","correctAnswer":"Stitching faults are spotted and corrected immediately at the workstation rather than sewing buttons and labels onto a defective garment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because stage-by-stage checks catch faults early before further materials and labour are wasted on defective items.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because agreed size tolerances are checked at every stage.","C":"Incorrect because early correction reduces end-of-line rejections.","D":"Incorrect because sewing consumables are still used in production."}}},{"id":"P1_U4_MCQ_958","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_958","question":"Why is ongoing staff training essential for quality assurance to succeed in a precision electronics factory?","options":{"A":"Because trained staff can ignore product specifications","B":"Because every operator must understand the agreed quality standards and know how to check their own assembly stage accurately","C":"Because training replaces all testing equipment","D":"Because untrained workers produce zero defects automatically"},"correctOption":"B","correctAnswer":"Because every operator must understand the agreed quality standards and know how to check their own assembly stage accurately","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because quality assurance relies on all employees having the skills and knowledge to uphold agreed standards at every stage.","distractor_reasons":{"A":"Incorrect because training reinforces adherence to exact product specifications.","B":"Correct selection.","C":"Incorrect because operators use testing gauges alongside their training.","D":"Incorrect because untrained staff are far more likely to make assembly errors."}}},{"id":"P1_U4_MCQ_959","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_959","question":"How does giving production employees responsibility for checking quality at their own stage under quality assurance benefit a business?","options":{"A":"Workers feel less trusted and make more careless errors","B":"It eliminates the need for clear product specifications","C":"Employees take greater pride and ownership in their work, increasing motivation while catching errors before they multiply","D":"It guarantees zero training costs for new employees"},"correctOption":"C","correctAnswer":"Employees take greater pride and ownership in their work, increasing motivation while catching errors before they multiply","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because trusting trained employees with stage-level quality responsibility boosts job satisfaction and prevents defects early.","distractor_reasons":{"A":"Incorrect because being trusted with quality checks increases rather than reduces trust and care.","B":"Incorrect because clear specifications remain the benchmark for stage checks.","C":"Correct selection.","D":"Incorrect because quality assurance requires upfront staff training."}}},{"id":"P1_U4_MCQ_960","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_960","question":"Why are 'silent dissatisfied customers' (buyers who experience poor quality and simply switch to a rival without complaining) a major hidden cost of poor quality?","options":{"A":"Because they give the business free positive advertising","B":"The business loses their lifetime repeat purchases and suffers negative word-of-mouth without even receiving feedback to fix the underlying defect","C":"Because silent customers increase profit margins","D":"Because complaints departments cost zero money to run"},"correctOption":"B","correctAnswer":"The business loses their lifetime repeat purchases and suffers negative word-of-mouth without even receiving feedback to fix the underlying defect","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because most dissatisfied buyers never lodge formal complaints—they quietly abandon the brand and warn friends.","distractor_reasons":{"A":"Incorrect because dissatisfied buyers spread negative word-of-mouth.","B":"Correct selection.","C":"Incorrect because losing repeat buyers shrinks revenue and profit.","D":"Incorrect because lost lifetime revenue far exceeds complaint-handling costs."}}},{"id":"P1_U4_MCQ_961","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_961","question":"How do 'consumer protection laws' reinforce the importance of quality management for businesses?","options":{"A":"Consumer laws allow businesses to sell dangerous, faulty goods with no refunds","B":"Consumer laws apply only to luxury goods priced above $1,000","C":"Statutory laws require products to be safe, fit for purpose, and as described, entitling buyers to refunds, repairs, or replacements if quality fails","D":"Consumer laws ban quality assurance certifications"},"correctOption":"C","correctAnswer":"Statutory laws require products to be safe, fit for purpose, and as described, entitling buyers to refunds, repairs, or replacements if quality fails","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because legal liability for defective goods imposes direct refund, replacement, and regulatory fine costs on poor-quality producers.","distractor_reasons":{"A":"Incorrect because consumer law prohibits selling unsafe or unfit goods.","B":"Incorrect because consumer rights cover everyday goods at all price points.","C":"Correct selection.","D":"Incorrect because quality standards help firms comply with consumer protection statutes."}}},{"id":"P1_U4_MCQ_962","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_962","question":"Why are 'Good Manufacturing Practice (GMP)' quality assurance protocols strictly enforced in pharmaceutical and food factories?","options":{"A":"To slow down production so medicines become more expensive","B":"To allow untrained visitors to walk freely through sterile mixing rooms","C":"To eliminate the need for expiry dates on medicine labels","D":"To prevent cross-contamination, incorrect dosage formulation, and bacterial growth through strict hygiene, batch logs, and equipment sterilization"},"correctOption":"D","correctAnswer":"To prevent cross-contamination, incorrect dosage formulation, and bacterial growth through strict hygiene, batch logs, and equipment sterilization","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because contaminated food or inaccurately dosed medicine can cause severe illness or death, requiring rigorous preventative QA.","distractor_reasons":{"A":"Incorrect because GMP protects patient and consumer safety rather than inflating prices.","B":"Incorrect because GMP restricts access to sterile zones.","C":"Incorrect because accurate expiry dating and batch tracking are mandatory under GMP.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_963","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_963","question":"How do retail banks and hotel chains use 'mystery shopping' to monitor service quality?","options":{"A":"Trained evaluators pose as ordinary customers to experience queue times, staff friendliness, cleanliness, and product advice firsthand, submitting objective scorecards","B":"Managers spy on employees' private home social-media accounts","C":"Mystery shoppers steal cash from tills to test security guards","D":"It replaces all formal staff induction training"},"correctOption":"A","correctAnswer":"Trained evaluators pose as ordinary customers to experience queue times, staff friendliness, cleanliness, and product advice firsthand, submitting objective scorecards","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mystery shopping measures real front-line customer experience when staff do not know they are being audited.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because mystery shopping evaluates workplace customer service.","C":"Incorrect because mystery shoppers conduct legitimate customer interactions.","D":"Incorrect because mystery shopping identifies coaching needs rather than replacing training."}}},{"id":"P1_U4_MCQ_964","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_964","question":"How does tracking 'Net Promoter Score (NPS)' and post-purchase customer surveys help a service business manage quality?","options":{"A":"It eliminates the need to train front-line staff","B":"It quantifies customer willingness to recommend the brand and highlights specific service touchpoints where quality is slipping","C":"It guarantees that competitors will lose all their customers","D":"It replaces financial accounting balance sheets"},"correctOption":"B","correctAnswer":"It quantifies customer willingness to recommend the brand and highlights specific service touchpoints where quality is slipping","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because continuous customer feedback measures perceived quality and guides targeted service improvements.","distractor_reasons":{"A":"Incorrect because survey feedback often reveals where additional staff training is needed.","B":"Correct selection.","C":"Incorrect because NPS tracks own customer loyalty.","D":"Incorrect because NPS is a customer quality metric rather than a financial statement."}}},{"id":"P1_U4_MCQ_965","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_965","question":"Why is structured 'induction and technical training' essential before allowing new recruits to work independently on a quality-assured line?","options":{"A":"Because new recruits already know every company-specific machine setting instinctively","B":"Because training increases the number of defective parts produced","C":"Because untrained workers misunderstand tolerances and operating procedures, causing high defect rates, equipment damage, and safety accidents","D":"Because laws ban trained employees from operating machinery"},"correctOption":"C","correctAnswer":"Because untrained workers misunderstand tolerances and operating procedures, causing high defect rates, equipment damage, and safety accidents","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because consistent execution of quality standards depends on every operator mastering exact methods before live production.","distractor_reasons":{"A":"Incorrect because every factory has specific equipment and tolerances.","B":"Incorrect because training reduces defects.","C":"Correct selection.","D":"Incorrect because laws require competent trained operators."}}},{"id":"P1_U4_MCQ_966","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_966","question":"How can introducing a well-run quality assurance system reduce a manufacturer's average cost per unit over time?","options":{"A":"Savings from fewer scrapped materials, less reworking of faulty items, and fewer customer returns outweigh the cost of staff training and process checks","B":"Quality assurance allows the firm to buy broken raw materials at half price","C":"Quality assurance eliminates all employee wages","D":"Quality assurance stops all preventative machine maintenance"},"correctOption":"A","correctAnswer":"Savings from fewer scrapped materials, less reworking of faulty items, and fewer customer returns outweigh the cost of staff training and process checks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because preventing defects across all stages reduces expensive scrap, rework, and customer refunds.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality assurance requires high-grade inputs.","C":"Incorrect because skilled employees remain essential.","D":"Incorrect because regular machine maintenance supports consistent quality."}}},{"id":"P1_U4_MCQ_967","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_967","question":"Why do fast-growing businesses frequently suffer a sudden drop in product or service quality during rapid expansion?","options":{"A":"Hiring large numbers of inexperienced staff quickly, rushing overtime shifts, and stretching suppliers beyond capacity overwhelm existing quality assurance systems","B":"Because higher sales volume automatically makes machines break down","C":"Because customers lower their quality expectations when a brand becomes popular","D":"Because growing businesses are exempt from quality standards"},"correctOption":"A","correctAnswer":"Hiring large numbers of inexperienced staff quickly, rushing overtime shifts, and stretching suppliers beyond capacity overwhelm existing quality assurance systems","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid scaling strains training, supervision, and supplier capacity unless QA processes expand ahead of demand.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because volume alone does not cause faults if maintenance and training scale properly.","C":"Incorrect because customers expect consistent quality as brands grow.","D":"Incorrect because quality expectations remain vital at every size."}}},{"id":"P1_U4_MCQ_968","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_968","question":"How do 'visual standard boards' (showing side-by-side photos of acceptable vs unacceptable weld or stitch quality) at workstations support quality assurance?","options":{"A":"They replace all measuring instruments and sensors","B":"They give operators an instant, unmistakable visual reference at the point of work so deviations are spotted immediately without consulting thick manuals","C":"They decorate factory walls for visiting tourists","D":"They eliminate the need for supplier quality checks"},"correctOption":"B","correctAnswer":"They give operators an instant, unmistakable visual reference at the point of work so deviations are spotted immediately without consulting thick manuals","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because clear visual standards make self-inspection fast, objective, and easy for every operator to apply.","distractor_reasons":{"A":"Incorrect because visual boards complement precision gauges.","B":"Correct selection.","C":"Incorrect because visual boards are practical shop-floor job aids.","D":"Incorrect because supplier audits remain necessary."}}},{"id":"P1_U4_MCQ_969","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_969","question":"How does 'quality assurance' work in bespoke job production (such as custom architectural interiors or enterprise software)?","options":{"A":"By producing 10,000 identical copies before showing the client","B":"By refusing to show the client anything until the final invoice is paid","C":"By scheduling formal client design approvals, prototype sign-offs, and milestone inspections throughout the project so specifications match client expectations","D":"By eliminating all written project specifications"},"correctOption":"C","correctAnswer":"By scheduling formal client design approvals, prototype sign-offs, and milestone inspections throughout the project so specifications match client expectations","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because milestone verification prevents costly misunderstandings on unique custom projects.","distractor_reasons":{"A":"Incorrect because job production builds one-off items rather than 10,000 copies.","B":"Incorrect because waiting until completion risks expensive rework if specifications were misunderstood.","C":"Correct selection.","D":"Incorrect because detailed written specifications are essential in bespoke contracts."}}},{"id":"P1_U4_MCQ_970","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_970","question":"Why do global car and smartphone manufacturers audit not just their direct ('Tier 1') suppliers, but also deeper ('Tier 2 and Tier 3') component makers?","options":{"A":"Because Tier 1 suppliers never use parts from smaller sub-suppliers","B":"Because carmakers want to increase defect rates","C":"Because sub-tier suppliers are legally responsible for the car brand's marketing","D":"Because a single faulty battery cell, airbag sensor, or alloy bolt from a sub-tier supplier can trigger a multi-million-dollar product recall and safety crisis"},"correctOption":"D","correctAnswer":"Because a single faulty battery cell, airbag sensor, or alloy bolt from a sub-tier supplier can trigger a multi-million-dollar product recall and safety crisis","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because end-product reliability is only as strong as the weakest component anywhere in the supply chain.","distractor_reasons":{"A":"Incorrect because Tier 1 assemblers rely heavily on sub-tier component suppliers.","B":"Incorrect because deep audits aim to eliminate defects.","C":"Incorrect because the final brand owner bears public reputational and recall responsibility.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_971","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_971","question":"What is meant by 'effective service recovery' when a hotel or airline makes a rare operational mistake (such as a delayed room or lost bag)?","options":{"A":"Apologizing sincerely, empowering front-line staff to resolve the problem immediately, and offering a thoughtful gesture, which often builds stronger loyalty than if no error occurred","B":"Arguing with the customer and blaming computer systems while offering zero help","C":"Ignoring customer complaints until they leave","D":"Eliminating all quality assurance checks because mistakes can be fixed later"},"correctOption":"A","correctAnswer":"Apologizing sincerely, empowering front-line staff to resolve the problem immediately, and offering a thoughtful gesture, which often builds stronger loyalty than if no error occurred","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because swift, empathetic recovery demonstrates genuine care and turns a potential detractor into a loyal advocate.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because defensive excuses escalate customer anger.","C":"Incorrect because ignoring complaints guarantees lost customers.","D":"Incorrect because preventing errors first remains the primary goal."}}},{"id":"P1_U4_MCQ_972","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_972","question":"Why do businesses combine quality assurance with Kaizen (continuous improvement) in competitive markets?","options":{"A":"Because customers lower their quality expectations every year","B":"Because competitor innovations and rising customer expectations mean quality standards must be continuously refined to stay competitive","C":"Because quality assurance certificates expire every 24 hours","D":"Because machines never need servicing or updating"},"correctOption":"B","correctAnswer":"Because competitor innovations and rising customer expectations mean quality standards must be continuously refined to stay competitive","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because continuous small improvements (Kaizen) keep quality standards aligned with evolving customer expectations.","distractor_reasons":{"A":"Incorrect because consumer expectations tend to rise over time.","B":"Correct selection.","C":"Incorrect because quality audits are scheduled periodically rather than daily.","D":"Incorrect because ongoing equipment care and improvement remain necessary."}}},{"id":"P1_U4_MCQ_973","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_973","question":"Why might paying factory workers strictly by piece-rate (paid only per unit completed) conflict with a business's quality assurance goals?","options":{"A":"Piece-rate pay causes workers to work too slowly","B":"Piece-rate pay eliminates all variable labour costs","C":"Rewarding output speed alone can encourage workers to rush tasks and overlook quality checks, increasing defects","D":"Quality assurance bans paying employees any financial rewards"},"correctOption":"C","correctAnswer":"Rewarding output speed alone can encourage workers to rush tasks and overlook quality checks, increasing defects","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because pure piece-rate pay incentivizes speed over accuracy, risking careless assembly mistakes.","distractor_reasons":{"A":"Incorrect because piece-rate pay encourages rushing rather than working slowly.","B":"Incorrect because piece-rate wages vary directly with output volume.","C":"Correct selection.","D":"Incorrect because quality assurance works alongside fair financial and non-financial motivation."}}},{"id":"P1_U4_MCQ_974","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_974","question":"Why do aerospace and medical-device manufacturers regularly calibrate micrometers, pressure gauges, and temperature sensors?","options":{"A":"To make gauges display random numbers","B":"To avoid keeping quality audit logs","C":"Because calibrated tools never require electricity","D":"Because precision instruments drift slightly over time; regular calibration ensures measurements remain accurate to exact engineering tolerances"},"correctOption":"D","correctAnswer":"Because precision instruments drift slightly over time; regular calibration ensures measurements remain accurate to exact engineering tolerances","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because uncalibrated measuring tools can falsely pass defective components or reject good ones.","distractor_reasons":{"A":"Incorrect because calibration aligns instruments to verified reference standards.","B":"Incorrect because calibration certificates are mandatory audit records.","C":"Incorrect because electronic sensors still require power.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_975","section":"4","unit":"Unit 4: Operations management","chapter":"4.5 Quality of goods and services","questionNumber":"P1_U4_MCQ_975","question":"Should a no-frills budget airline install gold-plated seats and serve five-course gourmet meals to improve its 'quality'?","options":{"A":"No—quality means meeting target customer expectations at the promised price; safe, punctual flights and clean cabins with low fares represent high budget-airline quality","B":"Yes, because every business in every market segment must offer luxury features","C":"Yes, because luxury meals reduce aircraft fuel consumption","D":"No, because airlines are exempt from safety and punctuality standards"},"correctOption":"A","correctAnswer":"No—quality means meeting target customer expectations at the promised price; safe, punctual flights and clean cabins with low fares represent high budget-airline quality","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality is defined by fitness for purpose and value for money relative to the target market segment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because adding luxury costs would destroy the low-fare business model.","C":"Incorrect because extra cabin weight increases fuel burn.","D":"Incorrect because safety and punctuality are core quality essentials for all airlines."}}},{"id":"P1_U4_MCQ_976","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_976","question":"Why do soft-drink bottling plants and bulky foam-mattress manufacturers locate close to major urban consumer markets rather than near raw-material sources?","options":{"A":"Because concentrated syrup and compressed foam weigh more than bottled drinks and expanded mattresses","B":"Because they are 'weight-gaining' or 'bulk-gaining' processes that add heavy local water or bulky volume during final assembly, making finished goods costly to transport long distances","C":"Because urban city centres offer free factory land","D":"Because consumers visit bottling factories to buy single cans"},"correctOption":"B","correctAnswer":"Because they are 'weight-gaining' or 'bulk-gaining' processes that add heavy local water or bulky volume during final assembly, making finished goods costly to transport long distances","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because transporting light concentrated syrup or compressed foam long distances and adding water/volume near customers minimizes total freight costs.","distractor_reasons":{"A":"Incorrect because finished bottled water/drinks and expanded mattresses are much heavier/bulkier than raw inputs.","B":"Correct selection.","C":"Incorrect because urban land is expensive, justified by transport savings.","D":"Incorrect because bottling plants distribute to supermarkets and retailers."}}},{"id":"P1_U4_MCQ_977","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_977","question":"Why do oil refineries, grain-flour mills, and export-oriented electronics assemblers often locate directly beside deep-water seaports?","options":{"A":"To attract cruise-ship tourists to buy crude oil","B":"Because seawater is used as fuel in oil refineries","C":"Locating at ports avoids costly inland transshipment and overland haulage when importing bulk raw materials or exporting finished goods by sea","D":"Because inland factories are banned from exporting goods"},"correctOption":"C","correctAnswer":"Locating at ports avoids costly inland transshipment and overland haulage when importing bulk raw materials or exporting finished goods by sea","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because break-of-bulk port locations eliminate double-handling costs between ocean vessels and inland lorries/trains.","distractor_reasons":{"A":"Incorrect because refineries are industrial B2B facilities.","B":"Incorrect because crude oil is refined into fuels, not seawater.","C":"Correct selection.","D":"Incorrect because inland firms export via road/rail links to ports."}}},{"id":"P1_U4_MCQ_978","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_978","question":"Which labour factor is most critical when an aerospace or semiconductor company selects a location for an advanced manufacturing plant?","options":{"A":"Lowest possible unskilled minimum wage with zero local schools","B":"Abundance of seasonal fruit-picking farm workers","C":"Workers who have never used computers or precision instruments","D":"Availability of highly qualified engineers, technicians, and research specialists trained by nearby universities and technical institutes"},"correctOption":"D","correctAnswer":"Availability of highly qualified engineers, technicians, and research specialists trained by nearby universities and technical institutes","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because capital-intensive high-tech manufacturing depends on specialized technical skills rather than cheap unskilled labour.","distractor_reasons":{"A":"Incorrect because unskilled labour cannot operate precision semiconductor or aerospace facilities.","B":"Incorrect because agricultural labour skills do not match high-tech engineering.","C":"Incorrect because digital technical literacy is mandatory.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_979","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_979","question":"Why have many global clothing and footwear brands located stitching and assembly factories in countries such as Bangladesh, Vietnam, or Ethiopia?","options":{"A":"Garment stitching remains relatively labour-intensive, so abundant, lower-cost production labour significantly reduces unit manufacturing costs","B":"Because fabric and shoes cannot be transported by container ship","C":"Because high-wage countries have zero consumers who buy clothing","D":"Because garment factories require giant underground coal mines"},"correctOption":"A","correctAnswer":"Garment stitching remains relatively labour-intensive, so abundant, lower-cost production labour significantly reduces unit manufacturing costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because where direct labour makes up a large share of unit cost, competitive wage rates strongly attract investment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because garments are lightweight and inexpensive to ship globally.","C":"Incorrect because garments are exported back to major consumer markets.","D":"Incorrect because garment stitching uses light sewing equipment."}}},{"id":"P1_U4_MCQ_980","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_980","question":"For which group of businesses are 'climate and physical geography' the primary location determinants?","options":{"A":"Online accounting software startups and telephone call centres","B":"Alpine ski resorts, utility-scale solar farms, vineyards, and hydroelectric power stations","C":"High-street hair salons and urban supermarkets","D":"Commercial banks and corporate law firms"},"correctOption":"B","correctAnswer":"Alpine ski resorts, utility-scale solar farms, vineyards, and hydroelectric power stations","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because snow terrain, high solar irradiance, specific soil/microclimates, and steep river valleys are immovable natural prerequisites.","distractor_reasons":{"A":"Incorrect because digital/service businesses are largely independent of physical terrain.","B":"Correct selection.","C":"Incorrect because retail and personal services follow population density.","D":"Incorrect because financial/legal offices locate in urban commercial districts."}}},{"id":"P1_U4_MCQ_981","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_981","question":"How do local government 'zoning laws and environmental planning regulations' restrict where a chemical plant or noisy metal foundry can locate?","options":{"A":"Zoning laws require chemical plants to be built next to primary schools","B":"Zoning laws apply only to small flower shops","C":"Planning authorities restrict heavy, noisy, or hazardous industries to designated industrial zones separated from residential housing and protected nature reserves","D":"Zoning laws eliminate the need for environmental impact assessments"},"correctOption":"C","correctAnswer":"Planning authorities restrict heavy, noisy, or hazardous industries to designated industrial zones separated from residential housing and protected nature reserves","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because land-use planning protects public health, safety, and residential amenity from industrial hazards.","distractor_reasons":{"A":"Incorrect because hazardous facilities are kept away from schools and homes.","B":"Incorrect because industrial developments face the strictest zoning rules.","C":"Correct selection.","D":"Incorrect because environmental impact assessments are required before permit approval."}}},{"id":"P1_U4_MCQ_982","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_982","question":"What is meant by 'nearshoring' (for example, a US firm moving production from East Asia to Mexico, or a German firm moving to Poland)?","options":{"A":"Moving a factory from a city centre to a village 5 kilometres away","B":"Closing all factories and stopping production completely","C":"Moving production to the most distant continent possible","D":"Relocating operations to a nearby neighbouring country to combine moderate labour costs with shorter freight transit times and compatible time zones"},"correctOption":"D","correctAnswer":"Relocating operations to a nearby neighbouring country to combine moderate labour costs with shorter freight transit times and compatible time zones","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because nearshoring balances cost efficiency with faster, more resilient regional supply chains.","distractor_reasons":{"A":"Incorrect because moving 5 km within the same country is domestic relocation.","B":"Incorrect because nearshoring maintains active cross-border production.","C":"Incorrect because distant relocation is far-shore offshoring.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_983","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_983","question":"Why does a large national e-commerce retailer operate five regional fulfilment warehouses across a large country instead of one single central warehouse?","options":{"A":"Holding popular stock closer to major regional cities enables fast same-day or next-day delivery while cutting long-distance last-mile parcel courier fees","B":"Because one central warehouse is illegal under retail law","C":"Because five warehouses have lower total fixed building rent than one warehouse","D":"To prevent customers in distant regions from ordering online"},"correctOption":"A","correctAnswer":"Holding popular stock closer to major regional cities enables fast same-day or next-day delivery while cutting long-distance last-mile parcel courier fees","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because decentralized regional fulfilment meets modern customer expectations for rapid delivery.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because multi-hub distribution is a competitive logistics strategy rather than a legal requirement.","C":"Incorrect because five warehouses raise fixed property costs, offset by faster delivery and lower last-mile courier fees.","D":"Incorrect because regional hubs expand fast service to distant regions."}}},{"id":"P1_U4_MCQ_984","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_984","question":"How has the expansion of 'high-speed fibre broadband and 5G networks' created new location opportunities for rural entrepreneurs?","options":{"A":"It allows rural farms to teleport heavy tractors to cities","B":"Artisanal producers, rural eco-lodges, and digital software consultants can market and sell globally from low-rent countryside premises","C":"It forces all rural businesses to relocate into crowded city centres","D":"It eliminates the need for rural courier parcel pickups"},"correctOption":"B","correctAnswer":"Artisanal producers, rural eco-lodges, and digital software consultants can market and sell globally from low-rent countryside premises","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because digital connectivity removes geographic isolation for online retail, tourism, and knowledge-based services.","distractor_reasons":{"A":"Incorrect because physical equipment still moves by road.","B":"Correct selection.","C":"Incorrect because broadband enables viable rural operations without paying high urban rents.","D":"Incorrect because physical goods sold online still require courier collection."}}},{"id":"P1_U4_MCQ_985","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_985","question":"Why do multinational banks and airlines consider 'language fluency and cultural familiarity' alongside wage rates when locating overseas customer-service hubs?","options":{"A":"Because customer-service agents never speak or write to customers","B":"Because language misunderstandings increase customer satisfaction","C":"Because clear, empathetic communication reduces call-handling times and prevents frustrated customers from switching to competitors","D":"Because overseas call centres operate without telephones or computers"},"correctOption":"C","correctAnswer":"Because clear, empathetic communication reduces call-handling times and prevents frustrated customers from switching to competitors","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because saving wage costs is counterproductive if communication barriers damage service quality and customer retention.","distractor_reasons":{"A":"Incorrect because live customer interaction is the core function of service hubs.","B":"Incorrect because communication friction frustrates callers.","C":"Correct selection.","D":"Incorrect because global telecom and IT networks connect the hub to callers."}}},{"id":"P1_U4_MCQ_986","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_986","question":"How do 'local-content rules' in international trade agreements influence where global carmakers locate engine and battery plants?","options":{"A":"Local-content rules ban foreign carmakers from building domestic factories","B":"Local-content rules force carmakers to import 100% of parts from overseas","C":"Local-content rules apply only to handmade wooden toys","D":"To qualify for tariff-free trade within a regional bloc (such as USMCA or the EU), a minimum percentage of vehicle value must be manufactured locally, prompting domestic supplier investment"},"correctOption":"D","correctAnswer":"To qualify for tariff-free trade within a regional bloc (such as USMCA or the EU), a minimum percentage of vehicle value must be manufactured locally, prompting domestic supplier investment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because rules of origin incentivize multinationals to localize high-value component production inside the trading bloc.","distractor_reasons":{"A":"Incorrect because local-content rules encourage rather than ban domestic factories.","B":"Incorrect because they require domestic rather than imported sourcing.","C":"Incorrect because automotive and electronics sectors are primary targets of rules of origin.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_987","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_987","question":"Why do luxury fashion houses pay millions in annual rent for flagship stores on prestigious avenues (such as Fifth Avenue, Champs-Élysées, or Ginza) even if store profit alone is modest?","options":{"A":"The iconic address acts as a global brand billboard, elevates perceived exclusivity, attracts wealthy international tourists, and boosts online and wholesale sales worldwide","B":"Because prestigious shopping avenues have the lowest rents in the country","C":"Because luxury brands are legally prohibited from selling online","D":"Because flagship stores manufacture clothing in the basement"},"correctOption":"A","correctAnswer":"The iconic address acts as a global brand billboard, elevates perceived exclusivity, attracts wealthy international tourists, and boosts online and wholesale sales worldwide","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because qualitative brand prestige and halo marketing effects justify high fixed urban rents for luxury brands.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because flagship avenues command the highest retail rents globally.","C":"Incorrect because luxury brands combine flagship boutiques with e-commerce.","D":"Incorrect because flagship stores are retail showrooms rather than factories."}}},{"id":"P1_U4_MCQ_988","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_988","question":"Which infrastructure factor is most decisive for a high-frequency financial trading firm or cloud-gaming provider selecting an office or server site?","options":{"A":"Proximity to deep-sea coal ports and heavy freight railways","B":"Ultra-low-latency fibre-optic internet connections and redundant electrical grid substations","C":"Large outdoor parking lots for heavy 40-tonne articulated lorries","D":"Proximity to fertile wheat farmland"},"correctOption":"B","correctAnswer":"Ultra-low-latency fibre-optic internet connections and redundant electrical grid substations","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because digital latency (milliseconds of data delay) and uninterrupted power directly govern performance and revenue.","distractor_reasons":{"A":"Incorrect because bulk freight infrastructure serves heavy industry.","B":"Correct selection.","C":"Incorrect because digital firms do not handle heavy lorry freight.","D":"Incorrect because agricultural land is unrelated to digital infrastructure."}}},{"id":"P1_U4_MCQ_989","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_989","question":"Why have many global electronics and apparel companies adopted a 'multi-country diversification strategy' (such as 'China Plus One') instead of concentrating 100% of production in a single overseas country?","options":{"A":"Because operating factories in multiple countries eliminates all transport costs","B":"Because single-country production is illegal under international law","C":"To reduce vulnerability to single-country disruptions such as sudden tariffs, geopolitical tensions, regional lockdowns, or natural disasters","D":"To avoid achieving economies of scale"},"correctOption":"C","correctAnswer":"To reduce vulnerability to single-country disruptions such as sudden tariffs, geopolitical tensions, regional lockdowns, or natural disasters","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because geographic diversification builds supply-chain resilience against localized shocks.","distractor_reasons":{"A":"Incorrect because multi-country networks require coordinating multiple freight lanes.","B":"Incorrect because diversification is a risk-management strategy rather than a legal mandate.","C":"Correct selection.","D":"Incorrect because firms balance scale economies against supply-chain disruption risk."}}},{"id":"P1_U4_MCQ_990","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_990","question":"Which 'hidden disruption cost' must managers include when budgeting to relocate an existing factory to another region?","options":{"A":"Zero loss of output during dismantling and moving heavy machinery","B":"Automatic 100% retention of every experienced shop-floor worker","C":"Immediate free construction of the new factory by local builders","D":"Redundancy payouts and recruitment/training costs for experienced staff unwilling to relocate, plus temporary lost sales while machinery is dismantled, moved, and recalibrated"},"correctOption":"D","correctAnswer":"Redundancy payouts and recruitment/training costs for experienced staff unwilling to relocate, plus temporary lost sales while machinery is dismantled, moved, and recalibrated","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because relocation disrupts human capital and live output far beyond simple van-hire expenses.","distractor_reasons":{"A":"Incorrect because moving heavy equipment halts production temporarily.","B":"Incorrect because many employees have family ties and will not move to another region.","C":"Incorrect because building or fitting out new premises requires major capital expenditure.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_991","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_991","question":"Which combination of location factors is most important for a discount supermarket opening a new suburban store?","options":{"A":"Dense residential catchment area, convenient car parking, easy rear-yard delivery lorry access, and moderate suburban land rent","B":"Proximity to deep-sea oil tankers and iron-ore mines","C":"Remote mountain location 80 kilometres from the nearest town","D":"Ultra-expensive luxury jewellery street with zero parking or delivery access"},"correctOption":"A","correctAnswer":"Dense residential catchment area, convenient car parking, easy rear-yard delivery lorry access, and moderate suburban land rent","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because suburban supermarkets need high household footfall, car access for weekly bulk shops, smooth lorry deliveries, and low overheads to keep prices low.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because oil tankers and mines serve heavy industry.","C":"Incorrect because remote sites lack daily grocery shoppers.","D":"Incorrect because high luxury rents and lack of parking clash with discount grocery economics."}}},{"id":"P1_U4_MCQ_992","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_992","question":"Which location factors are most critical for an eco-luxury wellness resort hotel?","options":{"A":"Adjacent to a noisy 24-hour heavy-freight motorway interchange and chemical refinery","B":"Scenic, tranquil natural surroundings (coast, forest, or mountains), reasonable airport/road transfer access for affluent guests, and hospitable local staff","C":"Inside a dense inner-city industrial warehouse zone","D":"Proximity to open-cast coal mining pits"},"correctOption":"B","correctAnswer":"Scenic, tranquil natural surroundings (coast, forest, or mountains), reasonable airport/road transfer access for affluent guests, and hospitable local staff","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because guest relaxation and natural beauty are the core product of a destination wellness resort.","distractor_reasons":{"A":"Incorrect because industrial noise and pollution destroy a wellness resort's appeal.","B":"Correct selection.","C":"Incorrect because industrial zones lack scenic tranquility.","D":"Incorrect because mining landscapes clash with eco-luxury hospitality."}}},{"id":"P1_U4_MCQ_993","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_993","question":"Why do technology start-ups continue to cluster in established tech hubs (such as Silicon Valley, Bangalore, Shenzhen, or London) despite high office rents?","options":{"A":"Because broadband internet does not work anywhere else on Earth","B":"Because office rents in tech hubs are lower than in small rural villages","C":"External economies of scale—concentrated access to venture-capital investors, experienced software engineers, specialist patent lawyers, and rapid knowledge sharing","D":"Because governments ban tech startups from opening in other cities"},"correctOption":"C","correctAnswer":"External economies of scale—concentrated access to venture-capital investors, experienced software engineers, specialist patent lawyers, and rapid knowledge sharing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because ecosystem network effects accelerate fundraising, hiring, and innovation.","distractor_reasons":{"A":"Incorrect because broadband is widely available elsewhere.","B":"Incorrect because tech hubs command premium commercial rents.","C":"Correct selection.","D":"Incorrect because startups cluster voluntarily for ecosystem benefits."}}},{"id":"P1_U4_MCQ_994","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_994","question":"How have municipal 'urban congestion charges and low-emission zones' influenced parcel-delivery logistics locations?","options":{"A":"Courier firms drive huge diesel lorries into city centres at rush hour","B":"Courier firms have stopped delivering parcels to city residents","C":"Congestion charges give free cash bonuses to diesel trucks","D":"Logistics firms establish 'micro-consolidation hubs' on city perimeters where large trucks transfer parcels onto zero-emission electric vans or e-cargo bikes for city-centre delivery"},"correctOption":"D","correctAnswer":"Logistics firms establish 'micro-consolidation hubs' on city perimeters where large trucks transfer parcels onto zero-emission electric vans or e-cargo bikes for city-centre delivery","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because regulatory charges reshape urban last-mile network design toward clean perimeter hubs.","distractor_reasons":{"A":"Incorrect because diesel lorries face heavy daily emission penalties in urban zones.","B":"Incorrect because urban e-commerce demand continues growing.","C":"Incorrect because congestion zones charge fees rather than paying bonuses.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_995","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_995","question":"Why do multinational corporations examine 'profit repatriation rules and double-taxation treaties' before investing in a foreign country?","options":{"A":"To ensure that profits earned by the foreign subsidiary can be legally transferred back to home-country shareholders without being taxed twice or blocked by currency controls","B":"Because multinationals want to pay corporate income tax three times on the same profit","C":"Because foreign subsidiaries never earn any revenue or profit","D":"Because tax treaties determine the physical weight of steel imports"},"correctOption":"A","correctAnswer":"To ensure that profits earned by the foreign subsidiary can be legally transferred back to home-country shareholders without being taxed twice or blocked by currency controls","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trapped cash or punitive withholding taxes severely reduce the true financial return of foreign direct investment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because firms seek double-taxation treaties specifically to avoid paying tax twice.","C":"Incorrect because generating after-tax profit is a primary goal of commercial expansion.","D":"Incorrect because tax treaties govern financial taxation rather than physical weight."}}},{"id":"P1_U4_MCQ_996","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_996","question":"What is meant by 'historical inertia' (industrial inertia) in business location decisions?","options":{"A":"A company moving its headquarters to a new country every single month","B":"A business remaining in its original birthplace long after the initial raw materials or cost advantages vanished, due to skilled local staff, brand heritage, and high relocation costs","C":"Machines refusing to start on Monday mornings","D":"Governments forcing all businesses to move away from their founding cities"},"correctOption":"B","correctAnswer":"A business remaining in its original birthplace long after the initial raw materials or cost advantages vanished, due to skilled local staff, brand heritage, and high relocation costs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sunk infrastructure, local workforce loyalty, and heritage roots often keep established firms in their original location.","distractor_reasons":{"A":"Incorrect because frequent moving is the opposite of inertia.","B":"Correct selection.","C":"Incorrect because industrial inertia is a geographic location phenomenon.","D":"Incorrect because governments rarely force established employers to leave."}}},{"id":"P1_U4_MCQ_997","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_997","question":"How does a 'weighted location factor rating table' help operations managers compare three candidate factory sites objectively?","options":{"A":"It chooses whichever site has the prettiest brochure picture","B":"It ignores all costs and selects a site by flipping a coin","C":"Managers assign percentage importance weights to key factors (such as transport, labour, rent, and grants), score each site, and calculate weighted totals to guide a balanced decision","D":"It eliminates the need to visit or inspect any of the candidate sites"},"correctOption":"C","correctAnswer":"Managers assign percentage importance weights to key factors (such as transport, labour, rent, and grants), score each site, and calculate weighted totals to guide a balanced decision","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because structured weighted scoring prevents managers from over-focusing on a single factor (like cheap land) while neglecting critical operational needs.","distractor_reasons":{"A":"Incorrect because weighted scoring evaluates concrete operational criteria.","B":"Incorrect because it replaces guesswork with systematic comparison.","C":"Correct selection.","D":"Incorrect because physical site due diligence remains essential alongside scoring."}}},{"id":"P1_U4_MCQ_998","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_998","question":"Why is 'public transport connectivity' (bus stops, metro lines, commuter rail) a critical location factor for large retail stores, hospitals, and call centres?","options":{"A":"Because freight trains deliver supermarket milk directly down store aisles","B":"Because retail and hospital employees are legally forbidden from owning cars","C":"Because public transport stations provide free warehouse storage","D":"Many shift workers and shoppers rely on public transit; easy rail/bus access widens the recruitment pool, reduces staff lateness, and increases customer footfall"},"correctOption":"D","correctAnswer":"Many shift workers and shoppers rely on public transit; easy rail/bus access widens the recruitment pool, reduces staff lateness, and increases customer footfall","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because labour-intensive service hubs require convenient daily commuting links for hundreds of employees and visitors.","distractor_reasons":{"A":"Incorrect because passenger transit serves people while lorries deliver store goods.","B":"Incorrect because staff may own cars, though many rely on affordable public transit.","C":"Incorrect because stations serve passenger movement.","D":"Correct selection."}}},{"id":"P1_U4_MCQ_999","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_999","question":"Why do multinational manufacturers conduct 'climate and natural-hazard risk assessments' (checking floodplains, earthquake zones, and coastal storm surges) before building new plants?","options":{"A":"Building on high-risk floodplains or fault lines exposes expensive machinery to catastrophic damage, prolonged supply-chain shutdowns, and prohibitive property insurance premiums","B":"Because factories operate faster when flooded with river water","C":"Because insurance companies charge lower premiums on active earthquake fault lines","D":"Because climate hazards never affect physical factories"},"correctOption":"A","correctAnswer":"Building on high-risk floodplains or fault lines exposes expensive machinery to catastrophic damage, prolonged supply-chain shutdowns, and prohibitive property insurance premiums","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because long-term physical resilience protects capital assets, worker safety, and uninterrupted customer deliveries.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because flooding destroys electrical machinery and inventory.","C":"Incorrect because insurers charge higher premiums or refuse coverage in high-hazard zones.","D":"Incorrect because extreme weather events pose growing physical risks to industrial sites."}}},{"id":"P1_U4_MCQ_1000","section":"4","unit":"Unit 4: Operations management","chapter":"4.6 Location decisions","questionNumber":"P1_U4_MCQ_1000","question":"How do all six areas of Unit 4 Operations Management work together to create sustainable competitive advantage for a business?","options":{"A":"By maximizing raw-material waste, ignoring product defects, and choosing the highest-cost location","B":"Choosing the right production method, appropriate technology, sustainable resource practices, scale economies, quality assurance, and strategic location lowers unit costs while delivering superior customer value","C":"Operations management operates in complete isolation from marketing, finance, and human resources","D":"By producing maximum output without checking whether any customers want to buy the product"},"correctOption":"B","correctAnswer":"Choosing the right production method, appropriate technology, sustainable resource practices, scale economies, quality assurance, and strategic location lowers unit costs while delivering superior customer value","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cohesive operations management transforms inputs efficiently, sustainably, and reliably into high-value outputs that drive long-term profitability.","distractor_reasons":{"A":"Incorrect because waste, defects, and poor location destroy competitiveness.","B":"Correct selection.","C":"Incorrect because operations depends closely on HR skills, finance budgets, and marketing demand forecasts.","D":"Incorrect because producing without market demand creates overproduction waste."}}}];
